(window.GIM_TUR_P=window.GIM_TUR_P||{})["SYD.8"]={"from":345,"s":[["הַמְאַבֵּד עַצְמוֹ לָדַעַת, \u0010y0\u0011 אֵין מִתְעַסְקִים עִמּוֹ לְכָל דָּבָר, וְאֵין מִתְאַבְּלִין עָלָיו, וְאֵין מַסְפִּידִין אוֹתוֹ, \u0010y1\u0011 וְלֹא קוֹרְעִין וְלֹא חוֹלְצִין, אֲבָל עוֹמְדִין עָלָיו בְּשׁוּרָה וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְכָל דָּבָר שֶׁהוּא כָּבוֹד לַחַיִּים.\nאֵיזֶהוּ מְאַבֵּד עַצְמוֹ לָדַעַת, \u0010y2\u0011 כְּגוֹן שֶׁאָמַר: הֲרֵי הוּא עוֹלֶה לְרֹאשׁ הַגַּג, וְרָאוּהוּ שֶׁעָלָה מִיָּד דֶּרֶךְ כַּעַס, אוֹ שֶׁהָיָה מֵצֵר, וְנָפַל וָמֵת, הֲרֵי זֶה בְּחֶזְקַת שֶׁאִבֵּד עַצְמוֹ לָדַעַת. אֲבָל אִם רָאוּהוּ חָנוּק וְתָלוּי בָּאִילָן, \u0010y3\u0011 אוֹ הָרוּג וּמֻשְׁלָךְ עַל גַּבֵּי סֵיפוֹ, הֲרֵי הוּא בְּחֶזְקַת כָּל הַמֵּתִים, וּמִתְעַסְקִים עִמּוֹ וְאֵין מוֹנְעִין מִמֶּנּוּ דָּבָר. \u0005הַגָּה: \u0010y4\u0011 מִי שֶׁגָּנַב וְגָזַל וְעַל יְדֵי זֶה נֶהֱרַג בְּדִין מַלְכוּת, מִתְאַבְּלִים עָלָיו, אִם אֵין בּוֹ סַכָּנָה מִפְּנֵי אֵימַת הַמַּלְכוּת, וְלֹא מִקְרֵי מְאַבֵּד לָדַעַת (מהרי\"ו סִימָן קי\"ד)\u0006.\nקָטָן הַמְאַבֵּד עַצְמוֹ לָדַעַת, חָשׁוּב כְּשֶׁלֹּא לָדַעַת. וְכֵן גָּדוֹל הַמְאַבֵּד עַצְמוֹ לָדַעַת, וְהוּא אָנוּס \u0010y5\u0011 כְּשָׁאוּל הַמֶּלֶךְ, אֵין מוֹנְעִין מִמֶּנּוּ כָּל דָּבָר. \u0010y6\u0011\nמְנֻדֶּה שֶׁמֵּת, דִּינוֹ כִּמְאַבֵּד עַצְמוֹ לָדַעַת; אֵין קוֹרְעִין וְלֹא חוֹלְצִין וְלֹא מַסְפִּידִין עָלָיו, וּמַנִּיחִין אֶבֶן עַל אֲרוֹנוֹ. וְהָנֵי מִלֵּי בְּאַפְקִירוּתָא, כְּשֶׁעוֹבֵר עַל דִּבְרֵי תּוֹרָה; אֲבָל בְּמָמוֹנָא, כֵּיוָן שֶׁמֵּת, פָּטוּר מִגְּזֵרָתָם, וְאֵין מַנִּיחִים אֶבֶן עַל אֲרוֹנוֹ, ומַסְפִּידִין אוֹתוֹ כָּרָאוּי.\nכָּל הַפּוֹרְשִׁים מִדַּרְכֵי צִבּוּר, וְהֵם הָאֲנָשִׁים שֶׁפָּרְקוּ עֹל הַמִּצְוֹת מֵעַל צַוָּארָם, וְאֵין נִּכְלָלִים בִּכְלַל יִשְׂרָאֵל בַּעֲשִׂיָּתָם, וּבִכְבוֹד הַמּוֹעֲדוֹת וִישִׁיבַת בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, אֶלָּא הֲרֵי הֵם כִּבְנֵי חֹרִין לְעַצְמָן כִּשְׁאָר הָאֻמּוֹת, וְכֵן הַמּוּמָרִים וְהַמּוֹסְרִים, כָּל אֵלּוּ אֵין אוֹנְנִים וּמִתְאַבְּלִים עֲלֵיהֶם, אֶלָּא אֲחֵיהֶם וּשְׁאָר קְרוֹבֵיהֶם \u0010y7\u0011 לוֹבְשִׁים לְבָנִים וּמִתְעַטְּפִים לְבָנִים וְאוֹכְלִים וְשׁוֹתִים \u0010y8\u0011 וּשְׂמֵחִים. \u0005הַגָּה: הַפּוֹרֵשׁ מִן הַצִּבּוּר וְלֹא רָצָה לָשֵׂאת עִמָּהֶם בְּמִסִּים וְאַרְנוֹנִיּוֹת, מִתְאַבְּלִים עָלָיו (תשו' רַשְׁבָּ\"א סי' תשס\"ג)\u0006 אֲבָל אֵין שְׁאָר בְּנֵי הָעִיר צְרִיכִים לְבַטֵּל מִמְּלָאכְתָן בִּשְׁבִילוֹ לַעֲסֹק עִמּוֹ \u0005(כֵּן מַשְׁמָע בנ\"י סוֹף מ\"ק)\u0006.\nקָטָן בֶּן שָׁנָה אוֹ שְׁנָתַיִם שֶׁהֵמִיר \u0010y9\u0011 עִם אִמּוֹ, וָמֵת, אֵין מִתְאַבְּלִין עָלָיו \u0005וְעַיֵּן לְעֵיל סִימָן ש\"מ (סָעִיף ה')\u0006.\nמִי שֶׁנָּפַל בַּיָּם, אוֹ טָבַע בַּנָּהָר, אוֹ אֲכָלַתּוּ חַיָּה, אֵין מוֹנְעִין מִמֶּנּוּ דָּבָר.\nאָרוֹן הָעוֹבֵר מִמָּקוֹם לְמָקוֹם, אִם שִׁלְדּוֹ \u0005(פֵּרוּשׁ הַשִּׁדְרָה וְצַלְעוֹתֶיהָ)\u0006 קַיֶּמֶת, עוֹמְדִין עָלָיו בְּשׁוּרָה וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים, אִם יֵשׁ אֲבֵלִים שֶׁמִּתְאַבְּלִין עָלָיו; וְאִם אֵין שִׁלְדּוֹ קַיֶּמֶת, אֵין עוֹמְדִין עָלָיו בְּשׁוּרָה וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְלֹא תַּנְחוּמֵי אֲבֵלִים.",["\u0003אין מתעסקין כו'. \u0004דכתיב ואת דמכם לנפשותיכם אדרוש וגו' דעון גדול הוא המאבד עצמו לדעת וכתב בתשו' הרשב\"א סי' תשס\"ג דאף שאמרו בכל מקום אין מתעסקין עמהם לכל דבר לא לענין קבורה ותכריכים אמרו אלא שאין קורעין ולא חולצין כו' ומביאו ד\"מ:","\u0003ולא קורעין כו'. \u0004משמע שאין קורעין עליו כלל אפי' האבלים אבל דעת הרמב\"ן והטור שהאבלי' קורעין עליו והאי אין קורעין פי' לרחוקים:","\u0003כגון שאמר הרי הוא עולה כו'. \u0004וכ' הרמב\"ן אע\"פ שלא ראוהו מפיל עצמו כיון שאמר הריני עולה לראש הגג ואפיל עצמי ואמות חזקה לדעת עשה וכ' הב\"ח בשם מהרש\"ל דאפי' אמר ראו שאני עולה כו' ולא ראוהו עולה אדבוריה לחוד לא סמכינן ואינו בחזקת מאבד עצמו לדעת וכתב שדבריו נכונים:","\u0003או הרוג כו'. \u0004ע\"ל סי' שס\"ד סעיף ד' דין הרוגים:","\u0003מי שגנב כו'. \u0004משמע דר\"ל דל\"ת דכיון שגנב וגזל והתיר עצמו למיתה בדיניהם לא יתאבל עליו דה\"ל מאבד עצמו לדעת קמ\"ל דלא לפי שהיה סבור שיוכל לברוח אבל משום עבירה דגנב וגזל מתאבלי' עליו דלא חשוב כפורש מדרכי הציבור דלקמן סעיף ה' כך משמע מדברי הרב וכן כתב הרשב\"א בתשובה ס\"ס תשס\"ג דאחד מבעלי עבירה כגזלנים וכה\"ג אינן בכלל הפורשים מדרכי הצבור ולפ\"ז בגנב וגזלן שמתו על מטתן מתאבלין עליהן וכתב הב\"ח שכן נוהגין ואע\"פ שבתשו' מהרי\"ו סי' קי\"ד כתב אמעשה דגנב שנהרג בדיניהם וז\"ל ומ\"ש בספרים שקבל הגונב כו' לא ידענא פירושו ובודאי שיש לו כפרה וחלק לעוה\"ב דאפי' הרוגי ב\"ד יש להם חלק לעוה\"ב אפילו עובדי כוכבים כדאיתא בפרק נגמר הדין אומרי' לו התודה שכל המתודה יש לו חל\"ה וה\"נ מסתמא התודה כמ\"ש כו' אין ר\"ל דדוקא מיתתו שנהרג הוי כפרה וכמו שהבין הב\"ח מדבריו אלא ה\"ה מת על מטתו הוי כפרה כשמתודה אלא דעובדא דהתם הוי בנהרג מיהו לעיל סי' ש\"מ סעיף ה' כתב הרב דברגיל לעשות עבירה אין מתאבלין עליו ונראה דהיינו כשלא התודה קודם מיתתו:","\u0003כשאול המלך. \u0004שהרג את עצמו לפי שראה שהפלשתים יעשו בו כרצונם ויהרגוהו:","\u0003מנודה כו'. \u0004כפול לעיל סי' של\"ד ס\"ג:","\u0003לובשים לבנים כו'. \u0004וכתב הטור בשם הרי\"ץ גיאות מכאן שהאבלים וקרובי המת לובשים שחורים וכל מקום ומקום יש לעשות כפי מנהגו:","\u0003ושמחים. \u0004על שאבדו שונאיו של מקום דכתיב באבוד רשעי' רנה:","\u0003עם אמו. \u0004או עם אביו כדלעיל סי' ש\"מ ס\"ה בהג\"ה:"],[],"\u0010g0\u0011 \u0010r0\u0011 הַמְאַבֵּד עַצְמוֹ לָדַעַת, \u0010y0\u0011 אֵין מִתְעַסְקִים עִמּוֹ לְכָל דָּבָר, וְאֵין מִתְאַבְּלִין עָלָיו, וְאֵין מַסְפִּידִין אוֹתוֹ, \u0010y1\u0011 \u0010g1\u0011 וְלֹא \u0010t0\u0011 קוֹרְעִין וְלֹא חוֹלְצִין, אֲבָל עוֹמְדִין עָלָיו בְּשׁוּרָה וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְכָל דָּבָר שֶׁהוּא כָּבוֹד לַחַיִּים. \u0010g2\u0011\nאֵיזֶהוּ מְאַבֵּד עַצְמוֹ לָדַעַת, \u0010y2\u0011 כְּגוֹן \u0010t1\u0011 שֶׁאָמַר: הֲרֵי הוּא עוֹלֶה לְרֹאשׁ הַגַּג, וְרָאוּהוּ שֶׁעָלָה מִיָּד דֶּרֶךְ כַּעַס, אוֹ שֶׁהָיָה מֵצֵר, וְנָפַל וָמֵת, הֲרֵי זֶה בְּחֶזְקַת שֶׁאִבֵּד עַצְמוֹ לָדַעַת. אֲבָל אִם רָאוּהוּ חָנוּק וְתָלוּי בָּאִילָן, \u0010y3\u0011 אוֹ הָרוּג וּמֻשְׁלָךְ עַל גַּבֵּי סֵיפוֹ, הֲרֵי הוּא בְּחֶזְקַת כָּל הַמֵּתִים, וּמִתְעַסְקִים עִמּוֹ וְאֵין מוֹנְעִין מִמֶּנּוּ דָּבָר. \u0005הַגָּה: \u0010y4\u0011 \u0010r1\u0011 מִי \u0010t2\u0011 שֶׁגָּנַב וְגָזַל וְעַל יְדֵי זֶה נֶהֱרַג בְּדִין מַלְכוּת, מִתְאַבְּלִים עָלָיו, \u0010r2\u0011 אִם אֵין בּוֹ סַכָּנָה מִפְּנֵי אֵימַת הַמַּלְכוּת, וְלֹא מִקְרֵי מְאַבֵּד לָדַעַת (מהרי\"ו סִימָן קי\"ד)\u0006. \u0010g3\u0011 \u0010r3\u0011\nקָטָן הַמְאַבֵּד עַצְמוֹ לָדַעַת, חָשׁוּב כְּשֶׁלֹּא לָדַעַת. \u0010r4\u0011 וְכֵן גָּדוֹל הַמְאַבֵּד עַצְמוֹ לָדַעַת, \u0010g4\u0011 וְהוּא אָנוּס \u0010y5\u0011 \u0010t3\u0011 כְּשָׁאוּל הַמֶּלֶךְ, אֵין מוֹנְעִין מִמֶּנּוּ כָּל דָּבָר. \u0010y6\u0011 \u0010g5\u0011 \u0010r5\u0011\nמְנֻדֶּה שֶׁמֵּת, דִּינוֹ כִּמְאַבֵּד עַצְמוֹ לָדַעַת; אֵין קוֹרְעִין וְלֹא חוֹלְצִין וְלֹא מַסְפִּידִין עָלָיו, \u0010g6\u0011 וּמַנִּיחִין אֶבֶן עַל אֲרוֹנוֹ. וְהָנֵי מִלֵּי בְּאַפְקִירוּתָא, כְּשֶׁעוֹבֵר עַל דִּבְרֵי תּוֹרָה; אֲבָל בְּמָמוֹנָא, כֵּיוָן שֶׁמֵּת, פָּטוּר מִגְּזֵרָתָם, וְאֵין מַנִּיחִים אֶבֶן עַל אֲרוֹנוֹ, ומַסְפִּידִין אוֹתוֹ כָּרָאוּי. \u0010g7\u0011\nכָּל הַפּוֹרְשִׁים מִדַּרְכֵי צִבּוּר, וְהֵם הָאֲנָשִׁים שֶׁפָּרְקוּ עֹל הַמִּצְוֹת מֵעַל צַוָּארָם, וְאֵין נִּכְלָלִים בִּכְלַל יִשְׂרָאֵל בַּעֲשִׂיָּתָם, וּבִכְבוֹד הַמּוֹעֲדוֹת וִישִׁיבַת בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, אֶלָּא הֲרֵי הֵם כִּבְנֵי חֹרִין לְעַצְמָן כִּשְׁאָר הָאֻמּוֹת, וְכֵן הַמּוּמָרִים וְהַמּוֹסְרִים, כָּל אֵלּוּ אֵין אוֹנְנִים וּמִתְאַבְּלִים עֲלֵיהֶם, אֶלָּא אֲחֵיהֶם וּשְׁאָר קְרוֹבֵיהֶם \u0010y7\u0011 לוֹבְשִׁים לְבָנִים וּמִתְעַטְּפִים לְבָנִים וְאוֹכְלִים וְשׁוֹתִים \u0010y8\u0011 \u0010t4\u0011 וּשְׂמֵחִים. \u0005הַגָּה: \u0010r6\u0011 הַפּוֹרֵשׁ מִן הַצִּבּוּר וְלֹא רָצָה לָשֵׂאת עִמָּהֶם בְּמִסִּים וְאַרְנוֹנִיּוֹת, מִתְאַבְּלִים עָלָיו (תשו' רַשְׁבָּ\"א סי' תשס\"ג)\u0006 \u0010r7\u0011 אֲבָל אֵין שְׁאָר בְּנֵי הָעִיר צְרִיכִים לְבַטֵּל מִמְּלָאכְתָן בִּשְׁבִילוֹ לַעֲסֹק עִמּוֹ \u0005(כֵּן מַשְׁמָע בנ\"י סוֹף מ\"ק)\u0006. \u0010g8\u0011 \u0010r8\u0011\nקָטָן בֶּן שָׁנָה אוֹ שְׁנָתַיִם שֶׁהֵמִיר \u0010y9\u0011 עִם \u0010t5\u0011 אִמּוֹ, וָמֵת, אֵין מִתְאַבְּלִין עָלָיו \u0005וְעַיֵּן לְעֵיל סִימָן ש\"מ (סָעִיף ה')\u0006. \u0010g9\u0011\nמִי שֶׁנָּפַל בַּיָּם, אוֹ טָבַע בַּנָּהָר, אוֹ אֲכָלַתּוּ חַיָּה, אֵין מוֹנְעִין מִמֶּנּוּ דָּבָר. \u0010g10\u0011\nאָרוֹן הָעוֹבֵר מִמָּקוֹם לְמָקוֹם, אִם שִׁלְדּוֹ \u0005(פֵּרוּשׁ הַשִּׁדְרָה וְצַלְעוֹתֶיהָ)\u0006 קַיֶּמֶת, עוֹמְדִין עָלָיו בְּשׁוּרָה וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים, אִם יֵשׁ אֲבֵלִים שֶׁמִּתְאַבְּלִין עָלָיו; וְאִם אֵין שִׁלְדּוֹ קַיֶּמֶת, אֵין עוֹמְדִין עָלָיו בְּשׁוּרָה וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְלֹא תַּנְחוּמֵי אֲבֵלִים.",{"g":["\u0003ברייתא באבל רבתי פ\"ב:\u0004 ","\u0003כדעת הרמב\"ם בפ\"א מהלכות אבל שאין קורעין עליו כלל:\u0004 ","לשון הרמב\"ם שם מברייתא דלעיל:\n(°) וסיים שם משום דהוה ליה כפרה בהריגתו כאוקימתא דרבא בסנהדין דף מ\"ז ע\"א דשאני הרוגי מלכות וכן כ' הרמב\"ם בפ\"א מהלכות אבל ועיין במ\"ש בסי' שע\"ה סעיף ה':","\u0003שם בברייתא דאבל רבתי:\u0004 ","\u0003הרמב\"ן בסת\"ה ונתן טעם לפי שאיבוד היה מותר לו כדאי' בב\"ר וכ\"כ הרא\"ש בסוף מ\"ק:\u0004 ","\u0003רמב\"ן בסת\"ה:\u0004 ","\u0003מ\"ק דף ט\"ו ע\"א:\u0004 ","\u0003לשון הרמב\"ם שם פ' א' מברייתא דאבל רבתי פרק ב' ובמקום המומרים כת' שם האפיקורסים:\u0004 ","מרדכי ור\"ת והביא ראיה מהתוספתא דסנהדרין וכתבו הגה' אשיר\"י שר\"ג נתאבל על בנו שהמיר דתו י\"ד יום ק\"ו לשכינה י\"ד יום וכתבו הגהות מיימוני בפרק א' אמנם אין ללמוד מזה דלאפושי צערא הוא דעבד שלא זכה לתשובה:","\u0003ברייתא באבל רבתי:\u0004 ","\u0003ברייתות מ\"ק דף כ\"ה ע\"א וכדמוקי להו שם בגמרא:\u0004 "],"t":["\u0003קורעין. \u0004 משמע שאין קורעין עליו כלל אפי' האבלים אבל דעת הרמב\"ן והטור שהאבלים קורעין עליו והאי אין קורעין פי' לרחוקים עכ\"ל הש\"ך. וכ' בתשובת הרשב\"א דבכל מקום שאמרו אין מתעסקין עמו לכל דבר מ\"מ לא לענין קבורה ותכריכים אמרו וכו':","\u0003שאמר. \u0004 וכ' מהרש\"ל דאם לא ראוהו עולה אדיבוריה לא סמכינן ואינו בחזקת מאבד עצמו לדעת וכ' הב\"ח שדבריו נכונים:","\u0003שגנב. \u0004 כ' הש\"ך משמע דמשום עבירה דגנבה וגזלה לא חשיב כפורש מדרכי הצבור ומתאבלים עליו ולפ\"ז בגנב וגזלן שמתו על מטתן יש להתאבל עליהן וכתב הב\"ח שכן נוהגין והיינו כשהתודה קודם מיתתו ומ\"ש הרב בסימן ש\"מ ס\"ה דברגיל לעשות עבירה אין מתאבלין עליו נראה דהיינו כשלא התודה קודם מיתתו. עכ\"ל:","\u0003כשאול. \u0004 שהרג את עצמו לפי שראה שהפלשתים יעשו בו כרצונם ויהרגוהו:","\u0003ושמחים. \u0004 על שאבדו שונאיו של מקום דכתיב באבוד רשעים רנה:","\u0003אמו. \u0004 או אם אביו כדלעיל סימן ש\"מ ס\"ה בהג\"ה:"],"r":["שמ\"ה ערא\"ש פ\"ג דמ\"ק סי' קמ\"א (ע\"כ):\n\u0003(ליקוט) המאבד כו' איזהו כו'. \u0004א\"ר פ\"ב (ע\"כ):","\u0003מי שגנב כו'. \u0004כמ\"ש בפ\"ו דסנהדרין \u0005(מ\"ז) \u0006בהרוגי מלכות דדוקא בהרוגי ב\"ד שהתיר עצמו למיתה כו' דלא כמרדכי שהביא ראיה ממ\"ש שאין מתאבלין עליו ועב\"י ומהרי\"ו כ' שט\"ס במ\"ש ועד\"מ \u0005(וע\"ל סי' שע\"ה ס\"ק יו\"ד):\u0006","\u0003אם אין בו סכנה. \u0004כמ\"ש בפ\"ק דסנהדרין \u0005(י\"א א') \u0006בר\"י בן בבא ופ' בתרא דסוטה:","\u0003(ליקוט) קטן כו'. \u0004שם מעשה בבנו כו' מעשה בתינוק כו': ס\"ה וס\"ז כל הפורשים כו' מי שנפל כו'. שם (ע\"כ):","\u0003וכן גדול כו'. \u0004ממ\"ש בפ' הערל \u0005(ע\"ח ב') \u0006שנענשו על שלא הספידו על שאול כמ\"ש בב\"ר פ' נח יכול אפילו נרדף כשאול ת\"ל אך:","\u0003(ליקוט) מנודה שמת כו'. \u0004דהא סוקלין אותו משום בזיון כ\"ש שאין מתעסקים בכבודו. תה\"א (ע\"כ):","\u0003הפורש מן כו'. \u0004ע\"ל סי' של\"ד ס\"ג אבל לממונא כו':","\u0003אבל אין כו'. \u0004לגדר בעלמא ועד\"מ:","\u0003קטן כו'. \u0004ממ\"ש בתוספתא פרק בתרא דסנהדרין קטני בני עיר הנדחת רא\"א נהרגין וחכ\"א אין נהרגין משמע אבל באבלות דכ\"ע מודי וע\"ל סי' ש\"מ שי\"ח עליו וכ\"כ במרדכי שם בשם ר\"י וע\"ש סי' אלף תקל\"ח:"]}],["מִי שֶׁהָיָה בַּעֲלָהּ עִמָּהּ צָלוּב בָּעִיר, אוֹ שֶׁאִשְׁתּוֹ עִמּוֹ צְלוּבָה בָּעִיר, אוֹ אָבִיו וְאִמּוֹ, וַעֲדַיִן לֹא כָּלָה הַבָּשָׂר \u0010y0\u0011 כֻּלּוֹ, לֹא יִשְׁהֶה בְּתוֹכָהּ אֶלָּא אִם כֵּן הָיְתָה גְּדוֹלָה כְּאַנְטוֹכְיָא, שֶׁאֵין אֵלּוּ מַכִּירִין אֶת אֵלּוּ, וְלֹא יִשְׁהֶה בְּצַד זֶה אֶלָּא בְּצַד זֶה.",["\u0003לא ישהה בתוכה. \u0004שהוא גורם לבזות המת שאומרים אותו פלוני הצלוב הוא אחיו של פלוני זה וכתב הפרישה דאם נקבר מותר וכתב הב\"ח דדוקא צלוב בעיר אבל במלכותינו שצולבין חוץ לעיר על פני השדה מותר לשהות בכל העיירות וע\"כ אין דין זה נוהג כלל עכשיו:"],[],"\u0010g0\u0011 מִי שֶׁהָיָה בַּעֲלָהּ עִמָּהּ צָלוּב \u0010t0\u0011 בָּעִיר, אוֹ שֶׁאִשְׁתּוֹ עִמּוֹ צְלוּבָה בָּעִיר, אוֹ אָבִיו וְאִמּוֹ, וַעֲדַיִן לֹא כָּלָה הַבָּשָׂר \u0010y0\u0011 כֻּלּוֹ, לֹא יִשְׁהֶה בְּתוֹכָהּ אֶלָּא אִם כֵּן הָיְתָה גְּדוֹלָה כְּאַנְטוֹכְיָא, \u0010g1\u0011 שֶׁאֵין אֵלּוּ מַכִּירִין אֶת אֵלּוּ, \u0010r0\u0011 וְלֹא יִשְׁהֶה בְּצַד זֶה אֶלָּא בְּצַד זֶה.",{"g":["ברייתא באבל רבתי פ\"ב ופי' הר\"ן בסוף מ\"ק לפי שהוא גורם לבזות את המת שאומרי' אותו האיש הצלוב הוא אחיו של פלוני וכשכלה הבשר ואין הצורה קיימת לא יזכרוהו לרעה עוד:","הר\"ן:"],"t":["\u0003בעיר. \u0004 כ' הב\"ח דוקא צלוב בעיר אבל במלכותינו שצולבין חוץ לעיר על פני השדה מותר להשהות בכל העיירות וע\"כ אין דין זה נוהג עכשיו כלל. ש\"ך:"],"r":["\u0003ולא ישהא כו'. \u0004שם במ\"ש:\n(ליקוט) שמ\"ו ערא\"ש פ\"ג דמ\"ק סימן קמ\"ב (ע\"כ):"]}],["\u0010y0\u0011 מִי שֶׁמֵּת לוֹ מֵת לִפִנֵי שְׁלֹשִׁים יוֹם הַסְמוּכִים לָרֶגֶל, לֹא יִסְפְּדֶנּוּ מִשֶּׁיִּכָּנְסוּ שְׁלֹשִׁים יוֹם הַסְמוּכִים לָרֶגֶל, וַאֲפִלּוּ יֵשׁ לוֹ הֶסְפֵּד בְּלֹא זֶה, כְּגוֹן שֶׁמֵּת לוֹ מֵת בְּתוֹךְ שְׁלֹשִׁים שֶׁמֻּתָּר לְסָפְדוֹ, וַאֲפִלּוּ מֵת עֶרֶב הָרֶגֶל, אָסוּר לְהַסְפִּיד עִמּוֹ עַל הַמֵּת שֶׁמֵּת לוֹ לִפְנֵי שְׁלֹשִׁים יוֹם קֹדֶם הַמּוֹעֵד.\nמִי שֶׁבָּאָה לוֹ שְׁמוּעָה בְּתוֹךְ שְׁלֹשִׁים יוֹם קֹדֶם הָרֶגֶל, \u0010y1\u0011 נִרְאֶה לִי שֶׁמֻּתָּר לְסָפְדוֹ, אַף עַל פִּי שֶׁהִיא רְחוֹקָה.\nמַה שֶּׁאָנוּ נוֹהֲגִין בְּתַשְׁלוּם הַשָּׁנָה לְקוֹנֵן וּלְהַזְכִּיר נְשָׁמוֹת, נִרְאֶה לִי אֵינוֹ בִּכְלַל זֶה וּמֻתָּר לַעֲשׂוֹתוֹ סָמוּךְ לָרֶגֶל.",["\u0003מי שמת כו'. \u0004עיין מזה בא\"ח סי' תקמ\"ז סעיף ג' ודין מחשיכין על התחום בשבת להביא צרכי המת כתוב בא\"ח סי' ש\"ו ס\"ג ודין עובד כוכבים שעשה קבר והביא חלילין בשבת נתבאר שס סי' שכ\"ה סעיף י\"ד ט\"ו ע\"ש:","\u0003נ\"ל כו'. \u0004וכ' העט\"ז ואנו נוהגין להזכיר אפילו פעם הראשון אפילו בתוך הרגל:"],[],"\u0010y0\u0011 \u0010g0\u0011 \u0010r0\u0011 מִי שֶׁמֵּת לוֹ מֵת לִפִנֵי שְׁלֹשִׁים יוֹם הַסְמוּכִים לָרֶגֶל, לֹא יִסְפְּדֶנּוּ מִשֶּׁיִּכָּנְסוּ שְׁלֹשִׁים יוֹם הַסְמוּכִים לָרֶגֶל, וַאֲפִלּוּ יֵשׁ לוֹ הֶסְפֵּד בְּלֹא זֶה, כְּגוֹן שֶׁמֵּת לוֹ מֵת בְּתוֹךְ שְׁלֹשִׁים שֶׁמֻּתָּר לְסָפְדוֹ, וַאֲפִלּוּ מֵת עֶרֶב הָרֶגֶל, אָסוּר לְהַסְפִּיד עִמּוֹ עַל הַמֵּת שֶׁמֵּת לוֹ לִפְנֵי שְׁלֹשִׁים יוֹם קֹדֶם הַמּוֹעֵד. \u0010g1\u0011\nמִי שֶׁבָּאָה לוֹ שְׁמוּעָה בְּתוֹךְ שְׁלֹשִׁים יוֹם קֹדֶם הָרֶגֶל, \u0010y1\u0011 נִרְאֶה לִי שֶׁמֻּתָּר לְסָפְדוֹ, אַף עַל פִּי שֶׁהִיא רְחוֹקָה.\nמַה שֶּׁאָנוּ נוֹהֲגִין \u0010t0\u0011 בְּתַשְׁלוּם הַשָּׁנָה לְקוֹנֵן וּלְהַזְכִּיר נְשָׁמוֹת, נִרְאֶה לִי אֵינוֹ בִּכְלַל זֶה וּמֻתָּר לַעֲשׂוֹתוֹ סָמוּךְ לָרֶגֶל.",{"g":["צינתיו בא\"ח סי' תקמ\"ז:\n(°) כאשר הגהתי כן הוא בטור וברא\"ש וש\"פ:","ג\"ז שם:\nדין להספיד בחלילין שהביא העובד כוכבים בשבת או קבר שעשה העובד כוכבים שם בסימן שכ\"ה ואם מותר להחשיך עליהן שם בסי' ש\"ו:"],"t":["\u0003בתשלום. \u0004 כתב הלבוש ואנו נוהגין להזכיר אפילו פעם הראשון אפילו בתוך הרגל עכ\"ל:"],"r":["\u0003(ליקוט) מי כו' ואפילו כו'. \u0004ערא\"ש פ\"א דמ\"ק סי' י\"ג ובשם ירוש' כו' (ע\"כ):"]}],["\u0010y0\u0011 שׂוֹרְפִין עַל הַמְּלָכִים \u0005אוֹ עַל הַנְּשִׂיאִים (טוּר בְּשֵׁם תּוֹסֶפְתָּא)\u0006, מִטָּתָן וּכְלֵי תַּשְׁמִישָׁן, אֲבָל עַל הַהֶדְיוֹטוֹת \u0010y1\u0011 אָסוּר.\nהָאוֹמֵר: אַל תִּקְבְּרוּהוּ מִנְּכָסָיו, \u0010y2\u0011 אֵין שׁוֹמְעִין לוֹ, \u0010y3\u0011 אֶלָּא מוֹצִיאִין מִיּוֹרְשָׁיו כָּל צָרְכֵי קְבוּרָתוֹ בְּעַל כָּרְחוֹ, וְכֵן כָּל מַה שֶּׁרְגִילִין לַעֲשׂוֹת לִבְנֵי מִשְׁפַּחְתּוֹ, וַאֲפִלּוּ הָאֶבֶן שֶׁנּוֹתְנִין עַל הַקֶּבֶר; \u0010y4\u0011 וְהוּא שֶׁיָּרְשׁוּ מָמוֹן מֵאֲבִיהֶם.\nאֲפִלּוּ מִי שֶׁאֵין לוֹ מָמוֹן שֶׁצִּוָּה וְאָמַר: אַל תִּקְבְּרוּהוּ, \u0010y5\u0011 אֵין שׁוֹמְעִין לוֹ.",["\u0003שורפין כו'. \u0004ואין בו משום דרכי האמורי ולא משום בל תשחית שזהו כבודם שלא ישתמשו אחרים בכלי תשמישן ומש\"ה שורפים מטתן וכלי תשמישן דוקא ולא דברים אחרים:","\u0003אסור. \u0004דאיכא יוהרא והשחתה:","\u0003אין שומעין לו. \u0004דלאו כל כמיניה להעשיר בניו ולהטיל עצמו על הצבור:","\u0003אלא מוציאין מיורשיו. \u0004אפי' נתן ממון הרבה לאחרים אין מוציאין מהמקבלין מתנות רק מהיורשים כמ\"ש בח\"מ סי' רנ\"ג סל\"א:","\u0003והוא שירשו ממון מאביהם. \u0004דאל\"כ אין כופין הקרובים אלא על הכל מוטל לקברו:","\u0003אין שומעין לו. \u0004משום דאיכא בזיונא דחיי:"],[],"\u0010y0\u0011 \u0010g0\u0011 שׂוֹרְפִין עַל הַמְּלָכִים \u0005אוֹ עַל הַנְּשִׂיאִים \u0010g1\u0011 (טוּר בְּשֵׁם תּוֹסֶפְתָּא)\u0006, מִטָּתָן וּכְלֵי \u0010t0\u0011 תַּשְׁמִישָׁן, \u0010g2\u0011 \u0010r0\u0011 אֲבָל עַל הַהֶדְיוֹטוֹת \u0010y1\u0011 אָסוּר. \u0010g3\u0011\nהָאוֹמֵר: אַל תִּקְבְּרוּהוּ מִנְּכָסָיו, \u0010y2\u0011 אֵין שׁוֹמְעִין לוֹ, \u0010y3\u0011 אֶלָּא מוֹצִיאִין מִיּוֹרְשָׁיו כָּל צָרְכֵי קְבוּרָתוֹ בְּעַל כָּרְחוֹ, וְכֵן כָּל מַה שֶּׁרְגִילִין לַעֲשׂוֹת לִבְנֵי מִשְׁפַּחְתּוֹ, \u0010g4\u0011 וַאֲפִלּוּ הָאֶבֶן שֶׁנּוֹתְנִין עַל הַקֶּבֶר; \u0010y4\u0011 וְהוּא שֶׁיָּרְשׁוּ \u0010t1\u0011 מָמוֹן מֵאֲבִיהֶם. \u0010g5\u0011\nאֲפִלּוּ מִי שֶׁאֵין לוֹ מָמוֹן שֶׁצִּוָּה וְאָמַר: אַל תִּקְבְּרוּהוּ, \u0010y5\u0011 אֵין \u0010t2\u0011 שׁוֹמְעִין לוֹ.",{"g":["\u0003ברייתא עבודת כוכבים דף י\"א ע\"א:\u0004 ","\u0003ואיתא נמי שם בברייתא:\u0004 ","\u0003טור בשם התוספתא:\u0004 ","\u0003כתובות דף מ\"ח ע\"א:\u0004 ","טור מדברי אביו הרא\"ש סנהדרין פ\"ו ובתשובות כלל י\"ג וכתב שאפילו נתן הרבה מתנות לאחרים ולא נשאר לבניו אלא מעט:","בעיא ולא נפשטא סנהדרין דף מ\"ו ע\"ב וכתב הרמב\"ן דספק איסורא הוא ולחומרא וכ\"כ הרמב\"ם סוף פ' י\"א מהלכות זכייה ומתנה:"],"t":["\u0003תשמישן. \u0004 ואין בו משום דרכי האמורי ולא משום בל תשחית שזהו כבודן שלא ישתמשו אחרים בכלי תשמישן ובהדיוטות אסור דאיכא יוהרא והשחתה:","\u0003ממון. \u0004 דאל\"כ אין כופין הקרובים אלא על הכל מוטל לקברו ועיין בח\"מ סימן רנ\"ג סל\"א:","\u0003שומעין. \u0004 משום דאיכא בזיוני דחיי. ש\"ך:"],"r":["\u0003(אבל על הדיוטות אסור. \u0004תוספתא פרק ח' דשבת ופ\"ד דסנהדרין):"]}],["מֵת, בֵּין עוֹבֵד כּוֹכָבִים בֵּין יִשְׂרָאֵל, תַּכְרִיכָיו \u0010y0\u0011 אֲסוּרִים בַּהֲנָאָה. וְדַוְקָא שֶׁהִזְמִינָם לְצָרְכּוֹ וּנְתָנָם עָלָיו, אֲבָל בְּהַזְמָנָה לְבַד, אֲפִלּוּ עֲשָׂאָם לְצָרְכּוֹ לְאַחַר שֶׁמֵּת, לֹא נֶאֶסְרוּ, \u0010y1\u0011 דְּהַזְמָנָה לָאו מִלְּתָא. וְכֵן אִם נְתָנָם עָלָיו וְלֹא הִזְמִינָם לְכָךְ בִּתְחִלָּה, עֲדַיִן לֹא נֶאֶסְרוּ.\nנוֹיֵי הַמֵּת הַמְחֻבָּרִים בְּגוּפוֹ, כְּגוֹן פֵּאָה נָכְרִית וְכַיּוֹצֵא בָהּ, אֲסוּרִים כְּמוֹ הַמֵּת עַצְמוֹ. \u0010y2\u0011 \u0005וְדַוְקָא כְּשֶׁהֵם קְשׁוּרִים בְּשַׂעֲרוֹת גּוּפָן, אֲבָל אֵינָן קְשׁוּרִים, מֻתָּר (כָּךְ מַשְׁמָע מִפֵּרוּשׁ רַשִׁ\"י פ\"ק דַּעֲרָכִין)\u0006 ; וְלָכֵן מֻתָּר לִטֹּל טַבָּעוֹת שֶׁבְּיָדָם שֶׁל מֵתִים, וְכַיּוֹצֵא בָּזֶה. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּסְתָם, אֲבָל אִם צִוָּה שֶׁיִּתְּנוּ נוֹי גּוּפוֹ הַמְחֻבָּרִים בּוֹ לִבְנוֹ אוֹ לְבִתּוֹ אוֹ לְצֹרֶךְ דָּבָר אַחֵר, מֻתָּרִים. אֲבָל שְׂעָרוֹ מַמָּשׁ, אֲפִלּוּ אִם צִוָּה עָלָיו, אָסוּר בַּהֲנָאָה. \u0005הַגָּה: אִשָּׁה שֶׁיּוֹצֵאת לֵהָרֵג, נֶהֱנִין בִּשְׂעָרָהּ, אַף עַל פִּי שֶׁנִּגְמַר דִּינָה, אֵין שַׂעֲרוֹתֶיהָ נֶאֱסָרִים עַד שֶׁתִּקָּטֵל (טוּר)\u0006.\nאִם הָיוּ אָבִיו וְאִמּוֹ מְזָרְקִים עָלָיו כֵּלִים, \u0010y3\u0011 מִצְוָה לַאֲחֵרִים לְהַצִּילָן, אִם לֹא נָגְעוּ \u0010y4\u0011 בַּמִּטָּה הַנִּקְבֶּרֶת עִמּוֹ. \u0005הַגָּה: וְאִם הִצִּילָן, חַיָּב בִּשְׁמִירָתָן; וְאִם הֶחֱזִירָן לְאָבִיו וּלְאִמּוֹ, וְחָזְרוּ וּזְרָקוּם, וְנֶאֶסְרוּ, חַיָּב הַמַּחֲזִיר לְשַׁלֵּם, דְּהָוֵי כִּזְרָקָן לִמְקוֹם גְּדוּדֵי חַיּוֹת וְלִסְטִים (בְּמָרְדְּכַי פֶּרֶק הַמּוֹכֵר אֶת הַסְפִינָה תְּשׁוּבַת מהר\"מ)\u0006. אֲבָל אִם נָגְעוּ בָּהּ, \u0010y5\u0011 אֲסוּרִים, \u0010y6\u0011 אִם הֵם שֶׁל אוֹתוֹ שֶׁזְּרָקָן עָלָיו, \u0010y7\u0011 וְהוּא שֶׁיִּזְרְקֵם עַל דַּעַת שֶׁיִּקְבְּרֵם עִמּוֹ \u0005(טוּר בְּשֵׁם רֹא\"שׁ וְהוּא סוֹף מ\"ק)\u0006. \u0005הַגָּה: הַדַּף שֶׁטִּהֲרוּ עָלָיו, וְכָל הַכֵּלִים שֶׁמּוֹלִיכִין הַמֵּת עֲלֵיהֶם לִקְבוּרָה, לֹא נֶאֶסְרוּ, דַּהֲרֵי לֹא נְתָנָם שָׁם עַל מְנָת לִקְבֹּר עִמּוֹ.\u0006 \u0005(תְּשׁוּבַת מהרי\"ל סִימָן נ\"ה, וְכָךְ מַשְׁמָע מִדִּבְרֵי הָרֹא\"שׁ שֶׁהֵבִיא הַטּוּר)\u0006.\nכָּל הַמַּרְבֶּה כֵּלִים עַל הַמֵּת, הֲרֵי זֶה עוֹבֵר מִשּׁוּם בַּל תַּשְׁחִית. \u0005(וַיִּקְרָא כ, יט)\u0006.",["\u0003אסורים בהנאה. \u0004דכתיב ותקבר שם מרים וילפינן שם שם מעגלה ערופה מה עגלה ערופה אסורה בהנאה אף מת וכל תכריכיו אסורים בהנאה:","\u0003דהזמנה לאו מלתא היא כו'. \u0004עיין בא\"ח ס\"ס מ\"ב:","\u0003ודוקא כשהם קשורים כו'. \u0004והב\"ח פסק דאפי' קלועים בתוכם ואינם קשורים אסורים אלא כשאינן קשורין בה כלל דהיינו דתלי בסיכתא מותרים ע\"ש:","\u0003מצוה לאחרים כו'. \u0004שיש בו משום השבת אבדה דודאי יתחרטו אח\"כ:","\u0003במטה הנקברת עמו. \u0004כלומר שנושאין אותו בה לקבורה:","\u0003אסורים. \u0004מדרבנן שגזרו בהן משום דמיחלפי בתכריכי המת:","\u0003אם הם של אותו כו'. \u0004לאפוקי של אחרים דלא דאין אדם אוסר דבר שאינו שלו:","\u0003והוא שיזרקם ע\"ד שיקברם עמו. \u0004כגון שיזרקם מתוך מרירות הלב ע\"מ לקברן עמו ונגעו במטה הנקברת לאפוקי המצע שמניחים על המת או הכר וכסת שנותנים תחת מראשותיו או סדין או טלית שפירסו על הארון או על המטה שמוליכין בה המת לקברו אינו נאסר:"],[],"\u0010g0\u0011 מֵת, \u0010r0\u0011 בֵּין עוֹבֵד כּוֹכָבִים בֵּין יִשְׂרָאֵל, תַּכְרִיכָיו \u0010y0\u0011 אֲסוּרִים בַּהֲנָאָה. וְדַוְקָא שֶׁהִזְמִינָם לְצָרְכּוֹ וּנְתָנָם עָלָיו, \u0010g1\u0011 אֲבָל בְּהַזְמָנָה לְבַד, אֲפִלּוּ עֲשָׂאָם לְצָרְכּוֹ לְאַחַר שֶׁמֵּת, לֹא נֶאֶסְרוּ, \u0010y1\u0011 דְּהַזְמָנָה לָאו מִלְּתָא. \u0010g2\u0011 וְכֵן אִם נְתָנָם עָלָיו וְלֹא הִזְמִינָם לְכָךְ בִּתְחִלָּה, עֲדַיִן לֹא נֶאֶסְרוּ. \u0010g3\u0011\nנוֹיֵי הַמֵּת הַמְחֻבָּרִים בְּגוּפוֹ, כְּגוֹן פֵּאָה נָכְרִית וְכַיּוֹצֵא בָהּ, אֲסוּרִים כְּמוֹ הַמֵּת עַצְמוֹ. \u0010y2\u0011 \u0005וְדַוְקָא כְּשֶׁהֵם \u0010t0\u0011 קְשׁוּרִים בְּשַׂעֲרוֹת גּוּפָן, אֲבָל אֵינָן קְשׁוּרִים, מֻתָּר (כָּךְ מַשְׁמָע מִפֵּרוּשׁ רַשִׁ\"י פ\"ק דַּעֲרָכִין)\u0006 ; וְלָכֵן מֻתָּר לִטֹּל טַבָּעוֹת שֶׁבְּיָדָם שֶׁל מֵתִים, וְכַיּוֹצֵא בָּזֶה. \u0010r1\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, בִּסְתָם, אֲבָל אִם צִוָּה שֶׁיִּתְּנוּ נוֹי גּוּפוֹ הַמְחֻבָּרִים בּוֹ לִבְנוֹ אוֹ לְבִתּוֹ אוֹ לְצֹרֶךְ דָּבָר אַחֵר, מֻתָּרִים. אֲבָל שְׂעָרוֹ מַמָּשׁ, אֲפִלּוּ אִם צִוָּה עָלָיו, אָסוּר בַּהֲנָאָה. \u0005הַגָּה: אִשָּׁה שֶׁיּוֹצֵאת לֵהָרֵג, נֶהֱנִין בִּשְׂעָרָהּ, אַף עַל פִּי שֶׁנִּגְמַר דִּינָה, אֵין שַׂעֲרוֹתֶיהָ נֶאֱסָרִים עַד שֶׁתִּקָּטֵל (טוּר)\u0006. \u0010g4\u0011\nאִם הָיוּ אָבִיו וְאִמּוֹ מְזָרְקִים עָלָיו כֵּלִים, \u0010y3\u0011 מִצְוָה לַאֲחֵרִים לְהַצִּילָן, אִם לֹא נָגְעוּ \u0010y4\u0011 בַּמִּטָּה הַנִּקְבֶּרֶת עִמּוֹ. \u0005הַגָּה: וְאִם הִצִּילָן, חַיָּב בִּשְׁמִירָתָן; וְאִם הֶחֱזִירָן לְאָבִיו וּלְאִמּוֹ, וְחָזְרוּ וּזְרָקוּם, וְנֶאֶסְרוּ, חַיָּב הַמַּחֲזִיר לְשַׁלֵּם, דְּהָוֵי כִּזְרָקָן לִמְקוֹם גְּדוּדֵי חַיּוֹת וְלִסְטִים (בְּמָרְדְּכַי פֶּרֶק הַמּוֹכֵר אֶת הַסְפִינָה תְּשׁוּבַת מהר\"מ)\u0006. אֲבָל אִם נָגְעוּ בָּהּ, \u0010y5\u0011 אֲסוּרִים, \u0010y6\u0011 \u0010g5\u0011 אִם הֵם שֶׁל אוֹתוֹ שֶׁזְּרָקָן עָלָיו, \u0010y7\u0011 וְהוּא שֶׁיִּזְרְקֵם עַל דַּעַת שֶׁיִּקְבְּרֵם עִמּוֹ \u0005(טוּר בְּשֵׁם רֹא\"שׁ וְהוּא סוֹף מ\"ק)\u0006. \u0005הַגָּה: הַדַּף שֶׁטִּהֲרוּ עָלָיו, וְכָל הַכֵּלִים שֶׁמּוֹלִיכִין הַמֵּת עֲלֵיהֶם לִקְבוּרָה, לֹא נֶאֶסְרוּ, דַּהֲרֵי לֹא נְתָנָם שָׁם עַל מְנָת לִקְבֹּר עִמּוֹ.\u0006 \u0005(תְּשׁוּבַת מהרי\"ל סִימָן נ\"ה, וְכָךְ מַשְׁמָע מִדִּבְרֵי הָרֹא\"שׁ שֶׁהֵבִיא הַטּוּר)\u0006. \u0010g6\u0011\nכָּל הַמַּרְבֶּה כֵּלִים עַל הַמֵּת, הֲרֵי זֶה עוֹבֵר מִשּׁוּם בַּל תַּשְׁחִית. \u0005(וַיִּקְרָא כ, יט)\u0006.",{"g":["ברייתות ומימרות סנהדרין דף מ\"ז ע\"ב ודף מ\"ח ע\"א:\n(°) תשובת הרשב\"א סימן שס\"ה:","\u0003שם וכרבא דהזמנה לאו מילתא היא:\u0004 ","\u0003מימרא דרב חסדא שם:\u0004 ","ערכין דף ז' ע\"ב ומה שתמה הכ\"מ על הרמב\"ם בסוף הלכות אבל על מה שכתב שם בדין שער המת וכן בב\"י עיין בתשובות הרשב\"א סימן ש\"ל שהאריך בזה:\n(°) שם מאוקימתא דרב נחמן:","ברייתא סנהדרין דף מ\"ח ע\"א וכרשב\"ג שם:\n(°) פירוש מדרבנן משום דמחלפי בתכריכי המת ואתו למימר תכריכי המת מותרים:","\u0003טור מדברי הרמב\"ן בסת\"ה ממשמעות הגמרא יבמות דף ס\"ו ע\"ב:\u0004 ","\u0003ברייתא באבל רבתי פ\"ט:\u0004 "],"t":["\u0003קשורים. \u0004 והב\"ח פסק דאפי' קלועים בתוכם ואינם קשורים אסורים אלא כשאינן קשורים בה כלל דהיינו דתלי בסיכתא מותרים:"],"r":["\u0003(ליקוט) בין עובד כוכבים. \u0004אבל הרשב\"א בב\"ק כתב בפשיטות דמת עובד כוכבים מותר בהנאה וכ\"כ תופ' שם י' א' סד\"ה שהשור וכ' הרשב\"א שם דהיינו עבד ערל ע\"ש וכ\"כ בפ' הפרה נ\"ד א' וסתר תירוץ ראשון של תוס' וי\"ל דוהמת יהיה כו' דליתא דודאי כולה משתמע מוהמת י\"ל כמש\"ש נ\"ד א' אלא א\"ק והמת י\"ל כ\"ד כו' ועוד דפריך בין לרבנן כו' ואם איתא הא משתעי בשור לבד כו' אלא כמסקנא דתוס' בשביל עבד ועובד כוכבים דאיסורא דמת ילפינן ממרים ודוקא ישראלים כמותה עכ\"ל שם (ע\"כ):\n\u0003(ליקוט) בין עובד כוכבים. \u0004כ\"כ בבד\"ה בשם הרשב\"א וליתא ובירושלמי פ\"י דשבת הלכה ו' אמר בהדיא דמותר דגרסינן שם את המת במטה חייב דברי הכל לא כן תני אף ריח רע כל שהוא וא\"ר אילא אף ר\"ש מודה בה ומודה ר\"ש באיסורי הנאה א\"ר יודן תיפתר במת עובד כוכבים ושאין בו ריח רע והוציאו לכלבו תני חצי זית מן המת וחצי זית מן הנבילה ופחות מכעדשה מן השרץ חייב ור\"ש פוטר מ\"מ דר\"ש כבר נתמעטה הטומאה מ\"מ דרבנן כההיא דר' יודן תיפתר במת עובד כוכבים ושאין בו ריח רע והוציאו לכלבו וט\"ס כאן בירושלמי וצ\"ל ברישא מ\"ט דרבנן ובסיפא מ\"ט דר\"ש וה\"פ את כו' ד\"ה ר\"ל דל\"פ אלא בסיפא בשיעורא דת\"ק מחייב כשיעור טומאה ור\"ש לא מחייב בכך אבל במת שלם מודה ר\"ש ופריך לא כן כו' והוא בפ' כלל גדול על מתני' מקק ספרים כו' אמר שם תני כו' וה\"נ ליחייב בכ\"ש משום ריח רע ועוד משום איסורי הנאה וה\"ה דיכול למיפרך את\"ק אלא על ר\"ש יותר קשה דאף בכזית פוטר וא\"ר יודן כו' והוציאו לכלבו דצריכה לגופה דבלא\"ה פוטר ר\"ש ולכך פוטר ר\"ש בכזית דבעי שיעור מלא פי כלב ואמר תני חצי כו' ר\"ל מכזית כמ\"ש בגמ' ור\"ש פוטר וה\"ה בכזית אלא משום ת\"ק נקטה ואמר מ\"מ דרבנן כבר כו' משום דמיעטה לטומאה אבל ר\"ש פוטר משום זה משום דהוי מלאכה שא\"צ לגופה אלא לטהרות הבית אבל בריח רע ואיסורי הנאה מודה דחייב אע\"ג דהוי מלאכה שאצ\"ל וקאמר מ\"ט דר\"ש כקושיא הנ\"ל לא כן כו' ואמר כההיא כו'. מ\"מ נשמע בהדיא דמותר וכ\"כ הרשב\"א והר\"נ בשבת צ\"ד ב' על מש\"ש דמי קאמינא לר\"ה כו' דמקשין דלר\"ש יהא מותר אף לר\"ה ותי' ר\"ח דלא התירו אלא בדבר שעיקרו מד\"ס אבל ר\"ה לא דמי מפיס אם צריך לגופה או לא שהרי אפשר אף בהוצאת המת שיהא צריך לגופה כגון אותה שאמרו בירושלמי בעובד כוכבים שהוציאו לכלבו והן דברי הרמב\"ן בספר תה\"א שער ז' כ\"ה ד' וכ\"ד תוס' \u0005(בב\"ק) \u0006הרי תוס' ורמב\"ן ורשב\"א ור\"נ התירו וכן בירושלמי כנ\"ל וכ\"מ בגמ' דסנהדרין י\"ט ב' ועכ\"מ פ\"ה דהלכות ערכין הלכה י\"ז (ע\"כ):\n\u0003(ליקוט) בין עובד כוכבים. \u0004כ\"כ בבד\"ה בשם תשובת הרשב\"א והוא שם סימן שס\"ה אבל אין הכרח דפשיטא ליה לאיסור ובחידושיו \u0005(בב\"ק) \u0006כתב בשני מקומות בפשיטות להיתר ויש ראיות על זה וע' משנה למלך סוף הלכות אבל שהאריך וכתב בשם הירושלמי \u0005(כנ\"ל בליקוט ב') \u0006שמותר (ע\"כ):\n\u0003(ליקוט) בין עובד כוכבים. \u0004אבל תוס' ורשב\"א לא כתבו כן והביאו משנה למלך ושאר אחרונים ראיה מדוד שקידש בערלות פלשתים ש\"מ דלאו איסורי הנאה נינהו ובפ\"ב דסנהדרין \u0005(י\"ט ב') \u0006אמרינן דחזו לכלבי ושונרי (ע\"כ):","\u0003בד\"א בסתם כו' אבל כו' אשה כו'. \u0004הכל גמ' שם:"]}],["אִם רָצוּ, מַתִּירִין שְׂעָרוֹת לְכַלּוֹת, וּמְגַלִּים פְּנֵי חֲתָנִים, וְנוֹתְנִין דְּיוֹ וְקֻלְמוֹס בְּצִדּוֹ, \u0010y0\u0011 וְתוֹלִין מַפְתְּחוֹ שֶׁל מֵת וּפִנְקָסוֹ בָּאֲרוֹנוֹ, מִשּׁוּם עָגְמַת נֶפֶשׁ. וְעוֹשִׂים חֻפּוֹת לַחֲתָנִים וְכַלּוֹת, וְתוֹלִין בָּהֶם דְּבָרִים שֶׁלֹּא הֵבִיאוּ אֹכֶל נֶפֶשׁ; אֲבָל דְּבָרִים שֶׁהֵבִיאוּ אוֹכֵל נֶפֶשׁ, אָסוּר, \u0010y1\u0011 מִפְּנֵי שֶׁהֵם נֶאֱסָרִים בַּהֲנָאָה.",["\u0003ותולין כו'. \u0004כתב הב\"ח ומיהו עכשיו לא נהגו לעשות כן ומעכבין על מי שבא לשנות המנהג:","\u0003מפני שהם נאסרים בהנאה. \u0004והוה בהו משום בל תשחית לאסור אוכל נפש שלא לצורך:"],[],"\u0010g0\u0011 \u0010r0\u0011 אִם רָצוּ, מַתִּירִין שְׂעָרוֹת לְכַלּוֹת, וּמְגַלִּים פְּנֵי חֲתָנִים, וְנוֹתְנִין דְּיוֹ וְקֻלְמוֹס בְּצִדּוֹ, \u0010y0\u0011 \u0010t0\u0011 וְתוֹלִין מַפְתְּחוֹ שֶׁל מֵת וּפִנְקָסוֹ בָּאֲרוֹנוֹ, מִשּׁוּם עָגְמַת נֶפֶשׁ. וְעוֹשִׂים חֻפּוֹת לַחֲתָנִים וְכַלּוֹת, וְתוֹלִין בָּהֶם דְּבָרִים שֶׁלֹּא הֵבִיאוּ אֹכֶל נֶפֶשׁ; אֲבָל דְּבָרִים שֶׁהֵבִיאוּ אוֹכֵל נֶפֶשׁ, אָסוּר, \u0010y1\u0011 \u0010g1\u0011 מִפְּנֵי שֶׁהֵם נֶאֱסָרִים בַּהֲנָאָה.",{"g":["\u0003ברייתא באבל רבתי:\u0004 ","\u0003כחכמים שם שאין אוסרין אוכלים ואין מפסידין אותן אלא לצורך:\u0004 "],"t":["\u0003ותולין. \u0004 וכתב הב\"ח ועכשיו לא נהגו כן ומעכבין על מי שבא לשנות המנהג:"],"r":["\u0003(ליקוט) אם רצו כו' ועושים חופות כו'. \u0004א\"ר פ\"ח (ע\"כ):\n\u0003(ליקוט) אם כו'. \u0004ערא\"ש פ\"ג דמ\"ק סי' קכ\"ח (ע\"כ):"]}],["תַּכְרִיכֵי הַמֵּת, מֻתָּר לַעֲשׂוֹתָן \u0010y0\u0011 מִכִּלְאַיִם.\nאֵין קוֹבְרִין אֶת הַמֵּת אֶלָּא בְּטַלִּית שֶׁיֵּשׁ בּוֹ צִיצִית. \u0005הַגָּה: \u0010c0\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין צָרִיךְ צִיצִית (טוּר בְּשֵׁם י\"א)\u0006. וְנָהֲגוּ לְקָבְרוֹ בְּצִיצִית, \u0010y1\u0011 אַךְ שֶׁפּוֹסְלִין תְּחִלָּה הַצִּיצִית, אוֹ כּוֹרְכִין אֶחָד מִן הַכַּנְפוֹת.",["\u0003מכלאים. \u0004כדלעיל סי' ש\"א סעיף ז':","\u0003אך שפוסלין כו'. \u0004והב\"ח כתב דאין לפסלן אלא יש לקשרן זה עם זה או לכסותם תוך הכנפות ע\"ש:"],["\u0003וי\"א שא\"צ ציצית. \u0004כשנפטר רבינו גרשון אמר ציצית חוץ ונחלקו בפירוש דבריו יש אומרים דרצונו לומר יסירו הציצית מהטלית ויש אומרים דהכי קאמר שישימו אותן חוץ לארון:"],"\u0010g0\u0011 תַּכְרִיכֵי הַמֵּת, מֻתָּר לַעֲשׂוֹתָן \u0010y0\u0011 מִכִּלְאַיִם. \u0010g1\u0011 \u0010r0\u0011\nאֵין קוֹבְרִין אֶת הַמֵּת אֶלָּא בְּטַלִּית שֶׁיֵּשׁ בּוֹ צִיצִית. \u0005הַגָּה: \u0010c0\u0011 \u0010r1\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין צָרִיךְ צִיצִית (טוּר בְּשֵׁם י\"א)\u0006. וְנָהֲגוּ לְקָבְרוֹ בְּצִיצִית, \u0010y1\u0011 אַךְ \u0010t0\u0011 שֶׁפּוֹסְלִין תְּחִלָּה הַצִּיצִית, אוֹ כּוֹרְכִין אֶחָד מִן הַכַּנְפוֹת.",{"g":["\u0003משנה ד' פ\"ט דכלאים:\u0004 ","כהכרעת הרמב\"ן בסת\"ה:\n(°) בטור כתב קושרין וכתב שם בשעה שקוברין אותו:"],"t":["\u0003שפוסלין. \u0004 והב\"ח כתב דאין לפוסלן אלא יש לקושרן זה עם זה או לכסותם תחת הכנפות וכתב הט\"ז כשנפטר רבינו גרשום אמר ציצית חוץ ונחלקו בפירוש דבריו י\"א דרצונו לומר יסירו הציצית מהטלית ויש אומרים דה\"ק שישימו אותן חוץ לארון עכ\"ל:"],"r":["\u0003אין כו' וי\"א כו'. \u0004עתוס' דנדה ס\"א ב' ד\"ה לא כו' ובברכות י\"ח א' ד\"ה למחר כו':\n\u0003(ליקוט) אין כו'. \u0004כמ\"ש בפ\"ד דמנחות \u0005(מ\"א א') \u0006ההיא שעתא ודאי רמינן כו' ואע\"ג דבפי\"ב דא\"ר אמר אבא שאול התירו תכלת מאפליוני ועליה סמכו תוס' וש\"פ כ' בספר תה\"א \u0005(ובמלחמות סוף מ\"ק) \u0006דחכמים חולקין על אבא שאול כמ\"ש במס' ציצית אין מתירין ציצית על המת אבא שאול בן בטנית מתיר אמר אבא שאול אבא אמר לי כשאמות התר לי ציצותי לפי שיש בהן משום קדושה וחכ\"א אין בהן משום קדושה אלא עושה אותן תכריך למת ומרדעת לחמור והלכה כחכמים וכן אמרינן ברפ\"ד דמגילה ת\"ר תשמישי כו' (ע\"כ):","\u0003(ליקוט) וי\"א כו'. \u0004ערא\"ש פ\"ג דמ\"ק סי' קכ\"ז (ע\"כ):"]}],["\u0010y0\u0011 אֵין קוֹבְרִין הַמֵּת בְּתַכְרִיכִים יְקָרִים, אֲפִלּוּ לְנָשִׂיא שֶׁבְּיִשְׂרָאֵל.\nנָהֲגוּ לִקְבֹּר בִּבְגָדִים לְבָנִים. \u0010y1\u0011\nהָאִישׁ אֵינוֹ כּוֹרֵךְ וּמְקַשֵּׁר הָאִשָּׁה, אֲבָל הָאִשָּׁה כּוֹרֶכֶת וּמְקַשֶּׁרֶת הָאִישׁ.\nמַעֲצִימִין עֵינָיו שֶׁל מֵת; וְאִם נִפְתַּח פִּיו, קוֹשְׁרִין לְחַיָּיו. וּפוֹקְקִין נְקָבָיו אַחַר שֶׁמְּדִיחִין אוֹתוֹ בְּמִינֵי בְּשָׂמִים. וְגוֹזְזִין שְׂעָרוֹ. \u0005הַגָּה: וְצִפָּרְנָיו. וּמְדִיחִים אוֹתוֹ הֵיטֵב בְּכָל מָקוֹם, שֶׁיְּהֵא נָקִי מִכָּל טֻמְאָה (בִּנְיָמִין זְאֵב)\u0006, וְטָחִין רֹאשׁוֹ בְּבֵיצִים טְרוּפִים בִּקְלִפָּתָן, שֶׁגַּלְגַּל הוּא שֶׁחוֹזֵר בָּעוֹלָם \u0005(כָּל בּוֹ)\u0006.",["\u0003אין קוברין כו'. \u0004משום תיקון העולם שהעניים אינם יכולים לעשות כן וגם משום גסות הרוח והשחתה וכתוב בד\"מ והגהת דרישה בשם נ\"י פרק אלו מגלחין כל העושה תכריכין נאים למת מכירין בו שהוא מודה בתחיית המתים ותע\"ב עכ\"ל. ומיירי שהבגד פשתן יהא נאה וע\"כ נהגו קצת לחזור אחר היפה אבל בחשובים יותר מדאי ודאי אסור:","\u0003האיש אינו כורך. \u0004משום הרהור אבל באשה ליכא הרהור כל כך:"],[],"\u0010y0\u0011 \u0010g0\u0011 אֵין קוֹבְרִין הַמֵּת בְּתַכְרִיכִים \u0010t0\u0011 יְקָרִים, אֲפִלּוּ לְנָשִׂיא שֶׁבְּיִשְׂרָאֵל. \u0010g1\u0011 \u0010r0\u0011\nנָהֲגוּ לִקְבֹּר בִּבְגָדִים לְבָנִים. \u0010y1\u0011 \u0010g2\u0011\nהָאִישׁ אֵינוֹ כּוֹרֵךְ וּמְקַשֵּׁר הָאִשָּׁה, אֲבָל הָאִשָּׁה כּוֹרֶכֶת וּמְקַשֶּׁרֶת הָאִישׁ. \u0010g3\u0011 \u0010r1\u0011\nמַעֲצִימִין עֵינָיו שֶׁל מֵת; וְאִם נִפְתַּח פִּיו, קוֹשְׁרִין לְחַיָּיו. וּפוֹקְקִין נְקָבָיו אַחַר שֶׁמְּדִיחִין אוֹתוֹ בְּמִינֵי בְּשָׂמִים. וְגוֹזְזִין שְׂעָרוֹ. \u0005הַגָּה: וְצִפָּרְנָיו. וּמְדִיחִים אוֹתוֹ הֵיטֵב בְּכָל מָקוֹם, שֶׁיְּהֵא נָקִי מִכָּל טֻמְאָה (בִּנְיָמִין זְאֵב)\u0006, וְטָחִין רֹאשׁוֹ בְּבֵיצִים טְרוּפִים בִּקְלִפָּתָן, שֶׁגַּלְגַּל הוּא שֶׁחוֹזֵר בָּעוֹלָם \u0010g4\u0011 \u0005(כָּל בּוֹ)\u0006.",{"g":["\u0003ברייתא משמיה דרשב\"ג מ\"ק דף כ\"ז ע\"ב:\u0004 ","\u0003טור וכ\"כ הרמב\"ן בסת\"ה:\u0004 ","\u0003ברייתא באבל רבתי פי\"ב:\u0004 ","טור בשם הרמב\"ן בשם מנהג כל ישראל וכתב הכל בו כדי להעביר זוהמתן שלא יקוצו העם בטלטולו\n(°) עיין בערוך ערך (עמץ) [אמץ]):","\u0003וכתב שם הוא סי' הקדום לפי שהיו מוליכין אותו חוץ לעיר כדי שיכירו הקוברין שהוא ישראל:\u0004 "],"t":["\u0003יקרים. \u0004 ובד\"מ כתוב כל העושה תכריכין נאים למת מכירין בו שהוא מודה בתחיית המתים ותע\"ב עכ\"ל ומיירי שהבגד פשתן יהא נאה וע\"כ נהגו קצת לחזור אחר היפה אבל חשובים יותר מדאי ודאי אסור ש\"ך \u0005(ומיהו נראה הכל לפי מה שהוא אדם אם הוא משופע בעושר אין איסור להלבישו בפשתן חשוב דר\"י קרא למנא מכבדותא א\"כ מה שהוא כבוד למת ודאי מותר. ובפרט מה שכתבו המקובלים שמלבישין הנשמה בבגדי חופש כמו שמלבישין להגוף וראיה משתי רוחות דגמרא ברכות. ועוד כמה ראיות לזה וע\"כ יזהרו שלא לשנות בלבישת המתים מן הנהוג כי מצינו שהמתים מקפידין ע\"ז כדאיתא בס\"ח ובס' החיים. ובס' מעבר יבק כ' אפי' ירקבו התכריכים לעולם הנפש תתלבש ברוחניותם ויש בני אדם שמצוים איזה דברים בעניני תכריכין ומצוה לקיים דברי המת אם אפשר ואם אינו נגד הדין. מעשה שחפרו המתים בבה\"ק שלנו והפשיטום ערומים והיינו נוהגים כמ\"ש בש\"י ח\"ב שאלה ק\"ג ע\"ש. אם שכחו להלביש איזה דבר מבגדי המת יניחו אותו על הארון ועיין בשו\"ת ח\"צ סימן מ\"ז וכנ\"י ס\"ד. ובס\"ח סימן תנ\"א כ' כשיש דבר בעיר ב\"מ מחפשין על אותן המתים שמא יש בהם שבלה הבגד פי' שנקברים בבגדים בלוים והוא סכנה או ידיו פשוטות וכו' וכל דבר שהוא משום פקוח נפש יכול לעשות למת עכ\"ל)\u0006:"],"r":["\u0003(ליקוט) נהגו כו'. \u0004אע\"ג דבפט\"ו דשבת \u0005(קי\"ד א') \u0006א\"ל ר' ינאי כו' בירושלמי \u0005(סוף כלאים ופי\"ב דכתובות) \u0006אמרו ר' יאשיה מפקד אלבשוניה חוורין חפתין א\"ל מה את טב מן רבך א\"ל ומה אנא בהית בעובדוי. ר' ירמיה מפקד אלבשוני חוורין חפיתין יהבון כו' ומכאן נתפשט המנהג הכל בלבנים (ע\"כ):","\u0003מעצימין כו'. \u0004פכ\"ג רשבת \u0005(קנ\"א ב'):\u0006"]}],["בָּרִאשׁוֹנָה הָיוּ מְגַלִּים פְּנֵי עֲשִׁירִים וּמְכַסִים פְּנֵי עֲנִיִּים, מִפְּנֵי שֶׁמַּשְׁחִירִים בִּשְׁנַת בַּצֹּרֶת, וְהָיוּ עֲנִיִּים חַיִּים מִתְבַּיְּשִׁים. הִתְקִינוּ שֶׁיִּהְיוּ מְכַסִים פְּנֵי הַכֹּל. \u0010y0\u0011 \u0010c0\u0011\nאֵין מַנִּיחִין סֵפֶר תּוֹרָה עַל מִטָּתוֹ שֶׁל חָכָם.\nכְּבוֹדוֹ שֶׁל חָכָם לְהוֹצִיאוֹ דֶּרֶךְ הַפֶּתַח, וְלֹא לְשַׁלְשְׁלוֹ דֶּרֶךְ גַּגּוֹת; וּבְמִטָּה רִאשׁוֹנָה, וְלֹא לְשַׁנּוֹתוֹ מִמִּטָּה לְמִטָּה.\nתִּינוֹק בֶּן ל' יוֹם, מוֹצִיאִים אוֹתוֹ \u0010y1\u0011 בְּחֵיק לְבֵית הַקְּבָרוֹת, וְלֹא בְּאָרוֹן, וְנִקְבָּר בְּאִשָּׁה אַחַת וּשְׁנֵי אֲנָשִׁים; \u0010y2\u0011 אֲבָל לֹא בְּאִישׁ אֶחָד וּשְׁתֵּי נָשִׁים, מִשּׁוּם יִחוּד. \u0010y3\u0011 וְאֵין עוֹמְדִים עָלָיו \u0010y4\u0011 בְּשׁוּרָה, וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים, וַאֲפִלּוּ אִם קִים לָן שֶׁכָּלוּ לוֹ חֳדָשָׁיו.\nבֶּן ל' יוֹם גְּמוּרוֹת, יוֹצֵא \u0010y5\u0011 בִּגְלוּסְקָמָא \u0005(פי' אָרוֹן וַיִּישֶׂם בָּאָרוֹן (בְּרֵאשִׁית נ, כו)\u0006, ת\"י וְשַׁוּוּן יָתֵהּ בִּגְלוּסְקָמָא נ\"י) \u0010c1\u0011 הַנִּטֶּלֶת בַּאֲגַפַּיִם \u0005(פי' נֶסֶר רָחָב, וּפי' אֲגַפַּיִם, זְרוֹעוֹת)\u0006, וְעוֹמְדִין עָלָיו בְּשׁוּרָה, וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים. בֶּן י\"ב חֹדֶשׁ, יוֹצֵא בְּמִטָּה. וְכָל הַיּוֹצֵא בְּמַטָּה, רַבִּים מַצְהִיבִים עָלָיו; וְשֶׁאֵינוֹ יוֹצֵא בְּמִטָּה, אֵין רַבִּים מַצְהִיבִים עָלָיו. וְכָל הַנִּכָּר לָרַבִּים, רַבִּים מִתְעַסְקִין בּוֹ; וְכָל שֶׁאֵינוֹ נִכָּר לָרַבִּים, אֵין רַבִּים חַיָּבִים לְהִתְעַסֵק בּוֹ.\nתִּינוֹק שֶׁמֵּת \u0010y6\u0011 קֹדֶם שֶׁנִּמּוֹל, מוֹהֲלִין אוֹתוֹ עַל קִבְרוֹ, בְּלֹא בְּרָכָה, וְקוֹרִין לוֹ שֵׁם.\nאֵין מוֹצִיאִין מֵת בְּמִטָּה, אֶלָּא אִם כֵּן הָיָה רֹאשׁוֹ וְרֻבּוֹ קַיָּם.",["\u0003אין מניחין וכו'. \u0004דוקא על מטתו אבל לפניו על גבי קרקע או ספסל משמע בטור לעיל סי' שד\"מ מתשו' רב האי שמותר וכ\"כ בפרישה:","\u0003בחיק כו'. \u0004וכתוב בא\"ז דהיינו דא\"צ להוציא ואלא בחיק אבל אם רוצים להוציאו במטה הרשות בידם ומביאו הב\"ח:","\u0003אבל לא באיש א' ושתי נשים. \u0004משום יחוד:","\u0003ואין עומדין כו'. \u0004פי' אין צריך לעמוד. רש\"י וכ\"כ העט\"ז:","\u0003בשורה. \u0004ר\"ל שהיה כל אחד אומר לו תתנחם:","\u0003בגלוסקמא. \u0004פי' בנסר רחב שאינו ניטל אלא על הכתפים ואין צריך מטה גדול:","\u0003מוהלין כו'. \u0004נתבאר לעיל ס\"ס רס\"ג:"],["\u0003אין מניחין ס\"ת על מטתו. \u0004בסימן שד\"מ העתיק ב\"י בשם ת\"ה וז\"ל ואם נפטר אדם גדול וחסיד ויחיד במקומו אל יהיה ס\"ת בדבר זה מוטל אלא עומד בתיבה וכדומה לה עכ\"ל:","\u0003הניטלת באגפיים. \u0004פירוש בשני בני אדם דרך כבוד:"],"\u0010g0\u0011 בָּרִאשׁוֹנָה הָיוּ מְגַלִּים פְּנֵי עֲשִׁירִים וּמְכַסִים פְּנֵי עֲנִיִּים, מִפְּנֵי שֶׁמַּשְׁחִירִים בִּשְׁנַת בַּצֹּרֶת, וְהָיוּ עֲנִיִּים חַיִּים מִתְבַּיְּשִׁים. הִתְקִינוּ שֶׁיִּהְיוּ מְכַסִים פְּנֵי הַכֹּל. \u0010y0\u0011 \u0010c0\u0011 \u0010g1\u0011\nאֵין מַנִּיחִין סֵפֶר תּוֹרָה עַל \u0010t0\u0011 מִטָּתוֹ שֶׁל חָכָם. \u0010g2\u0011\nכְּבוֹדוֹ שֶׁל חָכָם לְהוֹצִיאוֹ דֶּרֶךְ הַפֶּתַח, וְלֹא לְשַׁלְשְׁלוֹ דֶּרֶךְ גַּגּוֹת; וּבְמִטָּה רִאשׁוֹנָה, וְלֹא לְשַׁנּוֹתוֹ מִמִּטָּה לְמִטָּה. \u0010g3\u0011\nתִּינוֹק בֶּן ל' יוֹם, מוֹצִיאִים אוֹתוֹ \u0010y1\u0011 \u0010t1\u0011 בְּחֵיק לְבֵית הַקְּבָרוֹת, וְלֹא בְּאָרוֹן, וְנִקְבָּר בְּאִשָּׁה אַחַת וּשְׁנֵי אֲנָשִׁים; \u0010y2\u0011 אֲבָל לֹא בְּאִישׁ אֶחָד וּשְׁתֵּי נָשִׁים, מִשּׁוּם יִחוּד. \u0010y3\u0011 וְאֵין עוֹמְדִים עָלָיו \u0010y4\u0011 בְּשׁוּרָה, וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים, \u0010r0\u0011 וַאֲפִלּוּ אִם קִים לָן שֶׁכָּלוּ לוֹ חֳדָשָׁיו. \u0010g4\u0011\nבֶּן ל' יוֹם גְּמוּרוֹת, יוֹצֵא \u0010y5\u0011 בִּגְלוּסְקָמָא \u0005(פי' אָרוֹן וַיִּישֶׂם בָּאָרוֹן (בְּרֵאשִׁית נ, כו)\u0006, ת\"י וְשַׁוּוּן יָתֵהּ בִּגְלוּסְקָמָא נ\"י) \u0010c1\u0011 הַנִּטֶּלֶת בַּאֲגַפַּיִם \u0005(פי' נֶסֶר רָחָב, וּפי' אֲגַפַּיִם, זְרוֹעוֹת)\u0006, וְעוֹמְדִין עָלָיו בְּשׁוּרָה, וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים. בֶּן י\"ב חֹדֶשׁ, יוֹצֵא בְּמִטָּה. \u0010g5\u0011 וְכָל הַיּוֹצֵא בְּמַטָּה, רַבִּים מַצְהִיבִים עָלָיו; וְשֶׁאֵינוֹ יוֹצֵא בְּמִטָּה, אֵין רַבִּים מַצְהִיבִים עָלָיו. \u0010g6\u0011 וְכָל הַנִּכָּר לָרַבִּים, רַבִּים מִתְעַסְקִין בּוֹ; וְכָל שֶׁאֵינוֹ נִכָּר לָרַבִּים, אֵין רַבִּים חַיָּבִים לְהִתְעַסֵק בּוֹ. \u0010g7\u0011\nתִּינוֹק שֶׁמֵּת \u0010y6\u0011 קֹדֶם שֶׁנִּמּוֹל, מוֹהֲלִין אוֹתוֹ עַל קִבְרוֹ, בְּלֹא בְּרָכָה, וְקוֹרִין לוֹ שֵׁם. \u0010g8\u0011 \u0010r1\u0011\nאֵין מוֹצִיאִין מֵת בְּמִטָּה, אֶלָּא אִם כֵּן הָיָה רֹאשׁוֹ וְרֻבּוֹ קַיָּם.",{"g":["\u0003ברייתא מ\"ק דף כ\"ז ע\"א:\u0004 ","\u0003מעובדא כי נח נפשיה דרב הונא שם דף כ\"ה ע\"א:\u0004 ","שם:","ברייתא שם דף כ\"ד ע\"א וכת\"ק:\n(°) פי' רש\"י כשחוזרין מבית הקברות עוברים לפני האבל בשורה וכל אחד אומר לו תתנחם וברכת אבלים ברכה שאומרים ברחבה ותנחומי אבלים שהולכים כל שבעה לביתו לנחמו:","\u0003שם בברייתא וכדמפרש רבי יהודה שם:\u0004 ","לשון הרמב\"ם בפי\"ב מהלכות אבל מברייתא דרשב\"ג שם:\n(°) פירוש מרגישין ומצטערין ערוך:","\u0003שם ומדברי (רבי אלי) [ראב\"ע] שם:\u0004 ","\u0003ציינתיו לעיל סוף סי' רס\"ג:\u0004 ","\u0003ברייתא באבל רבתי וכת\"ק:\u0004 "],"t":["\u0003מטתו. \u0004 אבל לפניו ע\"ג קרקע או ספסל משמע בטור לעיל סימן שמ\"ד מתשובת רב האי שמותר וכ\"כ בפרישה עד כאן לשון הש\"ך:","\u0003בחיק. \u0004 וכתב בא\"ז דאם רצו להוציאו במטה הרשות בידן:"],"r":["\u0003ואפילו אי כו'. \u0004תוס' שם ד\"ה ואין כו':","\u0003(ליקוט) אין מוציאין. \u0004א\"ר ספי\"ב (ע\"כ):"]}],["עִיר שֶׁיֵּשׁ בָּהּ שְׁנֵי מֵתִים, מוֹצִיאִין \u0010y0\u0011 אֶת הָרִאשׁוֹן וְאַחַר כָּךְ מוֹצִיאִין הַשֵּׁנִי. \u0010y1\u0011 \u0010c0\u0011 וְאִם הָיוּ מְלִינִים הָרִאשׁוֹן, מוֹצִיאִין הַשֵּׁנִי. חָכָם וְתַלְמִיד חָכָם, מוֹצִיאִין הֶחָכָם. תַּלְמִיד חָכָם וְעַם הָאָרֶץ, מוֹצִיאִין תַּלְמִיד חָכָם. אִישׁ וְאִשָּׁה, מוֹצִיאִין הָאִשָּׁה, מִפְּנֵי שֶׁקְּרוֹבָה לְבֵית הַנִּוּוּל. הוֹצִיאוּ הָרִאשׁוֹן וּקְבָרוּהוּ, \u0010y2\u0011 אֵין עוֹמְדִין עָלָיו בְּשׁוּרָה, וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְלֹא תַּנְחוּמֵי אֲבֵלִים, עַד שֶׁיּוֹצִיאוּ הַשֵּׁנִי. \u0010y3\u0011 הוֹצִיאוּ הַשֵּׁנִי וּקְבָרוּהוּ, בָּאִים וְעוֹמְדִים בְּשׁוּרָה, מְנַחֲמִים וּפוֹטְרִים אֶת הָרַבִּים; \u0010y4\u0011 וְאֵין מְנַחֲמִים שְׁנֵי אֲבֵלִים כְּאֶחָד, אֶלָּא אִם כֵּן הָיָה כְּבוֹדָם שָׁוֶה וְקִלּוּסָן שָׁוֶה.",["\u0003את הראשון. \u0004היינו אותו שמת ראשון:","\u0003ואם היו מלינין כו'. \u0004כלומר אם רוצים להלין הראשון לכבודו כדלקמן סי' שנ\"ז מוציאין את השני דהא בלא\"ה לא יוציאו עכשיו הראשון:","\u0003אין עומדין עליו כו'. \u0004כדי שלא לעכב קבורת השני:","\u0003הוציאו השני וקברוהו. \u0004(דאין עומדין) [באין ועומדין] בשורה על הא' והשני כאחד:","\u0003ואין מנחמין שני אבלים. \u0004אלא מנחמין אותן בזה אחר זה או נחלקים לשתי כתות:"],["\u0003ואם היו מלינים הראשון. \u0004פירוש שרוצים להלין הראשון להמתין על קרוביו או שאר צרכיו אין להלין גם השני בשבילו."],"\u0010g0\u0011 \u0010r0\u0011 עִיר שֶׁיֵּשׁ בָּהּ שְׁנֵי מֵתִים, מוֹצִיאִין \u0010y0\u0011 אֶת \u0010t0\u0011 הָרִאשׁוֹן וְאַחַר כָּךְ מוֹצִיאִין הַשֵּׁנִי. \u0010y1\u0011 \u0010c0\u0011 וְאִם הָיוּ מְלִינִים הָרִאשׁוֹן, מוֹצִיאִין הַשֵּׁנִי. חָכָם וְתַלְמִיד חָכָם, מוֹצִיאִין הֶחָכָם. תַּלְמִיד חָכָם וְעַם הָאָרֶץ, מוֹצִיאִין תַּלְמִיד חָכָם. אִישׁ וְאִשָּׁה, מוֹצִיאִין הָאִשָּׁה, מִפְּנֵי שֶׁקְּרוֹבָה לְבֵית הַנִּוּוּל. הוֹצִיאוּ הָרִאשׁוֹן וּקְבָרוּהוּ, \u0010y2\u0011 אֵין עוֹמְדִין עָלָיו בְּשׁוּרָה, וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְלֹא תַּנְחוּמֵי אֲבֵלִים, עַד \u0010t1\u0011 שֶׁיּוֹצִיאוּ הַשֵּׁנִי. \u0010y3\u0011 הוֹצִיאוּ הַשֵּׁנִי וּקְבָרוּהוּ, בָּאִים וְעוֹמְדִים בְּשׁוּרָה, מְנַחֲמִים וּפוֹטְרִים אֶת הָרַבִּים; \u0010y4\u0011 וְאֵין מְנַחֲמִים שְׁנֵי אֲבֵלִים כְּאֶחָד, אֶלָּא אִם כֵּן הָיָה כְּבוֹדָם שָׁוֶה וְקִלּוּסָן שָׁוֶה.",{"g":["ברייתא באבל רבתי:\n(°) כלומר אם רוצים להלין הראשון לכבודו מוציאין את השני דהא בלאו הכי לא יוציאו עכשיו הראשון. שפתי כהן:\n(°) פירוש אלא מנחמי' את זה וחוזרים ומנחמין את חבירו או נחלקים לשתי כתות כת זו מנחמת את זה והשניה לזה:"],"t":["\u0003הראשון. \u0004 היינו אותו שמת ראשון. ש\"ך:","\u0003שיוציאו. \u0004 כדי שלא לעכב קבורת השני ש\"ך:"],"r":["\u0003(ליקוט) עיר כו'. \u0004א\"ר רפי\"א: הוציאו כו' ואין כו'. שם (ע\"כ):\n\u0003(ליקוט) עיר כו' \u0004עד סוף הסימן ערא\"ש פ\"ג דמ\"ק סי' קכ\"ט (ע\"כ):"]}],["\u0010y0\u0011 אֵין מַנִּיחִין מִטָּה שֶׁל אִשָּׁה בָּרְחוֹב, מִפְּנֵי הַכָּבוֹד. \u0010y1\u0011 \u0010c0\u0011 \u0005וְאֵין עוֹלִין בְּחֶבֶר עִיר עַל הָאִשָּׁה (טוּר)\u0006.",["\u0003אין מניחין כו'. \u0004מפני שקרובה לינוול:","\u0003ואין עולין כו'. \u0004שאין כבוד לחכם שמנהיג העיר שכל העיר נוהגין ע\"פ צוויו שיהא עולה באשה כשנושאין אותה לקבורה:"],["\u0003ואין עולין בחבר עיר. \u0004בסימן רנ\"ו כתב הטור יש בעיר חבר עיר פירוש אדם גדול ובברכות אמרינן ר' יהודה אומר אין מתפללין מוספין אלא בחבר עיר והיינו צבור ואיך שיהיה פירושו כאן מ\"מ לא בא למעט באשה אלא שאין עומדין בחבורה ברחובה של עיר לענין הנזכר בטור בסימן שע\"ז אבל לענין ללוותה פשיטא שאין חלוק בין אשה לאיש וכמ\"ש סי' שד\"מ סעיף ב' כנ\"ל פשוט וכן משמע בפרישה:"],"\u0010y0\u0011 \u0010g0\u0011 \u0010r0\u0011 אֵין מַנִּיחִין מִטָּה שֶׁל אִשָּׁה בָּרְחוֹב, מִפְּנֵי הַכָּבוֹד. \u0010y1\u0011 \u0010c0\u0011 \u0010r1\u0011 \u0005וְאֵין עוֹלִין \u0010t0\u0011 בְּחֶבֶר עִיר עַל הָאִשָּׁה \u0010g1\u0011 (טוּר)\u0006.",{"g":["משנה מ\"ק דף כ\"ז ע\"א וכרבי אלעזר שם בגמ' דף כ\"ח ע\"א הסכמת הפוסקים:\n(°) הש\"ך פי' לפי שאינו כבוד לחכם ללוות אשה והט\"ז פירשו כמו חברת רוב עם ומשום ניוול:","\u0003מברייתא באבל רבתי פרק י\"א:\u0004 "],"t":["\u0003בחבר. \u0004 כ' הט\"ז בסימן רנ\"ה כ' הטור יש בעיר חבר עיר פירוש אדם גדול. ובברכות אמרינן ר\"י אומר אין מתפללין מוספין אלא בחבר עיר והיינו צבור ואיך שיהיה פירושו כאן מ\"מ לא בא למעט באשה אלא שאין עומדין בחבורה ברחובה של עיר \u0005(ר\"ל בחבר עיר הוא בחבר רוב עם ומשום ניוול ע\"ש)\u0006 אבל לענין ללוותה פשיטא שאין חילוק בין איש לאשה עכ\"ל:"],"r":["\u0003(ליקוט) אין מניחין כו'. \u0004כר\"א שם וכן תניא בא\"ר פי\"ב להדיא (ע\"כ):","\u0003(ליקוט) ואין עולין כו'. \u0004א\"ר פי\"א (ע\"כ):\n\u0003(ליקוט) ואין כו'. \u0004ערא\"ש פ\"ג דמ\"ק סי' קל\"א (ע\"כ):"]}],["מֵת שֶׁלֹּא הָיָה לוֹ צָרְכֵי קְבוּרָה, וְגָבוּ לוֹ וְהוֹתִירוּ, אִם כְּשֶׁגָּבוּ \u0010y0\u0011 יַחְדָּו לְצָרְכֵי זֶה הַמֵּת, \u0010c0\u0011 יִנָּתְנוּ לְיוֹרְשָׁיו; וְאִם לָאו, יַעֲשׂוּ מֵהֶם צָרְכֵי מֵתִים אֲחֵרִים.",["\u0003יחדו לצרכי זה המת.\u0004 ל\"ש מעות או שאר דברים ינתנו ליורשיו לא משום דקני ליה זה המת בגביי' בעלמא דהא קי\"ל הזמנה לאו מלתא היא אלא משום דזילותא ה\"ל למת זה בגבייה ואחיל לי' זילותא ליורשיו וע\"ל סי' רנ\"ג ס\"ו:"],["\u0003ינתנו ליורשיו. \u0004אע\"פ דהזמנה לאו מילתא היא מ\"מ כיון דהוה ליה זילותא לגביה אחולי אחליה לגבי יורשיו כן איתא פרק נגמר הדין:"],"\u0010g0\u0011 מֵת שֶׁלֹּא הָיָה לוֹ צָרְכֵי קְבוּרָה, וְגָבוּ לוֹ וְהוֹתִירוּ, אִם כְּשֶׁגָּבוּ \u0010y0\u0011 \u0010t0\u0011 יַחְדָּו לְצָרְכֵי זֶה הַמֵּת, \u0010c0\u0011 יִנָּתְנוּ לְיוֹרְשָׁיו; וְאִם לָאו, יַעֲשׂוּ מֵהֶם צָרְכֵי מֵתִים אֲחֵרִים.",{"g":["משנה סוף פרק ב' דשקלים ופי' הרמב\"ן אע\"ג דהזמנה לאו מילתא היא אלא משום דזילותא ה\"ל לגביה ואחולי אחיל זילותיה ליורשים וכן פירש בגמרא דסנהדרין דף מ\"ח ע\"א:"],"t":["\u0003יחדו. \u0004 ל\"ש מעות או שאר דברים ינתנו ליורשיו ולא משום דקניה ליה זה המת בגבייה בעלמא אלא משום דזילותא הוא אחיל ליה ליורשיו וע\"ל סימן רנ\"ג ס\"ו:"]}],["אָסוּר לְהָלִין הַמֵּת, אֶלָּא אִם כֵּן הֵלִינוּ לִכְבוֹדוֹ, \u0010c0\u0011 לְהָבִיא לוֹ אָרוֹן וְתַכְרִיכִין אוֹ מְקוֹנְנוֹת, אוֹ כְּדֵי שֶׁיָּבֹאוּ קְרוֹבִים אוֹ לְהַשְׁמִיעַ עֲיָרוֹת.\nכָּל הַמֵּתִים, הַמְמַהֵר לְהוֹצִיא מִטָּתוֹ \u0010y0\u0011 הֲרֵי זֶה מְשֻׁבָּח. אֲבָל עַל אָבִיו וְעַל אִמּוֹ, הֲרֵי זֶה מְגֻנֶּה, אֶלָּא אִם כֵּן הָיָה עֶרֶב שַׁבָּת אוֹ עֶרֶב יוֹם טוֹב, אוֹ שֶׁהָיוּ גְּשָׁמִים מְזַלְּפִים עַל מִטָּתוֹ.",["\u0003ה\"ז משובח. \u0004לפי שאין דרך להספיד ולהתאבל עליהם הרבה הלכך יותר כבוד להם כשנקברים במהרה משיעמדו הרבה ולא יספידו' אבל על אביו ואמו שחייב להספידם ולקונן עליהם הרבה הממהר להוציא הרי זה מגונה:"],["\u0003להביא לו ארון ותכריכין. \u0004וה\"ה להמתין על קרוביו. כן כתב רש\"ל:"],"\u0010g0\u0011 אָסוּר לְהָלִין הַמֵּת, אֶלָּא אִם כֵּן הֵלִינוּ לִכְבוֹדוֹ, \u0010c0\u0011 לְהָבִיא לוֹ אָרוֹן וְתַכְרִיכִין אוֹ מְקוֹנְנוֹת, \u0010g1\u0011 \u0010r0\u0011 אוֹ כְּדֵי שֶׁיָּבֹאוּ קְרוֹבִים אוֹ לְהַשְׁמִיעַ \u0010g2\u0011 עֲיָרוֹת.\nכָּל הַמֵּתִים, הַמְמַהֵר לְהוֹצִיא מִטָּתוֹ \u0010y0\u0011 הֲרֵי זֶה \u0010t0\u0011 מְשֻׁבָּח. אֲבָל עַל אָבִיו וְעַל אִמּוֹ, הֲרֵי זֶה מְגֻנֶּה, אֶלָּא אִם כֵּן הָיָה עֶרֶב שַׁבָּת אוֹ עֶרֶב \u0010r1\u0011 יוֹם טוֹב, אוֹ שֶׁהָיוּ גְּשָׁמִים מְזַלְּפִים עַל מִטָּתוֹ.",{"g":["משנה סנהדרין דף מ\"ו ע\"א:\n[א] ברייתא שם מ\"ז ע\"א:","ברייתא באבל רבתי:\n[ב] [ברייתא דסנהדרין שם]:","\u0003ברייתא מ\"ק דף כ\"ב ע\"א ורמב\"ן ורא\"ש:\u0004 "],"t":["\u0003משובח. \u0004 לפי שאין דרך להספיד ולהתאבל עליהם הרבה הלכך יותר כבוד להם כשנקברים במהרה \u0005(משיעמדו הרבה ולא יספידום)\u0006 אבל על אביו ואמו שחייב להספידם ולקונן עליהם הרבה הממהר להוציא ה\"ז מגונה. עכ\"ל הש\"ך:"],"r":["\u0003(ליקוט) או כדי כו'. \u0004א\"ר ריש פי\"א מפני שאמרו כל המלין כו' (ע\"כ):","\u0003(ליקוט) או שהיו גשמים כו'. \u0004א\"ר פ\"ט (ע\"כ):\n\u0003(ליקוט) סעיף א' וסעיף ב' או כו' \u0004או כו' ע\"ש \u0005(ברא\"ש פ\"ג דמ\"ק) \u0006סי' פ\"ח (ע\"כ):"]}],["נוֹשְׂאֵי הַמִּטָּה, וְחִלּוּפֵיהֶן, וְחִלּוּפֵי חִלּוּפֵיהֶן, בֵּין אוֹתָם שֶׁהֵם לִפְנֵי הַמִּטָּה בֵּין אוֹתָם שֶׁל אַחֲרֶיהָ, מֵאַחַר שֶׁלַּמִּטָּה צֹרֶךְ בָּהֶם, \u0010y0\u0011 פְּטוּרִים \u0005מִקְּרִיאַת שָׁמַע;\u0006 וּשְׁאָר הַמְּלַוִּין אֶת הַמֵּת, שֶׁאֵין לַמִּטָּה צֹרֶךְ בָּהֶם, חַיָּבִים. \u0005וְעַיֵּן בא\"ח סִימָן ע\"ב.\u0006 \u0010y1\u0011\nאֵין מוֹצִיאִין אֶת הַמֵּת סָמוּךְ לִקְרִיאַת שְׁמַע, כָּל שֶׁאֵין שְׁהוּת לְהוֹצִיאוֹ לְקִבְרוֹ קֹדֶם שֶׁיַּגִּיעַ זְמַן קְרִיאַת שְׁמַע; וְאִם הִתְחִילוּ לְהוֹצִיאוֹ, אֵין מַפְסִיקִין כְּדֵי לִקְרוֹת. \u0005הַגָּה: וְיֵשׁ לְהַמְתִּין מִלְּקָבְרוֹ עַד שֶׁיּוּכְלוּ לְשַׁעֵר שֶׁכְּבָר הִתְפַּלְּלוּ רֹב הַקָּהָל; וְאֵין חִלּוּק בָּזֶה בֵּין קְרִיאַת שְׁמַע שֶׁל שַׁחֲרִית לִקְרִיאַת שְׁמַע שֶׁל עַרְבִית. וְיֵשׁ מְקִלִּין בְּשֶׁל עַרְבִית, הוֹאִיל וּזְמַנָּהּ כָּל הַלַּיְלָה (מְבֹאָר בא\"ח סִימָן ע\"ב)\u0006. \u0010y2\u0011 \u0010c0\u0011\nבְּמָקוֹם שֶׁיֵּשׁ כַּתָּפִים מְיֻחָדִים לָשֵׂאת אֶת הַמִּטָּה, אֲסוּרִים בִּנְעִילַת הַסַנְדָּל, שֶׁמָּא יַפְסִיק סַנְדָּלוֹ שֶׁל אֶחָד מֵהֶם, וְנִמְצָא מִתְעַכֵּב מֵהַמִּצְוָה. \u0005הַגָּה: יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁהָאֲבֵלִים יוֹצְאִים רִאשׁוֹן מִן הַבַּיִת, וְהַקְּרוֹבִים וְהַמִּטָּה אַחֲרֵיהֶם, וְהָרְחוֹקִים נוֹתְנִין הַמֵּת עַל הַמִּטָּה, וְלוֹקְחִים הָאֲבֵלִים וְהַקְּרוֹבִים הַמִּטָּה עַל כִּתְפֵיהֶם, וְאַחַר כָּךְ שְׁאָר הָעָם (כָּל בּוֹ)\u0006. יֵשׁ אוֹמְרִים כְּשֶׁמַּגִּיעִים עִם הַמֵּת לַקְּבָרוֹת, \u0010y3\u0011 מַעֲמִידִים אוֹתוֹ כָּל ד' אַמּוֹת קֹדֶם שֶׁנִּקְבַּר \u0005(שָׁם וּב\"ז)\u0006 ; וְכֵן נָהֲגוּ הָאִדָּנָא לְהַעֲמִידוֹ ב' ג' פְּעָמִים קֹדֶם שֶׁאוֹמְרִים עָלָיו צִדּוּק הַדִּין, וּבְיָמִים שֶׁאֵין אוֹמְרִים צִדּוּק הַדִּין אֵין צָרִיךְ לְהַעֲמִיד אוֹתוֹ \u0005(מ\"כ בְּשֵׁם מהרי\"ל)\u0006.",["\u0003פטורים מק\"ש. \u0004שעוסק במצוה פטור מהמצוה:","\u0003אין מוציאין כו'. \u0004שלא להפקיע חובת קריאת שמע:","\u0003במקום שיש כו'. \u0004לאפוקי האידנא שאין לנו כתפים מיוחדי' אלא הכל מסייעים לישא לית לן בה:","\u0003מעמידים אותו כו'. \u0004כתב העט\"ז וטעם ההעמדה שמעתי כדי להבריח רוחות הטומאה הרוצים להחזיק בו שלא להכניס עמו לקבורה כי כשמעמידים אותו הולכים להם ובימים שא\"א בהם צדוק הדין א\"צ להעמיד אותו כי ביום זה אין כל כך רוחות טמאות מצויות:"],["\u0003במקום שיש כתפים כו'. \u0004נ\"ל שלא יפה עושים באיזה קהילות שעושין להם חבורה של נושאי המטה ואין מניחין אחרים לשאת דא\"כ היו צריכים לילך יחף והם אין עושין כן:"],"\u0010g0\u0011 נוֹשְׂאֵי הַמִּטָּה, וְחִלּוּפֵיהֶן, וְחִלּוּפֵי חִלּוּפֵיהֶן, בֵּין אוֹתָם שֶׁהֵם לִפְנֵי הַמִּטָּה בֵּין אוֹתָם שֶׁל אַחֲרֶיהָ, מֵאַחַר שֶׁלַּמִּטָּה צֹרֶךְ בָּהֶם, \u0010y0\u0011 \u0010t0\u0011 פְּטוּרִים \u0005מִקְּרִיאַת שָׁמַע;\u0006 וּשְׁאָר הַמְּלַוִּין אֶת הַמֵּת, שֶׁאֵין לַמִּטָּה צֹרֶךְ בָּהֶם, חַיָּבִים. \u0005וְעַיֵּן בא\"ח סִימָן ע\"ב.\u0006 \u0010y1\u0011 \u0010g1\u0011\nאֵין מוֹצִיאִין אֶת הַמֵּת סָמוּךְ \u0010r0\u0011 לִקְרִיאַת שְׁמַע, כָּל שֶׁאֵין שְׁהוּת לְהוֹצִיאוֹ לְקִבְרוֹ קֹדֶם שֶׁיַּגִּיעַ זְמַן קְרִיאַת שְׁמַע; וְאִם הִתְחִילוּ לְהוֹצִיאוֹ, אֵין מַפְסִיקִין כְּדֵי לִקְרוֹת. \u0005הַגָּה: וְיֵשׁ לְהַמְתִּין מִלְּקָבְרוֹ עַד שֶׁיּוּכְלוּ לְשַׁעֵר שֶׁכְּבָר הִתְפַּלְּלוּ רֹב הַקָּהָל; וְאֵין חִלּוּק בָּזֶה בֵּין קְרִיאַת שְׁמַע שֶׁל שַׁחֲרִית לִקְרִיאַת שְׁמַע שֶׁל עַרְבִית. וְיֵשׁ מְקִלִּין בְּשֶׁל עַרְבִית, הוֹאִיל וּזְמַנָּהּ כָּל הַלַּיְלָה (מְבֹאָר בא\"ח סִימָן ע\"ב)\u0006. \u0010y2\u0011 \u0010c0\u0011 \u0010g2\u0011\nבְּמָקוֹם שֶׁיֵּשׁ כַּתָּפִים \u0010t1\u0011 מְיֻחָדִים לָשֵׂאת אֶת הַמִּטָּה, אֲסוּרִים בִּנְעִילַת הַסַנְדָּל, שֶׁמָּא יַפְסִיק סַנְדָּלוֹ שֶׁל אֶחָד מֵהֶם, וְנִמְצָא מִתְעַכֵּב מֵהַמִּצְוָה. \u0005הַגָּה: \u0010r1\u0011 יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁהָאֲבֵלִים יוֹצְאִים רִאשׁוֹן מִן הַבַּיִת, וְהַקְּרוֹבִים וְהַמִּטָּה אַחֲרֵיהֶם, וְהָרְחוֹקִים נוֹתְנִין הַמֵּת עַל הַמִּטָּה, וְלוֹקְחִים הָאֲבֵלִים וְהַקְּרוֹבִים הַמִּטָּה עַל כִּתְפֵיהֶם, וְאַחַר כָּךְ שְׁאָר הָעָם (כָּל בּוֹ)\u0006. יֵשׁ אוֹמְרִים כְּשֶׁמַּגִּיעִים עִם הַמֵּת לַקְּבָרוֹת, \u0010y3\u0011 \u0010t2\u0011 מַעֲמִידִים אוֹתוֹ כָּל ד' אַמּוֹת קֹדֶם שֶׁנִּקְבַּר \u0005(שָׁם וּב\"ז)\u0006 ; וְכֵן נָהֲגוּ הָאִדָּנָא לְהַעֲמִידוֹ ב' ג' פְּעָמִים קֹדֶם שֶׁאוֹמְרִים עָלָיו צִדּוּק הַדִּין, וּבְיָמִים שֶׁאֵין אוֹמְרִים צִדּוּק הַדִּין אֵין צָרִיךְ לְהַעֲמִיד אוֹתוֹ \u0005(מ\"כ בְּשֵׁם מהרי\"ל)\u0006.",{"g":["\u0003ציינתיו בא\"ח סימן ע\"ב:\u0004 ","\u0003ג\"ז שם:\u0004 ","\u0003טור בשם ירושלמי וכפי' הב\"י דהאידנא שאין לנו כתפים מיוחדים אלא הכל מסייעים לית לן בה:\u0004 "],"t":["\u0003פטורים. \u0004 שהעוסק במצוה פטור מהמצוה. ש\"ך:","\u0003מיוחדים. \u0004 כ' הט\"ז נ\"ל שלא יפה עושים באיזה קהלות שעושין להם חבורה של נושאי המטה ואין מניחים אחרים לשאת דא\"כ היו צריכין לילך יחף והם אין עושין כך עכ\"ל:","\u0003מעמידים. \u0004 כ' הלבוש וטעם ההעמדה שמעתי כדי להבריח רוחות הטומאה הרוצים להחזיק בו שלא להכניס עמו לקבורה כי כשמעמידים אותו הולכים להם וביום שא\"א בהם צדוק הדין אין צריך להעמיד אותו כי ביום זה אין כ\"כ רוחות טמאות מצויות עכ\"ל:"],"r":["\u0003(ליקוט) כל שאין כו'. \u0004א\"ר פ\"י אא\"כ הקדימו כו' (ע\"כ):\n\u0003(ליקוט) כל שאין כו'. \u0004כמ\"ש בירושלמי \u0005(פ\"ג דברכות ופ\"ב דסנהדרין) \u0006תני אין מוציאין את המת סמוך לק\"ש אא\"כ הקדימו שעה א' כדי שיקראו ויתפללו והא תנינן קברו את המת וחזרו אם יכולין להתחיל כו' תפתר באילין דהווין סברין דאית בה עונה ולית בה עונה (ע\"כ):","\u0003יש מקומות כו'. \u0004תוספתא \u0005(פ\"ג דפסחים וכגירסת הרמב\"ן) \u0006מקום שנהגו להיות אבלים הולכין לפני המטה הולכין כו' והביאו הרמב\"ן בתה\"א וב\"י בס\"ס שנ\"ט ועבה\"ג:"]}],["\u0010y0\u0011 מָקוֹם שֶׁנָּהֲגוּ לָצֵאת נָשִׁים לִפְנֵי הַמִּטָּה, יוֹצְאוֹת. מָקוֹם שֶׁנָּהֲגוּ לָצֵאת לְאַחַר הַמִּטָּה, יוֹצְאוֹת. וְעַכְשָׁו נָהֲגוּ שֶׁאֵין יוֹצְאוֹת אֶלָּא לְאַחַר הַמִּטָּה, וְאֵין לְשַׁנּוֹת. \u0010y1\u0011\nיֵשׁ לִמְנֹעַ מִלָּצֵאת נָשִׁים לְבֵית הַקְּבָרוֹת אַחַר הַמִּטָּה.",["\u0003מקום שנהגו כו'. \u0004כתב הרמב\"ן והטור מתוספתא מקומות שנהגו להיות אבלים הולכים לפני המטה הולכים וכתב הב\"ח האידנא ליכא מנהג בהליכת אבלים אלא הולכים בין שאר העם:","\u0003יש למנוע כו'. \u0004כלומר שיצאו אחר המטה וכדלעיל סעיף א' אבל יש למנוע שלא יצאו לבית הקברות אחר המטה שאם עושים כן גורמים רעה לעולם ח\"ו:"],[],"\u0010y0\u0011 \u0010g0\u0011 מָקוֹם שֶׁנָּהֲגוּ לָצֵאת נָשִׁים \u0010g1\u0011 לִפְנֵי הַמִּטָּה, יוֹצְאוֹת. מָקוֹם שֶׁנָּהֲגוּ לָצֵאת \u0010g2\u0011 לְאַחַר הַמִּטָּה, יוֹצְאוֹת. וְעַכְשָׁו נָהֲגוּ שֶׁאֵין יוֹצְאוֹת אֶלָּא לְאַחַר הַמִּטָּה, וְאֵין לְשַׁנּוֹת. \u0010y1\u0011 \u0010g3\u0011\nיֵשׁ \u0010t0\u0011 לִמְנֹעַ מִלָּצֵאת נָשִׁים לְבֵית הַקְּבָרוֹת אַחַר הַמִּטָּה.",{"g":["\u0003ברייתא סנהדרין דף כ' ע\"א:\u0004 ","\u0003בירושלמי מפרש שהן גרמו מיתה לעולם:\u0004 ","\u0003שם מפני כבודן של בנות ישראל שלא יהיו מביטין בנשים:\u0004 ","\u0003בית יוסף בשם ספר הזוהר פרשת ויקהל שאם יוצאות גורמות רעה לעולם:\u0004 "],"t":["\u0003למנוע. \u0004 כלומר אף על פי שכ' בס\"א שנהגו לצאת אחר המטה ואין לשנות מ\"מ לא ילכו לבית הקברות אחר המטה שאם עושים כן גורמים רעות לעולם ח\"ו עכ\"ל הש\"ך:"]}],["אִם פָּגְעוּ מֵת וְכַלָּה זֶה בָּזֶה, \u0010y0\u0011 מַעֲבִירִין הַמֵּת מִלִּפְנֵי הַכַּלָּה; וְכֵן אִם אֵין בָּעִיר כְּדֵי לָזֶה וְלָזֶה, מַקְדִּימִין וּמַכְנִיסִין הַכַּלָּה לַחֻפָּה, וְאַחַר כָּךְ קוֹבְרִים הַמֵּת. אֲבָל אַחַר שֶׁנִּכְנְסָה לַחֻפָּה, וְיֵשׁ לְפָנָיו לְנַחֵם אָבֵל וּלְשַׂמֵּחַ חָתָן, תַּנְחוּמֵי הָאֵבֶל קוֹדֵם. \u0010y1\u0011 וְכֵן הַבְרָאַת הָאָבֵל קוֹדֵם לְמִשְׁתֶּה שֶׁל חָתָן. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁיֵּשׁ בְּיָדוֹ סִפּוּק כְּדֵי שְׁנֵיהֶם, אֲבָל אִם אֵין בְּיָדוֹ כְּדֵי שְׁנֵיהֶם, מִשְׁתֵּה הֶחָתָן קוֹדֵם. \u0005חָתָן וְאָבֵל בב\"ה, יוֹצֵא הֶחָתָן עִם שׁוֹשְׁבִינָיו תְּחִלָּה, וְאַחַר כָּךְ הָאָבֵל, וְהַמְנַחֲמִים וְכֵן הַקְּרוּאִים שֶׁלָּהֶם אוֹכְלִים עִם הֶחָתָן כְּשֶׁיִּרְצוּ, וְלֹא עִם הָאָבֵל (בֵּית יוֹסֵף בְּשֵׁם הַגָּהוֹת מַיְמוֹנִי פ\"ד)\u0006. הַמֵּת וְהַמִּילָה, מִילָה קוֹדֶמֶת; וְאִם הוּא מֵת מִצְוָה, \u0010y2\u0011 \u0010c0\u0011 מֵת מִצְוָה קוֹדֵם.",["\u0003מעבירין את המת מלפני הכלה. \u0004להכניסה לחופה דלעולם מצות החיים קודמת למצות המתים ועיקר מצות הכלה להכניסה לחופה משום לא תוהו בראה וגו':","\u0003וכן הבראת האבל קודם כו'. \u0004מפני שהחתן אוכל משלו ומאכיל אחרים והאבל אינו אוכל עד שיאכילוהו אחרים:","\u0003מת מצוה קודם כו'. \u0004אכל הסימן קאי שמת מצוה קודם לכל דבר שבתורה כדלקמן ר\"ס שע\"ד ועיין באו\"ח ס\"ס תרפ\"ז:"],["\u0003מת מצוה קודם. \u0004בטור סיים שהרי הוא דוחה תלמוד תורה ומקרא מגילה כו' והוא בגמ' הביאו הרא\"ש פ\"ב דכתובות וכ' שם אע\"ג דגם מת שאינו מצוה נמי דוחה ת\"ת כמ\"ש סי' שס\"א מ\"מ נקט מת מצוה משום שאר דברים שאמר שם בגמרא והטור נגרר אחר לשון הגמרא. ומת מצוה אמרינן בפ' האשה רבה דהיינו כל שקורא ואין אחרים עונין ופירשו התוספות בנזיר דף מ\"ג כלומר שאם המת יכול לקרות יש לו עונין קרובים אין זה מת מצוה ועיין לקמן סימן שע\"ד סעיף ג' שכתוב בענין אחר:"],"\u0010g0\u0011 אִם פָּגְעוּ מֵת וְכַלָּה זֶה בָּזֶה, \u0010y0\u0011 מַעֲבִירִין הַמֵּת מִלִּפְנֵי \u0010t0\u0011 הַכַּלָּה; \u0010g1\u0011 \u0010r0\u0011 וְכֵן אִם אֵין בָּעִיר כְּדֵי לָזֶה וְלָזֶה, מַקְדִּימִין וּמַכְנִיסִין הַכַּלָּה לַחֻפָּה, וְאַחַר כָּךְ קוֹבְרִים הַמֵּת. \u0010g2\u0011 אֲבָל אַחַר שֶׁנִּכְנְסָה לַחֻפָּה, וְיֵשׁ לְפָנָיו לְנַחֵם אָבֵל וּלְשַׂמֵּחַ חָתָן, תַּנְחוּמֵי הָאֵבֶל קוֹדֵם. \u0010y1\u0011 וְכֵן הַבְרָאַת הָאָבֵל \u0010t1\u0011 קוֹדֵם לְמִשְׁתֶּה שֶׁל חָתָן. \u0010g3\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁיֵּשׁ בְּיָדוֹ סִפּוּק כְּדֵי שְׁנֵיהֶם, אֲבָל אִם אֵין בְּיָדוֹ כְּדֵי שְׁנֵיהֶם, מִשְׁתֵּה הֶחָתָן קוֹדֵם. \u0005חָתָן וְאָבֵל בב\"ה, יוֹצֵא הֶחָתָן עִם שׁוֹשְׁבִינָיו תְּחִלָּה, וְאַחַר כָּךְ הָאָבֵל, וְהַמְנַחֲמִים וְכֵן הַקְּרוּאִים שֶׁלָּהֶם אוֹכְלִים עִם הֶחָתָן כְּשֶׁיִּרְצוּ, וְלֹא עִם הָאָבֵל (בֵּית יוֹסֵף בְּשֵׁם הַגָּהוֹת מַיְמוֹנִי פ\"ד)\u0006. \u0010g4\u0011 הַמֵּת וְהַמִּילָה, מִילָה קוֹדֶמֶת; \u0010g5\u0011 וְאִם הוּא מֵת מִצְוָה, \u0010y2\u0011 \u0010c0\u0011 מֵת מִצְוָה קוֹדֵם.",{"g":["\u0003ברייתא כתובות דף י\"ז ע\"א וכפירוש רש\"י שם:\u0004 ","\u0003טור וכ\"כ הרמב\"ן בסת\"ה:\u0004 ","\u0003שם בסת\"ה מברייתא דאבל רבתי:\u0004 ","\u0003שם בשם מכילתא אחריתא ומפרש שם שכבוד החיים קודם:\u0004 ","\u0003שם ושם:\u0004 ","בית יוסף וגם להכנסת כלה שהוא קודם לת\"ת ועבודה ומקרא מגילה ודוחה טומאה ונזיר ופסח ומילה ולא מצינו דבר קודם לו בכל התורה כולה:"],"t":["\u0003הכלה. \u0004 להכניסה לחופה דלעולם מצות החיים קודמת למצות המתים ועיקר מצות הכלה להכניסה לחופה משום לא תוהו בראה וגו' עד כאן לשון הש\"ך:","\u0003קודם. \u0004 מפני שהחתן אוכל משלו ומאכיל לאחרים והאבל אינו אוכל עד שיאכילוהו אחרים. ש\"ך:"],"r":["\u0003וכן כו' אבל כו'. \u0004בתה\"א הביא ברייתא המת והמילה מילה קודמת שזו מצוה לחיים וזו מצוה למתים המת והכלה כלה קודמת בית האבל ובית המשתה בית המשתה קודמת ואם יש לו פרנסה בית האבל קודם אבל וחתן אבל קודם מפני שהחתן אוכל ומאכיל אחרים והאבל אינו אוכל עד שיאכלוהו אחרים ועב\"י:\n\u0003(ליקוט) וכן אם אין כו'. \u0004א\"ר פי\"א: אבל אחר כו'. שם פי\"ב (ע\"כ):"]}],["\u0010y0\u0011 מְבַטְּלִים תַּלְמוּד תּוֹרָה לְהוֹצָאַת הַמֵּת. לְמָאן דְּמַתְנֵי לַאֲחֵרִים, אֵין לוֹ שִׁעוּר, אֲפִלּוּ יֵשׁ עִמּוֹ כַּמָּה אֲלָפִים מִתְבַּטֵּל בִּשְׁבִילוֹ. לְמָאן דְּקָרֵי וְתָנֵי, \u0010y1\u0011 דְּהַיְנוּ שֶׁקָּרָא וְשָׁנָה וַעֲדַיִן לֹא שָׁנָה לַתַּלְמִידִים, \u0010y2\u0011 אִם יֵשׁ ס' רִבּוֹא אֵין צָרִיךְ לְהִתְבַּטֵּל בִּשְׁבִילוֹ. לְמָאן דְּלֹא קָרֵי וְתָנֵי, כֵּיוָן שֶׁיֵּשׁ לוֹ מִי שֶׁיִּתְעַסֵק עִמּוֹ אֵין צָרִיךְ לְהִתְבַּטֵּל בִּשְׁבִילוֹ, \u0010y3\u0011 וְהוּא שֶׁיֵּשׁ שָׁם עֲשָׂרָה. \u0005וְיֵשׁ אוֹמְרִים דְּעַכְשָׁיו מִן הַסְּתָם מְבַטְּלִין, שֶׁאֵין לְךָ אֶחָד מִיִּשְׂרָאֵל בַּזְּמַן הַזֶּה שֶׁאֵינוֹ בַּמִּקְרָא אוֹ בַּמִּשְׁנָה. (בֵּית יוֹסֵף בְּשֵׁם הריטב\"א פ\"ב דִּכְתֻבּוֹת שכ\"כ בְּשֵׁם סמ\"ג)\u0006 וְאִשָּׁה, יֵשׁ אוֹמְרִים שֶׁדִּינָה כְּמָאן דְּקָרֵי וְתָנֵי; וְיֵשׁ אוֹמְרִים שֶׁדִּינָה כְּמָאן דְּלֹא קָרֵי וְתָנֵי, וְכֵן נָהֲגוּ בְּאִשָּׁה וְתִינוֹק \u0010y4\u0011 לְקֻלָּא. וְאֵין מְבַטְּלִין תַּלְמוּד תּוֹרָה לְמֵת, כְּשֶׁיֵּשׁ מִי שֶׁיִּתְעַסֵק עִמּוֹ כָּל צָרְכּוֹ, אֶלָּא עוֹסֵק בַּתּוֹרָה. \u0010c0\u0011 וְאֵינוֹ צָרִיךְ לָצֵאת וְלִרְאוֹת אִם יֵשׁ עִמּוֹ כָּל צָרְכּוֹ אִם לָאו, אֶלָּא כֵּיוָן שֶׁיֵּשׁ שָׁם מִי שֶׁיַּעֲשֶׂה מַעֲשֶׂה, תַּלְמוּד תּוֹרָה שֶׁלּוֹ קוֹדֵם. \u0010y5\u0011 וְתִינוֹקוֹת שֶׁל בֵּית רַבָּן אֵין מִתְבַּטְּלִין כְּלָל.\nבַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁמְּבַטְּלִין תַּלְמוּד תּוֹרָה, לְלַוּוֹתוֹ בִּשְׁעַת הוֹצָאָתוֹ; אֲבָל כָּל זְמַן שֶׁמֻּטָּל לְקָבְרוֹ, אֵין מְבַטְּלִין בִּשְׁבִילוֹ תַּלְמוּד תּוֹרָה, אֶלָּא אִם יֵשׁ חֲבוּרוֹת בָּעִיר שֶׁכָּל אַחַת מִתְעַסֶקֶת יוֹמָהּ, אוֹתָהּ שֶׁאֵינָהּ יוֹמָהּ מֻתֶּרֶת בֵּין בְּלִמּוּד בֵּין בִּשְׁאָר מְלָאכוֹת. וּבִשְׁעַת הוֹצָאָה, מְבַטְּלִין מִכָּל שְׁאָר מְלָאכוֹת וּבָאִים לְלַוּוֹתוֹ, אֲפִלּוּ אִי לֹא קָרֵי וְתָנֵי, דְּלֹא מְפַלְּגִינָן בֵּין לֹא קָרֵי וְתָנֵי אֶלָּא בְּבִטּוּל תַּלְמוּד תּוֹרָה, אֲבָל בִּשְׁאָר מְלָאכוֹת, אֲפִלּוּ אִי לֹא קָרֵי וְתָנֵי הַכֹּל בְּטֵלִים וּבָאִים לְלַוּוֹתוֹ. וְאִם אֵין חֲבוּרוֹת בָּעִיר, כָּל בַּעֲלֵי מְלָאכוֹת צְרִיכִים לְהִתְבַּטֵּל וּלְהִתְעַסֵק בּוֹ עַד שֶׁיִּקָּבֵר; אֲבָל מִתַּלְמוּד תּוֹרָה אֵין צְרִיכִים לְהִתְבַּטֵּל אֶלָּא בִּשְׁעַת הוֹצָאָתוֹ, כִּדְאַמְרָן.\nהָרוֹאֶה אֶת הַמֵּת וְאֵינוֹ מְלַוֵּהוּ, עוֹבֵר מִשּׁוּם לוֹעֵג לָרָשׁ \u0005(מִשְׁלֵי יז, ה)\u0006 וּבַר נִדּוּי הוּא, וּלְפָחוֹת יְלַוֶּנּוּ ד' אַמּוֹת.\nאֲפִלּוּ בְּמָקוֹם שֶׁאֵינוֹ צָרִיךְ לְלַוּוֹת אֶת הַמֵּת, \u0010c1\u0011 צָרִיךְ לַעֲמֹד מִפָּנָיו.\nאָרוֹן הָעוֹבֵר מִמָּקוֹם לְמָקוֹם, אִם שִׁלְדּוֹ קַיֶּמֶת, צְרִיכִין לְלַוּוֹתוֹ כְּמוֹ בִּשְׁעַת הוֹצָאַת הַמֵּת.",["\u0003מבטלין ת\"ת כו'. \u0004פירוש חובה לבטל כן הסכימו הפוסקים:","\u0003שקרא ושנה כו'. \u0004משמע תרווייהו בעינן אבל מלשון הריטב\"א שהביא ב\"י שאין לך אדם מישראל שאינו או במקרא או במשנה כו' משמע דקרא או שנה קאמרינן:","\u0003אם יש ס' רבוא כו'. \u0004דנטילתה כנתינתה מסיני מה נתינת התורה בסיני בס' רבוא אף נטילתה בס' רבוא:","\u0003והוא שיש עמו עשרה. \u0004כדי שיוכלו לומר קדיש וברכת אבלים:","\u0003ואין מבטלים ת\"ת למת כשיש כו'. \u0004הל' מגומגם אבל בטור ניחא דקאי אמאן דלא קרי ותני דסגי כשיש לו מי שיתעסקו עמו וקאמר דאם יש אנשים בעיר שיוכלו להתעסק עמו א\"צ לראות אם מתעסקים עמו דמסתמא מתעסקים עמו ות\"ת קודם אבל מאן דמתני דאין לו שיעור ודאי דלעולם צריך ללוותו וכן למאן דקרי ותני דצריך ששים רבוא ודאי מסתמא ליכא ששים רבוא וע\"כ גם דברי המחבר צריך לפרש כן ודו\"ק. כתב האגודה מה שרגילין לבטל תלמוד תורה כל זמן שיש מת בעיר הטעם פן יהיה צרכי המת נדחה כי כולם ילכו ללמוד ונ\"ל בקהלות שעשו כתות ויש אנשים מיוחדים המתעסקים בו אדם הלומד לש\"ש ואינו רגיל לטפל בהם יכול ללמוד ע\"כ ומביאו מהרש\"ל והדרישה והב\"ח כתב עליו ונראה דאפילו למאן דקרי ותני קאמר דיוכל ללמוד אבל למאן דמתני לאחרים דאין לו שיעור צריך לבטל אפי' עשו כתות דהא דתניא מבטלין ת\"ת להוצאת המת אין פירושו מותר לבטל אלא חובה קתני עכ\"ל ולא הבנתי דבריו דהא האגודה מיירי שלא בשעת הוצאתו דיוכל ללמוד אפילו למאן דמתני דדוקא בשעת הוצאתו צריך לבטל וכדלקמן סעיף ב':","\u0003ותינוקות של בית רבן אינן מתבטלין כלל. \u0004פי' אפי' להוצאת המת וטעמא כדכ' הטור שהרי אין מבטלין אותן אפי' לבנין בית הכנסת דלא כעט\"ז שכתב הטעם שהרי אינם מתעסקים עמו דהא אין מבטלין אותו אפילו להוצאת המת:"],["\u0003וא\"צ לצאת ולראות כו'. \u0004זה קאי אמאן דלא קרי ותני שא\"צ לראות אם יש שם מתעסקים כל צרכו כמ\"ש לפני זה ונראה דהדעה הזאת חולקת על מה שכתב רמ\"א דהאידנא מן הסתם מבטלין ואם כן לפי דברי רמ\"א יש לבטל גם בזה מ\"מ רב הלומד עם תלמידיו לא יבטל בשביל זה מן הסתם. נראה לי:","\u0003צריך לעמוד מפניו. \u0004פי' מפני העוסקים עמו שהם גומלי חסדים כן הוא בטור בשם ירושלמי דקאמר אלין דקיימי מקמי מיתא לא קיימי מקמי מיתא אלא מקמי אלין דגמלין לו חסד וקשה לי ממ\"ש בפרק אלו מגלחין דכשנשא רבי חגי ארונו של רב הונא למערתא דר' חייא ובניו א\"ל יהודא לחזקיה קום מדוכתיך דלאו אורח ארעא דקאים רב הונא בהדי דקאים כו' ש\"מ דקם מקמי מיתא וצריך לומר דהכא אמר מסתם אדם שאין ת\"ח ומ\"מ נ\"ל ללמוד דבכל דבר מצוה שאדם הולך ומתעסק בה יש לעמוד לפניו וכן משמע בפ\"ק דקידושין (דף ל\"ג) א\"ר יוסי בר אבין בוא וראה כמה חביבה מצוה בשעתה שהרי מפניהם עומדים בעלי אומניות ומפני תלמיד חכם אין עומדים משמע כל מצוה:"],"\u0010y0\u0011 \u0010g0\u0011 מְבַטְּלִים תַּלְמוּד תּוֹרָה לְהוֹצָאַת הַמֵּת. \u0010g1\u0011 לְמָאן דְּמַתְנֵי לַאֲחֵרִים, אֵין לוֹ שִׁעוּר, אֲפִלּוּ יֵשׁ עִמּוֹ כַּמָּה אֲלָפִים מִתְבַּטֵּל בִּשְׁבִילוֹ. לְמָאן דְּקָרֵי וְתָנֵי, \u0010y1\u0011 דְּהַיְנוּ שֶׁקָּרָא \u0010t0\u0011 וְשָׁנָה וַעֲדַיִן לֹא שָׁנָה לַתַּלְמִידִים, \u0010y2\u0011 אִם יֵשׁ ס' רִבּוֹא אֵין צָרִיךְ לְהִתְבַּטֵּל בִּשְׁבִילוֹ. \u0010g2\u0011 \u0010r0\u0011 לְמָאן דְּלֹא קָרֵי וְתָנֵי, כֵּיוָן שֶׁיֵּשׁ לוֹ מִי שֶׁיִּתְעַסֵק עִמּוֹ אֵין צָרִיךְ לְהִתְבַּטֵּל בִּשְׁבִילוֹ, \u0010y3\u0011 \u0010g3\u0011 וְהוּא שֶׁיֵּשׁ שָׁם עֲשָׂרָה. \u0005וְיֵשׁ אוֹמְרִים דְּעַכְשָׁיו מִן הַסְּתָם מְבַטְּלִין, שֶׁאֵין לְךָ אֶחָד מִיִּשְׂרָאֵל בַּזְּמַן הַזֶּה שֶׁאֵינוֹ בַּמִּקְרָא אוֹ בַּמִּשְׁנָה. (בֵּית יוֹסֵף בְּשֵׁם הריטב\"א פ\"ב דִּכְתֻבּוֹת שכ\"כ בְּשֵׁם סמ\"ג)\u0006 וְאִשָּׁה, יֵשׁ אוֹמְרִים שֶׁדִּינָה כְּמָאן דְּקָרֵי וְתָנֵי; \u0010g4\u0011 וְיֵשׁ אוֹמְרִים שֶׁדִּינָה כְּמָאן דְּלֹא קָרֵי וְתָנֵי, וְכֵן נָהֲגוּ בְּאִשָּׁה וְתִינוֹק \u0010y4\u0011 \u0010g5\u0011 \u0010r1\u0011 לְקֻלָּא. וְאֵין מְבַטְּלִין תַּלְמוּד תּוֹרָה לְמֵת, כְּשֶׁיֵּשׁ מִי שֶׁיִּתְעַסֵק עִמּוֹ כָּל צָרְכּוֹ, אֶלָּא עוֹסֵק בַּתּוֹרָה. \u0010c0\u0011 וְאֵינוֹ צָרִיךְ \u0010t1\u0011 לָצֵאת וְלִרְאוֹת אִם יֵשׁ עִמּוֹ כָּל צָרְכּוֹ אִם לָאו, אֶלָּא כֵּיוָן שֶׁיֵּשׁ שָׁם מִי שֶׁיַּעֲשֶׂה מַעֲשֶׂה, תַּלְמוּד תּוֹרָה שֶׁלּוֹ קוֹדֵם. \u0010y5\u0011 \u0010r2\u0011 וְתִינוֹקוֹת שֶׁל בֵּית רַבָּן אֵין מִתְבַּטְּלִין כְּלָל. \u0010g6\u0011 \u0010r3\u0011\nבַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁמְּבַטְּלִין תַּלְמוּד תּוֹרָה, לְלַוּוֹתוֹ בִּשְׁעַת הוֹצָאָתוֹ; אֲבָל כָּל זְמַן שֶׁמֻּטָּל לְקָבְרוֹ, אֵין מְבַטְּלִין בִּשְׁבִילוֹ תַּלְמוּד תּוֹרָה, אֶלָּא אִם יֵשׁ חֲבוּרוֹת בָּעִיר שֶׁכָּל אַחַת מִתְעַסֶקֶת יוֹמָהּ, אוֹתָהּ שֶׁאֵינָהּ יוֹמָהּ מֻתֶּרֶת בֵּין בְּלִמּוּד בֵּין בִּשְׁאָר מְלָאכוֹת. וּבִשְׁעַת הוֹצָאָה, מְבַטְּלִין מִכָּל שְׁאָר מְלָאכוֹת וּבָאִים לְלַוּוֹתוֹ, אֲפִלּוּ אִי לֹא קָרֵי וְתָנֵי, דְּלֹא מְפַלְּגִינָן בֵּין לֹא קָרֵי וְתָנֵי אֶלָּא בְּבִטּוּל תַּלְמוּד תּוֹרָה, אֲבָל בִּשְׁאָר מְלָאכוֹת, אֲפִלּוּ אִי לֹא קָרֵי וְתָנֵי הַכֹּל בְּטֵלִים וּבָאִים לְלַוּוֹתוֹ. וְאִם אֵין חֲבוּרוֹת בָּעִיר, כָּל בַּעֲלֵי מְלָאכוֹת צְרִיכִים לְהִתְבַּטֵּל וּלְהִתְעַסֵק בּוֹ עַד שֶׁיִּקָּבֵר; אֲבָל מִתַּלְמוּד תּוֹרָה אֵין צְרִיכִים לְהִתְבַּטֵּל אֶלָּא בִּשְׁעַת הוֹצָאָתוֹ, כִּדְאַמְרָן. \u0010g7\u0011\nהָרוֹאֶה אֶת הַמֵּת וְאֵינוֹ מְלַוֵּהוּ, עוֹבֵר מִשּׁוּם לוֹעֵג לָרָשׁ \u0010g8\u0011 \u0005(מִשְׁלֵי יז, ה)\u0006 וּבַר נִדּוּי הוּא, \u0010g9\u0011 וּלְפָחוֹת יְלַוֶּנּוּ ד' אַמּוֹת. \u0010g10\u0011\nאֲפִלּוּ בְּמָקוֹם שֶׁאֵינוֹ צָרִיךְ לְלַוּוֹת אֶת הַמֵּת, \u0010c1\u0011 צָרִיךְ \u0010t2\u0011 לַעֲמֹד מִפָּנָיו. \u0010g11\u0011\nאָרוֹן הָעוֹבֵר מִמָּקוֹם לְמָקוֹם, אִם שִׁלְדּוֹ קַיֶּמֶת, צְרִיכִין לְלַוּוֹתוֹ כְּמוֹ בִּשְׁעַת הוֹצָאַת הַמֵּת.",{"g":["\u0003ברייתא כתובות דף י\"ז ע\"א:\u0004 ","\u0003מימרא דרב ששת וכו'\u0004 שם ע\"ב:","\u0003טור בשם בה\"ג:\u0004 ","שם בשם רב נטוראי ושהרמב\"ן כ' דטעמא דמסתבר הוא דהא איכא שורה וקדיש וברכת אבלים דבעיא י':\n(°) טור בשם אביו הרא\"ש שם בפ\"ב דכתובות כיון דאינה מצווה ועושה מה שמוטל עליה:","\u0003הרמב\"ן בסת\"ה:\u0004 ","\u0003טור מדברי התוספות שם בכתובות ואביו הרא\"ש בסוף מ\"ק:\u0004 ","\u0003שם ושם:\u0004 ","\u0003מימרא דרחבא וכו'\u0004 ברכות דף י\"ח ע\"א:","\u0003טור מעובדא דרב המנונא וכו'\u0004 וציינתיו לעיל בסימן שמ\"ג:","\u0003שם מדברי רבינו יונה והרא\"ש:\u0004 ","\u0003שם בשם הרי\"ץ גיאות מהירושלמי אילן דקיימי מקמי מיתא וכו':\u0004 ","\u0003מ\"ק דף כ\"ה ע\"א:\u0004 "],"t":["\u0003ושנה. \u0004 משמע תרוייהו בעינן אבל מלשון הריטב\"א שהביא הב\"י משמע דקרא או שנה קאמרינן. ש\"ך:","\u0003לצאת. \u0004 כ' הט\"ז זה קאי אמאן דלא קרי ותני שא\"צ לראות אם יש שם מתעסקי' ונראה דהדעה זאת חולקת על מ\"ש רמ\"א דעכשיו מן הסתם מבטלין ואם כן לפי דעת הרמ\"א יש לבטל גם בזה מ\"מ רב הלומד עם תלמידיו לא יבטל בשביל זה מן הסתם עכ\"ל. וכתב האגודה מה שרגילין לבטל ת\"ת כל זמן שיש מת בעיר הטעם פן יהיה צרכי המת נדחה כי כולם ילכו ללמוד ונ\"ל בקהלות שעשו כתות ויש אנשים מיוחדי' המתעסקי' בו אז אדם הלומד לש\"ש ואינו רגיל לטפל בהם יכול ללמוד ע\"כ. וכתב הש\"ך דמיירי שלא בשעת הוצאתו דיוכל ללמוד וא\"צ להתעסק אפי' למאן דמתני רק בשעת הוצאתו צריך לבטל בשבילו כמ\"ש ס\"ב ודלא כהב\"ח ע\"ש:","\u0003לעמוד. \u0004 כ' הט\"ז פי' מפני העוסקים עמו שהם גומלים חסדים אע\"פ שאין המת ת\"ח. ומכאן יש ללמוד דבכל דבר מצוה שאדם הולך ומתעסק בה יש לעמוד לפניו וכ\"מ בש\"ס פ\"ק דקידושין בוא וראה כמה חביבה מצוה בשעתה שהרי בעלי אומניות עומדים מפני מביאי בכורים וכו'. עכ\"ל \u0005(וכן הוא בספר חסידים סימן תק\"פ)\u0006:"],"r":["\u0003למאן דלא כו'. \u0004רש\"י ותוס' שם בשם שאלתות:","\u0003(ליקוט) ואין מבטלין כו' וא\"צ לצאת כו'. \u0004תה\"א ממ\"ש בירושלמי פ\"ג דפסחים [ופ\"א דחגיגה] ר' אבהו שלח לר\"ח בריה לטבריא שלחין ליה גמיל חסד הוא שלח וא\"ל המבלי אין קברים בקסרין שלחתיך לטבריא וכבר נמנו בעליית בית לוד הלימוד קודם למעשה רבנין אמרין הדא דתימא כשיש שם מי שיעשה מעשה דלמא ר\"ח ור' יוסי ור' אמי חבשון מייתי קומי ר\"א א\"ל אין הוויתון א\"ל גמלין חסד א\"ל ולא הוו תמן אחרנין אמרין ליה מגיר הוה (ע\"כ):","\u0003(ליקוט) ותינוקות של כו'. \u0004ירושלמי \u0005(הביאו הרא\"ש ומרדכי פ\"ג דמ\"ק) \u0006אבוה דשמואל שלח לשמואל ללמוד תורה שלחון ליה גמיל חסדים הוא שלח ליה המבלי אין קברים כאן שלחתיך לשם הדא אמרה אין מבטלין תינוקות של בית רבן להוצאת המת ואמרינן בפט\"ז דשבת \u0005(קי\"ט ב') \u0006אין מבטלין תינוקות של בית רבן אפילו לבנין בה\"מ (ע\"כ):","\u0003בד\"א כו'. \u0004עתוס' בכתובות שם א' ד\"ה להוצאת כו' ובמ\"ק כ\"ז ב' ד\"ה אסורין כו':"]}],["הַנּוֹתֵן מֵתוֹ בְּאָרוֹן וְלֹא קְבָרוֹ בַּקַּרְקַע, עוֹבֵר מִשּׁוּם מֵלִין אֶת הַמֵּת. וְאִם נְתָנוֹ בְּאָרוֹן וּקְבָרוֹ בַּקַּרְקַע, אֵינוֹ עוֹבֵר עָלָיו, \u0010y0\u0011 וּמִכָּל מָקוֹם יָפֶה לְקָבְרוֹ בַּקַּרְקַע מַמָּשׁ, אֲפִלּוּ בְּחוּץ לָאָרֶץ.\nנוֹתְנִין הַמֵּת \u0010y1\u0011 עַל גַּבָּיו, וּפָנָיו לְמַעְלָה, כְּאָדָם שֶׁהוּא יָשֵׁן.\nאֵין קוֹבְרִים ב' מֵתִים זֶה בְּצַד זֶה, אֶלָּא אִם כֵּן הָיָה דֹּפֶן הַקֶּבֶר מַפְסִיק בֵּינֵיהֶם; וְלֹא הַמֵּת בְּצַד עֲצָמוֹת; וְלֹא עֲצָמוֹת בְּצַד הַמֵּת. אֲבָל נִקְבָּר הָאִישׁ עִם בִּתּוֹ קְטַנָּה, וְהָאִשָּׁה עִם בְּנָהּ קָטָן וְעִם בֶּן בְּנָהּ קָטָן. \u0010y2\u0011 זֶה הַכְּלָל כָּל שֶׁיָּשֵׁן עִמּוֹ בְּחַיָּיו, נִקְבָּר עִמּוֹ בְּמוֹתוֹ. \u0010y3\u0011\nאֵין נוֹתְנִין ב' אֲרוֹנוֹת זֶה עַל זֶה; וְאִם נָתַן, כּוֹפִין הָעֶלְיוֹן שֶׁיְּפַנֶּה. וְאִם יֵשׁ בֵּינֵיהֶם עָפָר שִׁשָּׁה טְפָחִים, מֻתָּר.\nאֵין קוֹבְרִין רָשָׁע אֵצֶל צַדִּיק, אֲפִלּוּ רָשָׁע חָמוּר אֵצֶל רָשָׁע קַל. \u0010y4\u0011 וְכֵן \u0010c0\u0011 אֵין קוֹבְרִין צַדִּיק וְכָשֵׁר וּבֵינוֹנִי, אֵצֶל חָסִיד \u0010y5\u0011 מֻפְלָג. \u0005אֲבָל קוֹבְרִים בַּעַל תְּשׁוּבָה אֵצֶל צַדִּיק גָּמוּר (בֵּית יוֹסֵף)\u0006.\nשְׁנַיִם שֶׁהָיוּ שׂוֹנְאִים זֶה לָזֶה, אֵין לְקָבְרָם יַחַד.",["\u0003ומ\"מ יפה לקברו בקרקע קשה ממש. \u0004כלומר אע\"פ שהארון קבור בקרקע מ\"מ לא יהא הארון סתום מכל צד אלא יקבר המת בקרקע ממש ובעט\"ז ובפרישה תמהו על מה שנוהגין עכשיו לעשות לכהנים ארונות שלמים (דהיינו שעושים מלמטה דף ושוכב על הדף ואומרים טעם משום חשיבות כהנים הוא) דהרי אדרבה טוב הוא לשכב על העפר ולפמ\"ש בדרישה דבזמנינו שנותנים חרסית על פיו ועיניו הוי במקום עפר דבזמנם ניחא עי\"ל דאי אפשר לארונות שעושין עכשיו שלא יהיו נקובים בצדדים ובנקב סגי כדאיתא בטור ופוסקים:","\u0003על גבי וכו'. \u0004דכל היכא דישכיבו אותו באופן אחר או מעומד או יושב ה\"ל דרך גנאי וכתב העט\"ז ונוהגין לכסות הארון בדף ושלא להטיל שום עפר על גופו מפני שבזיון הוא לו:","\u0003זה הכלל כו'. \u0004נראה דדוקא אקטן הנ\"ל קאי אבל בן גדול אף שמותר עם אביו וכן בת גדולה עם אמה אסור לקברה עמהם ומ\"ש עם בן בנה הקטן ה\"ה דהוא מותר עם בת בנו או בתה אלא במאי דסיים פתח וחד מנייהו נקט. פרישה:","\u0003אין נותנין כו'. \u0004כתב הב\"ח דאפילו אי אפשר לקבור במקום אחר ולכן צריך למחות בקהלות שהקוברים עושים כן שלא ישימו זה על זה אלא בדאיכא בבירור הפסקת ו' טפחים מיהו אם אי אפשר לקברו בענין אחר ודאי שרי וכן משמע מתשובת רב האי גאון שהביא הטור בסי' שאח\"ז ופשוט הוא:","\u0003וכן אין קוברין צדיק וכ\"ש בינוני כו'. \u0004כצ\"ל:","\u0003אבל קוברים בעל תשובה כו'. \u0004וכתב הב\"ח אבל אין קוברין בעל תשובה אצל חסיד:"],["\u0003אין קוברין צדיק וכ\"ש בינוני. \u0004כן צריך להיות כאן ובטור וכן הוא בספר ת\"ה:"],"\u0010g0\u0011 הַנּוֹתֵן מֵתוֹ \u0010r0\u0011 בְּאָרוֹן וְלֹא קְבָרוֹ בַּקַּרְקַע, עוֹבֵר מִשּׁוּם מֵלִין אֶת הַמֵּת. \u0010r1\u0011 וְאִם נְתָנוֹ בְּאָרוֹן וּקְבָרוֹ בַּקַּרְקַע, אֵינוֹ עוֹבֵר עָלָיו, \u0010y0\u0011 \u0010r2\u0011 וּמִכָּל מָקוֹם יָפֶה לְקָבְרוֹ \u0010g1\u0011 בַּקַּרְקַע \u0010t0\u0011 מַמָּשׁ, \u0010g2\u0011 \u0010r3\u0011 אֲפִלּוּ בְּחוּץ לָאָרֶץ.\nנוֹתְנִין הַמֵּת \u0010y1\u0011 עַל גַּבָּיו, וּפָנָיו \u0010t1\u0011 לְמַעְלָה, כְּאָדָם שֶׁהוּא יָשֵׁן. \u0010g3\u0011 \u0010r4\u0011\nאֵין קוֹבְרִים ב' מֵתִים זֶה בְּצַד זֶה, אֶלָּא אִם כֵּן הָיָה דֹּפֶן הַקֶּבֶר מַפְסִיק בֵּינֵיהֶם; וְלֹא הַמֵּת בְּצַד עֲצָמוֹת; וְלֹא עֲצָמוֹת בְּצַד הַמֵּת. \u0010g4\u0011 אֲבָל נִקְבָּר הָאִישׁ עִם בִּתּוֹ קְטַנָּה, וְהָאִשָּׁה עִם בְּנָהּ קָטָן וְעִם בֶּן בְּנָהּ קָטָן. \u0010y2\u0011 זֶה \u0010t2\u0011 הַכְּלָל כָּל שֶׁיָּשֵׁן עִמּוֹ בְּחַיָּיו, נִקְבָּר עִמּוֹ בְּמוֹתוֹ. \u0010y3\u0011 \u0010g5\u0011 \u0010r5\u0011\nאֵין נוֹתְנִין ב' אֲרוֹנוֹת זֶה עַל זֶה; וְאִם נָתַן, כּוֹפִין הָעֶלְיוֹן \u0010t3\u0011 שֶׁיְּפַנֶּה. \u0010r6\u0011 וְאִם יֵשׁ בֵּינֵיהֶם עָפָר \u0010r7\u0011 שִׁשָּׁה טְפָחִים, \u0010g6\u0011 מֻתָּר.\nאֵין קוֹבְרִין רָשָׁע אֵצֶל צַדִּיק, אֲפִלּוּ רָשָׁע חָמוּר אֵצֶל רָשָׁע קַל. \u0010y4\u0011 \u0010g7\u0011 וְכֵן \u0010c0\u0011 אֵין קוֹבְרִין צַדִּיק \u0010t4\u0011 וְכָשֵׁר וּבֵינוֹנִי, אֵצֶל חָסִיד \u0010y5\u0011 \u0010r8\u0011 מֻפְלָג. \u0005אֲבָל קוֹבְרִים בַּעַל תְּשׁוּבָה אֵצֶל צַדִּיק גָּמוּר \u0010g8\u0011 (בֵּית יוֹסֵף)\u0006.\nשְׁנַיִם שֶׁהָיוּ שׂוֹנְאִים זֶה לָזֶה, אֵין לְקָבְרָם יַחַד.",{"g":["\u0003לשון הטור מדברי הרמב\"ן בסת\"ה ממימרא דרבי יוחנן סנהדרין דף מ\"ו ע\"ב:\u0004 ","שם וכצוואתו דרבי שם בירושלמי ומה שהיו נוהגים חכמי התלמוד בארונות לאחר עיכול הבשר הוא או שהיו נוקבים הארון לארץ:","\u0003שם מהא דאמרינן במתי מדבר וכו'\u0004 דהוי גני אפרקיד ב\"ב דף ע\"ד ע\"א:","\u0003ברייתא באבל רבתי:\u0004 ","\u0003שם כרבי יהודה:\u0004 ","שם:","\u0003סנהדרין משנה וגמ' דף מ\"ז ע\"א:\u0004 ","\u0003טור מדברי הרמב\"ן בסת\"ה מעובדא כי נח נפשיה דרב הונא ואסקוהו לארץ ישראל וכו'\u0004 [במו\"ק כ\"ה ע\"א]:","רבינו ירוחם נתיב כ\"ח בשם ספר חסידים שאף במותם אין להם מנוחה יחד ועוד כתב שם קצת אזהרות בענין קבורת מת וע\"ש:"],"t":["\u0003ממש. \u0004 כלומר אע\"פ שהארון קבור בקרקע מ\"מ לא יהא הארון סתום מכל צד אלא יקבר המת בקרקע ממש ובלבוש ובפרישה תמהו על מה שנוהגין עכשיו לעשות לכהנים ארונות שלמים דהיינו שעושים למטה דף שהמת שוכב עליו ואומרים דעושים כן משום חשיבות הכהנים. דאדרבה הרי טוב יותר לשכב על העפר. ולפי מ\"ש הדרישה דבזמנינו שנותנים חרסים על פיו ועיניו הוי במקום עפר ניחא. א\"נ דאי אפשר לארונות שעושים עכשיו שלא יהיו נקובים בצדדים ובנקב סגי כמ\"ש הטור והפוסקים עכ\"ל הש\"ך \u0005(ועי\"ל לפי מנהגינו שמניחין כיס עפר תחת ראשו הוי כקבור בעפר אע\"פ שהכיס מפסיק כיון שהוא מפשתן דק כנהוג אין זה הפסק ולאותן שנותנין מעפר א\"י על פניו של מת ניחא טפי)\u0006:","\u0003למעלה. \u0004 וכ' הלבוש ונוהגין לכסות הארון בדף ושלא להטיל שום עפר על גופו מפני שבזיון הוא לו:","\u0003הכלל. \u0004 כ' הש\"ך נראה דדוקא אקטן קאי אבל בן גדול אף שמותר עם אביו וכן בת גדולה עם אמה מ\"מ אסור לקברם עמהם \u0005(ומ\"ש עם בן בנה הקטן ה\"ה דמותר עם בת בנה או בתה אלא במאי דסיים פתח וחדא מינייהו נקט)\u0006 פרישה:","\u0003שיפנה. \u0004 וכ' הב\"ח דאפילו אם א\"א לקבור במקום אחר ולכן צריך למחות בקהלות שהקוברים עושים כן שלא ישימו ע\"ז אלא בדאיכא בבירור הפסקת ו' טפחים מיהו אם א\"א לקברו בענין אחר ודאי שרי וכ\"מ מתשו' רב האי גאון שהביא הטור ופשוט הוא עכ\"ל הש\"ך \u0005(עיין בתשו' ח\"צ שאלה קמ\"ט)\u0006:","\u0003וכשר. \u0004 והט\"ז גורס וכ\"ש וכ' שכן הוא בס' ת\"ה:"],"r":["\u0003בארון. \u0004גמרא \u0005(שם) \u0006א\"ל שבור מלכא כו' דליעביד כו':","\u0003(ליקוט) ואם נתנו בארון. \u0004כמ\"ש בירושלמי \u0005(פ\"א דמ\"ק ופ\"ו דסנהדרין) \u0006בראשונה היו קוברין במהמורות כו' ומשימים בארון והביאו הרא\"ש ובטוש\"ע סי' שס\"ג ס\"ד (ע\"כ):","\u0003ומ\"מ כו'. \u0004ירושלמי פ' בתרא דכלאים \u0005(ופי\"ב דכתובות) \u0006והביאו הטור:\n\u0003(ליקוט) ומ\"מ יפה כו'. \u0004ירושלמי \u0005(שם) \u0006בצוואתו של רבי תהא ארוני נקובה ופי' הרמב\"ן שיטלוהו כף התחתון שבארון וישכיבוהו על הארץ שקבורות קרקע מצוה ול\"ת משום חביבותא דא\"י אלא אפי' בח\"ל משום שנאמר ואל עפר תשוב עכ\"ל (ע\"כ):","\u0003נותנין כו'. \u0004ירושלמי \u0005(שם) \u0006יהבוני על כו' והביאו תה\"א והטור ובסוף נזיר ירושלמי איזהו מושכב כדרכו רגליו מופשטות וידיו על לבו והביאו ב\"י ועבה\"ג:\n\u0003(ליקוט) נותנין כו'. \u0004עבה\"ג וה\"ה בצדו כמ\"ש בירושלמי \u0005(שם) \u0006בר' ירמיה שצוה כן ועב\"י בשם תה\"א וכן בגמ' דנזיר \u0005(ס\"ה א') \u0006מושכב כו' (ע\"כ):","\u0003(ליקוט) אין כו' אבל כו'. \u0004א\"ר פי\"ג (ע\"כ):\n\u0003(ליקוט) אין כו'. \u0004כמ\"ש בב\"ב ק' ב' המוכר כו' ושם ק\"א ב' הא קנגעי כו' ובמתני' שם רשב\"ג אומר הכל כו' וז\"ש אא\"כ כו' ופסק כרשב\"ג:","\u0003אין נותנין כו'. \u0004תה\"א בשם א\"ר אין נותנין ב' ארונות זה ע\"ג זה ואם נתן כופין את בעל העליון שיפנה שאין נוהגין בזיון במתים:","\u0003ואם יש כו'. \u0004כמ\"ש בב\"ב שם במעמיק:","\u0003ו' טפחים. \u0004טור. אבל בתה\"א כתב ג\"ט אלא שכתב שם ונשאל מר' האי כו' והשיב כו' ואי אפשר שלא יהא בין מת לחבירו ששה טפחים שלשה לתפוסת זה ושלשה לתפוסת זה כו' וערשב\"ם בב\"ב ק' ב' ד\"ה ושנים כנגדו כו' וה\"ה למעלה ודלא כפי' הרמב\"ם וש\"ע ח\"מ סי' רי\"ז ס\"ו (ע\"כ):","\u0003אבל קוברין כו'. \u0004עספ\"ה דברכות:\n\u0003(ליקוט) אבל קוברין כו'. \u0004ממ\"ש ברפ\"ג \u0005(דמ\"ק י\"ז א') \u0006עיילוה למערתא דדייני כו' דעבד כר' אלעאי כו' ועש\"ך (ע\"כ):"]}],["\u0010y0\u0011 \u0010c0\u0011 אֵין מְפַנִּין הַמֵּת וְהָעֲצָמוֹת, לֹא מִקֶּבֶר מְכֻבָּד לְקֶבֶר מְכֻבָּד, וְלֹא מִקֶּבֶר בָּזוּי לְקֶבֶר בָּזוּי, וְלֹא מִבָּזוּי לִמְכֻבָּד, וְאֵין צָרִיךְ לוֹמַר מִמְּכֻבָּד לְבָזוּי. \u0010y1\u0011 \u0010c1\u0011 וּבְתוֹךְ שֶׁלּוֹ, אֲפִלּוּ מִמְּכֻבָּד לְבָזוּי, מֻתָּר, שֶׁעָרֵב לְאָדָם שֶׁיְּהֵא נָח אֵצֶל אֲבוֹתָיו. וְכֵן כְּדֵי לְקָבְרוֹ \u0010y2\u0011 בְּאֶרֶץ יִשְׂרָאֵל, מֻתָּר. וְאִם נְתָנוּהוּ שָׁם עַל מְנַת לְפַנּוֹתוֹ, מֻתָּר בְּכָל עִנְיָן. וְאִם אֵינוֹ מִשְׁתַּמֵּר בְּזֶה הַקֶּבֶר, שֶׁיֵּשׁ לָחוּשׁ שֶׁמָּא יוֹצִיאוּהוּ עוֹבְדֵי כּוֹכָבִים, אוֹ שֶׁיִּכָּנְסוּ בּוֹ מַיִם, אוֹ שֶׁהוּא קֶבֶר הַנִּמְצָא, מִצְוָה לְפַנּוֹתוֹ. \u0005יֵשׁ נוֹהֲגִין לָתֵת מֵעֲפַר אֶרֶץ יִשְׂרָאֵל בַּקֶּבֶר (אוֹר זָרוּעַ)\u0006, וְיֵשׁ לְמִנְהָג זֶה עַל מַה שֶּׁיִּסְמֹכוּ \u0005(מִדְרָשׁ תַּנְחוּמָא פ' וַיְחִי)\u0006. \u0010y3\u0011\nאֵין מוֹלִיכִים מֵת מֵעִיר שֶׁיֵּשׁ בָּהּ קְבָרוֹת לְעִיר \u0005(אַחֶרֶת)\u0006, אֶלָּא אִם כֵּן מֵחוּצָה לָאָרֶץ, לָאָרֶץ. \u0005הַגָּה: אוֹ שֶׁמּוֹלִיכִין אוֹתוֹ לִמְקוֹם קִבְרוֹת אֲבוֹתָיו (כֵּן מַשְׁמָע בְּאוֹר זָרוּעַ)\u0006. וְאִם צִוָּה לְהוֹלִיכוֹ מִמָּקוֹם לְמָקוֹם, אוֹ שֶׁצִּוָּה לְקָבְרוֹ בְּבֵיתוֹ וְלֹא בְּבֵית הַקְּבָרוֹת, שׁוֹמְעִין לוֹ \u0005(ג\"ז שָׁם)\u0006. וּמֻתָּר לִתֵּן סִיד עָלָיו, \u0010c2\u0011 כְּדֵי לְעַכֵּל הַבָּשָׂר מַהֵר, וּלְהוֹלִיכוֹ לַמָּקוֹם אֲשֶׁר צִוָּה \u0005(רַשְׁבָּ\"א סִימָן שס\"ט)\u0006.\nאֵין מְלַקְּטִין עֲצָמוֹת, לֹא מִתּוֹךְ הָאָרוֹן וְלֹא מִתּוֹךְ הַקֶּבֶר, לְצַד זֶה, לִקְבֹּר שָׁם מֵת אַחֵר, אוֹ לְצֹרֶךְ הַמָּקוֹם.\nמָקוֹם שֶׁנּוֹהֲגִין \u0010c3\u0011 לִקְבֹּר בְּמַהֲמוֹרוֹת \u0005(פי' בְּשׁוּחוֹת עֲמֻקוֹת מִן בְּמַהֲמֹרוֹת בַּל יָקוּמוּ (תְּהִלִּים קמ, יא)\u0006 ) בְּלא אָרוֹן, עַד שֶׁיִּתְעַכֵּל הַבָּשָׂר, וְאַחַר כָּךְ מְלַקְּטִין הָעֲצָמוֹת וְקוֹבְרִין אוֹתָן בְּאָרוֹן, \u0010y4\u0011 מֻתָּר.\nאָרוֹן שֶׁפִּנּוּהוּ, אָסוּר בַּהֲנָאָה. אִם הוּא שֶׁל אֶבֶן וְשֶׁל חֶרֶס, יִשָּׁבֵר; וְשֶׁל עֵץ, יִשָּׂרֵף.\nהַמּוֹצֵא נְסָרִים בְּבֵית הַקְּבָרוֹת, \u0010y5\u0011 \u0010c4\u0011 לֹא יְזִיזֵם מִמְּקוֹמָם.\nאָסוּר לִפְתֹּחַ הַקֶּבֶר אַחַר שֶׁנִּסְתַּם הַגּוֹלֵל, אֲפִלּוּ אִם עוֹרְרִים הַיּוֹרְשִׁים לְפָתְחוֹ כְּדֵי \u0010c5\u0011 לִבְדֹּק אִם הֵבִיא שְׁתֵּי שְׂעָרוֹת.",["\u0003אין מפנין כו'. \u0004הטעם שהבלבול קשה למתים מפני שמתייראין מיום הדין וזכר לדבר ישנתי אז ינוח לי ובשמואל הוא אומר למה הרגזתני להעלות וגו':","\u0003ובתוך שלו כו'. \u0004כלומר לפנותו לקברו אצל אבותיו מפני שזהו כבודו וכתב הבית יוסף וד\"מ משום האי כבוד מפנין ולא משום כבוד אחר:","\u0003בארץ ישראל מותר.\u0004 שהוא כפרתו שעפר א\"י מכפרת דכתיב וכפר אדמתו עמו:","\u0003אין מוליכין כו'. \u0004משום כבוד המתים הקבורים באותה העיר שמבזה אותם שלא לנוח אצלם את זה:","\u0003ארון שפינוהו אסור בהנאה. \u0004שכל מה שנקבר עם המת אסור בהנאה כדלעיל ר\"ס שמ\"ט:","\u0003לא יזיזם ממקומם. \u0004דחיישינן שמא מארון שפינוהו הם:"],["\u0003אין מפנין כו'. \u0004הטעם דבלבול קשה להם שמתייראין מיום הדין וזכר לדבר ישנתי אז ינוח לי:","\u0003ובתוך שלו. \u0004פי' למקום שהוא שלו ששם שוכבים בני משפחתו:","\u0003כדי לעכל הבשר. \u0004שנאמר בשרו עליו יכאב כל זמן שבשרו עליו יכאב אינו נוח מן הדין:","\u0003במהמורות. \u0004פי' גומא מלשון במהמורות בל יקומו:","\u0003לא יזיזם ממקומם. \u0004דשמא מן ארון הם וכתוב בפרישה ה\"ה חרסים:","\u0003אם הביא שתי שערות. \u0004פי' אם היה גדול ונפקא מינה לענין מכירתו שמכר אם הוא מכר:"],"\u0010y0\u0011 \u0010c0\u0011 \u0010g0\u0011 \u0010r0\u0011 אֵין \u0010t0\u0011 מְפַנִּין הַמֵּת וְהָעֲצָמוֹת, לֹא מִקֶּבֶר מְכֻבָּד לְקֶבֶר מְכֻבָּד, וְלֹא מִקֶּבֶר בָּזוּי לְקֶבֶר בָּזוּי, וְלֹא מִבָּזוּי לִמְכֻבָּד, וְאֵין צָרִיךְ לוֹמַר מִמְּכֻבָּד לְבָזוּי. \u0010y1\u0011 \u0010c1\u0011 וּבְתוֹךְ שֶׁלּוֹ, אֲפִלּוּ מִמְּכֻבָּד לְבָזוּי, מֻתָּר, שֶׁעָרֵב לְאָדָם שֶׁיְּהֵא נָח אֵצֶל אֲבוֹתָיו. \u0010g1\u0011 \u0010r1\u0011 וְכֵן כְּדֵי לְקָבְרוֹ \u0010y2\u0011 \u0010t1\u0011 בְּאֶרֶץ יִשְׂרָאֵל, \u0010r2\u0011 מֻתָּר. וְאִם נְתָנוּהוּ שָׁם עַל מְנַת לְפַנּוֹתוֹ, מֻתָּר בְּכָל עִנְיָן. \u0010g2\u0011 וְאִם אֵינוֹ מִשְׁתַּמֵּר בְּזֶה הַקֶּבֶר, שֶׁיֵּשׁ לָחוּשׁ שֶׁמָּא יוֹצִיאוּהוּ עוֹבְדֵי כּוֹכָבִים, אוֹ שֶׁיִּכָּנְסוּ בּוֹ מַיִם, אוֹ שֶׁהוּא קֶבֶר הַנִּמְצָא, מִצְוָה לְפַנּוֹתוֹ. \u0005יֵשׁ נוֹהֲגִין לָתֵת מֵעֲפַר אֶרֶץ יִשְׂרָאֵל בַּקֶּבֶר (אוֹר זָרוּעַ)\u0006, וְיֵשׁ לְמִנְהָג זֶה עַל מַה שֶּׁיִּסְמֹכוּ \u0005(מִדְרָשׁ תַּנְחוּמָא פ' וַיְחִי)\u0006. \u0010y3\u0011 \u0010g3\u0011\nאֵין מוֹלִיכִים מֵת מֵעִיר שֶׁיֵּשׁ בָּהּ קְבָרוֹת לְעִיר \u0005(אַחֶרֶת)\u0006, אֶלָּא אִם כֵּן מֵחוּצָה לָאָרֶץ, לָאָרֶץ. \u0005הַגָּה: \u0010r3\u0011 אוֹ שֶׁמּוֹלִיכִין אוֹתוֹ לִמְקוֹם קִבְרוֹת אֲבוֹתָיו (כֵּן מַשְׁמָע בְּאוֹר זָרוּעַ)\u0006. וְאִם צִוָּה לְהוֹלִיכוֹ מִמָּקוֹם לְמָקוֹם, אוֹ שֶׁצִּוָּה לְקָבְרוֹ בְּבֵיתוֹ וְלֹא בְּבֵית הַקְּבָרוֹת, שׁוֹמְעִין לוֹ \u0005(ג\"ז שָׁם)\u0006. וּמֻתָּר לִתֵּן סִיד עָלָיו, \u0010c2\u0011 כְּדֵי לְעַכֵּל \u0010t2\u0011 הַבָּשָׂר מַהֵר, וּלְהוֹלִיכוֹ לַמָּקוֹם אֲשֶׁר צִוָּה \u0005(רַשְׁבָּ\"א סִימָן שס\"ט)\u0006. \u0010g4\u0011 \u0010r4\u0011\nאֵין מְלַקְּטִין עֲצָמוֹת, לֹא מִתּוֹךְ הָאָרוֹן וְלֹא מִתּוֹךְ הַקֶּבֶר, לְצַד זֶה, לִקְבֹּר שָׁם מֵת אַחֵר, אוֹ לְצֹרֶךְ הַמָּקוֹם. \u0010g5\u0011\nמָקוֹם שֶׁנּוֹהֲגִין \u0010c3\u0011 לִקְבֹּר בְּמַהֲמוֹרוֹת \u0005(פי' בְּשׁוּחוֹת עֲמֻקוֹת מִן בְּמַהֲמֹרוֹת בַּל יָקוּמוּ (תְּהִלִּים קמ, יא)\u0006 ) בְּלא אָרוֹן, עַד שֶׁיִּתְעַכֵּל הַבָּשָׂר, וְאַחַר כָּךְ מְלַקְּטִין הָעֲצָמוֹת וְקוֹבְרִין אוֹתָן בְּאָרוֹן, \u0010y4\u0011 \u0010g6\u0011 מֻתָּר.\nאָרוֹן שֶׁפִּנּוּהוּ, אָסוּר בַּהֲנָאָה. אִם הוּא שֶׁל אֶבֶן וְשֶׁל חֶרֶס, יִשָּׁבֵר; וְשֶׁל עֵץ, יִשָּׂרֵף. \u0010g7\u0011 \u0010r5\u0011\nהַמּוֹצֵא נְסָרִים בְּבֵית הַקְּבָרוֹת, \u0010y5\u0011 \u0010c4\u0011 לֹא יְזִיזֵם מִמְּקוֹמָם. \u0010g8\u0011 \u0010r6\u0011\nאָסוּר לִפְתֹּחַ הַקֶּבֶר אַחַר שֶׁנִּסְתַּם הַגּוֹלֵל, אֲפִלּוּ אִם עוֹרְרִים הַיּוֹרְשִׁים לְפָתְחוֹ כְּדֵי \u0010c5\u0011 לִבְדֹּק אִם הֵבִיא שְׁתֵּי שְׂעָרוֹת.",{"g":["\u0003ירושלמי סוף פ\"ג דמ\"ק וכתב הכל בו הטעם מפני שהוא קשה למתים וכו'\u0004 ע\"ש:\n(°) פירוש למקום שהוא שלו ששוכבין שם בני משפחתו:","\u0003רבינו ירוחם:\u0004 ","\u0003הגהות אשיר\"י בשם א\"ז בפ\"ג דמ\"ק:\u0004 ","שם:","\u0003ברייתא הביאו הטור וסת\"ה:\u0004 ","\u0003טור מדברי הרמב\"ן בסת\"ה ולמד כן מהירושלמי וברייתא דלעיל:\u0004 ","\u0003ברייתא באבל רבתי פרק י\"ג:\u0004 ","\u0003דחיישינן שמא הוא ארון שפינוהו:\u0004 ","רבינו ירוחם בשם אבל רבתי (הביאם הרא\"ש במ\"ק):"],"t":["\u0003מפנין. \u0004 הטעם שהבלבול קשה למתים מפני שמתייראים מיום הדין וזכר לדבר ישנתי אז ינוח לי ובשמואל הוא אומר למה הרגזתני להעלות וגו'. ט\"ז וש\"ך:","\u0003בא\"י. \u0004 שהוא כפרתו שעפר א\"י מכפרת דכתיב וכפר אדמתו עמו. ש\"ך:","\u0003הבשר. \u0004 שנאמר בשרו עליו יכאב כל זמן שבשרו עליו אינו נוח מן הדין. ט\"ז \u0005(ועיין ש\"י ח\"ב סי' צ\"ז)\u0006:"],"r":["\u0003(ליקוט) אין מפנין כו'. \u0004א\"ר פי\"ג (ע\"כ):","\u0003וכן כדי כו'. \u0004ג\"כ מטעם הנ\"ל דניחא ליה:\n\u0003(ליקוט) וכן כדי כו'. \u0004שכל משום כפרה מותר כמ\"ש בירושלמי ברשונה היו קוברין במהמורות כו' וכמ\"ש בס\"ד (ע\"כ):","\u0003ואם נתנוהו כו'. \u0004ע\"ל סי' שס\"ד ס\"א:","\u0003(ליקוט) או שמוליכין כו'. \u0004כמ\"ש במכות י\"א ב' תנא כו' וערש\"י שם ד\"ה תנא כו' אחר זמן ר\"ל דאף לפנות מותר. וכמ\"ש בס\"א שערב כו' (ע\"כ):","\u0003(ליקוט) אין מלקטין כו'. \u0004תה\"א בשם א\"ר ומסיים שם מקום שנהגו לעשות כן עושין מקום שנהגו שלא לעשות כן אין עושין וע\"ז נאמר אל תסג גבול עולם ופי' שם דמ\"ש מקום שנהגו כו' היינו כמ\"ש בירושלמי לאחר עיכול הבשר וז\"ש בס\"ד מקום כו' (ע\"כ):","\u0003(ליקוט) המוצא כו'. \u0004א\"ר סוף פי\"ג:","\u0003אסור כו'. \u0004שם פ\"ד הלכה י\"ב מעשה כו' גמ' פ\"ט דב\"ב \u0005(קנ\"ד קנ\"ה) \u0006(ע\"כ):"]}],["\u0010y0\u0011 קֶבֶר שֶׁל בִּנְיָן, אָסוּר בַּהֲנָאָה; אֲבָל קַרְקַע עוֹלָם שֶׁל קֶבֶר, אֵינוֹ נֶאֱסָר. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּהַקַּרְקַע שֶׁלָּקְחוּ מִן הַקֶּבֶר וְחָזְרוּ וְנָתְנוּ עָלָיו, \u0010y1\u0011 דְּהָוֵי תָּלוּשׁ וּלְבַסּוֹף חִבְּרוֹ, אָסוּר בַּהֲנָאָה (טוּר בְּשֵׁם הר\"ר יְשַׁעְיָה)\u0006. \u0010y2\u0011 וְיֵשׁ אוֹסְרִין עוֹד לֵישֵׁב עַל הָאֶבֶן שֶׁנּוֹתְנִין עַל הַקֶּבֶר לְמַצֵּבָה \u0005(גַּם זוֹ בִּשְׁמוֹ וכ\"כ הַגָּהוֹת אֲשֵׁרִ\"י בְּשֵׁם אוֹר זָרוּעַ פֶּרֶק אֵלּוּ מְגַלְּחִין)\u0006. \u0010c0\u0011 וְיֵשׁ חוֹלְקִים וּמַתִּירִים \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. הַכֵּלִים שֶׁחוֹפְרִים וְקוֹבְרִים בָּהֶם, מֻתָּרִים בַּהֲנָאָה, וְאֵין לְהִשְׁתַּמֵּשׁ בָּהֶן אֶלָּא מִדַּעַת הַגַּבַּאי, כְּמוֹ בִּשְׁאָר צְדָקָה \u0005(תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן צ\"ז)\u0006. וְהָא דְּקֶבֶר שֶׁל בִּנְיָן אָסוּר לְעוֹלָם, דַּוְקָא שֶׁבְּנָאוֹ לְשֵׁם מֵת, וּנְתָנוֹ בּוֹ אֲפִלּוּ עַל דַּעַת לְפַנּוֹתוֹ, וַאֲפִלּוּ לֹא נָתַן בּוֹ אֶלָּא נֵפֶל. אֲבָל אִם בְּנָאוֹ לִשְׁמוֹ, וְלֹא נְתָנוֹ בּוֹ, מֻתָּר. וְכֵן אִם נְתָנוֹ בּוֹ אַדַּעְתָּא לְפַנּוֹתוֹ, וְלֹא הִזְמִינוֹ מִתְּחִלָּה, מֻתָּר לְאַחַר שֶׁפִּנָּהוּ. אֲבָל אִם נְתָנוֹ בּוֹ עַל דַּעַת לִהְיוֹת בּוֹ עוֹלָמִית, אָסוּר אֲפִלּוּ לְאַחַר שֶׁפִּנָּהוּ, אֲפִלּוּ לֹא בְּנָאוֹ לִשְׁמוֹ. וְאִם לֹא בְּנָאוֹ לִשְׁמוֹ, וּנְתָנוּהוּ בְּתוֹכוֹ וְהוֹסִיף בּוֹ דִּימוֹס \u0005(פֵּרוּשׁ נִדְבָּךְ, וְהוּא שׁוּרַת בִּנְיַן הַחוֹמָה)\u0006 לִשְׁמוֹ, כֻּלּוֹ אָסוּר, אֲפִלּוּ לְאַחַר שֶׁפִּנָּהוּ וַאֲפִלּוּ שֶׁקְּבָרוֹ שָׁם עַל דַּעַת לְפַנּוֹתוֹ. וְאִם מַכִּיר הַדִּימוֹס שֶׁהוֹסִיף לִשְׁמוֹ, מְסִירוֹ, וְהוּא לְבַדּוֹ אָסוּר, וּשְׁאָר הַקֶּבֶר מֻתָּר.\nקֶבֶר הַנִּמְצָא, \u0010y3\u0011 מֻתָּר לְפַנּוֹתוֹ. פִּנָּהוּ, מְקוֹמוֹ טָהוֹר \u0010y4\u0011 וּמֻתָּר בַּהֲנָאָה. \u0010y5\u0011 קֶבֶר הַיָּדוּעַ, אָסוּר לְפַנּוֹתוֹ; \u0010y6\u0011 פִּנָּהוּ, מְקוֹמוֹ טָמֵא וְאָסוּר בַּהֲנָאָה. \u0010y7\u0011 וְהָרַמְבַּ\"ם גּוֹרֵס קֶבֶר הַנִּמְצָא, מֻתָּר לְפַנּוֹתוֹ; \u0010y8\u0011 פִּנָּהוּ, מְקוֹמוֹ טָמֵא וְאָסוּר בַּהֲנָאָה; קֶבֶר הַיָּדוּעַ, אָסוּר לְפַנּוֹתוֹ; פִּנָּהוּ, מְקוֹמוֹ טָהוֹר וּמֻתָּר בַּהֲנָאָה.\nמֵת מִצְוָה, שֶׁמְּצָאוֹ אָדָם בַּשָּׂדֶה וּקְבָרוֹ שָׁם, אֲפִלּוּ שֶׁלֹּא מִדַּעַת בַּעַל הַשָּׂדֶה, אָסוּר לְפַנּוֹתוֹ, שֶׁמֵּת מִצְוָה קוֹנֶה מְקוֹמוֹ. \u0010y9\u0011 וְכָל הַמּוֹצְאוֹ צָרִיךְ לְקָבְרוֹ בַּמָּקוֹם שֶׁמְּצָאוֹ. וְאִם מְצָאוֹ עַל הַמֶּצֶר, שֶׁצָּרִיךְ לְפַנּוֹתוֹ מִשָּׁם מִפְּנֵי הָרַבִּים שֶׁלֹּא יַאֲהִילוּ עָלָיו, אִם מְצָאוֹ בֵּין שְׂדֵה בּוּר \u0005(פיר' שֶׁאֵינָהּ חֲרוּשָׁה וּזְרוּעָה)\u0006 לִשְׂדֵה נִיר \u0005(פֵּרוּשׁ נִיר נֶחֱרַשׁ וְלֹא נִזְרַע)\u0006, מְפַנֶּהוּ לִשְׂדֵה בּוּר. בֵּין שְׂדֵה נִיר לִשְׂדֵה זֶרַע, מְפַנֶּהוּ לִשְׂדֵה נִיר. בֵּין שְׂדֵה זֶרַע לִשְׂדֵה אִילָן, מְפַנֶּהוּ לִשְׂדֵה זֶרַע. בֵּין שְׂדֵה אִילָן לִשְׂדֵה כֶּרֶם, מְפַנֶּהוּ לִשְׂדֵה אִילָן. וְאִם שְׁתֵּיהֶם שָׁווֹת, מְפַנֶּהוּ לַקָּרוֹב שֶׁבָּהֶם. וְאִם שְׁתֵּיהֶן שָׁווֹת בְּקֵרוּב, מְפַנֶּהוּ לְאֵיזֶהוּ מֵהֶם שֶׁיִּרְצֶה. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּמְצָאוֹ חוּץ לַתְּחוּם. אֲבָל אִם מְצָאוֹ בְּתוֹךְ הַתְּחוּם, מְבִיאוֹ לְבֵית הַקְּבָרוֹת. וְאֵינוֹ נִקְרָא מֵת מִצְוָה, \u0010c1\u0011 אֶלָּא אִם כֵּן מָצָא רֹאשׁוֹ וְרֻבּוֹ.\nאִם מָצְאוּ יִשְׂרָאֵל הָרוּג, יִקְבְּרוּהוּ כְּמוֹ שֶׁמְּצָאוּהוּ, בְּלֹא תַּכְרִיכִין, וְלֹא יַחְלְצוּ בּוֹ אֲפִלּוּ מִנְעָלָיו. \u0005הַגָּה: \u0010c2\u0011 וְכֵן עוֹשִׂין לְיוֹלֶדֶת שֶׁמֵּתָה, \u0010y10\u0011 אוֹ לְמִי שֶׁנָּפַל וָמֵת (מהרי\"ל סִימָן ס\"ה)\u0006. וְיֵשׁ אוֹמְרִים שֶׁמַּלְבִּישִׁין אוֹתָם לְמַעְלָה מִבִּגְדֵיהֶם, תַּכְרִיכִין \u0005(הגהמי\"י בְּשֵׁם ר\"י מִדּוּרָא)\u0006. וְנָהֲגוּ שֶׁאֵין עוֹשִׂין לָהֶם תַּכְרִיכִין כִּשְׁאָר מֵתִים, רַק קוֹבְרִין אוֹתָן בְּבִגְדֵיהֶם, וּלְמַעְלָה מֵהֶם סָדִין, כִּשְׁאָר מֵתִים.\nקֶבֶר הַמַּזִּיק אֶת הָרַבִּים, כְּגוֹן שֶׁהוּא סָמוּךְ לַדֶּרֶךְ, אֲפִלּוּ נִקְבַּר שָׁם מִדַּעַת בַּעַל הַשָּׂדֶה, מֻתָּר לְפַנּוֹתוֹ, \u0010c3\u0011 וּמְקוֹמוֹ טָהוֹר, \u0010y11\u0011 וְאָסוּר בַּהֲנָאָה אִם קָדַם הַקֶּבֶר; אֲבָל אִם קָדַם הַדֶּרֶךְ, מְקוֹמוֹ \u0010y12\u0011 מֻתָּר בַּהֲנָאָה.\nקֶבֶר שֶׁפִּנָּהוּ, הֵיכָא דְּמֻתָּר בַּהֲנָאָה, \u0010y13\u0011 לֹא יַעֲשֶׂנּוּ בֵּית הַתֶּבֶן וְלֹא בֵּית הָעֵצִים וְלֹא בֵּית הָאוֹצָרוֹת.\nהַחוֹצֵב קֶבֶר לְאָבִיו וּקְבָרוֹ בְּמָקוֹם אַחֵר, \u0010y14\u0011 לֹא יִקָּבֵר בּוֹ הוּא עוֹלָמִית, מִשּׁוּם כְּבוֹד אָבִיו; אֲבָל אַחֵר, מֻתָּר לִקָּבֵר בּוֹ.",["\u0003קבר של בנין כו'. \u0004דילפינן מדכתיב וישלך את עפרה אל קבר בני העם מקיש קבר לעבודת כוכבי' מה עבודת כוכבי' אינו נאסר במחובר כדלעיל סי' קמ\"ה אף קבר אין נאסר במחובר אבל קבר של בנין הוי תלוש ולבסוף חברו דאסור כמו שבנאו לעבודת כוכבים כדלעיל סימן קמ\"ה סעיף ג':","\u0003דהוי תלוש ולבסוף חברו אסור בהנאה. \u0004ואיזה הוא קרקע עולם כגון החופר כוך בסלע שהוא קרקע עולם שלא נתלש. טור וכ\"ש צדדי הקבר ותחתיתו שאין נאסר אלא דאשמועינן בכוך דאפי' העפר שעל גביו אינו נאסר משום דקרקע עולם הוא וכ\"כ בפרישה:","\u0003ויש אוסרים עוד כו'. \u0004וכתב בהגהת אשר\"י דאסור למכור מצבה שנשברה ואסור להשען על המצבה ואסור לדרוך ע\"ג הקברים דאסור בהנאה וכתב הב\"ח שכן נוהגין איסור:","\u0003מותר לפנותו. \u0004ולא חיישי' שמא מת מצוה הוא דמת מצוה קלא אית ליה:","\u0003ומותר בהנאה. \u0004שאין אדם אוסר דבר שאינו שלו ומיירי בקבר של בנין דאלו במחובר בלאו הכי אין מחובר נאסר וכ\"כ נ\"י:","\u0003קבר הידוע. \u0004שנקבר שם מדעת בעל השדה:","\u0003מקומו טמא ואסור בהנאה. \u0004גזירה דרבנן היא שגזרו טומאה עולמית כדי שלא יפנוהו:","\u0003והרמב\"ם גורס קבר כו'. \u0004וה\"פ קבר הנמצא דהיינו שלא היינו יודעים שהיה שם קבר מותר לפנותו דכיון שלא היה ידוע מסתמא נקבר שם שלא ברשות בעל השדה:","\u0003פינהו מקומו טמא. \u0004כלומר השדה שסביבותיו היכא דאיכא למיחש לקברים. קבר הידוע שאין שם אלא הוא לבדו (ועבר) [ונקבר] שם שלא מדעת בעל השדה מותר לפנותו ומקומו טהור ומותר בהנאה כיון שידוע שאין שם קברים אחרים. ב\"י:","\u0003וכל המוצאו צריך לקברו במקום שמצאו. \u0004וא\"צ להוליכו לקברות וכתב מהרש\"ל ומה שהאידנא אין נזהרים בזה הוא לפי שאין הארץ שלנו ואין לנו רשות לקבור בכל מקום ואף אם נקבר אותו לשם יש לחוש שהעובדי כוכבים יחזרו ויוציאו אותו כדי לפשוט בגדיו מעליו [או] משום זלזול ע\"כ מוליכין אותו לבה\"ק מיוחד עד כאן והביאוהו האחרונים:","\u0003או למי שנפל ומת. \u0004במהרי\"ל כתוב דאם דם יצא ממנו אז אין לטהר אותו כי הדם יסתלק ממנו אך יקברוהו במלבושיו וכ' הב\"ח ונראה דהיינו דוקא כשמת במלבושיו אבל בנפל ולא מת מיד אלא לאחר כמה ימים שכבר פשט מלבושיו וגם אין דם יוצא ממנו שכבר פסק ומת על מטתו מכח אותו נפילה אז ודאי מטהרין אותו ועושין לו תכריכין כשאר בני אדם שמתין על מטתן ובדבר הזה יש חילוק בין נפל מן הגג להרוג דאלו בהרוג בידי עובד כוכבים אע\"פ שבשעה שמלאוהו כבר פסק הדם קוברים אותו כאשר הוא נמצא כדי להעלות חימה ולנקום נקם וזה אין שייך בנפל מן הגג וכן ביולדת שמתה ודם יוצא ממנה אין לטהרה אלא קוברים אותה בלבושיה אבל אם לא מתה אלא לאחר כמה ימים ושבועות וכבר פסק הדם נוהגין עמה כמו בשאר מתים לטהרה ולעשות לה תכריכין שוב מצאתי כתוב שמעתי הטעם גבי הרוג דהרי כבר יצאו כל הדמים ממנו והם מובלעים בבגדיו וחיישינן שמא נבלע בתוכן הרביעית דם שהנפש יוצאת בו ע\"כ יקברוהו כמו שמצאוהו ולא יחלצו אפילו מנעליו דשמא הדמים שיצאו עם יציאת הנפש הם בתוך המנעלים וע\"כ נוהגין בהרוג לחפור ולחתור במרא וחצינא בקרקע במקום שנמצא שם ההרוג וכן כל דמו שיצא ממנו במקום קרוב לו וקוברין אותו עפר שנבלע בו דמו עם ההרוג דשמא באותו הדם יצא דם הנפש ומזה הטעם ג\"כ במי שנפל מן הגג ומת או נפל עליו הבית ומת ונעשה בגופו פצעים וחבורות ומוציא מהם דם וזה גם כן טעם היולדת דרובם אינם מתי' אלא מחמת שנעשה באיברים הפנימים שלה פצעים כשכורעת לילד וע\"י כן יצא ממנה דם הרבה נבלעו בכתונת שעל גופה ובשאר בגדים שעליה והדמים שיצאו עם יציאת הנפש נבלעו בתוכם משא\"כ כשאין שם פצעים ולא יצא מהם דם כלל דאז אין קוברין אותה בבגדיה אלא בתכריכינן כשאר מתים ומטהרין אותם ולפ\"ז מי שמת בדרך בקור גדול ושלג נראה דפושטין מלבושיו ומטהרין ומלבישין אותו בתכריכין כיון שאין בו פצעים ולא יצא ממנו דם וכן מי שנטבע במים בבגדיו דפושטין בגדיו ומטהרין אותו ומלבישין אותו תכריכין וכמ\"ש בסוף ספר מהרי\"ל ע\"כ ואני ראיתי בהרבה קהלות נוהגין לטהר כל יולדת ולהלבישה תכריכים ולהלבישה בגדיה למעלה מהתכריכין ולמעלה מהם הסדין:","\u0003ואסור בהנאה. \u0004אם הוא קבר של בנין לאפוקי קרקע עולם אינה נאסרת כדלעיל ריש הסימן:","\u0003מותר בהנאה. \u0004שהרי אין אדם אוסר דבר שאינו שלו ולאו כל כמיניה לאסור של רבים:","\u0003לא יעשנו כו'. \u0004דגנאי הוא למת לעשות כן:","\u0003לא יקבר כו'. \u0004עיין בטור דמסיק בשם הרמב\"ן דכיון דטעמא הוא משום כבוד אביו אפי' קרקע עולם נמי אסור:"],["\u0003ויש חולקין ומתירין. \u0004דס\"ל דלא אסרו בגמרא אלא קבר של בנין לחוד וכ' רש\"ל שהעולם נהגו איסור לישב על הקבר עד כאן. וכתב בהגהת אשר\"י דכל מה שנעשה לצורך המת ולכבוד המת אסור בהנאה ומתוך כך אסור למכור מצבה שנשברה ולפי דבריו אסור להשען על המצבה וא\"כ אסור לדרוך על גבי הקברים משום דאסור בהנאה עכ\"ל. ובפרק (הספינה) [המוכר פירות] (דף ק\"א) פי' רשב\"ם דנושאי המטה שדורסין ע\"ג המערות המוקפות מכל צד כשמביאין את המטה לחצר דבשביל הילוך לפי שעה לא קפיד ר\"ש עכ\"ל משמע דאין איסור כשדורסין ע\"ג הקברים לפי (דהכי) [שעה] בהילוך למקום שרוצים לילך שם:","\u0003אא\"כ מצא ראשו ורובו. \u0004פי' וכ\"ש אם נמצא כולו שלם. וכ' רש\"ל הא דאין נוהגין האידנא בדיני מת מצוה האלו לפי שאין הארץ שלנו ואין לנו רשות בכל מקום ואף אם נקבר אותו לשם יש לחוש שהעובדי כוכבים יחזרו ויוציאו אותו כדי לפשוט בגדיו מעליו או משום זלזול ע\"כ מוליכים אותו לבה\"ק מיוחד נ\"ל עכ\"ל:","\u0003וכן עושין ליולדת כו'. \u0004בתשו' מהרי\"ל סימן ס\"ה כתוב וז\"ל על אשה שנפלה מהגג ומתה הורה מהר\"ש אם דם יוצא ממנה אין לטהרה כי הדם יסתלק ממנה ומנהג פשוט לקבור בבגדים כל הרוגים בידי עובדי כוכבי' הנמצאי' לעלות חימה ולנקום נקם אבל יולדת שמתה נסתפקו אם מיתה בידי שמים היא כמו שאר חלאים כו' עכ\"ל. משמע ה\"ה ביולדת אם יוצא ממנה דם דאין לטהרה שלא יסתלק הדם דמ\"ש מנפלה. וכ' מו\"ח ז\"ל בזה יש חילוק בין נפלה מגג להרוג דבהרוג אף אם כבר פסק הדם בשעה שמצאוהו מ\"מ קוברין אותו בבגדיו להעלות חימה משא\"כ בנפלה ולא מתה אלא לאחר כמה ימים על מטתה וכן ביולדת שמתה לאחר ימים יש לטהרה כשאר מתים. וכתב עוד דמי שמת מחמת קור ושלג או נטבע במים בבגדיו דפושטין בגדיו ומטהרין אותו ומלבישין אותו בתכריכין ע\"כ. והמנהג לקבור בבגדים הנמצאים נטבעים וכן יולדת שמתה בר מינן בבגדיה והיותר תמוה שמלבישין בגדים ומנעלים ליולדת שמתה אפי' כמה ימים אחר לידתה והוא שלא כדין לפי ע\"ד:","\u0003ומקומו טהור. \u0004דלא גזרו עליו מפני הנזח ומיהו אסור בהנאה דאיסור דאורייתא הוא ולא פקע רש\"י. והא דאסור בהנאה היינו בקבר בנין כמ\"ש בריש סימן זה:"],"\u0010y0\u0011 \u0010g0\u0011 קֶבֶר שֶׁל בִּנְיָן, אָסוּר בַּהֲנָאָה; אֲבָל קַרְקַע עוֹלָם שֶׁל קֶבֶר, אֵינוֹ נֶאֱסָר. \u0005הַגָּה: \u0010r0\u0011 וְיֵשׁ אוֹמְרִים דְּהַקַּרְקַע שֶׁלָּקְחוּ מִן הַקֶּבֶר וְחָזְרוּ וְנָתְנוּ עָלָיו, \u0010y1\u0011 דְּהָוֵי תָּלוּשׁ וּלְבַסּוֹף חִבְּרוֹ, אָסוּר בַּהֲנָאָה (טוּר בְּשֵׁם הר\"ר יְשַׁעְיָה)\u0006. \u0010y2\u0011 וְיֵשׁ אוֹסְרִין עוֹד לֵישֵׁב עַל הָאֶבֶן שֶׁנּוֹתְנִין עַל הַקֶּבֶר לְמַצֵּבָה \u0005(גַּם זוֹ בִּשְׁמוֹ וכ\"כ הַגָּהוֹת אֲשֵׁרִ\"י בְּשֵׁם אוֹר זָרוּעַ פֶּרֶק אֵלּוּ מְגַלְּחִין)\u0006. \u0010c0\u0011 \u0010r1\u0011 וְיֵשׁ \u0010t0\u0011 חוֹלְקִים וּמַתִּירִים \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. הַכֵּלִים שֶׁחוֹפְרִים וְקוֹבְרִים בָּהֶם, מֻתָּרִים בַּהֲנָאָה, וְאֵין לְהִשְׁתַּמֵּשׁ בָּהֶן אֶלָּא מִדַּעַת הַגַּבַּאי, כְּמוֹ בִּשְׁאָר צְדָקָה \u0005(תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן צ\"ז)\u0006. \u0010g1\u0011 וְהָא דְּקֶבֶר שֶׁל בִּנְיָן אָסוּר לְעוֹלָם, דַּוְקָא שֶׁבְּנָאוֹ לְשֵׁם מֵת, וּנְתָנוֹ בּוֹ \u0010g2\u0011 \u0010r2\u0011 אֲפִלּוּ עַל דַּעַת לְפַנּוֹתוֹ, \u0010g3\u0011 וַאֲפִלּוּ לֹא נָתַן בּוֹ אֶלָּא נֵפֶל. אֲבָל אִם בְּנָאוֹ לִשְׁמוֹ, וְלֹא נְתָנוֹ בּוֹ, מֻתָּר. וְכֵן אִם נְתָנוֹ בּוֹ אַדַּעְתָּא לְפַנּוֹתוֹ, וְלֹא הִזְמִינוֹ מִתְּחִלָּה, מֻתָּר לְאַחַר \u0010g4\u0011 שֶׁפִּנָּהוּ. אֲבָל אִם נְתָנוֹ בּוֹ עַל דַּעַת לִהְיוֹת בּוֹ עוֹלָמִית, אָסוּר אֲפִלּוּ לְאַחַר שֶׁפִּנָּהוּ, אֲפִלּוּ לֹא בְּנָאוֹ לִשְׁמוֹ. \u0010g5\u0011 וְאִם לֹא בְּנָאוֹ לִשְׁמוֹ, וּנְתָנוּהוּ בְּתוֹכוֹ וְהוֹסִיף בּוֹ דִּימוֹס \u0005(פֵּרוּשׁ נִדְבָּךְ, וְהוּא שׁוּרַת בִּנְיַן הַחוֹמָה)\u0006 לִשְׁמוֹ, כֻּלּוֹ אָסוּר, אֲפִלּוּ לְאַחַר שֶׁפִּנָּהוּ וַאֲפִלּוּ שֶׁקְּבָרוֹ שָׁם עַל דַּעַת לְפַנּוֹתוֹ. \u0010g6\u0011 וְאִם מַכִּיר הַדִּימוֹס שֶׁהוֹסִיף לִשְׁמוֹ, מְסִירוֹ, וְהוּא לְבַדּוֹ אָסוּר, וּשְׁאָר הַקֶּבֶר \u0010g7\u0011 מֻתָּר.\nקֶבֶר הַנִּמְצָא, \u0010y3\u0011 \u0010t1\u0011 מֻתָּר לְפַנּוֹתוֹ. פִּנָּהוּ, מְקוֹמוֹ טָהוֹר \u0010y4\u0011 \u0010t2\u0011 וּמֻתָּר בַּהֲנָאָה. \u0010y5\u0011 קֶבֶר הַיָּדוּעַ, אָסוּר לְפַנּוֹתוֹ; \u0010y6\u0011 פִּנָּהוּ, מְקוֹמוֹ טָמֵא \u0010t3\u0011 וְאָסוּר בַּהֲנָאָה. \u0010y7\u0011 \u0010g8\u0011 \u0010t4\u0011 וְהָרַמְבַּ\"ם גּוֹרֵס קֶבֶר הַנִּמְצָא, מֻתָּר לְפַנּוֹתוֹ; \u0010y8\u0011 פִּנָּהוּ, מְקוֹמוֹ טָמֵא וְאָסוּר בַּהֲנָאָה; קֶבֶר הַיָּדוּעַ, אָסוּר לְפַנּוֹתוֹ; פִּנָּהוּ, מְקוֹמוֹ טָהוֹר וּמֻתָּר בַּהֲנָאָה. \u0010g9\u0011\nמֵת מִצְוָה, שֶׁמְּצָאוֹ אָדָם בַּשָּׂדֶה וּקְבָרוֹ שָׁם, \u0010r3\u0011 אֲפִלּוּ שֶׁלֹּא מִדַּעַת בַּעַל הַשָּׂדֶה, אָסוּר לְפַנּוֹתוֹ, שֶׁמֵּת מִצְוָה קוֹנֶה מְקוֹמוֹ. \u0010y9\u0011 \u0010g10\u0011 וְכָל הַמּוֹצְאוֹ צָרִיךְ לְקָבְרוֹ \u0010t5\u0011 בַּמָּקוֹם שֶׁמְּצָאוֹ. \u0010g11\u0011 וְאִם מְצָאוֹ עַל הַמֶּצֶר, שֶׁצָּרִיךְ לְפַנּוֹתוֹ מִשָּׁם מִפְּנֵי הָרַבִּים שֶׁלֹּא יַאֲהִילוּ עָלָיו, אִם מְצָאוֹ בֵּין שְׂדֵה בּוּר \u0005(פיר' שֶׁאֵינָהּ חֲרוּשָׁה וּזְרוּעָה)\u0006 לִשְׂדֵה נִיר \u0005(פֵּרוּשׁ נִיר נֶחֱרַשׁ וְלֹא נִזְרַע)\u0006, מְפַנֶּהוּ לִשְׂדֵה בּוּר. בֵּין שְׂדֵה נִיר לִשְׂדֵה זֶרַע, מְפַנֶּהוּ לִשְׂדֵה נִיר. \u0010g12\u0011 \u0010r4\u0011 בֵּין שְׂדֵה זֶרַע לִשְׂדֵה אִילָן, מְפַנֶּהוּ לִשְׂדֵה זֶרַע. בֵּין שְׂדֵה אִילָן לִשְׂדֵה כֶּרֶם, מְפַנֶּהוּ לִשְׂדֵה אִילָן. וְאִם שְׁתֵּיהֶם שָׁווֹת, מְפַנֶּהוּ לַקָּרוֹב שֶׁבָּהֶם. וְאִם שְׁתֵּיהֶן שָׁווֹת בְּקֵרוּב, מְפַנֶּהוּ לְאֵיזֶהוּ מֵהֶם שֶׁיִּרְצֶה. \u0010g13\u0011 \u0010r5\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, בִּמְצָאוֹ חוּץ לַתְּחוּם. אֲבָל אִם מְצָאוֹ בְּתוֹךְ הַתְּחוּם, מְבִיאוֹ לְבֵית הַקְּבָרוֹת. \u0010g14\u0011 וְאֵינוֹ נִקְרָא מֵת מִצְוָה, \u0010c1\u0011 אֶלָּא אִם כֵּן מָצָא רֹאשׁוֹ \u0010g15\u0011 וְרֻבּוֹ.\nאִם מָצְאוּ יִשְׂרָאֵל הָרוּג, יִקְבְּרוּהוּ כְּמוֹ שֶׁמְּצָאוּהוּ, בְּלֹא תַּכְרִיכִין, וְלֹא יַחְלְצוּ בּוֹ אֲפִלּוּ מִנְעָלָיו. \u0005הַגָּה: \u0010c2\u0011 וְכֵן עוֹשִׂין לְיוֹלֶדֶת שֶׁמֵּתָה, \u0010y10\u0011 אוֹ לְמִי \u0010t6\u0011 שֶׁנָּפַל וָמֵת (מהרי\"ל סִימָן ס\"ה)\u0006. וְיֵשׁ אוֹמְרִים שֶׁמַּלְבִּישִׁין אוֹתָם לְמַעְלָה מִבִּגְדֵיהֶם, תַּכְרִיכִין \u0005(הגהמי\"י בְּשֵׁם ר\"י מִדּוּרָא)\u0006. וְנָהֲגוּ שֶׁאֵין עוֹשִׂין לָהֶם תַּכְרִיכִין כִּשְׁאָר מֵתִים, רַק קוֹבְרִין אוֹתָן בְּבִגְדֵיהֶם, וּלְמַעְלָה מֵהֶם סָדִין, כִּשְׁאָר מֵתִים. \u0010g16\u0011\nקֶבֶר הַמַּזִּיק אֶת הָרַבִּים, כְּגוֹן שֶׁהוּא סָמוּךְ לַדֶּרֶךְ, \u0010r6\u0011 אֲפִלּוּ נִקְבַּר שָׁם מִדַּעַת בַּעַל הַשָּׂדֶה, מֻתָּר לְפַנּוֹתוֹ, \u0010c3\u0011 וּמְקוֹמוֹ טָהוֹר, \u0010y11\u0011 \u0010g17\u0011 וְאָסוּר בַּהֲנָאָה \u0010g18\u0011 \u0010r7\u0011 אִם קָדַם הַקֶּבֶר; אֲבָל אִם קָדַם הַדֶּרֶךְ, מְקוֹמוֹ \u0010y12\u0011 \u0010t7\u0011 מֻתָּר בַּהֲנָאָה. \u0010g19\u0011 \u0010r8\u0011\nקֶבֶר שֶׁפִּנָּהוּ, הֵיכָא דְּמֻתָּר בַּהֲנָאָה, \u0010y13\u0011 לֹא יַעֲשֶׂנּוּ בֵּית \u0010t8\u0011 הַתֶּבֶן וְלֹא בֵּית הָעֵצִים וְלֹא בֵּית הָאוֹצָרוֹת. \u0010g20\u0011 \u0010r9\u0011\nהַחוֹצֵב קֶבֶר לְאָבִיו וּקְבָרוֹ בְּמָקוֹם אַחֵר, \u0010y14\u0011 לֹא יִקָּבֵר בּוֹ הוּא עוֹלָמִית, מִשּׁוּם כְּבוֹד אָבִיו; אֲבָל אַחֵר, מֻתָּר לִקָּבֵר בּוֹ.",{"g":["מסקנת הגמרא סנהדרין דף מ\"ז ע\"ב גבי עובדא דקברא דרב:\n(°) ולפי זה אסור לדרוך ע\"ג הקברות הגהת אשר\"י:","אוקימתא דגמרא שם [מ\"ח ע\"א]:","\u0003כפי' הרמב\"ן בהא דמשני אע\"ג דפנייה:\u0004 ","\u0003ברייתא שם:\u0004 ","\u0003כפירוש הרמב\"ן דהיינו אזמניה וצר ביה:\u0004 ","\u0003ברייתא שם דף מ\"ח ע\"ב:\u0004 ","\u0003מימרא דרפרם וכו'\u0004 שם:","\u0003ברייתא שם דף מ\"ז ע\"ב וכפירוש רש\"י שם:\u0004 ","\u0003בהלכות טומאת מת פ\"ח וכפי' הב\"י ושם בכ\"מ:\u0004 ","\u0003ברייתות ב\"ק דף פ\"א ע\"א וע\"ב:\u0004 ","שם:","\u0003ברייתא שם וכדמפרש לה רב ביבי:\u0004 ","\u0003ברייתא באבל רבתי:\u0004 ","\u0003ירושלמי פרק כהן גדול ונזיר דף נ\"ו:\u0004 ","\u0003ברייתא באבל רבתי וכת\"ק וכן משמע שם בירושלמי בפרק הנזכר:\u0004 ","\u0003הגהות מיימוני בסוף הלכות אבל בשם רבינו אפרים:\u0004 ","\u0003ברייתא סנהדרין דף מ\"ז ע\"ב:\u0004 ","\u0003פי' אם הוא קבר של בנין וע\"ל סעיף א':\u0004 ","\u0003ירושלמי סוף נזיר וכגירסת הטור:\u0004 ","\u0003מרדכי סוף מ\"ק בשם פי\"ג דמסכת שמחות:\u0004 ","\u0003ברייתא סנהדרין דף מ\"ח ע\"א:\u0004 "],"t":["\u0003חולקים. \u0004 כתב מהרש\"ל שהעולם נוהגים איסור לישב על הקבר ובהג\"א כ' דאסור למכור מצבה שנשברה וגם אסור להשען על המצבה משום דאסור בהנאה ומטעם זה אסור לדרוך על הקברים. אך נושאי המטה שדורסין לפי שעה בהילוכן עם המטה משמע דאין איסור כשדורסין על הקברים. עכ\"ל הט\"ז:","\u0003לפנותו. \u0004 ולא חיישינן שמא מת מצוה הוא דמ\"מ קלא אית ליה. ש\"ך \u0005(והוא מפרק נגמר הדין)\u0006:","\u0003בהנאה. \u0004 שאין אדם אוסר דבר שאינו שלו ומיירי בקבר של בנין דאלו במחובר בלא\"ה אין מחובר נאסר וכ\"כ נ\"י וקבר הידוע היינו שנקבר שם מדעת בעל השדה. ש\"ך:","\u0003ואסור. \u0004 דרבנן גזרו עליו טומאה עולמית כדי שלא יפנוהו:","\u0003והרמב\"ם. \u0004 כ' הש\"ך דהכי פירושו קבר הנמצא דהיינו שלא היינו יודעים שהיה שם קבר מותר לפנותו דמסתמא נקבר שם שלא מדעת בעל השדה כיון שלא היה ידוע פנוהו מקומו טמא וכו' כלומר השדה שסביבותיו היכא דאיכא למיחש לקברים וקבר הידוע שאין שם אלא הוא לבדו אסור לפנותו פנוהו מקומו טהור וכו' כיון שידוע שאין שם קברים אחרים. ב\"י עכ\"ל:","\u0003במקום\u0004 \u0003שמצאו. \u0004 וא\"צ להוליכו לקברות וכתב מהרש\"ל ומה שהאידנא אין נזהרים בזה הוא לפי שאין הארץ שלנו ואין לנו רשות לקבור בכל מקום ואף אם נקבר אותו לשם יש לחוש שהעובדי כוכבים יוציאו אותו כדי לפשוט בגדיו מעליו או משום זלזול ע\"כ מוליכין אותו לבה\"ק מיוחד עכ\"ל:","\u0003שנפל. \u0004 במהרי\"ל כתב דאם דם יצא ממנו אז אין לטהר אותו כי הדם יסתלק ממנו אך יקברוהו במלבושיו. וכתב הב\"ח ונראה דהיינו דוקא כשמת במלבושיו אבל בנפלו ולא מת מיד אלא לאחר כמה ימים שכבר פשט מלבושיו וגם אין דם יוצא ממנו שכבר פסק ומת על מטתו מכח אותה נפילה אז ודאי מטהרין אותו ועושין לו תכריכין כשאר המתים על מטתן. ובזה יש חילוק בין נפל מן הגג להרוג דאלו בהרוג ביד עובד כוכבים אע\"פ שבשעה שמצאוהו כבר פסק הדם קוברים אותו כאשר נמצא כדי להעלות חימה ולנקום נקם וזה לא שייך בנפל מן הגג. וכן יולדת שמתה ודם יוצא ממנה אין לטהרה אלא קוברים אותה בלבושיה אבל אם לא מתה רק אחר כמה ימים ושבועות וכבר פסק הדם נוהגים עמה כמו בשאר מתים לטהרה ולעשות לה תכריכין. שוב מצאתי הטעם גבי הרוג דהרי כבר יצאו כל הדמים ממנו והם מובלעים בבגדיו וחיישינן שמא נבלע בתוכן רביעית דם שהנפש יוצאת בו ע\"כ יקברוהו כמו שמצאוהו ולא יחלצו אפי' מנעליו דשמא דם יציאת הנפש הוא בתוך המנעלים וע\"כ נוהגים בהרוג לחפור במרא וחצינא בקרקע במקום שנמצא שם ההרוג וכן כל דמו שיצא ממנו במקום קרוב לו וקוברין העפר שנבלע בו דמו עם ההרוג דשמא באותו הדם יש דם הנפש. ומזה הטעם ג\"כ במי שנפל מן הגג או נפל עליו הבית ומת ונעשה בגופו פצעים וחבורות ויוצא מהם דם וה\"ה ביולדת דרובם אינן מתים אלא מחמת שנעשה באברים הפנימיים שלה פצעים כשכורעת לילד ונבלע דם בכתונת שעל גופה ובשאר בגדים שעליה והדמים שיצאו עם יציאת הנפש נבלעו ג\"כ בתוכן משא\"כ כשאין שם פצעים ולא יצא מהם דם כלל אין קוברין אותם בבגדיהם אלא בתכריכים כשאר מתים ומטהרין אותם. ולפ\"ז מי שמת בדרך בקור גדול נראה דפושטין מלבושיו ומטהרין ומלבישין אותו תכריכים כיון שאין בו פצעים ולא יצא ממנו דם וכן מי שנטבע במים בבגדיו פושטין בגדיו ומטהרין אותו וגם חכריכים מלבישין אותו וכמ\"ש בסוף ס' מהרי\"ל ע\"כ ואני ראיתי בהרבה קהלות נוהגין לטהר כל יולדת ולהלבישה תכריכים ואחר כך מלבישין בגדיה למעלה מהתכריכין ולמעלה מהם הסדין. עכ\"ל הש\"ך:","\u0003מותר. \u0004 שהרי אין אדם אוסר דבר שאינו שלו ולאו כל כמיניה לאסור של רבים. ש\"ך:","\u0003התבן וכו'. \u0004 דגנאי הוא למת לעשות לו כן. ש\"ך:"],"r":["\u0003וי\"א דהקרקע כו' וי\"א כו'. \u0004הג\"א בפ\"ג דמ\"ק בסי' קכ\"ו:","\u0003ויש חולקים כו'. \u0004ממ\"ש בגמ' דסנהדרין בקבר בנין משמע דוקא כה\"ג ואינו מוכרח וגם על הסיפא חולק שאינו נחשב לקבר אלא לציון. טור:","\u0003אפילו ע\"ד לפנותו. \u0004עבה\"ג דאל\"כ אסור לפנותו כמש\"ל סי' שס\"ג ס\"א:","\u0003אפילו שלא מדעת כו'. \u0004סנהדרין מ\"ז ב' וש\"מ:","\u0003(ליקוט) בין שדה כו'. \u0004א\"ר פ\"ד הלכה ל\"ג \u0005(וכ\"ה בירושלמי פ\"ז דנזיר אלא דשם איכא מ\"ד בין שדה אילן לשדה כרם מפנהו לשדה כרם וכ\"פ הרמב\"ם ובספר האשכול) \u0006(ע\"כ):","\u0003(ליקוט) בד\"א כו' ואינו כו'. \u0004ירושלמי שם המוצא מ\"מ ה\"ז מטפל בו וקוברו במקומו אימתי בזמן שמצא חוץ לתחום אבל אם מצאו בתוך התחום ה\"ז מביאו למקום בית הקברות וקוברו אר\"ע כך תחלת תשמישי לפני חכמים פ\"א כו' ושם מה ת\"ל כי קבור תקברנו מכאן שאינו נעשה מת מצוה עד שיהא ראשו ורובו וכן תניא בא\"ר \u0005(כ\"כ בתה\"א וליתא במ\"ש שלנו) \u0006לעולם אינו מ\"מ עד שימצא ראשו ורובו רי\"א השדרה והגלגלת הן הן רובו (ע\"כ):","\u0003אפילו נקבר כו'. \u0004דקאמר שם קבר הידוע כו' וקבר המזיק כו' משמע אפילו קבר ידוע:","\u0003(ליקוט) אם קדם כו'. \u0004ירושלמי סוף נזיר קבר שהוא מזיק את הרבים מותר לפנותו פינהו מקומו טהור ואסור בהנאה הורי ר' אבא בר כהן בכפר עקביא מקומו מותר בהנאה מה ופליג כאן כשקדם את העיר כאן בשקדמתו העיר וכ\"פ בתה\"א (ע\"כ):","\u0003(ליקוט) קבר שפינוהו כו'. \u0004א\"ר פי\"ג (ע\"כ):","\u0003החוצב כו'. \u0004עתוס' שם מ\"ז ב' ד\"ה איתביה כו' אבל הרמב\"ן כתב דסוגיא שם לאביי אבל לרבא בכל ענין אסור:"]}],["הַחוֹפֵר כּוּךְ לַמֵּת, \u0010y0\u0011 פָּטוּר מִקְּרִיאַת שְׁמַע וּמִן הַתְּפִלָּה וּמִן הַתְּפִלִּין וּמִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה. וְאִם הֵם שְׁנַיִם, וְהִגִּיעַ זְמַן קְרִיאַת שְׁמַע, אֶחָד עוֹלֶה וְקוֹרֵא קְרִיאַת שְׁמַע וּמִתְפַּלֵּל, וְחוֹזֵר זֶה וְחוֹפֵר, וְעוֹלֶה חֲבֵרוֹ וְקוֹרֵא קְרִיאַת שְׁמַע וּמִתְפַּלֵּל. וְדַוְקָא כּוּךְ, דְּלֹא חָפִיר לֵיהּ אֶלָּא חַד, אֲבָל אִם הָיָה מָקוֹם שֶׁשְּׁנַיִם יְכוֹלִים לְהִתְעַסֵק בּוֹ כְּאֶחָד, פְּטוּרִים. \u0010y1\u0011\nמַרְחִיקִין הַקְּבָרוֹת מֵהָעִיר חֲמִשִּׁים אַמָּה.",["\u0003פטור כו'. \u0004דעוסק במצוה הוא ופטור משאר מצות:","\u0003מרחיקין כו'. \u0004כתב העט\"ז הטעם שלא יפגעו בו תמיד ויתעצבו ולא דק דהטעם הוא מפני שריחה רע וכדמשמע בלא יחפור ריש דף כ\"ה דקתני מרחיקין את הנבלות ואת הקברות ואת הבורסקי כו' וכן פירש\"י ושאר מפרשים שם וכ\"כ הרמב\"ם והמחבר בח\"מ סי' קנ\"ה סכ\"ג:"],[],"\u0010g0\u0011 הַחוֹפֵר כּוּךְ לַמֵּת, \u0010y0\u0011 פָּטוּר מִקְּרִיאַת שְׁמַע וּמִן הַתְּפִלָּה וּמִן הַתְּפִלִּין וּמִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה. וְאִם הֵם שְׁנַיִם, וְהִגִּיעַ זְמַן קְרִיאַת שְׁמַע, אֶחָד עוֹלֶה וְקוֹרֵא קְרִיאַת שְׁמַע וּמִתְפַּלֵּל, וְחוֹזֵר זֶה וְחוֹפֵר, וְעוֹלֶה חֲבֵרוֹ וְקוֹרֵא קְרִיאַת שְׁמַע וּמִתְפַּלֵּל. \u0010r0\u0011 וְדַוְקָא כּוּךְ, דְּלֹא חָפִיר לֵיהּ אֶלָּא חַד, אֲבָל אִם הָיָה מָקוֹם שֶׁשְּׁנַיִם יְכוֹלִים לְהִתְעַסֵק בּוֹ כְּאֶחָד, פְּטוּרִים. \u0010y1\u0011 \u0010g1\u0011 \u0010t0\u0011\nמַרְחִיקִין הַקְּבָרוֹת מֵהָעִיר חֲמִשִּׁים אַמָּה.",{"g":["\u0003ברייתא ברכות דף י\"ד ע\"ב:\u0004 ","\u0003משנה ב\"ב דף כ\"ה ע\"א:\u0004 "],"t":["\u0003מרחיקין. \u0004 כתב הלבוש הטעם שלא יפגעו בו תמיד ויתעצבו ולא דק שהטעם הוא מפני שריחה רע. וכן משמע בש\"ס דב\"ב פ' לא יחפור. וכן פירש\"י ושאר מפרשים וכ\"כ הרמב\"ם והמחבר בח\"מ סי' קנ\"ה סכ\"ב עכ\"ל הש\"ך \u0005(ואפשר לומר דגם בעל הלבוש ס\"ל האי טעמא משום דריח רע שהרי כתבו בלבוש עיר שושן גבי נזקי שכנים סי' קנ\"ה אלא הא קמ\"ל דאפי' היכא דלא שייך האי טעמא דריח רע כגון שחפרו וקברו אותו בקרקע עמוק עמוק שאין ריח רע יוצא ממנו או באופן אחר דלא שייך בו טעם הנ\"ל מ\"מ תיקנו שירחיק חמשים אמה כדי שלא יראו תמיד ויתעצבו ואולי עי\"כ יעורר עצמו לעשות אבל ובכיה יותר מזמן שקבעו חז\"ל ויענש כמ\"ש חז\"ל ע\"כ הוא בכלל תקנות חז\"ל שלא יתאבל יותר מדאי. וכתב בה\"י אבל במדינתנו לא שייך דין זה בקצת מקומות הקברות באמצע העיר ובקצת מקומות הוא רחוק הרבה מהעיר לפי השתדלות מן השרים)\u0006:"],"r":["\u0003(ליקוט) ודוקא כו'. \u0004כמו מלקט דפטורים אפילו רבים כמש\"ל סי' ת\"ג ועמש\"ש (ע\"כ):"]}],["\u0010y0\u0011 הַמּוֹכֵר קִבְרוֹ וְדֶרֶךְ קִבְרוֹ, מְקוֹם מַעֲמָדוֹ וּמְקוֹם הֶסְפֵּדוֹ, \u0010y1\u0011 בָּאִים בְּנֵי הַמִּשְׁפָּחָה וְקוֹבְרִין אוֹתוֹ בְּעַל כָּרְחוֹ שֶׁל לוֹקֵחַ, וּמַחֲזִירִין אֶת דָּמָיו.\nאִשָּׁה שֶׁיָּרְשָׁה קֶבֶר מִמִּשְׁפַּחְתָּהּ, נִקְבֶּרֶת בְּתוֹכוֹ הִיא, \u0010y2\u0011 אֲבָל לֹא יוֹצְאֵי יְרֵכָה; אֶלָּא אִם כֵּן רָאֲתָה אוֹתָם בְּחַיֶיהָ.\nאָבִיהָ אוֹמֵר: תִּקָּבֵר אֶצְלִי, וּבַעֲלָהּ אוֹמֵר: תִּקָּבֵר אֶצְלִי, תִּקָּבֵר אֵצֶל בַּעֲלָהּ. וְיֵשׁ גּוֹרְסִין תִּקָּבֵר אֵצֶל אָבִיהָ. וְאִם יֵשׁ לָהּ בָּנִים, וְאוֹמֶרֶת: אֵצֶל בָּנַי, קוֹבְרִין אוֹתָהּ אֵצֶל בָּנֶיהָ.\nאָבִיהָ אוֹמֵר: לֹא תִּקָּבֵר אֶצְלִי, וּבַעֲלָהּ אוֹמֵר: לֹא תִּקָּבֵר אֶצְלִי, \u0010y3\u0011 קוֹבְרִים אוֹתָהּ אֵצֶל בַּעֲלָהּ.",["\u0003המוכר קברו כו'. \u0004עי' בח\"מ ס\"ס רי\"ז:","\u0003באים בני המשפחה כו'. \u0004שגנאי להם שבני המשפחה לא יהיו קבורים במקום אחד כמנהגם ואע\"ג דמי שצוה שאל יספידוהו שומעין לו כדלעיל סי' שד\"מ סעיף י' שאני התם דאמר כן בשעת מיתה אבל הכא זוזי אנסוהו א\"נ התם לדידיה לחוד אבל הכא מקום הספדו יורשיו ובני משפחתו נספדים שם ואיכא פגם שלהן:","\u0003אבל לא יוצאי ירכה. \u0004מפני שבניה מתייחסים על שם משפחות אביהם וגנאי לבני משפחתם ליקבר אצלם. טור:","\u0003קוברים אותה אצל בעלה. \u0004מפני שחייב בקבורתה כמו שנתבאר בא\"ע סימן פ\"ט:"],[],"\u0010y0\u0011 \u0010g0\u0011 הַמּוֹכֵר קִבְרוֹ וְדֶרֶךְ קִבְרוֹ, מְקוֹם מַעֲמָדוֹ וּמְקוֹם הֶסְפֵּדוֹ, \u0010y1\u0011 בָּאִים בְּנֵי \u0010t0\u0011 הַמִּשְׁפָּחָה וְקוֹבְרִין אוֹתוֹ בְּעַל כָּרְחוֹ שֶׁל לוֹקֵחַ, וּמַחֲזִירִין אֶת דָּמָיו. \u0010g1\u0011 \u0010r0\u0011\nאִשָּׁה שֶׁיָּרְשָׁה קֶבֶר מִמִּשְׁפַּחְתָּהּ, נִקְבֶּרֶת בְּתוֹכוֹ הִיא, \u0010y2\u0011 אֲבָל לֹא יוֹצְאֵי יְרֵכָה; אֶלָּא אִם כֵּן רָאֲתָה אוֹתָם בְּחַיֶיהָ. \u0010g2\u0011\nאָבִיהָ אוֹמֵר: תִּקָּבֵר אֶצְלִי, וּבַעֲלָהּ אוֹמֵר: תִּקָּבֵר אֶצְלִי, תִּקָּבֵר אֵצֶל בַּעֲלָהּ. \u0010g3\u0011 וְיֵשׁ גּוֹרְסִין תִּקָּבֵר אֵצֶל אָבִיהָ. וְאִם יֵשׁ לָהּ בָּנִים, וְאוֹמֶרֶת: אֵצֶל בָּנַי, קוֹבְרִין אוֹתָהּ אֵצֶל בָּנֶיהָ. \u0010g4\u0011\nאָבִיהָ אוֹמֵר: לֹא תִּקָּבֵר אֶצְלִי, וּבַעֲלָהּ אוֹמֵר: לֹא תִּקָּבֵר אֶצְלִי, \u0010y3\u0011 קוֹבְרִים אוֹתָהּ אֵצֶל בַּעֲלָהּ.",{"g":["\u0003ברייתא ב\"ב דף ק' ע\"ב ומפרש התם משום פגם משפחה:\u0004 ","\u0003ברייתא באבל רבתי וכנוסחת הטור וכ\"כ הרמב\"ן בסת\"ה וכפי פירושו שם:\u0004 ","\u0003באבל רבתי פרק י\"ד וכגירסת הטור:\u0004 ","\u0003כגירסת ספרים שלנו והרמב\"ן בסת\"ה:\u0004 ","שם משום דבעלה חייב בקבורתה:\n(°) (דין חפירת כוכין בח\"ה וחינוכן עיין בא\"ח בסימן תקפ\"ז):"],"t":["\u0003המשפחה. \u0004 שגנאי הוא להם שבני המשפחה לא יהיו קבורים במקום אחד כמנהגם. ש״ך \u0005(ואע״ג דמי שצוה שלא יספידוהו שומעין לו שאני התם דאמר כן בשעת מיתה אבל הכא זוזי אנסוהו. א״נ התם לדידיה לחוד אבל הכא מקום הספדו יורשיו ובני ביתו נספדים שם ואיכא פגם שלהן ועי' בתוס' פרק יש בכור (בכורות דף נ״ב) ד״ה באין בני משפחה)\u0006:"],"r":["\u0003(ליקוט) אשה כו' \u0004עד סוף הסימן הכל בא\"ר פי\"ד (ע\"כ):"]}],["קוֹבְרִים מֵתֵי \u0010y0\u0011 עוֹבְדֵי כּוֹכָבִים וּמְנַחֲמִים אֲבֵלֵיהֶם, מִפְּנֵי דַּרְכֵי שָׁלוֹם.\nלֹא יְהַלֵּךְ בְּבֵית הַקְּבָרוֹת אוֹ בְּתוֹךְ ד' אַמּוֹת שֶׁל מֵת וּתְפִלִּין בְּרֹאשׁוֹ, מִשּׁוּם לֹעֵג לָרָשׁ \u0005(מִשְׁלֵי יז, ה)\u0006, וְאִם הֵם \u0010y1\u0011 מְכֻסִים, מֻתָּר.\nלֹא יְהַלֵּךְ בְּבֵית הַקְּבָרוֹת אוֹ בְּתוֹךְ ד' אַמּוֹת שֶׁל מֵת, אוֹ שֶׁל קֶבֶר, וְסֵפֶר תּוֹרָה בִּזְרוֹעוֹ, וְיִקְרָא בּוֹ \u0010y2\u0011 אוֹ יִתְפַּלֵּל, וְהוּא הַדִּין עַל פֶּה אָסוּר לִקְרוֹת, אֶלָּא אִם כֵּן לִכְבוֹד הַמֵּת, כְּמוֹ שֶׁנִּתְבָּאֵר. \u0005וְעַיֵּן לְעֵיל סִימָן שד\"מ סָעִיף י\"ז.\u0006\nמֻתָּר לִכָּנֵס לְבֵית הַקְּבָרוֹת אוֹ לְתוֹךְ ד' אַמּוֹת שֶׁל מֵת אוֹ שֶׁל קֶבֶר, וְהוּא לָבוּשׁ צִיצִית, וְהוּא שֶׁלֹּא יְהֵא נִגְרָר עַל הַקֶּבֶר. אֲבָל אִם נִגְרָר, אָסוּר מִשּׁוּם: לֹעֵג לָרָשׁ \u0005(מִשְׁלֵי יז, ה)\u0006 בַּמֶּה דְּבָרִים אֲמוּרִים, בִּימֵיהֶם שֶׁהָיוּ מַטִּילִים צִיצִית בַּמַּלְבּוּשׁ שֶׁלּוֹבְשִׁים לְצֹרֶךְ עַצְמָן, \u0010y3\u0011 אֲבָל הָאִדָּנָא שֶׁאֵין אָנוּ לוֹבְשִׁין אוֹתוֹ \u0010c0\u0011 אֶלָּא לְשֵׁם מִצְוָה, אָסוּר, אֲפִלּוּ אֵינָם נִגְרָרִים. וְהָנֵי מִלֵּי כְּשֶׁהַצִּיצִיּוֹת מְגֻלִּים, אֲבָל אִם הֵם מְכֻסִים, מֻתָּר.\nיֵשׁ נוֹהֲגִין לִקְשֹׁר שְׁנֵי צִיצִיּוֹת שֶׁבִּשְׁנֵי כְּנָפַיִם זֶה עִם זֶה כְּשֶׁנִּכְנָסִים לְבֵית הַקְּבָרוֹת, וְלֹא הוֹעִילוּ כְּלוּם בְּתַקָּנָתָם \u0005וְעַיֵּן בא\"ח סִימָן כ\"ג.\u0006\nכֵּיוָן שֶׁהִרְחִיק ד' אַמּוֹת, קוֹרֵא וּמִתְפַּלֵּל, וַאֲפִלּוּ רוֹאֶה הַקֶּבֶר אוֹ בֵּית הַקְּבָרוֹת. וְאִם יֵשׁ שָׁם מְחִצָּה, מֻתָּר אַחַר הַמְּחִצָּה, סָמוּךְ אֲפִלּוּ תּוֹךְ ד' אַמּוֹת לַקֶּבֶר.",["\u0003קוברים כו'. \u0004היינו שמשתדלין בקבורת מתים עובדי כוכבים ועי' טור וב\"י:","\u0003לא יהלך כו'. \u0004עי' בא\"ח סי' מ\"ה ולעיל סי' רפ\"ב ס\"ד:","\u0003או יתפלל כו'. \u0004כתב מהרש\"ל דה\"ה קדיש צריך להרחיק ד' אמות ומביאו הדרישה וכ\"כ הב\"ח:","\u0003אבל האידנא כו'. \u0004כתב מהרש\"ל והעולם נוהגין היתר בטלית קטן וכ\"כ הב\"ח וסיים הטעם כיון שהציציות מכוסים:"],["\u0003אלא לשם מצוה אסור. \u0004כתב רש\"ל והעולם נהגו היתר בטלית קטן עיין בא\"ח סימן כ\"ג עכ\"ל:"],"קוֹבְרִים מֵתֵי \u0010y0\u0011 \u0010g0\u0011 \u0010r0\u0011 עוֹבְדֵי כּוֹכָבִים וּמְנַחֲמִים אֲבֵלֵיהֶם, מִפְּנֵי דַּרְכֵי שָׁלוֹם. \u0010g1\u0011\nלֹא יְהַלֵּךְ בְּבֵית הַקְּבָרוֹת אוֹ בְּתוֹךְ ד' אַמּוֹת שֶׁל מֵת וּתְפִלִּין בְּרֹאשׁוֹ, מִשּׁוּם לֹעֵג לָרָשׁ \u0005(מִשְׁלֵי יז, ה)\u0006, וְאִם הֵם \u0010y1\u0011 \u0010g2\u0011 מְכֻסִים, מֻתָּר.\nלֹא יְהַלֵּךְ בְּבֵית הַקְּבָרוֹת אוֹ בְּתוֹךְ ד' אַמּוֹת שֶׁל מֵת, אוֹ שֶׁל קֶבֶר, וְסֵפֶר תּוֹרָה בִּזְרוֹעוֹ, וְיִקְרָא בּוֹ \u0010y2\u0011 אוֹ יִתְפַּלֵּל, \u0010g3\u0011 וְהוּא הַדִּין עַל פֶּה אָסוּר לִקְרוֹת, אֶלָּא אִם כֵּן לִכְבוֹד הַמֵּת, כְּמוֹ שֶׁנִּתְבָּאֵר. \u0005וְעַיֵּן לְעֵיל סִימָן שד\"מ סָעִיף \u0010g4\u0011 י\"ז.\u0006\nמֻתָּר לִכָּנֵס לְבֵית הַקְּבָרוֹת אוֹ לְתוֹךְ ד' אַמּוֹת שֶׁל מֵת אוֹ שֶׁל קֶבֶר, וְהוּא לָבוּשׁ צִיצִית, וְהוּא שֶׁלֹּא יְהֵא נִגְרָר עַל הַקֶּבֶר. אֲבָל אִם נִגְרָר, אָסוּר מִשּׁוּם: לֹעֵג לָרָשׁ \u0010g5\u0011 \u0005(מִשְׁלֵי יז, ה)\u0006 בַּמֶּה דְּבָרִים אֲמוּרִים, בִּימֵיהֶם שֶׁהָיוּ מַטִּילִים צִיצִית בַּמַּלְבּוּשׁ שֶׁלּוֹבְשִׁים לְצֹרֶךְ עַצְמָן, \u0010y3\u0011 אֲבָל הָאִדָּנָא שֶׁאֵין אָנוּ לוֹבְשִׁין אוֹתוֹ \u0010c0\u0011 אֶלָּא לְשֵׁם מִצְוָה, אָסוּר, אֲפִלּוּ אֵינָם נִגְרָרִים. \u0010g6\u0011 \u0010r1\u0011 וְהָנֵי מִלֵּי כְּשֶׁהַצִּיצִיּוֹת מְגֻלִּים, אֲבָל אִם הֵם \u0010g7\u0011 \u0010t0\u0011 מְכֻסִים, מֻתָּר.\nיֵשׁ נוֹהֲגִין לִקְשֹׁר שְׁנֵי צִיצִיּוֹת שֶׁבִּשְׁנֵי כְּנָפַיִם זֶה עִם זֶה כְּשֶׁנִּכְנָסִים לְבֵית הַקְּבָרוֹת, וְלֹא הוֹעִילוּ כְּלוּם בְּתַקָּנָתָם \u0005וְעַיֵּן בא\"ח סִימָן כ\"ג.\u0006 \u0010g8\u0011\nכֵּיוָן שֶׁהִרְחִיק ד' אַמּוֹת, קוֹרֵא וּמִתְפַּלֵּל, וַאֲפִלּוּ רוֹאֶה הַקֶּבֶר אוֹ בֵּית הַקְּבָרוֹת. וְאִם יֵשׁ שָׁם מְחִצָּה, מֻתָּר אַחַר הַמְּחִצָּה, סָמוּךְ אֲפִלּוּ תּוֹךְ ד' אַמּוֹת לַקֶּבֶר.",{"g":["ברייתא גיטין דף ס\"א ע\"א וכתב הב\"י בפירוש דברי הכל בו שחייב גם כן ללוות את העובד כוכבים אם הוא מפני דרכי שלום או בעובד כוכבים חסיד דקי\"ל חסידי עובדי כוכבים יש להם חלק לעולם הבא:\n[א] [תוספתא שם ספ\"ג וירושלמי ספ\"ה וש\"מ]","\u0003ברייתא ברכות דף י\"ח ע\"א:\u0004 ","\u0003שם בברייתא:\u0004 ","\u0003שם בתוספות:\u0004 ","\u0003מעובדא דרבי חייא ורבי יהונתן שם:\u0004 ","\u0003טור בשם ה\"ר יונה וכ\"כ התוספות שם:\u0004 ","\u0003שם בתוספות:\u0004 ","\u0003ב\"י בא\"ח סי' כ\"ג וע\"ש:\u0004 ","\u0003הרשב\"א בתשובה:\u0004 "],"t":["\u0003מכוסים. \u0004 כתב מהרש\"ל והעולם נוהגין היתר בטלית קטן וכ\"כ הב\"ח וסיים הטעם כיון שהציצית מכוסים וכתב עוד דה\"ה לקדיש צריך להרחיק ד\"א עכ\"ל הש\"ך:"],"r":["\u0003מתי עכו\"ם כו'. \u0004דמש\"ש עם כו' לאו דוקא וכן בירושלמי \u0005(ספ\"ה דגטין) \u0006לא שנו עם בכל אלו וכן בתוספתא \u0005(שם ספ\"ג) \u0006מספידין [וקוברין] מתי עובדי כוכבים ומנחמין אביליהם מפני דרכי שלום. ר\"ן:","\u0003וה\"מ כו'. \u0004עמ\"ש בא\"ח סי' כ\"ג:"]}],["בֵּית הַקְּבָרוֹת, \u0010y0\u0011 אֵין נוֹהֲגִין בָּהֶן קַלּוּת רֹאשׁ; \u0005כְּגוֹן לִפָּנוֹת שָׁם (כָּל בּוֹ)\u0006 אוֹ לֶאֱכֹל וְלִשְׁתּוֹת שָׁם, וְאֵין קוֹרִין וְאֵין שׁוֹנִין שָׁם \u0005(סמ\"ג)\u0006, \u0010y1\u0011 וְאֵין מְחַשְּׁבִין שָׁם חֶשְׁבּוֹנוֹת. \u0005(בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006 ; וְאֵין מַרְעִין בָּהֶם בְּהֵמוֹת; וְאֵין מוֹלִיכִין בָּהֶם אַמַּת הַמַּיִם; וְלֹא יְטַיֵּל בָּהֶם לְקַפַּנְדְרִיָא \u0005(פי' לְמַעֲבָר מִצַד זֶה לְצַד זֶה)\u0006 ; וְלֹא יְלַקֵּט מֵהֶם עֲשָׂבִים; וְאִם לִקֵּט, שֶׁצָּרִיךְ לְלָקְטָן לְצֹרֶךְ בֵּית הַקְּבָרוֹת, \u0010y2\u0011 שׂוֹרְפָן בִּמְקוֹמָן. \u0005הַגָּה: וְכֵן אֵין לִקַּח מִקַּרְקַע עוֹלָם שֶׁל קֶבֶר, אַף עַל גַּב דְּמֻתָּר בַּהֲנָאָה (כֵּן מַשְׁמָע מֵהָרֹא\"שׁ וְהַמָּרְדְּכַי)\u0006. וְכָל זֶה אֵינוֹ אֶלָּא מִשּׁוּם כְּבוֹד הַמֵּתִים, וְלָכֵן אִם צָרִיךְ אוֹתוֹ לִרְפוּאָה, שָׁרֵי \u0005(ג\"ז בְּמָרְדְּכַי)\u0006. וְכֵן מֻתָּר לֵהָנוֹת מֵהָעֲשָׂבִים שֶׁעַל הַקְּבָרוֹת אוֹ פֵּרוֹת אִילָנוֹת שֶׁעֲלֵיהֶם לְצֹרֶךְ הַקְּבָרוֹת, כְּגוֹן שֶׁהַמּוֹשֵׁל עוֹבֵד כּוֹכָבִים מַרְעֶה בְּהֵמוֹת עַל הַקְּבָרִים וְאִי אֶפְשָׁר לִמְחוֹת בְּיָדוֹ כִּי אִם בְּהוֹצָאָה מְרֻבָּה, וְאֵין יַד הַקָּהָל מַשֶּׂגֶת, מוֹכְרִים דְּבָרִים אֵלּוּ כְּדֵי לְהַצִּיל הַקְּבָרוֹת מִיַּד עוֹבְדֵי כּוֹכָבִים, שֶׁזֶּהוּ כְּבוֹד הַמֵּתִים \u0005(ת\"ה סִימָן רפ\"ד ומהרי\"ו סִימָן נ')\u0006. וְאִם אֵין דְּבָרִים עַל הַקְּבָרוֹת לִמְכֹּר לְצֹרֶךְ הַהוֹצָאָה, אִם יַד הַקָּהָל מַשֶּׂגֶת וְשֶׁבְּיָדָם לִמְחוֹת בְּהוֹצָאָה מוּעֶטֶת, צְרִיכִין לִמְחוֹת, אִם אֵין חֲשָׁשׁ בַּדָּבָר שֶׁהַמּוֹשֵׁל יִתְגָּרֶה בָּהֶם עַל יְדֵי זֶה; אֲבָל בְּלָאו הָכֵי אֵין צְרִיכִין לִמְחוֹת \u0005(ג\"ז שָׁם)\u0006.\nאִילָנוֹת שֶׁנּוֹטְעִין בְּבֵית הַקְּבָרוֹת, \u0010y3\u0011 מֻתָּר לְלַקֵּט פֵּרוֹתֵיהֶם, מֵאַחַר שֶׁאֵינָם עַל הַקְּבָרוֹת עַצְמָם.\nקֶבֶר חָדָשׁ, נִמְדָּד וְנִמְכָּר וְנֶחְלָק; וְהַיָּשָׁן, אֵינוֹ נִמְדָּד וְלֹא נִמְכָּר וְלֹא נֶחְלָק.",["\u0003אין נוהגין כו'. \u0004מפני כבודן של מתים:","\u0003ואין מחשבין שם חשבונות. \u0004אפילו של רבים. שם:","\u0003שורפן במקומן. \u0004אין זה כבוד של מתים אלא קנסא או משום שלא יחשדוהו שמוליכם לבהמתו:","\u0003מותר ללקט כו'. \u0004כתב הב\"ח מה שנוהגין הגבאים ללקוט הפירות למכרם והדמים לצדקה ומקצתם נותנים אותם לעובד כוכבים שומר בה\"ק והעובד כוכבים יעשה לו ג\"כ גן בבה\"ק צריך ליזהר שלא יהא אילן נטוע ולא הגן זרוע אלא במקום שאין בו ספק קבר:"],[],"\u0010g0\u0011 בֵּית הַקְּבָרוֹת, \u0010y0\u0011 אֵין נוֹהֲגִין בָּהֶן קַלּוּת רֹאשׁ; \u0005כְּגוֹן לִפָּנוֹת שָׁם (כָּל בּוֹ)\u0006 \u0010r0\u0011 אוֹ לֶאֱכֹל וְלִשְׁתּוֹת שָׁם, \u0010r1\u0011 וְאֵין קוֹרִין וְאֵין שׁוֹנִין שָׁם \u0005(סמ\"ג)\u0006, \u0010y1\u0011 וְאֵין מְחַשְּׁבִין שָׁם \u0010t0\u0011 חֶשְׁבּוֹנוֹת. \u0005(בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006 \u0010g1\u0011 ; וְאֵין מַרְעִין בָּהֶם בְּהֵמוֹת; וְאֵין מוֹלִיכִין בָּהֶם אַמַּת הַמַּיִם; \u0010r2\u0011 וְלֹא יְטַיֵּל בָּהֶם לְקַפַּנְדְרִיָא \u0005(פי' לְמַעֲבָר מִצַד זֶה לְצַד זֶה)\u0006 ; וְלֹא יְלַקֵּט מֵהֶם עֲשָׂבִים; וְאִם לִקֵּט, שֶׁצָּרִיךְ לְלָקְטָן לְצֹרֶךְ בֵּית הַקְּבָרוֹת, \u0010y2\u0011 \u0010g2\u0011 שׂוֹרְפָן בִּמְקוֹמָן. \u0005הַגָּה: \u0010r3\u0011 וְכֵן אֵין לִקַּח מִקַּרְקַע עוֹלָם שֶׁל קֶבֶר, אַף עַל גַּב דְּמֻתָּר בַּהֲנָאָה (כֵּן מַשְׁמָע מֵהָרֹא\"שׁ וְהַמָּרְדְּכַי)\u0006. וְכָל זֶה אֵינוֹ אֶלָּא מִשּׁוּם כְּבוֹד הַמֵּתִים, וְלָכֵן אִם צָרִיךְ אוֹתוֹ לִרְפוּאָה, שָׁרֵי \u0010g3\u0011 \u0005(ג\"ז בְּמָרְדְּכַי)\u0006. \u0010r4\u0011 וְכֵן מֻתָּר לֵהָנוֹת מֵהָעֲשָׂבִים שֶׁעַל הַקְּבָרוֹת אוֹ פֵּרוֹת אִילָנוֹת שֶׁעֲלֵיהֶם לְצֹרֶךְ הַקְּבָרוֹת, כְּגוֹן שֶׁהַמּוֹשֵׁל עוֹבֵד כּוֹכָבִים מַרְעֶה בְּהֵמוֹת עַל הַקְּבָרִים וְאִי אֶפְשָׁר לִמְחוֹת בְּיָדוֹ כִּי אִם בְּהוֹצָאָה מְרֻבָּה, וְאֵין יַד הַקָּהָל מַשֶּׂגֶת, מוֹכְרִים דְּבָרִים אֵלּוּ כְּדֵי לְהַצִּיל הַקְּבָרוֹת מִיַּד עוֹבְדֵי כּוֹכָבִים, שֶׁזֶּהוּ כְּבוֹד הַמֵּתִים \u0005(ת\"ה סִימָן רפ\"ד ומהרי\"ו סִימָן נ')\u0006. וְאִם אֵין דְּבָרִים עַל הַקְּבָרוֹת לִמְכֹּר לְצֹרֶךְ הַהוֹצָאָה, אִם יַד הַקָּהָל מַשֶּׂגֶת וְשֶׁבְּיָדָם לִמְחוֹת בְּהוֹצָאָה מוּעֶטֶת, צְרִיכִין לִמְחוֹת, אִם אֵין חֲשָׁשׁ בַּדָּבָר שֶׁהַמּוֹשֵׁל יִתְגָּרֶה בָּהֶם עַל יְדֵי זֶה; אֲבָל בְּלָאו הָכֵי אֵין צְרִיכִין לִמְחוֹת \u0005(ג\"ז שָׁם)\u0006. \u0010g4\u0011\nאִילָנוֹת שֶׁנּוֹטְעִין בְּבֵית הַקְּבָרוֹת, \u0010y3\u0011 \u0010t1\u0011 מֻתָּר לְלַקֵּט פֵּרוֹתֵיהֶם, מֵאַחַר שֶׁאֵינָם עַל הַקְּבָרוֹת עַצְמָם. \u0010g5\u0011\nקֶבֶר חָדָשׁ, נִמְדָּד וְנִמְכָּר וְנֶחְלָק; וְהַיָּשָׁן, אֵינוֹ \u0010t2\u0011 נִמְדָּד וְלֹא נִמְכָּר וְלֹא נֶחְלָק.",{"g":["\u0003ברייתא מגילה דף כ\"ט ע\"א:\u0004 ","\u0003שם וכתב הרא\"ש וכ\"כ המרדכי בשם ר\"י דמיירי בקרקע שלא חפרו כלל ומשום כבודן של מתים:\u0004 ","שם וכתב המרדכי משום קנס או משום שלא יחשדוהו שמוליכו לבהמתו:\n(°) (ע\"ל ריש סי' שס\"ד בהג\"ה):","מעובדא דקבריה דרב סנהדרין דף מ\"ז ע\"ב:\n(°) מה שהתוספות כתבו שם במגילה דאילנות שנוטעין בהם מותרים וכו' מאחר שאינן על הקברים עצמן וכ\"כ הרא\"ש וכן פירש בש\"ע בסעיף ב' והמרדכי התיר גם הגנות שאינם נטועים על הקברים והביאם הבית יוסף נלע\"ד דרמ\"א איירי בהנך דעל הקברים עצמן:","\u0003שם בתוס' וכן כתב הרא\"ש והמרדכי שם:\u0004 ","\u0003ברייתא באבל רבתי פרק י\"ד:\u0004 "],"t":["\u0003חשבונות. \u0004 אפילו הם של רבים. ש\"ך:","\u0003ללקט. \u0004 כ' הב\"ח מה שנוהגין הגבאים ללקוט הפירות למוכרם והדמים לצדקה ומקצתם נותנים לעובד כוכבים שומר בית הקברות וגם עושה לו העובד כוכבים גן בבה\"ק צריך ליזהר שלא יהא אילן נטוע ולא הגן זרוע אלא במקום שאין שם ספק קבר עכ\"ל:","\u0003נמדד. \u0004 כתב הטור פי' שאין מודדין אותו כמה מתים נקברים במקצתם שיתנו אותה מדה למתים אחרים כנגדו ולא נמכר משום פגם משפחה ולא נחלק בין היורשין אלא כולם נקברים שורות שורות לעצמן והכל משום כבודן של מתים ובה\"ק חדש שאין נקבר בו אלא א' לא חששו לכבודו עכ\"ל:"],"r":["\u0003או לאכול כו' ואין כו'. \u0004דזהו קלות ראש כמש\"ש בבה\"כ שם כ\"ח א' וערש\"י שם ד\"ה אין אוכלין כו':","\u0003ואין קורין כו'. \u0004משום לעג לרש כמ\"ש בסי' שס\"ז:","\u0003(ליקוט) ולא יטייל כו'. \u0004א\"ר רפי\"ד (ע\"כ):","\u0003וכן אין ליקח כו'. \u0004מדברי המדרכי שכתב והא דאמרינן בפ\"ו דסנהדרין \u0005(מ\"ז ב') \u0006קבריה דרב כו' לרפואה שאני וכמש\"ו:","\u0003וכן מותר כו'. \u0004וראיה מחזקיה שקצץ דלתות היכל כו' להציל שאר המקדש. שם:"]}],["הַכֹּהֵן \u0010c0\u0011 מֻזְהָר שֶׁלֹּא לִטָּמֵא בְּמֵת, וְלֹא לְכָל טֻמְאוֹת הַפּוֹרְשׁוֹת מִמֶּנּוּ, וְלֹא \u0010c1\u0011 לְגוֹלָל, וְלֹא לְדוֹפֵק, וְלֹא לְאֵבֶר מִן הַחַי שֶׁאֵין בּוֹ כְּדֵי לְהַעֲלוֹת אֲרוּכָה אִם הָיָה \u0010y0\u0011 מְחֻבָּר, וְלֹא לְאִילָן הַמֵּסֵךְ עַל הָאָרֶץ וַעֲנָפָיו מֻבְדָּלִים זֶה מִזֶּה וְטֻמְאָה תַּחַת אֶחָד \u0010c2\u0011 מֵהֶן וְאֵין יָדוּעַ תַּחַת אֵיזֶה, אוֹ אֲבָנִים הַיּוֹצְאִים מֵהַגָּדֵר וְטֻמְאָה תַּחַת אֶחָד מֵהֶם וְאֵין יָדוּעַ תַּחַת אֵיזֶה, וְכֵן שָׂדֶה שֶׁנֶּחֱרַשׁ בּוֹ קֶבֶר וְאֵין יָדוּעַ מְקוֹמוֹ \u0010y1\u0011 \u0010c3\u0011 וְכָל אֶרֶץ הָעַמִּים, אָסוּר לְכֹהֵן לִטָּמֵא בָּהֶן. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּכֹהֲנִים אֲסוּרִים \u0010y2\u0011 לִטָּמֵא לְחֶרֶב שֶׁנִּטְמָא בְּמֵת (כָּל בּוֹ בְּשֵׁם סֵפֶר יְרֵאִים ותשו' רַשְׁבָּ\"א בְּשֵׁם רַבּוֹתֵינוּ הַצָרְפָתִים)\u0006, וְיֵשׁ מְקִלִּין \u0005(תְּשׁוּבַת רַשְׁבָּ\"א שָׁם בְּשֵׁם הָרַאֲבַ\"ד וְעַיֵּן בתוס' דְּנָזִיר בַּאֲרִיכוּת)\u0006, וְכֵן נָהֲגוּ לְהָקֵל וְאֵין נִזְהָרִין מִזֶּה.",["\u0003ולא לאילן כו'. \u0004אע\"פ שאין כאן אלא ספק טומאה הכהן מוזהר עליו ומוכח מכאן דאילן המיסך על המת דיכול לעמוד תחת ענפיו שאינם מאהילין על המת דהרי כאן לא אסר לעמוד תחת האילן אלא מטעם דאינו ידוע תחת איזו. פרישה:","\u0003וכל ארץ העמים כו'. \u0004פירוש בזמן שהיה א\"י בטהרה אסור לכהן לילך מארץ ישראל לארץ העמים שהוא חוצה לארץ שהיו העובדי כוכבים קוברים מתיהם בכל מקום:","\u0003ליטמא לחרב. \u0004דחרב הרי הוא כחלל וה\"ה לכל מיני מתכות:"],["\u0003הכהן מוזהר שלא ליטמא למת. \u0004) אפי' נפל כדאיתא פרק בתרא דאהלות שמא קברו בו נפלים:","\u0003לגולל. \u0004הוא אבן שנותנין על הקבר לציון ודופק היינו לפעמים סומכין אבן באבנים קטנים. טור:","\u0003ואין ידוע תחת איזה כו'. \u0004משמע דאם ידוע תחת איזה מהם מותר לכהן לעמוד תחת אחרים שאינם מאהילים:","\u0003וכל ארץ העמים כו'. \u0004זה קאי בזמן שהיה טהרות בא\"י:"],"הַכֹּהֵן \u0010c0\u0011 \u0010g0\u0011 מֻזְהָר שֶׁלֹּא \u0010t0\u0011 לִטָּמֵא בְּמֵת, \u0010g1\u0011 וְלֹא לְכָל טֻמְאוֹת הַפּוֹרְשׁוֹת מִמֶּנּוּ, \u0010g2\u0011 וְלֹא \u0010c1\u0011 \u0010t1\u0011 לְגוֹלָל, וְלֹא לְדוֹפֵק, וְלֹא לְאֵבֶר מִן הַחַי \u0010g3\u0011 שֶׁאֵין בּוֹ כְּדֵי לְהַעֲלוֹת אֲרוּכָה אִם הָיָה \u0010y0\u0011 מְחֻבָּר, וְלֹא לְאִילָן \u0010t2\u0011 הַמֵּסֵךְ עַל הָאָרֶץ וַעֲנָפָיו מֻבְדָּלִים זֶה מִזֶּה וְטֻמְאָה תַּחַת אֶחָד \u0010c2\u0011 מֵהֶן וְאֵין יָדוּעַ תַּחַת אֵיזֶה, אוֹ אֲבָנִים הַיּוֹצְאִים מֵהַגָּדֵר וְטֻמְאָה תַּחַת אֶחָד מֵהֶם וְאֵין יָדוּעַ תַּחַת אֵיזֶה, וְכֵן שָׂדֶה שֶׁנֶּחֱרַשׁ בּוֹ קֶבֶר וְאֵין יָדוּעַ מְקוֹמוֹ \u0010y1\u0011 \u0010c3\u0011 \u0010r0\u0011 וְכָל אֶרֶץ הָעַמִּים, אָסוּר לְכֹהֵן לִטָּמֵא בָּהֶן. \u0005הַגָּה: \u0010r1\u0011 יֵשׁ אוֹמְרִים דְּכֹהֲנִים אֲסוּרִים \u0010y2\u0011 לִטָּמֵא לְחֶרֶב שֶׁנִּטְמָא בְּמֵת (כָּל בּוֹ בְּשֵׁם סֵפֶר יְרֵאִים ותשו' רַשְׁבָּ\"א בְּשֵׁם רַבּוֹתֵינוּ הַצָרְפָתִים)\u0006, וְיֵשׁ מְקִלִּין \u0005(תְּשׁוּבַת רַשְׁבָּ\"א שָׁם בְּשֵׁם הָרַאֲבַ\"ד וְעַיֵּן בתוס' דְּנָזִיר בַּאֲרִיכוּת)\u0006, וְכֵן נָהֲגוּ לְהָקֵל וְאֵין נִזְהָרִין מִזֶּה.",{"g":["\u0003פשוט בפרשת אמור:\u0004 ","\u0003ברייתא בת\"כ והביאו הכ\"מ בריש פ\"ג מהלכות אבל אדברי הרמב\"ם שם:\u0004 ","\u0003ממשנה נזיר דף נ\"ד ע\"א ומשמעות ברייתא דמסכת שמתות כל טומאה מן המת וכו'\u0004 דמשמע דנהי דמלקי לא לקי אבל איסורא איכא:","כן הוא ברמב\"ם ריש פ\"ג מהלכות טומאת מת וכמ\"ש הכ\"מ שם ממשנה ג' פרק ו' דעדיות:\n(°) פי' בזמן שא\"י היה בטהרה היה אסור לכהן לילך מא\"י לח\"ל. מהרש\"ל:"],"t":["\u0003במת. \u0004 אפי' נפל כדאיתא בפ' בתרא דאהלות שמא קברו בו נפלים. ט\"ז \u0005(אבל טומאת נבילות ושרצים אין הכהן מוזהר מליגע בהן)\u0006 \u0005(בה\"י)\u0006:","\u0003לגולל. \u0004 הוא אבן שנותנים על הקבר לציון. ודופק היינו שלפעמים סומכין האבן באבנים קטנים טור \u0005(ורש\"י פי' גולל זה כיסוי הארון ודופק הוא דופן של צדדים. כתובות דף ד')\u0006:","\u0003המיסך: \u0004 \u0005(אע\"פ שאין כאן אלא ספק טומאה הכהן מוזהר עליו)\u0006 ומוכח מכאן דאילן המיסך על המת דיוכל לעמוד תחת ענפיו שאינם מאהילין על המת דהרי כאן לא נאסר לעמוד תחת האילן אלא מטעם דאינו ידוע תחת איזה. פרישה:"],"r":["\u0003וכל ארץ כו'. \u0004פ\"ד דעירובין \u0005(מ\"ז א') \u0006וש\"מ הרבה:","\u0003(ליקוט) י\"א כו'. \u0004ר\"ל לכלי מתכות והוא דעת ר\"ת דלא אמרינן כלים הנוגעים במת שיהיו כמוהו אלא דוקא בכלי מתכות כמ\"ש תוס' דנזיר נ\"ד ב' בד\"ה ומשני והר\"ש בפ\"ק דאהלות וכ\"ד רש\"י \u0005(בפסחים י\"ד ב' וש\"מ) \u0006וראב\"ד \u0005(כפ\"ה מהלכות טומאת מת) \u0006אבל הרי\"מ ור\"י ורמב\"ם ורמב\"ן דש\"פ חולקין ע\"ז ודעתם שה\"ה בכל הכלים ובגדים לבד מכ\"ח שאינם נעשים אב הטומאה לעולם וראיה ממתני' ריש אהלות דסתם ארבעה כו' וקאמר בכולם כלים סתם ועוד דכלים הנוגעים באדם שיהא כמוהו לא גמרינן מחלל חרב אלא מוכבסתם בגדיכם כו' כמ\"ש בספרי אלא דבשאר טומאת בגדים דוקא בעורו נוגע וכאן אפילו לאחר פרישתו וע\"כ צ\"ל כל הכלים וה\"ה לרישא ובריש חולין ובפ\"ק דפסחים \u0005(י\"ד י\"ט ב'. ואצ\"ל הא דשבת ק\"א ב' עבתוס' שם) \u0006ובפ\"ח דפסחים לא גרסינן חרב הרי הוא כחלל דהא לא מחלל חרב גמיר וכן א\"צ שם לזה \u0005(עיין משנה למלך פ\"ה מה' ט\"מ) \u0006וכ\"כ הר\"ש בריש אהלות שם וכן קאמר בספרי הא למדנו לכלים ואדם כלים באדם מנין כו' אלמא בכל כלים הוא וכנ\"ל ועוד הביא ר\"י ראיה מתוספתא פ\"ו דכלים החמת כו' ע\"ש בתוס' ור\"ש אע\"ג שדחק ר\"ת מ\"מ פשטא דמתני' וברייתא כדברי הרמב\"ם. ולעיקר דינא דכאן הנה דעת ר\"ת בתוס' הנ\"ל דהנזיר מגלח על חרב בחלל ושלכן לא אוקמוהו גמרא שם בבלי מתכות כמ\"ש בתוס' שם וא\"כ ה\"ה דכהן מוזהר עליו כמ\"ש בתוספתא \u0005(פ\"ג דמכות) \u0006ופ\"ד דשמחות כל טומאה שהנזיר מגלח עליה כהן מוזהר כו' וזהו ג\"כ ראיה לשיטתו דדוקא מתכות מדפריך גמ' והני כו' \u0005(וע\"ש בתוס' שהניחו בצ\"ע לשיטת הרי\"מ אבל הרמב\"ן בב\"ב כ' א' תירץ דא\"צ הזאה אלא הנוגע או מאהיל במת עצמו שכן משמעות המקראות. וכ\"כ רבינו בליקוטיו) \u0006ולפ\"ז אסור ג\"כ ליכנס לאהל שהכלי שם שדעתו שם ג\"כ שמטמא באהל כמ\"ש בתוס' שם ובפ\"ב דב\"ב כ' א' ד\"ה בחבית ובחולין ק\"ד א' בד\"ה חלת ובפ\"א דשבת \u0005(י\"ז א') \u0006וש\"מ \u0005(ואינו כן דעת הרמב\"ם ועיין בא\"ר ריש כלים) . \u0006אבל ש\"פ חולקין עליו דאין הנזיר מגלח ואין הכהן מוזהר עליה \u0005(משמעות הלשון שבתוספתא ומ\"ש דמ\"מ איסורא מיהא איכא ועב\"י ובספר האשכול) \u0006כמ\"ש בתוספתא דאהלות והביאו תוס' שם והר\"ש בפ\"ק דאהלות כל המטמא במת טומאת שבעה כו' כלים בכלים כו' בד\"א בתרומה וקדשים אבל אין הנזיר מגלח אלא על המת בלבד ואין חייבים על טומאת מקדש וקדשיו אלא על המת בלבד וכמ\"ש בספ\"ז דנזיר כלל אר\"י כל כו' וכ\"כ הרמב\"ם בפ\"ז מהלכות נזירות אבל לענין טומאת מקדש וקדשיו פסק בפ\"ה מהלכות טומאות מת שהנוגע במת והנוגע בו חייב מכאן ואילך פטורין והוא כר' יוחנן \u0005(בירושלמי פ\"ז דנזיר) \u0006(ע\"כ):"]}],["מִי שֶׁנִּשְׁבְּרָה מַפְרַקְתּוֹ \u0010y0\u0011 וְרֹב בָּשָׂר עִמָּהּ, וְכֵן מִי שֶׁנִּקְרַע \u0010y1\u0011 מִגַּבּוֹ כְּדָג, אֲפִלּוּ עֲדַיִן הוּא חַי, חָשִׁיב כְּמֵת, וּמְטַמֵּא. אֲבָל גּוֹסֵס, וּמִי שֶׁנִּשְׁחֲטוּ בּוֹ ב' סִימָנִים אוֹ פָּצוּעַ פְּצָעִים הַרְבֵּה, אֵינָם מְטַמְּאִין, עַד שֶׁתֵּצֵא נַפְשָׁם; \u0010y2\u0011 וּמִכָּל מָקוֹם אָסוּר לִכָּנֵס לְבַיִת שֶׁיֵּשׁ בּוֹ גּוֹסֵס. \u0005וְיֵשׁ מַתִּירִין, (ר\"ן סוֹף מַ\"ק וּמָרְדְּכַי פֶּרֶק אֵלּוּ מְגַלְּחִין בְּשֵׁם בה\"ג)\u0006, \u0010y3\u0011 וְטוֹב לְהַחְמִיר.",["\u0003ורוב בשר עמה כו'. \u0004ומשמע בש\"ס דחולין (דף כ\"א) דבזקן אפילו בלא רוב בשר מטמא באהל וכ\"כ מהרש\"ל פ\"ק דחולין סימן מ\"ד ומשמעותו התם דאם נעשה גיסטרא שנחתך לרחבו בצואר כולה או בשדרה עד חללה או שנחלק לשנים מטמא באוהל וכ\"כ מהרש\"ל שם:","\u0003מגבו כו'. \u0004אבל מלפניו לא:","\u0003ומ\"מ אסור ליכנס כו'. \u0004פי' אע\"פ שטומאה אין כאן חילול יש כאן:","\u0003וטוב להחמיר. \u0004והב\"ח כתב דמדינא צריך ליזהר ואין כאן מקום לפסוק לקולא ע\"ש מיהו נראה דא\"צ להקיצו ולהגיד לו כשיש גוסס כמו שצריכין להקיצו כשיש מת כדלקמן סי' שע\"ב וכן אם הגידו לו והוא ערום מותר להמתין עד שילבש עצמו ואח\"כ יצא וקרוב הדבר לומר שא\"צ לצאת כלל מבית שיש בו גוסס דהכי משמע לישנא דאסור ליכנס לבית כו' משמע דוקא ליכנס אסור אלא שנכון להחמיר ולצאת כי מדברי המרדכי ושאר פוסקים משמע דאין חילוק:"],[],"\u0010g0\u0011 מִי שֶׁנִּשְׁבְּרָה מַפְרַקְתּוֹ \u0010y0\u0011 \u0010t0\u0011 וְרֹב בָּשָׂר עִמָּהּ, וְכֵן \u0010g1\u0011 מִי שֶׁנִּקְרַע \u0010y1\u0011 מִגַּבּוֹ כְּדָג, אֲפִלּוּ עֲדַיִן הוּא חַי, חָשִׁיב כְּמֵת, וּמְטַמֵּא. אֲבָל \u0010g2\u0011 גּוֹסֵס, וּמִי \u0010g3\u0011 שֶׁנִּשְׁחֲטוּ בּוֹ ב' סִימָנִים אוֹ פָּצוּעַ פְּצָעִים הַרְבֵּה, אֵינָם מְטַמְּאִין, עַד שֶׁתֵּצֵא נַפְשָׁם; \u0010y2\u0011 \u0010g4\u0011 \u0010r0\u0011 וּמִכָּל מָקוֹם אָסוּר לִכָּנֵס לְבַיִת שֶׁיֵּשׁ בּוֹ גּוֹסֵס. \u0005וְיֵשׁ מַתִּירִין, (ר\"ן סוֹף מַ\"ק וּמָרְדְּכַי פֶּרֶק אֵלּוּ מְגַלְּחִין בְּשֵׁם בה\"ג)\u0006, \u0010y3\u0011 וְטוֹב \u0010t1\u0011 לְהַחְמִיר.",{"g":["\u0003מימרא דרב יהודה וכו'\u0004 חולין דף כ\"א ע\"א:","\u0003מימרא דר' יוחנן ושמואל וכו'\u0004 שם:","\u0003ציינתיו לעיל סימן של\"ט:\u0004 ","\u0003הרי\"ף והרא\"ש ממימרא דרב יהודה וכו'\u0004 גיטין דף ע' ע\"ב:","\u0003טור וכדעת בה\"ג הביאו אביו הרא\"ש דגרסי בנזיר דף מ\"ג אברייתא אלהחלו וכו'\u0004 פלוגתא דאביי ורבא והלכה כרבא לגבי אביי וכת\"ק דברייתא דאין הלכה כר' מחביריו וכ\"כ ההג\"א בפ\"ג דמ\"ק:"],"t":["\u0003ורוב. \u0004 ומשמע בש\"ס דחולין דבזקן אפי' בלא רוב בשר מטמא באהל וכ\"כ מהרש\"ל פ\"ק דחולין. ומשמעותו התם דאם נעשה גיסטרא שנחתך לרחבו בצואר כולה או בשדרה עד חללה או שנחלק לשנים מטמא באהל עכ\"ל הש\"ך:","\u0003להחמיר. \u0004 והב\"ח כתב דמדינא צריך ליזהר ואין כאן מקום לפסוק לקולא ע\"ש מיהו נראה דאין צריך להקיצו ולהגיד לו כשיש גוסס כמה שצריכים לעשות כשיש מת כמו שכתב בסימן שע\"ב וכן אם הגידו לו והוא ערום מותר להמתין עד שילביש עצמו ואח\"כ יצא עכ\"ל הש\"ך:"],"r":["\u0003ומ\"מ כו' ויש מתירין. \u0004עתוס' דנזיר מ\"ג א' ד\"ה ומהכא כו':"]}],["\u0010y0\u0011 אָסוּר לְכֹהֵן לִכָּנֵס תַּחַת אֹהֶל שֶׁהַמֵּת תַּחְתָּיו, אֲפִלּוּ הוּא גָּדוֹל הַרְבֵּה, וַאֲפִלּוּ לְבַיִת אַחֵר אוֹ לַעֲלִיָּה אַחֶרֶת, הַפְּתוּחִים לְאוֹתוֹ בַּיִת \u0010c0\u0011 בְּנֶקֶב שֶׁיֵּשׁ בּוֹ טֶפַח עַל טֶפַח, וּבַיִת לְאוֹתוֹ בַּיִת, עַד עוֹלָם; וְאִם סָתַם הַנֶּקֶב, מֻתָּר לוֹ לִכָּנֵס לַבַּיִת \u0010y1\u0011 הָאַחֵר, שֶׁהַסְתִימָה חוֹצֶצֶת, אֲפִלּוּ לֹא בִּטְּלוּ לִהְיוֹת שָׁם עוֹלָמִית. וְהָנֵי מִלֵּי, שֶׁסָתַם כָּל הַנֶּקֶב; אֲבָל אִם לֹא סָתַם כָּל הַנֶּקֶב, אֶלָּא מִעֲטוֹ מִטֶּפַח, אִם נְתָנוֹ לִהְיוֹת שָׁם עוֹלָמִית, מְמַעֵט וְחוֹצֵץ בִּפְנֵי הַטֻּמְאָה שֶׁלֹּא תַּעֲבֹר; וְאִם לָאו, אֵינוֹ מְמַעֵט. \u0005הַגָּה: \u0010y2\u0011 \u0010c1\u0011 וְכָל דָּבָר הַמְקַבֵּל טֻמְאָה אֵינוֹ חוֹצֵץ בִּפְנֵי הַטֻּמְאָה (הַגָּהַת אַלְפָסִי פֶּרֶק בְּנֵי הָעִיר ובהל' טֻמְאָה לְהָרִי\"ף וְרַמְבַּ\"ן וְרֹא\"שׁ וּמָרְדְּכַי רֵישׁ פֶּרֶק לֹא יַחְפֹּר)\u0006. וְלֹא מִקְרֵי סְתִימָה בְּחַלּוֹן, \u0010c2\u0011 אֶלָּא אִם כֵּן יָכוֹל לַעֲמֹד בְּלֹא סְמִיכָה \u0005(ג\"ז שָׁם)\u0006.\nאֲרֻבָּה שֶׁבֵּין בַּיִת לַעֲלִיָּה וְאֵין בָּהּ פּוֹתֵחַ טֶפַח, וְכַזַּיִת מֵהַמֵּת לְמַטָּה בַּבַּיִת כְּנֶגֶד \u0010y3\u0011 \u0010c3\u0011 הָאֲרֻבָּה, הַבַּיִת טָהוֹר וְהָעֲלִיָּה טְמֵאָה. \u0010y4\u0011\nשְׁנֵי חֲדָרִים פְּתוּחִים לְבַיִת, וּבְכָל אַחַת חֲצִי זַיִת מֵהַמֵּת, וְדַלְתוֹתֵיהֶם נְעוּלִים, \u0010y5\u0011 \u0010c4\u0011 הַבַּיִת טָמֵא וְהֵם טְהוֹרִים; וְאִם נִפְתְחוּ, גַּם הֵם טְמֵאִים. \u0010y6\u0011\nחָצֵר הַמֻּקֶּפֶת זִיזִין וְאַכְסַדְרָאוֹת, וְטֻמְאָה בְּאֶחָד מֵהַבָּתִּים, \u0010y7\u0011 \u0010c5\u0011 אִם כָּל פִּתְחֵי הַבָּתִּים וְהַחַלּוֹנוֹת נְעוּלִים, טֻמְאָה יוֹצֵאת לְתַחַת הַזִּיזִין וְהָאַכְסַדְרָאוֹת; \u0005וְהַטַּעַם, מִשּׁוּם דְּהוֹאִיל וְסוֹף הַטֻּמְאָה לָצֵאת דֶּרֶךְ שָׁם, רוֹאִין כְּאִלּוּ יָצְאָה; \u0010y8\u0011 וְלָכֵן יֵשׁ מַחְמִירִין לְכֹהֲנִים לֵילֵךְ דֶּרֶךְ שַׁעַר הָעִיר שֶׁסּוֹף הַמֵּת לָצֵאת מִשָּׁם (פִּסְקֵי מהרא\"י סִימָן כ\"ה וְכָל בּוֹ)\u0006, \u0010c6\u0011 וְיֵשׁ מַתִּירִין \u0005(שָׁם הֵבִיא בְּשֵׁם י\"א)\u0006, וְהַמֵּקֵל לֹא הִפְסִיד בְּמָקוֹם שֶׁלֹּא נָהֲגוּ לְהַחְמִיר; \u0010y9\u0011 וְאִם נִפְתַּח \u0010y10\u0011 חַלּוֹן אוֹ פֶּתַח מִצַּד הָאַחֵר, וְאוֹתָם שֶׁל צַד הֶחָצֵר כֻּלָּם נְעוּלִים, אֵין הַטֻּמְאָה יוֹצֵאת לְתַחַת הַזִּיזִין. \u0010c7\u0011 וְאִם נִפְתַּח גַּם כֵּן אֶחָד מֵהֶן לְצַד הַזִּיזִין, הַטֻּמְאָה יוֹצֵאת מֵהַבַּיִת לְתַחַת הַזִּיזִין. \u0010y11\u0011 וְכֵן אִם טֻמְאָה תַּחַת הַזִּיזִין, \u0010c8\u0011 נִכְנֶסֶת מִתַּחְתֵּיהֶן לַבַּיִת; \u0010y12\u0011 לָכֵן \u0010y13\u0011 גַּגִּים הַבּוֹלְטִים לְמַעְלָה לְחוּץ עַל פִּתְחֵי הַבָּתִּים, וְטֻמְאָה בְּאֶחָד מֵהַבָּתִּים, \u0010c9\u0011 כָּל הַבָּתִּים \u0010y14\u0011 שֶׁפִּתְחֵיהֶם פְּתוּחִים, טְמֵאִים. \u0005הַגָּה: ב' גַּגִּין שֶׁאֵין נוֹגְעִין זֶה בָּזֶה, אַף עַל פִּי שֶׁאֵין בֵּינֵיהֶם רַק פָּחוֹת מִג', לֹא הָוֵי חִבּוּר לַטֻּמְאָה, דְּלֹא אַמְרִינָן לָבוּד לְהַחְמִיר (מהרי\"ו בִּפְסָקָיו)\u0006. \u0010y15\u0011 וְאִם הָיוּ זֶה לְמַעְלָה מִזֶּה, אַף עַל פִּי שֶׁאֵינָן נוֹגְעִים, אַמְרִינָן: חָבוּט רָמֵי, וּכְאִלּוּ נוֹגְעִים \u0005(נ\"י בְּהִלְכוֹת \u0010y16\u0011 טֻמְאָה רי\"ף)\u0006. הַכֹּהֲנִים \u0010c10\u0011 אֵינָן יְכוֹלִין לָכֹף לִקְרוֹבֵי הַמֵּת שֶׁיּוֹצִיאוּ הַמֵּת מִמְּקוֹמוֹ, כְּדֵי שֶׁהֵם יִהְיוּ רַשָּׁאִים לִכָּנֵס לְבֵיתָם, אִם לֹא בְּמָקוֹם שֶׁדֶּרֶךְ לְהוֹצִיא כָּל הַמֵּתִים \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ס\"ה)\u0006. \u0010y17\u0011\nאָסוּר לִקְרַב בְּתוֹךְ אַרְבַּע אַמּוֹת שֶׁל מֵת אוֹ שֶׁל קֶבֶר. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁאֵין הַקֶּבֶר מְסֻיָּם בִּמְחִצּוֹת גְּבוֹהוֹת י' טְפָחִים, אֲבָל אִם הוּא מְסֻיָּם בִּמְחִצּוֹת גְּבוֹהוֹת עֲשָׂרָה טְפָחִים, אוֹ בְּחָרִיץ עָמֹק י' טְפָחִים, אֵין צָרִיךְ לְהַרְחִיק מִמֶּנּוּ אֶלָּא ד' טְפָחִים. \u0010y18\u0011 \u0005וּמֻתָּר לְכֹהֵן לַעֲמֹד אֵצֶל בַּיִת שֶׁיֵּשׁ בּוֹ מֵת, וּמֻתָּר לִגֹּעַ בִּכְתָלָיו, וּבִלְבַד שֶׁלֹּא יְהֵא שׁוּם דָּבָר מַאֲהִיל עָלָיו (תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן קל\"ו)\u0006.\nמֵת הַמּוּנָח בִּסְפִינָה, \u0010y19\u0011 אִם הִיא קְטַנָּה שֶׁמִּתְנַדְנֶדֶת כְּשֶׁדּוֹרְכִין בָּהּ, \u0010c11\u0011 אָסוּר לְכֹהֵן לִכָּנֵס בָּהּ.",["\u0003אסור לכהן ליכנס כו'. \u0004כתב הרוקח סימן שס\"ו אשת כהן שמעוברת מותרת ליכנס באהל המת דס\"ס הוא שמא נפל הוא או שמא נקבה הוא:","\u0003שהסתימה חוצצת כו'. \u0004ובמשנה פ\"ח דאהלו' אית' דסריגות שבחלונות חוצצין פירוש שאם היה חלון בין ב' בתים והטומאה בבית א' והיו עצים דקים או טסי ברזל בחלונות בסירוג בקלוע אע\"פ שיש ביניהם אויר כיון שאין שם פותח טפח אף באחד מהנקבים הרי זה חוצץ ולא יצטרפו נקבי הסריגות לפותח טפח וכ\"פ הרמב\"ם סוף פרק י\"ג מהל' טומאת המת וכ\"כ הסמ\"ג סוף עשין רל\"א וכן כתב הב\"ח:","\u0003וכל דבר המקבל טומאה כו'. \u0004עי' ברמב\"ם בהלכות כלים מהו הן הדברים המקבלים טומאה או לאו:","\u0003הבית טהור כו'. \u0004דטומאה בוקעת ועולה כיון שהיא מונחת תחת הארובה ואע\"פ שאין בארובה פותח טפח ואין הטומאה מתפשטת לצדדי הבית הואיל שיש מקום לטומאה לעלות לארובה שכנגדה ואינה חוזרת ויורדת לבית כיון שאין בארובה טפח שאם היה בארובה טפח הוה חשבינן בית ועליה כמו חדר א':","\u0003שני חדרים פתוחים לבית. \u0004היינו כששני החדרים כל א' מהם פתחו פתוח לבית בפני עצמו ושניהם הם לפנים מן הבית:","\u0003הבית טמא כו'. \u0004דסוף הטומאה לצאת ורואה אני כאלו שני החצאי זיתים מונחים בבית ואין הטומאה נכנסת בחדרים כיון שדלתותיהם נעולות אבל כשנפתחו חזרה הטומאה מן הבית לחדרים:","\u0003חצר המוקפת כו'. \u0004כלומר בתי החצר המה סביב לצד החצר ולא לצד הב' דהיינו אחורי החצר לכל בית יש ב' פתחי' וכן חלונות א' פתוח לצד השני לאחורי החצר אשר אין שם זיזין:","\u0003אם כל פתחי הבתים והחלונות נעולים כו'. \u0004כצ\"ל ור\"ל כשכל דלתות הבית שהטומאה בתוכו נעולות מכל צד בין אותו צד הפתוח לחצר בין אותו צד שאחורי החצר אז טומאה יוצאת לתחת הזיזין ואכסדראות וכל מה שתחתיהן טמא דכיון דאין מקום לטומאה לצאת אלא דרך שם חזינן לטומאה כאלו כבר הוא שם דגזרו חכמים על כל המקומות שסוף הטומאה לצאת כאחד ואין ידוע דרך איזה יצא אבל לא נ\"מ מידי במה ששאר פתחי הבית פתוחים או נעולים דמ\"מ הטומאה יוצאת לתחת הזיזין והאכסדראות אי נמי אשמועינן דאם היו שאר פתחי הבית פתוחים אז היו ג\"כ הבתים הפתוחים טמאים וכל מה שבתוכה היה טמא כי הטומאה יוצאת לתחת הזיזין כיון שסוף הטומאה לצאת ואח\"כ יוצאת מתחת הזיזין ונכנסת לבתי' הפתוחי':","\u0003ולכן יש מחמירין כו'. \u0004אמנם אין להחמיר בבית של צדוק הדין דאדרבה אותו הפתח בא לטמא את האהל פסקי מהרא\"י שם וכתב בספר מע\"מ ד' קי\"ח סוף ע\"א שטעם זה יספיק בבית צדוק הדין שאין בו אלא פתח אחד שבו מכניסין ומוציאין את המת אבל אם יש בו ב' פתחים שבפתח האחד מכניסין ובפתח אחד מוציאין כמו שיש בבית צדוק הדין שבק\"ק פראג יש להחמיר שאין לכהני' ליכנס באותו הפתח שמוציאין ממנו המת:","\u0003ואם נפתח חלון או פתח מצד האחר. \u0004שאחורי החצר שבאותו הפתח יצא שהרי לצד החצר הוא נעול:","\u0003חלון או פתח. \u0004שיש בו ד' על ד' כן הוא בעט\"ז והוא מדברי הרא\"ש:","\u0003וכן אם טומאה תחת הזיזין נכנסת מתחתיהן לבית. \u0004היינו כשהבית פתוח:","\u0003וכן גגין הבולטין כצ\"ל. \u0004כתב מהרש\"ל והאחרונים בשם תשובת מהר\"ח א\"ז במקום שיש עירוב ועשו קורות שיש בהקיפן טפח ממבוי למבוי וראשי הקורות נכנסין תחת הגגין שמכאן ומכאן והטומאה נכנסת תחתיה והקורה מביאה הטומאה מגג לגג ומתפשטת בכל הבתים מכאן ומכאן א\"כ כשיש מת ב\"מ באחד מן הבתים נמצא שהמבוי מחובר ע\"י קורות העירוב ע\"כ וכ' הב\"ח שהקור' צריך שתהי' עגולה ג\"ט כדי שתהיה רחבה טפח דכל שיש בהקיפו ג\"ט רחבו טפח:","\u0003גגין הבולטין כו'. \u0004כתב דרישה הכל תלוי בגג שע\"ג הפתח הבית שהמת בתוכו ומשם באה מהגג שלפני הפתח להגג של הבית ואף שאין הבתים סמוכים זה אצל זה אלא שיש מחיצה ביניהם מן הצד אף שאין עליה גג קטן אם הקורה מונח עליה רחב טפח דהא כשהטומאה באה מהפתח לגג והגג מקיף את כל הבית הרי טומאה מתחת הגג שהוא מן תחת אותה מחיצה ואותה מחיצה מביא הטומאה תחת גג הבית הסמוך לה ונכנסה תוכו דרך (בתים) [פתחים] או חורין אבל כשאין גג ע\"ג פתח הבית שהמת בתוכו אף שיש לו גג מן הצד והוא מאהיל על הבתים שסמוכים לה מכל צד אין הטומא' באה שם ומה שרגילין לומר אם הוא מוקף חומה גבוהה אותה חומה אין בה נ\"מ כ\"א לענין צד שלפני הפתח או אם אין חומה גבוהה לפני פתח הבית שהמת בתוכו ויש חומה בבית הסמוך לו בצד שלפני הפתח באופן שלא יביא הטומאה מגג של מת לתחת הגג שלפני פתח הבית הסמוך אף שמן הצד ליכא חומה מפסקת והגגות מאהילין זה על זה לית לן בה עכ\"ל. ול\"נ שצריך שיהא גג אהל טפח מתחלה עד סוף אבל כל שיש ביניהם הפסק בחומה גבוהה אף שהיא עבה כמה טפחים כיון שאין אהל טפח שוב אין לטומאה מקום לילך וכן הסכימו רבים וגדולים) וכן המנהג פשוט:","\u0003שפתחיהן פתוחים טמאים. \u0004אבל אם הן סתומים טהורים ולפ\"ז אף כשהטומאה באה באיזה בית אם דעת הכהנים לסגור פתח בתיהן וחלונותיהן ולא לצאת מהן עד אחר הוצאת המת אין צריכין לצאת מבתיהן וכ\"כ בדרישה ולפ\"ז כהן שהוא בבית או בחדר שהטומא' נוגעת אליו והוא נעול בדלת וחלונות ונודע לו שהגיע הטומא' אליו אסור לצאת מן החדר עד אחר הוצאת המת שהרי כל זמן שלא נפתח החדר לא נכנסת הטומאה לתוכו וכשיפתח תכנס הטומאה לתוכו:","\u0003ואם היו זה למעלה מזה כו'. \u0004כתב הב\"ח דאפילו היה הגג העליון הרבה למעלה משלשה טפחים כיון שיש בגגו טפח אמרי' חביט רמי כו' ע\"ש:","\u0003הכהנים אינם יכולים כו'. \u0004כתב הב\"ח נ\"ל דאם הוא נפל דליכא משום כבוד כופין אותו להוציאו ממקומו כדי שיכנסו לביתם:","\u0003אסור לקרב תוך ארבע אמות כו'. \u0004כ' הדרישה מכאן מוכח דאפילו תוך ד' אמות של מת המונח לפנינו אסור לקרב כהן משום דתופס ד\"א או משום גזרה שמא יגע במת עצמו אף שהוא מונח לפנינו והכל יודעים שאסור ליגע במת מ\"מ לא מחשב כמו מחיצה גבוהה י' טפחים וכן המרדכי והג\"מ כתבו דאסור וב\"י הביאם ע\"ש ולא כמו ששמעתי מקילין לכהן הדורש לעמוד עליו אפי' תוך ארבע אמות של מת כיון שהמת מונח לפנינו וניכר עכ\"ל. ולי נראה שטעם אותן המקילין דדוקא במת שמונח בבית בהך גוונא דמיירי הטור וכן בהך דמרדכי וה\"מ במת המונח בספינה דהוי כמונח בבית שהוא מקום קביעתו תופס ארבע אמות אבל לא המונח על המטה וכן מחלק הרוקח סימן שט\"ו וז\"ל מת בביתו סתום אסור לכהן ליקרב בתוך ארבע אמות דמת תופס ד' אמות לטומאה כשהוא בקבר אבל כשהוא במטה שמוציאין אותו ובעת צדוק הדין מעמידין אותו אינו תופס דאין שם קביעותו עכ\"ל. ומ\"ש מעמידין אותו נראה דכ\"ש כשנושאין אותו על המטה דאין תופס:","\u0003ומותר לכהן לעמוד כו'. \u0004ואין חילוק בין בית פתוח או סתום לענין זה והב\"ח כתב דיש להחמיר דאף בבית סתום אם פרץ פצימתו ומת בתוכו תופס ד' אמות סביביו וצריך להרחיק ארבע אמות מהבית ע\"כ וכ\"כ הרוקח סימן שט\"ו מת בבית סתום אסור לכהן ליקרב בתוך ד' אמות:","\u0003אם היא קטנה שמתנדנדת כשדורכים בה אסור ליכנס בה. \u0004אפי' חוץ לד\"א של מת כיון שא\"א שלא יסיט הטומאה אבל אם היא גדולה שאינה מתנדנדת כשדורכים בה מותר חוץ לארבע אמות של מת:"],["\u0003בנקב שיש בו טפח. \u0004פירוש במקום אחד אבל אם אינו במקום אחד אלא ע\"י צירוף יש טפח כגון מה שקורין גיגאטי\"ר שעשוי ע\"י סירוג ויש שם נקבים קטנים הרבה אין זה מביא הטומאה והוא משנה פרק י\"ג דאהלות הסירוגות מצטרפות למלא מקדח דברי בית שמאי וב\"ה אומרים עד שיהא כמלא מקדח במקום אחד ומבואר שם בין להביא הטומאה ובין להוציא ופשוט הוא דדין שיעור מקדח בחלון שעשוי לאורה שוה לשיעור טפח בחלון העשוי לתשמיש כמבואר בפ' הנ\"ל וכ\"פ רמב\"ם להדיא פרק י\"ד דטומאת מת דדוקא בעינן טפח במקום א' ואם לאו הרי היא כסתומה. וכ\"כ הרמב\"ם בפירוש המשנה בפרק ח' דאהלות גבי סריגת החלון ועיין מה שכתבתי מזה לקמן סעיף ד' על דברי הדרישה:","\u0003וכל דבר המקבל טומאה. \u0004זה קאי גם ארישא דסותם כל הנקב דמועיל אפילו אין מבטלו שם מ\"מ בעינן שלא יהא דבר המקבל טומאה אלא צריך לסתמו בעץ או באבן דבר שאינו כלי כמ\"ש בית יוסף בשם לשון הרי\"ף:","\u0003אא\"כ יכול לעמוד בלא סמיכה. \u0004בפרק לא יחפור סוף (בבא בתרא דף י\"ט) כתבו התוס' טעם לזה דכל שצריך סמיכה מקרי סתימת עראי ועוד טעם אחר שהסמיכה לא תהיה על ידי דבר שהוא מקבל טומאה אע\"פ שהדבר עצמו שסותם הוא אינו מקבל טומאה מכל מקום כיון שהדבר שסומכו מקבל טומאה הוה כאלו הוא עצמו מקבל טומאה וכ\"פ הר\"ש והרמב\"ם בפ\"ו דאהלות במשנה דקוברי המת שהיו עוברין כו' ופשוט הוא לדברי הכל כל שמושיב באותו חלון עצים ואבנים כל כך הרבה עד שכותלי החלון מחזיקים אותם זה ודאי מהני וחוצץ דאין זה בכלל סמיכה כלל כנ\"ל פשוט:) \u0003ומעשה \u0004שהי' בטומאה שהיתה בבית סמוך לבית הכנסת באופן שהיתה נכנסת דרך חלון ביהכ\"נ של נשים וצוה מורה אחד לסתום החלון באותו פרוכת קטן שתלוי שם בקרסי הברזל תמיד שהוא לצניעות שתולין אותו שם הנשים בשעה שאינן צריכין לראות ביהכ\"נ של אנשים ואמרתי שטעה המורה דבהדיא אמרינן במתניתין דפ' ח' דאהלות דסדין ומחצלת העשוין כאהלים שחוצץ בפני הטומאה אבל אם אין עשוים כאהלים אין חוצץ וכתב שם הר\"ש כל שהוא עשוי כאהל חוצץ אע\"ג דמקבל טומאה ואם אין עשוי כאהל אינו חוצץ וביאר ברמב\"ם פרק י\"ג דטומאת מת שאין עשוי כאהל אלא מתוח בלבד ואין להם שיפוע אהלים ואין שם כתלים עכ\"ל וה\"ה כאן שאין כאן אלא סתימה על החלון ולא כותל ולא אהל ותו דאותו הפרוכת תלוי בטבעות של ברזל נמצא דהברזל עושה הקיום ובהדיא כ' רמב\"ם פרק י\"ח דטומאת מת אם הגיף א' את הדלת וסמכו במפתח כדי שלא יטמא את הבית וכן אם היה אדם מבפנים או בחוץ סומך את הדלת אם יכול הדלת לעמוד בפני עצמו הבית טהור ואם לאו הבית טמא לפי שהאדם והכלים הוא שחוצץ בפני הטומאה והאדם והכלים מביאין את הטומאה ואינם חוצצין עכ\"ל וכן כתבו התוס' בפרק לא יחפור (בבא בתרא דף י\"ט) בד\"ה רואין כו' לענין אם סגר הדלת במפתח דבעינן דבר החוצץ עומד על ידי דבר שאינו מקבל טומאה ולשונם אזכיר בסמוך ה\"ה נמי כאן שהטבעות של ברזל מעמידין את הפרוכת והם כלים וא\"ל ממ\"ש במשנה דכלים דף כ\"א דטבעות כלים טהורות דהא איתא בפרק במה בהמה (שבת דף נ\"ב) ברש\"י וז\"ל ומיהו עם הרצועה מקבלת טומאה אלא שאין מקבלת טומאה לעצמה עכ\"ל ממילא כאן שהטבעות עם אותו פרוכת הוה ודאי שם כלי עליהם והוה כמפתח ותו נראה דאפי' אם אינו מקבל טומאה מ\"מ אינו חוצץ וזה מוכח ממה דקשה תרי משניות אהדדי לכאורה דבפי\"א דכלים שנינו כל כלי מתכות שיש לו שם בפני עצמו טמא חוץ מן הדלת ומן הנגר ומן המנעול והפותה שתחת הציר (והציר) [והצינור] שנעשו לקרקע פי' הרמב\"ם שתשמישן עם הקרקע משמע מזה דכלים אלו ובתוכן מנעול שנועל בו בית לא מקבל טומאה ובפרק ו' דאהלות שנינו קוברי המת שהיו עוברים באכסדרה והגיף אחד מהם את הדלת וסמכו במפתח פירש הרמב\"ם שהיה שער הבית קצת פתוח והחזיק אחד מהנושאים לנעול שער הבית במפתח אשר בו עכ\"ל אם יכול הדלת לעמוד בפני עצמו טהור פירש ר\"ש דאם יכולה לעמוד בלא סמיכת המפתח ה\"ל מפתח כמאן דליתיה ואם לאו טמא דכל דבר הנסמך באדם וכלים אין חוצץ בפני הטומאה משמע מזה דמפתח שהדלת נעול בו מקבל טומאה וע\"כ אינו חוצץ ובתוס' פרק לא יחפור (בבא בתרא דף י\"ט) כתוב טעם למה אמרינן דאם ינטלו אינם יכולים לעמוד דאינו חוצץ וז\"ל והיינו טעמא דסתימת עראי היא כיון שאינו יכול לעמוד בפני עצמו אי נמי משום דבעינן דבר החוצץ עומד על ידי דבר שאינו מקבל טומאה ומיהו בפי' משניות מצא ר\"י דמפרש דאפי' במפתח שאינו מקבל טומאה איירי ומטעמא דלא חשיב אהל לחוץ בפני הטומאה כיון שעומד ע\"י כלי אע\"ג דאינו מקבל טומאה עכ\"ל נ\"ל דהתו' באו לפרש המשנה דאהלות שזכרנו ולתרץ קושיא שזכרנו דתחלה תירצו דמפתח לאו דוקא אלא כל דבר שבעולם אם בא לסמוך בו דבר החוצץ אינו חוצץ ולא תליא מילתא במקבל טומאה אלא סתימה מעלייתא בלא שום סמיכה בעינן ואח\"כ כתבו דדוקא מפתח נקט שהוא מקבל טומאה ולא מיירי בההוא גוונא דמיירי בכלים שזכרנו דהתם המנעול אין מקבל טומאה דנעשה תחלה לצורך תשמיש קרקע אבל באהלות מיירי ממפתח דעלמא שלא נעשה לקרקע והוא מקבל טומאה ואח\"כ כתבו שבפי' המשניות ס\"ל דודאי מפתח דוקא נקט דאינו חוצץ כיון שהוא על כל פנים כלי מה שאין כן במידי דאינו כלי לגמרי ולא תליא מילתא בטומאה ומתני' דאהלות מיירי אפי' במפתח שנעשה לקרקע דאין מקבל טומאה הנה לפנינו דמפתח שנועלין בו הדלת פשיטא דאינו חוצץ ואפי' אינו מקבל טומאה אלא אפי' שאר דבר שאינו כלי לגמרי אין יכול לסמוך בו הדלת לתירוצא קמא ובמרדכי פרק לא יחפור כתב כתירוצא קמא דצריך שיהיה עומד שם בחלון בלא סמיכת דבר אחר וכ\"כ רמ\"א בסי' זה בסמוך. ואע\"ג דבמרדכי הביא שם עוד מתני' דהגפת מפתח לא מהני אע\"פ שאינו מקבל טומאה לא נתכוין שיהיה עכ\"פ כלי דהא פסק כתירוצא קמא כמו שזכרתי אלא בא לתקן בזה שלא נימא דבטומאה תליא מילתא תדע דהא לא זכר שיהיה דוקא כלי. ממילא נשמע מזה דלא מועיל חציצת דלת או חלון כל שאינה יכולה לעמוד בלא צירים של ברזל או שאר דבר של ברזל אע\"פ שהם לצורך קרקע וזה מועיל שלא יקבלו טומאה מ\"מ אינם חוצצים כמו שזכרנו ולפ\"ז הא דאמרי' בסעיף ד' דמהני נעילת מפתחים לחצון היינו אם הם בענין שיכולים לעמוד בלא שום סמיכה ולא ביש לה צירים של ברזל דאל\"כ אינם חוצצין דהוה כמפתח של משנה דאהלות ועיין מה שאכתוב לקמן שלא לסמוך להקל כדברי הדרישה לנעול הבית כדי לחוץ. ועל כן בודאי אינו חוצץ ומטעם זה יראה דאם יש סתימה בחלון של ברזל שהוא עשוי כמו סבכה שקורין בלשון אשכנז גיגאטי\"ר והוא של ברזל אינו מועיל כיון שהוא מקבל טומאה) ואינו עשוי כעין אהל ועיין מה שכתבתי מזה בסעיף ד' שעל פי זה אין להתיר לכהן להיות בבית ולסתום הפתח והחלון:","\u0003הבית טהור והעליה טמאה. \u0004לפי שהטומאה עולה כנגדה מאחר שהיא מונחת תחת הארובה והוה כאלו אין שם אהל עליה ואין לה כח לירד ולהחזיר הטומאה לבית מאחר שאין בה פותח טפח כ\"פ הרא\"ש בהלכות קטנות ואין להקשות יהיה פתח הבית ההוא טמא משום שסוף הטומאה לצאת דרך אותה פתח כמו דאמרינן אחר כך בסי' זה דכאן שאין שם רק כזית מן המת ועליו אין אהל הוה כמונח ברשות הרבים ואינו מטמא כלל בבית כנ\"ל פשוט ובחנם האריך על זה בדרישה.) ומזה למדנו שאם יש מת בבית בחדר שאין עליו אהל אין לכהן להיות בכל הבית הן מטעם שהטומאה חוזרת ויורדת הן מטעם שסוף הטומאה לצאת דרך הפתח דלא הקיל הרא\"ש כאן אלא אם אין פתח רק פחות מטפח:","\u0003הבית טמא והם טהורים. \u0004הואיל ואין בכל אחד אלא חצי זית שהוא חצי שיעור והבית טמא דסוף הטומאה לצאת דרך שם ורואין כאלו שני חצאי זיתים מונחים בבית ואין הטומאה נכנסת בחדרים כיון שדלתותיהם נעולים: \u0003דלא אמרינן לבוד להחמיר. \u0004לכאורה משמע אבל להקל אמרינן לבוד והוא תמוה דא\"כ לא תמצא טומאה יוצאת או נכנסת דרך נקב דנימא כלבוד דמי והוה סתום ועיינתי במקור דכתב מהרי\"ו וז\"ל הר\"ר יעקב שאלני אם אמרינן לבוד גבי אהל המת כגון ב' בתים הסמוכים זה לזה בבנין פחות מג' טפחים ומת באחד מהם והשבתי לו דלא אמרי' לבוד וראיה מפ\"ק דעירובין גבי עור העסלא ובסוכה פרק הישן גבי קורות הבית שאינם מכוונות עי\"ש בגמרא ורש\"י עכ\"ל ועיינתי בפ\"ק דעירובין כתבו שם התוספות דבטומאה לא אמרינן לבוד ולא זכרו מחומרא כלל ובפרק הישן (סוכה דף כ\"ב) אמרינן אבל אין ביניהם פותח טפח ביניהן ועל גביהן טהור פרש\"י וה\"ה באין מכוונות שע\"ג טהור ותחתיה טמא דכיון שיש בה טפח מביאה טומאה לכל אורך שתחתיה עכ\"ל משמע דהטומאה יורדת למטה ומטמא מה שבתחתונה דאין שם חציצה ואי ס\"ד דאמרינן לבוד לקולא אמאי יטמא מה שבתחתונה אע\"פ שלא אמרינן חבוט רמי מ\"מ להוי כסתום ויהיה חציצה לטהר מה שלמטה אלא ודאי לטומאה לא אמרינן כלל לבוד וא\"כ צריכין לומר מ\"ש רמ\"א כאן דלא אמרינן לבוד פי' אפי' להחמיר:","\u0003אם כל פתחי הבתים נעולים כו'. \u0004כן הוא גם בטור אבל הוא לאו דוקא דהעיקר תלוי בפתח הבית שהמת בתוכו דסוף הטומאה לצאת דרך שם ע\"כ מטמא אע\"פ שהוא נעול אבל בבתים אחרים מאי מעלה יש בנעילתם וכן מה שכ' אח\"כ דאותם של צד החצר כולם נעולים הלא אפי' אם הם פתוחים רק שאותו פתח של בית שהטומאה בתוכו הוא נעול אין הטומאה יוצאת תחת הזיזין כיון שיש פתח לצד אחר להבית שהמת בתוכו ורבים אומרי' שיש ט\"ס בדברי הטור וצ\"ל אם כל פתחי הבית כו' וכן אח\"כ צ\"ל ואותו של צד החצר נעול וכן הוא ברא\"ש דלא זכר רק אותו פתח שהמת בתוכו שיש לו שני פתחים אחד לצד הזיזין ואחד לצד המבוי ותליא מילתא איזה מהם פתוח דאמרינן שם תצא הטומאה:","\u0003ויש מתירין. \u0004טעם לזה דלא אמרינן סוף הטומאה לצאת טמא אלא באותו פתח שמוציאין תחילה מתוך האהל ולא מתוך האויר הואיל ובאותה יציאה נטהר האוהל ע\"כ אותו פתח יטמא ולא מכאן ואילך:","\u0003ואם נפתח ג\"כ אחד מהם. \u0004פי' אותו שהמת בתוכו נפתח ג\"כ לצד הזיזין דהיינו שנפתח אותו הבית משני צדדיו על כן גם תחת הזיזין טמא אף על פי ששאר בתים שתחתיה נעולים וכמו שזכרנו בסמוך:","\u0003נכנסת מתחתיהן לבית. \u0004פי' כל בית שפתחו פתוח לצד הזיזין:\n\u0003רש\"ל \u0004הביא הג\"ה אחת וז\"ל אני אומר במקום שיש עירוב ועשו קורות שיש בהם היקף טפח ממבוי למבוי וראשי הקורות נכנסין תחת הגגין שמכאן ומכאן והטומא' נכנסת תחתיה הקורה מביאה את הטומאה מגג לגג ומתפשטת בכל הבתים מכאן ומכאן אם כן כשיש מת ב\"מ באחד מן הבתים אין כהן רשאי להיות בשום בית מן הבתים שבמבואות המחוברות ע\"י קורה של העירוב וזוכרני כשהיינו לומדים בבית מורי ר\"מ ז\"ל והיה פתח פתוח מחצר הרב לחצר בית הכנסת ומשקוף הפתח היה מגיע מצד א' תחת תקרת הבית שהיה בו מת ואסר מורי לכהנים לצאת ולבוא דרך אותו הפתח כל זמן שהמת בבית ע\"כ לשון תשובת מהר\"ר חיים. וכתוב בדרישה ונראה לע\"ד וגם שמעתי דהיינו דוקא במחיצה שיש עליה גג קטן או מחיצה שמשקוף עליה רוחב טפח ויש בו פתח פתוח לצאת ולבוא דרך תוכה דנמצא שם משקוף עליה כיון שנכנסין ויוצאים דרך תוכה אבל מחיצה מושכת מבית לבית ואין גג עליו וגם אין פתח פתוח בתוך המחיצה אפי' אם הקורה המונח עליו בעובי טפח וגם גגות הבתים משני צדדי המחיצה בקצה שלהם מאהילים עליהם מכל מקום אינו מביא הטומאה כיון דבאמצעית המחיצה אין עליה גג ולא שם תקרה כיון שאין שם פתח נקרא כסתום באמצע ואין בו כח להוליך הטומאה עכ\"ל משמע מדבריו באם יש מחיצה פנויה בלא גג עליה ויש פתח באמצעיתה מביאה את הטומאה מבית לבית כיון שמראש המחיצה יש שם אוהל מן הגג של בית הטמא אע\"פ שאין הפתח מגיע עד אותו החלק שהוא תחת הגג והיינו כיון שיש שם משקוף עליו מאחר שנכנסין ויוצאין שם ותמיהני מאד על דבר זה כיון שיש הפסק בחלק המחיצה שהוא סותם קודם התחלת הפתח בין החלק שמגיע תחת הגג ובין פתח מי יכניס הטומאה מן תחת הגג להפתח שבאמצע והלא אפילו ביש הפסק בפחות משלשה לא אמרינן לבוד להחמיר וע\"כ לא אסרו שם בתשובה שהבאתי בשם רש\"ל אלא שהתקרה היתה מונחת בלא מחיצה תחתיה מן תחת הגג של בית הטמא לתחת הגג של בית אחר נמצא שהיה חלל תחת התקרה מן בית הטמא לבית האחר בלי הפסק מחיצה סתומה מה שאין כן בהך מילתא שיש הפסק מחמת המחיצה הבנויה על הארץ ואין בה בליטה טפח סמוך לחלק שתחת הגג השני ודאי אין כאן הבאת טומאה כלל מידי דהוה אשני בתים סמוכים ואין גג בולט למעלה מהם דאין נכנסת הטומאה מבית לבית אע\"פ ששניהם פתוחים דהא גגים בולטים בעינן כמ\"ש בשולחן ערוך כאן ונראה דאין לחוש לטומאה כשיש מחיצה בנויה אע\"פ שיש פתח באמצעה לא בתוך המחיצה כולה אלא אם כן יש עליה גם כן גג קטן או בליטה טפח מן אותו צד שנכנס תחת בית הטמא לחלק המגיע תחת הגג השני:","\u0003כל הבתים שפתחיהם פתוחים כו'. \u0004הטעם שכיון שיש גגין על הפתח של הבתים כולם ובאחד מהן יש שם מת הטומאה הולכת דרך פתח ביתו תחת הגגין ונכנסת לבתים אחרים שהם פתוחים תחת הגג שלהם אבל אם אין גג על הפתחים וכותלי הבתים שאצל הבית הטמא הם סתומים עד הגג שלהם מן החצר אין טומאה לאותן הבתים אע\"פ שהם פתוחים לצד הרחוב אע\"פ שגג אחד יש מבית הטמא מן הצד לבית שאצלו מ\"מ אין מקום לטומאה להכניס לבית האחר כיון שבצד ששם הפתח אין שם גג. וכתוב בדרישה אף אם הטומאה באה מפתח בית הטמא לתחת גגו ומשם מגג לגג של בית אחר מ\"מ אם דעת הכהנים לסגור פתח בתיהן וחלונותיהן ולא לצאת משם עד אחר הוצאת המת אין צריכין לצאת מבתיהן וגדולה מזאת עשיתי במת עמי ביום השבת וצויתי להוציאו ולהניחו במרתף שתחת הבית ופתח המרתף לצד חוץ ולא היה גג על גבי [פתח] המרתף והכהנים נשארו בבית אלא שיש להקשות אהנחת מת במרתף ודלת המרתף סגורה בפתח המרתף הא בעינן שיהיה ביציאת הקבר פותח טפח וכמ\"ש בסימן שע\"ב דהאידנא דכולו סתום אפילו יש בו אויר טפח כל שכנגדו טמא) וה\"נ אף שבמרתף הוא חלל גדול סביב המת מכל מקום ליכא ביציאת הפתח דהמרתף פותח טפח כל זמן שהוא סגור והכהנים בבית ע\"ג המרתף מיהו אם בהדלת הפתח שבמרתף עשוים חורין חורין כמו שקורין בל\"א גיגאטי\"ר אף שאין בחור א' טפח מ\"מ כיון שיש בהצטרפות החורין יחד פתוח כמה טפחים יש צד להקל שהוא בכלל יציאתה פותח טפח עכ\"ל ותמהני על פה קדוש יאמר כן נגד המשניות ערוכות הבאתים בתחלת סימן זה שאין נקבי הגיגאטי\"ר מצטרפות לטפח. ובפירוש אמרו במשנה פרק י\"ב דאהלות שאין הטומאה יוצאת מהבית כשאין שם נקב [טפח] במקום א' וא\"כ נשארה הטומא' בבית והוה כקבר סתום ומטמא עד לרקיע והיאך כ' לקולא מחמת הצטרפות הנקבים להוציא הטומאה כיון שהמרתף סגור מכל צד אע\"ג דאין הדלת מקרי חציצה כמו שאכתוב בסמוך מ\"מ המרתף סתום ע\"כ אין לסמוך על היתר זה דהצטרפות הנקבים כלל. גם מה שכתב להתיר לכהנים לסגור פתחיהם וחלון זהו דבר הנמנע דהא סגירת הפתח ע\"י מפתח הוא ואינו חוצץ כדאיתא לעיל ר\"ס זה סעיף א' הבאתיו בשם רמב\"ם) ותו דהא הדלת תלויה ע\"י צירים של ברזל ודבר כזה אינו חוצץ כמו שכתבתי לעיל בראיה ברורה ומעולם לא שמענו לנהוג בהיתר זה לכהנים וכמה הקילו רבותינו להיות חס על הכהן שלא להגיד לו עד שילביש עצמו ולא נהגו בהיתר זה אלא ודאי דליתיה. כן נלע\"ד ברור:","\u0003אינם יכולים לכוף כו'. \u0004הטעם בתשובת מהרי\"ל וז\"ל אבל אי רגילין להשהותם משום כבודם להשמיע עליו רבים שיתעסקו עמו א\"נ לטהרו בביתו א\"כ היאך מצינו לכופן לזלזל נגד המנהג ולא שייך הכא על המזיק להרחיק עצמו כיון דאנוס הוא דהואיל ונהוג נהוג עכ\"ל. ומו\"ח ז\"ל כתב דאם הוא נפל דלא איכא משום כבוד כופין אותו להוציאו מביתו בשביל הכהנים דעל המזיק להרחיק עצמו ע\"כ. ואני תמהתי על דברי התשובה הנ\"ל דהא אין שייך כלל כאן לכוף אותו להוציאו מטעם על המזיק להרחיק עצמו כדאיתא בח\"מ סימן קנ\"ה בש\"ע סעיף ל\"ב בהיה לו אילן סמוך לבור חבירו אין בעל הבור יכול לומר הרי שרשי האילן מפסידים לבורי שזה נזק הבא מאליו לאחר זמן ובשעה שנטעו אינו מזיקו כו' ק\"ו כאן שאין עושה לעולם שום מעשה להזיקו אלא מן השמים הוא היאך יכוף אותו ונראה דעל זה נמי נתכוון בתשובה במה שכתב דאונס הוא כלומר דנעשה ממילא ומה שסיים אחר זה דהואיל ונהוג נהוג ובלאו הכי ראוי להגיה כן דהיאך שייך לומר אונס כיון שהוא מנהג ולפי זה גם בנפל אין שייך לכופו להוציאו כיון שאין שם מזיק עליו אלא שאם הכהן רוצה לשלוח שם להוציא הנפל אל מקום אחר אין אבי הנפל יכול לעכב כיון שהוא ניזוק וזה לא חסר כלל כן נראה לע\"ד:","\u0003אסור לכהן כו'. \u0004דא\"א לו שלא יסיט הטומאה. רש\"ל הביא בשם הגהת מיי' וא\"ז שפסקו כרבינו משולם להתיר אפי' בספינה קטנה רק שלא יהא תוך ד' אמותיו ויש להחמיר כיון שגם ב\"י הביא זה להחמיר:"],"\u0010y0\u0011 \u0010g0\u0011 \u0010r0\u0011 אָסוּר לְכֹהֵן \u0010t0\u0011 לִכָּנֵס תַּחַת אֹהֶל שֶׁהַמֵּת תַּחְתָּיו, אֲפִלּוּ הוּא גָּדוֹל הַרְבֵּה, \u0010r1\u0011 וַאֲפִלּוּ לְבַיִת אַחֵר אוֹ לַעֲלִיָּה אַחֶרֶת, הַפְּתוּחִים לְאוֹתוֹ בַּיִת \u0010c0\u0011 \u0010t1\u0011 בְּנֶקֶב שֶׁיֵּשׁ בּוֹ טֶפַח עַל טֶפַח, וּבַיִת לְאוֹתוֹ בַּיִת, עַד עוֹלָם; \u0010g1\u0011 וְאִם סָתַם הַנֶּקֶב, מֻתָּר לוֹ לִכָּנֵס לַבַּיִת \u0010y1\u0011 הָאַחֵר, שֶׁהַסְתִימָה חוֹצֶצֶת, \u0010r2\u0011 אֲפִלּוּ לֹא בִּטְּלוּ לִהְיוֹת שָׁם עוֹלָמִית. \u0010g2\u0011 \u0010r3\u0011 וְהָנֵי מִלֵּי, שֶׁסָתַם כָּל הַנֶּקֶב; אֲבָל אִם לֹא סָתַם כָּל הַנֶּקֶב, אֶלָּא מִעֲטוֹ מִטֶּפַח, אִם נְתָנוֹ לִהְיוֹת שָׁם עוֹלָמִית, מְמַעֵט וְחוֹצֵץ בִּפְנֵי הַטֻּמְאָה שֶׁלֹּא תַּעֲבֹר; וְאִם לָאו, אֵינוֹ מְמַעֵט. \u0005הַגָּה: \u0010y2\u0011 \u0010c1\u0011 \u0010r4\u0011 וְכָל דָּבָר הַמְקַבֵּל טֻמְאָה אֵינוֹ חוֹצֵץ בִּפְנֵי הַטֻּמְאָה (הַגָּהַת אַלְפָסִי פֶּרֶק בְּנֵי הָעִיר ובהל' טֻמְאָה לְהָרִי\"ף וְרַמְבַּ\"ן וְרֹא\"שׁ וּמָרְדְּכַי רֵישׁ \u0010g3\u0011 פֶּרֶק לֹא \u0010r5\u0011 יַחְפֹּר)\u0006. וְלֹא מִקְרֵי סְתִימָה בְּחַלּוֹן, \u0010c2\u0011 אֶלָּא אִם כֵּן יָכוֹל לַעֲמֹד בְּלֹא \u0010t2\u0011 סְמִיכָה \u0010g4\u0011 \u0005(ג\"ז שָׁם)\u0006. \u0010g5\u0011\nאֲרֻבָּה שֶׁבֵּין בַּיִת לַעֲלִיָּה וְאֵין בָּהּ פּוֹתֵחַ טֶפַח, וְכַזַּיִת מֵהַמֵּת לְמַטָּה בַּבַּיִת כְּנֶגֶד \u0010y3\u0011 \u0010c3\u0011 הָאֲרֻבָּה, הַבַּיִת טָהוֹר \u0010t3\u0011 וְהָעֲלִיָּה טְמֵאָה. \u0010y4\u0011 \u0010g6\u0011\nשְׁנֵי חֲדָרִים \u0010t4\u0011 פְּתוּחִים לְבַיִת, וּבְכָל אַחַת חֲצִי זַיִת מֵהַמֵּת, וְדַלְתוֹתֵיהֶם נְעוּלִים, \u0010y5\u0011 \u0010c4\u0011 הַבַּיִת \u0010t5\u0011 טָמֵא וְהֵם טְהוֹרִים; וְאִם נִפְתְחוּ, גַּם הֵם טְמֵאִים. \u0010y6\u0011 \u0010g7\u0011 \u0010r6\u0011\nחָצֵר הַמֻּקֶּפֶת זִיזִין וְאַכְסַדְרָאוֹת, וְטֻמְאָה בְּאֶחָד מֵהַבָּתִּים, \u0010y7\u0011 \u0010c5\u0011 אִם כָּל פִּתְחֵי הַבָּתִּים וְהַחַלּוֹנוֹת נְעוּלִים, טֻמְאָה יוֹצֵאת לְתַחַת הַזִּיזִין וְהָאַכְסַדְרָאוֹת; \u0010r7\u0011 \u0005וְהַטַּעַם, מִשּׁוּם דְּהוֹאִיל וְסוֹף הַטֻּמְאָה לָצֵאת דֶּרֶךְ שָׁם, רוֹאִין כְּאִלּוּ יָצְאָה; \u0010y8\u0011 וְלָכֵן יֵשׁ \u0010t6\u0011 מַחְמִירִין לְכֹהֲנִים לֵילֵךְ דֶּרֶךְ שַׁעַר הָעִיר שֶׁסּוֹף הַמֵּת לָצֵאת מִשָּׁם (פִּסְקֵי מהרא\"י סִימָן כ\"ה וְכָל בּוֹ)\u0006, \u0010c6\u0011 \u0010r8\u0011 וְיֵשׁ מַתִּירִין \u0005(שָׁם הֵבִיא בְּשֵׁם י\"א)\u0006, וְהַמֵּקֵל לֹא הִפְסִיד בְּמָקוֹם שֶׁלֹּא נָהֲגוּ לְהַחְמִיר; \u0010y9\u0011 \u0010r9\u0011 וְאִם נִפְתַּח \u0010y10\u0011 חַלּוֹן אוֹ \u0010t7\u0011 פֶּתַח מִצַּד הָאַחֵר, וְאוֹתָם שֶׁל צַד הֶחָצֵר כֻּלָּם נְעוּלִים, אֵין הַטֻּמְאָה יוֹצֵאת לְתַחַת הַזִּיזִין. \u0010c7\u0011 \u0010r10\u0011 וְאִם נִפְתַּח גַּם כֵּן אֶחָד מֵהֶן לְצַד \u0010t8\u0011 הַזִּיזִין, הַטֻּמְאָה יוֹצֵאת מֵהַבַּיִת לְתַחַת הַזִּיזִין. \u0010y11\u0011 \u0010g8\u0011 וְכֵן אִם טֻמְאָה תַּחַת הַזִּיזִין, \u0010c8\u0011 נִכְנֶסֶת מִתַּחְתֵּיהֶן \u0010t9\u0011 לַבַּיִת; \u0010y12\u0011 לָכֵן \u0010y13\u0011 גַּגִּים הַבּוֹלְטִים לְמַעְלָה לְחוּץ עַל פִּתְחֵי הַבָּתִּים, וְטֻמְאָה בְּאֶחָד מֵהַבָּתִּים, \u0010c9\u0011 כָּל הַבָּתִּים \u0010y14\u0011 שֶׁפִּתְחֵיהֶם \u0010t10\u0011 פְּתוּחִים, טְמֵאִים. \u0005הַגָּה: \u0010r11\u0011 ב' גַּגִּין שֶׁאֵין נוֹגְעִין זֶה בָּזֶה, אַף עַל פִּי שֶׁאֵין בֵּינֵיהֶם רַק פָּחוֹת מִג', לֹא הָוֵי חִבּוּר לַטֻּמְאָה, דְּלֹא אַמְרִינָן לָבוּד לְהַחְמִיר (מהרי\"ו בִּפְסָקָיו)\u0006. \u0010y15\u0011 \u0010r12\u0011 וְאִם הָיוּ זֶה לְמַעְלָה מִזֶּה, אַף עַל פִּי שֶׁאֵינָן נוֹגְעִים, אַמְרִינָן: \u0010t11\u0011 חָבוּט רָמֵי, וּכְאִלּוּ נוֹגְעִים \u0005(נ\"י בְּהִלְכוֹת \u0010y16\u0011 \u0010r13\u0011 טֻמְאָה רי\"ף)\u0006. הַכֹּהֲנִים \u0010c10\u0011 אֵינָן יְכוֹלִין \u0010t12\u0011 לָכֹף לִקְרוֹבֵי הַמֵּת שֶׁיּוֹצִיאוּ הַמֵּת מִמְּקוֹמוֹ, כְּדֵי שֶׁהֵם יִהְיוּ רַשָּׁאִים לִכָּנֵס לְבֵיתָם, אִם לֹא בְּמָקוֹם שֶׁדֶּרֶךְ לְהוֹצִיא כָּל הַמֵּתִים \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ס\"ה)\u0006. \u0010y17\u0011 \u0010g9\u0011\nאָסוּר \u0010t13\u0011 לִקְרַב בְּתוֹךְ אַרְבַּע אַמּוֹת שֶׁל מֵת \u0010r14\u0011 אוֹ שֶׁל קֶבֶר. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁאֵין הַקֶּבֶר מְסֻיָּם בִּמְחִצּוֹת גְּבוֹהוֹת י' טְפָחִים, \u0010g10\u0011 \u0010r15\u0011 אֲבָל אִם הוּא מְסֻיָּם בִּמְחִצּוֹת גְּבוֹהוֹת עֲשָׂרָה טְפָחִים, אוֹ בְּחָרִיץ עָמֹק י' טְפָחִים, אֵין צָרִיךְ לְהַרְחִיק מִמֶּנּוּ \u0010r16\u0011 אֶלָּא ד' טְפָחִים. \u0010y18\u0011 \u0010r17\u0011 \u0005וּמֻתָּר לְכֹהֵן לַעֲמֹד אֵצֶל בַּיִת שֶׁיֵּשׁ בּוֹ מֵת, וּמֻתָּר לִגֹּעַ בִּכְתָלָיו, וּבִלְבַד שֶׁלֹּא יְהֵא שׁוּם דָּבָר מַאֲהִיל עָלָיו (תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן קל\"ו)\u0006. \u0010g11\u0011 \u0010r18\u0011\nמֵת הַמּוּנָח בִּסְפִינָה, \u0010y19\u0011 אִם הִיא קְטַנָּה שֶׁמִּתְנַדְנֶדֶת כְּשֶׁדּוֹרְכִין בָּהּ, \u0010c11\u0011 אָסוּר לְכֹהֵן \u0010t14\u0011 לִכָּנֵס בָּהּ.",{"g":["\u0003לשון הטור מדברי הרי\"ף והרא\"ש בהלכות טומאה ממשנה ו' ז' פרק ג' דאהלות:\u0004 ","\u0003הרי\"ף והרא\"ש שם בהלכות טומאה ופשוט בכמה דוכתי ובמשנה שבת דף קנ\"ז ע\"א:\u0004 ","\u0003מדברי התוס' ב\"ב דף כ' ע\"א:\u0004 ","\u0003ממשנה ג' פרק (קמא) ח' דאהלות:\u0004 ","\u0003ממשנה ב' פ\"ו שם:\u0004 ","ממשנה ריש פ\"י דאהלות וכתב הב\"י שהטור כתב דין זה ושאחריו מביא כל שאר דינים השנויים במסכת אהלות לפי שהוא דבר חידוש שמותר ליכנס לבית שהמת בתוכו ואסור ליכנס לעליה:\n(°) פירוש דאז אינה חוזרת ויורדת:","\u0003ממשנה סוף פ\"ח דאהלות:\u0004 ","\u0003מדברי הרי\"ף בהלכות טומאה ממשנה ג' פ\"ז דאהלות:\u0004 ","\u0003מדברי אביו הרא\"ש שם בהלכות טומאה ממשנה ריש פי\"ד דאהלות ובכמה דוכתי:\u0004 ","\u0003מימרא דר' יוחנן וכו'\u0004 סוטה דף מ\"ד ע\"א:","\u0003מדברי הרא\"ש בהלכות טומאה בשם ה\"ר יהונתן מסוגיא דסוטה שם:\u0004 ","מרדכי דמ\"ק והגמ\"יי פ\"ב בשם תשו' הר\"מ ממשנה ריש פ\"ג דזבים וכ\"כ הרשב\"א סי' כ\"ח ובספינה גדולה שאינה מתנדנדת אסור לו ליכנס להתקרב תוך ד' אמות:"],"t":["\u0003ליכנס. \u0004 כתב הרוקח אשת כהן המעוברת מותרת ליכנס באוהל המת דס\"ס הוא שמא נפל או שמא נקבה היא:","\u0003בנקב. \u0004 כתב הט\"ז דהיינו אם הוא במקום א' אבל אם אינו במקום א' אלא ע\"י צירוף יש טפח כגון מה שקורין גיגאטי\"ר שעשוי ע\"י סירוג אין מביא את הטומאה והוא משנה פי\"ג דאהלות הסירוגות ב\"ה אומרים עד שיהא כמלא מקדח במקום א' ומבואר שם דבין להביא את הטומאה בין להוציא עכ\"ל:","\u0003סמיכה. \u0004 כ' הט\"ז דהתוספות כתבו הטעם דכל שצריך סמיכה מקרי סתימת עראי ופשוט הוא לכ\"ע כל שמושיב באותו חלון עצים ואבנים כ\"כ הרבה עד שכותלי החלון מחזיקים אותם זה ודאי מהני וחוצץ דאין זה בכלל סמיכה כלל. ומעשה שהיה בטומאה שהיתה בבית סמוך לבהכ\"נ באופן שהיתה נכנסת דרך חלון בהכ\"נ של נשים וצוה מורה א' לסתום החלון באותו פרוכת קטן שתלוי שם בקרסי ברזל תמיד שהוא לצניעות הנשים וכו' ואמרתי שטעה המורה דבהדיא אמרינן במתני' דסדין שאינו עשוי כאהלים אינו חוצץ ועוד דמחמת דטבעות של ברזל הם עומדים וכלים אינם חוצצין ע\"ש שמאריך בכמה ראיות לסתור דברי המורה הנ\"ל \u0005(ובלקט הקמח כתב שמעשה כזה אירע בעה\"ק בבהכ\"נ הגדולה בשבת קודש והורו גאוני ההוראה לסתום החלון שהיה טפח על טפח בצמר חדא משום דהוי ראוי לשכיבה ולית ביה משום מוקצה ומשום בנין ותוספת בנין מותר וברשת של עץ ג\"כ התירו לסתום הן מפני כבוד הצבור שלא יתפללו במקום שהטומאה נכנסת דרך החלון ואין ראוי להניחם בלא ברכת כהנים באהבה עכ\"ל)\u0006 וכתב עוד דלא מועיל חציצת דלת או חלון כל שאינו יכול לעמוד בלא צירים של ברזל או שאר דבר של ברזל אע\"פ שהם לצורך קרקע וזה מועיל שלא יקבלו טומאה מ\"מ אינם חוצצים \u0005(ובנה\"כ השיג עליו בכל זה ופסק דשפיר חוצץ ע\"ש באורך)\u0006 עוד כתב הט\"ז ונראה דאם יש סתימה בחלון של ברזל שהוא עשוי כמו סבכה שקורין בלשון אשכנז גיגאטי\"ר והוא של ברזל אינו מועיל כיון שהוא מקבל טומאה ואינו עשוי כעין אוהל \u0005(וכתב נה\"כ דצ\"ל שהגיגאטי\"ר אינו קבוע בכותל דאל\"כ אינו מקבל טומאה וחוצץ ועיין שם)\u0006:","\u0003והעליה. \u0004 הטעם כתב הש\"ך משום דטומאה בוקעת ועולה כיון שהיא מונחת תחת הארובה ואין הטומאה מתפשטת לצדדי הבית הואיל שיש מקום לטומאה לעלות לארובה שכנגדה ואינה חוזרת ויורדת לבית כיון שאין בארובה טפח שאם היה בה טפח הוה ליה חשבינן בית ועליה כמו חדר א' וכתב הט\"ז וא\"ל שיהיה פתח הבית ההוא טמאה משום שסוף הטומאה לצאת דרך אותו הפחח כמ\"ש בס\"ד דכאן שאין שם רק כזית מן המת ואין עליו אהל הוה כמונח ברה\"ר ואינו מטמא כלל בבית ומזה למדנו שאם יש מת בבית ומונח בחדר שאין עליו אהל אין לכהן להיות בכל הבית הן מטעם שהטומאה חוזרת ויורדת והן מטעם שסוף הטומאה לצאת דרך הפתח דלא הקילו כאן אלא אם אין פתוח רק פחות מטפח עכ\"ל:","\u0003פתוחים. \u0004 היינו כששני החדרים כל א' מהם פתחו פתוח לבית בפ\"ע ושניהם הם לפנים מן הבית. ש\"ך:","\u0003טמא. \u0004 דסוף הטומאה לצאת ורואה אני כאלו שני חצאי הזיתים מונחים בבית ואין הטומאה נכנסת בחדרים כיון שדלתותיהם נעולות אבל כשנפתחו חזרה הטומאה מן הבית לחדרים. ש\"ך:","\u0003מחמירין. \u0004 כ' הש\"ך אמנם אין להחמיר בבית של צדוק הדין דאדרבה אותו הפתח בא לטמא את האוהל פסקי מהרא\"י וכ' בס' מעדני מלך שטעם זה יספיק אם אין בו אלא פתח א' שבו מכניסין ומוציאין את המת אבל אם יש בו ב' פתחים שבפתח הא' מכניסין ובהשני מוציאין כמו שיש בבית צדוק הדין שבק\"ק פראג יש להחמיר שאין לכהנים ליכנס באותו הפתח שמוציאין ממנו המת עכ\"ל והט\"ז כ' דהעיקר תלוי בפתח הבית שהמת בתוכו דסוף הטומאה לצאת דרך שם ע\"כ מטמא אף שהוא נעול אבל בבתים אחרים מה מעלה יש בנעילתם וצ\"ל דמ\"ש המחבר אם כל פתחי הבתים נעולים הוא לאו דוקא עכ\"ל \u0005(ובת' ח\"צ סי' ק\"ג חולק ע\"ז ואחר שהביא ראיות לדבריו כ' וז\"ל הדבר ברור דבבית צדוק הדין אין לחוש כלל אם יכנסו בו הכהנים אף שיש מת בעיר יכולים הכהנים להקדים ולכנוס בו בין שיש לו פתח א' ובין שיש לו ב' פתחים וע\"ש עוד בזה)\u0006:","\u0003פתח. \u0004 שיש בו ד' על ד' כן הוא בלבוש:","\u0003הזיזין. \u0004 פירש הט\"ז דהיינו אותו החדר שהמת בתוכו נפתח גם כן לצד הזיזין באופן שנפתח אותו הבית משני צדדיו:","\u0003לבית. \u0004 פי' לבית שפתחו פתוח לצד הזיזין. ט\"ז:","\u0003פתוחים. \u0004 כתב הש\"ך אבל אם הם סתומים טהורים ולפ\"ז אף כשהטומאה באה באיזה בית אם דעת הכהנים לסגור פתח בתיהן וחלונותיהן ולא לצאת מהן עד אחר הוצאת המת א\"צ לצאת מבתיהן ולפ\"ז כהן שהוא בבית או חדר שהטומאה נוגע אליו והוא נעול בדלת וחלונות ונודע לו שהגיע הטומאה אליו אסור לצאת מן החדר עד אחר הוצאת המת שהרי כל זמן שלא נפתח החדר לא נכנסת הטומאה לתוכו וכשיפתח תכנס הטומאה לתוכו ובדרישה כתב וז\"ל וגדולה מזאת עשיתי במת עמי ביום השבת וצויתי להוציאו ולהניחו במרתף שתחת הבית ופתח המרתף לצד חוץ ולא היה גג ע\"ג [פתח] המרתף והכהנים נשארו בבית אלא שיש להקשות ע\"ז בהנחת מת במרתף ודלת המרתף סגור הא בעינן שיהיה ביציאת הקבר פתוח טפח וכמ\"ש בסי' שע\"ב וה\"נ אף שבמרתף יש חלל גדול סביב המת מ\"מ אם אין בהפתח פותח טפח אינם רשאים הכהנים להיות ע\"ג המרתף כל זמן שהוא סגור מיהו אם הדלת שבמרתף עשויה כמו שקורין בל\"א גיגאטי\"ר אף שאין בחור א' טפח מכל מקום כיון שיש בהצטרפות החורין יחד פתוח כמה טפחים יש צד להקל שהוא בכלל יציאתה פותח טפח \u0005(ועיין ש\"א שאלה צ\"ג ושבות יעקב שאלה פ\"ה)\u0006 והט\"ז חולק עליו מטעם שמבואר לעיל שמוכח מהמשנה דאהלות להדיא שאין נקבי הגיגאטי\"ר מצטרפין לטפח גם מ\"ש להתיר להכהנים לסגור פתחיהן וחלונות זהו דבר הנמנע דהא סגירת הפתח הוא ע\"י מפתח גם ע\"י צירים של ברזל וזה אינו חוצץ כמ\"ש לעיל בראיה ברורה ומעולם לא שמענו לנהוג בהיתר זה לכהנים וכמה הקילו רבותינו להיות חס על הכהן שלא להגיד לו עד שילביש עצמו ולא נהגו בהיתר זה אלא ודאי דליתא עכ\"ל \u0005(ובנה\"כ השיג עליו וכתב דהוא נמשך לשיטתו דלעיל ריש הסי' וכבר כתבתי דליתא ואדרבה מהרמב\"ם משמע דחוצץ גם י\"ל דהדרישה מיירי היכא דהדלת יכולה לעמוד בלא סמיכה כמו שעושים ברוב בתים גם יש לתמוה עליו ועל הדרישה היאך סתמו וכתבו דחור שבדלת שיעורו פותח טפח והא דבר זה יש פלוגתא דר\"ע ור\"ט באהלות פי\"ד ור\"ע ס\"ל דשיעורו מלא אגרוף וקי\"ל הלכה כר\"ע מחבירו וכ\"פ הרמב\"ם להדיא ובע\"כ צ\"ל לדבריהם דהיינו דוקא בסתם חור שנעשה בתחלה ע\"י אומן אבל בחור שעשוי להוציא ולהביא דהוי כעשוי לתשמיש מודה ר\"ע לר\"ט אלא דא\"כ ה\"ל לפרושי דמיירי בכה\"ג. וגם הרמב\"ם לא חילק בדבר משמע דס\"ל דבכל גוני שיעורו כאגרוף וצ\"ע עכ\"ל)\u0006 וכ' מהרש\"ל דבמקום שיש עירוב ועשו קורות שיש בהם היקף טפח ממבוי למבוי וראשי הקורות נכנסין תחת הגגין שמכאן ומכאן והטומאה נכנסת תחתיהם הקורה מביאה הטומאה מגג לגג ומתפשטת בכל הבתים מכאן ומכאן א\"כ כשיש מת באחד מן הבתים אין כהן רשאי להיות בשום בית מן הבתים שבמבואות המחוברות ע\"י קורה של העירוב \u0005(וכתב הב\"ח שהקורה צריך להיות עגולה כדי שיהיה רחבה טפח)\u0006 וזוכרני כשהיינו לומדים בבית מורי ר\"מ ז\"ל והיה פתח פתוח מחצר הרב לחצר בהכ\"נ ומשקוף הפתח היה מגיע מצד א' תחת תקרת הבית שהיה בו מת ואסר מורי לכהנים לצאת ולבוא דרך אותו הפתח כל זמן שהמת בבית וכ' הדרישה ושמעתי דהיינו דוקא במחיצה שיש עליה גג קטן או מחיצה שמשקוף עליה רוחב טפח וכו' אבל מחיצה מושכת מבית לבית ואין גג עליה וגם אין פתח פתוח בתוך המחיצה אפילו אם הקורה המונח עליה בעובי טפח וגם גגות הבתים משני צדדי המחיצה בקצה שלהם מאהילים עליהם מ\"מ אינו מביא הטומאה כיון דבאמצעית המחיצה אין עליה גג ולא תקרה כיון שאין שם פתח נקרא כסתום באמצע ואין בו כח להוליך הטומאה וכתב הט\"ז דמשמע מדבריו באם יש מחיצה פנויה בלא גג עליה ויש פתח באמצעיתה מביאה את הטומאה מבית לבית כיון שבראש המחיצה יש שם אהל מן הגג של בית הטמא אע\"פ שאין הפתח מגיע עד אותו החלק שהוא תחת הגג ותמיהני מאד על הדבר הזה כיון שיש הפסק בחלק המחיצה מי יכניס הטומאה מן תחת הגג להפתח שבאמצע והלא אפי' ביש הפסק בפחות משלשה לא אמרינן לבוד להחמיר. וע\"כ לא אסר מהרש\"ל אלא שהתקרה היתה מונחת בלא מחיצה תחתיה מן תחת הגג של בית הטמא לתחת הגג של בית אחר נמצא שהיה חלל תחת התקרה בלי הפסק מחיצה סתומה משא\"כ כאן שיש הפסק במחיצה הבנויה על הארץ ואין בליטה טפח סמוך לחלק שתחת הגג השני ודאי אין כאן הבאת טומאה כלל מידי דהוה אשני בתים סמוכים ואין גג בולט למעלה מהם דאין נכנסת הטומאה מבית לבית אע\"פ ששניהם פתוחים דהא גגין בולטין בעינן ונראה דאין לחוש לטומאה כשיש מחיצה בנויה אע\"פ שיש פתח באמצעה לא בתוך המחיצה כולה אא\"כ יש עליה ג\"כ גג קטן או בליטה טפח מן אותו צד שנכנס תחת בית הטמא לחלק המגיע תחת גג השני. והש\"ך כ' ונראה דצריך שיהא הגג אוהל טפח מתחלה עד סוף אבל כל שיש ביניהם הפסק בחומה גבוה אף שהיא עבה כמה טפחים כיון שאין אהל טפח שוב אין לטומאה מקום לילך וכן הסכימו רבים וגדולים וכן המנהג פשוט עכ\"ל:","\u0003חבוט. \u0004 וכ' הב\"ח נ\"ל דאפי' היה גג העליון הרבה למעלה מג\"ט כיון שיש בגגו טפח אמרי' חביט רמי וע\"ש:","\u0003לכוף. \u0004 ונראה דאם הוא נפל דליכא משום כבוד כופין אותו להוציאו ממקומו כדי שיכנסו הכהנים לביתם כ\"כ הב\"ח ואין כן דעת הט\"ז אלא שאם הכהן רוצה לשלוח שם להוציא הנפל אל מקום אחר אין אבי הנפל יכול לעכב כיון שהוא ניזוק וזה לא חסר כלל עכ\"ל \u0005(ובנה\"כ מסכים לדעת הב\"ח ע\"ש)\u0006:","\u0003לקרב. \u0004 וכ' הדרישה מכאן מוכח דאפי' תוך ד' אמות של מת המונח לפנינו אסור לקרב בהן משום דתופס ד\"א או משום גזרה שמא יגע במת עצמו ולא כמו ששמעתי דמקילין לכהן הדורש לעמוד עליו אפי' תוך ד\"א של מת עכ\"ל והש\"ך כתב דנראה דטעם המקילין הוא דיש חילוק בין שהמת מונח בבית אז אסור לכהן לקרב למקום קביעתו שהוא תופס ד\"א אבל במונח על המטה שמוציאין אותו \u0005(וכ\"ש כשנושאין על המטה)\u0006 ובעת צדוק הדין מעמידין אותו אינו תופס דאין זה מיקרי קביעות וכן מחלק הרוקח עכ\"ל:","\u0003ליכנס. \u0004 אפי' חוץ לד\"א של מת כיון שא\"א שלא יסיט הטומאה אבל אם היא גדולה שאינה מתנדנדת כשדורכין בה מותר חוץ לד' אמות של מת עכ\"ל הש\"ך:"],"r":["\u0003אסור לכהן כו'. \u0004פרק ד' דמגילה \u0005(כ\"ו ב') \u0006וש\"מ:","\u0003ואפילו לבית כו'. \u0004כמה משניות באהלות וש\"מ:","\u0003אפילו לא כו'. \u0004פ\"ד דמגילה \u0005(שם):\u0006","\u0003וה\"מ כו'. \u0004עתוס' דב\"ב כ' א' ד\"ה היא כו':","\u0003וכ\"ד כו'. \u0004גמרא שם ובמגלה שם:","\u0003ולא מקרי כו'. \u0004עבה\"ג ועתוס' דב\"ב י\"ט ב' ד\"ה רואין כו':","\u0003חצר כו'. \u0004ממתני' ג' פ\"ז דאהלות:","\u0003והטעם כו'. \u0004וכמש\"ש בפ\"ד ע\"ש:","\u0003ויש מתירין. \u0004עט\"ז:\n\u0003(ליקוט) ויש מתירין. \u0004וכ\"ה במתני' ריש פי\"א דאהלות הבית שנסדק כו' ובה\"א כו' ולא אמרינן שסוף טומאה לצאת אלא תחת אהל א' והוא פשוט שם בכמה מקומות (ע\"כ):","\u0003ואם נפתח כו'. \u0004מתני' שם:","\u0003ואם נפתח כו'. \u0004כנ\"ל ס\"א:","\u0003ב' גגין כו' דלא כו'. \u0004כנ\"ל ס\"ב וכמ\"ש בסוכה י\"ח א':","\u0003ואם היו כו'. \u0004שם כ\"ב א':","\u0003הכהנים כו'. \u0004מהא דפ\"ד דמגילה \u0005(כ\"ו ב') \u0006ולא הוציאוהו חוצה ודוחק לומר שהיה בשבת ועוד דאף בשבת מותר ע\"י עובד כוכבים או ע\"י ככר ותינוק. שם:","\u0003(ליקוט) או של כו'. \u0004כמש\"ש במת וכמש\"ש וה\"מ חצר כו' משמע הא לא\"ה דינו כמת וכ\"כ רש\"י בב\"ב י\"ב א' ד\"ה פרץ כו' ועתוס' שם ד\"ה פרץ כו'. אבל דברי רש\"י ותוס' צ\"ע דהא קבר סתום מטמא כל סביביו ואפ\"ה מותר לעמוד בחצר הקבר הואיל מסיימי מחיצתא וכמש\"ו כאן בד\"א כו' (ע\"כ):","\u0003אבל אם הוא כו'. \u0004גמ' שם:","\u0003(ליקוט) אלא ד\"ט. \u0004צ\"ע דבגמרא לא אמרינן אלא דצריך שיהיה בחצר ד\"ט (ע\"כ):","\u0003ומותר כו'. \u0004כמ\"ש בב\"ב י\"ב א' ועתוס' שם ד\"ה פרץ כו':\n\u0003(ליקוט) ומותר לכהן כו' ומותר כו'. \u0004בב\"ב שם דבית סתום אינו מטמא כל סביביו ואפילו בכתלים עצמן וכמ\"ש תוס' שם בשם ספרי אבל לעמוד אצל הכותל אף בפרץ פצימיו מותר כנ\"ל דלא כרש\"י ומ\"ש מטמא כל סביביו היינו ליגע בכתלים עצמן ותוס' שם בתחלה פי' פי' אחד עיין שם (ע\"כ):","\u0003מת כו'. \u0004מתני' פ\"ג דזבין והוא הדין למת אם מסיט את המת:"]}],["אַף עַל פִּי שֶׁהַכֹּהֵן אָסוּר \u0010y0\u0011 לִכָּנֵס לְבֵית הַפְּרָס, \u0005(פֵּרוּשׁ שָׂדֶה שֶׁנֶּאֱבַד בָּהּ קֶבֶר, וְשֶׁנֶּחֱרַשׁ בָּהּ קֶבֶר, וְשִׁעוּרָהּ מֵאָה אַמָּה)\u0006 אוֹ לְאֶרֶץ הָעַמִּים, אִם הָיָה צָרִיךְ לֵילֵךְ שָׁם לִשָּׂא אִשָּׁה אוֹ לִלְמֹד תּוֹרָה, וְאֵין לוֹ דֶּרֶךְ אַחֶרֶת, \u0010c0\u0011 יָכוֹל לַעֲבֹר דֶּרֶךְ שָׁם, אֲפִלּוּ אִם מוֹצֵא לִלְמֹד בְּמָקוֹם אַחֵר. וְכֵן אָבֵל הָעוֹבֵר דֶּרֶךְ שָׁם, יָכוֹל לֵילֵךְ אַחֲרָיו לְנַחֲמוֹ. וְכֵן מִטַּמֵּא בְּטֻּמְאָה שֶׁל דִּבְרֵיהֶם, לָדִין עִם עוֹבְדֵי כּוֹכָבִים וּלְעַרְעֵר עִמָּהֶם, מִפְּנֵי שֶׁהוּא כְּמַצִּיל מִיָּדָם, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: כֹּהֵן שֶׁשּׁוֹכֵב \u0010y1\u0011 עָרֹם, וְהוּא בְּאֹהֶל עִם הַמֵּת וְלֹא יָדַע, אֵין לְהַגִּיד לוֹ, אֶלָּא יִקְרְאוּ לוֹ סְתָם, שֶׁיֵּצֵא כְּדֵי שֶׁיַּלְבִּישׁ עַצְמוֹ תְּחִלָּה. אֲבָל אִם כְּבַר הִגִּידוּ לוֹ, אָסוּר לְהַמְתִּין עַד שֶׁיִּלְבַּשׁ עַצְמוֹ. וְדַוְקָא אִם הוּא בְּאֹהֶל הַמֵּת, שֶׁהוּא טֻמְאָה דְּאוֹרַיְתָא, אֲבָל אִם הוּא בְּבֵית הַפְּרָס אוֹ אֶרֶץ הָעַמִּים, שֶׁהוּא טֻמְאָה דְּרַבָּנָן, יַלְבִּישׁ עַצְמוֹ תְּחִלָּה, דְּגָדוֹל כְּבוֹד הַבְּרִיּוֹת (ת\"ה סִימָן רפ\"ה)\u0006, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן ש\"ג לְעִנְיַן כִּלְאַיִם. כֹּהֵן שֶׁהוּא יָשֵׁן, וּמֵת עִמּוֹ בָּאֹהֶל, \u0010y2\u0011 צְרִיכִין לַהֲקִיצוֹ וּלְהַגִּיד לוֹ כְּדֵי שֶׁיֵּצֵא \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ס\"ט)\u0006.\nקִבְרֵי עוֹבְדֵי כּוֹכָבִים, נָכוֹן לִזָּהֵר הַכֹּהֵן מִלֵּילֵךְ עֲלֵיהֶם; \u0005(מהר\"מ וְתוס' פ' הַמְקַבֵּל)\u0006 \u0010y3\u0011 \u0005אַף עַל פִּי שֶׁיֵּשׁ מְקִלִּין\u0006 \u0005(רַמְבַּ\"ם והגמי\"י בְּשֵׁם ס' יְרֵאִים)\u0006. \u0005וְנָכוֹן לְהַחְמִיר. אֲבָל קֶבֶר שֶׁל מוּמָר\u0006 \u0005(לַעֲבוֹדַת כּוֹכָבִים)\u0006, \u0005מְטָּמֵא כְּשֶׁל יִשְׂרָאֵל\u0006 \u0005(רַשְׁבָּ\"א סי' קצ\"ד ורמ\"ב)\u0006.",["\u0003לבית הפרס. \u0004הוא שדה שנחרש בו קבר:","\u0003והוא באוהל כו'. \u0004ודוקא) אם הוא באוהל המת כו' נראה דוקא נקט באוהל המת אבל אם בבתים הסמוכים לבית שהמת בתוכו אע\"פ שהן ג\"כ טמאים כדלעיל סימן שע\"א ס\"ד מ\"מ י\"ל דאינו אלא טומאה דרבנן כדאיתא בטור סי' זה ופוסקים עב\"י דדבר תורה אוהל שיש בו חלל פותח טפח טהור ע\"ש ודוק וכשהבית שהמת בתוכו סתום מכל צד נמי ליכא בבתים הסמוכים טומאה אלא מדרבנן משום דסוף הטומאה לצאת ואם כן בבתים הסמוכים בכל ענין ילביש עצמו תחלה:","\u0003צריכין להקיצו ולהגיד לו. \u0004דאפילו בלא שהייה קעבר הכהן ואע\"ג דלא ידע מ\"מ איסורא עביד בשוגג ואף על גב דאינו עושה מעשה איסורא איכא ולאחריני דידעי מצוה להפרישו עכ\"ל תשובת מהרי\"ל סי' ס\"ט ס\"ל אע\"ג דאינו מעשה ולאו שאין בו מעשה אין לוקין עליו איסור דאוריי' מיהא איכא ולפי זה משמע דבאיסורא דרבנן א\"צ להקיצו וא\"כ למ\"ש בסמוך דהיכא דאינו באוהל עצמו אם המת רק בבית הסמוך לה ליכא אלא איסורא [דרבנן] אין צריך להקיצו ואפשר לזה דקדק הרב ומת עמו באוהל צריכים להקיצו וע\"ל סי' שע\"ג ס\"ק א':","\u0003אף על פי שיש מקילין. \u0004מטעם דכתיב אדם כי ימות באוהל וגו' ואתם קרוים אדם ואין העובדי כוכבים קרוים אדם אבל במגע ומשא י\"א דאפילו המקילים אוסרים וכן נראה דעת ב\"י ע\"ש:"],["\u0003יכול לעבור דרך שם. \u0004אבל לא על הקברות אפילו לדבר מצוה משום דהאידנא כולם סתומים ויש בהקברים חלל הרבה על כן טומאה בוקעת ועולה עד לרקיע ואפילו נגד צד הריקן שבו מה שאין כן אי הוה סתום ואין בתוכו חלל טפח אינו מטמא אלא כנגד הטומאה ממש לא נגד צד הריקן שבו:"],"\u0010g0\u0011 אַף עַל פִּי שֶׁהַכֹּהֵן אָסוּר \u0010y0\u0011 לִכָּנֵס לְבֵית הַפְּרָס, \u0005(פֵּרוּשׁ שָׂדֶה שֶׁנֶּאֱבַד בָּהּ קֶבֶר, וְשֶׁנֶּחֱרַשׁ בָּהּ קֶבֶר, וְשִׁעוּרָהּ מֵאָה אַמָּה)\u0006 אוֹ לְאֶרֶץ הָעַמִּים, אִם הָיָה צָרִיךְ לֵילֵךְ שָׁם לִשָּׂא אִשָּׁה אוֹ לִלְמֹד תּוֹרָה, וְאֵין לוֹ דֶּרֶךְ אַחֶרֶת, \u0010c0\u0011 יָכוֹל \u0010t0\u0011 לַעֲבֹר דֶּרֶךְ שָׁם, \u0010g1\u0011 אֲפִלּוּ אִם מוֹצֵא לִלְמֹד בְּמָקוֹם אַחֵר. וְכֵן \u0010g2\u0011 \u0010r0\u0011 אָבֵל הָעוֹבֵר דֶּרֶךְ שָׁם, יָכוֹל לֵילֵךְ אַחֲרָיו לְנַחֲמוֹ. \u0010g3\u0011 וְכֵן מִטַּמֵּא בְּטֻּמְאָה שֶׁל דִּבְרֵיהֶם, לָדִין עִם עוֹבְדֵי כּוֹכָבִים וּלְעַרְעֵר עִמָּהֶם, מִפְּנֵי שֶׁהוּא כְּמַצִּיל מִיָּדָם, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: כֹּהֵן שֶׁשּׁוֹכֵב \u0010y1\u0011 עָרֹם, וְהוּא בְּאֹהֶל עִם הַמֵּת וְלֹא יָדַע, אֵין לְהַגִּיד לוֹ, אֶלָּא יִקְרְאוּ לוֹ סְתָם, שֶׁיֵּצֵא כְּדֵי שֶׁיַּלְבִּישׁ עַצְמוֹ תְּחִלָּה. אֲבָל אִם כְּבַר הִגִּידוּ לוֹ, אָסוּר לְהַמְתִּין עַד שֶׁיִּלְבַּשׁ עַצְמוֹ. \u0010t1\u0011 וְדַוְקָא אִם הוּא בְּאֹהֶל הַמֵּת, שֶׁהוּא טֻמְאָה דְּאוֹרַיְתָא, אֲבָל אִם הוּא בְּבֵית הַפְּרָס אוֹ אֶרֶץ הָעַמִּים, שֶׁהוּא טֻמְאָה דְּרַבָּנָן, יַלְבִּישׁ עַצְמוֹ תְּחִלָּה, דְּגָדוֹל כְּבוֹד הַבְּרִיּוֹת (ת\"ה סִימָן רפ\"ה)\u0006, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן ש\"ג לְעִנְיַן כִּלְאַיִם. \u0010r1\u0011 כֹּהֵן שֶׁהוּא יָשֵׁן, וּמֵת עִמּוֹ בָּאֹהֶל, \u0010y2\u0011 צְרִיכִין \u0010t2\u0011 לַהֲקִיצוֹ וּלְהַגִּיד לוֹ כְּדֵי שֶׁיֵּצֵא \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ס\"ט)\u0006. \u0010g4\u0011 \u0010r2\u0011\nקִבְרֵי עוֹבְדֵי כּוֹכָבִים, נָכוֹן לִזָּהֵר הַכֹּהֵן מִלֵּילֵךְ עֲלֵיהֶם; \u0005(מהר\"מ וְתוס' פ' הַמְקַבֵּל)\u0006 \u0010y3\u0011 \u0005אַף עַל פִּי שֶׁיֵּשׁ \u0010t3\u0011 מְקִלִּין\u0006 \u0005(רַמְבַּ\"ם והגמי\"י בְּשֵׁם ס' יְרֵאִים)\u0006. \u0005וְנָכוֹן לְהַחְמִיר. \u0010r3\u0011 אֲבָל קֶבֶר שֶׁל מוּמָר\u0006 \u0005(לַעֲבוֹדַת כּוֹכָבִים)\u0006, \u0005מְטָּמֵא כְּשֶׁל יִשְׂרָאֵל\u0006 \u0005(רַשְׁבָּ\"א סי' קצ\"ד ורמ\"ב)\u0006.",{"g":["ברייתא עבודת כוכבים דף י\"ג ע\"א וכתבוהו הרי\"ף והרא\"ש בסוף הלכות טומאה וכתבו התוספות שם ודוקא שדעתו לחזור מהא דאמרינן בכתובות דף קי\"א ע\"א ברוך המקום שהרגו:","\u0003שם בברייתא וכר' יוסי שלא מן הכל אדם זוכה ללמוד:\u0004 ","\u0003ברייתא ברכות דף י\"ט ע\"ב וכאוקימתא דרבי אבא שם:\u0004 ","\u0003הרמב\"ם בפ\"ג מהלכות אבל מברייתא עבודת כוכבים דף י\"ג ע\"א:\u0004 ","טור בשם תשובת אביו הרא\"ש וש\"פ אבל במגע ובמשא מטמאין כ\"כ הרמב\"ם בפ\"ה מהלכות טומאת מת וכתבו ההגהות עליו שכדברי רבינו משמע מהא דאמרינן נהי דמעטינהו קרא וכו' יבמות דף ס\"א ע\"א:"],"t":["\u0003לעבור. \u0004 אבל לא על הקברות אפי' לדבר מצוה משום דהאידנא כולם סתומים ויש בהקברים חלל הרבה ע\"כ הטומאה בוקעת ועולה עד לרקיע ואפי' נגד צד הריקן שבו משא\"כ אי הוה סתום ואין בו חלל טפח אינו מטמא אלא כנגד הטומאה ממש ולא נגד צד הריקן שבו עכ\"ל הט\"ז:","\u0003ודוקא. \u0004 כתב הש\"ך נראה דדוקא נקט באהל המת אבל אם בבתים הסמוכים לבית שהמת בתוכו אף על פי שהם ג\"כ טמאים כדלעיל סי' שע\"א ס\"ד מ\"מ י\"ל דאינו אלא טומאה דרבנן כדאיתא בטור בסימן זה ובפוסקים ועב\"י דדבר תורה אהל שיש בו חלל פותח טפח טהור ע\"ש ודוק. וכשהבית שהמת בתוכו סתום מכל צד נמי ליכא בבתים הסמוכים טומאה אלא מדרבנן מפני שסוף הטומאה לצאת ואם כן בבתים הסמוכים בכל ענין ילביש עצמו תחלה עכ\"ל:","\u0003להקיצו. \u0004 כתב הש\"ך ולפי מ\"ש בסמוך דהיכא דאינו עם המת באהל עצמו רק בבית הסמוך לו ליכא אלא איסורא דרבנן א\"צ להקיצו. ואפשר לזה דקדק הרב וכתב ומת עמו באהל וכו' וע\"ל סי' שע\"ג עכ\"ל:","\u0003מקילין. \u0004 כתב הש\"ך אבל במגע ומשא י\"א דאפילו המקילים אוסרים וכן נראה דעת הב\"י ע\"ש עכ\"ל:"],"r":["\u0003(ליקוט) אבל העובר כו' כהן ששוכב כו'. \u0004עתוס' דברכות כ' א' ד\"ה שב כו' אלא נראה כו' וכתב הרמב\"ן \u0005(בתה\"א) \u0006וכן יש נוסחאות דגרסי בגמרא הכי בהדיא וכ\"כ רב האי גאון ולפ\"ז אידחי ליה מש\"ש בתחלה בטומאה דרבנן דכל לאו טומאה לאו שאינו שוה בכל הוא אבל נראין דברי רש\"י שם ד\"ה שב כו' דמעיקרא כו' וכמ\"ש בפ\"ק דיבמות \u0005(ג' ב' ז' א') \u0006אימור דאמרינן עשה דוחה ל\"ת כו' ולא גמיר מאשת אח עצמה שדוחה ייבום אותה ע\"ש (ע\"כ):","\u0003כהן שהוא כו'. \u0004עש\"ך:","\u0003קברי כו' אע\"פ כו'. \u0004עתוס' דיבמות ס\"א א' ד\"ה ממגע כו':","\u0003אבל כו'. \u0004כמ\"ש בפ\"ו דסנהדרין \u0005(מ\"ד א') \u0006אע\"פ שחטא כו' ובפ\"ד דיבמות מ\"ז ב' \u0005(למאי הלכתא דאי הדר כו') \u0006ובספ\"ק דקדושין \u0005(ל\"ו א') \u0006לר\"מ בין כך ובין כך קרויין בנים כו'. שם:"]}],["כְּשֵׁם שֶׁהַכֹּהֵן מֻזְהָר שֶׁלֹּא לִטָּמְאוֹת, כָּךְ \u0010c0\u0011 מֻזְהָרִים הַגְּדוֹלִים עַל הַקְּטַנִּים. \u0005וְדַוְקָא לְטַמְּאוֹתָן בְּיָדַיִם, אֲבָל אִם הַקְּטַנִּים מִטָּמְאִין מֵעַצְמָן, \u0010y0\u0011 עַיֵּן בְּא\"ח סִימָן שמ\"ג אִי צָרִיךְ לְהַפְרִישָׁן (הָרַשְׁבָּ\"א סִימָן קכ\"ח ומהרי\"ו, וְטוּר בְּשֵׁם הָרַמְבַּ\"ם כָּתַב כָּאן דְּאֵין צָרִיךְ)\u0006.\nאֲפִלּוּ בַּעַל מוּם, \u0010y1\u0011 מֻזְהָר מִלִּטַּמֵּא, אֲבָל חָלָל וְכֹהֶנֶת, מֻתָּרִים לִטָּמֵא.\nכָּל הַמֵּתִים הָאֲמוּרִים בַּפָּרָשָׁה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, מִצְוָה שֶׁיִּטָּמֵא לָהֶם; וְאִם לֹא רָצָה, מְטַמְאִים אוֹתוֹ עַל כָּרְחוֹ, אֶחָד הָאִישׁ \u0010y2\u0011 וְאֶחָד הָאִשָּׁה.\nאֵלּוּ הֵם הַקְּרוֹבִים שֶׁמִּטָּמֵא לָהֶם: אִשְׁתּוֹ נְשׂוּאָה שֶׁהִיא כְּשֵׁרָה; \u0010y3\u0011 אֲבָל פְּסוּלָה, אוֹ גְּרוּשָׁה, אוֹ אֲרוּסָה, לֹא אוֹנֵן וְלֹא מִטָּמֵא לָהּ; וְכֵן הִיא, לֹא אוֹנֶנֶת \u0010y4\u0011 וְלֹא מִטָּמְאָה לוֹ. וּמִטָּמֵא לְאִמּוֹ, \u0010y5\u0011 אֲפִלּוּ נִתְחַלְּלָה; וְלִבְנוֹ וּלְבִתּוֹ דְּקִים לֵיהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו, \u0010y6\u0011 אוֹ שֶׁהֵם מִשְּׁלֹשִׁים יוֹם וָאֵילָךְ, אֲפִלּוּ הֵם פְּסוּלִים; חוּץ מִבְּנוֹ וּבִתּוֹ מִשִּׁפְחָה אוֹ כּוּתִית; וּלְאָחִיו וְלַאֲחוֹתוֹ מֵאָבִיו, אֲפִלּוּ הֵם פְּסוּלִים, אֶלָּא אִם כֵּן הֵם בְּנֵי שִׁפְחָה אוֹ כּוּתִית; אֲבָל לְאָחִיו וְלַאֲחוֹתוֹ מֵאִמּוֹ, אֵינוֹ מִטָּמֵא. \u0005וְכֵן אֵינוֹ מִטָּמֵא\u0006 לַאֲחוֹתוֹ אֲרוּסָה, אֲפִלּוּ הִיא אֲרוּסָה לְכֹהֵן; וְלֹא לַאֲנוּסָה \u0010y7\u0011 וּמְפֻתָּה; אֲבָל מִטָּמֵא לַאֲחוֹתוֹ אֲרוּסָה שֶׁנִּתְגָּרְשָׁה, וּבוֹגֶרֶת, וּמֻכַּת עֵץ; וּמִטָּמֵא לְשׁוֹמֶרֶת יָבָם, אֲפִלּוּ אִם כָּתַב בִּכְתֻבָּתָהּ: אִי מִיתַת בְּלֹא בָּנִים תֶּהְדַּר כְּתֻבָּתֵךְ לְבֵי נָשָׁא \u0005(פֵּרוּשׁ לְבֵית אָבִיהָ)\u0006.\nכָּל אֵלּוּ שֶׁמִּטָּמֵא לָהֶם, \u0010y8\u0011 אֲפִלּוּ שֶׁלֹּא \u0010y9\u0011 לְצֹרֶךְ. וְיֵשׁ אוֹמְרִים דְּדַוְקָא לְצֹרֶךְ. \u0005הַגָּה: וְלַסְּבָרָא הָרִאשׁוֹנָה, אֲפִלּוּ מֵת לוֹ מֵת בְּשַׁבָּת, שֶׁאִי אֶפְשָׁר לְקָבְרוֹ בּוֹ בַּיּוֹם, שָׁרֵי לִטָּמְאוֹת לוֹ וּלְשָׁמְרוֹ, כְּדֵי שֶׁלֹּא יְהֵא מֻטָּל בְּבִזָּיוֹן (ת\"ה סי' רפ\"ג)\u0006 ; וְנָכוֹן לְהַחְמִיר כַּסְּבָרָא הָאַחֲרוֹנָה, שֶׁלֹּא לִטָּמְאוֹת רַק לְצֹרֶךְ קְבוּרָה וּלְהָבִיא לוֹ אָרוֹן וְתַכְרִיכִין. \u0005(שָׁם בְּשֵׁם תּוֹסָפוֹת שנ\"ץ)\u0006.\nאֵינוֹ מִטָּמֵא לָהֶם, אֶלָּא \u0010y10\u0011 עַד שֶׁיִּסְתֹּם הַגּוֹלֵל. \u0005וְאִם דַּעְתּוֹ לְפַנּוֹתוֹ, מֻתָּר לִטָּמֵא לוֹ לְצֹרֶךְ, עַד שֶׁיִּסְתֹּם גּוֹלֵל שֵׁנִי (תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן רצ\"ב)\u0006.\nאָסוּר לְכֹהֵן לְהִתְטַמֵּא לְמֵת, אֲפִלּוּ בְּעֵת שֶׁמִּטָּמֵא לִקְרוֹבָיו. לְפִיכָךְ כֹּהֵן שֶׁמֵּת לוֹ מֵת, צָרִיךְ לִזָּהֵר וּלְקָבְרוֹ בְּסוֹף בֵּית הַקְּבָרוֹת, כְּדֵי שֶׁלֹּא לִכָּנֵס לְבֵית הַקְּבָרוֹת וְלֹא יִתְטַמֵּא בְּקִבְרוֹת אֲחֵרִים כְּשֶׁיִּקְבֹּר מֵתוֹ. \u0005הַגָּה: \u0010y11\u0011 וְדַוְקָא לְאַחַר שֶׁפָּרַשׁ מִמֵּתוֹ, אֲבָל בְּעוֹד שֶׁהוּא עוֹסֵק בְּמֵתוֹ, מֻתָּר לִטָּמְאוֹת אַף לַאֲחֵרִים (טוּר)\u0006.\nכֹּהֵן שֶׁפָּרְשׁוּ אֲבוֹתָיו מִדַּרְכֵי צִבּוּר, כְּגוֹן הַמַּסוּרוֹת, אֵינוֹ מִטָּמֵא לָהֶם; וְלֹא לַהֲרוּגֵי בֵּית דִּין; וְלֹא לְמִי שֶׁמְּאַבֵּד עַצְמוֹ לָדַעַת, וְלֹא לְסָפֵק, כְּגוֹן שֶׁנִּתְעָרֵב וְלָדָהּ בִּוְלַד חֲבֶרְתָּהּ אוֹ סָפֵק בֶּן ט' לָרִאשׁוֹן אוֹ בֶּן ז' לָאַחֲרוֹן.\nאֵין הַכֹּהֵן מִטָּמֵא לְאֵבֶר מִן הַחַי מֵאָבִיו, וְלֹא לְעֶצֶם מֵעַצְמוֹת אָבִיו. וְכֵן הַמְלַקֵּט עֲצָמוֹת, אֵינוֹ מִטָּמֵא לָהֶם, אַף עַל פִּי שֶׁהַשִּׁדְרָה \u0010y12\u0011 קַיֶּמֶת. חָסֵר מִמֶּנּוּ כָּל שֶׁהוּא, אֲפִלּוּ הוּא מֻנָּח אֶצְלוֹ, אֵינוֹ מִטָּמֵא לוֹ, שֶׁאֵינוֹ מִטָּמֵא אֶלָּא לְשָׁלֵם. וְיֵשׁ מִי שֶׁאוֹמֵר דְּהָנֵי \u0010y13\u0011 מִלֵּי כְּשֶׁחָסֵר לְאַחַר מִיתָה, אֲבָל אִם חָסַר מִמֶּנּוּ אֵבֶר בְּחַיָּיו, וּמֵת, מִטָּמֵא לוֹ, אַף עַל פִּי שֶׁאֵינוֹ שָׁלֵם. \u0005וְיֵשׁ אוֹמְרִים שֶׁאֵינוֹ מִטָּמֵא לְהָרוּג, דְּמִקְרֵי חָסֵר (כָּל בּוֹ בְּשֵׁם ר\"ש מאוירא)\u0006 וְנָכוֹן לְהַחְמִיר.",["\u0003עיין באו\"ח סימן שמ\"ג כו'. \u0004משמע כמו דאמרינן התם דא\"צ להפרישן הוא הדין הכא מיהו הביא הרב שם די\"א דהיינו דוקא שלא הגיע לחינוך ע\"ש ובאגודה פרק חרש כתב נ\"ל על תינוקות הישנים באוהל המת אין מחייבים להקיצם ולהוציאם אך מפני חינוך טוב הוא עכ\"ל והביאוהו האחרונים:","\u0003אבל חלל כו'. \u0004כתב הב\"ח דוקא חלל דאורייתא אבל של דבריהם כגון שנולד מחלוצה אסור לטמא ואם הוא נולד מספק חלוצה הוי כהן גמור לכל דבר ויתבאר בא\"ע סימן ז' ע\"ש:","\u0003ואחד האשה. \u0004שהיתה כהנת מצוה לה לטמאות:","\u0003אבל פסולה או גרושה. \u0004פי' אפי' יש לו בנים ממנה. מרדכי וכ\"כ האחרונים:","\u0003ולא מיטמאה לו. \u0004כלומר אינה מחוייבת לטמא לו אבל הרשות בידה לטמא:","\u0003אפי' נתחללה. \u0004כגון אחר שנולד כהן זה ממנה נשאת לכהן כשהיא גרושה:","\u0003או שהם מל' יום ואילך. \u0004לאפוקי ספק נפל דאין מטמאין לו וה\"ה לאחיו ולאחותו הקטנים שהן ספק נפלים אין מטמא להם:","\u0003אבל מטמא לאחותו הארוסה אחר שנתגרשה. \u0004מן האירוסין:","\u0003אפילו שלא לצורך. \u0004מיטמא ומצוה ליטמא:","\u0003וי\"א דוקא לצורך. \u0004קבורה או להביא לו ארון ותכריכים ואז מצוה ליטמא אבל שלא לצורך אסור לטמאות:","\u0003עד שיסתום הגולל בו'. \u0004ע\"ל ריש סי' שע\"ה בטור מהו גולל שרש\"י פי' גולל היינו כיסוי הארון ור\"ת פי' גולל הוא אבן שנותנים על הקבר כו' ע\"ש ובב\"ח שם כתב דנקטינן כרש\"י וכתב הרמב\"ן בת\"ה ומביאו הטור שם דלפירש\"י כשנותנים אותו בבית בארון וסותמין הכסוי במסמרים ע\"ד ליתן הארון בכוך או בקבר הוי סתימה כו' והוא תמה עליו בת\"ה דהיאך אפשר לומר שאם סתמו ארונו בבית שלא יטמא בנו עליו כו' ומביאו ב\"י שם ולפעד\"נ דמה שפירש\"י בכל מקום גולל היינו כסוי הארון אין ר\"ל אפילו סתמו בבית אלא ר\"ל משיסתם כסוי הארון בקבר תדע דבפרק שואל (שבת ד' קנ\"ב ע\"ב) אמרינן כל שאומרי' בפני המת יודע עד שיסתום הגולל (ופירש\"י גם כן התם גולל הוא כסוי שנותנים על ארונו) דכתיב וישוב העפר אל הארץ כשהיה פירש\"י גופו קרוי עפר ומששב אל הארץ כשהי' מיד והרוח תשוב שאין בו עוד רוח ע\"כ ולפי זה אם נסתם הארון בבית במסמרים גם לפירש\"י בנו מיטמא עליו עד שיסתם בקבר:","\u0003ודוקא לאחר שפירש ממתו כו'. \u0004כלומר אין כאן איסור בהליכה מפני שאז עוסק במתו ומות' לטמאות אז אף לאחרים אלא האיסור הוא מפני שבחזרה יצטרך לילך על הקברי' וכבר פירש ממתו והב\"ח פסק דאף בהליכה אסור להוסיף טומאה כיון שאפשר לו לקברו בסוף בית הקברות וכן נראה דעת המחבר וכ\"כ העטרת זהב דנכון להחמיר כסברא זו והמ\"מ דף קי\"ז מיקל בדבר:","\u0003חסר ממנו כל שהוא. \u0004מן המת:","\u0003כשחסר לאחר מיתה. \u0004או כשחסר בשעת מיתה כגון שחתכו ראשו שאינו עכשיו כמו שהיה בחיים ולא קרינן ביה לאביו:"],["\u0003הגדולים על הקטנים. \u0004פי' הכהנים הגדולים ובטור כתוב אם מטמאין מעצמן אין ב\"ד מצווין להפרישו כו' ש\"מ שעל ב\"ד יש גם כן אזהרה שלא לטמאות בידים. וכ' באגודה דתינוק הישן באוהל המת אין צריכין להקיצו ולהוציאו אך מפני החינוך טוב הוא עכ\"ל:"],"\u0010g0\u0011 כְּשֵׁם שֶׁהַכֹּהֵן מֻזְהָר שֶׁלֹּא לִטָּמְאוֹת, כָּךְ \u0010c0\u0011 מֻזְהָרִים הַגְּדוֹלִים עַל הַקְּטַנִּים. \u0010r0\u0011 \u0005וְדַוְקָא לְטַמְּאוֹתָן \u0010t0\u0011 בְּיָדַיִם, אֲבָל אִם הַקְּטַנִּים מִטָּמְאִין מֵעַצְמָן, \u0010y0\u0011 עַיֵּן בְּא\"ח סִימָן שמ\"ג אִי צָרִיךְ לְהַפְרִישָׁן (הָרַשְׁבָּ\"א סִימָן קכ\"ח ומהרי\"ו, וְטוּר בְּשֵׁם \u0010g1\u0011 הָרַמְבַּ\"ם כָּתַב כָּאן דְּאֵין צָרִיךְ)\u0006. \u0010g2\u0011\nאֲפִלּוּ בַּעַל מוּם, \u0010y1\u0011 \u0010r1\u0011 מֻזְהָר מִלִּטַּמֵּא, אֲבָל \u0010t1\u0011 חָלָל \u0010r2\u0011 וְכֹהֶנֶת, \u0010g3\u0011 מֻתָּרִים לִטָּמֵא.\nכָּל הַמֵּתִים הָאֲמוּרִים בַּפָּרָשָׁה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, מִצְוָה שֶׁיִּטָּמֵא לָהֶם; וְאִם לֹא רָצָה, מְטַמְאִים אוֹתוֹ עַל כָּרְחוֹ, \u0010g4\u0011 אֶחָד הָאִישׁ \u0010y2\u0011 \u0010r3\u0011 וְאֶחָד הָאִשָּׁה.\nאֵלּוּ הֵם הַקְּרוֹבִים שֶׁמִּטָּמֵא לָהֶם: \u0010g5\u0011 אִשְׁתּוֹ נְשׂוּאָה שֶׁהִיא כְּשֵׁרָה; \u0010y3\u0011 אֲבָל פְּסוּלָה, \u0010r4\u0011 אוֹ \u0010t2\u0011 גְּרוּשָׁה, \u0010r5\u0011 אוֹ \u0010g6\u0011 אֲרוּסָה, לֹא אוֹנֵן וְלֹא מִטָּמֵא לָהּ; וְכֵן הִיא, לֹא אוֹנֶנֶת \u0010y4\u0011 וְלֹא \u0010t3\u0011 מִטָּמְאָה לוֹ. \u0010g7\u0011 וּמִטָּמֵא לְאִמּוֹ, \u0010y5\u0011 \u0010t4\u0011 אֲפִלּוּ נִתְחַלְּלָה; וְלִבְנוֹ וּלְבִתּוֹ \u0010g8\u0011 \u0010r6\u0011 דְּקִים לֵיהּ שֶׁכָּלוּ לוֹ \u0010t5\u0011 חֳדָשָׁיו, \u0010y6\u0011 אוֹ שֶׁהֵם מִשְּׁלֹשִׁים יוֹם וָאֵילָךְ, \u0010r7\u0011 אֲפִלּוּ הֵם פְּסוּלִים; חוּץ מִבְּנוֹ וּבִתּוֹ מִשִּׁפְחָה אוֹ כּוּתִית; וּלְאָחִיו וְלַאֲחוֹתוֹ \u0010g9\u0011 מֵאָבִיו, אֲפִלּוּ הֵם \u0010g10\u0011 פְּסוּלִים, אֶלָּא אִם כֵּן הֵם בְּנֵי שִׁפְחָה אוֹ כּוּתִית; \u0010r8\u0011 אֲבָל לְאָחִיו וְלַאֲחוֹתוֹ מֵאִמּוֹ, אֵינוֹ מִטָּמֵא. \u0010r9\u0011 \u0005וְכֵן אֵינוֹ מִטָּמֵא\u0006 לַאֲחוֹתוֹ \u0010g11\u0011 אֲרוּסָה, \u0010g12\u0011 אֲפִלּוּ הִיא אֲרוּסָה לְכֹהֵן; וְלֹא לַאֲנוּסָה \u0010y7\u0011 \u0010g13\u0011 וּמְפֻתָּה; אֲבָל מִטָּמֵא לַאֲחוֹתוֹ אֲרוּסָה \u0010t6\u0011 שֶׁנִּתְגָּרְשָׁה, וּבוֹגֶרֶת, \u0010g14\u0011 וּמֻכַּת עֵץ; \u0010g15\u0011 \u0010r10\u0011 וּמִטָּמֵא לְשׁוֹמֶרֶת יָבָם, \u0010r11\u0011 אֲפִלּוּ אִם כָּתַב בִּכְתֻבָּתָהּ: אִי מִיתַת בְּלֹא בָּנִים תֶּהְדַּר כְּתֻבָּתֵךְ לְבֵי נָשָׁא \u0005(פֵּרוּשׁ לְבֵית אָבִיהָ)\u0006. \u0010r12\u0011\nכָּל אֵלּוּ שֶׁמִּטָּמֵא לָהֶם, \u0010y8\u0011 \u0010g16\u0011 אֲפִלּוּ שֶׁלֹּא \u0010y9\u0011 \u0010g17\u0011 \u0010r13\u0011 לְצֹרֶךְ. וְיֵשׁ אוֹמְרִים דְּדַוְקָא לְצֹרֶךְ. \u0005הַגָּה: וְלַסְּבָרָא הָרִאשׁוֹנָה, אֲפִלּוּ מֵת לוֹ מֵת בְּשַׁבָּת, שֶׁאִי אֶפְשָׁר לְקָבְרוֹ בּוֹ בַּיּוֹם, שָׁרֵי לִטָּמְאוֹת לוֹ וּלְשָׁמְרוֹ, כְּדֵי שֶׁלֹּא יְהֵא מֻטָּל בְּבִזָּיוֹן (ת\"ה סי' רפ\"ג)\u0006 ; וְנָכוֹן לְהַחְמִיר כַּסְּבָרָא הָאַחֲרוֹנָה, שֶׁלֹּא לִטָּמְאוֹת רַק לְצֹרֶךְ קְבוּרָה וּלְהָבִיא לוֹ אָרוֹן וְתַכְרִיכִין. \u0005(שָׁם בְּשֵׁם תּוֹסָפוֹת שנ\"ץ)\u0006. \u0010g18\u0011 \u0010r14\u0011\nאֵינוֹ מִטָּמֵא לָהֶם, אֶלָּא \u0010y10\u0011 עַד \u0010t7\u0011 שֶׁיִּסְתֹּם הַגּוֹלֵל. \u0010r15\u0011 \u0005וְאִם דַּעְתּוֹ לְפַנּוֹתוֹ, מֻתָּר לִטָּמֵא לוֹ לְצֹרֶךְ, עַד שֶׁיִּסְתֹּם גּוֹלֵל שֵׁנִי (תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן רצ\"ב)\u0006. \u0010g19\u0011 \u0010r16\u0011\nאָסוּר לְכֹהֵן לְהִתְטַמֵּא לְמֵת, אֲפִלּוּ בְּעֵת שֶׁמִּטָּמֵא לִקְרוֹבָיו. \u0010g20\u0011 לְפִיכָךְ כֹּהֵן שֶׁמֵּת לוֹ מֵת, צָרִיךְ לִזָּהֵר וּלְקָבְרוֹ בְּסוֹף בֵּית הַקְּבָרוֹת, כְּדֵי שֶׁלֹּא לִכָּנֵס לְבֵית הַקְּבָרוֹת וְלֹא יִתְטַמֵּא בְּקִבְרוֹת אֲחֵרִים כְּשֶׁיִּקְבֹּר מֵתוֹ. \u0005הַגָּה: \u0010y11\u0011 \u0010t8\u0011 \u0010r17\u0011 וְדַוְקָא לְאַחַר שֶׁפָּרַשׁ מִמֵּתוֹ, אֲבָל בְּעוֹד שֶׁהוּא עוֹסֵק בְּמֵתוֹ, מֻתָּר לִטָּמְאוֹת אַף לַאֲחֵרִים \u0010g21\u0011 (טוּר)\u0006. \u0010g22\u0011 \u0010r18\u0011\nכֹּהֵן שֶׁפָּרְשׁוּ אֲבוֹתָיו מִדַּרְכֵי צִבּוּר, כְּגוֹן הַמַּסוּרוֹת, אֵינוֹ מִטָּמֵא לָהֶם; \u0010g23\u0011 וְלֹא לַהֲרוּגֵי בֵּית דִּין; וְלֹא לְמִי שֶׁמְּאַבֵּד עַצְמוֹ לָדַעַת, \u0010g24\u0011 \u0010r19\u0011 וְלֹא לְסָפֵק, כְּגוֹן שֶׁנִּתְעָרֵב וְלָדָהּ בִּוְלַד חֲבֶרְתָּהּ אוֹ סָפֵק בֶּן ט' לָרִאשׁוֹן אוֹ בֶּן ז' לָאַחֲרוֹן. \u0010g25\u0011 \u0010r20\u0011\nאֵין הַכֹּהֵן מִטָּמֵא לְאֵבֶר מִן הַחַי מֵאָבִיו, וְלֹא לְעֶצֶם מֵעַצְמוֹת אָבִיו. \u0010r21\u0011 וְכֵן הַמְלַקֵּט עֲצָמוֹת, אֵינוֹ מִטָּמֵא לָהֶם, אַף עַל פִּי שֶׁהַשִּׁדְרָה \u0010y12\u0011 \u0010g26\u0011 קַיֶּמֶת. חָסֵר מִמֶּנּוּ כָּל שֶׁהוּא, אֲפִלּוּ הוּא מֻנָּח אֶצְלוֹ, אֵינוֹ מִטָּמֵא לוֹ, שֶׁאֵינוֹ מִטָּמֵא אֶלָּא לְשָׁלֵם. \u0010g27\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר דְּהָנֵי \u0010y13\u0011 מִלֵּי כְּשֶׁחָסֵר לְאַחַר מִיתָה, אֲבָל אִם חָסַר מִמֶּנּוּ אֵבֶר בְּחַיָּיו, וּמֵת, מִטָּמֵא לוֹ, אַף עַל פִּי שֶׁאֵינוֹ שָׁלֵם. \u0010r22\u0011 \u0005וְיֵשׁ אוֹמְרִים שֶׁאֵינוֹ מִטָּמֵא לְהָרוּג, דְּמִקְרֵי חָסֵר (כָּל בּוֹ בְּשֵׁם ר\"ש מאוירא)\u0006 וְנָכוֹן לְהַחְמִיר.",{"g":["\u0003ברייתא יבמות דף קי\"ד ע\"א:\u0004 ","\u0003בפ\"ג מהלכות אבל כ' אין הב\"ד מצווין להפרישו אבל אביו צריך לחנכו בקדושתו:\u0004 ","\u0003בספרא ריש פרשת אמור והביאו רש\"י בפירושו שם:\u0004 ","\u0003ברייתא זבחים דף ק' ע\"א:\u0004 ","\u0003טור מדברי אביו הרא\"ש בהלכות טומאה:\u0004 ","\u0003ברייתא יבמות דף צ' ע\"ב ודף כ\"ב ע\"ב:\u0004 ","ברייתא שם דף (ס' ע\"א כר' יוסי ור\"ש) [כ\"ט ע\"ב]:","\u0003בת\"כ דריש לה מקרא:\u0004 ","\u0003רמב\"ם בפ\"ב מהלכות אבל והרא\"ש מהא דת\"כ שם דממעט נפלים מקרא:\u0004 ","\u0003שם בת\"כ:\u0004 ","\u0003משנה יבמות דף כ\"ב ע\"א:\u0004 ","ברייתא שם דף (כ\"ט ע\"ב) [ס' ע\"א כר' יוסי ור\"ש]:","\u0003רמב\"ם בפ\"ב מהלכות אבל:\u0004 ","\u0003שם אפי' לר' יוסי ור\"ש:\u0004 ","\u0003שם כר' יוסי ור' יהודה ור\"מ:\u0004 ","\u0003הרשב\"א בתשובה:\u0004 ","\u0003ברייתא באבל רבתי וכרבי יהודה משום ר' טרפון הרמב\"ן בסת\"ה וש\"פ בשמו:\u0004 ","\u0003תה\"ד סי' רפ\"ג בשם תוספות דפסחים דף ט' ע\"א ותוספות שנ\"ץ:\u0004 ","\u0003שם בברייתא כרבי יהודה משום ר' טרפון:\u0004 ","\u0003לשון הרמב\"ם פ\"ה מהלכות אבל:\u0004 ","\u0003שם פ\"ב:\u0004 ","מדברי הרמב\"ם והרא\"ש מברייתא דנזיר והסוגיא שם דף מ\"ב ע\"ב הביאו הב\"י ובכ\"מ שם ושכ\"נ דעת התוספות בנדה ריש דף נ\"ז ולענ\"ד נראה מלשון הרמב\"ם שאוסר גם בזה כמשמעות סוגיא דנזיר דבחבורין חיובא הוא דליכא הא איסורא איכא:","\u0003ברייתא כתבוהו הרי\"ף והרא\"ש בהלכות טומאה ונתבאר בסי' שמ\"ה סעיף ה':\u0004 ","\u0003טור וכ\"כ הרמב\"ם בפ\"ב מברייתא כל שהכהן מיטמא וכו'\u0004 מ\"ק דף כ' ע\"ב [סנהדרין מ\"ו ע\"ב]:","\u0003ברייתא בת\"כ וכתבוהו הרי\"ף והרמב\"ן והרא\"ש:\u0004 ","\u0003לשון הרמב\"ם שם בפ\"ב דף י\"ז מברייתא מעשה דרבי צדוק וכו'\u0004 נזיר דף מ\"ג ע\"ב:","\u0003טור מדברי אביו הרא\"ש וכן משמע מדברי הרמב\"ם והרמב\"ן ז\"ל:\u0004 ","\u0003מדברי הרמב\"ן והוא לא הכריע בזה והרא\"ש כתבה כאלו היא מוכרעת וכ' כהטור:\u0004 "],"t":["\u0003בידים. \u0004 וכתב באגודה נ\"ל דתינוקות הישנים באהל המת אין מחוייבים להקיצם ולהוציאם אך מפני החינוך טוב הוא עכ\"ל \u0005(אבל א\"צ להוציא את הקטן שאינו בר דעת הצריך לאמו. בה\"י סי' שע\"א)\u0006:","\u0003חלל. \u0004 כ' הב\"ח דוקא חלל דאורייתא אבל של דבריהם כגון שנולד מחלוצה אסור לטמא ואם נולד מספק חלוצה הוי כהן גמור לכל דבר ויתבאר בא\"ע סי' ז' עיין שם:","\u0003גרושה. \u0004 פירוש אפילו יש לו בנים ממנה. מרדכי וכ\"כ האחרונים. ש\"ך:","\u0003מיטמאה. \u0004 כלומר אינה מחויבת לטמא לו אבל הרשות בידה לטמא. ש״ך: \u0005(וכ״כ בטור ובש״ע אה״ע סי' נ״ה וז״ל רש״י בפ' ד' אחין (יבמות דף כ״ט) ולא מיטמאה א״צ להתעסק בו ולאו דוקא נקט ולא מיטמאה דהא בנות אהרן לא הוזהרו על הטומאה אלא איידי דנקט ולא אוננת דאיצטריך ליה נקט ולא מיטמאה דבעי למיתני תרתי בדידה ובדידיה כך שמעתי ולי נראה ולא מיטמאה כגון ברגל שישראלים מוזהרים על הטומאה מונבלתם לא תגעו עכ״ל. נמצא לפי' שני שברש״י אסור לה לטמא לו ברגל משום דהיא ג״כ מוזהרת לטהר עצמה ברגל ומהתימא מהפוסקים ראשונים ואחרונים שהשמיטו את זה בגוף הדין שחייב לטהר את עצמו ברגל דהא אף לפי' הראשון לענין טהרת הרגל מודו דכ״ע חייבים לטהר עצמם עכ״ל בה״י והנה מ״ש שכל הפוסקים לא הביאו דין זה דחייב לטהר כו' לאו דוקא כל הפוסקים שהרי הרמב״ם הביאו בפט״ז מטומאת אוכלין והסמ״ג בעשין רמ״ו. וכן הפוסקים המדברים בדינין שאינן נהוגין עכשיו מביאים ג״כ דין זה. משא״כ הרא״ש והטור ושאר פוסקים שאינן מביאין אלא דינין הנהוגין אין מביאין דין זה. כי עיקר הדין לטהר ברגל קאי על זמן הבית שהיו צריכין להיות טהורים לאכול בקדשים כמ״ש רש״י ורמב״ם. אבל בזמה״ז אין נפקותא בזה בין הרגל לכולי שתא שהרי טמאי מתים אנן ואין לנו אפר פרה ומה גם גזרו טומאה על ארץ העמים ומה טהרה שייך ביה. ואף שאיזה פוסקים כתבו שגם בזמה״ז חייב אדם לטהר עצמו ברגל לאו מטומאת מת ושרץ קאמרי אלא מטומאה היוצא מגופו של אדם וכדומה. וגם מרמזת הטהרה על טהרת הנפש. כי ע״י טהרת הגוף מעורר ומזכך טהרת הנפש כדאיתא בכמה מקומות בראשית חכמה ובשל״ה וזה ברור. וע״כ תפסו הפוסקים פי' ראשון שברש״י דהיא לא מיטמאה לאו דוקא אלא שאינה מחייבת להתעסק בעניני קבורה אבל בנשואין הן כהן וכ״ש ישראל והן אשה כולם שוין לענין זה ליטמא ולהתעסק בשבעה מתים דידהו הן ברגל והן בשאר ימות השנה דמ״ש ואם לא רצו כופין אותן ועי' בשו״ת יד אליהו סימן ס״ח)\u0006:","\u0003נתחללה. \u0004 כגון אחר שנולד כהן זה ממנה נשאת לכהן כשהיתה גרושה. ש\"ך:","\u0003חדשיו. \u0004 לאפוקי ספק נפל דאין מטמאין לו וה\"ה לאחיו ולאחותו הקטנים שהם ספק נפלים אינו מטמא להם. ש\"ך:","\u0003שנתגרשה. \u0004 היינו מן האירוסין וק\"ל:","\u0003הגולל. \u0004 כתב הש\"ך בסי' שע\"ה כתב הטור שיש פלוגתא בין רש\"י ור\"ת מהו הגולל והב\"ח כ' דנקטינן כרש\"י שפירש דהוא כסוי הארון וכתב הרמב\"ן דלרש\"י כשנותנין אותו בבית בארון וסותמין הכסוי במסמרים ע\"ד ליתן הארון בקבר הוי סתימה והוא תמה עליו דהיאך אפשר לומר שאם סתמו ארונו בבית שלא יטמא בנו עליו כו' ולי נראה דמה שפירש\"י בכל מקום גולל היינו כסוי הארון אין ר\"ל אפילו סתמו בבית אלא ר\"ל משיסתם כסוי הארון בקבר תדע דבפ' שואל אמרי' כל שאומרים בפני המת יודע עד שיסתם הגולל דכתיב וישוב העפר אל הארץ כשהיה ופירש\"י גופו קרי עפר ומששב אל הארץ כאשר היה מיד והרוח תשוב שאין בו עוד רוח ע\"כ ולפ\"ז אפילו נסתם הארון במסמרים בבית גם לרש\"י בנו מיטמא עליו עד שיסתם בקבר עכ\"ל:","\u0003ודוקא. \u0004 והב\"ח פסק דאף בהליכה אסור להוסיף טומאה כיון שאפשר לו לקברו בסוף בה\"ק וכ\"כ הלבוש דנכון להחמיר כסברא זו והמ\"מ מיקל בדבר עכ\"ל הש\"ך:"],"r":["\u0003ודוקא כו'. \u0004גמ' שם:","\u0003אבל חלל. \u0004בת\"כ שם \u0005(ויבמות ק' ב') \u0006ובפ\"ק דסנהדרין \u0005(ה' ב'):\u0006","\u0003וכהנת. \u0004בת\"כ שם ובפ\"ק דקדושין וספ\"ג דסוטה וש\"מ:","\u0003וא' האשה. \u0004ערש\"י בכתובות נ\"ג א' ד\"ה ולא מטמאה כו':","\u0003או גרושה. \u0004ת\"כ שם לשארו הקרוב ולא ארוסה אליו ולא גרושה:\n\u0003(ליקוט) או גרושה. \u0004א\"ר פ\"ד ה\"ג (ע\"כ):","\u0003או ארוסה. \u0004כנ\"ל וגמרא פ\"ג דיבמות \u0005(כ\"ט ב') \u0006ופ\"ד דכתובות וש\"מ:","\u0003דקים ליה כו'. \u0004עבה\"ג וכמ\"ש בפי\"ט דשבת \u0005(קל\"ו א'):\u0006","\u0003אפילו הם כו'. \u0004בת\"כ ופ\"ב דיבמות וכמש\"ו:","\u0003אבל לאחיו כו'. \u0004בת\"כ שם ובפ\"ג דמ\"ק \u0005(כ' ב'):\u0006","\u0003וכן אינו כו'. \u0004יבמות ס' א' וכר\"י ור\"ש:","\u0003ומיטמא לשומרת יבם. \u0004ר\"ל שנפלה לפניו כיון שיורש כתובתה וכמ\"ש בכתובות פ\"א א' יורשי כתובתה חייבין כו' וכמ\"ש בקטנה ביבמות פ\"ט ב'. שם. וצ\"ע ועתוס' שם ד\"ה כיון כו':","\u0003ואפילו אם כו'. \u0004דלא פלוג וכמש\"ש בקטנה בסתם אפילו אין לה נכסים. שם:","\u0003כל אלו כו'. \u0004כ\"מ במ\"ש דפליגי כמה ימים מותר ליטמא להם ור\"י אמר עד שיסתם הגולל וכמ\"ש בס\"ו משמע דאף שלא לצורך:\n\u0003(ליקוט) כל אלו כו'. \u0004א\"ר פ\"ד הלכה י\"א מעשה כו' (ע\"כ):","\u0003וי\"א כו'. \u0004תוס' דפסחים ט' א' סד\"ה בשפחתו ובנדה ט\"ו ב' סד\"ה ובא:","\u0003(ליקוט) אינו מטמא כו'. \u0004א\"ר פ\"ד הלכה י' י\"א (ע\"כ):","\u0003ואם דעתו כו'. \u0004כמש\"ל סי' שע\"ה ס\"ג לענין אבלות. שם ברשב\"א:","\u0003אסור כו'. \u0004נזיר מ\"ב ב' וירושלמי פ\"ג דנזיר ומ\"ש פ\"ד ועתוס' דנדה נ\"ז א' ד\"ה ודלמא כו':\n\u0003(ליקוט) אסור כו'. \u0004כמ\"ש בנזיר מ\"ב ב' ואע\"ג דבפ\"ד דא\"ר פליגי בזה ר\"ט ור\"ע והלכה כר\"ע בזה הלכה כר\"ט דר\"ה קאי כוותיה ועוד דסתם במתני' ומחלוקת בברייתא הלכה כסתם ובמתני' שם א\"ל אל תטמא כו' ועוד דסוגיין בפ\"ב דשבועות \u0005(י\"ז א') \u0006בענין נזיר בקבר כר\"ט ועוד דבירושלמי שם המחלוקת להיפך דאיתמר שם יצא ונכנס ר\"ט פוטר ור\"ע מחייב א\"ל ר\"ט וכי מה הוסיף זה חלול על חלולו א\"ל ר\"ע בשעה שהיה שם טמא טומאת שבעה פירש טמא טומאת ערב חזר ונכנס טמא טומאת שבעה א\"ל ר\"ט עקיבא כל הפורש ממך כפורש מחיים וגם ר\"ט הודה לו וכ\"ז לחיוב אבל לאיסורא כ\"ע מודי ודלא כר\"ת וערא\"ש הלכות טומאה ס\"ו (ע\"כ):\n\u0003(ליקוט) אסור לכהן כו' ודוקא כו'. \u0004א\"ר פ\"ד הלכה י\"ג ט\"ו ט\"ז כהן הדיוט כו' היה עומד כו' נטמא כו' (ע\"כ):","\u0003ודוקא כו'. \u0004גמ' שם וירושלמי שם ואמר במ\"ש להדיא דאפילו לכתחלה מותר בכה\"ג והביאו כ\"ז הרא\"ש בה' טומאה ס\"ו ע\"ש:","\u0003כהן שפירשו כו'. \u0004ת\"כ \u0005(וסנהדרין מ\"ז א') \u0006בעמיו בזמן שעושין כו':","\u0003ולא לספק כו'. \u0004מתני' פי\"א דיבמות \u0005(ק' ב') \u0006ועבה\"ג:","\u0003אין כו'. \u0004נזיר שם לד\"ה:","\u0003וכן כו' אע\"פ כו' חסר כו'. \u0004ר\"ל דלא כראב\"י ור\"י אלא כרב וכזקנים ומעשה רב וכ\"ש לחומרא. הרא\"ש שם:","\u0003(ליקוט) וי\"א כו'. \u0004דז\"ש בנזיר מ\"ג \u0005(ב') \u0006אלא מעתה קאזיל כו' \u0005(ד\"ר צ\"ע) \u0006(ע\"כ):"]}],["מִצְוָה לְהִטָּמְאוֹת לְמֵת מִצְוָה, אֲפִלּוּ הוּא כֹּהֵן גָּדוֹל וְנָזִיר וְהוֹלֵךְ לִשְׁחֹט אֶת פִּסְחוֹ, וְלָמוּל אֶת בְּנוֹ, וּמָצָא מֵת מִצְוָה, הֲרֵי זֶה מִטָּמֵא לוֹ.\nאֵינוֹ נִקְרָא מֵת מִצְוָה לְעִנְיָן זֶה, אֶלָּא אִם כֵּן מָצָא רֹאשׁוֹ וְרֻבּוֹ. וְאִם מָצָא רֹאשׁוֹ וְרֻבּוֹ חוּץ מֵאֵבֶר אֶחָד, \u0010y0\u0011 חוֹזֵר לִטָּמֵא בִּשְׁבִיל אוֹתוֹ אֵבֶר.\nאֵיזֶהוּ מֵת מִצְוָה, שֶׁמְּצָאוֹ בַּדֶּרֶךְ אוֹ בְּעִיר שֶׁל עוֹבְדֵי כּוֹכָבִים, וְאֵין לוֹ קוֹבְרִים, וּמִמָּקוֹם שֶׁמְּצָאוֹ \u0010c0\u0011 אֵינוֹ יָכוֹל לִקְרוֹת יִשְׂרָאֵל שֶׁיַּעֲנֵהוּ וְיָבֹא לְטַפֵּל בּוֹ וּלְקָבְרוֹ, אָסוּר לוֹ לָזוּז מִשָּׁם וּלְהַנִּיחַ אֶת הַמֵּת, אֲפִלּוּ לֵילֵךְ לָעִיר לְהָבִיא קוֹבְרִים, אֶלָּא יְטַמֵּא עַצְמוֹ וְיִקְבְּרֶנּוּ. אֲבָל אִם הָיוּ יִשְׂרָאֵל קְרוֹבִים לִמְקוֹם הַמֵּת, שֶׁהַמּוֹצֵא אֶת הַמֵּת קוֹרֵא אוֹתָם וְהֵם עוֹנִים לוֹ וּבָאִים לְקָבְרוֹ, אֵין זֶה מֵת מִצְוָה שֶׁיִּטָּמֵא עָלָיו הַכֹּהֵן, אֶלָּא קוֹרֵא אוֹתָם וְהֵם קוֹבְרִים. בָּאוּ בְּנֵי הָעִיר, אִם יֵשׁ לוֹ כָּל צָרְכּוֹ, מוֹשֵׁךְ אֶת יָדָיו. \u0005(לְשׁוֹן רַמְבַּ\"ן בתה\"א ורא\"ש בְּהִלְכוֹת טֻמְאָה)\u0006 \u0005הַגָּה: יֵשׁ אוֹמְרִים אִם אֵינוֹ מוֹצֵא שֶׁיִּקְבְּרוּהוּ, רַק בְּשָׂכָר, אֵינוֹ חַיָּב לִשְׂכֹּר מִשֶּׁלּוֹ, אֶלָּא מִטָּמֵא, אִם יִרְצֶה\u0006 \u0005(נ\"י פֶּרֶק הָאִשָּׁה רַבָּה בְּשֵׁם ריטב\"א)\u0006. \u0005מֵת הַנִּמְצָא, וְלֹא יַדְעִינָן אִם עוֹבֵד כּוֹכָבִים אִם יִשְׂרָאֵל הוּא, \u0010y1\u0011 אַזְלִינָן בָּתַר רֻבָּא הַנִּמְצָאִים שָׁם, אִם יֵשׁ, \u0010y2\u0011 שֶׁלֹּא נוּכַל לוֹמַר כָּל קָבוּעַ כְּמֶחֱצָה עַל מֶחֱצָה\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת הָרַשְׁבָּ\"א)\u0006.\nכָּל הַקְּרוֹבִים שֶׁהַכֹּהֵן מִטָּמֵא לָהֶם, שֶׁהֵם: אָבִיו, וְאִמּוֹ, וּבְנוֹ, וּבִתּוֹ, וְאָחִיו, וַאֲחוֹתוֹ מֵאָבִיו הַבְּתוּלָה, וְאִשְׁתּוֹ, מִתְאַבְּלִים עֲלֵיהֶם. וְעוֹד הוֹסִיפוּ עֲלֵיהֶם: אָחִיו מֵאִמּוֹ, וַאֲחוֹתוֹ מֵאִמּוֹ, בֵּין בְּתוּלָה בֵּין נְשׂוּאָה, וַאֲחוֹתוֹ נְשׂוּאָה מֵאָבִיו, שֶׁמִּתְאַבְּלִים עֲלֵיהֶם אַף עַל פִּי שֶׁאֵין כֹּהֵן מִטָּמֵא לָהֶם. וּכְשֵׁם שֶׁהוּא מִתְאַבֵּל עַל אִשְׁתּוֹ, כָּךְ הִיא מִתְאַבֶּלֶת עָלָיו. וְדַוְקָא אִשְׁתּוֹ כְּשֵׁרָה וּנְשׂוּאָה, אֲבָל פְּסוּלָה אוֹ אֲרוּסָה, לֹא. אֲבָל בְּנוֹ, וּבִתּוֹ, וְאָחִיו, וַאֲחוֹתוֹ, אֲפִלּוּ הֵם פְּסוּלִים, מִתְאַבֵּל עֲלֵיהֶם, חוּץ מִבְּנוֹ, וּבִתּוֹ וְאָחִיו וַאֲחוֹתוֹ מִשִּׁפְחָה וְכוּתִית, שֶׁאֵינוֹ מִתְאַבֵּל עֲלֵיהֶם.\nהַגֵּר שֶׁנִּתְגַּיֵּר הוּא וּבָנָיו, אוֹ עֶבֶד שֶׁנִּשְׁתַּחְרֵר הוּא וְאִמּוֹ, אֵין מִתְאַבְּלִין זֶה עַל זֶה. \u0010y3\u0011 \u0005וְהוּא הַדִּין גֵּר שֶׁנִּתְגַּיֵּר עִם אִמּוֹ, אֵין מִתְאַבֵּל עֲלֵיהֶם (סְבָרַת הָרַב מֵהַמָּרְדְּכַי הל' שְׂמָחוֹת מִמַּעֲשֶׂה שֶׁבָּא לִפְנֵי ר\"י לְמַאי דקי\"ל אֲבֵלוּת יוֹם רִאשׁוֹן דְּרַבָּנָן)\u0006.\nכָּל מִי שֶׁמִּתְאַבֵּל עָלָיו, מִתְאַבֵּל עִמּוֹ אִם מֵת לוֹ מֵת. וְדַוְקָא בְּעוֹדוֹ בְּפָנָיו, אֲבָל שֶׁלֹּא בְּפָנָיו אֵין צָרִיךְ לִנְהֹג אֲבֵלוּת; חוּץ מֵאִשְׁתּוֹ, שֶׁאַף עַל פִּי שֶׁמִּתְאַבֵּל עָלֶיהָ אֵינוֹ מִתְאַבֵּל עִמָּהּ אֶלָּא עַל אָבִיהָ אוֹ עַל אִמָּהּ מִשּׁוּם כְּבוֹד חָמִיו וַחֲמוֹתוֹ, אֲבָל עַל אָחִיהָ וַאֲחוֹתָהּ אוֹ בְּנָהּ וּבִתָּהּ מֵאִישׁ אַחֵר, אֵינוֹ מִתְאַבֵּל עִמָּהּ. וּמִכָּל מָקוֹם אֵינוֹ יָכוֹל לְכֹפָהּ לְהִתְקַשֵּׁט, אֲבָל יְכוֹלָה לִמְזֹג לוֹ הַכּוֹס וּלְהַצִּיעַ לוֹ הַמִּטָּה וְלִרְחֹץ פָּנָיו יָדָיו וְרַגְלָיו. וְכֵן הִיא אֵינָהּ מִתְאַבֶּלֶת עִמּוֹ, אֶלָּא כְּשֶׁמֵּתוּ חָמִיהָ אוֹ חֲמוֹתָהּ, אֲבָל שְׁאָר קְרוֹבָיו שֶׁמֵּתוּ, אֵינָהּ מִתְאַבֶּלֶת עִמּוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּהָאִידָּנָא נוֹהֲגִין לְהָקֵל בַּאֲבֵלוּת זֶה שֶׁל הַמִתְאַבְּלִים עִמּוֹ, דְּאֵין זֶה אֶלָּא מִשּׁוּם כְּבוֹד הַמִתְאַבְּלִים, וְעַכְשָׁו נָהֲגוּ כֻּלָּם לִמְחֹל. וְכֵן נוֹהֲגִין הָאִדָּנָא שֶׁלֹּא לְהִתְאַבֵּל כְּלָל עִם הַמִתְאַבְּלִים (טוּר בְּשֵׁם הָרֹא\"שׁ וְהוּא בְּפ' א\"מ וְרַמְבַּ\"ן בת\"ה והגמי\"י פֶּרֶק א)\u0006, וְכָל הַמַּחְמִיר בָּזֶה \u0010y4\u0011 אֵינוֹ אֶלָּא מִן הַמַּתְמִיהִים \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ב)\u0006. וּמִכָּל מָקוֹם נָהֲגוּ שֶׁכָּל קְרוֹבֵי הַמֵּת, \u0010y5\u0011 הַפְּסוּלִין לוֹ לְעֵדוּת, מַרְאִין קְצָת אֲבֵלוּת בְּעַצְמָן כָּל שָׁבוּעַ הָרִאשׁוֹנָה, \u0010y6\u0011 \u0010c1\u0011 דְּהַיְנוּ עַד אַחַר שַׁבָּת הָרִאשׁוֹן, שֶׁאֵינָן רוֹחֲצִים וְאֵין מְשַׁנִּים קְצָת בִּגְדֵיהֶם כְּמוֹ בִּשְׁאָר שַׁבָּת \u0005(גְּדוֹלֵי אוסטריי\u0006 ךָ \u0005נָהֲגוּ כֵּן)\u0006. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ עוֹד לְהַחְמִיר בְּעִנְיָנִים אֲחֵרִים, וְהָעִקָּר כְּמוֹ שֶׁכָּתַבְתִּי. וְכָל זֶה בִּשְׁמוּעָה קְרוֹבָה, אוֹ שֶׁהָיָה אֵצֶל הַמִּיתָה; אֲבָל בִּשְׁמוּעָה רְחוֹקָה, אֵין לַאֲבֵלוּת זֶה מָקוֹם כְּלָל \u0005(תִּמְצָא הַכֹּל מְבֹאָר בת\"ה סִימָן רנ\"א)\u0006. מִי שֶׁרוֹצֶה לְהַחְמִיר עַל עַצְמוֹ לְהִתְאַבֵּל עַל מִי שֶׁאֵינוֹ צָרִיךְ, אוֹ לִלְבֹּשׁ שְׁחֹרִים עַל קְרוֹבוֹ, אֵין מוֹחִין בְּיָדוֹ \u0005(הָרֹא\"שׁ כְּלָל כ\"ז דִּין ט')\u0006.\nאֵין מִתְאַבְּלִים עִם הַקְּרוֹבִים שֶׁמִּתְאַבְּלִים עֲלֵיהֶם, אֶלָּא כְּשֶׁמִּתְאַבְּלִים עַל הַקֻּרְבָה דִּשְׁאֵר, כְּגוֹן בְּנוֹ וְאָחִיו שֶׁמִּתְאַבֵּל עַל בֵּן וּבַת שֶׁלָּהֶם; אֲבָל עַל קֻרְבָה דְּקִדּוּשִׁין שֶׁלָּהֶם, כְּגוֹן שֶׁמֵּתָה אֵשֶׁת בְּנוֹ אוֹ אֵשֶׁת אָחִיו אוֹ בַּעַל בִּתּוֹ אוֹ בַּעַל אֲחוֹתוֹ, אֵינוֹ מִתְאַבֵּל עֲלֵיהֶם.\nתִּינוֹק, כָּל שְׁלֹשִׁים יוֹם וְיוֹם שְׁלֹשִׁים בַּכְּלָל, \u0010y7\u0011 אֵין מִתְאַבְּלִים עָלָיו, אֲפִלּוּ גָּמְרוּ שְׂעָרוֹ וְצִפָּרְנָיו; וּמִשָּׁם וָאֵילָךְ מִתְאַבֵּל עָלָיו, אֶלָּא אִם כֵּן נוֹדַע שֶׁהוּא בֶּן ח'. וְאִי קִים לֵיהּ בֵּיהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו, כְּגוֹן שֶׁבָּעַל וּפֵרֵשׁ וְנוֹלַד חַי לִט' חֳדָשִׁים גְּמוּרִים, אֲפִלּוּ מֵת בַּיּוֹם שֶׁנּוֹלַד, מִתְאַבְּלִים עָלָיו. \u0005סָפֵק בֶּן ט' לָרִאשׁוֹן (אוֹ)\u0006 בֶּן ז' לָאַחֲרוֹן, \u0010c2\u0011 שְׁנֵיהֶם מִתְאַבְּלִים עָלָיו \u0005(מָרְדְּכַי הִלְכוֹת אֲבֵלוּת וְהַגָּהוֹת מַיְמוֹנִי פֶּרֶק א' וּבֵית יוֹסֵף בְּשֵׁם הַתּוֹסָפוֹת)\u0006.\nיֵשׁ מִי שֶׁאוֹמֵר דִּתְאוֹמִים שֶׁמֵּת א' מֵהֶם תּוֹךְ שְׁלֹשִׁים יוֹם, \u0010y8\u0011 וְהַשֵּׁנִי חַי \u0010c3\u0011 וּמֵת אַחַר ל' יוֹם, אֵין מִתְאַבְּלִין עָלָיו. \u0010y9\u0011\nעַל רַבּוֹ שֶׁלִּמְּדוֹ חָכְמָה נוֹהֵג דִּינֵי אֲנִינוּת, אֶלָּא שֶׁמְּבָרֵךְ וּמְזַמֵּן וּמִתְאַבֵּל עָלָיו בַּחֲלִיצַת סַנְדָּל \u0010c4\u0011 וְכָל דִּינֵי אֲבֵלוּת, יוֹם אֶחָד. \u0005(וְכָתַב הַבֵּית יוֹסֵף בְּשֵׁם רַבִּי שִׂמְחָה שֶׁצָרִיךְ לְשַׁנּוֹת מְקוֹמוֹ בב\"ה, מִיהוּ בְּמִקְצָת הַיּוֹם סָגֵי)\u0006.\nנָשִׂיא, אַף עַל פִּי שֶׁהַכֹּל מִטָּמְאִין לוֹ, אֵין מִתְאַבְּלִים עָלָיו. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּאֵין מִתְאַבְּלִין עַל בֵּן הָרִאשׁוֹן אוֹ בֵּן הַבְּכוֹר שֶׁמֵּת לְאָדָם (כָּל בּוֹ וריב\"ש וּבֵית יוֹסֵף הֵבִיאוּ מִי שֶׁנָּהֲגוּ כֵּן, וְהֵם כָּתְבוּ שֶׁהוּא טָעוּת)\u0006 ; וְהַמִּנְהָג הוּא מִנְהַג טָעוּת, אֶלָּא חַיָּבִים לְהִתְאַבֵּל עֲלֵיהֶם. וּמִכָּל מָקוֹם נִשְׁתַּרְבֵּב הַמִּנְהָג בְּעִירֵנוּ \u0010y10\u0011 שֶׁאֵין אָב וָאֵם הוֹלְכִים אַחַר בְּנֵיהֶם הָרִאשׁוֹן לְבֵית הַקְּבָרוֹת. יֵשׁ אוֹמְרִים בִּשְׁעַת הַדֶּבֶר אֵין מִתְאַבְּלִים, מִשּׁוּם בִּיעֲתוּתָא \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ג')\u0006, וְשָׁמַעְתִּי קְצָת נָהֲגוּ כֵּן.",["\u0003חוזר ליטמא כו'.\u0004 כלומר דאע\"ג דאינו מטמא עליו אלא כשמצא ראשו ורובו היינו לטמאות לכתחלה אבל אם כבר קברו חוץ מאבר א' חוזר לטמאות על אותו אבר ובזה חמור מהקרובים שאינו מטמא להם אלא א\"כ הם שלמים כדלעיל ס\"ס הקודם:","\u0003אזלינן בתר רוב הנמצאים שם אם לא שנוכל לומר כל קבוע כמחצה כו'. \u0004כצ\"ל ור\"ל דאזלינן בתר רוב העוברים ושבים המצויים שם או בתר רוב עיירות אם רובו עובדי כוכבים א\"צ לקברו ואם רובו ישראל הוי מת מצוה ולא אזלינן בתר העיר הקרובה אפי' בקורבה דמוכח אלא בתר רובו אזלינן דכל דפריש מרובא פריש כן הוא בתשו' הרשב\"א סי' פ\"ג ס\"ק ח':","\u0003שנוכל לומר כל קבוע כו'. \u0004כגון שידוע שהיו כאן ט' עובדי כוכבים וחד ישראל ונהרג אחד מהן במקומו דה\"ל קבוע לא אזלינן בתר רוב עובדי כוכבים אלא הוי כמחצה על מחצה וכ' העט\"ז ולחומרא ואין הכהן מטמא עכ\"ל ר\"ל דכיון דהוי כמחצה על מחצה אם כן הוי ספיקא ואזלינן לחומרא וצריך לקברו ומ\"מ אין הכהן מיטמא מספק כדלעיל סי' שע\"ג ס\"ח:","\u0003וה\"ה גר כו'. \u0004ואע\"פ דבמרדכי כ' דגר מתאבל על אמו היינו למ\"ד אבילות יום ראשון דאורי' ולא לדידן דקי\"ל לקמן ס\"ס שצ\"ט דהוא מדרבנן וכן כ' בד\"מ:","\u0003אינו אלא מן המתמיהים. \u0004ואינו כמכבד האבלים אלא כלועג להם. שם בהגמ\"ר ואע\"ג דמי שרוצה להחמיר ולהתאבל על מי שאינו צריך הרשות בידו וכמ\"ש הרב בסוף ההג\"ה היינו דוקא כשמתאבל לגמרי כדין אבילות אבל כשאינו מתאבל אלא לפניו הוי כלועג לאבל. נ\"ל:","\u0003הפסולים לו לעדות כו'. \u0004עיין בח\"מ סי' ל\"ג איזהו פסולין לעדות ומ\"מ נראה דדוקא פסולי עדות מחמת קורבה דשאר ולא פסולי עדות מחמת קורבה דקידושין כדלקמן בסעיף שאח\"ז והכי נהוג שאינם רוחצים כי אם בפושרים גמורים. ת\"ה שם:","\u0003דהיינו עד אחר שבת הראשון. \u0004הן סמוך הן מופלג וכ' הב\"ח דכ\"ש דאסור לילך לסעודת מצוה כגון ברית מילה עד מוצאי שבת ע\"ש ובתשו' משאת בנימין סי' פ\"ג כ' וז\"ל קרובי המת שאינן חייבים להתאבל ומ\"מ מראין קצת סימני אבילות ראיתי מקומות חלוקים בזה יש מקומות שנוהגין רק פסולי עדות למת מראין אבילות אבל הכשרים לעדות אין מראין אבילות כלל ויש מקומות שאפי' שלישי ברביעי מראין אבילות והיכא דנהוג נהוג והיכא דלא נהוג נראה דאין להראות אבילות רק הפסולים לעדות וכדעת תרומת הדשן סימן רצ\"ח מ\"מ נראה דאין כל הקרובים שוים לזה אלא קרוב קרוב קודם ואותם קרובים שמן הדין היו חייבים להתאבל ממש כדאמרינן כל שאתה מתאבל עליו אתה מתאבל עמו אף ע\"ג דהאידנא לא נהיגין הכי מ\"מ באבילות ממש צריכין להראות אבילות ביום המית' או ביום השמוע' אם הוא תוך ל' עד מוצאי שבת הא' ואין להחליף מבגדי חול לבגדי שבת וגם אין לרחוץ בחמין גם לא לחוף הראש רק בצונן או במים פושרין גם אין לאכול חוץ לביתו לא בסעודת מצוה ולא בסעודת מריעות אבל כתונת לבן אין למנוע לכבוד שבת גם אין לשנות את מקומם בב\"ה אבל במו\"ש מותר בכל דבר בין אם הוא מופלג או סמוך ואותן הקרובים שמן הדין אין מתאבלין אין להחמיר עליהן ברחיצת חמין וחפיפת הראש ולא בחילוף בגדי שבת כל כך ודי להם בבגד העליון של חול ושלא לאכול חוץ לבית וכ\"ש אותן מקומות שנהגו דאפילו הכשרים לעדות מראי' קצת אבילות שאין להחמיר כל כך עכ\"ל ומ\"ש להתיר ברחיצת חמין וחפיפת הראש באותן קרובים שאין מתאבלים עם מי שמתאבל עמהן אין נראה כן מדברי ת\"ה והרב דהא אוסרי' ברחיצ' על קרובי המת הפסולים לעדות דהיינו שני בשני אע\"ג שאין מתאבלין גם מ\"ש להחמיר שאין להחליף כלל מבגדי חול לשבת כאותן שמתאבלין אין נראה כן מדבריהם אלא משנים רק קצת מבגדיהן ומ\"מ נראה דהולכים בדברים אלו אחר המנהג:","\u0003אין מתאבלין עליו כו'. \u0004משמע דמיירי דלא קים לן שכלו חדשיו והיינו שהשיג הב\"י על הגהת אשר\"י וז\"ל ואיני יודע למה התנה שלא גמרו שערו וצפרניו כו' דלא כהב\"ח שכ' על הב\"י ומ\"ש הגהת אשר\"י ולא גמרו שערו וצפרניו כו' היינו משום דאי גמרו שערו וצפרניו ודאי מתאבלין כיון דספק הוא אם כלו חדשיו תלינן דכלו לו חדשיו כיון דלא מת עד לאחר שלשים וגם גמרו שערו וצפרניו והב\"י כתב על הגהת אשר\"י זו ואיני יודע כו' ושגגה יצאה מתחת קולמסו דהדבר פשוט כדפרישית עכ\"ל ולא עמדתי על סוף דעתו דהא הב\"י מיירי השתא במת תוך ל' וכן מיירי בהגהת אשר\"י וז\"ל בסוף מ\"ק והיכא דלא קים לן אי כלו לו חדשיו או לאו ולא גמרו שערו וצפרניו ומת ביום ל' אין מתאבלין עליו עכ\"ל ודוחק לומר דמת ביום ל' דינו כלאחר ל' דהא קי\"ל בענין אבילות דיום ל' כתוך ל' וכדמסיק רב אשי בפרק יש בכור ריש (בכורות ד' מ\"ט) וכן דעת הרמב\"ן והטור להדיא דאם מת ביום שלשים אפי' גמרו שערו וצפרניו אין מתאבלין עליו היכא דלא קים ליה ביה שכלו חדשיו וכן דעת המחבר:","\u0003והשני חי אחר שלשים יום כו' כצ\"ל. \u0004ור\"ל אין מתאבלין ע\"ז שמת תוך ל' ולא אמרינן מדזה הוא חי והוא בן קיימא אפילו גם זה שמת מסתמא בן קיימא הוי דלא כהעט\"ז שכתב שאין מתאבלין על זה השני שמת אחר שלשים דמסתמא נמי נפל היה דהא ודאי ליתא וכבר השיג עליו הב\"ח בזה וכן משמע להדיא בא\"ז גופיה שממנו מקור דין זה ומביאו בד\"מ וז\"ל תשובה על תאומים שמת אחד מהן תוך ל' והשני חי לא אמרינן מדהשני חי הראשון נמי בן קיימא הוי ואין מתאבלין עליו עכ\"ל תשובת הרשב\"א וכן פירש בהגה' דרישה ועיקר:","\u0003על רבו כו'. \u0004ע\"ל סימן רמ\"ב סעיף כ\"ו:","\u0003שאין אב ואם הולכים כו'. \u0004אבל על בניהם השני הולכים אע\"פ שהראשון היה נפל וכן נוהגין:"],["\u0003אינו יכול לקרות ישראל. \u0004כתב רש\"ל לעולם הוא מ\"מ עד שיהיו שם נושאי המטה וקובריה. רוקח עכ\"ל:","\u0003עד אחר שבת הראשון. \u0004כתב מו\"ח ז\"ל כ\"ש שאין נכנסין לסעודה אפילו לסעודת מצוה עד מוצ\"ש ובספר משאת בנימין כ' שיש להחמיר עוד שלא לחוף הראש בחמין אותו ערב שבת:","\u0003שניהם מתאבלין עליו. \u0004אע\"ג דאבילות דרבנן החמירו כאן בספק דגנאי היה לו אם לא היו מתאבלין עליו כלל. כ\"כ במרדכי:","\u0003ומת אחר ל' יום אין מתאבלין עליו. \u0004לפי זה משמע דעל השני אין מתאבלין והטעם דאנו רואין שגם השני אינו בן קיימא כיון שהוא מטיפה אחת עם הראשון וכ\"פ בלבוש ואמר דהיינו דוקא כשהי' השני ג\"כ חולה בשעת מיתת הראשון והאריך בזה לחזק דבריו ובאמת דעתו מתמיה מאד לפטור מאבילות מכח סברא חלושה כזאת ובדרכי משה ראיתי שהעתיק בלשון זה כתב אור זרוע תשובה על תאומים שמת אחד מהן תוך שלשים והשני חי לא אמרינן מדהשני חי הראשון נמי הוה בן קיימא ואין מתאבלין עליו עכ\"ל רשב\"א עכ\"ל. ונמצא דעל הראשון קאמר דאין מתאבלין אבל על השני דמת אחר שלשים יום ודאי מתאבלין עליו וכאן הוא ט\"ס וצריך להיות והשני חי עדיין אחר שלשים יום אין מתאבלים עליו וקאי על הראשון וכן משמע בסימני הטור שחיבר בעל השו\"ע שז\"ל תאומים שמת אחד מהם תוך שלשים יום והשני חי עדיין אין מתאבלין עליו אפילו מת בסוף שלשים עכ\"ל הרי כ' אין מתאבלין עליו קודם שזכר אפי' מת בסוף ל' ואם איתא דעל השני כ' אין מתאבלין היה לו לכתוב תחילה מיתתו של שני ואדרבה כתבו אחר שכ' שהשני חי עדיין אלא פשוט שעל הראשון קאי ועליה מסיים אפי' מת בסוף ל' כלומר ביום הל' עצמו אפ\"ה אין מתאבלין עליו אע\"פ שיש שתי סברות להתאבל על הראשון. האחת כיון שחי עד יום ל' ובו מת ועוד שהשני חי עדיין והם מטפה אחת הוה אמינא כמו שהשני בן קיימא ה\"נ הראשון קמ\"ל דלא ומימים רבים הודעתי דברים אלו למו\"ח ז\"ל והשיב לי שמזמן קודם הרבה התעורר אותו הרב הגאון מוהר\"ר משה חריף ז\"ל בזה וכן עלה המוסכם בין שניהם וכן קבע בחבורו דאראשון דוקא קאי וכן כתב בפרישה. אח\"כ מצאתי בתשובת מהר\"ם מינץ בסי' נ\"ה שהביא בהדיא המקור מהלכות שמחות שדין זה קאי שהשני חי עדיין ואז נאמר שהראשון גם כן לא היה נפל ולקמן סימן שצ\"ז אעתיק דבריו ודברי הלבוש אינם נכונים בזה דעל השני אם מת פשיטא שחייב להתאבל עליו. שוב ראיתי שגם מהר\"ר מאיר ז\"ל מלובלין פסק בתשובות סימן ס\"ז דאין להתאבל על השני מכח הג\"ה זאת והוא מחסרון ידיעה שהיה לו להרב בזה ועלה לו כמו לבעל הלבוש:","\u0003וכל דיני אבילות יום אחד. \u0004בסימן רמ\"ב מבואר דסגי במקצת יום ראשון וכתב רש\"ל ונכון להם שלא לשתות ולא לאכול בשר כל היום עד לאחר קבורה מא\"ז עכ\"ל:"],"\u0010g0\u0011 מִצְוָה לְהִטָּמְאוֹת לְמֵת מִצְוָה, אֲפִלּוּ הוּא כֹּהֵן גָּדוֹל וְנָזִיר וְהוֹלֵךְ לִשְׁחֹט אֶת פִּסְחוֹ, וְלָמוּל אֶת בְּנוֹ, וּמָצָא מֵת מִצְוָה, הֲרֵי זֶה מִטָּמֵא לוֹ. \u0010g1\u0011\nאֵינוֹ נִקְרָא מֵת מִצְוָה לְעִנְיָן זֶה, אֶלָּא אִם כֵּן מָצָא רֹאשׁוֹ \u0010g2\u0011 וְרֻבּוֹ. וְאִם מָצָא רֹאשׁוֹ וְרֻבּוֹ חוּץ מֵאֵבֶר אֶחָד, \u0010y0\u0011 חוֹזֵר \u0010t0\u0011 לִטָּמֵא בִּשְׁבִיל אוֹתוֹ אֵבֶר. \u0010g3\u0011 \u0010r0\u0011\nאֵיזֶהוּ מֵת מִצְוָה, שֶׁמְּצָאוֹ בַּדֶּרֶךְ אוֹ בְּעִיר שֶׁל עוֹבְדֵי כּוֹכָבִים, וְאֵין לוֹ קוֹבְרִים, וּמִמָּקוֹם שֶׁמְּצָאוֹ \u0010c0\u0011 אֵינוֹ יָכוֹל לִקְרוֹת יִשְׂרָאֵל שֶׁיַּעֲנֵהוּ וְיָבֹא לְטַפֵּל בּוֹ וּלְקָבְרוֹ, אָסוּר לוֹ לָזוּז מִשָּׁם וּלְהַנִּיחַ אֶת הַמֵּת, אֲפִלּוּ לֵילֵךְ לָעִיר לְהָבִיא קוֹבְרִים, אֶלָּא יְטַמֵּא עַצְמוֹ וְיִקְבְּרֶנּוּ. אֲבָל אִם הָיוּ יִשְׂרָאֵל קְרוֹבִים לִמְקוֹם הַמֵּת, שֶׁהַמּוֹצֵא אֶת הַמֵּת קוֹרֵא אוֹתָם וְהֵם עוֹנִים לוֹ וּבָאִים לְקָבְרוֹ, אֵין זֶה מֵת מִצְוָה שֶׁיִּטָּמֵא עָלָיו הַכֹּהֵן, אֶלָּא קוֹרֵא אוֹתָם וְהֵם קוֹבְרִים. בָּאוּ בְּנֵי הָעִיר, \u0010g4\u0011 \u0010r1\u0011 אִם יֵשׁ לוֹ כָּל \u0010t1\u0011 צָרְכּוֹ, מוֹשֵׁךְ אֶת יָדָיו. \u0005(לְשׁוֹן רַמְבַּ\"ן בתה\"א ורא\"ש בְּהִלְכוֹת טֻמְאָה)\u0006 \u0005הַגָּה: יֵשׁ אוֹמְרִים אִם אֵינוֹ מוֹצֵא שֶׁיִּקְבְּרוּהוּ, רַק בְּשָׂכָר, אֵינוֹ חַיָּב לִשְׂכֹּר מִשֶּׁלּוֹ, אֶלָּא מִטָּמֵא, אִם יִרְצֶה\u0006 \u0005(נ\"י פֶּרֶק הָאִשָּׁה רַבָּה בְּשֵׁם ריטב\"א)\u0006. \u0010r2\u0011 \u0005מֵת הַנִּמְצָא, וְלֹא יַדְעִינָן אִם עוֹבֵד כּוֹכָבִים אִם יִשְׂרָאֵל הוּא, \u0010y1\u0011 אַזְלִינָן בָּתַר \u0010t2\u0011 רֻבָּא הַנִּמְצָאִים שָׁם, אִם יֵשׁ, \u0010y2\u0011 שֶׁלֹּא נוּכַל לוֹמַר כָּל קָבוּעַ כְּמֶחֱצָה עַל מֶחֱצָה\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת הָרַשְׁבָּ\"א)\u0006. \u0010g5\u0011\nכָּל הַקְּרוֹבִים שֶׁהַכֹּהֵן מִטָּמֵא לָהֶם, שֶׁהֵם: אָבִיו, וְאִמּוֹ, וּבְנוֹ, וּבִתּוֹ, וְאָחִיו, וַאֲחוֹתוֹ מֵאָבִיו הַבְּתוּלָה, וְאִשְׁתּוֹ, מִתְאַבְּלִים עֲלֵיהֶם. \u0010g6\u0011 וְעוֹד הוֹסִיפוּ עֲלֵיהֶם: אָחִיו מֵאִמּוֹ, וַאֲחוֹתוֹ מֵאִמּוֹ, בֵּין בְּתוּלָה בֵּין נְשׂוּאָה, וַאֲחוֹתוֹ נְשׂוּאָה מֵאָבִיו, שֶׁמִּתְאַבְּלִים עֲלֵיהֶם אַף עַל פִּי שֶׁאֵין כֹּהֵן מִטָּמֵא לָהֶם. \u0010g7\u0011 \u0010r3\u0011 וּכְשֵׁם שֶׁהוּא מִתְאַבֵּל עַל אִשְׁתּוֹ, כָּךְ הִיא מִתְאַבֶּלֶת עָלָיו. \u0010r4\u0011 וְדַוְקָא אִשְׁתּוֹ כְּשֵׁרָה וּנְשׂוּאָה, אֲבָל פְּסוּלָה אוֹ אֲרוּסָה, לֹא. \u0010g8\u0011 אֲבָל בְּנוֹ, וּבִתּוֹ, וְאָחִיו, וַאֲחוֹתוֹ, אֲפִלּוּ הֵם פְּסוּלִים, מִתְאַבֵּל עֲלֵיהֶם, חוּץ מִבְּנוֹ, וּבִתּוֹ וְאָחִיו וַאֲחוֹתוֹ מִשִּׁפְחָה וְכוּתִית, שֶׁאֵינוֹ מִתְאַבֵּל עֲלֵיהֶם. \u0010g9\u0011 \u0010r5\u0011\nהַגֵּר שֶׁנִּתְגַּיֵּר הוּא וּבָנָיו, אוֹ עֶבֶד שֶׁנִּשְׁתַּחְרֵר הוּא וְאִמּוֹ, אֵין מִתְאַבְּלִין זֶה עַל זֶה. \u0010y3\u0011 \u0005וְהוּא הַדִּין גֵּר שֶׁנִּתְגַּיֵּר עִם אִמּוֹ, אֵין מִתְאַבֵּל עֲלֵיהֶם (סְבָרַת הָרַב מֵהַמָּרְדְּכַי הל' שְׂמָחוֹת מִמַּעֲשֶׂה שֶׁבָּא לִפְנֵי ר\"י לְמַאי דקי\"ל אֲבֵלוּת יוֹם רִאשׁוֹן דְּרַבָּנָן)\u0006. \u0010g10\u0011\nכָּל מִי שֶׁמִּתְאַבֵּל עָלָיו, מִתְאַבֵּל עִמּוֹ אִם מֵת לוֹ מֵת. וְדַוְקָא בְּעוֹדוֹ בְּפָנָיו, אֲבָל שֶׁלֹּא בְּפָנָיו אֵין צָרִיךְ לִנְהֹג אֲבֵלוּת; חוּץ מֵאִשְׁתּוֹ, שֶׁאַף עַל פִּי שֶׁמִּתְאַבֵּל עָלֶיהָ אֵינוֹ מִתְאַבֵּל עִמָּהּ \u0010g11\u0011 אֶלָּא עַל אָבִיהָ אוֹ עַל אִמָּהּ מִשּׁוּם כְּבוֹד חָמִיו וַחֲמוֹתוֹ, אֲבָל עַל אָחִיהָ וַאֲחוֹתָהּ אוֹ בְּנָהּ וּבִתָּהּ מֵאִישׁ אַחֵר, אֵינוֹ מִתְאַבֵּל עִמָּהּ. \u0010g12\u0011 וּמִכָּל מָקוֹם אֵינוֹ יָכוֹל לְכֹפָהּ לְהִתְקַשֵּׁט, אֲבָל יְכוֹלָה לִמְזֹג לוֹ הַכּוֹס וּלְהַצִּיעַ לוֹ הַמִּטָּה וְלִרְחֹץ פָּנָיו יָדָיו וְרַגְלָיו. \u0010r6\u0011 וְכֵן הִיא אֵינָהּ מִתְאַבֶּלֶת עִמּוֹ, אֶלָּא כְּשֶׁמֵּתוּ חָמִיהָ אוֹ חֲמוֹתָהּ, \u0010g13\u0011 אֲבָל שְׁאָר קְרוֹבָיו שֶׁמֵּתוּ, אֵינָהּ מִתְאַבֶּלֶת עִמּוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּהָאִידָּנָא נוֹהֲגִין לְהָקֵל בַּאֲבֵלוּת זֶה שֶׁל הַמִתְאַבְּלִים עִמּוֹ, דְּאֵין זֶה אֶלָּא מִשּׁוּם כְּבוֹד הַמִתְאַבְּלִים, וְעַכְשָׁו נָהֲגוּ כֻּלָּם לִמְחֹל. וְכֵן נוֹהֲגִין הָאִדָּנָא שֶׁלֹּא לְהִתְאַבֵּל כְּלָל עִם הַמִתְאַבְּלִים (טוּר בְּשֵׁם הָרֹא\"שׁ וְהוּא בְּפ' א\"מ וְרַמְבַּ\"ן בת\"ה והגמי\"י פֶּרֶק א)\u0006, וְכָל הַמַּחְמִיר בָּזֶה \u0010y4\u0011 אֵינוֹ אֶלָּא מִן \u0010t3\u0011 הַמַּתְמִיהִים \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ב)\u0006. \u0010r7\u0011 וּמִכָּל מָקוֹם נָהֲגוּ שֶׁכָּל קְרוֹבֵי הַמֵּת, \u0010y5\u0011 הַפְּסוּלִין לוֹ \u0010t4\u0011 לְעֵדוּת, מַרְאִין קְצָת אֲבֵלוּת בְּעַצְמָן כָּל שָׁבוּעַ הָרִאשׁוֹנָה, \u0010y6\u0011 \u0010c1\u0011 דְּהַיְנוּ עַד אַחַר שַׁבָּת \u0010t5\u0011 הָרִאשׁוֹן, שֶׁאֵינָן רוֹחֲצִים וְאֵין מְשַׁנִּים קְצָת בִּגְדֵיהֶם כְּמוֹ בִּשְׁאָר שַׁבָּת \u0005(גְּדוֹלֵי אוסטריי\u0006 ךָ \u0005נָהֲגוּ כֵּן)\u0006. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ עוֹד לְהַחְמִיר בְּעִנְיָנִים אֲחֵרִים, וְהָעִקָּר כְּמוֹ שֶׁכָּתַבְתִּי. וְכָל זֶה בִּשְׁמוּעָה קְרוֹבָה, אוֹ שֶׁהָיָה אֵצֶל הַמִּיתָה; אֲבָל בִּשְׁמוּעָה רְחוֹקָה, אֵין לַאֲבֵלוּת זֶה מָקוֹם כְּלָל \u0005(תִּמְצָא הַכֹּל מְבֹאָר בת\"ה סִימָן רנ\"א)\u0006. מִי שֶׁרוֹצֶה לְהַחְמִיר עַל עַצְמוֹ לְהִתְאַבֵּל עַל מִי שֶׁאֵינוֹ צָרִיךְ, אוֹ לִלְבֹּשׁ שְׁחֹרִים עַל קְרוֹבוֹ, אֵין מוֹחִין בְּיָדוֹ \u0005(הָרֹא\"שׁ כְּלָל \u0010g14\u0011 \u0010r8\u0011 כ\"ז דִּין ט')\u0006.\nאֵין מִתְאַבְּלִים עִם הַקְּרוֹבִים שֶׁמִּתְאַבְּלִים עֲלֵיהֶם, אֶלָּא כְּשֶׁמִּתְאַבְּלִים עַל הַקֻּרְבָה דִּשְׁאֵר, כְּגוֹן בְּנוֹ וְאָחִיו שֶׁמִּתְאַבֵּל עַל בֵּן וּבַת שֶׁלָּהֶם; אֲבָל עַל קֻרְבָה דְּקִדּוּשִׁין שֶׁלָּהֶם, כְּגוֹן שֶׁמֵּתָה אֵשֶׁת בְּנוֹ אוֹ אֵשֶׁת אָחִיו אוֹ בַּעַל בִּתּוֹ אוֹ בַּעַל אֲחוֹתוֹ, אֵינוֹ מִתְאַבֵּל עֲלֵיהֶם. \u0010g15\u0011\nתִּינוֹק, כָּל שְׁלֹשִׁים יוֹם \u0010g16\u0011 וְיוֹם שְׁלֹשִׁים בַּכְּלָל, \u0010y7\u0011 אֵין מִתְאַבְּלִים עָלָיו, אֲפִלּוּ גָּמְרוּ שְׂעָרוֹ וְצִפָּרְנָיו; וּמִשָּׁם וָאֵילָךְ מִתְאַבֵּל עָלָיו, \u0010g17\u0011 \u0010r9\u0011 אֶלָּא אִם כֵּן נוֹדַע שֶׁהוּא בֶּן ח'. \u0010g18\u0011 וְאִי קִים לֵיהּ בֵּיהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו, \u0010g19\u0011 כְּגוֹן שֶׁבָּעַל וּפֵרֵשׁ וְנוֹלַד חַי לִט' חֳדָשִׁים גְּמוּרִים, אֲפִלּוּ מֵת בַּיּוֹם שֶׁנּוֹלַד, מִתְאַבְּלִים עָלָיו. \u0010r10\u0011 \u0005סָפֵק בֶּן ט' לָרִאשׁוֹן (אוֹ)\u0006 בֶּן ז' לָאַחֲרוֹן, \u0010c2\u0011 שְׁנֵיהֶם מִתְאַבְּלִים עָלָיו \u0005(מָרְדְּכַי הִלְכוֹת אֲבֵלוּת וְהַגָּהוֹת מַיְמוֹנִי פֶּרֶק א' וּבֵית יוֹסֵף בְּשֵׁם הַתּוֹסָפוֹת)\u0006. \u0010g20\u0011 \u0010r11\u0011\nיֵשׁ מִי שֶׁאוֹמֵר דִּתְאוֹמִים שֶׁמֵּת א' מֵהֶם תּוֹךְ שְׁלֹשִׁים יוֹם, \u0010y8\u0011 וְהַשֵּׁנִי חַי \u0010c3\u0011 וּמֵת אַחַר ל' יוֹם, אֵין מִתְאַבְּלִין \u0010t6\u0011 עָלָיו. \u0010y9\u0011 \u0010g21\u0011\nעַל רַבּוֹ שֶׁלִּמְּדוֹ חָכְמָה נוֹהֵג דִּינֵי אֲנִינוּת, \u0010g22\u0011 אֶלָּא שֶׁמְּבָרֵךְ וּמְזַמֵּן וּמִתְאַבֵּל עָלָיו בַּחֲלִיצַת סַנְדָּל \u0010c4\u0011 וְכָל דִּינֵי אֲבֵלוּת, \u0010g23\u0011 יוֹם \u0010t7\u0011 אֶחָד. \u0005(וְכָתַב הַבֵּית יוֹסֵף בְּשֵׁם רַבִּי שִׂמְחָה שֶׁצָרִיךְ לְשַׁנּוֹת מְקוֹמוֹ בב\"ה, מִיהוּ בְּמִקְצָת הַיּוֹם סָגֵי)\u0006. \u0010g24\u0011\nנָשִׂיא, אַף עַל פִּי \u0010r12\u0011 שֶׁהַכֹּל מִטָּמְאִין לוֹ, \u0010r13\u0011 אֵין מִתְאַבְּלִים עָלָיו. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּאֵין מִתְאַבְּלִין עַל בֵּן הָרִאשׁוֹן אוֹ בֵּן הַבְּכוֹר שֶׁמֵּת לְאָדָם (כָּל בּוֹ וריב\"ש וּבֵית יוֹסֵף הֵבִיאוּ מִי שֶׁנָּהֲגוּ כֵּן, וְהֵם כָּתְבוּ שֶׁהוּא טָעוּת)\u0006 ; וְהַמִּנְהָג הוּא מִנְהַג טָעוּת, אֶלָּא חַיָּבִים לְהִתְאַבֵּל עֲלֵיהֶם. וּמִכָּל מָקוֹם נִשְׁתַּרְבֵּב הַמִּנְהָג בְּעִירֵנוּ \u0010y10\u0011 שֶׁאֵין אָב וָאֵם הוֹלְכִים אַחַר בְּנֵיהֶם \u0010t8\u0011 הָרִאשׁוֹן לְבֵית הַקְּבָרוֹת. יֵשׁ אוֹמְרִים בִּשְׁעַת הַדֶּבֶר אֵין מִתְאַבְּלִים, מִשּׁוּם בִּיעֲתוּתָא \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ג')\u0006, וְשָׁמַעְתִּי קְצָת נָהֲגוּ כֵּן.",{"g":["\u0003ברייתא ברכות דף י\"ט ע\"ב ונזיר דף מ\"ג ע\"ב:\u0004 ","\u0003ברייתא באבל רבתי וכת\"ק:\u0004 ","\u0003ירושל' כ\"ז דנזיר:\u0004 ","\u0003ברייתא יבמות דף פ\"ט ע\"ב ומהירושלמי שם בנזיר:\u0004 ","עיין בטור איזה מקרי כל צרכו:\n(°) דאינם קבועים בדרך אלא ניידי:","\u0003ברייתא מ\"ק דף כ' ע\"ב:\u0004 ","\u0003שם בברייתא:\u0004 ","מדברי הרמב\"ם והרא\"ש וטעמא דכיון דתלוי אבילות בטומאה כשם שהאשה מיטמאה על בעלה כך היא מתאבלת עליו:","\u0003ממשנה יבמות דף כ\"ב ע\"א:\u0004 ","ג\"ז ברמב\"ם שם בפ\"ב וכ' הכ\"מ שהוא נלמד מדין בנו שהוא מן השפחה ומן הכותית ועוד דגר שנתגייר כקטן שנולד דמי:","\u0003ברייתא מ\"ק דף כ' ע\"ב וכאוקימתא דגמ' שם:\u0004 ","\u0003ברייתא שם:\u0004 ","\u0003ברייתא שם:\u0004 ","כדעת הרמב\"ם שם בפ\"ב והביאו הטור וכמ\"ש הרמב\"ן טעמו הביאו הב\"י:\n(°) אם היו שני בשני או בן בנו או בן בתו מלביש כל בגדי שבת חוץ מבגד עליון וכשמת חמיו או חמותו וכן אשה שמת לה חמיה או חמותה או אבי אביו או [אבי] אמו וכן האשה בשביל אבי אביה ואבי אמה אינם לובשים רק כתונת לבן והאשה עוד צעיף לבן וכן המנהג שלא לילך לבית המרחץ ולא לחוף הראש. מצאתי:","\u0003גם זה שם בשם הרמב\"ם שם בפ\"ב וכ\"כ ההגהות בשם רש\"י:\u0004 ","\u0003מברייתא דרשב\"ג שבת דף קל\"ה ע\"ב:\u0004 ","\u0003כרב אשי בכורות דף מ\"ט ע\"א:\u0004 ","\u0003כדעת הרמב\"ם בפ\"א מהלכות אבל וטעמו מבואר בדברי ה\"ה בפ\"א מהלכות ייבום:\u0004 ","\u0003שבת דף קל\"ו ע\"א ונדה דף מ\"ד ע\"ב:\u0004 ","\u0003הגהות מיימוני בשם רש\"י:\u0004 ","\u0003הגה\"א בסוף מ\"ק בשם א\"ז:\u0004 ","\u0003מסוגיית הירושלמי פ\"ג דברכות:\u0004 ","\u0003בית יוסף ועיין לעיל סי' רמ\"ב וסימן ש\"מ:\u0004 ","\u0003מימרא דר' יוחנן מ\"ק דף כ\"ה ע\"ב:\u0004 ","\u0003כ\"כ הרמב\"ן ושכ\"כ הראב\"ד:\u0004 "],"t":["\u0003ליטמא. \u0004 כלומר דאע\"ג דאינו מטמא עליו אלא כשמצאו ראשו ורובו היינו לטמאות לכתחלה אבל אם כבר קברו חוץ מאבר א' חוזר לטמאות על אותו אבר ובזה חמור מקרובים שאינו מטמא להם אא\"כ הם שלמים כמ\"ש בס\"ס שע\"ג עכ\"ל הש\"ך:","\u0003צרכו. \u0004 כתב מהרש\"ל לעולם הוא מת מצוה עד שיהיו שם נושאי המטה וקובריה עכ\"ל:","\u0003רובא. \u0004 כתב הש\"ך דר\"ל דאזלינן בתר עוברים ושבים המצויים שם או בתר רוב עיירות ולא אזלינן בתר העיר הקרובה אפילו בקורבה דמוכח דכל דפריש מרובא פריש אם לא שנוכל לומר כל קבוע וכו' כגון שידוע שהיו כאן ט' עובדי כוכבים וחד ישראל ונהרג אחד מהן במקומו לא אזלינן בתר רוב עובדי כוכבים אלא הוי כמחצה ע\"מ. וכתב הלבוש ולחומרא ואין הכהן מטמא מספק כדלעיל סי' שע\"ג ס\"ח עכ\"ל:","\u0003המתמיהים. \u0004 כתב הש\"ך ואע\"ג דמי שרוצה להחמיר ולהתאבל על מי שאינו צריך הרשות בידו וכמ\"ש הרב בסוף הג\"ה היינו דוקא כשמתאבל לגמרי כדין אבילות אבל כשאינו מתאבל אלא לפניו הוי כלועג לאבל עכ\"ל \u0005(ולי נראה הא דאמר אין מוחין בידו היינו מי שעושה זה מצד עצמו שיודע שאינו חייב בדבר אלא שעושים מקצת אבילות לכבוד המת מצד שהיה אוהבו או קרובו או מצד מע\"ט שהיה בו או משארי טעמים שזו היתר גמור כמו שמביא בד\"מ תשובת הרא\"ש כלל כ\"ז סי' ט' וז\"ל וששאלתם אם הרשות בידם ללבוש שחורים על חמיו שנפטר או על אוהבו י\"ב חודש. על חמיו פשיטא דרשות בידו כו' ועל אוהבו נמי אם רוצה להצטער עליו בלבישת שחורים או בשביל כבודו הרשות בידו. וכן מצינו בדוד שקבל הבראה על אבנר עכ\"ל. ומ\"ש שאינו אלא מן המתמיהים היינו מי שרוצה לעשות זה מצד החיוב לנהוג אבלות כמו האבלים ורוצה לדחוק עצמו בקורבה כמו האבלים ממש וזה נקרא כמו לועג לאבל. ובאה\"ע סי' קמ\"ה ס\"ט בהג\"ה אשה שנתגרשה על תנאי ומת הבעל אינה צריכה להתאבל עליו אבל אין איסור אם רצונה להחמיר על עצמה לבכות עליו ולצאת אחר מטתו עכ\"ל ופי' בה\"י דלא חיישינן שמא יוציאו לעז על הגט ויאמרו שאינו גט אעפ\"כ אין איסור בדבר הרי שאומר בלשון שרצונה להחמיר באיזה דבר שמותר)\u0006:","\u0003לעדות. \u0004 עי' בח\"מ סי' ל\"ג איזהו פסולין לעדות ומ\"מ נראה דדוקא פסולי עדות מחמת קורבה דשאר אבל לא מחמת קורבה דקדושין כדלקמן בסעיף שאח\"ז עכ\"ל הש\"ך:","\u0003הראשון. \u0004 וכתב הב\"ח דכ\"ש דאסור לילך לסעודת מצוה כגון ברית מילה עד מוצאי שבת וכתב בתשובת מ\"ב דיש מקומות שנוהגים רק פסולי עדות למת מראין קצת אבילות ויש מקומות שאפילו שלישי ברביעי מראין אבילות והיכא דנהוג נהוג והיכא דלא נהוג נראה דאין להראות אבילות רק הפסולים לעדות. ומ\"מ נראה דאין כל הקרובים שוים לזה אלא קרוב קרוב קודם. ואותם קרובים שמן הדין היו חייבים להתאבל ממש אע\"ג דהאידנא לא נהיגין הכי מ\"מ צריכין להראות אבילות ביום המיתה או ביום השמועה אם הוא תוך ל' יום עד מוצאי שבת הראשון ואין להחליף מבגדי חול לבגדי שבת גם אין לרחוץ בחמין ולא לחוף הראש רק בצונן או במים פושרין ואין לאכול חוץ מביתו לא בסעודת מצוה ולא בסעודת מריעות אבל כתונת לבן אין למנוע לכבוד שבת גם אין לשנות את מקומן בבהכ\"נ ובמו\"ש מותר בכל דבר בין אם הוא מופלג או סמוך ואותן הקרובים שמן הדין אין מתאבלין אין להחמיר בכל אלו ודי להם בבגד העליון של חול ושלא לאכול חוץ לבית ע\"כ ומ\"ש להתיר לקרובים שאין מתאבלים מן הדין ברחיצת חמין וכו' אין נראה כן מדברי הרב דהא אוסר ברחיצה לפסולי עדות דהיינו שני בשני אע\"פ שמן הדין אין מתאבלין. גם מ\"ש להחמיר באותן שמתאבלין מן הדין שלא להחליף כלל מבגדי חול אין נראה כן אלא משנים רק קצת מבגדיהם. ומ\"מ נראה דהולכים בדברים אלו אחר המנהג עכ\"ל הש\"ך:","\u0003עליו. \u0004 הט\"ז והש\"ך כתבו שט\"ס יש כאן בהג\"ה וכצ\"ל והשני חי עדיין אחר ל' יום ור\"ל דאין מתאבלין על הראשון ולא אמרי' מדזה הוא חי והוא בן קיימא מסתמא גם זה שמת הוה בן קיימא דלא כהלבוש שכתב שעל השני קאי דאין מתאבלין עליו אפי' מת אחר ל' דמסתמא נמי נפל היה דהא ודאי ליתא וכן הסכים הב\"ח והגאון מוהר\"ר משה חריף ז\"ל דעל השני שמת אחר ל' ודאי דמתאבלין עליו ודלא כמוהר\"ם מלובלין בתשובה ששגג בזה ג\"כ עכ\"ל הט\"ז:","\u0003אחד. \u0004 וכתב מהרש\"ל ונכון שלא לשתות יין ולא לאכול בשר כל היום עד לאחר קבורה מא\"ז עכ\"ל:","\u0003הראשון. \u0004 כתב הש\"ך אבל על בניהם השני הולכים אע\"פ שהראשון היה נפל וכן נוהגין עכ\"ל:"],"r":["\u0003(ליקוט) איזהו כו' באו כו'. \u0004ירושלמי פ\"ו דנזיר איזהו מ\"מ כל שהוא צווח ואין בני העיר באין באו בני העיר ה\"ז מושך את ידו עד היכן עד כדי נושאי המטה וחילופיהן וחילופי חילופיהן בשא\"צ אבל היו צריכין לו לא בדא בשאין מכירין אותו אבל היו מכירין אותו לא בדא ושאין כבודו לכך אבל אם היה כבודו לכך לא בדא והנשיא כבודו לכן. ומהו שיטמא כהן לכבוד הנשיא כד דמך ר' יודן נשיא אכריז ר' ינאי ואמר אין כהונה היום כד דמך ר' יודן נשיא בר בריה דר' יודן נשיא דחף ר\"ח בר בא לר\"ז בכנישתא דגופנא דצפרין וסאביה. ומ\"ש ומהו כו' ר\"ל באינו מת מצוה וזהו שאמרו בגמרא בפי\"ב דכתובות \u0005(ק\"ג ב') \u0006אותו היום שמת ר' בטלה כהונה \u0005(כ\"ה בתה\"א וברא\"ש הלכות טומאה) \u0006וכן בפ\"ג דברכות \u0005(ופ\"ז דנזיר) \u0006בירושלמי ודלא כתוס' דכתובות שם ד\"ה אותו כו' ומפרש בירושלמי \u0005(שם ושם) \u0006שעשו אותו כמ\"מ ושאלו בירושלמי בתלמיד אצל רבו אם יטמא ולא איפשטא הלכך לא יטמא. תה\"א וע' סי\"א נשיא כו' כ\"כ הראב\"ד והרמב\"ן הניח בצ\"ע (ע\"כ):\n\u0003(ליקוט) איזהו מ\"מ כו' באו כו'. \u0004א\"ר פ\"ד הלכה כ\"ט. אם יש לו כו'. שם הלכה ל' לעולם כו' (ע\"כ):","\u0003אם יש לו כ\"צ כו'. \u0004ירושלמי שם והביאו הרא\"ש שם כל זה:","\u0003מת הנמצא כו'. \u0004בירושלמי נהרג מטבריא לצפורי חזקה הוא ישראל:","\u0003וכשם שהוא כו'. \u0004\u0005(מתני' ביבמות מ\"א חוץ מן האלמנה מפני האיבול ובברייתא שם מ\"ג ב' וכמה איבול שלה שלשים יום) \u0006עס\"ו כל מי שמתאבל כו' וכן היא אינה כו':","\u0003ודוקא אשתו כו' אבל כו'. \u0004כמו בטומאה דלא הוסיפו אלא השנויין כברייתא כאן כמ\"ש הוסיפו כו' ובארוסה אמרינן בהדיא בפ\"ג דיבמות \u0005(כ\"ט ב') \u0006וש\"מ לא אונן כו':","\u0003הנר כו'. \u0004עפי\"א דיבמות צ\"ז ב':","\u0003וכן היא כו' אבל כו'. \u0004מדקאמר חמיה וחמותה:\n\u0003(ליקוט) וכן היא כו'. \u0004תוס' שם ד\"ה אלא כו' ועיין ס' תה\"א (ע\"כ):\n\u0003(ליקוט) וכן היא כו'. \u0004מדקאמר וכן היא שמת כו' אבל י\"ח ממש\"ש לא אמרו לכבוד אשתו \u0005(אלא חמיו וחמותו) \u0006ול\"ק ג\"כ ולא אמרו לכבוד בעלה \u0005(אלא חמיה וחמותה) \u0006וכן תניא בירושלמי להדיא הרי שמת חמיו או חמותו \u0005(או א' מקרובי אשתו. כ\"ה הגירסא שלנו בהירושלמי והיא הברייתא דא\"ר ולפ\"ז י\"ל דשמואל משבש גם הסיפא ורישא נקט וה\"ה לסיפא. ודברי הרמב\"ן לפי גירסתו) \u0006אינו כופה לא לכחול ולא לפקוס אלא נוהג עמה כדרך שהיא נוהגת וכן היא שמת חמיה או חמותה או א' מקרובי בעלה אינה כוחלת ולא פוקסת אלא נוהגת עמו כדרך שהוא נוהג שמואל אמר ל\"ש אלא חמיו וחמותו הא בשאר כל הקרובים לא וכן בא\"ר \u0005(פי\"א) \u0006אלא דשם קתני גם קרובי אשתו ומשובשת היא או י\"ל דקתני משום זה דאינו יכול לכופה:","\u0003ומ\"מ נהגו כו'. \u0004אבל מדינא חייב בכל אבלות שבעה ושלשים וכנ\"ל כדרך שהיא נוהגת כו' וכן בגמ' דקאמר \u0005(סבר למיתב עליה שבעה ושלשים כו') \u0006צודנייתא קבעית כו'. תה\"א (ע\"כ):\n\u0003(ליקוט) ומ\"מ נהנו כו'. \u0004דמדינא בכל דיני אבלות חייב תוס' שם ד\"ה באפה כו' (ע\"כ):","\u0003אין מתאבלין כו'. \u0004כמו שהם אין מתאבלין עליו כמ\"ש בס\"ו:","\u0003אא\"כ כו'. \u0004עמ\"ש בא\"ח סי' של\"א ס\"ג:","\u0003ספק כו'. \u0004עתוס' דיבמות ל\"ו ב' ד\"ה הא. והא דתנן כו' וכ\"כ הרא\"ש בספ\"ב דברכות ובפ\"ג דמ\"ק וכן תניא בהדיא בפ\"ד דמ\"ש ספק שהוא אחיו ספק שאינו אחיו ספק שהוא בנו ספק שאינו בנו מתאבל ואונן ואינו מטמא. ב\"י:","\u0003יש כו'. \u0004עש\"ך:\n\u0003(ליקוט) יש מי כו'. \u0004עפ\"ב דנזיר י\"ג א' תוס' ד\"ה והפילה כו' (ע\"כ):\n(ליקוט) ס\"ט עהג\"א סי' קמ\"א ד\"ה תאומים כו' (ע\"כ):","\u0003שהכל מטמאין לו. \u0004ירושלמי פ\"ז דנזיר וגמ' פי\"ב דכתובות \u0005(וע\"ל ס\"ק א'):\u0006","\u0003אין כו'. \u0004עב\"י \u0005(דלענין טומאה עשו אותו כמת מצוה אבל אבלות לא למדנו בו. וע\"ל סי' ש\"מ ס\"ק ל\"ט):\u0006"]}],["מֵאֵימָתַי חָל הָאֲבֵלוּת, מִשֶּׁנִּקְבַּר וְנִגְמַר \u0010c0\u0011 סְתִימַת הַקֶּבֶר בְּעָפָר, מִיָּד מַתְחִיל הָאֲבֵלוּת וּמְעַטֵּף רֹאשׁוֹ, אֲבָל אֵינוֹ חוֹלֵץ מִנְעָלָיו עַד שֶׁיַּגִּיעַ לְבֵיתוֹ \u0005(רַמְבַּ\"ן)\u0006. וְעַכְשָׁו נוֹהֲגִים לַחֲלֹץ מִנְעָל אַחַר סְתִימַת הַגּוֹלָל מִיָּד, כִּדְאִיתָא בְּסִימָן שע\"ו. \u0005הַגָּה: וְע\"ל סִימָן שפ\"ב. הָיָה סָבוּר שֶׁנִּסְתַּם הַקֶּבֶר וְהִתְחִיל לְהִתְאַבֵּל, וְאַחַר כָּךְ נוֹדַע לוֹ שֶׁטָּעָה, חוֹזֵר וּמַתְחִיל הָאֲבֵלוּת מֵחָדָשׁ (תְּשׁוּבַת הָרֹא\"שׁ כְּלָל כ\"ז)\u0006.\nמִי שֶׁדַּרְכָּם לִשְׁלֹחַ הַמֵּת \u0010y0\u0011 לִמְדִינָה אַחֶרֶת לְקָבְרוֹ, וְאֵינָם יוֹדְעִים מָתַי יִקָּבֵר, מֵעֵת שֶׁיַּחַזְרוּ פְּנֵיהֶם מִלְלַוּוֹת מַתְחִילִין לִמְנוֹת שִׁבְעָה וּשְׁלֹשִׁים וּמַתְחִילִין לְהִתְאַבֵּל \u0005(ל' רַמְבַּ\"ם פֶּרֶק א' מה\"א ד\"ו)\u0006 ; וְהַהוֹלְכִים עִמּוֹ, מוֹנִים מִשֶּׁיִּקָבֵר. \u0010y1\u0011 וְאִם גָדוֹל הַמִּשְׁפָּחָה הוֹלֵךְ עִמּוֹ, \u0010y2\u0011 אַף אֵלוּ שֶׁבְּכָאן אֵינָם מוֹנִים אֶלָא מִשֶּׁיִּקָבֵר; וּגְדוֹל \u0010y3\u0011 מִשְׁפָּחָה הַיְנוּ דְּבֵיתָא סָמוּךְ עֲלֵהּ וּגְרִירֵי כֻּלְהוּ בַּתְרֵיהּ, לֹא שְׁנָא אָח לֹא שְׁנָא בֵּן קָטָן; וְיֵשׁ מִי שֶׁאוֹמֵר וְהוּא שֶׁיְּהֵא בֶּן י\"ג.\nאִם מְפַנִּין אֶת הַמֵּת מִקֶבֶר לְקֶבֶר, אִם קְבָרוּהוּ בְּקֶבֶר רִאשׁוֹן עַל דַּעַת לִהְיוֹת קָבוּר שָׁם עוֹלָמִית, אֶלָא שֶׁאַחַר כָּךְ נִמְלְכוּ לְפַנּוֹתוֹ מִשָּׁם, אֵין מוֹנִין לוֹ אֶלָא מִשֶּׁיִּקָבֵר בְּקֶבֶר רִאשׁוֹן, אֲפִלוּ פִּנּוּהוּ תּוֹךְ ז'. אֲבָל אִם בִּתְחִלָה קְבָרוּהוּ עַל דַּעַת לְפַנּוֹתוֹ כְּשֶׁיִּזְדַּמֵּן לָהֶם, מַתְחִילִין אֲבֵלוּת מִיָּד; וְאִם פִּנּוּהוּ תּוֹךְ שִׁבְעָה, חוֹזְרִין וּמוֹנִין מִשֶּׁיִּקָבֵר שֵׁנִית; וְאִם לֹא פִּנּוּהוּ עַד לְאַחַר שִׁבְעָה, כְּבַר עָבַר אֲבֵלוּתָם וְאֵין מִתְאַבְּלִין עָלָיו פַּעַם אַחֶרֶת; וְאִם מִתְּחִלָה הָיָה דַּעְתָּם לְפַנּוֹתוֹ מִשָּׁם תּוֹךְ שִׁבְעָה, אֵין מַתְחִילִין לִמְנוֹת עַד שֶׁיִּקָבֵר בַּקֶבֶר הַשֵּׁנִי.\nאִם נָתְנוּ הַמֵּת בְּאָרוֹן, וּנְתָנוּהוּ בְּבַיִת אַחֵר לְפִי שֶׁהָיְתָה הָעִיר בְּמָצוֹר, מוֹנִים לוֹ מִיָּד שִׁבְעָה וּשְׁלֹשִׁים, אַף עַל פִּי שֶׁדַּעְתָּם לְקָבְרוֹ בְּבֵית הַקְבָרוֹת אַחַר הַמָּצוֹר, \u0010y4\u0011 וּסְתִימַת אָרוֹן הָוֵי כִּקְבוּרָה וְחָל עֲלֵיהֶם אֲבֵלוּת מִיָּד.\nהֲרוּגֵי מַלְכוּת שֶׁאֵין מַנִּיחִים אוֹתָם לִקָבֵר, מֵאֵימָתַי מַתְחִילִין לְהִתְאַבֵּל עֲלֵיהֶם וְלִמְנוֹת ז' וּשְׁלֹשִׁים, \u0010y5\u0011 מִשֶּׁנִּתְיָאֲשׁוּ לִשְׁאֹל לַמֶּלֶךְ לְקָבְרָן, אַף עַל פִּי שֶׁלֹּא נִתְיָאֲשׁוּ מִלִגְנֹב אוֹתָם.\nמִי שֶׁהוֹדִיעוּהוּ שֶׁצָּלְבוּ עוֹבְדֵי כּוֹכָבִים קְרוֹבוֹ בְּעִיר אַחֶרֶת וְנָהַג אֲבֵלוּת מִיָּד, וְאַחַר כָּךְ נוֹדַע לוֹ שֶׁעֲדַיִן עוֹמֵד בַּצְּלִיבָה, אוֹתוֹ אֲבֵלוּת לֹא עָלָה לוֹ וְחוֹזֵר וּמוֹנֶה מִשֶּׁיִּקָבֵר \u0010c1\u0011 אוֹ מִשֶּׁנִּתְיָאֲשׁוּ מִלְקָבְרוֹ \u0005(דַּעַת ר\"י וְרַמְבַּ\"ן)\u0006. \u0010y6\u0011\nמִי שֶׁטָּבַע \u0010c2\u0011 בְּמַיִם שֶׁיֵּשׁ לָהֶם סוֹף, אוֹ שֶׁיָּצָא קוֹל שֶׁהֲרָגוּהוּ לִסְטִים אוֹ שֶׁגְרַרְתּוֹ חַיָּה, מֵאֵימָתַי מוֹנִים, מִשֶּׁנִּתְיָאֲשׁוּ לְבַקֵשׁ. מְצָאוּהוּ אֵבָרִים אֵבָרִים וּמַכִּירִין אוֹתוֹ בְּסִימָנֵי גוּפוֹ, אֵין מוֹנִין לוֹ עַד שֶׁיִּמָּצֵא רֹאשׁוֹ וְרֻבּוֹ אוֹ יִתְיָאֲשׁוּ מִלְבַקֵשׁ \u0005(בָּרַיְתָא מְבִיאָהּ רַמְבַּ\"ן)\u0006 ; וְאִם נִמְצָא אַחַר שֶׁנִּתְיָאֲשׁוּ מִמֶּנּוּ, \u0010y7\u0011 אֵין הַקְרוֹבִין צְרִיכִים לַחֲזֹר וּלְהִתְאַבֵּל, אֶלָא הַבָּנִים, \u0010y8\u0011 אִם הֵם שָׁם בְּשָׁעָה שֶׁנִּמְצָא מִתְאַבְּלִים אוֹתוֹ הַיּוֹם דְּלֹא גָרַע מִלִקוּט עַצְמוֹת אָבִיו; אֲבָל אִם אֵינָם שָׁם, וְשָׁמְעוּ אַחַר שֶׁעָבַר הַיּוֹם, אֵין צְרִיכִין לְהִתְאַבֵּל. \u0005הַגָּה: אִם שָׁלְחוּ מֵתֵיהֶם לְעִיר אַחֶרֶת, \u0010y9\u0011 שֶׁדִּינָם לְהַתְחִיל הָאֲבֵלוּת מִשֶּׁיַּחֲזִירוּ פְּנֵיהֶם, וְהִתְחִילוּ לִמְנוֹת הָאֲבֵלוּת, וְאַחַר כָּךְ נִתְפַּס הַמֵּת וְלֹא נִתַּן לִקְבוּרָה זְמַן אָרֹךְ, אֵין צְרִיכִין לְהַפְסִיק אֲבֵלוּתָן, וְאֵין צְרִיכִין לַחֲזֹר וּלְהִתְאַבֵּל אַחַר כָּךְ, דְּמֵאַחַר שֶׁדִּינָם לְהַתְחִיל מִיָּד, אֵין צְרִיכִין לְהַפְסִיק (מָרְדְּכַי סוֹף מ\"ק)\u0006.\nמִי שֶׁמֵּת לוֹ קָרוֹב, וְלֹא יָדַע עַד שֶׁבָּא \u0010y10\u0011 לַמָּקוֹם שֶׁמֵּת שָׁם הַמֵּת, אוֹ לִמְקוֹם קְבוּרָה, אִם הָיָה בְּמָקוֹם קָרוֹב שֶׁהוּא מַהֲלַךְ י' פַּרְסָאוֹת שֶׁאֶפְשָׁר שֶׁיָּבֹא בְּיוֹם אֶחָד, אֲפִלוּ בָּא בַּיּוֹם הַז', אִם מָצָא מְנַחֲמִים אֵצֶל גְדוֹל הַבַּיִת, אֲפִלוּ שֶׁנִּנְעֲרוּ לַעֲמֹד, הוֹאִיל וּמָצָא מְנַחֲמִים \u0005דְּהַיְנוּ שֶׁנּוֹהֲגִים עֲדַיִן קְצָת אֲבֵלוּת (טוּר וְרַשְׁבָּ\"א בִּתְשׁוּבָה)\u0006, עוֹלֶה וּמוֹנֶה לוֹ עִמָּהֶם תַּשְׁלוּם שְׁלֹשִׁים יוֹם; וְאִם לֹא מָצָא מְנַחֲמִים, מוֹנֶה לְעַצְמוֹ. וְכֵן אִם הָיָה בְּמָקוֹם רָחוֹק, אֲפִלוּ בָּא בְּיוֹם שֵׁנִי, מוֹנֶה לְעַצְמוֹ שִׁבְעָה וּשְׁלֹשִׁים מִיּוֹם שֶׁבָּא. \u0005הַגָּה: \u0010y11\u0011 וְיֵשׁ אוֹמְרִים דַּאֲפִילוּ אִם בָּא אֶחָד, וְאֵין הַגָּדוֹל בַּבַּיִת רַק שֶׁהָלַךְ לְצֹרֶךְ הַמֵּת, אִם חָזַר תּוֹךְ ג' יָמִים הָוֵי כְּאִלּוּ הוּא בַּבַּיִת \u0010y12\u0011 וְהַבָּא תּוֹךְ ג' מוֹנֶה עִמָּהֶם (וְכֵן הוּא בַּטּוּר)\u0006 ; וְיֵשׁ לְהָקֵל כִּסְבָרָא זוֹ. וְכָל שֶׁדִּינוֹ לִמְנוֹת עִמָּהֶם, אֲפִלּוּ אִם חָזַר אַחַר כָּךְ לְבֵיתוֹ, מוֹנֶה עִמָּהֶם \u0005(הָרַשְׁבָּ\"א סִימָן תע\"ז)\u0006.\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁלֹּא שָׁמַע שֶׁמֵּת, עַד שֶׁבָּא. אֲבָל אִם נוֹדַע לוֹ בַּיּוֹם הַשֵּׁנִי וְהִתְחִיל לְהִתְאַבֵּל, לֹא יְקַצֵּר אֲבֵלוּתוֹ בִּשְׁבִיל שֶׁבָּא אֶצְלָם.\nמִי שֶׁהוּא אָבֵל, וּבְתוֹךְ ז' מֵת לוֹ מֵת אַחֵר, מוֹנֶה ז' לְמֵת אַחֲרוֹן וְעוֹלִים לוֹ לְתַשְׁלוּם שִׁבְעָה יְמֵי אֲבֵלוּת הָרִאשׁוֹן. \u0010y13\u0011\nמִי שֶׁהִתְפַּלֵל עַרְבִית, וַעֲדַיִן הוּא יוֹם, וְשָׁמַע שֶׁמֵּת לוֹ מֵת, יֵשׁ מִי שֶׁאוֹמֵר שֶׁמּוֹנֶה מִיּוֹם הַמָּחֳרָת, \u0010y14\u0011 \u0010y15\u0011 וְאוֹתוֹ יוֹם \u0010c3\u0011 אֵינוֹ עוֹלֶה.",["\u0003למדינה אחרת כו'. \u0004משמע דוקא) כששולחים אותו לעיר אחרת אבל הקוברים בבית הקברות סמוך לעיר החוזרים משערי העיר אינן מתאבלין עד שאמרו להם שנקבר וכמ\"ש הרמב\"ן וכן כתב בית יוסף ונ\"מ ע\"כ לענין קובר מתו בערב הרגל וכדאיתא בפוסקים בשם בעל הלכות:","\u0003ואם גדול המשפחה כו'. \u0004משמע דוקא לחומרא אזלינן בתר גדול המשפחה דאין מונין אלא משיקבר אבל אי גדול המשפחה הוא אצל אלו שנשארו כאן אין מעלה ומוריד אלא אף על פי כן ההולכים עם המת אין מונין אלא משיקבר וכדעת התוספות שמביא בית יוסף וכן כתבו התוספות פרק אלו מגלחין (מועד קטן דף כ\"ב) סוף ע\"א ריש ד\"ה מהדריתו אפייכו כו' דההולכים עם המת מונין משיסתם הגולל בין גדול הבית בבית בין הולך לבית הקברות וכן המנהג עכ\"ל. אבל הטור כ' דהכל הולך אחר גדול הבית דאם נשאר כאן אלו ואלו מונין משיצא המת וכן נראה דעת הרמב\"ן בת\"ה דף מ\"ז ע\"ג והרא\"ש פרק אלו מגלחין במה שהביאו שם הירושלמי ע\"ש ולא עמדתי על סוף דעת בית יוסף שכ' וגירסת הרמב\"ן בירושלמי מגומגמת כו' שהרי גירסתו אות באות כגירסת הרא\"ש מיהו לפי מה שהביא הבית יוסף נוסח הירושלמי מוכח לענין דינא כדעת התוספות הנ\"ל ונ\"ל שגירסא זו עיקר דהא בירושלמי פריך אית תנוי תני אלו שבכאן מונין משיצא המת ואלו ששם מונין משיסתם הגולל ואית תנוי תני אלו וחלו משיסתם הגולל ומשני רבי סימון דהכל הולך אחר גדול המשפחה ואם איתא מאי פסקא הל\"ל נמי אלו ואלו מונין משיצא המת והיינו כשיש גדול הבית בבית אלא ודאי לא אזלינן אחר גדול הבית אלא להחמיר ונ\"ל שכן דעת ראבי\"ה שהביא מרדכי פ' א\"מ שכתב ואותם שהלכו עם המת לקברו משמע מתוך דברי ראבי\"ה שמונה משיסתם הגולל ולדברי רבי אברהם מונה משיצא מפתח ביתו עם גדול הבית ואח\"כ כתב ואם היה גדול הבית בבה\"ק בהא פליגי רבוותא ראבי\"ה פירש דכולן מונין עמו משיסתם הגולל כו' ע\"ש:","\u0003אף אלו שבכאן כו'. \u0004ומדברי ראב\"ן דף ל\"ח ע\"ג מבואר דדוקא אם יכול לבא אל הקבר תוך שלשה ימים אבל אם אינו יכול לבוא תוך שלשה ימים אלו שבבית מונין מיד וגדול הבית שבב\"ה משיסתם הגולל ואין נגררים עמו ומפרש שם כך בש\"ס הא דאתא גו תלתא כו' ואפשר גם המחבר וסייעתו מודים לזה דלא מסתבר כלל אם יקבר המת במקום רחוק שאלו שבכאן ישבו ימים רבים ולא יתחילו אבלות עד שיקבר אף שפי' ראב\"ן בש\"ס דחוק מ\"מ הסברא נכונה:","\u0003דהיינו דביתא סמוך עליה כו'. \u0004לקמן כתבתי בשם הרשב\"א דמי שמתה אשתו הבעל נקרא גדול הבית עיין שם:","\u0003וסתימת הארון הוי כקבורה. \u0004כלומר אע\"ג דקי\"ל לעיל סעיף א' דאין אבילות חל אלא משיסתם הגולל דהיינו משנקבר ונגמר סתימת הקבר בעפר היינו בעלמא אבל במצור מיד שנתנוהו בבית אחר וסתמו הארון הוי כקבורה דהוי כנתיאשו מלקברו דאע\"ג דרוצים לקברו אח\"כ בבה\"ק מ\"מ השתא במצור ה\"ל קבורה מעליותא לדידהו שהרי אם תלכד העיר לא יקברוהו בענין אחר וכן נראה בב\"י ובב\"ח טרח ליישב דברי המחבר בע\"א ע\"ש:","\u0003משנתיאשו כו'. \u0004ואין חילוק בין נתיאשו תוך ל' או אחר ל'. כן הסכמת הפוסקים:","\u0003מי שטבע במים שיש להם סוף כו'. \u0004נראה להכי נקט מים שיש להם סוף לאפוקי שאין להם סוף דאין מתאבלין עליו כלל וכמ\"ש הב\"י בשם העיטור בשם תשובת הרי\"ף מי שטבע במים שאין להם סוף דאין היתר לאשתו לא ינהוג אבילות והא דתניא באבל רבתי טבע בנהר איכא למימר שנפל ומת או שנפל למים שיש להם סוף עכ\"ל ולפ\"ז מ\"ש או שיצא קול כו' או שגררתו חיה כו' היינו נמי בענין שמותרת אשתו להנשא ואע\"ג דמדברי רב האי ורב שרירא שהביא הטור משמע דאפילו לא נתברר שמת אלא קול יוצא בכך מתאבלין עליו נראה כיון דנדחו דבריהם בפוסקים כדאיתא בטור וב\"י נדחו ג\"כ בזה וכן כתב הרב בא\"ע סימן י\"ז ס\"ה דאשתו אסורה להספיד או ללבוש שחורים כל זמן שאין כאן עדות שהוא ראוי להשיאה על ידו עיין שם:","\u0003אין הקרובים צריכים להתאבל. \u0004כ\"כ טור ותמיה לי דהא כיון דלא גרע מליקוט עצמות אם כן גם הקרובים צריכין להתאבל כדלקמן סימן ת\"ג סעיף א' וסעיף ה' ונראה דמשמע ליה הכי מדכתב הרא\"ש בשם מהר\"ם דאם קברוהו במקום בנו וידע בנו את קבורתו לא גרע מיום ליקוט עצמות כו' משמע ליה מהאי לישנא דוקא בנו אבל הדבר ברור משום דמהר\"ם שם קאי אעובדא דר' אליקום שנהרג אחד בדרך וחפשו בנו ואח\"כ נמצא ולא הוזכר שם רק בנו עלה קאי אבל אה\"נ דה\"ה שאר קרובים דהא מייתי ראיה מהא דתניא באבל רבתי כל שקורעים במיתתו קורעים עליו בשעת ליקוט עצמות עיין שם וגם דברי רבינו ירוחם נתיב כ\"ח ח\"א מגומגמים שכתב ואם אחר כך נמצא ההרוג וקברוהו הורה רבי אליקום דאין מתאבלין עליו אפילו בניו. אבל רבי מאיר כתב דבניו מתאבלין כל אותו היום כדין ליקוט עצמות כו' ויש לישב דבריו דנקט בניו והוא הדין שאר קרובים א\"נ אתא לאפוקי שאותן המתאבלין עם מי שמתאבלין כדלעיל סימן שע\"ד סעיף ו' א\"צ להתאבל כאן אבל דברי הט\"ו אי אפשר ליישב כן וצ\"ע:","\u0003אם הם שם כו'. \u0004אורחא דמילתא נקט דמסתמא כל שאינן שם לא שמעו באותו היום אבל ודאי אע\"פ שאינן שם ושמעו באותו היום צריכין להתאבל כל אותו היום כדלקמן סימן ת\"ג סעיף ה' ולפי מ\"ש בסמוך גם בקרובים הדין כן:","\u0003שדינם להתחיל האבילות משיחזרו פניהם. \u0004היינו היכא שלא הלך גדול הבית עמהם לעיר אחרת כדלעיל סעיף ב' וכ\"כ ב\"י ומביאו בד\"מ ולהכי כתב הרב אם שלחו מתיהם לעיר אחרת כו' דאילו בבה\"ק שבאותה העיר אף החוזרים אינם מתאבלים עד שנאמר להם שנקבר וכמ\"ש לעיל ס\"ק א':","\u0003למקום שמת. \u0004דוקא שבא אצלם למקום שמת או למקום קבורה אבל אם לא היה לא מקום מיתה ולא מקום קבורה כל אחד מונה לעצמו כ\"כ הגהת אשר\"י מא\"ז ומביאו ב\"י וד\"מ:","\u0003וי\"א כו'. \u0004באמת הרב נמשך אחר מ\"ש הב\"י שדעת הרמב\"ם (שהעתיק המחבר דבריו כאן) כדעת הרי\"ף שהשמיט מלכתוב דין דהלך גדול לבה\"ק כו' וגדול הבית שהלך לבה\"ק אינו מונה אלא משיסתם הגולל ואפילו חזר אצל בני הבית ביום ג' והם מונים משיחזרו פניהם והבא ממקום קרוב מונה עם גדול הבית דאחריו הוא נגרר ולא אחר בני הבית עכ\"ל ומביאו ד\"מ וכתב עליו ואני אומר דסברת הרא\"ש הוא סברת רבותינו הצרפתים ור\"ח כמבואר מדברי הרמב\"ן שהביא ב\"י בארוכה ולכן נראה דכוותייהו נקטינן דהלכה כדברי המיקל באבל. ותו דבעלי התוספות ור\"ח והרא\"ש רבים נינהו גם הרא\"ש בתרא הוא והסכים לסברתן וכן הלכה עכ\"ל וע\"פ זה כתב הרב כאן וי\"א כו' ויש להקל כסברא זו כו' אבל באמת אין דברי הב\"י נראים עיקר כמ\"ש בספרי אלא נראה עיקר כמ\"ש הרמב\"ן לדעת הרי\"ף ומביאו ב\"י דס\"ל דאפי' בא הגדול אצל בני הבית תוך ז' מונה עמהם ולא מסתימת הגולל בין שבא ממקום קרוב או רחוק וכן אפי' קטן שהלך לבה\"ק וחזר תוך ז' מונה עמהן וכן הבא ממקום אחר לשם ומצא שהלך גדול הבית לבה\"ק כיון שחזר גדול הבית אפי' ביום ז' מונה עמהן אף זה נגרר עמו ונמצאו כולם מונין מנין א' והוא שבא זה ממקום קרוב וא\"כ גם דעת הרמב\"ם כן שהוא הלך ממש בדרך הרי\"ף רבו ע\"ש והסמ\"ג דף רמ\"ו ע\"ג כ' כל' הרמב\"ם ומדברי רבינו ירוחם נתיב כ\"ח ח\"א נראה שפוסק כהרמב\"ן ע\"ש ודעת הרא\"ש נ\"ל דמפרש הא דאתא בגו תלתא על האחר הבא ולא הוזכר לדבריו בש\"ס אם חזר הגדול לביתו או לא אלא לעולם היכא דהלך הגדול לבית הקברות ובא אחר תוך שלשה מונה עמהן לאחר שלשה מונה לעצמו ואם לא הלך לבית הקברות אז אפי' בא ביום הז' מונה עמהן כרבי שמעון והיינו דכ' הרא\"ש הלך גדול הבית לבה\"ק כו' ובא אחד מן האחין תוך ג' מהו כו' אבל הטור ס\"ל דהרא\"ש מפרש הא דאתא בגו תלתא על הגדול לדבריו שצ\"ל הא דכתב הרא\"ש ובא א' מן האחין תוך שלשה היינו משום דאי בא אחר ג' בעוד שהגדול בבית אז פשיטא ול\"מ לן דהא' מונה עמהן כשחזר הגדול תוך ג' ודוחק וגם לדבריו צ\"ל הא דכ' הרא\"ש והא דמפליג רבי יוחנן הכא בין תוך ג' ובין לאחר ג' היינו היכא דהלך גדול הבית לבה\"ק עכ\"ל היינו דבגדול הבית מפליג בין חזר תוך ג' או לא ולישנא לא משמע הכי ועוד דהעיקר חסר מן הספר וה\"ל לפרש דבגדול הבית הוא דמפליג בין חזר תוך ג' או לא ודוק ודעת ר\"ח ורי\"ץ גיאות ורבותינו הצרפתים שהביא הרמב\"ן ופירש דעתם הכל תלוי במה שהגדול מונה עמהם או לא דאם הגדול מונה עמהם אז גם הבא ממקום קרוב מונה עמהם ואם גדול מונה לעצמו אז גם הבא מונה לעצמו וע\"כ הוכרח לפרש דבריהם שהגדול הלך לבה\"ק קודם סתימת הגולל דאם לא כן לא משכחת לה שהגדול מונה לעצמו והלכך לסברתם שחילקו בין תוך ג' לאחר ג' דינא הכי אם חזר הגדול תוך ג' שאז מונה עמה' ולא מסתימת הגולל גם הבא מונה עמהם ואם חזר אחר ג' שאז מונה לעצמו לסברתם אז גם הבא מונה לעצמו ואינו מונה עמהם ולא עם הגדול רק לעצמו אבל כשחזר הגדול ג\"כ מן המת קודם סתימת הגולל שמתחיל מיד למנות עם שאר בני הבית אף שהולך אח\"כ לבה\"ק וחזר אחר שלשה ימים מ\"מ הרי הוא מונה עמהם וכיון שמונה עמהם א\"כ גם הבא מונה עמהן בכל ענין רק שבא ממקום קרוב אבל להרא\"ש אינו תלוי במה שהגדול מונה עמהן או לא אלא הכל תלוי בין אם בא תוך שלשה או לא ואף שאבלות הגדול התחיל בשוה עם שאר בני הבית יש חילוק בין תוך שלשה או לא וע\"כ כתב הרא\"ש שהלך הגדול לבה\"ק להתעסק בצרכי המת לעשות לו מצבה או צורך בנין בתוך הקבר כלומר שמתחילתן התחיל אבילותם בשוה רק שהלך לבה\"ק אחר הקבורה לצורך מצבה וכה\"ג אז יש חילוק בין תוך ג' לאחר ג' וע\"כ כתב הטור וא\"א הרא\"ש ז\"ל כתב כסברא ראשונה שאינו נגרר אחריהם אלא אם כן חזר הגדול תוך שלשה ימים ולא כתב בקיצור וא\"א ז\"ל כתב כסברא הראשונה שאינו נגרר אחריהם אלא כשבא תוך שלשה אבל לא הוזכר בדבריו לחלק בין סתימת הגולל או לא וכן לענין התחלת אבלות נראה שחולק הרא\"ש שהרי אחר שכתב פירוש דבריו על סוגיא דש\"ס דידן הביא הירושלמי דאית תנוי תני אלו שבכאן מונין משיצא המת ואלו ששם מונין משיסתם הגולל ואית תנוי תני אלו ואלו מונין משיסתם הגולל ר' סימון בשם ריב\"ל אומר הכל הולך אחר גדול שאם היה הגדול כאן אלו ואלו מונין משיצא המת ואם היה הגדול שם אלו ואלו מונין משיסתם הגולל אין שם גדול אלו שכאן מונין משיצא המת ואלו ששם מונין משיסתם הגולל ע\"כ וכ' עלה הך הירושלמי לאו מענין סוגיא דשמעתין אלא איירי בענין התחלת אבלות כדאמרינן בשמעתין אמר ליה רבא לבני מחוזאי אתון דלא אזליתו בתר ערסא מכי אהדריתו אפייכו מבבא דאבולא אתחילו מנו והירושלמי השמיענו שיש חילוק כשיש שם גדול עכ\"ל ר\"ל דש\"ס דידן מיירי כשהתחילו האבילות בשוה כגון שכולם הלכו לקברות בשעת קבורה או שגם הגדול נשאר בבית בענין שהתחילו כולם למנות משיסתם הגולל לאו משיצא המת אלא דאם אח\"כ יצא הגדול לבה\"ק לצורך מצבה וכה\"ג יש חילוק בין תוך ג' לאחר שלשה (אבל לר\"ת וסייעתו וכן להרי\"ף לדעת הרמב\"ן צריך לומר שהירושלמי חולק על ש\"ס דידן וכן הוא בת\"ה בהדיא ע\"ש בדף צ\"ב ע\"ג) ולפי זה היכא שהיה הגדול בשעת קבורה דהיינו בסתימת הגולל והאחרים נשארו בבית לעולם מונין אלו ואלו משיסתם הגולל ולא הוזכר חילוק דתוך ג' או לאחר ג' בכאן ובין חזר הגדול לבית או לא לעולם מתחילין הכל משיסתם הגולל וע\"כ דקדק הטור וכ' וא\"א הרא\"ש ז\"ל כ' כסברא הראשונה שאינו נגרר אחריהם אא\"כ חזר הגדול תוך שלשה רצה לומר בזה דוקא הסכים לסברא הראשונה דלא כהפרישה סעיף כ\"ז שערבב דברי הרמב\"ן עם דעת הרא\"ש וטור ולכן הוקשה לו מ\"ש הטור לעיל (דהיינו שפסק כהירושלמי דלעיל) דהכל הולך אחר הגדול לענין התחלת אבילות ולפמ\"ש לק\"מ דהתם מיירי לענין התחלת אבילות וכאן מיירי שהתחילו שניהם בשוה וזה ברור ומ\"מ בלא\"ה יש לתרץ דהא דכ' לעיל דאלו ואלו מונין משיסתם הגולל היינו היכא דגדול הבית דר שם במקום שיקבר המת וכן מחלק במרדכי וז\"ל ור' אברהם פירש דכולהו מונין משיצא מפתח ביתו לפי שהוא טפל להם וכן מצאתי כתוב בשם ר\"י ופירש דירושלמי פליג אש\"ס דידן וכש\"ס דידן עבדינן דמונה עמהם והוא דאתא בגו תלתא יומי אבל אתא בתר תלתא יומי מונה לעצמו משיסתם הגולל לפי דבריו כשהוא דר כאן והלך לבה\"ק כן הוא הדין אבל אם גדול הבית דר שם במקום שיקבר המת אז אלו ואלו מונין משיסתם הגולל כדברי הירושלמי ולא יחלוק על ש\"ס שלנו לפ\"ז עכ\"ל ובע\"כ לדברי המחבר צריך לתרץ כן שהרי העתיק דברי הרמב\"ם דמשמע מיניה מיהא בין לפי מה שפי' הוא דבריו בין לפי מה שפירשתי דבריו דאלו שנשארו כאן מיהא מונין משיצא המת ולא משיסתם הגולל אע\"ג דהגדול היה בשעת סתימת הגולל בבה\"ק ולעיל סעיף ב' כתב ואם גדול המשפחה הולך עמו אף אלו שבכאן אינן מונין אלא משיקבר א\"ו התם מיירי דגדול הבית דר במקום שיקבר והאי דר שם נראה לי היינו דכיון דדר שם ונשאר שם הולכים אחריו אבל אם לא נשאר שם כי דר שם מאי הוי ס\"ס השתא הוא אצלם ונראה דאף הרמב\"ן שכ' דהירושלמי מיירי בכל גווני אפילו היכא דהגדול חזר אצלם ולכך הוצרך לומר דפליג אש\"ס דידן תדע דע\"כ במרדכי גופיה צ\"ל כן שמתחילה כתב ופירוש ירושלמי פליג אש\"ס דידן כו' ואח\"כ כתב ולא יחלוק על ש\"ס שלנו לפ\"ז א\"ו מ\"ש מתחילה דפליג היינו בחזר הגדול לביתו משום דבירושלמי אינו מחלק בכך ומשמע דבכל ענין הולכים אחר הגדול ומ\"ש אח\"כ ולא יחלוק כו' היינו דנשאר שם במקום שדר שם ולענין דינא נראה עיקר כסברת הרי\"ף והרמב\"ם והרמב\"ן והסמ\"ג ורבינו ירוחם דלעיל דרבים וגדולים נינהו ומקילין באבל וגם רבינו ירוחם בתרא הוא וכ' מהרש\"ל דאף הרמב\"ן מודה היכא שלא נשארו מקצתן בבית דמונה לעצמו והביאוהו האחרונים ומשמע מדבריו שם דמודה להרא\"ש וא\"כ אם בא תוך ג' מיהת מונה עמהן אף שלא נשארו מקצתן בבית ודוק. אלא מיהו היכא דהתחיל הגדול למנות עמהן בשוה ואח\"כ הלך לבה\"ק לצורך מצבה וכה\"ג נהי דלהרמב\"ן בכל ענין מונה עמהן היינו היכא דחזר הגדול אצלן תוך ז' אבל היכא דלא חזר כלל מזה לא הוזכר בדבריו ונראה דקי\"ל כהרא\"ש בהא דאם בא אחד ממקום קרוב תוך ג' מונה עמהן דהוי כמי שישנו בבית ואם בא אחר ג' מונה לעצמו כיון דאין הגדול שם ודוקא כשהלך להתעסק בצרכי המת אבל אם הלך בעסק אחר בכל ענין מונה לעצמו כיון שלא חזר הגדול תוך ז' וכל גדול שבענין זה היינו כמו גדול דלעיל סעיף ב'. וכן משמע מדברי הפוסקים בהדיא מיהו היכא דאשתו מתה ובאו אחים ושאר קרובים הבעל נקרא גדול הבית מפני שהוא חייב בקבורתה ולטפל יותר מן האח או האב ואין הולכים אחר המצטער יותר שאין כל הדעות שוות. כ\"כ הרשב\"א בתשוב' סי' תע\"ח:","\u0003והבא תוך ג' מונה עמהן. \u0004לא ידענא למה הצריך שיבא תוך ג' דהא לסברא זו דהטור א\"צ רק שהגדול יחזור תוך ג' ואפי' בא הקרוב ביום ז' מונה עמהן ואפשר דנקט תוך ג' לרבותא דאע\"פ שבא בעוד שלא היה גדול הבית בבית ואצ\"ל אם בא אחר ג' בעוד שחזר הגדול תוך ג' וכעין מה שפירשתי לעיל לישנא דהרא\"ש ובא אחד מן האחים בתוך ג' כו' לדעת הטור ואפשר דאפי' לסברא הראשונה אם בא אחר שלשה בעוד שחזר הגדול לבית מונה עמהם כיון דבא אצלם וגדול הבית שם להכי נקט תוך שלשה דלסברא הראשונה מונה לעצמו א\"א משום דהרב נטה לסברת הרא\"ש דבתראי הוא וכמ\"ש בד\"מ הבאתיו לעיל וספוקי מספקא ליה בדעת הרא\"ש הא דמחלק בין תוך שלשה אי קאי אגדול וכדעת הטור או אקרוב הבא וכדפרש\"י הלכך אזיל הכא והכא לחומרא ודו\"ק:","מזה מי שמת לו קרוב ונודע לו במקומו מונה לעצמו משנודע לו ואפי' בא אח\"כ למקום המת אצל שאר הקרובים שהתחילו כבר להתאבל לא יקצר אבילותו בשביל זה וכן אם בא אצל הקרובים ואינם במקום שמת המת ולא במקום קבורה כל אחד מונה לעצמו משעה שנודע לו אבל אם לא ידע שמת לו מת עד שבא אל הקרובי' שבמקום המת או מקום קבורה אם היה במקום קרוב שהוא מהלך עשר פרסאות אפי' בא ביום הז' אם מצא מנחמין אצל גדול הבית אפילו שננערו לעמוד הואיל ומצא מנחמין דהיינו שנוהגין עדיין קצת אבילות מונה עמהן דכיון שהגדול מונה עמהן גם הוא מונה עמהן אבל אם לא מצא אצלן גדול הבית מונה לעצמו וכן גדול הבית שבא ממקום קרוב מונה לעצמו ואם בשעת קבורה הלכו מקצת הקרובי' לבית הקברות מונין עם אלו שבבית בין גדולים בין קטנים בין שבה\"ק קרוב או רחוק בין באו תוך ג' בין ביום ז' והוא שבאו ומצאו מנחמין אבל אם לא מצאו מנחמין ביום ז' אותן שהלכו לבה\"ק מונין לעצמן משיסתם הגולל וכן הבא ממקום אחר לשם ומצא שהלך הגדול לבה\"ק כיון שחזר הגדול אצלם אפי' ביום ז' ומונה עמהם אף זה נגרר עמהם ונמצא כולם מונין מנין א' והוא שבא זה ממקום קרוב ודוקא שנשארו מקצתן בבית אבל אם לא נשארו מקצתן בבית מונה לעצמו אם לא שבא תוך ג' ואם לא חזר הגדול תוך ז' שאז הגדול מונה לעצמו משיסתם הגולל אז גם הבא ממקום קרוב אינו מונה עם אותן שבבית משיצא המת אלא מונה לעצמו משעה שנודע לו וכל זה שהלך הגדול לבה\"ק במקום שאינו דר שם אבל הלך למקום שדר שם ונשאר שם אפי' אותן שנשארו כאן שהחזירו פניהם מהמת הולכים אחריו ומונים משיסתם הגולל ודוקא שיכול לבא שם תוך ג' אבל אם אינו יכול לבא שם תוך ג' אלו שכאן מונין מיד וגדול שבבה\"ק מונה משיסתם הגולל ואם התחילו אותן שבבית והגדול למנות אבלותן בשוה כולם משיצא המת או כולם משיסתם הגולל אז הבא ממקום קרוב מונה עמהן בכל ענין אפי' בא ביום הז' בעוד שנוהגין קצת אבילות כיון שחזר הגדול קודם שעמדו המנחמין ומונה עמהן אבל אם התחילו אבילות בשוה והלך הגדול אח\"כ לבה\"ק להתעסק בצרכי המת לעשות מצבה או בנין לקבר ולא חזר כלל אחר שבא הקרוב או שחזר אחר שעמדו המנחמין דינא הכי אם בא הקרוב תוך ג' מונה עמהם ואם בא לאחר ג' מונה לעצמו ואם הלך הגדול לעסק אחר שלא בצרכי המת אפילו בא הקרוב תוך ג' מונה לעצמו כיון שלא חזר הגדול לביתו ואם בא הקרוב ממקום רחוק בכל ענין מונה לעצמו וכל שדינו למנות עמהם אפילו חזר אח\"כ לביתו מונה עמהן:","\u0003מי שהתפללו ערבית. \u0004וגם הוא התפלל וכן במרדכי ובתשו' מהרי\"ל סימן פ\"א ובב\"ח העתיק מי שהתפלל ערבית כו' וכן בת\"ה סימן רמ\"א אבל אם הוא עדיין לא התפלל ערבית כתבו מהרש\"ל והב\"ח שם שאותו יום עולה לו אף ע\"פ שהקהל התפללו ערבית אפילו למ\"ד לעיל ס\"ס קצ\"ו לענין נדה דבתר צבורא גרירא שאני אשה שרובן אינן מתפללים ונגררות אחר הקהל לכן אף אם היא רגילה להתפלל לא חילקו בדבר משא\"כ הכא כן כתב מהרש\"ל שם וכן כתב הגאון אמ\"ו זצ\"ל בתשובה דאם לא התפלל הוא אף על פי שהצבור התפללו אותו היום עולה לו דהא בכה\"ג לא עביד תרי קולי דסתרי אהדדי ואפי' למאן דמחמיר לעיל סימן קצ\"ו שאני אבילות דרבנן דקי\"ל הלכה כדברי המיקל באבל א\"נ יש לחלק דלעיל איירי שהקהל התפללו ערבית והיא רצתה להקל על עצמה ולעשות יום וללבוש לבנים לאו כל כמינה לאפוקי נפשה מצבורא אבל כאן מן השמים שלחו לו אבלות בעודו יום ולא התפלל יכול לומר לדידי יום הוא ומהרש\"ל בתשובה חילק בע\"א ולדעתי הוא חילוק קלוש ויותר נ\"ל כמ\"ש עכ\"ל ודבריו נכונים. ולפ\"ז אם אירע אבילות זו לאשה שלא התפללה אותו יום עולה לה) דלא כמהרש\"ל וכן עיקר:","\u0003ואותו יום אינו עולה. \u0004כתב העט\"ז ולפי מ\"ש לעיל ר\"ס קצ\"ו גבי לובשת לבנים דהמיקל לא הפסיד נ\"ל דכ\"ש באבל דהמיקל למנות יום ששמע ליום א' אע\"פ שהתפללו הקהל ערבית לא הפסיד נ\"ל עכ\"ל ואין נ\"ל דהא דין דהכא לקוח ממרדכי בשם מהר\"ם ומביאו בת\"ה סי' רמ\"א ויליף מינה לענין נדה וכ' שם שאחד מן הגדולים כתב לו בתשובה שאין לדמות נדה לאבלות משום דאותה שעה דמתפלל ערבית אינו אלא סניף ותוספת ליום שלאחריו ואינו עיצומו של יום ולכך לענין אבלות לא חשיב כיום דהא סניף הוא ותוספות ליום שלאחריו אבל לענין ספירה לא קפדינן אלא אעיצומו של ז' ימים ולא על התוספת עכ\"ד וא\"כ אנן קי\"ל כגדול זה וכן משמע מדברי הב\"ח ושאר אחרונים דמקילין גבי נדה ולא הכא ואפשר גם העט\"ז לא קאמר אלא כשהתפללו הקהל ערבית ולא הוא דאז אותו יום עולה לו וכמ\"ש בסמוך:"],["\u0003סתימת הקבר בעפר. \u0004דמ\"ש בגמרא עד שיסתום הגולל פרש\"י כסוי הארון ופירש הרמב\"ן דהיינו כשנותנין אותו בארון וסותמין הכיסוי בנסרים לדעת ליתן אותו ארון בכוך או קבר אח\"כ אז מונה משעת סתימת הארון אבל אם מוציאין במטה או בארון פתוח לבה\"ק מונים משיסתום הקבר לגמרי ור\"ת פי' גולל הוא האבן שנותנין על הקבר למעלה לסתמו ולא לעשות סימן לקבר וכל זמן שהארון מגולה דהיינו שלא ניתן עליו עפר עדיין אע\"פ שנשתקע במסמרים אין אבילות עדיין:","\u0003או משנתיאשו לקברו. \u0004מעשה ביהודי אחד שהרגוהו והשליכוהו בנהר רינו\"ס ובעשרה בטבת היה המעשה ולפני אדר נתיאש בנו מלבקשו עוד והורה ר' יעקב למנות מעתה שבעה ושלשים ולאחר שעברו ימי האבילות נמצא אביו בתוך הנהר והובא לבה\"ק והורה לו הזקן רק לקרוע והסכים עמו הרמב\"ן:","\u0003במים שיש להם סוף. \u0004דאלו במים שאין להם סוף אין היתר לאשתו דבחזקת חי קיים ע\"כ לא ינהג אבילות כ\"כ בית יוסף בשם בעל העיטור:","\u0003אינו עולה. \u0004דהוו תרי קולי דסתרי אהדדי ועיין מה שכתבתי בזה סי' ת\"ב סעיף י\"א:"],"\u0010g0\u0011 \u0010r0\u0011 מֵאֵימָתַי חָל הָאֲבֵלוּת, מִשֶּׁנִּקְבַּר \u0010r1\u0011 וְנִגְמַר \u0010c0\u0011 סְתִימַת הַקֶּבֶר \u0010g1\u0011 בְּעָפָר, מִיָּד מַתְחִיל הָאֲבֵלוּת וּמְעַטֵּף רֹאשׁוֹ, \u0010g2\u0011 \u0010r2\u0011 אֲבָל אֵינוֹ חוֹלֵץ מִנְעָלָיו עַד שֶׁיַּגִּיעַ לְבֵיתוֹ \u0005(רַמְבַּ\"ן)\u0006. וְעַכְשָׁו נוֹהֲגִים לַחֲלֹץ מִנְעָל אַחַר סְתִימַת הַגּוֹלָל מִיָּד, כִּדְאִיתָא בְּסִימָן שע\"ו. \u0005הַגָּה: וְע\"ל סִימָן \u0010r3\u0011 שפ\"ב. הָיָה סָבוּר שֶׁנִּסְתַּם הַקֶּבֶר וְהִתְחִיל לְהִתְאַבֵּל, וְאַחַר כָּךְ נוֹדַע לוֹ שֶׁטָּעָה, חוֹזֵר וּמַתְחִיל הָאֲבֵלוּת מֵחָדָשׁ (תְּשׁוּבַת הָרֹא\"שׁ כְּלָל כ\"ז)\u0006. \u0010g3\u0011\nמִי שֶׁדַּרְכָּם לִשְׁלֹחַ הַמֵּת \u0010y0\u0011 לִמְדִינָה \u0010t0\u0011 אַחֶרֶת לְקָבְרוֹ, וְאֵינָם יוֹדְעִים מָתַי יִקָּבֵר, מֵעֵת שֶׁיַּחַזְרוּ פְּנֵיהֶם מִלְלַוּוֹת מַתְחִילִין לִמְנוֹת שִׁבְעָה וּשְׁלֹשִׁים וּמַתְחִילִין לְהִתְאַבֵּל \u0005(ל' רַמְבַּ\"ם פֶּרֶק א' מה\"א ד\"ו)\u0006 \u0010r4\u0011 ; וְהַהוֹלְכִים עִמּוֹ, מוֹנִים מִשֶּׁיִּקָבֵר. \u0010y1\u0011 וְאִם גָדוֹל הַמִּשְׁפָּחָה הוֹלֵךְ עִמּוֹ, \u0010y2\u0011 אַף אֵלוּ \u0010t1\u0011 שֶׁבְּכָאן אֵינָם מוֹנִים אֶלָא מִשֶּׁיִּקָבֵר; \u0010g4\u0011 \u0010r5\u0011 וּגְדוֹל \u0010y3\u0011 \u0010t2\u0011 מִשְׁפָּחָה הַיְנוּ דְּבֵיתָא סָמוּךְ עֲלֵהּ וּגְרִירֵי כֻּלְהוּ בַּתְרֵיהּ, לֹא שְׁנָא אָח לֹא שְׁנָא בֵּן קָטָן; וְיֵשׁ מִי שֶׁאוֹמֵר \u0010g5\u0011 וְהוּא שֶׁיְּהֵא בֶּן י\"ג. \u0010g6\u0011 \u0010r6\u0011\nאִם מְפַנִּין אֶת הַמֵּת מִקֶבֶר לְקֶבֶר, אִם קְבָרוּהוּ בְּקֶבֶר רִאשׁוֹן עַל דַּעַת לִהְיוֹת קָבוּר שָׁם עוֹלָמִית, אֶלָא שֶׁאַחַר כָּךְ נִמְלְכוּ לְפַנּוֹתוֹ מִשָּׁם, אֵין מוֹנִין לוֹ אֶלָא מִשֶּׁיִּקָבֵר בְּקֶבֶר רִאשׁוֹן, אֲפִלוּ פִּנּוּהוּ תּוֹךְ ז'. אֲבָל אִם בִּתְחִלָה קְבָרוּהוּ עַל דַּעַת לְפַנּוֹתוֹ כְּשֶׁיִּזְדַּמֵּן לָהֶם, מַתְחִילִין אֲבֵלוּת מִיָּד; וְאִם פִּנּוּהוּ תּוֹךְ שִׁבְעָה, חוֹזְרִין וּמוֹנִין מִשֶּׁיִּקָבֵר שֵׁנִית; וְאִם לֹא פִּנּוּהוּ עַד לְאַחַר שִׁבְעָה, כְּבַר עָבַר אֲבֵלוּתָם וְאֵין מִתְאַבְּלִין עָלָיו פַּעַם אַחֶרֶת; \u0010g7\u0011 \u0010r7\u0011 וְאִם מִתְּחִלָה הָיָה דַּעְתָּם לְפַנּוֹתוֹ מִשָּׁם תּוֹךְ שִׁבְעָה, אֵין מַתְחִילִין לִמְנוֹת עַד שֶׁיִּקָבֵר בַּקֶבֶר הַשֵּׁנִי. \u0010g8\u0011 \u0010r8\u0011\nאִם נָתְנוּ הַמֵּת בְּאָרוֹן, וּנְתָנוּהוּ בְּבַיִת אַחֵר לְפִי שֶׁהָיְתָה הָעִיר בְּמָצוֹר, מוֹנִים לוֹ מִיָּד שִׁבְעָה וּשְׁלֹשִׁים, אַף עַל פִּי שֶׁדַּעְתָּם לְקָבְרוֹ בְּבֵית הַקְבָרוֹת אַחַר הַמָּצוֹר, \u0010y4\u0011 וּסְתִימַת אָרוֹן הָוֵי \u0010t3\u0011 כִּקְבוּרָה וְחָל עֲלֵיהֶם אֲבֵלוּת מִיָּד. \u0010g9\u0011\nהֲרוּגֵי מַלְכוּת שֶׁאֵין מַנִּיחִים אוֹתָם לִקָבֵר, מֵאֵימָתַי מַתְחִילִין לְהִתְאַבֵּל עֲלֵיהֶם וְלִמְנוֹת ז' וּשְׁלֹשִׁים, \u0010y5\u0011 \u0010t4\u0011 מִשֶּׁנִּתְיָאֲשׁוּ לִשְׁאֹל לַמֶּלֶךְ לְקָבְרָן, \u0010r9\u0011 אַף עַל פִּי שֶׁלֹּא נִתְיָאֲשׁוּ מִלִגְנֹב אוֹתָם. \u0010g10\u0011 \u0010r10\u0011\nמִי שֶׁהוֹדִיעוּהוּ שֶׁצָּלְבוּ עוֹבְדֵי כּוֹכָבִים קְרוֹבוֹ בְּעִיר אַחֶרֶת וְנָהַג אֲבֵלוּת מִיָּד, וְאַחַר כָּךְ נוֹדַע לוֹ שֶׁעֲדַיִן עוֹמֵד בַּצְּלִיבָה, אוֹתוֹ אֲבֵלוּת לֹא עָלָה לוֹ וְחוֹזֵר וּמוֹנֶה מִשֶּׁיִּקָבֵר \u0010c1\u0011 אוֹ מִשֶּׁנִּתְיָאֲשׁוּ \u0010t5\u0011 מִלְקָבְרוֹ \u0005(דַּעַת ר\"י וְרַמְבַּ\"ן)\u0006. \u0010y6\u0011 \u0010g11\u0011 \u0010r11\u0011\nמִי שֶׁטָּבַע \u0010c2\u0011 בְּמַיִם \u0010g12\u0011 \u0010r12\u0011 שֶׁיֵּשׁ לָהֶם \u0010t6\u0011 סוֹף, אוֹ שֶׁיָּצָא קוֹל שֶׁהֲרָגוּהוּ לִסְטִים אוֹ שֶׁגְרַרְתּוֹ חַיָּה, מֵאֵימָתַי מוֹנִים, מִשֶּׁנִּתְיָאֲשׁוּ לְבַקֵשׁ. \u0010r13\u0011 מְצָאוּהוּ אֵבָרִים אֵבָרִים וּמַכִּירִין אוֹתוֹ בְּסִימָנֵי גוּפוֹ, אֵין מוֹנִין לוֹ עַד שֶׁיִּמָּצֵא רֹאשׁוֹ וְרֻבּוֹ אוֹ יִתְיָאֲשׁוּ מִלְבַקֵשׁ \u0005(בָּרַיְתָא מְבִיאָהּ רַמְבַּ\"ן)\u0006 \u0010r14\u0011 ; וְאִם \u0010g13\u0011 נִמְצָא אַחַר שֶׁנִּתְיָאֲשׁוּ מִמֶּנּוּ, \u0010y7\u0011 אֵין הַקְרוֹבִין צְרִיכִים לַחֲזֹר וּלְהִתְאַבֵּל, אֶלָא הַבָּנִים, \u0010y8\u0011 אִם הֵם \u0010t7\u0011 שָׁם בְּשָׁעָה שֶׁנִּמְצָא מִתְאַבְּלִים אוֹתוֹ הַיּוֹם דְּלֹא גָרַע מִלִקוּט עַצְמוֹת אָבִיו; אֲבָל אִם אֵינָם שָׁם, וְשָׁמְעוּ אַחַר שֶׁעָבַר הַיּוֹם, אֵין צְרִיכִין לְהִתְאַבֵּל. \u0005הַגָּה: אִם שָׁלְחוּ מֵתֵיהֶם לְעִיר אַחֶרֶת, \u0010y9\u0011 \u0010t8\u0011 שֶׁדִּינָם לְהַתְחִיל הָאֲבֵלוּת מִשֶּׁיַּחֲזִירוּ פְּנֵיהֶם, וְהִתְחִילוּ לִמְנוֹת הָאֲבֵלוּת, וְאַחַר כָּךְ נִתְפַּס הַמֵּת וְלֹא נִתַּן לִקְבוּרָה זְמַן אָרֹךְ, אֵין צְרִיכִין לְהַפְסִיק אֲבֵלוּתָן, וְאֵין צְרִיכִין לַחֲזֹר וּלְהִתְאַבֵּל אַחַר כָּךְ, דְּמֵאַחַר שֶׁדִּינָם לְהַתְחִיל מִיָּד, אֵין צְרִיכִין לְהַפְסִיק (מָרְדְּכַי סוֹף מ\"ק)\u0006. \u0010g14\u0011\nמִי שֶׁמֵּת לוֹ קָרוֹב, \u0010r15\u0011 וְלֹא יָדַע עַד שֶׁבָּא \u0010y10\u0011 \u0010g15\u0011 \u0010r16\u0011 לַמָּקוֹם שֶׁמֵּת שָׁם הַמֵּת, אוֹ לִמְקוֹם קְבוּרָה, אִם הָיָה בְּמָקוֹם קָרוֹב \u0010g16\u0011 \u0010r17\u0011 שֶׁהוּא מַהֲלַךְ י' פַּרְסָאוֹת שֶׁאֶפְשָׁר שֶׁיָּבֹא בְּיוֹם אֶחָד, \u0010g17\u0011 אֲפִלוּ בָּא בַּיּוֹם הַז', \u0010g18\u0011 אִם מָצָא מְנַחֲמִים אֵצֶל גְדוֹל הַבַּיִת, \u0010r18\u0011 אֲפִלוּ שֶׁנִּנְעֲרוּ לַעֲמֹד, הוֹאִיל וּמָצָא מְנַחֲמִים \u0005דְּהַיְנוּ שֶׁנּוֹהֲגִים עֲדַיִן קְצָת אֲבֵלוּת (טוּר וְרַשְׁבָּ\"א בִּתְשׁוּבָה)\u0006, עוֹלֶה וּמוֹנֶה לוֹ עִמָּהֶם תַּשְׁלוּם שְׁלֹשִׁים יוֹם; וְאִם לֹא מָצָא מְנַחֲמִים, מוֹנֶה לְעַצְמוֹ. וְכֵן אִם הָיָה בְּמָקוֹם רָחוֹק, אֲפִלוּ בָּא בְּיוֹם שֵׁנִי, מוֹנֶה לְעַצְמוֹ שִׁבְעָה וּשְׁלֹשִׁים מִיּוֹם שֶׁבָּא. \u0005הַגָּה: \u0010y11\u0011 \u0010t9\u0011 \u0010r19\u0011 וְיֵשׁ אוֹמְרִים דַּאֲפִילוּ אִם בָּא אֶחָד, וְאֵין הַגָּדוֹל בַּבַּיִת רַק שֶׁהָלַךְ לְצֹרֶךְ הַמֵּת, אִם חָזַר תּוֹךְ ג' יָמִים הָוֵי כְּאִלּוּ הוּא בַּבַּיִת \u0010y12\u0011 וְהַבָּא תּוֹךְ ג' מוֹנֶה עִמָּהֶם (וְכֵן הוּא בַּטּוּר)\u0006 ; וְיֵשׁ לְהָקֵל כִּסְבָרָא זוֹ. וְכָל שֶׁדִּינוֹ לִמְנוֹת עִמָּהֶם, אֲפִלּוּ אִם חָזַר אַחַר כָּךְ לְבֵיתוֹ, מוֹנֶה עִמָּהֶם \u0005(הָרַשְׁבָּ\"א סִימָן תע\"ז)\u0006. \u0010g19\u0011\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁלֹּא שָׁמַע שֶׁמֵּת, עַד שֶׁבָּא. אֲבָל אִם נוֹדַע לוֹ בַּיּוֹם הַשֵּׁנִי וְהִתְחִיל לְהִתְאַבֵּל, לֹא יְקַצֵּר אֲבֵלוּתוֹ בִּשְׁבִיל שֶׁבָּא אֶצְלָם. \u0010g20\u0011 \u0010r20\u0011\nמִי שֶׁהוּא אָבֵל, וּבְתוֹךְ ז' מֵת לוֹ מֵת אַחֵר, מוֹנֶה ז' לְמֵת אַחֲרוֹן וְעוֹלִים לוֹ לְתַשְׁלוּם שִׁבְעָה יְמֵי אֲבֵלוּת הָרִאשׁוֹן. \u0010y13\u0011\nמִי \u0010t10\u0011 שֶׁהִתְפַּלֵל עַרְבִית, וַעֲדַיִן הוּא יוֹם, וְשָׁמַע שֶׁמֵּת לוֹ מֵת, יֵשׁ \u0010g21\u0011 מִי שֶׁאוֹמֵר שֶׁמּוֹנֶה מִיּוֹם הַמָּחֳרָת, \u0010y14\u0011 \u0010y15\u0011 וְאוֹתוֹ יוֹם \u0010c3\u0011 אֵינוֹ עוֹלֶה.",{"g":["\u0003ברייתא מ\"ק דף כ\"ו ע\"א:\u0004 ","\u0003טור בשם הגאונים ואביו הרא\"ש ז\"ל וכ\"נ מדברי הרמב\"ם בפ\"א:\u0004 ","\u0003הרא\"ש שם:\u0004 ","\u0003מימרא דרבא מ\"ק דף כ\"ב ע\"א:\u0004 ","\u0003טור בשם הרי\"ץ גיאת מדברי אביו הרא\"ש וכ\"כ ש\"פ:\u0004 ","\u0003הגהמ\"יי בפ\"ז בשם סמ\"ק:\u0004 ","\u0003הרמב\"ן בסת\"ה והרא\"ש בפ\"ג דמ\"ק מהירושל':\u0004 ","\u0003הרא\"ש שם במעשה דשפירא כשנפטר רבי קלונימוס הזקן:\u0004 ","שם במעשה הנזכר (ומרדכי פרק אלו מגלחין ורבינו ירוחם):","לשון הרמב\"ם בפ\"א מהלכות אבל מברייתא דאבל רבתי וכ' המרדכי דמ\"ק דמסיים בירושלמי ובלבד שלא יהא גנב ולכן אין מתאבלין על הגנב ע\"כ וראיתי בב\"ח שכ' בזה ולא ראיתי נוהגין כן וצ\"ע:\n(°) פי' שם משום דמלתא דלא שכיחא הוא שכל הגונב כשופך דמים ועובד עבודת כוכבים כו' ומחלל שבתות ופי' הרמב\"ן בסת\"ה לפי שבורחין ובאין לידי סכנת נפשות ופעמים מגיעים לידי חילול שבתות ועובדים עבודת כוכבים:","\u0003תשו' הרא\"ש:\u0004 ","\u0003ברייתא באבל רבתי:\u0004 ","כפירוש העיטור בשם תשו' הרי\"ף דאלו במים שאין להם סוף כיון שאין היתר לאשתו ובחזקת חי קיימא מסתברא דלא נהיגא אבילותא:","\u0003טור בשם הרמב\"ן בסת\"ה וכן כ' אביו הרא\"ש בשם הר\"מ:\u0004 ","\u0003ברייתא מ\"ק דף כ\"א ע\"ב:\u0004 ","\u0003הג\"א שם בשם א\"ז:\u0004 ","\u0003הרא\"ש שם בשם הגאונים וכ\"כ הרמב\"ם בפ\"ז מהל' אבל ד\"ז וכ\"כ התוספות בשם בה\"ג:\u0004 ","\u0003כרבי שמעון שם בברייתא דאיפסקא הלכתא כוותיה שם בגמ' דף כ\"ב ע\"א:\u0004 ","\u0003כדמפרש (ר' יוחנן) שם ר' חייא בר גמדא וכו'\u0004 (דף כ\"ב ע\"ב):","\u0003טור בשם אביו הרא\"ש:\u0004 ","מרדכי בסוף מ\"ק מעשה דר' שלמה מטירויש וכ' שילווהו יחף לב\"ה (והגמי\"י פ\"ט):","שם במרדכי (בשם מהר\"מ) ומפרש הטעם משום דהוי כתרי קולי דסתרן אהדדי וכפול לקמן בסימן ת\"ב סעיף י\"א:"],"t":["\u0003אחרת. \u0004 אבל הקוברים בבה\"ק סמוך לעיר החוזרים משערי העיר אין מתאבלין עד שיאמרו להם שנקבר ונ\"מ לענין קובר מתו בערב הרגל עכ\"ל הש\"ך \u0005(ועוד יש נ\"מ דכתב לעיל סי' שע\"ד דנשתרבב המנהג שאין אב ואם הולכין אחר בניהם הראשון א\"כ אם אירע כן בערב הרגל אין למנות מעת שיחזרו פניהם מללוות אלא ג\"כ עד שאומרים לו שנקבר. ונ\"מ שאם אירע כן שאומרים לו שנקבר הוא קודם בין השמשות זמן מה שא\"צ עוד למנות ז' אבל אם אומרים שנקבר והוא בין השמשות צריך למנות ז' אחר הרגל (בה\"י)\u0006 והנה בשיעור ריחוק מקום אחר לא הוזכר פה אלא כשהוא רחוק כ\"כ שאינם יודעים מתי יקבור וזהו סברת הרמב\"ם בשיעור זה. והרמב\"ן כתב סתם במוליכין אותו מעיר לעיר דכיון שמסרוהו לאיזו שמוליכין אותו והחזירו פניהם כבר נתיאשו ממנו ויאוש כסתימת גולל וכו' ואח\"כ כתב וכן נראין דברי הרמב\"ם ז\"ל שכתב מי שדרכן לשלוח המת למדינה אחרת לקברו ואינם יודעים מתי יקבר מעת שיחזרו פניהם מתחילין למנות כו' ואח\"כ כתב דעת בה\"ג שלא חילק אלא כדנפיק ממתא ואינשי ליה מקרובים חדא שעתא מקמי דליפול רגל חלה אבילות עליהם ובטלה ממנו גזרת ז' והכריע הב\"י כהרמב\"ם וזהו שכתב כאן כשהוא רחוק כ\"כ שאינם יודעים מתי יקבר. והרדב\"ז שאלה ס\"ג כתב ג\"כ כרמב\"ם והרמב\"ן אלא שכתב לבסוף והיכא דנקבר בה\"ש של ע\"ש חל האבילות אפילו על אותן שלא הלכו עם המטה ועולה להם יום א' וכן אם היה ערב הרגל מבטל מהם הרגל גזרת ז' אע\"פ שלא חזרו הקרובים אלא אחר שנכנס שבת או הרגל אע\"פ שבשאר הימים לא חל עליהם אבילות עד שיחזרו הקרובים כדעת הרמב\"ן. ע\"ש עוד. ועי' תשובת דרכי נועם שאלה י\"ט וך'. וראנ\"ח ח\"ב שאלה נ\"ח):","\u0003שבכאן. \u0004 כתב הש\"ך ומדברי הרמב\"ן מבואר דדוקא אם יכול לבא אל הקבר תוך ג' ימים אבל אם אינו יכול לבא תוך ג' ימים אלו שבבית מונין מיד וגדול הבית שבבה\"ק משיסתם הגולל ואין נגררים עמו ע\"כ ודוקא לחומרא אזלינן בתר גדול המשפחה דאין מונין אלא משיקבר אבל אם גדול המשפחה הוא אצל אלו שנשארו בבית אינו מעלה ומוריד אלא אעפ\"כ ההולכין עם המת אין מונין אלא משיקבר אבל דעת הטור דהכל הולך אחר גדול הבית דאם נשאר כאן אלו ואלו מונין משיצא המת וכן נראה דעת הרמב\"ן וכו' ע\"ש:","\u0003דביתא. \u0004 וכתב הרשב\"א דמי שמתה אשתו הבעל נקרא גדול המשפחה:","\u0003כקבורה. \u0004 דהוי כנתיאשו מלקברו דאע\"ג דרוצים לקברו אח\"כ בבה\"ק מ\"מ השתא במצור ה\"ל קבורה מעלייתא לדידהו שהרי אם תלכד העיר לא יקברוהו בענין אחר עכ\"ל הש\"ך:","\u0003משנתיאשו. \u0004 ואין חילוק בין נתיאשו תוך ל' או אחר ל'. ש\"ך:","\u0003מלקברו. \u0004 כתב הט\"ז מעשה ביהודי אחד שהרגוהו בעשרה בטבת והשליכוהו בנהר רינו\"ס ולפני אדר נתיאש בנו מלבקשו עוד והורה ר' יעקב למנות מעתה שבעה ושלשים ולאחר שעברו ימי האבילות נמצא אביו בתוך הנהר והובא לבה\"ק והורה לו הזקן רק לקרוע והסכים עמו הרמב\"ן עכ\"ל:","\u0003סוף. \u0004 לאפוקי אם אין להם סוף דאין מתאבלין כלל מאחר שאין היתר לאשתו לא ינהגו אבילות וכן מ\"ש או שיצא קול וכו' או שגררתו חיה דהיינו נמי בענין שמותרת אשתו להנשא וכ\"כ הרב בא\"ע סי' י\"ז ס\"ה דאשתו אסורה להספיד או ללבוש שחורים כל זמן שאין כאן עדות שהוא ראוי להשיאה על ידו ע\"ש עכ\"ל הש\"ך:","\u0003שם. \u0004 כ' הש\"ך וה\"ה אם אינן שם ושמע באותו היום צריכין להתאבל כל אותו היום וגם בקרובים הדין כן ודלא כהמחבר וצ\"ע עכ\"ל:","\u0003שדינם. \u0004 היינו היכא שלא הלך גדול הבית עמהם לעיר אחרת כדלעיל ס\"ב. ש\"ך:","\u0003וי\"א. \u0004 הנה הש\"ך האריך מאד בדינים אלו וכלל העולה מדבריו ומסקנתו לענין דינא הוא כך. מי שמת לו קרוב ונודע לו במקומו מונה לעצמו משנודע לו ואפילו בא אח\"כ למקום המת אצל שאר הקרובים שהתחילו כבר להתאבל לא יקצר אבלתו בשביל זה. וכן אם בא אצל הקרובים ואינם במקום שמת המת ולא במקום קבורה כל א' מונה לעצמו משעה שנודע לו. אבל אם לא ידע שמת לו מת עד שבא אצל הקרובים שבמקום המת או מקום קבורה אם היה במקום קרוב שהוא מהלך עשר פרסאות אפי' בא ביום הז' אם מצא מנחמין אצל גדול הבית אפי' שננערו לעמוד \u0005(הואיל ומצא מנחמין עדיין שנוהגים קצת אבילות)\u0006 מונה עמהן דכיון שהגדול מונה עמהם גם הוא מונה עמהם אבל אם לא מצא אצלם גדול הבית מונה לעצמו וכן גדול הבית שבא ממקום קרוב מונה לעצמו ואם בשעת קבור' הלכו מקצת הקרובים לבה\"ק מונין עם אלו שבבית בין גדולים בין קטנים בין שבה\"ק קרוב או רחוק בין באו תוך ג' בין ביום ז'. והוא שבאו ומצאו מנחמין אצלם אבל אם לא מצאו מנחמין ביום ז' אותן שהלכו לבה\"ק מונין לעצמן משיסתם הגולל. וכן הבא ממקום אחר לשם ומצא שהלך הגדול לבה\"ק כיון שחזר הגדול אצלם אפי' ביום ז' ומונה עמהם אף זה נגרר עמהם ונמצא כולם מונין מנין א'. והוא שבא זה ממקום קרוב. ודוקא שנשארו מקצתן בבית אבל אם לא נשארו מקצתן בבית מונה לעצמו אם לא שבא תוך ג'. ואם לא חזר הגדול תוך ז' שאז הגדול מונה לעצמו משיסתם הגולל אז הבא ממקום קרוב ג\"כ \u0005(אינו מונה עם אותן שבבית משיצא המת)\u0006 אלא מונה לעצמו משעה שנודע לו. וכל זה שהלך הגדול לבה\"ק במקום שאינו דר שם אבל הלך למקום שדר שם ונשאר שם אפי' אותן שנשארו כאן שהחזירו פניהם מהמת הולכים אחריו ומונים משיסתם הגולל. ודוקא שיכול לבא שם תוך שלשה אבל אם אינו יכול לבא שם תוך שלשה אלו שבכאן מונים מיד וגדול שבבה\"ק מונה משיסתם הגולל ואם התחילו אותן שבבית והגדול למנות אבילותן בשוה הן משיצא המת או משיסתם הגולל אז הבא ממקום קרוב מונה עמהן בכל ענין אפילו בא ביום השביעי בעוד שנוהגין קצת אבילות כיון שחזר הגדול קודם שעמדו המנחמין ומונה עמהן אבל אם התחילו אבילותן בשוה והלך הגדול אח\"כ לבית הקברות להתעסק בצרכי המת לעשות מצבה או בנין לקבר ולא חזר כלל אחר שבא הקרוב או שחזר אחר שעמדו המנחמין אז דינא הכי אם בא הקרוב תוך שלשה מונה עמהם ואם בא לאחר ג' מונה לעצמו ואם הלך הגדול לעסק אחר שלא לצורך המת אפילו בא הקרוב תוך ג' מונה לעצמו כיון שלא חזר הגדול לביתו ואם בא הקרוב ממקום רחוק בכל ענין מונה לעצמו וכל שדינו למנות עמהם אפילו חזר אחר כך לביתו מונה עמהם עכ\"ל:","\u0003שהתפלל. \u0004 אבל אם עדיין הוא לא התפלל ערבית כתבו מהרש\"ל וב\"ח שאותו יום עולה לו אף על פי שהקהל התפללו ערבית. ואפילו למ\"ד לעיל סימן קצ\"ו לענין נדה דבתר צבורא גרירה שאני גבי אשה שרובן אינן מתפללות ונגררות אחר הקהל לכן אף אם היא רגילה להתפלל לא חלקו בדבר משא\"כ הכא כ\"כ מהרש\"ל א\"נ יש לחלק דלעיל איירי שהקהל התפללו ערבית והיא רצתה להקל על עצמה לעשות יום וללבוש לבנים לאו כל כמינה לאפוקי נפשה מצבורא אבל כאן מן השמים שלחו לו אבלות בעוד יום ולא התפלל עדיין יכול לומר לדידי יום הוא ולפ\"ז אף אם אירע אבלות כזה לאשה שלא התפללה ג\"כ אותו יום עולה לה ודלא כדמשמע ממהרש\"ל וכן עיקר עכ\"ל הש\"ך \u0005(אחד שנקבר סמוך לשבת ותיכף אחר הקבורה הפכו פניהם לבהכ\"נ ולא ישבו על הארץ אעפ\"כ עולה יום ו' למנין ז' דהפיכת פניהם הוי התחלת אבלות)\u0006 \u0005(הראנ\"ח ח\"ב סימן נ\"א)\u0006:"],"r":["\u0003(ליקוט) מאימתי כו'. \u0004דזהו נקרא סתימת הגולל ועתוס' \u0005(ברכות י\"ט ב' וש\"מ) \u0006ורא\"ש וכ\"מ בא\"ר פ\"ד מעשה כו' וכן בש\"ט לא נקראו האבות הקדושים עד שנתנו בארץ ונסתם הגולל בפניהם וכן בא\"ר פ\"י ובגמ' בכמה מקומות (ע\"כ):","\u0003ונגמר כו'. \u0004כן הכריע הרא\"ש ע\"ש בסי' פ\"ו והתוס' האריכו בזה בכמה מקומות:","\u0003אבל אינו כו'. \u0004כמ\"ש בפ\"א דתענית \u0005(י\"ג א') \u0006ובירושלמי \u0005(פ\"ב דברכות וש\"מ) \u0006ותוספתא \u0005(בתוספתא שלנו ליתא אלא בא\"ר פ\"ה) \u0006אבל ומנודה שמהלכין כו' וכמש\"ל סי' פ\"ב ס\"ד. הרא\"ש שם:","\u0003היה כו'. \u0004כמש\"ל סי' ש\"מ סכ\"ה:","\u0003וההולכים עמו כו' ואם גדול כו'. \u0004ירושלמי הביאו הרא\"ש סי' פ\"ו:","\u0003וגדול כו'. \u0004שם:","\u0003אם מפנין כו'. \u0004ירושלמי הביאו הרא\"ש סי' פ\"ז:","\u0003ואם מתחלה היה כו'. \u0004שם ס\"ס ק\"ג ממ\"ש ע\"ש:","\u0003אם כו'. \u0004שם ברא\"ש וכמ\"ש בס\"ג:","\u0003אע\"פ כו'. \u0004כ\"ה הגי' במ\"ש שם ודלא כמרדכי והביאו בה\"ג ס\"ק י' וכבר סתר דבריו בב\"י סי' שמ\"ה ועבד\"מ שם וכמש\"ש בהג\"ה ס\"ב:","\u0003מי כו'. \u0004ע\"ל ס\"א בהג\"ה:","\u0003מי כו'. \u0004מ\"ש וירושלמי הביאו הרא\"ש סי' ק\"ג ותוס' י\"ז ב' ד\"ה כשחל כו':","\u0003שי\"ל סוף. \u0004עבא\"ע סי' י\"ז ס\"ה בהג\"ה ועבה\"ג:\n\u0003(ליקוט) סעיף ה' וסעיף ז' הרוגי כו' מי שטבע כו'. \u0004א\"ר פ\"ב:","\u0003מצאוהו כו'. \u0004כת\"ק שם (ע\"כ):\n(ליקוט) ס\"ה וס\"ז ע\"ש \u0005(ברא\"ש) \u0006ס\"ס קמ\"א (ע\"כ):","\u0003ואם נמצא כו'. \u0004עברא\"ש שם וירושלמי א\"ר מנא יש קריעה בלא איבול כו':","\u0003ולא ידע כו'. \u0004הרא\"ש שם ע\"ש:","\u0003למקום כו'. \u0004דוקא. הג\"א שם:","\u0003שהוא כו'. \u0004תוס' שם ד\"ה מקום כו' וש\"פ:","\u0003אפילו שננערו כו'. \u0004בעיא דלא איפשיטא שם ולקולא:","\u0003וי\"א כו'. \u0004שם ת\"ש דאר\"ח כו' ל\"ק כו' והרי\"ף ורמב\"ם וש\"ע השמיטוהו דס\"ל דהוא אליבא דת\"ק והרא\"ש וש\"פ כתבו דאתי אף כר\"ש דר\"ש מודה כה\"ג היכא דהלך גדול לבדוק ועב\"י וד\"מ:","\u0003מי שהוא כו'. \u0004כמו בקריעה דמוסיף על קרע ראשון בתוך ז' כו' כמ\"ש בירושלמי \u0005(לגירסת המרדכי שם) \u0006ודבריו תמוהין דבגמ' דידן קי\"ל להיפך וכמש\"ל סי' ש\"מ סכ\"א ולהא ה\"ל לדמויי למש\"ש סכ\"ג מי שמתו לו כו' ול\"ד לקרע ואח\"כ מת כו' דקריעה הראשונה הלכה לה:"]}],["אֵין הַמְנַחֲמִים רַשָּׁאִים לִפְתֹּחַ, עַד שֶׁיִּפְתַּח הָאָבֵל תְּחִלָה. וְהָאָבֵל מֵסֵב בָּרֹאשׁ, וְכֵיוָן שֶׁנִּעְנַע הָאָבֵל בְּרֹאשׁוֹ, בְּעִנְיָן שֶׁנִּרְאֶה שֶׁפּוֹטֵר אֶת הַמְנַחֲמִים, אֵינָם רַשָּׁאִים לֵישֵׁב אֶצְלוֹ. \u0005אֵין אָבֵל אוֹ חוֹלֶה חַיָּבִים לַעֲמֹד, אֲפִלּוּ מִפְּנֵי נָשִׂיא (פ' א\"מ)\u0006.\nהַבָּא לְכַבֵּד אֶת חֲבֵרוֹ וְלָקוּם מִפָּנָיו, אוֹמֵר לוֹ: שֵׁב, אֶלָא אִם כֵּן הוּא אָבֵל אוֹ חוֹלֶה, דְּמַשְׁמָע: שֵׁב בָּאֲבֵלוּת שֶׁלְךָ, שֵׁב בַּחֹלִי שֶׁלְךָ. \u0005הַגָּה: לֹא יֹאמַר אָדָם: לֹא נִפְרַעְתִּי כְּפִי מַעֲשַׂי, אוֹ כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ, שֶׁאַל יִפְתַּח פִּיו לַשָּׂטָן (כֵּן מַשְׁמָע בְּפֶרֶק מִי שֶׁמֵּתוֹ וּבְהַגָּהוֹת אַלְפָסִי שָׁם)\u0006. וְאַל יֹאמַר אָדָם לְאָבֵל: מַה לְּךְ לַעֲשׂוֹת כִּי אִי אֶפְשָׁר לְשַׁנּוֹת, שֶׁזֶּהוּ \u0010c0\u0011 כְּגִדּוּף, דְּמַשְׁמָע הָא אִם אֶפְשָׁר לְשַׁנּוֹת הָיָה עוֹשֶׂה, אֶלָּא יְקַבֵּל עָלָיו גְּזֵרַת הַשֵּׁם יִתְבָּרַךְ מֵאַהֲבָה \u0005(נ\"י פ' שׁוֹר שֶׁנָּגַח דְּמַשְׁמָע כֵּן בַּגְּמָרָא)\u0006.\nמֵת שֶׁאֵין לוֹ אֲבֵלִים לְהִתְנַחֵם, בָּאִים עֲשָׂרָה בְּנֵי אָדָם כְּשֵׁרִים וְיוֹשְׁבִים בִּמְקוֹמוֹ כָּל ז' יְמֵי הָאֲבֵלוּת, וּשְׁאָר הָעָם מִתְקַבְּצִים עֲלֵיהֶם; וְאִם לֹא הָיוּ שָׁם עֲשָׂרָה קְבוּעִים, בְּכָל יוֹם וְיוֹם מִתְקַבְּצִים עֲשָׂרָה מִשְּׁאָר הָעָם וְיוֹשְׁבִים בִּמְקוֹמוֹ. \u0005הַגָּה: וְלֹא רָאִיתִי נוֹהֲגִין כֵּן. וְכָתוּב במהרי\"ל: \u0010c1\u0011 נוֹהֲגִים לְהִתְפַּלֵּל בַּעֲשָׂרָה כָּל ז' בַּמָּקוֹם שֶׁנִּפְטַר שָׁם הָאָדָם, \u0010y0\u0011 וְהַיְנוּ עַל אָדָם שֶׁלֹּא הִנִּיחַ קְרוֹבִים יְדוּעִים לְהִתְאַבֵּל עָלָיו, אֲבָל יֵשׁ לוֹ בְּשׁוּם מָקוֹם שֶׁמִּתְאַבְּלִים עָלָיו, אֵין צָרִיךְ וְכָזֶה רָאוּי לִנְהֹג.\u0006\nעַכְשָׁו נוֹהֲגִים שֶׁאַחַר שֶׁנִּגְמַר סְתִימַת הַקֶבֶר מֵעָפָר \u0005אוֹ לְאַחַר שֶׁהָפַךְ הָאָבֵל פָּנָיו מִן הַמֵּת,\u0006 \u0010y1\u0011 חוֹלְצִין מִנְעָל וְסַנְדָּל \u0010y2\u0011 וּמַרְחִיקִין מְעַט מִבֵּית הַקְבָרוֹת, וְאוֹמְרִים קַדִּישׁ דְּהוּא עָתִיד לְחַדְּתָא עָלְמָא, \u0010y3\u0011 וְאַחַר כָּךְ \u0010y4\u0011 תּוֹלְשִׁין עָפָר וְתוֹלְשִׁין עֲשָׂבִים, וּמַשְׁלִיכִים אַחַר גֵוָם וְרוֹחֲצִין יְדֵיהֶם בְּמַיִם. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁיּוֹשְׁבִים ז\"פ, מִפְּנֵי שֶׁהָרוּחוֹת מְלַוּוֹת אוֹתוֹ, וְכָל זְמַן שֶׁיּוֹשְׁבִין, בּוֹרְחִין מִמֶּנּוּ (מהרי\"ל בִּתְשׁוּבָה כ\"ג בְּשֵׁם י\"א)\u0006. וּבִמְדִינוֹת אֵלּוּ לֹא נָהֲגוּ לֵישֵׁב \u0010y5\u0011 \u0010c2\u0011 רַק ג\"פ, אַחַר שֶׁרָחֲצוּ הַיָּדַיִם, וְאוֹמְרִים כָּל פַּעַם: וִיהִי נֹעַם וְגו' \u0005(תְּהִלִּים צ, יז)\u0006, יוֹשֵׁב בְּסֵתֶר \u0005(תְּהִלִּים צא, א)\u0006 וְגו' וּכְשֶׁנִּקְבָּר הַמֵּת בְּיוֹם טוֹב, יְכוֹלִין לֵישֵׁב כָּךְ ג\"פ כְּמוֹ בַּחֹל \u0005(מ\"כ בְּהַגָּהוֹת מִנְהָגִים)\u0006. וְהוּא הַדִּין אִם נִקְבַּר סָמוּךְ לְשַׁבָּת, עוֹשִׂין כֵּן בְּשַׁבָּת. וְנָהֲגוּ לְהַקְפִּיד אִם יִכָּנֵס אָדָם לְבַיִת אַחֵר קֹדֶם שֶׁיִּרְחַץ וְיֵשֵׁב ג\"פ, וּמִנְהַג אֲבוֹתֵינוּ תּוֹרָה \u0005(שָׁם במהרי\"ל)\u0006. וְנִמְצָא בְּמִדְרָשׁוֹת לוֹמַר קַדִּישׁ עַל אָב \u0005(כָּל בּוֹ וריב\"ש בְּשֵׁם תַּנְחוּמָא וְסִפְרִי, וּבְחַיֵּי בְּשֵׁם מַסֶכֶת כַּלָּה, וּבֵית יוֹסֵף בְּשֵׁם הַזֹּהַר, וּבְאוֹר זָרוּעַ בְּשֵׁם תַּנָּא דְּבֵי אֵלִיָּהוּ רַבָּא)\u0006 ; עַל כֵּן נָהֲגוּ לוֹמַר עַל אָב וָאֵם קַדִּישׁ בַּתְרָא י\"ב חֹדֶשׁ, וְכֵן נָהֲגוּ לְהַפְטִיר בַּנָּבִיא, וּלְהִתְפַּלֵּל עַרְבִית בְּמוֹצָאֵי שַׁבָּתוֹת שֶׁהוּא הַזְּמַן שֶׁחוֹזְרִין הַנְּשָׁמוֹת לְגֵיהִנֹּם, וּכְשֶׁהַבֵּן מִתְפַּלֵּל וּמְקַדֵּשׁ בָּרַבִּים, פּוֹדֶה אָבִיו וְאִמּוֹ מִן הַגֵּיהִנֹּם \u0005(כָּל בּוֹ בְּשֵׁם הַגָּהוֹת)\u0006. וְנָהֲגוּ לוֹמַר קַדִּישׁ עַל הָאֵם אַף עַל פִּי שֶׁהָאָב חַי עֲדַיִן, אֵינוֹ בְּיָדוֹ לִמְחוֹת לִבְנוֹ שֶׁלֹּא יֹאמַר קַדִּישׁ עַל אִמּוֹ \u0005(סְבָרַת הַבֵּית יוֹסֵף עַל פִּי הַמִּנְהָג)\u0006. מִצְוָה לְהִתְעַנּוֹת בְּיוֹם שֶׁמֵּת אָב אוֹ אֵם \u0005(ריב\"ש וְכָל בּוֹ)\u0006. \u0010y6\u0011 שְׁלֹשָׁה אַחִין וְאִישׁ נָכְרִי, הַשְּׁלֹשָׁה אַחִין נוֹטְלִין הַשְּׁלֹשָׁה קַדִּישִׁין וְהָאוֹמֵר נוֹטֵל קַדִּישׁ אֶחָד. וְנָהֲגוּ שֶׁאִם מַגִּיעַ לְאָדָם יוֹם שֶׁמֵּת בּוֹ אָבִיו וְאִמּוֹ, שֶׁאוֹמְרִים עֲלֵיהֶם קַדִּישׁ יָתוֹם לְעוֹלָם, וּמִי שֶׁיּוֹדֵעַ לְהִתְפַּלֵּל כָּל הַתְּפִלָּה, מִתְפַּלֵּל; וְאִם יֵשׁ אֲבֵלִים אֲחֵרִים, נָהֲגוּ \u0010y7\u0011 \u0010c3\u0011 שֶׁתּוֹךְ שִׁבְעָה לְאֶבְלָם \u0010y8\u0011 הֵם קוֹדְמִים, וְאֵין לוֹ קַדִּישׁ כְּלָל; \u0010y9\u0011 תּוֹךְ שְׁלֹשִׁים, יֵשׁ לוֹ קַדִּישׁ אֶחָד; לְאַחַר ל', כָּל הַקַּדִּישִׁים שֶׁל אוֹתוֹ הַיּוֹם הֵם שֶׁלּוֹ. וּמוֹנִין שִׁבְעָה וְל' מִיּוֹם הַקְּבוּרָה, אַף עַל פִּי שֶׁלֹּא שָׁמַע הָאָבֵל מִיָּד \u0005(במהרי\"ל)\u0006. \u0010y10\u0011 וְאִם \u0010y11\u0011 נָכְרִי הוּא כְּאֶחָד מִבְּנֵי הָעִיר לְעִנְיַן קַדִּישׁ זוֹ, \u0010y12\u0011 הוֹלְכִים אַחַר הַמִּנְהָג \u0005(אָגוּר)\u0006. וְאֵין מָקוֹם לְקַדִּישׁ זוֹ אֶלָּא עַל אָב וָאֵם בִּלְבַד, אֲבָל לֹא בִּשְׁאָר קְרוֹבִים \u0005(בְּאוֹר זָרוּעַ)\u0006. וְאִם אֵין בב\"ה אָבֵל עַל אָבִיו וְאִמּוֹ, אוֹמֵר אוֹתוֹ קַדִּישׁ מִי שֶׁאֵין לוֹ אָב וָאֵם, בְּעַד כָּל מֵתֵי יִשְׂרָאֵל. \u0005(שָׁם)\u0006 וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁשְּׁאָר קְרוֹבִים אוֹמְרִים קַדִּישׁ עַל קְרוֹבֵיהֶם כְּשֶׁאֵין אֲבֵלִים עַל אֲבִיהֶם וְאִמָּם, וְיֵשׁ מְקוֹמוֹת שֶׁאֲפִלּוּ יֵשׁ אֲבֵלִים עַל אֲבִיהֶם וְאִמָּם, אוֹמְרִים שְׁאָר קְרוֹבִים, אֶלָּא שֶׁעוֹשִׂים פְּשָׁרָה בֵּינֵיהֶם שֶׁאֵין אוֹמְרִים כָּל כָּךְ קַדִּישִׁים כְּמוֹ הָאֲבֵלִים עַל אָב וָאֵם \u0005(מהרי\"ק שֹׁרֶשׁ מ\"ד)\u0006 ; וְהוֹלְכִין בְּכָל זֶה אַחַר הַמִּנְהָג, וּבִלְבַד שֶׁיְּהֵא מִנְהָג קָבוּעַ בָּעִיר. וְהָאֲבֵלִים אוֹמְרִים קַדִּישׁ אֲפִלּוּ בְּשַׁבָּת וְיוֹם טוֹב \u0005(בְּאוֹר זָרוּעַ בְּשֵׁם ר\"י \u0010y13\u0011 מקורבי\"ל)\u0006, אֲבָל לֹא נָהֲגוּ לְהִתְפַּלֵּל בְּשַׁבָּת וְיוֹם טוֹב \u0005(כֵּן הוּא בִּתְשׁוּבַת מהרי\"ל)\u0006, אַף עַל פִּי שֶׁאֵין אִסּוּר בַּדָּבָר, אֲבָל בִּימוֹת הַחֹל, מִי שֶׁיּוֹדֵעַ לְהִתְפַּלֵּל, יִתְפַּלֵּל וְיוֹתֵר מוֹעִיל מִקַּדִּישׁ יָתוֹם שֶׁלֹּא נִתְקַן אֶלָּא לִקְטַנִּים; וּמִי שֶׁאֵינוֹ יוֹדֵעַ לְהִתְפַּלֵּל כָּל הַתְּפִלָּה, יִתְפַּלֵּל לַמְנַצֵּחַ וּבָא לְצִיּוֹן וְכו' \u0005(בְּאוֹר זָרוּעַ)\u0006. וְנָהֲגוּ שֶׁאֵין אוֹמְרִים קַדִּישׁ וּתְפִלָּה \u0010c4\u0011 רַק י\"א חֳדָשִׁים, כְּדֵי שֶׁלֹּא יַעֲשׂוּ אֲבִיהֶם וְאִמָּם רְשָׁעִים, כִּי מִשְׁפַּט רָשָׁע י\"ב חֹדֶשׁ. וְאִם הָיוּ אֲבֵלִים כָּאן וּבָאוּ אַחַר כָּךְ אֲבֵלִים אֲחֵרִים, הַשְּׁנִיִּים יֵשׁ לָהֶם הַקַּדִּישִׁים וְהַתְּפִלּוֹת כָּל ל' יוֹם מִיּוֹם הַקְּבוּרָה, אַף עַל פִּי שֶׁלֹּא שָׁמְעוּ. \u0010y14\u0011 יֵשׁ אוֹמְרִים דְּמוּמָר \u0010c5\u0011 שֶׁנֶּהֱרַג בְּיַד עוֹבְדֵי כּוֹכָבִים, בָּנָיו אוֹמְרִים עָלָיו קַדִּישׁ \u0005(הרד\"כ בַּיִת י\"א ובב\"ז)\u0006 וְעַיֵּן לְעֵיל סִימָן ש\"מ.",["\u0003והיינו על אדם כו'. \u0004ע\"ל סימן שפ\"ד סעיף ג' בהג\"ה:","\u0003חולצים מנעל כו'. \u0004וע\"ל ס\"ס שפ\"ב:","\u0003ומרחיקין מעט מבה\"ק. \u0004כדי לומר קדיש לפחות ד\"א שהמת תופס ד\"א עכ\"ל עט\"ז וכ\"כ לעיל ס\"ס שס\"ז בשם האחרונים דאף לקדיש צריך להרחיק ד\"א. כתוב בב\"ה בשם א\"ח דאם נקבר בלילה א\"א לא צדוק הדין ולא קדיש בבה\"ק וכ\"כ בב\"י בשם הכל בו ():","\u0003ואחר כך תולשים עפר כו'. \u0004ואומרים זכור כי עפר אנחנו וגם הוא רמז לתחיית המתים שיחיו מעפרם ע\"ד ויציצו (ויפרחו) מעיר כעשב הארץ:","\u0003תולשים עפר כו'. \u0004לומר דטומאה זו אינה נטהרת אלא בכעין ג' דברים הללו מים ואפר פרה ואזוב. רמב\"ן. והכל בו כתב תולשים עשבים בצרור עפרם וזורקם על ראשו דרך צער ע\"ד ויזרקו עפר על ראשיהם השמימה:","\u0003רק שלש פעמים כו'. \u0004ועי' בעט\"ז שכ' דיש לישב ז\"פ בפסוק דכי מלאכיו יצוה לך וגו' ויאמר אתה גבור כו' שיש בזה סוד הקבל' להבריח כחות הטומאה ע\"כ וכ\"כ בפרישה בשם מהרש\"ל שקבל כך מאמ\"ז לומר ז' פעמים בפסוק כי מלאכיו גו' ע\"ש:","\u0003ג' אחין ואיש נכרי כו'.\u0004 כלומר נכרי שאינו אח שלהן אפי' הוא תושב:","\u0003שתוך ז' לאבלם כו'. \u0004כתוב במנהגים דהיינו דוקא בשבת שבתוך ז' אבל בחול אינו הולך לב\"ה אך אם הבן ז' הוא קטן שאינו בר מצוה והולך לב\"ה כל ז' לומר קדיש או מי שאירע לו מיתת אב ואם תוך אותן ז' יאמר קדיש יתום פעם א' עכ\"ל ונרא' דמי שבטלה אבלותו ברגל כגון שעה א' לפני הרגל בטלה ממנו גזירת ז' או ל' מ\"מ דין ז' ול' יש לו אפילו בחול כמו בשבת דהרי בדין הולך לב\"ה. כ' בתשו' מ\"ב סי' ע\"ג שדברי המנהגי' סותרי' זא\"ז דמתחלה כ' יום שמת אב ואם לתושב דוחה את בן ל' מכ\"ש בן י\"ב חדש לתושב כל אותו יום התענית דהיינו תפלת ערבית ושחרית ומנחה וכן הקדישי' של אותו יום שאומרים לפני העמוד אלמא דסבירא ליה דיא\"צ עדיף ושוב כ' דבן י\"ב חדש ויארצייט אורח יש לאורח קדיש א' אבל בן ל' אורח מחלק עמו כל הקדישים והתפלות אלמא דבן ל' עדיף ותירץ דברישא מיירי שיש הרבה יארצייט דאם לא יאמרו כלל עבר זמנו בטל קרבנו ולפי זה מ\"ש במנהגים אם הבן ז' קטן או מי שאירע יארצייט תוך אותן ז' יאמר קדיש יתום פעם א' זהו דוקא ביארצייט מטעם דעבר זמנו בטל קרבנו אבל לבן ל' א\"צ ליתן אפילו קדיש א' עכ\"ל ולא משמע הכי ברישא דיש הרבה יארצייט ועוד מדכתב דוחה את בן ל' מכ\"ש בן י\"ב חודש כו' אלמא דבגוני דאיירי בי\"ב חדש מיירי בל' ובי\"ב חדש ודאי מיירי אפילו ביארצייט א' ועוד דא\"כ מאי כ\"ש הוא דילמא היכא דליכא אלא יארצייט א' אינו דוחה אפילו י\"ב חדש והא דדוחה בן ל' היינו משום דיש הרבה יא\"צ אלא נראה דהדברים כפשטן דמיירי שיש רק יא\"צ א' ואפ\"ה דוחה את הבן ל' דס\"ל למנהגים דיא\"צ עדיפא מבן שלשים. וכן משמע מהעט\"ז שהבאתי לקמן דדעת המנהגים כן ול\"ק מ\"ש בסוף דאורח יא\"צ יש לו רק קדיש א' והבן ל' חולק עם תושב בן י\"ב די\"ל דודאי לענין אורח נגד תושב בן ל' עדיף משום דמצי התושב לומר מן הדין אין ליתן לך כלל דהרי היכא דשניהם בן ל' או יארצייט או בני י\"ב חדש אין לאורח כלום אלא כיון דאתה ל' ואני י\"ב חדש אתה חולק עמי אבל ביארצייט שזמנו קבוע וגם ידוע לו קודם לכן שנה תמימה ואתה באת בגבולי די לך בקדיש אחד אבל בבן ל' ליכא למימר הכי ולפי זה לדידן דקים לן דבן ל' עדיף א\"כ אירע בן ל' תושב תוך ז' לקטן יש לו ג\"כ קדיש אחד והכי נהוג:","\u0003הם קודמים כו'.\u0004 כתוב במנהגים דאפילו הבן ז' הוא נכרי דוחה את התושב אפילו בן ל' או יארצייט:","\u0003תוך שלשים יש לו קדיש אחד. \u0004ליארצייט אבל לבן י\"ב חדש אין לו כלום שהתושב בן שלשים דוחה את התושב בן י\"ב בתפלה ובקדיש לפני העמוד אך בקדיש ובפריסת שמע שעל פתח ב\"ה שניהם שוין בו ויחלקו בגורל כ\"כ במנהגים ויש מנהגים אחרים בקדיש ופריסת שמע שעל הפתח ונהרא נהרא ופשטיה ועיין עוד במנהגים מדינים אלו. ומ\"ש תוך שלשים יש לו קדיש אחד משמע דאם יש שלשה קדישים כגון בשבת אומר הבן שלשים שני קדישים והיארצייט קדיש אחד וכן משמע במהרי\"ל סוף הל' תפלה ובמנהגים כתוב ויום שמת בו אב ואם לתושב דוחה את בן שלשים מכ\"ש בן י\"ב חודש לתושב כל אותו יום התענית דהיינו תפלת ערבית שחרית ומנחה וכן הקדישים של אותו יום שאומרים לפני העמוד ע\"כ. מיהו הלבוש בא\"ח סימן קל\"ג השיג על זה וז\"ל ול\"נ שאין היארצייט דוחה את הבן שלשים מכל וכל אלא די לו בקדיש אחד עכ\"ל וזהו כדעת מהרי\"ל והרב וכ\"פ בתשובת מ\"ב סימן ע\"ג וכן עיקר וכתב עוד שם דהיינו דוקא דליכא אלא יארצייט אחד ובן שלשים אחד אבל היכא דבן שלשים ויארצייט הם רבים ואי אפשר ליתן קדיש לכל אחד ואחד ובע\"כ נידחין קצתן בכה\"ג היארצייט עדיף ונדחה הבן שלשים מפני היארצייט שאם לא יאמר היארצייט קדיש היום למחר עבר זמנו ובטל קרבנו מה שאין כן בבן שלשים ע\"כ ואע\"פ שהוציא כן מתוך מה שתירץ ליישב דברי מנהגים אהדדי ואין דבריו מוכרחים בתירוץ זה וכמ\"ש לעיל מ\"מ הסברא נכונה וכן נהגו:","\u0003ואם נכרי הוא באחד מבני העיר לענין קדיש זו הולכין אחר המנהג. \u0004יש קהילות דנהיגי דתושב דוחה את האורח ויש מקומות דנהיגי דשוין הן ומקומות דנהיגי דתושב דוחה את הנכרי מ\"מ פעם ראשונה יש רשות לנכרי להתפלל ולומר קדיש יתום פעם אחת. כ\"כ במנהגים. ונראה לי דהא דיש לו לאורח קדיש אחד היינו דהוי כמו תושב בן י\"ב חדש ולפי זה היכא דהתושב אין לו קדיש אחד כגון שיש כאן בן שלשים וכה\"ג גם לאורח אין לו כלום:","\u0003נכרי כו'. \u0004כתוב במנהגים אם אותו שמת יש לו בנים בעיר אחרת ובאו לשם אינם נקראים תושבים בשביל אביהם שנקבר שם רק אותן הדרים תוך הקהלה וכל דרי הקהלה נקראים תושבים הן אותן שנותנים מס או משרתי הקהלה ואפי' עניי העיר שיש להם שם דירת קבע כולם חשבינן כתושבים ואם אדם קובע דירתו תוך הקהלה אז משעה שהוא חייב לישא בעול עם דרי הקהלה חשוב תושב אבל לא משעה שגמר פיסוק המס עם ההגמון אע\"ג שצריך ליתן המס להגמון וכן איפכא מי שעקר דירה מן הקהלה אז משעה שאינו חייב לישא בעול עם דרי הקהלה חשוב כאורח אע\"פ שחייב עדיין ליתן המס להגמון ואם יש לבעל הבית מלמד או שמש המושכר לזמן והוא פנוי שאין לו אשה ובנים אז גם הוא נקרא תושב אבל אם יש לו אשה ובנים במקום אחר אז דינו כנכרי ואם בעל הבית מגדל בביתו יתום אפילו בשכר ואין לו אב או אם במקום אחר אז נקרא תושב אבל אם יש לו אב או אם אינו נקרא תושב אפילו אם מגדלו בתורת צדקה מכ\"ש אם הוא אצלו בשכר עכ\"ל ונראה דנערים ובחורים הלומדים בישיבה אפילו יש להם אב או אם במקום אחר יש להם דין תושב ואפי' בעה\"ב שלומד בישיבה אע\"פ שיש לו אשה ובנים במקום אחר ונותן מס במקום שאשתו ובניו שם מ\"מ דין תושב יש לו במקום שהוא לומד והכי נהוג:","\u0003הולכים אחר המנהג. \u0004וכתוב במנהגים דהיכא ששניהם בני שלשים או שניהם יא\"צ או שניהם שנים עשר חודש דוחה את האורח לגמרי מלהתפלל ולומר קדיש על העמוד אך בפריסת שמע וקדיש על הפתח שניהן שוין ויחלקו בגורל ואם תושב ואורח שניהם בני שבעה יחלקו בגורל כי לענין שבעה אין שום עילוי לתושב על האורח ע\"כ. וכתוב בתשובת מ\"ב שם דאפילו בן שבעה אחד גדול ותושב ובן שבעה אחד קטן ואורח אפ\"ה חולקים בשוה:","\u0003אבל לא נהגו להתפלל בשבתות ויו\"ט. \u0004וכן בימים נוראים אסור וכ\"פ מהרי\"ל מיהו היכא דליכא דעדיף מיניה מותר כ\"כ מהרי\"ו בדינים והלכות סימן מ\"ז:","\u0003דמומר שנהרג. \u0004דוקא נהרג אבל מת על מטתו לא וכן כתבתי לעיל סימן ש\"מ דכשנהרג יש לו כפרה עד כאן לשון ד\"מ."],["\u0003דמשמע הא אם אפשר לשנות כו'. \u0004בפרק שור שנגח ארבעה וחמשה איתא כן שלא רצה עולא לילך לנחם את רבי שמואל בר יהודה שאמר מה לי בתנחומין של בני בבל שאומרים מה אית לך למיעבד דמשמע הא אפשר למיעבד עבדי וזו היא גידוף. ורש\"ל דחה זה מהלכה שאמר הלא גם דוד המע\"ה אמר כן האוכל להשיבו עוד דמשמע אם היה אפשר להשיבו היה עושה. ותמהני על פה קדוש יאמר כן דשאני גבי דוד שאמר למה זה אני צם האוכל להשיבו עוד דודאי כל טצדקי תפלות וצומות יש לו לאדם לעשות כדי לבקש שלא ימות לו מת ועל זה אמר דוד כיון שכבר מת לא יועילו הצומות ועל זה סיים ואמר אני הולך אליו והוא לא ישוב אלי דלכאורה הוא דבר שאינו מענין תשובה לעבדיו שם אלא דהכי קאמר שמא תאמרו דיועילו הצומות שאזכה לראותו בעודו בחיים כשיקום זה הילד בתחיית המתים לזה אמר יודע אני שלא תהיה תחיית המתים בימי ועל זה אמר אני הולך אליו וגו' אבל אותן המנחמים שאומרים אל תצער עצמך כי מה לך לעשות אין אומרי' על התפלה כן אלא על הצער שלא יצער עצמו כיון שא\"א בענין אחר דמשמע הא אפשר בענין אחר היה עושה שפי' היה מצער עצמו על שלא יהיה כרצון האדם וזהו גידוף שמן הראוי להיות כרצון האל יתברך לא כרצון האדם וזה ברור לע\"ד:","\u0003נוהגים להתפלל בעשרה כל שבעה. \u0004באורח חיים סימן קל\"א כ' דאין אומרים תחנון בבית האבל והיינו כל ז' הימים וכ' הרוקח שאחר גמר התפלה אומרים תחנון ואין קורין שם בבית האבל הלל בר\"ח לפי שיש שם אנינות לכך אין אומרים לא המתים יהללו יה משום לועג לרש עכ\"ל. וכתב מו\"ח ז\"ל דבימים נוראים אם האבל הגון ולא נמצא כמוהו הוא קודם להתפלל אפי' תוך ל' על אביו ואמו וכן נמצא בהג\"ה ולא כיש מקפידים:","\u0003רק ג\"פ. \u0004כתב רש\"ל שקיבל מאביו זקינו שיש לומר ז' פעמים דהיינו בפעם א' עד מלת כי ומלת כי בכלל. ובפעם הב' עד כי מלאכיו. ובג' עד כי מלאכיו יצוה. ובד' עד יצוה לך. ובה' עד לך לשמרך. ובו' עד לשמרך בכל. ובז' עד בכל דרכיך ויש בו סוד וכתוב בלבוש שגם הוא נהג כן:","\u0003שתוך ז' לאבלם. \u0004במנהגים כתוב שבן ל' נדחה מבן יארציי\"ט לגמרי אם הוא תושב כל אותו יום ורמ\"א כ' כאן שאין ליא\"צ אלא קדיש א' תוך ל' ובספר משאת בנימין הקשה דברי המנהגים אהדדי דמתחלה כתבו בן ל' ויא\"צ דוחה היא\"צ לבן ל' כמו לי\"ב חודש אלמא דיא\"צ עדיף מבן ל' ושוב כ' דבן י\"ב תושב ויארציי\"ט אורח או בן שלשים אורח מסלק היב\"ח תושב להיארציי\"ט אורח בקדיש אחד ותפלה אחת ולבן שלשים אורח מחלק עמו כל הקדישי' כו' ש\"מ דבן שלשים עדיף מיארציי\"ט וחילק שם דהיכא דאיכא רווחא כגון בשבת דאיכא שלשה קדישים ואחד בן שלשים ואחד יארציי\"ט אז בן שלשים עדיף דהוא אומר שני קדישים והיארציי\"ט קדיש אחד אבל היכא דאיכא דוחק בקדישים ואינו מגיע לכל אחד קדיש אחד אז נדחה הבן שלשים מפני היארציי\"ט והטעם שאם לא יאמר היארציי\"ט אותו יום קדיש לא יוכל לומר למחר כי עבר היום בטל הקרבן מה שאין כן בבן שלשים שיוכל לומר למחר וחילוק נכון הוא דכל שאפשר לתת קדיש לשניהם אז יש מעלה לבן שלשים על היארצייט משא\"כ אם יהיה היארציי\"ט נדחה לגמרי זהו אינו מסתבר וכתב עוד דלענין שבעה אין חילוק בין גדול לקטן תושב לאורח נראה לי דמי שמת בשבת או בי\"ט וא\"א לקברו בו ביום דעל כל פנים יאמר קדיש תיכף אחר המיתה דאין אמירת קדיש תלוי באבילות כלל אבל בחול אין לעשות כן דהא כשהוא אונן פטור מן התפלה כן נ\"ל:","\u0003רק י\"א חודש. \u0004עיין מה שכתבתי בסימן ר\"מ סעיף ט' מזה דבר הגון:","\u0003שנהרג בידי עובדי כוכבים. \u0004פי' דאז יש לו כפרה ע\"י ההריגה אבל מת על מטתו לא וכן מבואר בסימן ש\"מ סעיף ה' לענין אבילות עליו וחילוק זה של מת או נהרג הוא תלמוד ערוך בפרק נגמר הדין (סנהדרין דף מ\"ז:)"],"\u0010g0\u0011 אֵין הַמְנַחֲמִים רַשָּׁאִים לִפְתֹּחַ, עַד שֶׁיִּפְתַּח הָאָבֵל תְּחִלָה. \u0010g1\u0011 וְהָאָבֵל מֵסֵב בָּרֹאשׁ, \u0010g2\u0011 וְכֵיוָן שֶׁנִּעְנַע הָאָבֵל בְּרֹאשׁוֹ, בְּעִנְיָן שֶׁנִּרְאֶה שֶׁפּוֹטֵר אֶת הַמְנַחֲמִים, אֵינָם רַשָּׁאִים לֵישֵׁב אֶצְלוֹ. \u0010r0\u0011 \u0005אֵין אָבֵל אוֹ חוֹלֶה חַיָּבִים לַעֲמֹד, אֲפִלּוּ מִפְּנֵי נָשִׂיא (פ' א\"מ)\u0006. \u0010g3\u0011\nהַבָּא לְכַבֵּד אֶת חֲבֵרוֹ וְלָקוּם מִפָּנָיו, אוֹמֵר לוֹ: שֵׁב, אֶלָא אִם כֵּן הוּא אָבֵל אוֹ חוֹלֶה, דְּמַשְׁמָע: שֵׁב בָּאֲבֵלוּת שֶׁלְךָ, שֵׁב בַּחֹלִי שֶׁלְךָ. \u0005הַגָּה: \u0010r1\u0011 לֹא יֹאמַר אָדָם: לֹא נִפְרַעְתִּי כְּפִי מַעֲשַׂי, אוֹ כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ, שֶׁאַל יִפְתַּח פִּיו לַשָּׂטָן (כֵּן מַשְׁמָע בְּפֶרֶק מִי שֶׁמֵּתוֹ וּבְהַגָּהוֹת אַלְפָסִי שָׁם)\u0006. \u0010r2\u0011 וְאַל יֹאמַר אָדָם לְאָבֵל: מַה לְּךְ לַעֲשׂוֹת כִּי אִי אֶפְשָׁר \u0010t0\u0011 לְשַׁנּוֹת, שֶׁזֶּהוּ \u0010c0\u0011 כְּגִדּוּף, דְּמַשְׁמָע הָא אִם אֶפְשָׁר לְשַׁנּוֹת הָיָה עוֹשֶׂה, אֶלָּא יְקַבֵּל עָלָיו גְּזֵרַת הַשֵּׁם יִתְבָּרַךְ מֵאַהֲבָה \u0005(נ\"י פ' שׁוֹר שֶׁנָּגַח דְּמַשְׁמָע כֵּן \u0010g4\u0011 בַּגְּמָרָא)\u0006.\nמֵת שֶׁאֵין לוֹ אֲבֵלִים לְהִתְנַחֵם, בָּאִים עֲשָׂרָה בְּנֵי אָדָם כְּשֵׁרִים וְיוֹשְׁבִים בִּמְקוֹמוֹ כָּל ז' יְמֵי הָאֲבֵלוּת, וּשְׁאָר הָעָם מִתְקַבְּצִים עֲלֵיהֶם; וְאִם לֹא הָיוּ שָׁם עֲשָׂרָה קְבוּעִים, בְּכָל יוֹם וְיוֹם מִתְקַבְּצִים עֲשָׂרָה מִשְּׁאָר הָעָם וְיוֹשְׁבִים בִּמְקוֹמוֹ. \u0005הַגָּה: וְלֹא רָאִיתִי נוֹהֲגִין כֵּן. וְכָתוּב במהרי\"ל: \u0010c1\u0011 נוֹהֲגִים \u0010t1\u0011 לְהִתְפַּלֵּל בַּעֲשָׂרָה כָּל ז' בַּמָּקוֹם שֶׁנִּפְטַר שָׁם הָאָדָם, \u0010y0\u0011 וְהַיְנוּ עַל אָדָם שֶׁלֹּא הִנִּיחַ קְרוֹבִים יְדוּעִים לְהִתְאַבֵּל עָלָיו, אֲבָל יֵשׁ לוֹ בְּשׁוּם מָקוֹם שֶׁמִּתְאַבְּלִים עָלָיו, אֵין צָרִיךְ וְכָזֶה רָאוּי \u0010g5\u0011 לִנְהֹג.\u0006\nעַכְשָׁו נוֹהֲגִים שֶׁאַחַר שֶׁנִּגְמַר סְתִימַת הַקֶבֶר מֵעָפָר \u0005אוֹ לְאַחַר שֶׁהָפַךְ הָאָבֵל פָּנָיו מִן הַמֵּת,\u0006 \u0010y1\u0011 חוֹלְצִין מִנְעָל וְסַנְדָּל \u0010y2\u0011 וּמַרְחִיקִין \u0010t2\u0011 מְעַט מִבֵּית הַקְבָרוֹת, וְאוֹמְרִים קַדִּישׁ דְּהוּא עָתִיד לְחַדְּתָא עָלְמָא, \u0010y3\u0011 \u0010r3\u0011 וְאַחַר כָּךְ \u0010y4\u0011 \u0010g6\u0011 תּוֹלְשִׁין \u0010t3\u0011 עָפָר וְתוֹלְשִׁין עֲשָׂבִים, וּמַשְׁלִיכִים אַחַר גֵוָם וְרוֹחֲצִין יְדֵיהֶם \u0010t4\u0011 בְּמַיִם. \u0005הַגָּה: \u0010r4\u0011 יֵשׁ אוֹמְרִים שֶׁיּוֹשְׁבִים ז\"פ, מִפְּנֵי שֶׁהָרוּחוֹת מְלַוּוֹת אוֹתוֹ, וְכָל זְמַן שֶׁיּוֹשְׁבִין, בּוֹרְחִין מִמֶּנּוּ (מהרי\"ל בִּתְשׁוּבָה כ\"ג בְּשֵׁם י\"א)\u0006. וּבִמְדִינוֹת אֵלּוּ לֹא נָהֲגוּ לֵישֵׁב \u0010y5\u0011 \u0010c2\u0011 רַק ג\"פ, אַחַר שֶׁרָחֲצוּ הַיָּדַיִם, וְאוֹמְרִים כָּל פַּעַם: וִיהִי \u0010t5\u0011 נֹעַם וְגו' \u0005(תְּהִלִּים צ, יז)\u0006, יוֹשֵׁב בְּסֵתֶר \u0005(תְּהִלִּים צא, א)\u0006 וְגו' וּכְשֶׁנִּקְבָּר הַמֵּת בְּיוֹם טוֹב, יְכוֹלִין לֵישֵׁב כָּךְ ג\"פ כְּמוֹ בַּחֹל \u0005(מ\"כ בְּהַגָּהוֹת מִנְהָגִים)\u0006. וְהוּא הַדִּין אִם נִקְבַּר סָמוּךְ לְשַׁבָּת, עוֹשִׂין כֵּן בְּשַׁבָּת. וְנָהֲגוּ לְהַקְפִּיד אִם יִכָּנֵס אָדָם לְבַיִת אַחֵר קֹדֶם שֶׁיִּרְחַץ וְיֵשֵׁב ג\"פ, וּמִנְהַג אֲבוֹתֵינוּ תּוֹרָה \u0005(שָׁם במהרי\"ל)\u0006. \u0010r5\u0011 וְנִמְצָא בְּמִדְרָשׁוֹת לוֹמַר קַדִּישׁ עַל אָב \u0005(כָּל בּוֹ וריב\"ש בְּשֵׁם תַּנְחוּמָא וְסִפְרִי, וּבְחַיֵּי בְּשֵׁם מַסֶכֶת כַּלָּה, וּבֵית יוֹסֵף בְּשֵׁם הַזֹּהַר, וּבְאוֹר זָרוּעַ בְּשֵׁם תַּנָּא דְּבֵי אֵלִיָּהוּ רַבָּא)\u0006 ; עַל כֵּן נָהֲגוּ לוֹמַר עַל אָב וָאֵם קַדִּישׁ בַּתְרָא י\"ב חֹדֶשׁ, וְכֵן נָהֲגוּ לְהַפְטִיר בַּנָּבִיא, וּלְהִתְפַּלֵּל עַרְבִית בְּמוֹצָאֵי שַׁבָּתוֹת שֶׁהוּא הַזְּמַן שֶׁחוֹזְרִין הַנְּשָׁמוֹת לְגֵיהִנֹּם, וּכְשֶׁהַבֵּן מִתְפַּלֵּל וּמְקַדֵּשׁ בָּרַבִּים, פּוֹדֶה אָבִיו וְאִמּוֹ מִן הַגֵּיהִנֹּם \u0005(כָּל בּוֹ בְּשֵׁם הַגָּהוֹת)\u0006. וְנָהֲגוּ לוֹמַר קַדִּישׁ עַל הָאֵם אַף עַל פִּי שֶׁהָאָב חַי עֲדַיִן, אֵינוֹ בְּיָדוֹ לִמְחוֹת לִבְנוֹ שֶׁלֹּא יֹאמַר קַדִּישׁ עַל אִמּוֹ \u0005(סְבָרַת \u0010g7\u0011 הַבֵּית יוֹסֵף עַל פִּי הַמִּנְהָג)\u0006. \u0010r6\u0011 מִצְוָה לְהִתְעַנּוֹת בְּיוֹם שֶׁמֵּת אָב אוֹ אֵם \u0005(ריב\"ש וְכָל בּוֹ)\u0006. \u0010y6\u0011 שְׁלֹשָׁה אַחִין וְאִישׁ \u0010t6\u0011 נָכְרִי, הַשְּׁלֹשָׁה אַחִין נוֹטְלִין הַשְּׁלֹשָׁה קַדִּישִׁין וְהָאוֹמֵר נוֹטֵל קַדִּישׁ אֶחָד. וְנָהֲגוּ שֶׁאִם מַגִּיעַ לְאָדָם יוֹם שֶׁמֵּת בּוֹ אָבִיו וְאִמּוֹ, שֶׁאוֹמְרִים עֲלֵיהֶם קַדִּישׁ יָתוֹם לְעוֹלָם, וּמִי שֶׁיּוֹדֵעַ לְהִתְפַּלֵּל כָּל הַתְּפִלָּה, מִתְפַּלֵּל; וְאִם יֵשׁ אֲבֵלִים אֲחֵרִים, נָהֲגוּ \u0010y7\u0011 \u0010c3\u0011 שֶׁתּוֹךְ שִׁבְעָה לְאֶבְלָם \u0010y8\u0011 הֵם \u0010t7\u0011 קוֹדְמִים, וְאֵין לוֹ קַדִּישׁ כְּלָל; \u0010y9\u0011 תּוֹךְ שְׁלֹשִׁים, יֵשׁ לוֹ קַדִּישׁ \u0010g8\u0011 \u0010t8\u0011 אֶחָד; לְאַחַר ל', כָּל הַקַּדִּישִׁים שֶׁל אוֹתוֹ הַיּוֹם הֵם שֶׁלּוֹ. וּמוֹנִין שִׁבְעָה וְל' מִיּוֹם הַקְּבוּרָה, אַף עַל פִּי שֶׁלֹּא שָׁמַע הָאָבֵל מִיָּד \u0005(במהרי\"ל)\u0006. \u0010y10\u0011 וְאִם \u0010y11\u0011 נָכְרִי הוּא כְּאֶחָד מִבְּנֵי הָעִיר לְעִנְיַן קַדִּישׁ זוֹ, \u0010y12\u0011 הוֹלְכִים אַחַר \u0010t9\u0011 הַמִּנְהָג \u0005(אָגוּר)\u0006. וְאֵין מָקוֹם לְקַדִּישׁ זוֹ אֶלָּא עַל אָב וָאֵם בִּלְבַד, אֲבָל לֹא בִּשְׁאָר קְרוֹבִים \u0005(בְּאוֹר זָרוּעַ)\u0006. וְאִם אֵין בב\"ה אָבֵל עַל אָבִיו וְאִמּוֹ, אוֹמֵר אוֹתוֹ קַדִּישׁ מִי שֶׁאֵין לוֹ אָב וָאֵם, בְּעַד כָּל מֵתֵי יִשְׂרָאֵל. \u0005(שָׁם)\u0006 וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁשְּׁאָר קְרוֹבִים אוֹמְרִים קַדִּישׁ עַל קְרוֹבֵיהֶם כְּשֶׁאֵין אֲבֵלִים עַל אֲבִיהֶם וְאִמָּם, וְיֵשׁ מְקוֹמוֹת שֶׁאֲפִלּוּ יֵשׁ אֲבֵלִים עַל אֲבִיהֶם וְאִמָּם, אוֹמְרִים שְׁאָר קְרוֹבִים, אֶלָּא שֶׁעוֹשִׂים פְּשָׁרָה בֵּינֵיהֶם שֶׁאֵין אוֹמְרִים כָּל כָּךְ קַדִּישִׁים כְּמוֹ הָאֲבֵלִים עַל אָב וָאֵם \u0005(מהרי\"ק שֹׁרֶשׁ מ\"ד)\u0006 ; וְהוֹלְכִין בְּכָל זֶה אַחַר הַמִּנְהָג, וּבִלְבַד שֶׁיְּהֵא מִנְהָג קָבוּעַ בָּעִיר. וְהָאֲבֵלִים אוֹמְרִים קַדִּישׁ אֲפִלּוּ בְּשַׁבָּת וְיוֹם טוֹב \u0005(בְּאוֹר זָרוּעַ בְּשֵׁם ר\"י \u0010y13\u0011 מקורבי\"ל)\u0006, אֲבָל לֹא נָהֲגוּ לְהִתְפַּלֵּל בְּשַׁבָּת וְיוֹם טוֹב \u0005(כֵּן הוּא בִּתְשׁוּבַת מהרי\"ל)\u0006, אַף עַל פִּי שֶׁאֵין אִסּוּר בַּדָּבָר, אֲבָל בִּימוֹת הַחֹל, מִי שֶׁיּוֹדֵעַ לְהִתְפַּלֵּל, יִתְפַּלֵּל וְיוֹתֵר מוֹעִיל מִקַּדִּישׁ יָתוֹם שֶׁלֹּא נִתְקַן אֶלָּא לִקְטַנִּים; וּמִי שֶׁאֵינוֹ יוֹדֵעַ לְהִתְפַּלֵּל כָּל הַתְּפִלָּה, יִתְפַּלֵּל לַמְנַצֵּחַ וּבָא לְצִיּוֹן וְכו' \u0005(בְּאוֹר זָרוּעַ)\u0006. וְנָהֲגוּ שֶׁאֵין אוֹמְרִים קַדִּישׁ וּתְפִלָּה \u0010c4\u0011 \u0010t10\u0011 רַק י\"א חֳדָשִׁים, כְּדֵי שֶׁלֹּא יַעֲשׂוּ אֲבִיהֶם וְאִמָּם רְשָׁעִים, כִּי מִשְׁפַּט רָשָׁע י\"ב חֹדֶשׁ. וְאִם הָיוּ אֲבֵלִים כָּאן וּבָאוּ אַחַר כָּךְ אֲבֵלִים אֲחֵרִים, הַשְּׁנִיִּים יֵשׁ לָהֶם הַקַּדִּישִׁים וְהַתְּפִלּוֹת כָּל ל' יוֹם מִיּוֹם הַקְּבוּרָה, אַף עַל פִּי שֶׁלֹּא שָׁמְעוּ. \u0010y14\u0011 \u0010r7\u0011 יֵשׁ אוֹמְרִים דְּמוּמָר \u0010c5\u0011 \u0010t11\u0011 שֶׁנֶּהֱרַג בְּיַד עוֹבְדֵי כּוֹכָבִים, בָּנָיו אוֹמְרִים עָלָיו קַדִּישׁ \u0005(הרד\"כ בַּיִת י\"א ובב\"ז)\u0006 וְעַיֵּן לְעֵיל סִימָן ש\"מ. \u0010g9\u0011",{"g":["\u0003מימרא דרבי יוחנן וכו'\u0004 מ\"ק דף כ\"ח ע\"ב וכ' הב\"י שנראה שמ\"ש הרמב\"ן בסת\"ה בשם רבינו האי שהאבלים מתחילין ואומרים ברוך דיין האמת הוא מטעם זה:","\u0003שם וכתובות דף ס\"ט ע\"ב ומייתי לה מקרא:\u0004 ","מימרא דר' יוחנן מ\"ק דף כ\"ז ע\"ב דכיון שהוא אסור בשאילת שלום בזמן שפוטר המנחמין שותה בראשו סת\"ה בשם הרי\"ץ גיאות:","\u0003מימרא דרבי יוחנן דכ\"ז ע\"ב:\u0004 ","\u0003לשון הרמב\"ם בפרק י\"ג מהלכות אבל (מביאו הטור) ממימרא דרב יהודה שבת דף קנ\"ב ע\"א:\u0004 ","\u0003טור וכמ\"ש הרמב\"ן בסת\"ה:\u0004 ","הגה\"א וכל בו ופי' שתולשין עשבים בצרור עפרם והזריקה על ראשם הוא דרך צער ע\"ד ויזרקו עפר על ראשיהם השמיעה ואח\"כ רוחצים ידיה' ואומרים ידינו לא שפכו את הדם הזה וגו' כפר לעמך ישראל וגו' עד בקרב עמך ישראל וי\"מ שטעם העפר מפני שסופו לעפר והעשב רמז לתחיית המתים שנאמר ויציצו מעיר כעשב הארץ. טור:","\u0003בסי' זה הביאו הב\"י בשם הכל בו כו'\u0004 שהאב יכול למחות וכ\"כ בסוף הי\"ד בשם התשב\"ץ וכו' וכ' שם מיהו נהגו העולם וכו' ולא זכיתי פה לספרו ד\"מ:","וכתב בספר משאת בנימין היכא דאיכא דוחק בקדישים ואינו מגיע לכל אחד קדיש אחד אז נדחה הבן ל' מפני היארצייט שאם לא יאמר היארצייט אותו יום לא יוכל לומר למחר כי עבר היום בטל הקרבן משא\"כ בבן ל' שיוכל לומר למחר וכן ראיתי נוהגים וכ\"ב הרב פי\"ז שחילוק נכון הוא וכ' עוד שם בשמו דלענין ז' אין חילוק בין גדול לקטן ובין תושב לאורח ועיין במנהגים:","\u0003סעיף ה' וע\"ש במ\"ש שם ובסימן שע\"ה סעיף ה' ובמ\"ש שם:\u0004 "],"t":["\u0003לשנות. \u0004 כתב הט\"ז דמהרש\"ל דחה זה מהלכה שאמר הלא גם דוד המע\"ה אמר כן האוכל להשיבו עוד דמשמע אם היה אפשר להשיבו היה עושה. ותמיהני עליו דשאני גבי דוד שאמר למה זה אני צם האוכל להשיבו וגו' וזה אמר דוד כיון שכבר מת לא יועילו הצומות אבל אותן המנחמים שאומרים אל תצער עצמך כי מה לך לעשות אין אומרים על התפלה והצומות כן אלא על הצער שלא יצער עצמו כיון שא\"א בענין אחר דמשמע הא אפשר בענין אחר היה לו לצער על שלא יהיה כרצון האדם וזהו גידוף שמן הראוי להיות כרצון האל יתברך לא כרצון האדם עכ\"ל:","\u0003להתפלל. \u0004 בא\"ח סי' קל\"א כתב דאין אומרים תחנון בבית האבל והיינו כל ז' ימים. וכתב הרוקח שאחר גמר התפלה אומרים תחנון ואין קורין הלל בר\"ח בבית האבל לפי שיש שם אנינות לכך אין אומרים לא המתים יהללו יה משום לועג לרש וכתב הב\"ח דבימים נוראים אם האבל הגון ולא נמצא כמוהו הוא קודם להתפלל אפי' תוך ל' על אביו ואמו וכן נמצא בהג\"ה ולא כיש מקפידים עכ\"ל הט\"ז:","\u0003מעט. \u0004 היינו עכ\"פ ד' אמות וכתב בב\"ה בשם א\"ח דאם נקבר בלילה א\"א לא צדוק הדין ולא קדיש בבה\"ק:","\u0003עפר. \u0004 ואומרים זכור כי עפר אנחנו \u0005(ופה קהלתינו אין נוהגין לתלוש עשבים מפני סכנת בלבול. במס' שמחות מעשה באשה שחלה בנה והקיפו את העזרה מכאן נראה שנהגו להקיף בה\"ק (אגודה)\u0006 ומזה נתפשט המנהג שמודדין הבית חיים סביביו בפתילות ואח\"כ עושין בהן נרות של שעוה ונותנין אותו לבהכ\"נ והכל מנהג טוב):","\u0003במים. \u0004 לרמז דטומאה זו אינה נטהרת אלא בכעין ג' דברים הללו מים ואפר פרה ואזוב. הרמב\"ן:","\u0003נעם. \u0004 כתב מהרש\"ל שקיבל מאביו זקינו שיש לומר ז' פעמים דהיינו בפעם א' עד מלת כי ומלת כי בכלל ובפעם הב' עד כי מלאכיו. ובג' עד כי מלאכיו יצוה. ובד' עד יצוה לך. ובה' עד לך לשמרך. ובו' עד לשמרך בכל. ובז' עד בכל דרכיך ויש בו סודות וכ' בלבוש שגם הוא נהג כן. ט\"ז. ויאמר אתה גבור וכו' שיש בזה סוד הקבלה להבריח כחות הטומאה לבוש וע\"ש:","\u0003נכרי. \u0004 כלומר שאינו אח שלהן אפילו הוא תושב. ש\"ך:","\u0003קודמים. \u0004 כתוב במנהגים דאפי' הבן ז' הוא איש נכרי דוחה את התושב אפי' בן ל' או יא\"צ וכל זה דוקא בשבת שבתוך ז' אבל בחול אינו הולך לבהכ\"נ. אך אם הבן ז' הוא קטן שאינו בר מצוה והולך לבהכ\"נ כל ז' לומר קדיש או מי שאירע לו מיתת אב ואם תוך אותן ז' יאמר קדיש יתום פעם א' ע\"כ. וכ' הש\"ך ונראה דמי שבטלה אבלותו ברגל כגון שעה א' לפני הרגל דבטלה ממנו גזרת ז' או ל' ומ\"מ דין ז' ול' יש לו אפילו בחול כמו בשבת דהרי בדין הולך לבהכ\"נ והנה בתשובת מ\"ב הקשה שדברי המנהגים סותרים זא\"ז דמתחלה כתב יום שמת אב ואם לתושב דוחה את בן ל' מכ\"ש בן י\"ב חדש לתושב כל אותו יום התענית דהיינו תפלת ערבית ושחרית ומנחה. וכן הקדישים של אותו יום שאומרים לפני העמוד אלמא דס\"ל דיא\"צ עדיף. ושוב כתב דבן י\"ב חדש ויא\"צ אורח יש לאורח קדיש א' אבל בן ל' אורח מחלק עמו כל הקדישים והתפלות אלמא דבן ל' עדיף. ותירץ דברישא מיירי שיש הרבה יא\"צ ואיכא דוחק בקדישים ואינו מגיע לכל א' קדיש אז נדחה הבן ל' מפני היא\"צ. והטעם שאם לא יאמר היא\"צ באותו יום קדיש אז עבר היום בטל הקרבן. משא\"כ בבן ל' שיוכל לומר למחר אבל היכא דאיכא רווחא בקדישים כגון בשבת אז הבן ל' עדיף לומר ב' קדישים והיא\"צ קדיש א' עכ\"ל והסכים עמו הט\"ז וכתב שחילוק נכון הוא. אבל הש\"ך השיג עליו וכתב דהדברים כפשטן הם דס\"ל למנהגים דיא\"צ עדיף מבן שלשים ול\"ק מ\"ש בסוף דאורח יא\"צ אין לו רק קדיש א' ובן שלשים חולק עם התושב בן יב\"ח. די\"ל דודאי לענין אורח נגד תושב בן ל' עדיף. משום דמצי התושב לומר ליא\"צ האורח הואיל וזמנך קבוע וידוע קודם לכן שנה תמימה ואתה באת בגבולי די לך בקדיש א' אבל בבן ל' ליכא למימר הכי ולפ\"ז לדידן דקי\"ל דבן ל' עדיף א\"כ אם אירע בן ל' תושב תוך ז' לקטן יש לו ג\"כ קדיש א' והכי נהוג עכ\"ל וכ' עוד בתשו' מ\"ב דאפילו בן ז' א' גדול ותושב ובן ז' אחד קטן ואורח אפ\"ה חולקים בשוה והט\"ז כ' ונ\"ל דמי שמת בשבת או ביו\"ט וא\"א לקברו בו ביום דעכ\"פ יאמר קדיש תיכף אחר המיתה דאין אמירת קדיש תלוי באבילות כלל אבל בחול אין לעשות כן דהא כשהוא אונן פטור מן התפלה עכ\"ל \u0005(ובנה\"כ חולק ע\"ז וכתב כיון דטעם הקדיש הוא שפודה את אביו מגיהנם א\"כ כל זמן שלא נקבר אין בו דין גיהנם וכמדומה שכן נוהגין עכ\"ל)\u0006:","\u0003אחד. \u0004 ליא\"צ אבל לבן יב\"ח אין לו כלום שהתושב בן ל' דוחה את התושב בן יב\"ח בתפלה ובקדיש שלפני העמוד אך בקדיש ובפריסת שמע שעל פתח בה\"כ שניהם שוין בו ויחלקו בגורל ויש מנהגים אחרים בקדיש ובפריסת שמע שעל הפתח ונהרא נהרא ופשטיה ומשמע דאם הוא בשבת דיש ג' קדישים אומר הבן ל' ב' קדישים והיא\"צ קדיש א'. ובמנהגים כתב דיא\"צ תושב דוחה את בן ל' מיהו הלבוש בא\"ח סי' קל\"ג השיג ע\"ז וכתב שאין היא\"צ דוחה את בן ל' מכל וכל אלא די לו בקדיש א' וכן עיקר וכן נהגו עכ\"ל הש\"ך:","\u0003המנהג. \u0004 יש קהלות דנהגו דתושב דוחה את האורח ויש מקומות דשוין הם ומקומות דנהיגי דתושב דוחה האורח מ\"מ פעם ראשונה יש רשות לאורח להתפלל ולומר קדיש יתום פעם א' כ\"כ במנהגים ונ\"ל דהיינו דהוי כמו תושב בן יב\"ח ולפ\"ז היכא דהתושב אין לו קדיש א' כגון שיש כאן בן ל' וכה\"ג גם לאורח אין לו כלום. ש\"ך. וכתוב עוד במנהגים דאם אותו שמת יש לו בנים בעיר אחרת ובאו לשם אינם נקראים תושבים בשביל אביהם שנקבר שם רק אותן הדרים בתוך הקהלה וכל דרי הקהלה נקראים תושבים הן אותן שנותנין מס או משרתי הקהלה ואפי' עניי העיר שיש להם שם דירת קבע כולם נחשבים כתושבים ואם אדם קובע דירתו תוך הקהלה אז משעה שהוא חייב לישא בעול עם דרי הקהלה חשוב תושב אבל לא משעה שגמר פיסוק המס עם ההגמון אע\"ג שצריך ליתן המס להגמון. וכן איפכא מי שעקר דירה מן הקהלה אז משעה שאינו חייב לישא בעול עם דרי הקהילה חשוב כאורח אע\"פ שחייב עדיין ליתן המס להגמון ואם יש לבעל הבית מלמד או שמש המושכר לזמן והוא פנוי שאין לו אשה ובנים אז גם הוא נקרא תושב אבל אם יש לו אשה ובנים במקום א' אז דינו כאיש נכרי ואם בעה\"ב מגדל בביתו יתום אפי' בשכר ואין לו אב או אם במ\"א אז נקרא תושב אבל אם יש לו אב או אם אינו נקרא תושב אפי' אם מגדלו בתורת צדקה ומכ\"ש אם הוא אצלו בשכר ע\"כ ונראה דנערים ובחורים הלומדים בישיבה אפי' יש להם אב או אם במקום אחר יש להם דין תושב ואפילו בעה\"ב שלומד בישיבה אע\"פ שיש לו אשה ובנים במקום אחר ונותן מס במקום שאשתו ובניו שם מ\"מ דין תושב יש לו במקום שהוא לומד והכי נהוג. ש\"ך. וכתוב עוד במנהגים דהיכא ששניהם בני ל' או שניהם יא\"צ או בני י\"ב חודש נדחה האורח לגמרי מלהתפלל ולומר קדיש לפני העמוד אך בפריסת שמע וקדיש על הפתח שניהם שוין ויחלקו בגורל ואם האורח והתושב שניהם בני ז' יחלקו בגורל כי לענין שבעה אין שום עילוי לתושב על האורח עכ\"ל:","\u0003רק. \u0004 ע\"ל סי' ר\"מ ס\"ט מה שמחלק הט\"ז שם דצריך לכתוב הכ\"מ כל י\"ב חדש ומאי שנא מהכא לענין קדיש ע\"ש:","\u0003שנהרג. \u0004 דוקא נהרג דאז יש לו כפרה ע״י ההריגה אבל מת על מטתו לא וכ״מ לעיל סי' ש״מ לענין אבילות וחילוק זה בין מת או נהרג הוא בש״ס פ' נגמר הדין (סנהדרין דף מ״ז) עכ״ל הט״ז:"],"r":["\u0003אין אבל כו'. \u0004גמרא שם:","\u0003לא יאמר כו'. \u0004גמ' רפ\"ג דברכות:","\u0003ואל יאמר כו'. \u0004גמ' פ\"ד דב\"ק \u0005(ל\"ח א'):\u0006","\u0003(ליקוט) ואח\"כ תולשין כו'. \u0004עבה\"ג \u0005(וי\"מ כו') \u0006וכמ\"ש בסוטה \u0005(בירושלמי פ\"ב דסוטה ומ\"ר פ' נשא) \u0006ועוד טעם אחר שהוא רמז לטהרת הטומאה במים ואפר ואזוב וזה טעם יפה. תה\"א (ע\"כ):","\u0003(ליקוט) וי\"א שיושבין ז\"פ כו'. \u0004נוהגין כן ע\"פ הסברא שכתב רשב\"ם בב\"ב ק' ב' בד\"ה משבעה כו' וראיתי כתוב כו' אבל הוא סתר שם דבריו ע\"ש (ע\"כ):","\u0003(ליקוט) ונמצא במדרשות. \u0004תנחומא פ' נח ומסכת כלה מעשה בר\"ע כו' והביאו במנורת המאור נר א' כלל א' חלק ב' פרק א'. אבל אינו בתנחומא ומס' כלה שלנו כידוע שחסר מהם בדפוס הרבה ועוד בתד\"א סא\"ז סוף פט\"ז מעשה בריב\"ז ועוד בז\"ח רות כ\"ה ד' ר' זמיראה כו' ארחב\"א כה\"ג אירע לר\"ע (ע\"כ):","\u0003מצוה להתענות כו'. \u0004כן משמע לכאורה ברפ\"ג דשבועות ביום שמת כו' אבל ראיתי למפרשים שפירשו אותו היום דוקא וע\"ל שע\"ח ס\"ד:","\u0003י\"א דמומר כו'. \u0004ע\"ל סי' ש\"מ ס\"ה:"]}],["הָעֲבָדִים וְהַשְּׁפָחוֹת, אֵין עוֹמְדִין עֲלֵיהֶם בְּשׁוּרָה, וְאֵין אוֹמְרִים עֲלֵיהֶם תַּנְחוּמֵי אֲבֵלִים, אֶלָא אוֹמְרִים לוֹ: הַמָּקוֹם יְמַלֵא חֶסְרוֹנְךָ, כְּשֵׁם שֶׁאוֹמְרִים לְאָדָם עַל שׁוֹרוֹ וַחֲמוֹרוֹ.\nאָבֵל מְנֻדֶּה, אֵין מַבְרִין אוֹתוֹ \u0010y0\u0011 וְאֵין אוֹמְרִים לוֹ תַּנְחוּמֵי אֲבֵלִים. \u0010y1\u0011\nמְנֻדֶּה שֶׁמֵּת, מְנַחֲמִים אֲבֵלָיו.",["\u0003ואין אומרים כו'. \u0004דכל דבר שהוא משום כבוד לחיים אין עושין לאבל שהוא מנודה:","\u0003מנודה כו'. \u0004עיין לעיל סימן שמ\"ה ס\"ד:"],[],"\u0010g0\u0011 הָעֲבָדִים וְהַשְּׁפָחוֹת, אֵין עוֹמְדִין עֲלֵיהֶם בְּשׁוּרָה, וְאֵין אוֹמְרִים עֲלֵיהֶם תַּנְחוּמֵי אֲבֵלִים, אֶלָא אוֹמְרִים לוֹ: הַמָּקוֹם יְמַלֵא חֶסְרוֹנְךָ, כְּשֵׁם שֶׁאוֹמְרִים לְאָדָם עַל שׁוֹרוֹ וַחֲמוֹרוֹ. \u0010g1\u0011\nאָבֵל מְנֻדֶּה, אֵין \u0010t0\u0011 מַבְרִין אוֹתוֹ \u0010y0\u0011 וְאֵין אוֹמְרִים לוֹ תַּנְחוּמֵי אֲבֵלִים. \u0010y1\u0011 \u0010g2\u0011 \u0010r0\u0011\nמְנֻדֶּה שֶׁמֵּת, מְנַחֲמִים אֲבֵלָיו.",{"g":["\u0003ברייתא ברכות דף ט\"ז ע\"ב:\u0004 ","\u0003טור בשם הרמב\"ן בסת\"ה מטעם דאסור לישב בד' אמותיו:\u0004 ","שם:"],"t":["\u0003מברין. \u0004 דכל דבר שהוא משום כבוד לחיים אין עושין לאבל שהוא מנודה. וע\"ל סי' שמ\"ה ס\"ד. עכ\"ל הש\"ך \u0005(ועיין בבה\"י)\u0006:"],"r":["\u0003מנודה שמת כו'. \u0004עיין לעיל סי' שמ\"ה ס\"א:"]}],["אָבֵל \u0010c0\u0011 אָסוּר לֶאֱכֹל מִשֶּׁלוֹ בִּסְעֻדָּה רִאשׁוֹנָה, אֲבָל בַּשְּׁנִיָּה מֻתָּר, אֲפִלוּ בְּיוֹם רִאשׁוֹן. וּמִצְוָה עַל שְׁכֵנָיו \u0010y0\u0011 שֶׁיַּאֲכִילוּהוּ מִשֶׁלָהֶם, כְּדֵי שֶׁלֹּא יֹאכַל מִשֶּׁלוֹ. וְיָכוֹל אֶחָד לְהַאֲכִיל אֶת חֲבֵרוֹ בִּימֵי אֶבְלוֹ, וְהוּא יַחֲזֹר גַם כֵּן וְיַאֲכִילֶנּוּ \u0010y1\u0011 בִּימֵי אֶבְלוֹ, וּבִלְבַד שֶׁלֹּא יַתְנוּ בִּתְחִלָה.\nאִשָּׁה שֶׁאֵרְעָהּ אֵבֶל, אֵין לַאֲנָשִׁים לְהַבְרוֹתָהּ; אֲבָל נָשִׁים מַבְרִין \u0010y2\u0011 אוֹתָהּ. וְאִשָּׁה נְשׂוּאָה שֶׁאֵרְעָהּ אֵבֶל, אֵינָהּ יְכוֹלָה לֶאֱכֹל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעֲלָהּ. וְכֵן מִי שֶׁיֵּשׁ לוֹ סוֹפֵר אוֹ שָׂכִיר, אִם אוֹכֵל בִּשְׂכָרוֹ וְאֵרְעוֹ אֵבֶל, לֹא יֹאכַל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעַל הַבַּיִת. אֲבָל מִי שֶׁזָּן עָנִי אוֹ יָתוֹם אוֹ לִבְנוֹ וּבִתּוֹ, בְּלֹא תְּנַאי, וְאֶרְעָם אֵבֶל, יְכוֹלִים לֶאֱכֹל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעַל הַבַּיִת. \u0010y3\u0011\nאִם רָצָה הָאָבֵל שֶׁלֹּא לֶאֱכֹל בַּיּוֹם הָרִאשׁוֹן, \u0010y4\u0011 מֻתָּר לֶאֱכֹל מִשֶּׁלוֹ אֲפִלוּ סְעֻדָּה רִאשׁוֹנָה. \u0005הַגָּה: וְכֵן אִם לֹא הִבְרוּהוּ בְּיוֹם רִאשׁוֹן שֶׁנִּמְשַׁךְ עַד הַלַּיְלָה, מֻתָּר לֶאֱכֹל בַּלַּיְלָה מִשֶּׁלּוֹ, וְאֵין צָרִיךְ הַבְרָאָה (טוּר בְּשֵׁם רֹב הַפּוֹסְקִים)\u0006.\nהָיוּ נוֹהֲגִים לְהִתְעַנּוֹת בְּיוֹם מִיתַת הַחֲכָמִים.\nמִי שֶׁנִּקְבַּר בְּעֶרֶב שַׁבָּת סָמוּךְ לַחֲשֵׁכָה \u0010y5\u0011 קֹדֶם בֵּין הַשְּׁמָשׁוֹת, יֵשׁ מִי שֶׁאוֹמֵר שֶׁמַּבְרִין אוֹתוֹ אָז; וְלִי נִרְאֶה דְּכֵיוָן שֶׁאֵינוֹ חוֹבָה טוֹב שֶׁלֹּא לְהַבְרוֹתוֹ אָז, מִפְּנֵי כְּבוֹד הַשַּׁבָּת, וְכֵן נוֹהֲגִין.\nאֵין מַבְרִין עַל הַקָטָן אֶלָא אִם כֵּן הוּא בֶּן שְׁלשִׁים יוֹם שְׁלֵמִים, אוֹ קִים לֵהּ בֵּהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו.\nמַרְבִּיצִין וּמְכַבְּדִין בְּבֵית הָאָבֵל, וּמְדִיחִין קְעָרוֹת, כּוֹסוֹת וּצְלוֹחִיּוֹת וְקִיתוֹנוֹת, וְאֵין מְבִיאִין שָׁם לֹא בְּשָׂמִים וְלֹא מֻגְמָר, אֲבָל מְבִיאִים אוֹתָם \u0010c1\u0011 בַּבַּיִת שֶׁהַמֵּת שָׁם וְאֵין מְבָרְכִים עֲלֵיהֶם; וְאֵין אוֹמְרִים שְׁמוּעָה וְאַגָדָה בְּבֵית הָאָבֵל, אֶלָא יוֹשְׁבִין וְדוֹמְמִים. \u0010y6\u0011\nכֵּיוָן שֶׁנִּקְבַּר הַמֵּת, מֻתָּר לֶאֱכֹל בָּשָׂר וְלִשְׁתּוֹת יַיִן מְעַט בְּתוֹךְ הַסְעֻדָּה, כְּדֵי לִשְׁרוֹת אֲכִילָה שֶׁבְּמֵעָיו אֲבָל לֹא לִרְווֹת.\nמָקוֹם שֶׁנָּהֲגוּ לְהַבְרוֹת בְּבָשָׂר וְיַיִן וּמִינֵי מַטְעַמִּים עוֹשִׂים; וּמַבְרִין \u0010y7\u0011 תְּחִלָה בְּבֵיצִים אוֹ בְּתַבְשִׁיל שֶׁל עֲדָשִׁים, זֵכֶר לַאֲבֵלוּת, וְאַחַר כָּךְ אוֹכְלִים כָּל צָרְכָּם. \u0010y8\u0011\nאֵין לֶאֱכֹל עִם הָאָבֵל כָּל כָּךְ בְּנֵי אָדָם שֶׁיִּתְחַלְקוּ לִשְׁנֵי מְקוֹמוֹת. \u0010y9\u0011\nהֵיכָא שֶׁצָּרִיךְ לִמְנוֹת שִׁבְעָה אַחַר הָרֶגֶל, וְכֵן \u0010y10\u0011 אִם שָׁמַע שְׁמוּעָה בְּשַׁבָּת, צָרִיךְ לְהַבְרוֹתוֹ הַבְרָאָה רִאשׁוֹנָה שֶׁבִּימֵי אֲבֵלוּת. \u0005וְיֵשׁ אוֹמְרִים שֶׁכֵּיוָן שֶׁנִּדְחָה יוֹם רִאשׁוֹן אֵין מַבְרִין אוֹתוֹ, וְכֵן נוֹהֲגִים (בְּמָרְדְּכַי במ\"ק בְּשֵׁם י\"א ונ\"י)\u0006, וַאֲפִלּוּ הֵיכָא דְּעוֹלֶה לוֹ לְמִנְיַן ז' כְּגוֹן בִּמְקוֹמוֹת שֶׁעוֹשִׂין שְׁנֵי יָמִים, שֶׁשֵּׁנִי עוֹלֶה.\nאֵין מַבְרִין עַל שְׁמוּעָה רְחוֹקָה.\nפָּרֵיס \u0005(פֵּרוּשׁ בּוֹצֵעַ לֶחֶם לְבָרֵךְ הַמּוֹצִיא)\u0006 מְנַחֵם גָדוֹל דִּבְּהוֹן, וּבְשַׁבָּת פָּרֵיס כְּאוֹרְחֵיהּ.",["\u0003שיאכילוהו משלהם. \u0004כלומר הסעודה ראשונה מצוה שיאכילוהו משלהם אבל בסעודה שניה אין כאן מצוה שהרי יכול לאכול משלו:","\u0003בימי אבלו. \u0004פירוש אע\"פ ששניהם אבלים:","\u0003ואשה נשואה כו'. \u0004דכיון שחייב במזונותיה כמשלה דמי:","\u0003אם רצה כו'. \u0004ומשמע דאם רצה האבל להתענות באותו היום מותר וכ\"פ הב\"ח:","\u0003מותר לאכול. \u0004ביום שני או בלילה שאחר יום ראשון משלו אפילו סעודה ראשונה:","\u0003יש מי שאומר כו'. \u0004הוא המרדכי (ואגודה) שהביא בב\"י והיינו מ\"ש בפרישה וב\"י לא כ' כן ואוסר אף בע\"ש והיינו דעתו כאן בש\"ע ודלא כהגהת דרישה שכ' ולא ידעתי למה כתב א\"א ז\"ל וב\"י לא כ\"כ ע\"ש:","\u0003כיון שנקבר כו'. \u0004אבל קודם קבורה אסור בבשר ויין דהוי אונן וכדלעיל סימן שמ\"א:","\u0003בביצים כו'. \u0004שאין להם פה כמו אבל שאין לו פה:","\u0003אין לאכול כו'. \u0004דהוי כסעודת מריעות שיש בה שמחה:","\u0003היכא כו'. \u0004כלומר ואפי' במקום שעושים ב' י\"ט שהשני עולה למנין ז' וכמו שנתבאר באו\"ח סי' תקמ\"ח ס\"ב ולקמן סי' שנ\"ט (סד\"א) [סי\"ג] דיש להברותו אח\"כ דהא לא נדחה דה\"ל להברות ביום ז' שהרי שייך ביה אבילותה כיון דעולה למנין ז' קמ\"ל דאמרי' בזה ג\"כ כיון דנדחה נדחה ואין צריך הבראה:","\u0003אם שמע שמועה בשבת. \u0004צריך עיון דבד\"מ ס\"ס זה פסק כב\"י שכ' בסי' שצ\"ג דמברין בשבת וכתב שכן פשט המנהג בכל העולם להברות בשבת ולא נשמע בעולם שום פוצה פה ומצפצף:"],["\u0003אסור לאכול משלו. \u0004נראה דאם לא שלחו לו או שהוא יחידי בעיר אין חייב לצער עצמו שלא לאכול כלל דמשום הכי כתב כאן הטור ושלחן ערוך דמצוה על שכיניו שיאכילוהו שלא יאכל משלו שזהו מיותר לכאורה אלא הכוונה דעיקר מצוה על השכנים שלא יגרמו שיצטרך לאכול משלו דאם לא ישלחו לו יהיה לו היתר לאכול משלו ע\"י ההכרח:","\u0003בבית שהמת שם. \u0004להעביר הסרחון:"],"\u0010g0\u0011 אָבֵל \u0010c0\u0011 \u0010t0\u0011 אָסוּר לֶאֱכֹל מִשֶּׁלוֹ בִּסְעֻדָּה רִאשׁוֹנָה, \u0010r0\u0011 אֲבָל בַּשְּׁנִיָּה \u0010g1\u0011 מֻתָּר, אֲפִלוּ בְּיוֹם רִאשׁוֹן. \u0010g2\u0011 וּמִצְוָה עַל שְׁכֵנָיו \u0010y0\u0011 שֶׁיַּאֲכִילוּהוּ מִשֶׁלָהֶם, כְּדֵי שֶׁלֹּא יֹאכַל מִשֶּׁלוֹ. \u0010g3\u0011 וְיָכוֹל אֶחָד לְהַאֲכִיל אֶת חֲבֵרוֹ בִּימֵי אֶבְלוֹ, וְהוּא \u0010t1\u0011 יַחֲזֹר גַם כֵּן וְיַאֲכִילֶנּוּ \u0010y1\u0011 בִּימֵי אֶבְלוֹ, \u0010g4\u0011 וּבִלְבַד שֶׁלֹּא יַתְנוּ \u0010g5\u0011 \u0010r1\u0011 בִּתְחִלָה.\nאִשָּׁה שֶׁאֵרְעָהּ אֵבֶל, אֵין לַאֲנָשִׁים לְהַבְרוֹתָהּ; \u0010g6\u0011 \u0010r2\u0011 אֲבָל נָשִׁים מַבְרִין \u0010y2\u0011 \u0010g7\u0011 אוֹתָהּ. וְאִשָּׁה נְשׂוּאָה שֶׁאֵרְעָהּ אֵבֶל, אֵינָהּ יְכוֹלָה לֶאֱכֹל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעֲלָהּ. וְכֵן מִי שֶׁיֵּשׁ לוֹ סוֹפֵר אוֹ שָׂכִיר, אִם אוֹכֵל בִּשְׂכָרוֹ וְאֵרְעוֹ אֵבֶל, לֹא יֹאכַל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעַל הַבַּיִת. אֲבָל מִי שֶׁזָּן עָנִי אוֹ יָתוֹם אוֹ לִבְנוֹ וּבִתּוֹ, בְּלֹא תְּנַאי, וְאֶרְעָם אֵבֶל, יְכוֹלִים לֶאֱכֹל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעַל הַבַּיִת. \u0010y3\u0011 \u0010g8\u0011\nאִם רָצָה הָאָבֵל שֶׁלֹּא \u0010t2\u0011 לֶאֱכֹל בַּיּוֹם הָרִאשׁוֹן, \u0010y4\u0011 מֻתָּר לֶאֱכֹל מִשֶּׁלוֹ אֲפִלוּ סְעֻדָּה רִאשׁוֹנָה. \u0005הַגָּה: \u0010r3\u0011 וְכֵן אִם לֹא הִבְרוּהוּ בְּיוֹם רִאשׁוֹן שֶׁנִּמְשַׁךְ עַד הַלַּיְלָה, מֻתָּר לֶאֱכֹל בַּלַּיְלָה מִשֶּׁלּוֹ, וְאֵין צָרִיךְ הַבְרָאָה (טוּר בְּשֵׁם רֹב הַפּוֹסְקִים)\u0006. \u0010g9\u0011 \u0010r4\u0011\nהָיוּ נוֹהֲגִים לְהִתְעַנּוֹת בְּיוֹם מִיתַת הַחֲכָמִים.\nמִי שֶׁנִּקְבַּר בְּעֶרֶב שַׁבָּת סָמוּךְ לַחֲשֵׁכָה \u0010y5\u0011 \u0010g10\u0011 \u0010r5\u0011 קֹדֶם בֵּין הַשְּׁמָשׁוֹת, יֵשׁ מִי שֶׁאוֹמֵר שֶׁמַּבְרִין אוֹתוֹ אָז; \u0010r6\u0011 וְלִי נִרְאֶה דְּכֵיוָן שֶׁאֵינוֹ חוֹבָה \u0010r7\u0011 טוֹב שֶׁלֹּא לְהַבְרוֹתוֹ אָז, מִפְּנֵי כְּבוֹד הַשַּׁבָּת, וְכֵן נוֹהֲגִין. \u0010g11\u0011\nאֵין מַבְרִין עַל הַקָטָן אֶלָא אִם כֵּן הוּא בֶּן שְׁלשִׁים יוֹם שְׁלֵמִים, אוֹ קִים לֵהּ בֵּהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו. \u0010g12\u0011\nמַרְבִּיצִין וּמְכַבְּדִין בְּבֵית הָאָבֵל, וּמְדִיחִין קְעָרוֹת, כּוֹסוֹת וּצְלוֹחִיּוֹת וְקִיתוֹנוֹת, וְאֵין מְבִיאִין שָׁם לֹא בְּשָׂמִים וְלֹא \u0010g13\u0011 מֻגְמָר, אֲבָל מְבִיאִים אוֹתָם \u0010c1\u0011 בַּבַּיִת \u0010t3\u0011 שֶׁהַמֵּת שָׁם וְאֵין מְבָרְכִים עֲלֵיהֶם; \u0010g14\u0011 \u0010r8\u0011 וְאֵין אוֹמְרִים שְׁמוּעָה וְאַגָדָה בְּבֵית הָאָבֵל, אֶלָא יוֹשְׁבִין וְדוֹמְמִים. \u0010y6\u0011 \u0010g15\u0011 \u0010r9\u0011\nכֵּיוָן שֶׁנִּקְבַּר הַמֵּת, מֻתָּר לֶאֱכֹל בָּשָׂר וְלִשְׁתּוֹת יַיִן \u0010r10\u0011 מְעַט בְּתוֹךְ הַסְעֻדָּה, כְּדֵי לִשְׁרוֹת אֲכִילָה שֶׁבְּמֵעָיו אֲבָל לֹא לִרְווֹת. \u0010g16\u0011 \u0010r11\u0011\nמָקוֹם שֶׁנָּהֲגוּ לְהַבְרוֹת בְּבָשָׂר וְיַיִן וּמִינֵי מַטְעַמִּים עוֹשִׂים; \u0010r12\u0011 וּמַבְרִין \u0010y7\u0011 תְּחִלָה בְּבֵיצִים אוֹ בְּתַבְשִׁיל שֶׁל עֲדָשִׁים, זֵכֶר לַאֲבֵלוּת, וְאַחַר כָּךְ אוֹכְלִים כָּל צָרְכָּם. \u0010y8\u0011 \u0010g17\u0011 \u0010r13\u0011\nאֵין לֶאֱכֹל עִם הָאָבֵל כָּל כָּךְ בְּנֵי אָדָם \u0010t4\u0011 שֶׁיִּתְחַלְקוּ לִשְׁנֵי מְקוֹמוֹת. \u0010y9\u0011 \u0010g18\u0011 \u0010r14\u0011\nהֵיכָא שֶׁצָּרִיךְ לִמְנוֹת שִׁבְעָה אַחַר הָרֶגֶל, וְכֵן \u0010y10\u0011 אִם שָׁמַע שְׁמוּעָה \u0010t5\u0011 בְּשַׁבָּת, צָרִיךְ לְהַבְרוֹתוֹ הַבְרָאָה רִאשׁוֹנָה שֶׁבִּימֵי אֲבֵלוּת. \u0005וְיֵשׁ אוֹמְרִים שֶׁכֵּיוָן שֶׁנִּדְחָה יוֹם רִאשׁוֹן אֵין מַבְרִין אוֹתוֹ, וְכֵן נוֹהֲגִים (בְּמָרְדְּכַי במ\"ק בְּשֵׁם י\"א ונ\"י)\u0006, וַאֲפִלּוּ הֵיכָא דְּעוֹלֶה לוֹ לְמִנְיַן ז' כְּגוֹן בִּמְקוֹמוֹת שֶׁעוֹשִׂין שְׁנֵי יָמִים, שֶׁשֵּׁנִי עוֹלֶה. \u0010g19\u0011 \u0010r15\u0011\nאֵין מַבְרִין עַל שְׁמוּעָה רְחוֹקָה. \u0010g20\u0011\nפָּרֵיס \u0005(פֵּרוּשׁ בּוֹצֵעַ לֶחֶם לְבָרֵךְ הַמּוֹצִיא)\u0006 מְנַחֵם גָדוֹל דִּבְּהוֹן, וּבְשַׁבָּת פָּרֵיס כְּאוֹרְחֵיהּ.",{"g":["\u0003מימרא דרב יהודה אמר רב מ\"ק דף כ\"ז ע\"ב:\u0004 ","כפירוש הרא\"ש דיום ראשון דקאמר רב יהודה הוא סעודה ראשונה וכיוצא בזה בפסחים דף ל\"ז ע\"א מימרא דריב\"ל יומא קמא וכו' וכ\"כ הגהמי\"י בשם סמ\"ג דנקטינן באבל הלכה כדברי המיקל:","\u0003ירושלמי תבא מאירה לשכניו שהצריכוהו לאכול משלו והביאו הרא\"ש שם:\u0004 ","\u0003מהא דרבה ורב יוסף מחלפי סעודתייהו להדדי שם בבבלי:\u0004 ","\u0003הרא\"ש שם.\u0004 ","\u0003ברייתא באבל רבתי משום הרגל עבירה:\u0004 ","\u0003הרא\"ש סוף מ\"ק בשם הר\"מ:\u0004 ","\u0003גם זה שם וכן כתבו ש\"פ:\u0004 ","\u0003ירושל' עובדא דרבי זעירא:\u0004 ","\u0003ג\"ז שם עובדא דרבי אבהו:\u0004 ","מרדכי בסוף מ\"ק (והגהמי\"י פרק י\"ב):","\u0003עובדא דרב דימי בר יוסף שבת דף קל\"ו ע\"א:\u0004 ","\u0003ברייתא מ\"ק דף כ\"ז ע\"א:\u0004 ","\u0003אוקימתא דגמ' שם מבריית' דבר קפרא:\u0004 ","\u0003ברייתא שם:\u0004 [דף כ\"ג ע\"א]:","\u0003לשון הרמב\"ם בפ\"ד מהלכות אבל דין ו':\u0004 ","\u0003טור בשם הרמב\"ן בס\"ה:\u0004 ","\u0003הגהמי\"י פ' י\"ב מהירושלמי:\u0004 ","\u0003מרדכי במ\"ק:\u0004 ","\u0003מרדכי ונ\"י במ\"ק:\u0004 ","הגהת מיי' פ\"ד בשם סמ\"ג בשם הירושלמי פ\"ג דברכות ופ\"ק דמ\"ק:\n(°) כתב רבינו ירוחם שנהגו לאכול משל אחרים כל שבעה מפני עניי ישראל שאינם יכולים לעשות מלאכה ולא יתביישו שאף לעשירים עושים כן ע\"כ וכן ראיתי פה מנהג קהל קדוש ספרדיים יצ\"ו:"],"t":["\u0003אסור. \u0004כתב הט\"ז נראה דאם לא שלחו לו או שהוא יחידי בעיר אינו חייב לצער עצמו שלא לאכול כלל ומש\"ה כתב המחבר דמצוה על שכניו שיאכילוהו שלא יאכל משלו דלכאורה הוא יתור לשון אלא הכוונה דעיקר מצוה על השכנים שלא יגרמו שיצטרך לאכול משלו עד כאן לשונו:","\u0003יחזור. \u0004 פי אע\"פ ששניהם אבלים. ש\"ך:","\u0003לאכול. \u0004 ומשמע דאם רצה האבל להתענות באותו היום מותר וכ\"כ הב\"ח עכ\"ל הש\"ך \u0005(ובהג\"א פרק אלו מגלחין כתב בשם א\"ז אין מניחים את האבל להתענות ביום ראשון אלא מאכילין ומשקין אותו אפילו בתענית שלפני ראש השנה לא הניח הרשב\"ם להתענות ביום הקבורה ע\"כ. ב\"י ופוסקים. ומכל מקום שמעינן מהא אפילו למאי דפסקינן שמותר להתענות אם רצה האבל שלא להתענות בימים שלפני ראש השנה או בתעניות הדומים לזה הרשות בידו ואם מת בחצי היום וכבר קבל עליו התענית ממתין לעת ערב עד אחר התפלה ולא משלים לגמרי)\u0006:","\u0003שהמת. \u0004 כדי להעביר הסרחון:","\u0003שיתחלקו. \u0004 דהוי כסעודת מריעות ושיש בה שמחה. ש\"ך:","\u0003בשבת. \u0004 כתב הש\"ך צ\"ע דלקמן ס\"ס שצ\"ט פסק הב\"י דמברין בשבת וכתב שכן פשוט המנהג בכל העולם להברות בשבת ולא נשמע מעולם שום פוצה פה ומצפצף עכ\"ל \u0005(ואפשר שזהו לפי יש נוהגין שמברין כל ז' כפי מנהג הספרדיים בהרבה מקומות לפי שאין האבל מכין עצמו דבר מכח טרדת אבלותו. וגם כדי שלא לבייש מי שאין לו לזון עצמו ז' ימים ימי בטולו ממלאכתו. וכ\"כ רבינו ירוחם. וע\"כ גם בשבת מברין שהאבלים סומכין על זה ובלא זה אין לו מה יאכל בשבת. אך לפי הנוהגין שאין מברין אלא סעודה הראשונה באיזה לחם וביצים מעולם לא שמענו שעושין זה בשבת כנ\"ל)\u0006: \u0003.. \u0004"],"r":["\u0003(ליקוט) אבל בשניה כו'. \u0004אבל תוס' לא כתבו כן ע\"ש כ' א' ד\"ה שכבר כו' ושם כ\"ז ב' ד\"ה יום כו' (ע\"כ):","\u0003(ליקוט) אשה שאירעה כו'. \u0004א\"ר פי\"א (ע\"כ):","\u0003אבל נשים כו'. \u0004עבמ\"ר פ' ויקרא פ' ו' ובאיכה רבתי על פ' ידי נשים רחמניות כו':","\u0003וכן אם כו'. \u0004נלמד מהנ\"ל:","\u0003(ליקוט) היו כו'. \u0004ירושלמי \u0005(פ\"ג דמ\"ק) \u0006הרואה ת\"ח שמת כרואה ס\"ת שנשרף א\"ר אבהו יבא עלי אם טעמתי כלום כל אותו היום ר' יונה הוה שמע דדמך בר בריה דר\"י אע\"ג דאכל גבינה ושתא מיא אסקיה צום כל ההוא יומא והביאו הרא\"ש בפ\"ק דתענית וכן בגמ' רפ\"ג דשבועות כיום שמת כו' (ע\"כ):","\u0003יש מי כו'. \u0004דקי\"ל כר' יוסי בע\"ש ועי\"ט כמ\"ש בפ' בתרא דפסחים \u0005(צ\"ט ב'):\u0006","\u0003ול\"נ כו'. \u0004כנ\"ל ס\"ג:","\u0003טוב כו'. \u0004עבא\"ה סי' רמ\"ט ס\"ב:","\u0003וא\"א כו'. \u0004כת\"ק שם:","\u0003כיון כו'. \u0004תענית י\"ג ב' נדרים נ\"ו א':","\u0003מעט בתוך הסעודה. \u0004פ\"ק דכתובות \u0005(ח' ב') \u0006התחילו כו' חזרו הדבר ליושנה ופי' בתה\"א משום דבתוך הסעודה אינו משכר כמ\"ש בירושלמי פ' בתרא דפסחים והביאו הרא\"ש וש\"פ שם וז\"ש אבל לא לרוות:","\u0003מקום כו'. \u0004מ\"ש והביאו תה\"א והטור וכן בגמ' דנדרים הנ\"ל:\n\u0003(ליקוט) מקום כו'. \u0004פי\"ד דא\"ר הכל מעלין כו' (ע\"כ):\n\u0003(ליקוט) מקום כו'. \u0004לשון הרמב\"ן בשם א\"ר מקום שנהגו לנחם אבלים בביצים ועדשים מאכילין מקום שנהגו בבשר ויין מאכילין וירושלמי פ\"ג דברכות כד דמך ר' יוסי קבל ר\"ח בר בא אבלויי ואוכלין בשר ואשקינן חמר כי דמך ר\"ח בר בא קבל ר\"ש בר ר\"י אבלוי ואוכלון טלפחין \u0005(כ\"ה בתה\"א ולעיל סי' רמ\"ב ס\"ק ס\"ו הביא רבינו גירסא שלנו) \u0006מימר כמא דו מנהגא ר\"ז מידמך פקיד ומר לא תקבלון עלוי יומא דין אכילה ולמחר מדידיה וז\"ש בס\"ג אם רצה כו' (ע\"כ):","\u0003ומברין כו'. \u0004ספ\"ק דב\"ב:","\u0003אין לאכול כו'. \u0004ירושלמי פ\"ג דמ\"ק והביאו הג\"מ פי\"ב הות מגורתיה זעירא וקרובוי בעי מיכל גביה מהו דיעלון ויתבין פלגא ופלגא מן לבד א\"ל יעלון פלגא יומא דין ופלגא למחר:\n\u0003(ליקוט) אין לאכול כו'. \u0004דכל בני המשפחה והעוסקין בהספד דינם לברות עמו ממ\"ש בחה\"מ אין מברין אלא קרוביו של מת (מתני' כ\"ד ב') ובחכם (כ\"ה א' ושבת ק\"ה ב') הכל מברין עליו כו'. תה\"א (ע\"כ):","\u0003(ליקוט) היכא כו'. \u0004עתוס' כ' א' ד\"ה שכבר כו' בשם רש\"י ע\"ש (ע\"כ):\n\u0003(ליקוט) היכא כו'. \u0004היינו שמת בי\"ט האחרון אבל בלא\"ה מברין בח\"ה כמ\"ש במתני' כ\"ד ב' וכמש\"ל סי' ת\"א ס\"ד ובא\"ח סי' תקמ\"ז (ע\"כ):","\u0003(ליקוט) אין כו'. \u0004וכ\"ה בסי' ת\"ב ס\"ג. תוס' כ\"ד ב' ד\"ה אלא כו' ע\"ש (ע\"כ):"]}],["כְּשֶׁמְּבָרְכִין בִּרְכַּת הַמָּזוֹן בְּבֵית הָאָבֵל, אוֹמֵר בְּרָכָה רְבִיעִית כְּנֻסַח זוֹ: בא\"י אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הָאֵל אָבִינוּ מַלְכֵּנוּ בּוֹרְאֵנוּ גוֹאֲלֵנוּ \u0010y0\u0011 קְדוֹשֵׁנוּ קְדוֹשׁ יַעֲקֹב הַמֶּלֶךְ הַחַי הַטּוֹב וְהַמֵּטִיב אֵל אֱמֶת דַּיַּן אֱמֶת שׁוֹפֵט בְּצֶדֶק וְכו'. \u0005הַגָּה: לוֹקֵחַ נְפָשׁוֹת בְּמִשְׁפָּט שַׁלִּיט בְּעוֹלָמוֹ לַעֲשׂוֹת בּוֹ כִּרְצוֹנוֹ כִּי כָּל דְּרָכָיו בְּמִשְׁפָּט וַאֲנַחְנוּ עַמּוֹ וַעֲבָדָיו וּבַכֹּל אֲנַחְנוּ חַיָּבִים לְהוֹדוֹת לוֹ וּלְבָרְכוֹ גּוֹדֵר פִּרְצוֹת יִשְׂרָאֵל הוּא יִגְדֹּר הַפִּרְצָה הַזֹּאת מֵעָלֵינוּ \u0010y1\u0011 וּמֵעַל אָבֵל זֶה לְחַיִּים וּלְשָׁלוֹם (טוּר)\u0006.\nיֵשׁ מוֹסִיפִים בִּבְרָכָה שְׁלִישִׁית: נַחֵם ה' אֱלֹהֵינוּ אֶת אֲבֵלֵי יְרוּשָׁלַיִם וְאֶת הָאֲבֵלִים הַמִתְאַבְּלִים בָּאֵבֶל הַזֶּה, נַחֲמֵם מֵאֶבְלָם וְשַׂמְּחֵם מִיגוֹנָם, כָּאָמוּר: \u0010y2\u0011 כְּאִישׁ אֲשֶׁר אִמּוֹ תְּנַחֲמֶנּוּ \u0005(יְשַׁעְיָה סו, יג)\u0006 וְכו' בא\"י \u0010y3\u0011 מְנַחֵם צִיּוֹן בְּבִנְיַן יְרוּשָׁלַיִם.\nיֵשׁ אוֹמְרִים בְּבִרְכַּת זִמּוּן: נְבָרֵךְ מְנַחֵם אֲבֵלִים שֶׁאָכַלְנוּ מִשֶּׁלוֹ.\nבְּשַׁבָּת, אִם בֵּרַךְ בְּיָחִיד, אוֹ בְּג' אֲבֵלִים, מְבָרֵךְ כְּדֶרֶךְ שֶׁמְּבָרֵךְ בְּחוֹל, דְּצִנְעָא הוּא. וְאִם אָכְלוּ אֲחֵרִים עִמּוֹ וּבֵרְכוּ, אֵין מַזְכִּירִין מֵעֵין הַמְּאֹרָע, דְּכֵיוָן דְּאִכָּא אֲחֵרִים \u0010y4\u0011 לָאו צִנְעָה הוּא. \u0010y5\u0011\nאָבֵל מִצְטָרֵף לִתְפִלָה וּלְזִמּוּן, בֵּין לְג' בֵּין לַעֲשָׂרָה.",["\u0003קדושנו קדוש יעקב. \u0004רוענו רועה ישראל המלך הטוב והמטיב לכל אל שבכל יום ויום הוא הטיב הוא מטיב הוא ייטיב לנו המלך החי הטוב והמטיב אל אמת דיין אמת כו'. דודאי צריך לומר הברכה מתחלה כתיקון חכמים:","\u0003ומעל אבל זה לחיים ולשלום. \u0004הוא גמלנו וכו' וכל טוב וכו' אל יחסרנו הרחמן הוא כו':","\u0003כאיש אשר אמו תנחמנו. \u0004כן אנכי אנחמכם ובירושלים תנוחמו בא\"י כו':","\u0003מנחם ציון בבנין ירושלים. \u0004אבל אין לומר מנחם אבלים ובונה ירושלים דאין חותמים בשתים. ומשמע לכאורה דה\"ה דאין לומר מנחם ציון ובונה ירושלים דה\"ל חותמים בשתים והכי אמרי' בש\"ס פרק שלשה שאכלו (ברכות דף מ\"ט ע\"א) דמושיע ישראל ובונה ירושלים הוה ליה חתימה בשתים דאסור אבל בנחם שאומרים בתשעה באב איתא בכל הסידורים בא\"י מנחם ציון ובונה ירושלים וצ\"ל דמנחם ציון ובונה ירושלים כולו חדא מילתא היא:","\u0003לאו צינעא הוא. \u0004ואין אבילות דבפרהסיא נוהג בשבת כדלקמן סי' ת':","\u0003אבל מצטרף כו'. \u0004ומדברי המרדכי נראה דסעודה ראשונה שמברין את האבל שאסור לאכלה משלו) אין האבל מצטרף בברכת המזון וכן כתב הרוקח סי' שי\"ג דכשמברכין ברכת המזון בשעת הבראתו אין האבלים מן המנין כדאמרינן בפ\"א דכתובות ור\"ל דאמרינן התם (דף ח' ע\"ב) דבברכת רחבה אין אבלים מן המנין ופי' רש\"י שם דהיינו כשמברין את האבל סעודה ראשונה משל אחרים כדאמרינן במ\"ק היו מברין אותו ברחבה כו' משמע להו דהוא הדין האידנא דליכא רחבה מ\"מ בסעודת הבראה תליא מילתא ואע\"פ שהתוס' כתבו במגילה (דף כ\"ג ע\"ב) דבברכת המזון האבל מצטרף אפשר דמודה בסעודה ראשונה דהבראה ולא מיירי אלא בשאר אבילות:"],[],"\u0010g0\u0011 כְּשֶׁמְּבָרְכִין בִּרְכַּת הַמָּזוֹן בְּבֵית הָאָבֵל, אוֹמֵר בְּרָכָה רְבִיעִית כְּנֻסַח זוֹ: בא\"י אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הָאֵל אָבִינוּ מַלְכֵּנוּ בּוֹרְאֵנוּ גוֹאֲלֵנוּ \u0010y0\u0011 קְדוֹשֵׁנוּ קְדוֹשׁ \u0010t0\u0011 יַעֲקֹב הַמֶּלֶךְ הַחַי הַטּוֹב וְהַמֵּטִיב אֵל אֱמֶת דַּיַּן אֱמֶת שׁוֹפֵט בְּצֶדֶק וְכו'. \u0005הַגָּה: \u0010g1\u0011 לוֹקֵחַ נְפָשׁוֹת בְּמִשְׁפָּט שַׁלִּיט בְּעוֹלָמוֹ לַעֲשׂוֹת בּוֹ כִּרְצוֹנוֹ כִּי כָּל דְּרָכָיו בְּמִשְׁפָּט וַאֲנַחְנוּ עַמּוֹ וַעֲבָדָיו וּבַכֹּל אֲנַחְנוּ חַיָּבִים לְהוֹדוֹת לוֹ וּלְבָרְכוֹ גּוֹדֵר פִּרְצוֹת יִשְׂרָאֵל הוּא יִגְדֹּר הַפִּרְצָה הַזֹּאת מֵעָלֵינוּ \u0010y1\u0011 וּמֵעַל אָבֵל זֶה לְחַיִּים \u0010t1\u0011 וּלְשָׁלוֹם (טוּר)\u0006. \u0010g2\u0011\nיֵשׁ מוֹסִיפִים בִּבְרָכָה שְׁלִישִׁית: נַחֵם ה' אֱלֹהֵינוּ אֶת אֲבֵלֵי יְרוּשָׁלַיִם וְאֶת הָאֲבֵלִים הַמִתְאַבְּלִים בָּאֵבֶל הַזֶּה, נַחֲמֵם מֵאֶבְלָם וְשַׂמְּחֵם מִיגוֹנָם, כָּאָמוּר: \u0010y2\u0011 כְּאִישׁ אֲשֶׁר אִמּוֹ תְּנַחֲמֶנּוּ \u0005(יְשַׁעְיָה סו, יג)\u0006 וְכו' בא\"י \u0010y3\u0011 מְנַחֵם צִיּוֹן בְּבִנְיַן יְרוּשָׁלַיִם. \u0010g3\u0011\nיֵשׁ אוֹמְרִים בְּבִרְכַּת זִמּוּן: נְבָרֵךְ מְנַחֵם אֲבֵלִים שֶׁאָכַלְנוּ מִשֶּׁלוֹ. \u0010g4\u0011 \u0010r0\u0011\nבְּשַׁבָּת, אִם בֵּרַךְ בְּיָחִיד, אוֹ בְּג' אֲבֵלִים, מְבָרֵךְ כְּדֶרֶךְ שֶׁמְּבָרֵךְ בְּחוֹל, דְּצִנְעָא הוּא. וְאִם אָכְלוּ אֲחֵרִים עִמּוֹ וּבֵרְכוּ, אֵין מַזְכִּירִין מֵעֵין הַמְּאֹרָע, דְּכֵיוָן דְּאִכָּא אֲחֵרִים \u0010y4\u0011 לָאו צִנְעָה הוּא. \u0010y5\u0011 \u0010g5\u0011 \u0010r1\u0011\nאָבֵל \u0010t2\u0011 מִצְטָרֵף לִתְפִלָה וּלְזִמּוּן, בֵּין לְג' בֵּין לַעֲשָׂרָה.",{"g":["\u0003מימרא דמר זוטרא ברכות דף מ\"ו ע\"ב:\u0004 ","\u0003טור בשם אביו הרא\"ש וכ\"כ התוס' שם ושכן עמא דבר דלא כמ\"ש בשם בה\"ג:\u0004 ","\u0003כל בו:\u0004 ","\u0003טור בשם רב עמרם ושכן הסכים הרמב\"ן בסת\"ה:\u0004 ","\u0003שם בשם הרמב\"ן:\u0004 ","המרדכי סוף פ\"ק:\n(°) מה שלא ראיתי נוהגין להוסיף ברכת אבלים בברכה רביעית נלע\"ד שסמכו אדברי התוספות כתובות דף ה' ריש ע\"ב שהוכיחו שם דברכת אבלים אינה אלא בעשרה וכ\"כ תשובת מהר\"מ סימן תרע\"ו וכ\"כ הב\"י בשם הרמב\"ן ובשם הר\"מ:"],"t":["\u0003יעקב. \u0004 רוענו רעה ישראל המלך הטוב והמטיב לכל אל שבכל יום ויום הוא הטיב הוא מטיב הוא ייטיב לנו המלך החי הטוב והמטיב וכו' דודאי צריך לומר הברכה מתחלה כתיקון חכמים עד כאן לשון הש\"ך:","\u0003ולשלום. \u0004 הרחמן הוא וכו':","\u0003מצטרף. \u0004 ומדברי המרדכי נראה דסעודה ראשונה שמברין את האבל שאסור לאכלה משלו אין האבל מצטרף בברכת המזון. וכ\"כ הרוקח דכן משמע בפ\"א דכתובות דף ח' ע\"ב ע\"ש עכ\"ל הש\"ך:"],"r":["\u0003בשבת כו'. \u0004עתוס' כ' ב' סד\"ה קורע כו':","\u0003אבל מצטרף כו' \u0004פ\"ק דכתובות ח' ב' וערש\"י ותוס' שם:"]}],["אֵלוּ דְּבָרִים שֶׁהָאָבֵל אָסוּר בָּהֶם: בִּמְלָאכָה, בִּרְחִיצָה וְסִיכָה וּנְעִילַת הַסַנְדָּל וְתַשְׁמִישׁ הַמִּטָּה, וְאָסוּר לִקְרוֹת בַּתּוֹרָה, וְאָסוּר בִּשְׁאֵלַת שָׁלוֹם וּבִכְבִיסָה, וְחַיָּב בַּעֲטִיפַת הָרֹאשׁ וּבִכְפִיַּת הַמִּטָּה, כָּל שִׁבְעָה, וְאָסוּר לְהַנִּיחַ תְּפִלִין בַּיּוֹם הָרִאשׁוֹן, וְאָסוּר בְּגִהוּץ וּבְתִסְפֹּרֶת וְשִׂמְחָה וְאִחוּי קֶרַע כָּל ל' יוֹם \u0005וְכָל דִּבְרֵי אֲבֵלוּת נוֹהֲגִין בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה (בִּתְשׁוּבַת הָרַשְׁבָּ\"א סִימָן תמ\"ו)\u0006.\nמְלָאכָה כֵּיצַד, כָּל ג' יָמִים הָרִאשׁוֹנִים אָסוּר בִּמְלָאכָה, אֲפִלוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה; מִכָּאן וָאֵילָךְ, אִם הוּא עָנִי וְאֵין לוֹ מַה יֹאכַל, עוֹשֶׂה בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ, \u0010y0\u0011 וְאִשָּׁה טוֹוָה בַּפֶּלֶךְ בְּתוֹךְ בֵּיתָהּ, אֲבָל אָמְרוּ חֲכָמִים: תָּבֹא מְאֵרָה לִשְׁכֵנָיו שֶׁהִצְרִיכוּהוּ לְכָךְ. \u0010y1\u0011 \u0005כְּדֶרֶךְ שֶׁמֻּתָּר לִכְתֹּב בְּחֹל הַמּוֹעֵד, כָּךְ מֻתָּר לִכְתֹּב בִּימֵי אֶבְלוֹ; אֲבָל לֹא בְּעִנְיָן אַחֵר (כָּל בּוֹ בְּשֵׁם הר\"מ וב\"י סוֹף סִימָן זֶה)\u0006.\nג כְּשֵׁם שֶׁהוּא אָסוּר בַּעֲשִׂיַּת מְלָאכָה, כָּךְ הוּא אָסוּר לִשָּׂא וְלִתֵּן בִּסְחוֹרָה, וְלֵילֵךְ מִמְּדִינָה לִמְדִינָה בִּסְחוֹרָה.\nאֲפִלוּ דָּבָר הָאָבֵד אָסוּר הָאָבֵל לַעֲשׂוֹת בֵּין עֲבָדָיו וְשִׁפְחוֹתָיו \u0010y2\u0011 וּבָנָיו וּבְנוֹתָיו שֶׁמַּעֲשֵׂה יְדֵיהֶם שֶׁלוֹ.\nאָסוּר לַעֲשׂוֹת מְלַאכְתּוֹ עַל יְדֵי אֲחֵרִים \u0005אֲפִלּוּ עוֹבֵד כּוֹכָבִים (מָרְדְּכַי רֵישׁ פֶּרֶק מִי שֶׁהָפַךְ)\u0006, אֶלָא אִם כֵּן הוּא דָּבָר הָאָבֵד, שֶׁדָּבָר הָאָבֵד מֻתָּר לְאָבֵל לַעֲשׂוֹת עַל יְדֵי אֲחֵרִים; \u0010y3\u0011 אֲפִלוּ דָּבָר הָאָסוּר בַּמּוֹעֵד מִשּׁוּם טִרְחָא, מֻתָּר, וַאֲפִלוּ הוּא מַעֲשֵׂה אֻמָּן. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם לֹא יוּכַל לַעֲשׂוֹת עַל יְדֵי אֲחֵרִים, וְהוּא דָּבָר הָאָבֵד, \u0010y4\u0011 \u0010y5\u0011 מֻתָּר לַעֲשׂוֹת הָאָבֵל בְּעַצְמוֹ (טוּר בְּשֵׁם הָרַמְבַּ\"ן וְהָרֹא\"שׁ וְכֵן כָּתַב רַבֵּנוּ יְרוּחָם)\u0006 ; וּלְאַחַר שְׁלֹשָׁה יָמִים הָרִאשׁוֹנִים יֵשׁ לְהָקֵל, וַאֲפִלּוּ תּוֹךְ ג' וְהוּא הֶפְסֵד מְרֻבֶּה.\nפְּרַקְמַטְיָא שֶׁלוֹ, בְּדָבָר הָאָבֵד, שֶׁאִם לֹא יִמְכֹּר יַפְסִיד מֵהַקֶרֶן, נִמְכֶּרֶת עַל יְדֵי אֲחֵרִים; אֲבָל אִם לֹא יַפְסִיד מֵהַקֶרֶן, אֶלָא שֶׁאִם יִמְכְּרֶנָּה עַתָּה יַרְוִיחַ בָּהּ יוֹתֵר מִשֶּׁאִם יִמְכְּרֶנָּה אַחַר כָּךְ, אָסוּר. \u0010y6\u0011 וּמִכָּל מָקוֹם אִם שַׁיָּרוֹת אוֹ סְפִינוֹת בָּאוּ, אוֹ שֶׁהֵם מְבַקְשִׁים לָצֵאת, וּמוֹכְרִים בְּזוֹל אוֹ לוֹקְחִים בְּיֹקֶר, מֻתָּר לִמְכֹּר וְלִקְנוֹת עַל יְדֵי אֲחֵרִים, אֲפִלוּ שֶׁלֹּא לְצֹרֶךְ תַּשְׁמִישׁוֹ, אֶלָא לַעֲשׂוֹת סְחוֹרָה לְהִשְׂתַּכֵּר.\nלְהַלְווֹת לְעוֹבְדֵי כּוֹכָבִים בְּרִבִּית, לְאוֹתָם שֶׁרְגִילִים לִלְווֹת מִמֶּנּוּ, מֻתָּר לְהַלְווֹת לָהֶם עַל יְדֵי אֲחֵרִים, \u0010y7\u0011 מִשּׁוּם דְּהָוֵי דָּבָר הָאָבֵד.\nאִי מַסִיק זוּזֵי בְּאִינְשֵׁי, וְהָאִדָּנָא מַשְׁכַּח לְהוּ, וּבָתַר הָכִי לָא מַשְׁכַּח לְהוּ, שָׁרֵי \u0010y8\u0011 לְשַׁדּוֹרֵי עֲלַיְהוּ.\nאִם יֵשׁ לוֹ דִּין עַל אָדָם, אֵינוֹ תּוֹבֵעַ כָּל ז'. וְאִם הוּא דָּבָר הָאָבֵד, כְּגוֹן שֶׁבִּקֵשׁ לֵילֵךְ לִמְדִינַת הַיָּם, אוֹ \u0010y9\u0011 שֶׁעֵדָיו חוֹלִים, עוֹשֶׂה מֻרְשֶׁה וְדָן עִמּוֹ. \u0010y10\u0011\nכָּל הַדְּבָרִים שֶׁהִתִּירוּ בַּמּוֹעֵד מִשּׁוּם צֹרֶךְ הַמּוֹעֵד, כֻּלָם אֲסוּרִים בְּאָבֵל, אֲפִלוּ עַל יְדֵי אֲחֵרִים.\nאָבֵל שֶׁשָּׂדֵהוּ בְּיַד אֲחֵרִים \u0010y11\u0011 בַּאֲרִיסוּת אוֹ בַּחֲכִירוּת אוֹ בְּקַבְּלָנוּת, הֲרֵי אֵלוּ עוֹבְדִין כְּדַרְכָּן בִּימֵי הָאֵבֶל שֶׁל בַּעַל הַשָּׂדֶה, וַאֲפִלוּ נִשְׁלַם זְמַן חֲכִירוּתָם קֹדֶם וְנִשְׁאֲרוּ בַּשָּׂדֶה כְּמוֹ שֶׁהָיוּ.\nאִם הָאָבֵל הוּא אָרִיס בְּשָׂדֶה שֶׁל אֲחֵרִים, לֹא יַעֲבֹד הוּא בְּעַצְמוֹ, \u0010y12\u0011 אֲבָל עַל יְדֵי אֲחֵרִים מֻתָּר.\nאִם יֵשׁ שְׂכִיר יוֹם שֶׁעוֹבֵד שְׂדֵה הָאָבֵל, אֲפִלוּ בְּעִיר אַחֶרֶת, \u0010y13\u0011 לֹא יַעֲשֶׂה.\nאִם יֵשׁ לָאָבֵל חֲמוֹר אוֹ סְפִינָה \u0010y14\u0011 מֻחְכָּר אוֹ מֻשְׂכָּר בְּיַד אַחֵר, הֲרֵי זֶה לֹא יַעֲשֶׂה בִּימֵי אֶבְלוֹ שֶׁל בַּעַל הַחֲמוֹר וְהַסְפִינָה, אִם לֹא שֶׁשְּׂכָרוֹ קֹדֶם שֶׁהִתְחִיל הָאֲבֵלוּת וַעֲדַיִן לֹא כָּלָה הַזְּמַן; אֲבָל אִם כָּלָה הַזְּמַן, אָסוּר.\nאִם הָיָה הַחֲמוֹר וְהַסְפִינָה בְּיַד אֲחֵרִים, לְמֶחֱצָה, לִשְׁלִישׁ וְלִרְבִיעַ, יֵשׁ מַתִּירִים \u0010y15\u0011 וְיֵשׁ אוֹסְרִים.\nאִם הָאָבֵל מֻשְׂכָּר לְאַחֵר, לֹא יַעֲשֶׂה מְלָאכָה בִּימֵי אֶבְלוֹ. \u0010y16\u0011 \u0005אֲבָל עַל יְדֵי אֲחֵרִים, שָׁרֵי (זֶהוּ מֵהָרֹא\"שׁ)\u0006.\nהָיְתָה מְלֶאכֶת אֲחֵרִים בְּיָדוֹ, \u0010y17\u0011 אֲפִלוּ בְּדָבָר תָּלוּשׁ, כְּגוֹן לֶאֱרֹג, בֵּין בְּקַבְּלָנוּת בֵּין שֶׁלֹּא בְּקַבְּלָנוּת, לֹא יַעֲשֶׂה. \u0005הַגָּה: \u0010y18\u0011 וְאִם הוּא דָּבָר הָאָבֵד, יַעֲשֶׂה עַל יְדֵי אֲחֵרִים (ד\"ע)\u0006. מֻתָּר לְקַבֵּל מְלָאכָה בִּימֵי אֶבְלוֹ לַעֲשׂוֹת אַחַר כָּךְ, וּבִלְבַד שֶׁלֹּא יִשְׁקֹל וְלֹא יִמְדֹּד כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בִּשְׁאָר פְּעָמִים \u0005(מָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006. \u0010y19\u0011\nהָיְתָה מְלַאכְתּוֹ בְּיַד אֲחֵרִים, בְּקַבְּלָנוּת בְּדָבָר תָּלוּשׁ, בְּבֵיתוֹ, לֹא יַעֲשׂוּ; בְּבֵית אֲחֵרִים, יַעֲשׂוּ. \u0005וּבִלְבַד שֶׁקִּבְּלוּ הַמְּלָאכָה קֹדֶם שֶׁנַּעֲשָׂה אָבֵל (מָרְדְּכַי סוֹף מ\"ק וְר\"י)\u0006.\nהָיָה לוֹ בִּנְיָן בְּיַד אֲחֵרִים, בְּקַבְּלָנוּת, בְּחֹל אוֹ בְּחֹל הַמּוֹעֵד \u0010y20\u0011 לֹא יַעֲשׂוּ, אֲפִלוּ הוּא חוּץ לִתְחוּם הָעִיר; וְאִם אֵלוּ הַקַבְּלָנִים עוֹבְדֵי כּוֹכָבִים, \u0010y21\u0011 מֻתָּרִים לִבְנוֹתוֹ בְּשַׁבָּת וְיוֹם טוֹב שֶׁחָלוּ בִּימֵי הָאֵבֶל, אִם הוּא חוּץ לִתְחוּם הָעִיר וְאֵין עִיר אַחֶרֶת שֶׁבָּהּ יִשְׂרָאֵל בְּתוֹךְ תְּחוּם שֶׁל אוֹתוֹ בַּיִת.\nאִם קִבְּלוּ אֲחֵרִים לַחֲרֹשׁ וְלִזְרֹעַ שָׂדֵהוּ, יֵשׁ אוֹמְרִים שֶׁמֻּתָּרִין לַחֲרֹשׁ וְלִזְרֹעַ בִּימֵי אֶבְלוֹ שֶׁל בַּעַל הַשָּׂדֶה, וְיֵשׁ מִי שֶׁאוֹסֵר.\nשְׁנֵי שֻׁתָּפִים חֶנְוָנִים שֶׁאֵרַע אֵבֶל לְאֶחָד מֵהֶם, נוֹעֲלִים חֲנוּתָם, שֶׁלֹּא יַעֲשֶׂה \u0010y22\u0011 הַשֻּׁתָּף בְּפַרְהֶסְיָא, אֲבָל יָכוֹל לַעֲשׂוֹת בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ, אֲפִלוּ בְּעֵסֶק הַשֻּׁתָּפוּת. וְאִם הָאָבֵל אָדָם חָשׁוּב, וְהַשֻּׁתָּפוּת נִקְרָא עַל שְׁמוֹ, שֶׁאֲפִלוּ אִם יַעֲשֵׂהוּ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ יָדוּעַ שֶּׁיֵּשׁ לָאָבֵל חֵלֶק בּוֹ, אָסוּר לַשֵּׁנִי לַעֲשׂוֹת אֲפִלוּ בְּתוֹךְ בֵּיתוֹ.\nכְּבוֹד הַבַּיִת, הֲדָחַת כּוֹסוֹת וְהַצָּעַת הַמִּטּוֹת, אֵין בָּהֶם מִשּׁוּם מְלָאכָה לְאָבֵל; וְכֵן מֻתָּר לְאִשָּׁה לֶאֱפוֹת וּלְבַשֵּׁל בִּימֵי אֶבְלָהּ \u0005כָּל הַצָּרִיךְ לָהּ, אֲבָל מַה שֶּׁאֵינוֹ צָרִיךְ לָהּ אָסוּר;\u0006 \u0010c0\u0011 וְכֵן אִשָּׁה הַמְשָׁרֶתֶת בְּבֵית בַּעַל הַבַּיִת אֶחָד, וְאֵרְעָהּ אֵבֶל, מֻתֶּרֶת לֶאֱפוֹת וּלְבַשֵּׁל וְלַעֲשׂוֹת שְׁאָר צָרְכֵי הַבַּיִת, בֵּין שֶׁהִיא מְשָׁרֶתֶת בְּחִנָּם בֵּין בְּשָׂכָר.\nהַהוֹלֵךְ מִמָּקוֹם לְמָקוֹם לִסְחוֹרָה, וְשָׁמַע שְׁמוּעָה קְרוֹבָה, אִם יָכוֹל לְמַעֵט שֶׁלֹּא לַעֲשׂוֹת שׁוּם עֵסֶק בְּאוֹתָהּ הָעִיר, מוּטָב; וְאִם לָאו, שֶׁאִם לֹא יִקְנֶה בְּאוֹתָהּ הָעִיר לֹא יִמָּצֵא, יִקְנֶה לְצֹרֶךְ הַדֶּרֶךְ דְּבָרִים שֶׁיֵּשׁ בָּהֶם חַיֵּי נֶפֶשׁ.\nעַל כָּל הַמֵּתִים, רָצָה לְמַעֵט בְּעֵסֶק סְחוֹרָה הַמֻּתֶּרֶת לוֹ, כְּגוֹן דָּבָר הָאָבֵד, יְמַעֵט; רָצָה, אֵינוֹ מְמַעֵט. עַל אָבִיו וְאִמּוֹ, יְמַעֵט.\nעַל כָּל הַמֵּתִים אָסוּר עַד ל' יוֹם לֵילֵךְ בִּסְחוֹרָה לְמֵרָחוֹק, דְּאִכָּא פִּרְסוּם גָדוֹל וְדוֹמֶה לְשִׂמְחָה שֶׁהוֹלֵךְ בְּשַׁיָּרָא גְדוֹלָה וּשְׂמֵחִים הַרְבֵּה בַּדֶּרֶךְ; בְּאָבִיו וְאִמּוֹ, עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו וְיֹאמְרוּ: לֵךְ עִמָּנוּ.",["\u0003ואשה טווה בפלך בתוך ביתה. \u0004פירוש אין מתירין לה אלא מלאכה של צינעה ושל עראי כגון להיות טווה בפלך בתוך ביתה ואם אינה מספקת בזה עושה אומנות שלה בצינעה תוך ביתה. עכ\"ל טור:","\u0003כדרך שמותר לכתוב בחוה\"מ כו'. \u0004כמו שנתבאר בא\"ח סי' תקמ\"ה ע\"ש:","\u0003ובניו ובנותיו כו'. \u0004פירוש אפי' הם גדולים אם סמוכים על שלחנו עכ\"ל טור ועט\"ז ור\"ל כל שכן קטנים כשסמוכים על שלחנו אבל אם אינם סמוכים על שלחנו אפי' קטנים מעשה ידיהן לעצמן כמו שנתבאר בח\"מ סימן ע\"ד ס\"ב.","\u0003אפי' כו' ואפי' כו'. \u0004דדוקא במועד אסרו דברים של טורח מפני כבוד המועד אבל באבל שעושה ע\"י אחרים מאי איכפת לן בטורח דאחרים. טור.","\u0003מותר לעשות האבל בעצמו. \u0004אפילו הוא דבר שיש בו טירחא ומעשה אומן כן משמע בש\"ס:","\u0003לעשות כו'. \u0004מיהו יעשה בצינעה כן משמע בש\"ס:","\u0003ומ\"מ אם שיירות או ספינות כו'. \u0004הטעם כיון שהוא דבר שאינו מצוי וכ\"מ בט\"ו בא\"ח סי' תקל\"ט ס\"ה דלא כנראה מהעט\"ז כאן הטעם דהוי הפסד מרובה ע\"ש:","\u0003משום דהוי דבר האבד. \u0004שאם לא ילוה להם ילכו לאחרים וילוו להם וירגילום לבא אצלם ואיכא פסידא. טור:","\u0003לשדורי עלייהו. \u0004כלומר לשלוח אחרים שיתבעו המעות מהם דה\"ל דבר האבד:","\u0003שעדיו חולים. \u0004וירא שמא ימותו:","\u0003כל הדברים כו'. \u0004כלומר כל הדברים שלא התירו במועד משום דבר האבד וכה\"ג אלא משום צורך המועד כולם אסורים באבל כו':","\u0003באריסות כו'. \u0004אריסות היינו לשליש ולרביע חכירות שנותן לו סכום מפירות השדה בין עושה מעט או הרבה וקבלנות שנותן לו מעות סכום ידוע:","\u0003אבל על ידי אחרים מותר. \u0004שאין זה נקרא מלאכת האבל אלא מלאכת בעל השדה:","\u0003לא יעשה. \u0004כיון שאינו אצלו באריסות או בחכירות ובקבלנות:","\u0003מוחכר או מושכר כצ\"ל. \u0004ומוחכר שייך בפירות ושכירות במעות:","\u0003ויש אוסרים. \u0004דדוקא בקרקע שרי דלאריסות קיימא משא\"כ הכא:","\u0003אבל על ידי אחרים שרי. \u0004משמע אפילו אינו דבר האבד וכן משמע להדיא בעט\"ז וכ' דאע\"פ דלעיל סעיף ב' וה' אסור אפי' ע\"י אחרים מ\"מ הכא מותר על ידי אחרים והוא יקח השכר מן הבעלים שהרי אין עיקר המלאכה שלו עכ\"ל. ודין זה הוציא הרב מהרא\"ש שכתב על פירש\"י מה שפי' שאם היה אבל מוחכר או מושכר אצל אחר שיעשה הוא עצמו מלאכה נ\"ל קולא גדולה דהא אפילו עני המתפרנס מן הצדקה לא יעשה בצינעה בתוך ביתו שלשה ימים הראשונים ומשום הפסד ממונו מעט שרית ליה לעשות מלאכה בפרהסיא עכ\"ל ומשמע ליה להרב מדכ' מאי שפירש כו' שיעשה הוא עצמו מלאכה נ\"ל קולא גדולה כו' משמע הא על ידי אחרים שרי ולפע\"ד נראה מדמדמי ליה לעני המתפרנס מן הצדקה משמע דאפי' ע\"י אחרים אסו' ומ\"ש שיעשה הוא עצמו מלאכה נ\"ל קולא גדולה כו' כ' כן כלפי מה שפירש\"י שם על ואם היו מוחכרים או מושכרים וז\"ל ואם היו מוחכרים או מושכרים הם או בהמתם אצל אחרים למהלך חדש או חדשים הרי אלו יעשו הם לעצמם ולא יפסידו שכרם עכ\"ל עלה קאי ואמר מה שפי' שיעשה הוא עצמו מלאכה קולא גדולה אלא קאי אבהמתן לחוד וכפי' הראב\"ד ולא כשהיה עצמו מושכר אבל לא נחית הרא\"ש לחלק כשהוא עצמו מושכר בין ע\"י עצמו לע\"י אחרי' וזה נרא' דעת הט\"ו שלא חילקו בכך:","\u0003אפילו בדבר תלוש. \u0004שיכול לעשותו בצינעה וכל שכן דבר מחובר שאינו יכול לעשותו אלא בפרהסיא:","\u0003ואם הוא דבר האבד כו'. \u0004והעט\"ז כתב וזה לשונו ונ\"ל אפילו אינו דבר האבד מותר לעשות ע\"י אחרים כיון שעיקר המלאכה אינו שלו וכמ\"ש בסעיף י\"ז גבי הוא עצמו מושכר עכ\"ל ודעת הרב נראה דדוקא התם שהוא מושכר לחדש או לחדשים שרי משא\"כ הכא ולפי מ\"ש בס\"ק י\"ז דבהוא עצמו מושכר אסור ע\"י אחרים אם לא בדבר האבד א\"כ כל שכן הכא:","\u0003היתה מלאכתו כו'. \u0004וכ' רבינו ירוחם בשם המפרשים שמכאן יש ללמוד שאם היה לאבל מלמד או סופר או פועל שלא יעשה בביתו ומביאו ב\"י:","\u0003לא יעשו אפי' הוא חוץ לתחום העיר. \u0004ואפי' מסרה להם קודם האבל או קודם ח\"ה אסור מפני מראית העין שכיון שיוכלו בני אדם ללכת שם ויראו המלאכה יאמרו ראה זה שמסר מלאכתו לאחרים בימי האבל או בחול המועד ולא ידעי דקבולת הוא גבייהו קודם לכן:","\u0003מותרים לבנותו כו' אם הוא חוץ לתחום כו'. \u0004דליכא למיגזר משום חשדא שאין בני העיר מצוים שם שיבינו שמלאכת אבל או של ישראל היא:","\u0003בפרהסיא כו'. \u0004זה סותר למ\"ש בב\"י ולענין הלכה כיון שהרי\"ף והרמב\"ם מסכימים לדעת א' הכי נקטינן וראיתי בב\"ה שתיקן דבריו שבב\"י שצ\"ל הכי נקטינן וכתירוצו של הראב\"ד וכך הם דברי רבינו עכ\"ל אבל צ\"ע דכיון דכתב הכי נקטינן על דברי הרי\"ף והרמב\"ם היאך כ' וכתירוצו של הראב\"ד הא ודאי הרי\"ף והרמב\"ם אין מחלקים בין צינעה לפרהסיא כהראב\"ד וכדמשמע בהרא\"ש ורמב\"ן ובב\"י ע\"ש וע' בתשו' מהרש\"ל סימן ס\"ז:"],["\u0003וכן אשה המשרתת כו'. \u0004ואין להקשות הא כתב בסעיף ט\"ז אם האבל מושכר לאחרים לא יעשה מלאכה בימי אבלו דהתם מיירי במלאכה גמורה שאסור לאבל בכל גווני משא\"כ במלאכת צרכי הבית דמותר לאשה עצמה כמ\"ש בסעיף שקודם לזה על כן מותר אפי' למשרתת אבל על כל פנים לא תעשה המשרתת מלאכה שאינו לצורך הבית אלא להרויח וכ\"ש שלא תצא מן הבית כדין אבל וראיתי מי שהורה לשמש שאירע לו אבל שיעשה עבודתו וילך לבית הכנסת ולשמש בצרכי הקהל ולא יפה הורה דטעה בטעם הדין הזה דהיתר משרתת. כ' רש\"ל בשם אגודה דאבל מותר להקיז דם וכתב הכל בו דאבל שעושה מלאכה מנדין אותו:"],"\u0010g0\u0011 \u0010r0\u0011 אֵלוּ דְּבָרִים שֶׁהָאָבֵל אָסוּר בָּהֶם: בִּמְלָאכָה, בִּרְחִיצָה וְסִיכָה וּנְעִילַת הַסַנְדָּל וְתַשְׁמִישׁ הַמִּטָּה, וְאָסוּר לִקְרוֹת בַּתּוֹרָה, \u0010r1\u0011 וְאָסוּר בִּשְׁאֵלַת שָׁלוֹם וּבִכְבִיסָה, וְחַיָּב בַּעֲטִיפַת הָרֹאשׁ וּבִכְפִיַּת הַמִּטָּה, כָּל שִׁבְעָה, וְאָסוּר לְהַנִּיחַ \u0010r2\u0011 תְּפִלִין בַּיּוֹם הָרִאשׁוֹן, \u0010r3\u0011 וְאָסוּר \u0010r4\u0011 בְּגִהוּץ וּבְתִסְפֹּרֶת וְשִׂמְחָה וְאִחוּי קֶרַע כָּל ל' יוֹם \u0005וְכָל דִּבְרֵי אֲבֵלוּת נוֹהֲגִין בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה (בִּתְשׁוּבַת הָרַשְׁבָּ\"א סִימָן תמ\"ו)\u0006. \u0010g1\u0011\nמְלָאכָה כֵּיצַד, \u0010r5\u0011 כָּל ג' יָמִים הָרִאשׁוֹנִים אָסוּר בִּמְלָאכָה, אֲפִלוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה; מִכָּאן וָאֵילָךְ, \u0010g2\u0011 \u0010r6\u0011 אִם הוּא עָנִי וְאֵין לוֹ מַה יֹאכַל, עוֹשֶׂה בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ, \u0010y0\u0011 וְאִשָּׁה טוֹוָה \u0010t0\u0011 בַּפֶּלֶךְ בְּתוֹךְ בֵּיתָהּ, \u0010g3\u0011 אֲבָל אָמְרוּ חֲכָמִים: תָּבֹא מְאֵרָה לִשְׁכֵנָיו שֶׁהִצְרִיכוּהוּ לְכָךְ. \u0010y1\u0011 \u0005כְּדֶרֶךְ \u0010t1\u0011 שֶׁמֻּתָּר לִכְתֹּב בְּחֹל הַמּוֹעֵד, כָּךְ מֻתָּר לִכְתֹּב בִּימֵי אֶבְלוֹ; אֲבָל לֹא בְּעִנְיָן אַחֵר (כָּל בּוֹ בְּשֵׁם הר\"מ וב\"י סוֹף סִימָן זֶה)\u0006. \u0010g4\u0011 \u0010r7\u0011\nג כְּשֵׁם שֶׁהוּא אָסוּר בַּעֲשִׂיַּת מְלָאכָה, כָּךְ הוּא אָסוּר לִשָּׂא וְלִתֵּן בִּסְחוֹרָה, וְלֵילֵךְ מִמְּדִינָה לִמְדִינָה בִּסְחוֹרָה. \u0010g5\u0011\nאֲפִלוּ דָּבָר הָאָבֵד אָסוּר הָאָבֵל לַעֲשׂוֹת \u0010r8\u0011 בֵּין \u0010g6\u0011 עֲבָדָיו וְשִׁפְחוֹתָיו \u0010y2\u0011 \u0010t2\u0011 וּבָנָיו וּבְנוֹתָיו שֶׁמַּעֲשֵׂה יְדֵיהֶם שֶׁלוֹ. \u0010g7\u0011 \u0010r9\u0011\nאָסוּר לַעֲשׂוֹת מְלַאכְתּוֹ עַל יְדֵי אֲחֵרִים \u0005אֲפִלּוּ עוֹבֵד כּוֹכָבִים (מָרְדְּכַי רֵישׁ פֶּרֶק מִי שֶׁהָפַךְ)\u0006, \u0010g8\u0011 אֶלָא אִם כֵּן הוּא דָּבָר הָאָבֵד, שֶׁדָּבָר הָאָבֵד מֻתָּר לְאָבֵל לַעֲשׂוֹת עַל יְדֵי אֲחֵרִים; \u0010y3\u0011 \u0010g9\u0011 \u0010r10\u0011 אֲפִלוּ דָּבָר הָאָסוּר בַּמּוֹעֵד מִשּׁוּם טִרְחָא, מֻתָּר, וַאֲפִלוּ הוּא מַעֲשֵׂה אֻמָּן. \u0005הַגָּה: \u0010r11\u0011 וְיֵשׁ אוֹמְרִים דְּאִם לֹא יוּכַל לַעֲשׂוֹת עַל יְדֵי אֲחֵרִים, וְהוּא דָּבָר הָאָבֵד, \u0010y4\u0011 \u0010y5\u0011 מֻתָּר לַעֲשׂוֹת הָאָבֵל \u0010t3\u0011 בְּעַצְמוֹ (טוּר בְּשֵׁם הָרַמְבַּ\"ן וְהָרֹא\"שׁ וְכֵן כָּתַב רַבֵּנוּ יְרוּחָם)\u0006 ; וּלְאַחַר שְׁלֹשָׁה יָמִים הָרִאשׁוֹנִים יֵשׁ לְהָקֵל, וַאֲפִלּוּ תּוֹךְ ג' וְהוּא הֶפְסֵד \u0010g10\u0011 \u0010r12\u0011 מְרֻבֶּה.\nפְּרַקְמַטְיָא שֶׁלוֹ, בְּדָבָר הָאָבֵד, שֶׁאִם לֹא יִמְכֹּר יַפְסִיד מֵהַקֶרֶן, נִמְכֶּרֶת עַל יְדֵי אֲחֵרִים; אֲבָל אִם לֹא יַפְסִיד מֵהַקֶרֶן, אֶלָא שֶׁאִם יִמְכְּרֶנָּה עַתָּה יַרְוִיחַ בָּהּ יוֹתֵר מִשֶּׁאִם יִמְכְּרֶנָּה אַחַר כָּךְ, אָסוּר. \u0010y6\u0011 \u0010g11\u0011 וּמִכָּל מָקוֹם אִם שַׁיָּרוֹת אוֹ סְפִינוֹת בָּאוּ, אוֹ שֶׁהֵם מְבַקְשִׁים לָצֵאת, וּמוֹכְרִים בְּזוֹל אוֹ לוֹקְחִים בְּיֹקֶר, מֻתָּר לִמְכֹּר וְלִקְנוֹת עַל יְדֵי אֲחֵרִים, אֲפִלוּ שֶׁלֹּא לְצֹרֶךְ תַּשְׁמִישׁוֹ, אֶלָא לַעֲשׂוֹת סְחוֹרָה לְהִשְׂתַּכֵּר.\nלְהַלְווֹת לְעוֹבְדֵי כּוֹכָבִים בְּרִבִּית, \u0010g12\u0011 לְאוֹתָם שֶׁרְגִילִים לִלְווֹת מִמֶּנּוּ, מֻתָּר לְהַלְווֹת לָהֶם עַל יְדֵי אֲחֵרִים, \u0010y7\u0011 מִשּׁוּם דְּהָוֵי דָּבָר \u0010t4\u0011 הָאָבֵד. \u0010g13\u0011\nאִי מַסִיק זוּזֵי בְּאִינְשֵׁי, וְהָאִדָּנָא מַשְׁכַּח לְהוּ, וּבָתַר הָכִי לָא מַשְׁכַּח לְהוּ, שָׁרֵי \u0010y8\u0011 \u0010t5\u0011 לְשַׁדּוֹרֵי \u0010g14\u0011 עֲלַיְהוּ.\nאִם יֵשׁ לוֹ דִּין עַל אָדָם, אֵינוֹ תּוֹבֵעַ כָּל ז'. וְאִם הוּא דָּבָר הָאָבֵד, כְּגוֹן שֶׁבִּקֵשׁ לֵילֵךְ לִמְדִינַת הַיָּם, אוֹ \u0010y9\u0011 שֶׁעֵדָיו \u0010t6\u0011 חוֹלִים, עוֹשֶׂה מֻרְשֶׁה וְדָן עִמּוֹ. \u0010y10\u0011 \u0010g15\u0011 \u0010r13\u0011\nכָּל הַדְּבָרִים שֶׁהִתִּירוּ בַּמּוֹעֵד מִשּׁוּם \u0010t7\u0011 צֹרֶךְ הַמּוֹעֵד, כֻּלָם אֲסוּרִים בְּאָבֵל, אֲפִלוּ עַל יְדֵי אֲחֵרִים. \u0010g16\u0011 \u0010r14\u0011\nאָבֵל שֶׁשָּׂדֵהוּ בְּיַד אֲחֵרִים \u0010y11\u0011 בַּאֲרִיסוּת אוֹ בַּחֲכִירוּת אוֹ בְּקַבְּלָנוּת, הֲרֵי אֵלוּ עוֹבְדִין כְּדַרְכָּן בִּימֵי הָאֵבֶל שֶׁל בַּעַל הַשָּׂדֶה, \u0010g17\u0011 \u0010r15\u0011 וַאֲפִלוּ נִשְׁלַם זְמַן חֲכִירוּתָם קֹדֶם וְנִשְׁאֲרוּ בַּשָּׂדֶה כְּמוֹ שֶׁהָיוּ. \u0010g18\u0011 \u0010r16\u0011\nאִם הָאָבֵל הוּא אָרִיס בְּשָׂדֶה שֶׁל אֲחֵרִים, לֹא יַעֲבֹד הוּא בְּעַצְמוֹ, \u0010y12\u0011 אֲבָל עַל יְדֵי אֲחֵרִים \u0010g19\u0011 \u0010t8\u0011 מֻתָּר.\nאִם יֵשׁ שְׂכִיר יוֹם שֶׁעוֹבֵד שְׂדֵה הָאָבֵל, אֲפִלוּ בְּעִיר אַחֶרֶת, \u0010y13\u0011 לֹא \u0010t9\u0011 יַעֲשֶׂה. \u0010g20\u0011 \u0010r17\u0011\nאִם יֵשׁ לָאָבֵל חֲמוֹר אוֹ סְפִינָה \u0010y14\u0011 מֻחְכָּר אוֹ מֻשְׂכָּר בְּיַד אַחֵר, הֲרֵי זֶה לֹא יַעֲשֶׂה בִּימֵי אֶבְלוֹ שֶׁל בַּעַל הַחֲמוֹר וְהַסְפִינָה, אִם לֹא שֶׁשְּׂכָרוֹ קֹדֶם שֶׁהִתְחִיל הָאֲבֵלוּת וַעֲדַיִן לֹא כָּלָה הַזְּמַן; אֲבָל אִם כָּלָה הַזְּמַן, אָסוּר. \u0010g21\u0011 \u0010r18\u0011\nאִם הָיָה הַחֲמוֹר וְהַסְפִינָה בְּיַד אֲחֵרִים, לְמֶחֱצָה, לִשְׁלִישׁ וְלִרְבִיעַ, יֵשׁ מַתִּירִים \u0010y15\u0011 \u0010g22\u0011 \u0010r19\u0011 וְיֵשׁ \u0010g23\u0011 אוֹסְרִים.\nאִם הָאָבֵל מֻשְׂכָּר לְאַחֵר, לֹא יַעֲשֶׂה מְלָאכָה בִּימֵי אֶבְלוֹ. \u0010y16\u0011 \u0010r20\u0011 \u0005אֲבָל עַל יְדֵי אֲחֵרִים, \u0010t10\u0011 שָׁרֵי (זֶהוּ מֵהָרֹא\"שׁ)\u0006. \u0010g24\u0011\nהָיְתָה מְלֶאכֶת אֲחֵרִים בְּיָדוֹ, \u0010y17\u0011 אֲפִלוּ בְּדָבָר \u0010t11\u0011 תָּלוּשׁ, כְּגוֹן לֶאֱרֹג, בֵּין בְּקַבְּלָנוּת בֵּין שֶׁלֹּא בְּקַבְּלָנוּת, לֹא יַעֲשֶׂה. \u0005הַגָּה: \u0010y18\u0011 \u0010r21\u0011 וְאִם הוּא דָּבָר הָאָבֵד, יַעֲשֶׂה עַל יְדֵי \u0010t12\u0011 אֲחֵרִים (ד\"ע)\u0006. \u0010r22\u0011 מֻתָּר לְקַבֵּל מְלָאכָה בִּימֵי אֶבְלוֹ לַעֲשׂוֹת אַחַר כָּךְ, וּבִלְבַד שֶׁלֹּא יִשְׁקֹל וְלֹא יִמְדֹּד כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בִּשְׁאָר פְּעָמִים \u0005(מָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006. \u0010y19\u0011 \u0010g25\u0011\nהָיְתָה \u0010t13\u0011 מְלַאכְתּוֹ בְּיַד אֲחֵרִים, בְּקַבְּלָנוּת בְּדָבָר תָּלוּשׁ, בְּבֵיתוֹ, לֹא יַעֲשׂוּ; בְּבֵית אֲחֵרִים, יַעֲשׂוּ. \u0010r23\u0011 \u0005וּבִלְבַד שֶׁקִּבְּלוּ הַמְּלָאכָה קֹדֶם שֶׁנַּעֲשָׂה אָבֵל (מָרְדְּכַי סוֹף מ\"ק \u0010g26\u0011 \u0010r24\u0011 וְר\"י)\u0006.\nהָיָה לוֹ בִּנְיָן בְּיַד אֲחֵרִים, בְּקַבְּלָנוּת, בְּחֹל אוֹ בְּחֹל הַמּוֹעֵד \u0010y20\u0011 לֹא יַעֲשׂוּ, אֲפִלוּ הוּא חוּץ \u0010t14\u0011 לִתְחוּם הָעִיר; וְאִם אֵלוּ הַקַבְּלָנִים עוֹבְדֵי כּוֹכָבִים, \u0010y21\u0011 מֻתָּרִים לִבְנוֹתוֹ בְּשַׁבָּת וְיוֹם טוֹב שֶׁחָלוּ בִּימֵי הָאֵבֶל, אִם הוּא חוּץ לִתְחוּם הָעִיר וְאֵין עִיר אַחֶרֶת שֶׁבָּהּ יִשְׂרָאֵל בְּתוֹךְ תְּחוּם שֶׁל אוֹתוֹ בַּיִת. \u0010r25\u0011\nאִם קִבְּלוּ אֲחֵרִים לַחֲרֹשׁ וְלִזְרֹעַ שָׂדֵהוּ, \u0010g27\u0011 יֵשׁ אוֹמְרִים שֶׁמֻּתָּרִין לַחֲרֹשׁ וְלִזְרֹעַ בִּימֵי אֶבְלוֹ שֶׁל בַּעַל הַשָּׂדֶה, \u0010g28\u0011 \u0010r26\u0011 וְיֵשׁ מִי שֶׁאוֹסֵר.\nשְׁנֵי שֻׁתָּפִים חֶנְוָנִים שֶׁאֵרַע אֵבֶל לְאֶחָד מֵהֶם, \u0010g29\u0011 נוֹעֲלִים חֲנוּתָם, שֶׁלֹּא יַעֲשֶׂה \u0010y22\u0011 הַשֻּׁתָּף בְּפַרְהֶסְיָא, אֲבָל יָכוֹל לַעֲשׂוֹת בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ, אֲפִלוּ בְּעֵסֶק \u0010r27\u0011 הַשֻּׁתָּפוּת. וְאִם הָאָבֵל אָדָם חָשׁוּב, וְהַשֻּׁתָּפוּת נִקְרָא עַל שְׁמוֹ, שֶׁאֲפִלוּ אִם יַעֲשֵׂהוּ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ יָדוּעַ שֶּׁיֵּשׁ לָאָבֵל חֵלֶק בּוֹ, אָסוּר לַשֵּׁנִי לַעֲשׂוֹת אֲפִלוּ בְּתוֹךְ בֵּיתוֹ. \u0010g30\u0011\nכְּבוֹד הַבַּיִת, הֲדָחַת כּוֹסוֹת וְהַצָּעַת הַמִּטּוֹת, אֵין בָּהֶם מִשּׁוּם מְלָאכָה לְאָבֵל; \u0010g31\u0011 \u0010r28\u0011 וְכֵן מֻתָּר לְאִשָּׁה לֶאֱפוֹת וּלְבַשֵּׁל בִּימֵי אֶבְלָהּ \u0005כָּל הַצָּרִיךְ לָהּ, אֲבָל מַה שֶּׁאֵינוֹ צָרִיךְ לָהּ אָסוּר;\u0006 \u0010c0\u0011 \u0010g32\u0011 וְכֵן אִשָּׁה הַמְשָׁרֶתֶת בְּבֵית בַּעַל הַבַּיִת אֶחָד, וְאֵרְעָהּ אֵבֶל, מֻתֶּרֶת לֶאֱפוֹת וּלְבַשֵּׁל וְלַעֲשׂוֹת שְׁאָר צָרְכֵי הַבַּיִת, בֵּין שֶׁהִיא מְשָׁרֶתֶת בְּחִנָּם בֵּין \u0010t15\u0011 בְּשָׂכָר. \u0010g33\u0011\nהַהוֹלֵךְ מִמָּקוֹם לְמָקוֹם לִסְחוֹרָה, וְשָׁמַע שְׁמוּעָה קְרוֹבָה, אִם יָכוֹל לְמַעֵט שֶׁלֹּא לַעֲשׂוֹת שׁוּם עֵסֶק בְּאוֹתָהּ הָעִיר, מוּטָב; וְאִם לָאו, שֶׁאִם לֹא יִקְנֶה בְּאוֹתָהּ הָעִיר לֹא יִמָּצֵא, \u0010r29\u0011 יִקְנֶה לְצֹרֶךְ הַדֶּרֶךְ דְּבָרִים שֶׁיֵּשׁ בָּהֶם חַיֵּי נֶפֶשׁ. \u0010g34\u0011\nעַל כָּל הַמֵּתִים, רָצָה לְמַעֵט בְּעֵסֶק סְחוֹרָה הַמֻּתֶּרֶת לוֹ, \u0010g35\u0011 \u0010r30\u0011 כְּגוֹן דָּבָר הָאָבֵד, יְמַעֵט; רָצָה, אֵינוֹ מְמַעֵט. עַל אָבִיו וְאִמּוֹ, יְמַעֵט. \u0010g36\u0011 \u0010r31\u0011\nעַל כָּל הַמֵּתִים אָסוּר עַד ל' יוֹם לֵילֵךְ בִּסְחוֹרָה לְמֵרָחוֹק, דְּאִכָּא פִּרְסוּם גָדוֹל וְדוֹמֶה לְשִׂמְחָה שֶׁהוֹלֵךְ בְּשַׁיָּרָא גְדוֹלָה וּשְׂמֵחִים הַרְבֵּה בַּדֶּרֶךְ; בְּאָבִיו וְאִמּוֹ, עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו וְיֹאמְרוּ: לֵךְ עִמָּנוּ.",{"g":["ברייתא מ\"ק דף כ\"א ע\"א ומייתי לה שם דף ט\"ו ע\"ב מקרא שנאמר והפכתי חגיכם לאבל מה חג אסור בעשיית מלאכה וכו':","\u0003ברייתא שם ע\"ב:\u0004 ","שם בתוספות בשם פי' הרב ושכן הוא משמעות הגמרא שם ושהכי תניא במסכת שמחות וכ\"כ הרמב\"ם שם בפ\"ה וכ\"כ כמעט כל הפוסקים כולם ומפרש בירושל' הטעם משום דכל שלשה ימים הנפש טייסא על גופא סברא דאיהי חזרא גביה כיון דאיהי חזייא דאשתני זווהון דאפויי היא שבקה ואזלה לה ורבינו ירוחם כתב בשם הראב\"ד משום דאמרו חז\"ל ג' לבכי ואם יעסוק במלאכה הוא מתעצל בבכי:","\u0003שם במסכת שמחות:\u0004 ","\u0003לשון הרמב\"ם שם מהירושלמי ומעובדא דגוריון בריה דרבא וכו'\u0004 וציינתיו לקמן בסעיף כ\"א:","\u0003כדיוקא דרב שישא בריה דרב אידי ממתני' דתניא כוותיה מ\"ק דף י\"א הסכמת הפוסקים:\u0004 ","\u0003ברייתא באבל רבתי וכפירוש הרמב\"ן בספר תורת האדם:\u0004 ","\u0003ברייתא שם וכן משמע במ\"ק דף י\"א ע\"ב:\u0004 ","\u0003ברייתא שם:\u0004 ","\u0003הרמב\"ן בסת\"ה והסכים הרא\"ש בפסקיו לדבריו וש\"פ:\u0004 ","\u0003רא\"ש שם בברייתא דלעיל וש\"פ:\u0004 ","\u0003ג\"ז שם וכ\"כ הטור בשמו:\u0004 ","\u0003טור בשם אביו הרא\"ש:\u0004 ","\u0003שם מדברי הרמב\"ן בסת\"ה:\u0004 ","\u0003שם כשם הגאונים וכ\"כ הרמב\"ם בפ\"ה:\u0004 ","\u0003שם בסת\"ה וש\"פ:\u0004 ","\u0003ברייתא מ\"ק דף י\"א ע\"ב וכמ\"ש הראב\"ד בשביל שבעל השדה הוא אבל לא ימנעו מלעבדה:\u0004 ","\u0003הרא\"ש ממשמעות הברייתא וכ' בשם הראב\"ד הטעם משום דארעא לאריסותא קיימא וכו'\u0004 וכיון שזה היה אריס מקודם לכו מסתמא לא מסלק ליה וה\"ל כמי שהיתה אצלו מושכרת מתחלה:","\u0003ברייתא שם:\u0004 ","\u0003שם בברייתא:\u0004 ","מלשון הברייתא שם וכמ\"ש הראב\"ד שבחמור וגמל וספינה הוא דרך בני אדם להחליפו מזה לזה וכל המרבה בשכרו קודם והיוקר והזול לפי הזמנים:","\u0003טור בשם הרמב\"ן:\u0004 ","שם בשם י\"א דשאני ארעא דלאריסותא קיימא ולא נקרא שם בעלים עליה משא\"כ בדברים אחרים וציינתיו לעיל סעיף י\"א:","\u0003שם בברייתא:\u0004 ","שם:","\u0003שם בברייתא:\u0004 ","ל' הטור ממימרא דשמואל וכדמוקים לה רב פפא ורב משרשיא שם דף י\"ב ע\"א וכפירש\"י בלשון ראשון שאע\"פ שקבלו המלאכה בקבולת קודם האבל אסור מפני מראית העין שלא יאמרו ראו זה שמסר מלאכתו לאחרים בימי האבל ולא ידעי דקבולת היא גבייהו:","טור בשם הרמב\"ן בסת\"ה מטעם שציינתיו לעיל סעיף י\"א ואין חוששין לחשד שלאחר זמן כשיראו שהעובד כוכבים יוצא ממנה והישראל אוכל פירות שאין בני אדם פונים מכל עסקיהם לומר חרש זה בכאן והיינו סבורים שהוא אריס וכו':","\u0003שם מטעם חשד הנ\"ל:\u0004 ","\u0003ירושלמי הביאו הרי\"ף בפ\"ב דמ\"ק דאסור לכל ובעובדא דמריון בריה דרבין וכו'\u0004 בבבלי דף י\"א ע\"ב מסיק דבאדם חשוב שאני ותירץ הראב\"ד דבירושלמי איירי בפרהסיא וכ\"כ הרמב\"ם בפ\"ה ובבבלי איירי בביתו:","\u0003בריית' באבל רבתי פרק י\"א וכתבה הרמב\"ן בסת\"ה וש\"פ:\u0004 ","\u0003מהרי\"ק בשורש נ\"ה:\u0004 ","\u0003תרומת הדשן:\u0004 ","\u0003לשון נימוקי יוסף מברייתא מ\"ק ריש דף כ\"ז ומדברי הרמב\"ם בפרק י' מהלכות אבל:\u0004 ","\u0003ברייתא מ\"ק דף כ\"ב ע\"ב:\u0004 ","כפירוש הי\"מ שהביא הנ\"י וכ\"כ התוספות שם ובכ\"מ שם פ\"ו פי' דאחר ז' תוך ל' מיירי דומיא מאי דתנן בפ\"ק דתענית דף י\"ב ע\"ב עברו אלו ולא נענו ממעטין במשא ובמתן:","\u0003ירושלמי סוף מ\"ק הביאו הרא\"ש שם בפסקיו שפירשו כן והביאו הטור:\u0004 "],"t":["\u0003בפלך. \u0004 פי' דאין מתירין לה אלא מלאכה של צינעא ושל עראי כגון להיות טווה בפלך בתוך ביתה. ואם אינה מספקת בזה עושה אומנות שלה בצינעה תוך ביתה. עכ\"ל הטור:","\u0003המועד. \u0004 כמו שנתבאר בא\"ח כו' תקמ\"ה ע\"ש:","\u0003ובניו. \u0004 פי' אפי' הם גדולים אם סמוכים על שלחנו כ\"כ הטור ולבוש ור\"ל כ\"ש קטנים בסמוכים על שלחנו. אבל אם אינם סמוכים על שלחנו אפילו קטנים מעשה ידיהם לעצמן כמ\"ש בח\"מ סי' ע\"ד ס\"ב עכ\"ל הש\"ך:","\u0003בעצמו. \u0004 אפי' הוא דבר שיש בו טרחא ומעשה אומן כ\"מ בש\"ס. ש\"ך. מיהו יעשה בצינעה. שם:","\u0003האבד. \u0004 שאם לא ילוה להם ילכו לאחרים וילוו להם וירגילום לבא אצלם ואיכא פסידא. טור:","\u0003לשדורי. \u0004 כלומר לשלוח אחרים שיתבעו המעות מהם דה\"ל דבר האבוד. ש\"ך:","\u0003חולים. \u0004 ומתיירא שמא ימותו:","\u0003צורך. \u0004 ולא משום דבר האבד וכה\"ג. ש\"ך:","\u0003מותר. \u0004 כתב הש\"ך משום שאין זה נקרא מלאכת האבל אלא של בעל השדה:","\u0003יעשה. \u0004 כיון שאינו אצלו באריסות או בחכירות ובקבלנות. ש\"ך:","\u0003שרי. \u0004 כתב הש\"ך משמע אפי' אינו דבר האבד וכן משמע להדיא בלבוש דאע\"ג דלעיל ס\"ב וס\"ה אסור אפילו ע\"י אחרים מ\"מ הכא מותר ע\"י אחרים והוא יקח השכר מן הבעלים שהרי אין עיקר המלאכה שלו ע\"כ אבל לא נראה כן מדברי הרא\"ש מדמדמי ליה לעני המתפרנס מן הצדקה משמע דאפי' ע\"י אחרים אסור וכו' ע\"ש:","\u0003תלוש. \u0004 שיכול לעשותו בצינעה וכ\"ש דבר מחובר שאינו יכול לעשות אלא בפרהסיא. ש\"ך:","\u0003אחרים. \u0004 והלבוש כתב ונראה דאפי' אינו דבר האבד מותר לעשותו ע\"י אחרים כיון שעיקר המלאכה אינו שלו וכמ\"ש בסי\"ז גבי הוא עצמו מושכר והש\"ך כתב דדעת הרב נראה דדוקא התם שהוא מושכר לחדש או לחדשים שרי משא\"כ הכא. ולפי מ\"ש לעיל דבהוא עצמו מושכר אסור על ידי אחרים אם לא בדבר האבד כ\"ש הכא עכ\"ל:","\u0003מלאכתו. \u0004 כתב ר' ירוחם בשם המפרשים שמכאן יש ללמוד שאם היה לאבל מלמד או סופר או פועל שלא יעשה בביתו. עכ\"ל \u0005(וכ' בה\"י עליו לפי דברי האחרונים שכתבו סי' שפ\"ד שמלמד תינוקות מותר ללמוד עם התינוקות אחר ג' ימים אם אירע אבילות למלמד א\"כ כ\"ש הוא שמותר ללמוד עם התינוקות בתוך ביתו של אחר שאירע לו אבילות)\u0006:","\u0003לתחום. \u0004 אפי' מסרה להם קודם האבל או קודם ח\"ה אסור מפני מראית עין שכיון שיוכלו בני אדם ללכת שם ויראו המלאכה יאמרו ראו זה שמסר מלאכתו לאחרים בימי האבל או בחול המועד ולא ידעי דקבולת הוא גבייהו קודם לכן עכ\"ל הש\"ך:","\u0003בשכר. \u0004 כתב הט\"ז וא\"ל הא כתב בסט\"ז אם האבל מושכר לאחרים לא יעשה מלאכה בימי אבלו דהתם מיירי במלאכה גמורה שאסור לאבל בכל גוני משא\"כ במלאכת צרכי הבית דמותר לאשה עצמה כמ\"ש בסעיף הקודם ע\"כ מותר אפי' למשרתת. אבל עכ\"פ לא תעשה המשרתת מלאכה שאינה לצורך הבית אלא להרויח וכ\"ש שלא תצא מן הבית כדין אבל. וראיתי מי שהורה לשמש שאירע לו אבל שיעשה עבודתו לילך לבהכ\"נ ולשמש בצרכי הקהל ולא יפה הורה דטעה בטעם הדין הזה דהיתר משרתת. וכתב רש\"ל בשם אגודה דאבל מותר להקיז דם וכ' הכל בו דאבל שעושה מלאכה מנדין אותו עכ\"ל:"],"r":["\u0003(ליקוט) אלו כו' ואסור כו'. \u0004עתוס' שם ד\"ה אלו כו' (ע\"כ):","\u0003ואסור בשאלת כו'. \u0004שם ט\"ו:","\u0003ביום כו'. \u0004שם כ\"א:","\u0003ואסור כו'. \u0004כ\"ג א' כ\"ז ב':","\u0003ובתספורת ושמחה ואיחוי כו'. \u0004כ\"ב ב':","\u0003(ליקוט) כל ג' ימים כו'. \u0004אע\"ג דבירושלמי והביאו הרא\"ש שם לת\"ק שני ימים הלכה כבר קפרא שם ובמ\"ש בגמ' דילן דהוא מתניתא דבר קפרא וכן כל ההיא דאיתמר בא\"ר \u0005(פ\"ו ועי\"ל סי' שצ\"ג ס\"ק ב') \u0006ב' ימים לב\"ק הוא שלשה ימים וכן הלכה. תה\"א (ע\"כ):","\u0003אם הוא כו'. \u0004כפסברא ראשונה בתוס' שם ד\"ה מכאן כו' ועבה\"ג:\n\u0003(ליקוט) אם הוא עני כו'. \u0004עתוס' שם ד\"ה מכאן כו' ושם א' ד\"ה אלו כו' (ע\"ב):\n\u0003(ליקוט) מכאן כו'. \u0004ערא\"ש סי' פ\"ד ירושלמי וא\"ר כו' (ע\"כ):","\u0003כשם שהוא כו'. \u0004ע\"ל סכ\"ג ועבה\"ג:","\u0003(ליקוט) בין הוא כו'. \u0004א\"ר רפ\"ה:","\u0003אסור כו'. \u0004שם (ע\"כ):","\u0003אפי' דבר כו'. \u0004עש\"ך והוא דברי הרא\"ש ע\"ש:","\u0003וי\"א כו'. \u0004כרשב\"ג שם זתיו כו' ורי\"ף ורמב\"ם פסקו דלא כוותיה וערא\"ש שם:\n\u0003(ליקוט) וי\"א כו'. \u0004ומיהו בצנעא דוקא. שם (ע\"כ):","\u0003פרקמטיא כו' להלוות כו' אי כו' אם י\"ל כו'. \u0004דע\"י אחרים דינו כמו בחה\"מ ועבא\"ח סי' תקל\"ט:","\u0003כל הדברים כו'. \u0004כנ\"ל ס\"ב מכאן ואילך אם כו' אבל כו' תבא כו' וכמ\"ש בירושלמי. תה\"א:","\u0003אבל ששדהו כו'. \u0004כגי' הראב\"ד ופי' כמ\"ש ברא\"ש:","\u0003ואפילו נשלם כו'. \u0004שזה החילוק בינם לחמרין ע\"ש:","\u0003אם כו' אבל כו'. \u0004כגי' רש\"י ופי' וכ' הרא\"ש דאפשר שגם הראב\"ד יודה בזה:","\u0003אם יש לאבל כו'. \u0004כפי' הראב\"ד וכנ\"ל:","\u0003אם היה כו'. \u0004כפירש\"י \u0005(צ\"ע וגם מ\"ש בס\"ק שאח\"ז צ\"ע):\u0006","\u0003ויש אוסרין. \u0004שהראב\"ד חולק עליו וכנ\"ל ס\"ב:","\u0003אבל ע\"י כו'. \u0004עש\"ך:","\u0003ואם הוא כו'. \u0004כנ\"ל ס\"ח וסי\"ב:","\u0003מותר לקבל כו'. \u0004כמ\"ש בחה\"מ י\"ב א':","\u0003ובלבד כו'. \u0004כנ\"ל סי\"ד:","\u0003ה\"ל בנין כו'. \u0004כן פירש\"י בלשון א' הביאו הרא\"ש וכ\"כ תוס' שם ד\"ה אמר לפי' ר\"ת וחה\"מ ל\"ד ה\"ח חול וערא\"ש וז\"ש בחול כו':","\u0003אם כו'. \u0004י\"א שמותרין כו'. כנ\"ל סי\"א. הרא\"ש שם סל\"ד בשם הדאב\"ד:","\u0003ויש כו'. \u0004כמו בבית וכמ\"ש בא\"ח בסי' רמ\"ד ס\"א לקצור כו':","\u0003ואם האבל כו'. \u0004גמ' שם ועבה\"ג וערא\"ש שם סל\"ג:","\u0003וכן מותר כו' וכן אשה כו'. \u0004כמו בכיבוד כו'. שם ושם:","\u0003(ליקוט) יקנה לצורך כו'. \u0004כן פי' בתה\"א בשם ר\"ח מ\"ש יגלגל עמהם (ע\"כ):","\u0003(ליקוט) כגון כו'. \u0004תוס' כ\"ז אי ד\"ה אם כו' (ע\"כ):","\u0003(ליקוט) על כל כו'. \u0004א\"ר פ\"ט (ע\"כ):\n\u0003(ליקוט) על כו'. \u0004ערא\"ש סי' צ\"ח (ע\"כ):"]}],["רְחִיצָה כֵּיצַד, אָסוּר לִרְחֹץ כָּל גוּפוֹ, אֲפִלוּ בְּצוֹנֵן; אֲבָל פָּנָיו יָדָיו וְרַגְלָיו, בְּחַמִּין, אָסוּר; בְּצוֹנֵן, מֻתָּר. וְאִם הָיָה מְלֻכְלָךְ בְּטִּיט וְצוֹאָה, רוֹחֵץ כְּדַרְכּוֹ וְאֵינוֹ חוֹשֵׁשׁ. \u0005הַגָּה: וְכָל זֶה מִדִּינָא אֵינוֹ אָסוּר רַק שִׁבְעָה, אֲבָל אַחַר כָּךְ מֻתָּר בִּרְחִיצָה, \u0010y0\u0011 \u0010c0\u0011 אֶלָּא שֶׁנָּהֲגוּ הָאִדָּנָא לֶאֱסֹר כָּל רְחִיצָה כָּל ל' יוֹם (מהר\"מ הִלְכוֹת שְׂמָחוֹת ובהגמי\"י פ\"ז מהל' י\"ט ופ\"י דהל' אֵבֶל)\u0006 ; וַאֲפִלּוּ לָחֹף הָרֹאשׁ אָסוּר \u0005(לְקַמָּן סי' ש\"צ ובא\"ז)\u0006 ; וְאֵין לְשַׁנּוֹת הַמִּנְהָג, כִּי מִנְהָג קָדוּם הוּא וְנִתְיַסֵּד עַל פִּי וָתִיקִין \u0005(א\"ז בְּשֵׁם רַשְׁבָּ\"א)\u0006.\nסִיכָה כֵּיצַד, אָסוּר לָסוּךְ אֲפִלוּ כָּל שֶׁהוּא, אִם מְכַוֵּן לְתַעֲנוּג, אֲבָל אִם הוּא לְהַעֲבִיר הַזֻּהֲמָא מֻתָּר; וְאֵין צָרִיךְ לוֹמַר מִשּׁוּם רְפוּאָה, כְּגוֹן שֶׁיֵּשׁ לוֹ חֲטָטִין בְּרֹאשׁוֹ.\nיוֹלֶדֶת אֲבֵלָה \u0010y1\u0011 שֶׁצְּרִיכָה לִרְחֹץ, מֻתָּר. וְכֵן מָאן דְּאִית לֵיהּ עִרְבּוּבְיָא בְּרֵישֵׁיהּ, מֻתָּר לָחֹף רֹאשׁוֹ בְּחַמִּין, דְּלֹא גָרַע מֵאִסְטְנִיס \u0005(פי' קַר הַגּוּף וּמְצֻנָּן)\u0006, שֶׁמֻּתָּר לִרְחֹץ כָּל גוּפוֹ. וְלֹא כָּל מִי שֶׁאָמַר: אִסְטְנִיס אֲנִי, מַתִּירִין לוֹ, אֶלָא דַּוְקָא שֶׁהוּא יָדוּעַ שֶׁהוּא אִסְטְנִיס וּמִתְנַהֵג בִּנְקִיּוּת, וְאִם לֹא יִרְחַץ יִצְטַעֵר הַרְבֵּה וְיָבֹא לִידֵי מֵחוּשׁ.\nמִי שֶׁתְּכָפוּהוּ אֲבֵלָיו, שֶׁאֵרְעוּ שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, מֻתָּר לִרְחֹץ כָּל גוּפוֹ בְּצוֹנֵן.\nנִדָּה שֶׁנִּזְדַּמְּנָה זְמַן טְבִילָתָהּ בִּימֵי אֶבְלָהּ, אֵינָהּ טוֹבֶלֶת \u0005(טוּר בְּשֵׁם ר\"ת וְע\"פ ומהרי\"ק שֹׁרֶשׁ ל\"ה)\u0006. \u0005הַגָּה: \u0010y2\u0011 \u0010c1\u0011 וְכָל שֶׁכֵּן שֶׁאֵינָהּ רוֹחֶצֶת לִלְבֹּשׁ לְבָנִים. אֲבָל מִיָּד אַחַר ז', אַף עַל פִּי שֶׁנָּהֲגוּ אִסּוּר בִּרְחִיצָה כָּל ל', מִכָּל מָקוֹם הִיא מֻתֶּרֶת רַק שֶׁתְּשַׁנֶּה הַרְחִיצָה קְצָת\u0006 \u0005(א\"ז בְּסוֹף הִלְכוֹת אֵבֶל)\u0006, \u0005וְחָלוּק לָבָן תִּלְבֹּש וְסָדִין לָבָן תַּצִּיעַ, שֶׁלֹּא תָּבֹא לִידֵי סָפֵק\u0006 \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ט\"ו)\u0006.\nאִשָּׁה לֹא תִּכְחֹל וְלֹא תְּפַרְקֵס בִּימֵי אֶבְלָהּ, \u0010y3\u0011 שֶׁכָּל אֵלוּ אֲסוּרִים בִּרְחִיצָה. וְאֵשֶׁת אִישׁ אֵינָהּ אֲסוּרָה אֶלָא תּוֹךְ שִׁבְעָה, אֲבָל אַחַר ז' מֻתֶּרֶת בַּכֹּל, כְּדֵי שֶׁלֹּא תִּתְגַנֶּה עַל בַּעֲלָהּ. כַּלָה שֶׁאֵרְעָהּ אֵבֶל תּוֹךְ שְׁלֹשִׁים יוֹם לְחֻפָּתָהּ, מֻתֶּרֶת לְהִתְקַשֵּׁט אֲפִלוּ תּוֹךְ ז'. בּוֹגֶרֶת שֶׁאֵרְעָהּ אֵבֶל, כֵּיוָן שֶׁעוֹמֶדֶת לִנָּשֵׂא, מֻתֶּרֶת בְּכִחוּל וּפִרְקוּס אֲבָל אֲסוּרָה בִּרְחִיצַת חַמִּין כָּל גוּפָהּ; נַעֲרָה אֲבֵלָה, אֲסוּרָה אֲפִלוּ בְּכִחוּל וּפִרְקוּס.",["\u0003אלא שנהגו האידנא לאסור רחיצה כל ל' כו'. \u0004כצ\"ל וכן הוא בעט\"ז ולא כמו שנדפס בספרים כל רחיצה כל ל') דודאי רחיצה בצונן ליכא איסורא כלל:","\u0003שצריכה לרחוץ מותר. \u0004אפילו ביום ראשון מיהו אם אין לה צורך כל כך יש להחמיר ביום ראשון כן כתבו האחרונים:","\u0003וכ\"ש שאינה רוחצת כו'. \u0004כלומר כיון דטבילה דאיכא למ\"ד טבילה בזמנה מצוה אסורה כ\"ש רחיצה ללבוש לבנים ובתשו' משאת בנימין סימן ה' חלק על הרב דדוקא טבילה קי\"ל דאסור כיון שאינו לצורך אבל רחיצה ללבון איכא צורך מצוה הלכך בין בתשע' באב בין בז' ימי אבלה תלביש ותציע כדרכה כשאר ימות השנים והרחיצה צריכה לשנות קצת וכמ\"ש הא\"ז והיינו שלא תרחוץ רק באותו מקום ובין ירכותיה בין בחמין בין בצונן ע\"כ דבריו:","\u0003שכל אלו אסורים כרחיצה. \u0004בכ\"ף כצ\"ל מיהו לענין זה חמור מרחיצה שאסור אחר ז' אם לא באשת איש ורחיצה שרי מדינא לאחר ז' כדלעיל סעיף א':"],["\u0003אלא שנהגו האידנא לאסור רחיצה כל שלשים יום. \u0004באור זרוע נתן טעם למנהג דחיישינן דילמא אתא למסרק רישיה דאסור כל שלשים וא\"כ לדידן דשרי לסרוק ראשו כדאיתא סימן ש\"ץ היה מותר לרחוץ ורש\"ל נתן טעם דאסרו משום תספורת כי כן דרך הנכנס במרחץ לגלח שערות ראשו ע\"כ ואין להקשות א\"כ בחול המועד דאסור תספורת ליהוי נמי רחיצה אסורה מטעם זה נראה ליישב דבח\"ה יש איסור על כל העולם ורבים לא יהיו נכשלים אבל באבילות דאיסור על היחיד הוא יש לחוש שמא ישכח באבילות ויגלח שערו כשאר בני אדם וסברא זו מצינו בפרק חבית (שבת דף קמ\"ו) במשנה אבל עשרה בני אדם ופירש\"י הואיל ומרובים הם מדכרי אהדדי:","\u0003וכ\"ש שאינה רוחצת ללבוש לבנים כו'. \u0004בתשובת מהרי\"ל סימן ט\"ז כתב וז\"ל ואסור בתשמיש המטה ואסור לטבול טבילת מצוה ביוה\"כ ותשעה באב דכדאי הוא בית אלהינו כו' וכן בז' ימי אבילות אבל תוך ל' שרי לטבול ולשמש ואפי' לרחוץ כדי ללבן כ' באור זרוע דשרי רק שתשנה הרחיצה קצת אבל חלוק לבן ודאי תלביש וסדין לבן ודאי תציע שלא תבוא לידי ספק עכ\"ל. כ' אחי הגאון מוהר\"ר יצחק הלוי ז\"ל דהאי אבל חלוק לבן כו' קאי נמי אתוך ז' וכן מבואר בבית יוסף שכתב שתוך ז' שרי לרחוץ רק שתשנה הרחיצ' קצת כו' ורמ\"א כאן הבין שמהרי\"ל כ' אבל חלוק לבן כו' קאי אתוך ל' דוקא משמע דתוך ז' אסור לרחוץ ללבישת ליבון והוא תימה דהא לאו רחיצה של תענוג היא ואמאי אסורה והא דאסו' רחיצה של טבילה היינו שהיא ללא צורך כיון שאסורה בתשמיש אבל רחיצה של ליבון אמאי אסורה ועל כל פנים נ\"ל דגם רמ\"א לא נתכוין כאן לדחות לבישת הליבון לגמרי עד אחר ז' דזה פשיטא שאינו שהרי אפשר לה ללבוש ליבון בלא רחיצה לגמרי כמ\"ש ביורה דעה סי' קצ\"ו סעיף ג' בהג\"ה דאפילו לא רחצה רק פניה של מטה סגי ובשעת הדחק סגי אפילו בלא רחיצה כלל רק שהחלוק נקי כו' ולמה נדחה כאן בחנם לבישת הליבון אלא ודאי שלא נתכוין רמ\"א לדחות לבישת הליבון כלל אלא הרחיצה לחוד הוא דאסור:\n\u0003ושוב \u0004ראיתי בתשו' משאת בנימין סימן ה' דמתיר אפי' לרחוץ בתוך שבעה ללבוש לבנים וחולק על רמ\"א בכאן ודבריו נכונים אלא דמ\"מ למעשה נראה לי דאין לה לרחוץ ללבישת ליבון אלא שתרחץ פניה של מטה ותלבוש חלוק נקי לא לבן ממש ותספור שבעה נקיים כנ\"ל ברור ונכון והמחמיר בזה לדחות לבישת הליבון לגמרי הוא מן המתמיהים:\n\u0003כתב \u0004רש\"ל מהר\"ם היה בעל ברית תוך ל' יום של אביו ורחץ בלילה שלפני המילה ונתן טעם לדבריו דהוה כרגל לגביה דידיה וחומרא בעלמא נהגו אבותינו ברחיצה עכ\"ל:"],"\u0010g0\u0011 רְחִיצָה כֵּיצַד, אָסוּר \u0010g1\u0011 לִרְחֹץ כָּל גוּפוֹ, אֲפִלוּ בְּצוֹנֵן; אֲבָל פָּנָיו יָדָיו וְרַגְלָיו, בְּחַמִּין, אָסוּר; בְּצוֹנֵן, \u0010r0\u0011 מֻתָּר. וְאִם הָיָה מְלֻכְלָךְ בְּטִּיט וְצוֹאָה, רוֹחֵץ כְּדַרְכּוֹ וְאֵינוֹ חוֹשֵׁשׁ. \u0005הַגָּה: \u0010r1\u0011 וְכָל זֶה מִדִּינָא אֵינוֹ אָסוּר רַק שִׁבְעָה, אֲבָל אַחַר כָּךְ מֻתָּר בִּרְחִיצָה, \u0010y0\u0011 \u0010c0\u0011 אֶלָּא שֶׁנָּהֲגוּ \u0010t0\u0011 הָאִדָּנָא לֶאֱסֹר כָּל רְחִיצָה כָּל ל' יוֹם (מהר\"מ הִלְכוֹת שְׂמָחוֹת ובהגמי\"י פ\"ז מהל' י\"ט ופ\"י דהל' אֵבֶל)\u0006 ; וַאֲפִלּוּ לָחֹף הָרֹאשׁ אָסוּר \u0005(לְקַמָּן סי' ש\"צ ובא\"ז)\u0006 ; וְאֵין לְשַׁנּוֹת הַמִּנְהָג, כִּי מִנְהָג קָדוּם הוּא וְנִתְיַסֵּד עַל פִּי וָתִיקִין \u0005(א\"ז בְּשֵׁם רַשְׁבָּ\"א)\u0006. \u0010g2\u0011\nסִיכָה כֵּיצַד, אָסוּר לָסוּךְ אֲפִלוּ כָּל שֶׁהוּא, אִם מְכַוֵּן לְתַעֲנוּג, אֲבָל אִם הוּא לְהַעֲבִיר \u0010g3\u0011 \u0010r2\u0011 הַזֻּהֲמָא מֻתָּר; וְאֵין צָרִיךְ לוֹמַר מִשּׁוּם רְפוּאָה, כְּגוֹן שֶׁיֵּשׁ לוֹ חֲטָטִין בְּרֹאשׁוֹ. \u0010g4\u0011 \u0010r3\u0011\nיוֹלֶדֶת אֲבֵלָה \u0010y1\u0011 שֶׁצְּרִיכָה \u0010g5\u0011 \u0010t1\u0011 לִרְחֹץ, מֻתָּר. וְכֵן מָאן דְּאִית לֵיהּ עִרְבּוּבְיָא בְּרֵישֵׁיהּ, מֻתָּר לָחֹף רֹאשׁוֹ בְּחַמִּין, דְּלֹא גָרַע מֵאִסְטְנִיס \u0005(פי' קַר הַגּוּף וּמְצֻנָּן)\u0006, שֶׁמֻּתָּר לִרְחֹץ כָּל גוּפוֹ. \u0010g6\u0011 \u0010r4\u0011 וְלֹא כָּל מִי שֶׁאָמַר: אִסְטְנִיס אֲנִי, מַתִּירִין לוֹ, אֶלָא דַּוְקָא שֶׁהוּא יָדוּעַ שֶׁהוּא אִסְטְנִיס וּמִתְנַהֵג בִּנְקִיּוּת, וְאִם לֹא יִרְחַץ \u0010g7\u0011 יִצְטַעֵר הַרְבֵּה וְיָבֹא לִידֵי \u0010g8\u0011 מֵחוּשׁ.\nמִי שֶׁתְּכָפוּהוּ אֲבֵלָיו, שֶׁאֵרְעוּ שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, מֻתָּר לִרְחֹץ כָּל גוּפוֹ בְּצוֹנֵן. \u0010g9\u0011 \u0010r5\u0011\nנִדָּה שֶׁנִּזְדַּמְּנָה זְמַן טְבִילָתָהּ בִּימֵי אֶבְלָהּ, אֵינָהּ טוֹבֶלֶת \u0005(טוּר בְּשֵׁם ר\"ת וְע\"פ ומהרי\"ק שֹׁרֶשׁ ל\"ה)\u0006. \u0005הַגָּה: \u0010y2\u0011 \u0010c1\u0011 וְכָל שֶׁכֵּן שֶׁאֵינָהּ רוֹחֶצֶת לִלְבֹּשׁ לְבָנִים. אֲבָל מִיָּד אַחַר ז', אַף עַל פִּי שֶׁנָּהֲגוּ אִסּוּר בִּרְחִיצָה כָּל ל', מִכָּל מָקוֹם הִיא מֻתֶּרֶת רַק שֶׁתְּשַׁנֶּה הַרְחִיצָה קְצָת\u0006 \u0005(א\"ז בְּסוֹף הִלְכוֹת אֵבֶל)\u0006, \u0005וְחָלוּק לָבָן תִּלְבֹּש וְסָדִין לָבָן תַּצִּיעַ, שֶׁלֹּא תָּבֹא לִידֵי סָפֵק\u0006 \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ט\"ו)\u0006. \u0010g10\u0011\nאִשָּׁה לֹא תִּכְחֹל וְלֹא תְּפַרְקֵס בִּימֵי אֶבְלָהּ, \u0010y3\u0011 שֶׁכָּל אֵלוּ אֲסוּרִים \u0010g11\u0011 \u0010r6\u0011 בִּרְחִיצָה. וְאֵשֶׁת אִישׁ אֵינָהּ אֲסוּרָה אֶלָא תּוֹךְ שִׁבְעָה, אֲבָל אַחַר ז' מֻתֶּרֶת בַּכֹּל, כְּדֵי שֶׁלֹּא תִּתְגַנֶּה עַל בַּעֲלָהּ. \u0010g12\u0011 כַּלָה שֶׁאֵרְעָהּ אֵבֶל תּוֹךְ שְׁלֹשִׁים יוֹם לְחֻפָּתָהּ, מֻתֶּרֶת לְהִתְקַשֵּׁט אֲפִלוּ תּוֹךְ ז'. \u0010g13\u0011 \u0010r7\u0011 בּוֹגֶרֶת שֶׁאֵרְעָהּ אֵבֶל, כֵּיוָן שֶׁעוֹמֶדֶת \u0010r8\u0011 לִנָּשֵׂא, מֻתֶּרֶת בְּכִחוּל וּפִרְקוּס אֲבָל אֲסוּרָה בִּרְחִיצַת חַמִּין כָּל גוּפָהּ; \u0010g14\u0011 נַעֲרָה אֲבֵלָה, אֲסוּרָה אֲפִלוּ בְּכִחוּל וּפִרְקוּס.",{"g":["ברייתא מ\"ק דף ט\"ו ע\"ב ויליף לה שנאמר התאבלי נא ולבשי בגדי אבל ואל תסוכי שמן ורחיצה בכלל סיכה ופירש רש\"י שנאמר ותבא כמים בקרבו וכשמן בעצמותיו והרמב\"ם שם בפ\"ה שהרחיצה קודמת לסיכה שנאמר ורחצת וסכת:","\u0003מסקנת הגמ' תענית דף י\"ג ע\"ב:\u0004 ","\u0003ג\"ז מסקנת הגמרא שם:\u0004 ","\u0003הרמב\"ן בסת\"ה:\u0004 ","\u0003הרא\"ש שם במ\"ק בשם ר\"י ממשנה מעשה דר\"ג שרחץ וכו'\u0004 ברכות דף ט\"ו ע\"ב:","\u0003שם בתוס':\u0004 ","\u0003רמב\"ן בסת\"ה וטור בשם רב האי גאון:\u0004 ","\u0003כן פי' הרמב\"ן שם דבריו:\u0004 ","\u0003אוקימתא דגמרא תענית דף י\"ג ע\"א וע\"ב:\u0004 ","סתמא בברייתא שם דטובלין ופלוגתא דתנאי בברייתא בסוף יומא וכתבו התוס' בביצה דף י\"ח ע\"ב דהאידנא כל טבילות שנשותינו טובלות הם שלא בזמנם שהן סופרות שבעה נקיים מספק אם כן דוקא בימיהם שהיו עוסקים בטהרות היו צריכים לטבול מיד כדי שלא יטמאו את הטהרות אבל הטבילה דהשתא דאינה באה אלא לטהרה לבעלה וכו' דהא אפילו תטבול ביה\"כ ובט\"ב אסורה לבעלה אין טובלין לא ביה\"כ ולא בתשעה באב:","\u0003ברייתא כתובות דף ד' ע\"ב ומ\"ק דף כ' ע\"ב:\u0004 ","טור מדברי הרא\"ש בריש כתובות דמשמע באבל רבתי דכל דין ל' היינו גיהוץ ותספורת אינו נוהג בא\"א:","\u0003ברייתא אין מונעין מן הכלה וכו'\u0004 כתובות דף ד' ע\"א וכפי' הרא\"ש:","שם:","\u0003תענית דף י\"ג ע\"ב:\u0004 "],"t":["\u0003לאסור רחיצה כל ל' וכו'. \u0004 כצ\"ל וכן הוא בלבוש. ולא כמו שנדפס בספרים כל רחיצה כל ל' דודאי רחיצה בצונן ליכא איסורא כלל עכ\"ל הש\"ך \u0005(בא\"ז נתן טעם למנהג דחיישינן דילמא אתי למסרק רישיה דאסור כל ל' וא\"כ לדידן דשרי למסרק רישיה כדאיתא סי' ש\"צ ע\"ש היה מותר לרחוץ. ורש\"ל נתן טעם דאסרו משום תספורת כי כן דרך הנכנס למרחץ לגלח שערות ראשו. ט\"ז. וע\"ש עוד)\u0006:","\u0003מותר. \u0004 אפילו ביום ראשון מיהו אם אין לה צורך כ\"כ יש להחמיר ביום ראשון. ש\"ך:"],"r":["\u0003ואם היה כו'. \u0004כמ\"ש ביה\"כ ביומא ע\"ז ב' ועתוס' דברכות ט\"ז ב' ד\"ה אסטניס כו':","\u0003וכ\"ז מדינא כו'. \u0004כמש\"ש י\"ט ב' אבל כיון כו':","\u0003ואצ\"ל כו'. \u0004דאפילו ביה\"כ דאסור סיכה שאינו של תענוג כמ\"ש כירושלמי \u0005(פ' בתרא דיומא וש\"מ) \u0006אפ\"ה מותר בכה\"ג כמ\"ש בגמ' ביומא שם:\n\u0003(ליקוט) ואצ\"ל כו'. \u0004ירושלמי \u0005(פ\"ב דברכות ופ\"ג דמ\"ק) \u0006הדא דתימא ברחיצה של תענוג אבל ברחיצה שאינה של תענוג עלו לו חטטין מותר (ע\"כ):","\u0003(ליקוט) יולדת כו'. \u0004עבה\"ג ובירושלמי ספ\"ב דברכות \u0005(ופ\"ג דמ\"ק) \u0006אבל אסור ברחיצה כל שבעה הדא דתימא ברחיצה של תענוג אבל רחיצה שאינה של תענוג מותר כהדא דשמואל עלו בו חטטים אתא שייליה לר' אסי א\"ל מהו דאסחי א\"ל יסחי במה אנן קיימין אם בדבר שיש בו סכנה אפילו בט' באב אפילו ביה\"כ נמי אלא בשאין בו סכנה \u0005(כ\"ה ברא\"ש שם) \u0006וז\"ש וכן מאן כו' וכ' שם הרא\"ש ודלא כמו שפר\"ח דאסטניס היינו מסוכן כו' אבל הרמב\"ן פי' דברי ר\"ח היינו מצטער הרבה וכמ\"ש למטה ואם לא ירחץ כו':","\u0003ולא כל כו'. \u0004כן כתב ג\"כ הרא\"ש שם בשם הר\"ח ועבה\"ג (ע\"כ):","\u0003נדה כו'. \u0004עמ\"ש בא\"ח סי' תקנ\"ט:","\u0003ואשת איש כו'. \u0004ע\"ל סי' ש\"צ ס\"ה:","\u0003(ליקוט) בוגרת כו' נערה כו'. \u0004עתוס' שם ד\"ה אין כו' (ע\"כ):","\u0003אבל אסורה כו'. \u0004גמ' שם:"]}],["\u0005(אָבֵל)\u0006 אָסוּר בִּנְעִילַת הַסַנְדָּל, דַּוְקָא שֶׁל עוֹר; אֲבָל בְּאַנְפִּלְיָא שֶׁל בֶּגֶד אוֹ שֶׁל גֻמִּי אוֹ שֶׁל שֵׂעָר אוֹ שֶׁל עֵץ, מֻתָּר, שֶׁאֵין מִנְעָל אֶלָא שֶׁל עוֹר. וְאִם הוּא שֶׁל עֵץ וּמְחֻפֶּה עוֹר, אָסוּר. \u0010y0\u0011\nחַיָּה מֻתֶּרֶת לִנְעֹל כָּל ל' יוֹם, מִפְּנֵי שֶׁהַצִּנָּה קָשָׁה לָהּ. \u0010c0\u0011\nכָּל אָדָם מֻתָּר לִנְעֹל בְּמָקוֹם שֶׁיֵּשׁ סַכָּנַת עַקְרָב.\nאָבֵל וּמְנֻדֶּה שֶׁהָיוּ מְהַלְכִים בַּדֶּרֶךְ, מֻתָּרִים בִּנְעִילַת הַסַנְדָּל, וּכְשֶׁיַּגִיעוּ לָעִיר, חוֹלְצִין. \u0010y1\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאִם הִיא עִיר שֶׁרֻבָּהּ עוֹבְדֵי כּוֹכָבִים, אֵין חוֹלְצִין עַד שֶׁיִּכָּנְסוּ לִרְחוֹב הַיְּהוּדִים.\nאִם צָרִיךְ לַחֲלֹץ מִנְעָל בְּבֵית הַקְבָרוֹת אַחַר שֶׁנִּקְבַּר הַמֵּת, נִתְבָּאֵר בְּסִימָן שע\"ה. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁצָּרִיךְ לֵילֵךְ יָחֵף מִבֵּית הַקְּבָרוֹת לְבֵיתוֹ אִם מֵת אָבִיו אוֹ אִמּוֹ (כָּל בּוֹ בְּשֵׁם ר\"י)\u0006, \u0010y2\u0011 וְלֹא רָאִיתִי נוֹהֲגִין כֵּן.",["\u0003חיה כו'. \u0004וה\"ה חולה ומי שיש לו מכה ברגלו כדאיתא בא\"ח סימן תרי\"ד ס\"ג:","\u0003ויש מי שאומר כו'. \u0004וכתב הרב בא\"ח סימן תקנ\"ד סעיף י\"ז שכן נהגו:","\u0003ולא ראיתי נוהגים כן. \u0004היינו משום רשעת העובדי כוכבים כדאיתא בכל בו בעל דין זה ובזה נסתלקה תמיהת הב\"ח על הרב ע\"ש מיהו היכא דליכא חשש דרשעת העובדי כוכבים יש לחלוץ מיד בבית הקברות כדלעיל ר\"ס שע\"ה וסימן שע\"ו ס\"ד:"],["\u0003כל אדם מותר לנעול במקום שיש סכנת עקרב. \u0004לפי מה שכתב המרדכי סוף מועד קטן דאם הולך לפני השר ויש הקפדה עליו אם ילך בלא מנעלים יתן עפר במנעליו וילך עכ\"ל. הוא הדין במקום סכנה ובכל מקום שצריך לילך במנעלים יעשה כן:"],"\u0010g0\u0011 \u0005(אָבֵל)\u0006 אָסוּר בִּנְעִילַת הַסַנְדָּל, \u0010g1\u0011 \u0010r0\u0011 דַּוְקָא שֶׁל עוֹר; אֲבָל בְּאַנְפִּלְיָא שֶׁל בֶּגֶד אוֹ שֶׁל גֻמִּי אוֹ שֶׁל שֵׂעָר אוֹ שֶׁל עֵץ, מֻתָּר, שֶׁאֵין מִנְעָל אֶלָא שֶׁל עוֹר. וְאִם הוּא שֶׁל עֵץ וּמְחֻפֶּה עוֹר, אָסוּר. \u0010y0\u0011 \u0010g2\u0011 \u0010t0\u0011\nחַיָּה מֻתֶּרֶת לִנְעֹל כָּל ל' יוֹם, מִפְּנֵי שֶׁהַצִּנָּה קָשָׁה לָהּ. \u0010c0\u0011 \u0010g3\u0011\nכָּל אָדָם מֻתָּר לִנְעֹל בְּמָקוֹם שֶׁיֵּשׁ סַכָּנַת עַקְרָב. \u0010g4\u0011 \u0010r1\u0011\nאָבֵל וּמְנֻדֶּה שֶׁהָיוּ מְהַלְכִים בַּדֶּרֶךְ, מֻתָּרִים בִּנְעִילַת הַסַנְדָּל, וּכְשֶׁיַּגִיעוּ לָעִיר, חוֹלְצִין. \u0010y1\u0011 \u0010g5\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאִם הִיא עִיר שֶׁרֻבָּהּ עוֹבְדֵי כּוֹכָבִים, אֵין חוֹלְצִין עַד שֶׁיִּכָּנְסוּ לִרְחוֹב \u0010t1\u0011 הַיְּהוּדִים.\nאִם צָרִיךְ לַחֲלֹץ מִנְעָל בְּבֵית הַקְבָרוֹת אַחַר שֶׁנִּקְבַּר הַמֵּת, נִתְבָּאֵר בְּסִימָן שע\"ה. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁצָּרִיךְ לֵילֵךְ יָחֵף מִבֵּית הַקְּבָרוֹת לְבֵיתוֹ אִם מֵת אָבִיו אוֹ אִמּוֹ (כָּל בּוֹ בְּשֵׁם ר\"י)\u0006, \u0010y2\u0011 \u0010r2\u0011 וְלֹא \u0010t2\u0011 רָאִיתִי נוֹהֲגִין כֵּן.",{"g":["\u0003ברייתא מ\"ק דף ט\"ו ע\"ב ויליף מדקאמר ליה רחמנא ליחזקאל ונעליך תשים ברגליך מכלל דלכ\"ע אסור:\u0004 ","\u0003רמב\"ן בסת\"ה ויליף לה מדין איסור נעילת הסנדל ביוה\"כ וציינתיו בא\"ח בסי' תרי\"ד:\u0004 ","\u0003ג\"ז הרמב\"ן שם וגמר לה מיוה\"כ:\u0004 ","\u0003ג\"ז שם:\u0004 ","\u0003ברייתא באבל רבתי:\u0004 ","\u0003הרמב\"ן בסת\"ה וכ\"כ המרדכי:\u0004 "],"t":["\u0003חיה. \u0004 וה\"ה חולה ומי שיש לו מכה ברגלו כמ\"ש בא\"ח סימן תרי\"ד ס\"ג. ש\"ך:","\u0003היהודים. \u0004 וכתב הרב בא\"ח סי' תקנ\"ד סי\"ז שכן נהגו:","\u0003ראיתי. \u0004 היינו משום רשעת העובדי כוכבים מיהו היכא דליכא חשש דרשעת העובדי כוכבים יש לחלוץ מיד בבה\"ק כדלעיל ר\"ס שע\"ה וסי' שע\"ו עכ\"ל הש\"ך. וכתב הט\"ז דלפי מ\"ש המרדכי דאם הולך לפני השר ויש הקפדה עליו אם ילך בלא מנעלים יתן עפר במנעליו וילך ע\"כ ה\"ה במקום סכנה ובכ\"מ שצריך לילך במנעלים יעשה כן. וכתב עוד בסי' שפ\"א בשם אחיו הגאון מוהר\"י דיש להתיר לאשה רחיצת הליבון אפי' תוך ז' ומ\"ש רמ\"א דתוך ז' אסור לרחוץ ללבישת ליבון הוא תימה דהא לאו רחיצה של תענוג היא והא דאסור רחיצה של טבילה מפני שהיא ללא צורך כיון שאסורה בתשמיש המטה אבל רחיצה של ליבון אמאי תיאסר ועכ\"פ נראה דגם רמ\"א לא נתכוין אלא שלא תרחוץ שהרי אפשר לה ללבוש לבנים בלא רחיצה לגמרי רק שהחלוק יהיה נקי כמ\"ש בסי' קצ\"ו ס\"ג בהג\"ה דבשעת הדחק סגי בהכי ובתשובת מ\"ב מתיר אפי' לרחוץ בתוך ז' ללבוש לבנים וחולק על הרמ\"א אלא דמ\"מ למעשה נ\"ל דלא תרחוץ אלא פנים של מטה ותלבוש חלוק נקי לא לבן ממש והמחמיר בזה לדחות לבישת הליבון לגמרי הוא מן המתמיהים עכ\"ל. וכתב מהרש\"ל מהר\"ם היה בעל ברית תוך שלשים יום של אביו ורחץ בלילה שלפני המילה ונתן טעם דהוה כרגל לגביה דידיה וחומרא בעלמא נהגו אבותינו ברחיצה ע\"כ:"],"r":["\u0003דוקא כו'. \u0004כמו ביוה\"כ ועי' כל זה בא\"ח סי' תרי\"ד:","\u0003(ליקוט) אבל כו'. \u0004א\"ר פ\"ה הלכה י' (וירושלמי פ\"ב דברכות וש\"מ) (ע\"כ):","\u0003ולא ראיתי כו'. \u0004כנ\"ל ס\"ד ויש כו' (ועש\"ך):"]}],["אָבֵל אָסוּר בְּתַשְׁמִישׁ הַמִּטָּה, אֲבָל בִּשְׁאָר דְּבַר קֻרְבָה מֻתָּר, אֲפִלוּ בִּמְזִיגַת הַכּוֹס וְהַצָּעַת הַמִּטָּה וְהַרְחָצַת פָּנָיו יָדָיו וְרַגְלָיו, \u0010y0\u0011 בֵּין בַּאֲבֵלוּת דִּידֵהּ בֵּין בַּאֲבֵלוּת דִּידָהּ. \u0005אֲבָל חִבּוּק וְנִשּׁוּק יֵשׁ לְהַחְמִיר (רַבֵּנוּ יְרוּחָם)\u0006. וּמֻתֶּרֶת לֶאֱכֹל עִמּוֹ בִּקְעָרָה. וּמֻתֶּרֶת לִישַׁן עִמּוֹ \u0010y1\u0011 הוּא בְּבִגְדּוֹ וְהִיא בְּבִגְדָּהּ; וּמִיהוּ מִשּׁוּם לֵךְ לֵךְ אַמְרִינָן נְזִירָא יֵשׁ לְהַחְמִיר שֶׁלֹּא יִישַׁן \u0005(עִמָּהּ)\u0006 בְּמִטָּה כְּלָל.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר אֲבֵלוּת; \u0010y2\u0011 אֲבָל אִם מֵת אָבִיו שֶׁל חָתָן אוֹ אִמָּהּ שֶׁל כַּלָה, שֶׁמַּכְנִיסִין אֶת הַמֵּת לַחֶדֶר וְאֶת הֶחָתָן וְאֶת הַכַּלָה לַחֻפָּה, וּבוֹעֵל בְּעִילַת מִצְוָה וּפוֹרֵשׁ וְנוֹהֲגִים ז' יְמֵי הַמִּשְׁתֶּה, וְאַחַר כָּךְ שִׁבְעַת יְמֵי אֲבֵלוּת, אָסוּר לְהִתְיַחֵד עִמָּהּ כָּל י\"ד יוֹם, אֶלָא הוּא יָשֵׁן בֵּין הָאֲנָשִׁים וְהִיא יְשֵׁנָה בֵּין הַנָּשִׁים, כִּדְאִיתָא בְּסִימָן שמ\"ב. אֲבָל אִם כָּנַס לַחֻפָּה וְהִתְחִילוּ יְמֵי הַמִּשְׁתֶּה שֶׁלוֹ, וְאַחַר כָּךְ מֵת לוֹ מֵת, מֻתָּר לְהִתְיַחֵד עִמָּהּ כְּמוֹ בִּשְׁאָר אֲבֵלוּת, וְהוּא שֶׁבָּעַל; אֲבָל אִם לֹא בָּעַל, אָסוּר לְהִתְיַחֵד עִמָּהּ כָּל יְמֵי הָאֵבֶל, בֵּין בְּחֹל בֵּין בְּשַׁבָּת.",["\u0003בין באבילות דידיה כו'.\u0004 כ' הפרישה פירוש אפילו באבילות דידה דאיכא למיחש יותר הואיל והוא אינו אבל דהכל ממנו ולא ממנה עכ\"ל ולא דק דאדרבה באבילות דידיה איכא למיחש יותר דאם יצרו מתגבר עליו נשמעת לו דכיון דאינה אבלה כדאיתא בפ\"ק דכתובות דף ד' ע\"ש):","\u0003הוא בבגדו כו'. \u0004אבל בלא בגדים אסור אפי' סינר מפסיק אפילו בשבת ורגל. טור ורמב\"ן:","\u0003אבל אם מת כו'. \u0004דכיון שהקילו לו רבנן והתירו לו לנהוג ז' ימי המשתה תחלה חיישינן דאתי לזלזולי ביה אבל אם כנס כבר לחופה כו' ליכא למיחש דאתי לזלזולי שהרי לא הקילו לו כלום שקדמו להן ימי החופה. וכן מי שאירעו אבל ברגל מותר לו להתייחד כמ\"ש הרב לקמן סימן שצ\"ט ס\"ב שהרי לא הקילו לו שום דבר אלא הרגל מעצמו הוא שנקבע וגם לית ביה אפושי שמחה כל כך כמו חתן כ\"כ הפוסקים:"],[],"\u0010g0\u0011 אָבֵל אָסוּר בְּתַשְׁמִישׁ הַמִּטָּה, \u0010g1\u0011 \u0010r0\u0011 אֲבָל בִּשְׁאָר דְּבַר קֻרְבָה מֻתָּר, אֲפִלוּ בִּמְזִיגַת הַכּוֹס וְהַצָּעַת הַמִּטָּה וְהַרְחָצַת פָּנָיו יָדָיו וְרַגְלָיו, \u0010y0\u0011 בֵּין בַּאֲבֵלוּת דִּידֵהּ בֵּין בַּאֲבֵלוּת דִּידָהּ. \u0010g2\u0011 \u0005אֲבָל חִבּוּק וְנִשּׁוּק יֵשׁ לְהַחְמִיר (רַבֵּנוּ יְרוּחָם)\u0006. \u0010g3\u0011 \u0010r1\u0011 וּמֻתֶּרֶת לֶאֱכֹל עִמּוֹ בִּקְעָרָה. \u0010r2\u0011 וּמֻתֶּרֶת לִישַׁן עִמּוֹ \u0010y1\u0011 הוּא \u0010t0\u0011 בְּבִגְדּוֹ וְהִיא בְּבִגְדָּהּ; וּמִיהוּ מִשּׁוּם לֵךְ לֵךְ אַמְרִינָן נְזִירָא יֵשׁ לְהַחְמִיר שֶׁלֹּא יִישַׁן \u0010g4\u0011 \u0005(עִמָּהּ)\u0006 בְּמִטָּה כְּלָל.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר אֲבֵלוּת; \u0010y2\u0011 \u0010g5\u0011 אֲבָל אִם מֵת אָבִיו שֶׁל חָתָן אוֹ אִמָּהּ שֶׁל כַּלָה, שֶׁמַּכְנִיסִין אֶת הַמֵּת לַחֶדֶר וְאֶת הֶחָתָן וְאֶת הַכַּלָה לַחֻפָּה, וּבוֹעֵל בְּעִילַת מִצְוָה וּפוֹרֵשׁ וְנוֹהֲגִים ז' יְמֵי הַמִּשְׁתֶּה, וְאַחַר כָּךְ שִׁבְעַת יְמֵי אֲבֵלוּת, \u0010g6\u0011 אָסוּר לְהִתְיַחֵד עִמָּהּ כָּל י\"ד יוֹם, אֶלָא הוּא יָשֵׁן בֵּין הָאֲנָשִׁים וְהִיא יְשֵׁנָה בֵּין הַנָּשִׁים, כִּדְאִיתָא בְּסִימָן שמ\"ב. \u0010g7\u0011 \u0010r3\u0011 אֲבָל אִם כָּנַס לַחֻפָּה וְהִתְחִילוּ יְמֵי הַמִּשְׁתֶּה שֶׁלוֹ, וְאַחַר כָּךְ מֵת לוֹ מֵת, מֻתָּר לְהִתְיַחֵד עִמָּהּ כְּמוֹ בִּשְׁאָר אֲבֵלוּת, \u0010g8\u0011 וְהוּא שֶׁבָּעַל; אֲבָל אִם לֹא בָּעַל, אָסוּר לְהִתְיַחֵד עִמָּהּ כָּל יְמֵי הָאֵבֶל, בֵּין בְּחֹל בֵּין בְּשַׁבָּת.",{"g":["מ\"ק דף ט\"ו ע\"ב ומייתי לה מדכתיב וינחם דוד את בת שבע אשתו ויבא אליה מכלל דמעיקרא אסור:","\u0003טור בשם הראב\"ד בספר בעלי הנפש מברייתא כתובות דף ג' ע\"ב:\u0004 ","\u0003רבינו ירוחם:\u0004 ","\u0003שם בשם הראב\"ד משמעתא דכתובות שם:\u0004 ","\u0003כן הוא בטור:\u0004 ","\u0003ציינתיו לעיל בסי' שמ\"ב:\u0004 ","ומפרש שם בגמרא כיון דאקילו בה רבנן דקתני נוהג ז' ימי המשתה תחלה קילא להו ואתי לזלוזולי ביה:","\u0003הכי משמע שם כיון דליכא הכא שום קולא כי נהוג ז' ימי המשתה תחלה:\u0004 ","\u0003מימרא דרב יוסף כתובות דף ד' ע\"א:\u0004 "],"t":["\u0003בבגדו. \u0004 אבל בלא בגדים אסור אפי' סינר מפסיק אפי' בשבת ורגל. טור ורמב\"ן:"],"r":["\u0003אבל בשאר כו'. \u0004כתובות ד' ב' וה\"ה לכ\"ד דחמירא ליה מנדה כמש\"ש:","\u0003ומותרת כו'. \u0004אע\"ג דאסור בנדה בפ\"ק דשבת \u0005(במתני' י\"א א'):\u0006","\u0003ומותרת לישן כו'. \u0004דהא אף בנדה איבעיא להו שם \u0005(י\"ג א') \u0006בתחלה:","\u0003אבל כו'. \u0004הרא\"ש שם ועבה\"ג:"]}],["אָבֵל, כָּל שִׁבְעָה יָמִים \u0010y0\u0011 אָסוּר לִקְרוֹת בְּתוֹרָה, נְבִיאִים וּכְתוּבִים, מִשְׁנָה, גְמָרָא, הֲלָכוֹת וְאַגָדוֹת. \u0010y1\u0011 \u0010c0\u0011 וְאִם רַבִּים צְרִיכִים לוֹ לְהִתְלַמֵּד, מֻתָּר, וּבִלְבַד שֶׁלֹּא יַעֲמִיד תֻּרְגְמָן אֶלָא יֹאמַר לְאַחֵר, וְהָאַחֵר לַתֻּרְגְמָן, וְתֻרְגְמָן יַשְׁמִיעַ לָרַבִּים. \u0005הַגָּה: אוֹ יִדְרֹשׁ בְּעַצְמוֹ (מָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006. וְיָכוֹל לִפְסֹק אִסּוּר וְהֶתֵּר לְיָחִיד הַשּׁוֹאֵל אוֹתוֹ, אִם אֵין אַחֵר אֶלָּא הוּא, וּצְרִיכִין לוֹ \u0005(בא\"ז וְר' יְרוּחָם)\u0006. אָבֵל אָסוּר לוֹמַר הֲלָכָה לְתַלְמִידָיו, וְכֵן נוֹהֲגִין, אַף עַל פִּי שֶׁיֵּשׁ מְקִלִּין \u0005(תא\"ו בְּשֵׁם י\"א)\u0006.\nאִם הָאָבֵל כֹּהֵן, וְאֵין בב\"ה כֹּהֵן אַחֵר, \u0010y2\u0011 אָסוּר לוֹ לַעֲלוֹת לִקְרוֹת בַּתּוֹרָה.\nאִם אֵין שָׁם מִי שֶׁיִּתְפַּלֵל לְהוֹצִיא אֶת הָרַבִּים יְדֵי חוֹבָתָן, יָכוֹל הָאָבֵל לְהִתְפַּלֵל לְהוֹצִיאָן. \u0005הַגָּה: \u0010y3\u0011 וּמִצְוָה לְהִתְפַּלֵּל שַׁחֲרִית וְעַרְבִית בַּמָּקוֹם שֶׁמֵּת שָׁם, אֲפִלּוּ אֵין אָבֵל, כִּי יֵשׁ בָּזֶה נַחַת רוּחַ לַנְּשָׁמָה (א\"ז)\u0006, וְהָאָבֵל מִצְטָרֵף לְמִנְיָן \u0005(שָׁם)\u0006.\nאָבֵל מֻתָּר לִקְרוֹת בְּאִיּוֹב וּבְקִינוֹת וּבִדְבָרִים הָרָעִים שֶׁבְּיִרְמִיָּה וּבְהִלְכוֹת אֲבֵלוּת \u0005וְעַיֵּן בא\"ח סִימָן תקנ\"ד סָעִיף ב'.\u0006 וְהָנֵי מִלֵי בֵּינוֹ לְבֵין עַצְמוֹ, אֲבָל אֵינוֹ לוֹמֵד עִם אֲחֵרִים, אֶלָא הֵם יוֹשְׁבִים וְנוֹשְׂאִים וְנוֹתְנִין בְּהִלְכוֹת אֲבֵלוּת, וְאִם טָעוּ מְשִׁיבָן בְּשָׂפָה רָפָה, וְהוּא אֵינוֹ שׁוֹאֵל. וְהָנֵי מִלֵי כְּשֶׁאֵין רַבִּים צְרִיכִים לוֹ, אֲבָל אִם רַבִּים צְרִיכִים לוֹ, אֲפִלוּ בַּהֲלָכוֹת אֲחֵרוֹת מֻתָּר, כִּדְאָמְרִינַן.\nאָבֵל שֶׁיֵּשׁ לוֹ בָּנִים קְטַנִּים, \u0010y4\u0011 אֵין לוֹ לְבַטְּלָם מִלִמּוּדָם.",["\u0003אסור לקרות בתורה. \u0004דכתיב פקודי ה' ישרים משמחי לב:","\u0003ואם רבים צריכים כו'. \u0004כתוב בבדק הבית בשם א\"ח מלמדי תינוקות י\"ל שדינן כרבים צריכים לו ועוד דמלאכת האבד הוא כשהתינוקות בטלים ע\"כ וכן כתב מהרש\"ל בתשובה סימן ס\"ו ע\"ש:","\u0003אסור לו כו'. \u0004כתב הב\"ח ותימה דבסימן ת' בדין שבת כ' הרב דבאין שם כהן אחר אלא הוא מותר לקרותו וכאן לא כ' כלום עכ\"ל ולק\"מ דהכא טעמא דאיסורא דאבל אסור בדברי תורה אתא לאשמועינן ומדין אבילות בשבת לא מיירי אבל התם דמיירי בכל הסימן מדין איסור אבילות בשבת קאמר דמותר לעלות משום דאל\"כ ה\"ל אבילות דפרהסי' ואין אבילות דפרהסי' נוהג בשבת והכי משמע התם להדיא ע\"ש:","\u0003ומצוה להתפלל כו'. \u0004ע\"ל סי' שע\"ו ס\"ג:","\u0003אין לו לבטלם. \u0004דאין אבילות לקטן כדלקמן ס\"ס שצ\"ו:"],["\u0003ואם רבים צריכים לו להתלמד. \u0004בתא\"ו נתיב כ\"ח כתב וראיתי לרבותי שהיו מגידים ההלכה אחר ג' ימים מזה נ\"ל במלמד שיכול ג\"כ ללמוד ההלכה. עם תלמידיו אחר ג' ימים דזה הוה בכלל רבים צריכים לו דתינוקות של בית רבן הבל פיהם חביב מלימוד הגדולים כדאמרינן במסכת שבת אינו דומה הבל שיש בו חטא לאין בו חטא. ונראה פשוט שאבל מותר להשתמש בתשמישי התורה כשקורין כגון גלילה וכיוצא בה דקריאה לחוד אסור לו משום דכתיב משמחי לב וכן ראיתי בהג\"ה שזה לשונו הרב ר\"ח היה אבל בזמן שני וחמישי והתפללו סליחות אצלו וקראו בתורה והוא היה גולל ס\"ת כו' ומביאה בדרישה:"],"\u0010g0\u0011 \u0010r0\u0011 אָבֵל, כָּל \u0010g1\u0011 שִׁבְעָה יָמִים \u0010y0\u0011 אָסוּר לִקְרוֹת בְּתוֹרָה, נְבִיאִים וּכְתוּבִים, מִשְׁנָה, גְמָרָא, הֲלָכוֹת וְאַגָדוֹת. \u0010y1\u0011 \u0010c0\u0011 \u0010g2\u0011 וְאִם רַבִּים צְרִיכִים לוֹ \u0010g3\u0011 \u0010t0\u0011 לְהִתְלַמֵּד, מֻתָּר, וּבִלְבַד שֶׁלֹּא יַעֲמִיד תֻּרְגְמָן אֶלָא יֹאמַר לְאַחֵר, וְהָאַחֵר לַתֻּרְגְמָן, וְתֻרְגְמָן יַשְׁמִיעַ לָרַבִּים. \u0005הַגָּה: אוֹ יִדְרֹשׁ בְּעַצְמוֹ (מָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006. וְיָכוֹל לִפְסֹק אִסּוּר וְהֶתֵּר לְיָחִיד הַשּׁוֹאֵל אוֹתוֹ, אִם אֵין אַחֵר אֶלָּא הוּא, וּצְרִיכִין לוֹ \u0005(בא\"ז וְר' יְרוּחָם)\u0006. אָבֵל אָסוּר לוֹמַר הֲלָכָה לְתַלְמִידָיו, וְכֵן נוֹהֲגִין, אַף עַל פִּי שֶׁיֵּשׁ מְקִלִּין \u0005(תא\"ו בְּשֵׁם י\"א)\u0006. \u0010g4\u0011 \u0010r1\u0011\nאִם הָאָבֵל \u0010t1\u0011 כֹּהֵן, וְאֵין בב\"ה כֹּהֵן אַחֵר, \u0010y2\u0011 אָסוּר לוֹ לַעֲלוֹת לִקְרוֹת בַּתּוֹרָה. \u0010g5\u0011 \u0010r2\u0011\nאִם אֵין שָׁם מִי שֶׁיִּתְפַּלֵל לְהוֹצִיא אֶת הָרַבִּים יְדֵי חוֹבָתָן, יָכוֹל הָאָבֵל לְהִתְפַּלֵל לְהוֹצִיאָן. \u0005הַגָּה: \u0010y3\u0011 \u0010r3\u0011 וּמִצְוָה לְהִתְפַּלֵּל שַׁחֲרִית וְעַרְבִית בַּמָּקוֹם שֶׁמֵּת שָׁם, אֲפִלּוּ אֵין אָבֵל, כִּי יֵשׁ בָּזֶה נַחַת רוּחַ לַנְּשָׁמָה (א\"ז)\u0006, וְהָאָבֵל מִצְטָרֵף לְמִנְיָן \u0005(שָׁם)\u0006. \u0010g6\u0011 \u0010r4\u0011\nאָבֵל מֻתָּר לִקְרוֹת בְּאִיּוֹב וּבְקִינוֹת וּבִדְבָרִים הָרָעִים שֶׁבְּיִרְמִיָּה וּבְהִלְכוֹת אֲבֵלוּת \u0005וְעַיֵּן בא\"ח סִימָן תקנ\"ד סָעִיף ב'.\u0006 \u0010g7\u0011 \u0010r5\u0011 וְהָנֵי מִלֵי בֵּינוֹ לְבֵין עַצְמוֹ, אֲבָל אֵינוֹ לוֹמֵד עִם אֲחֵרִים, אֶלָא הֵם יוֹשְׁבִים וְנוֹשְׂאִים וְנוֹתְנִין בְּהִלְכוֹת אֲבֵלוּת, וְאִם טָעוּ מְשִׁיבָן בְּשָׂפָה רָפָה, וְהוּא אֵינוֹ שׁוֹאֵל. \u0010g8\u0011 \u0010r6\u0011 וְהָנֵי מִלֵי כְּשֶׁאֵין רַבִּים צְרִיכִים לוֹ, אֲבָל אִם רַבִּים צְרִיכִים לוֹ, אֲפִלוּ בַּהֲלָכוֹת אֲחֵרוֹת מֻתָּר, כִּדְאָמְרִינַן. \u0010g9\u0011 \u0010r7\u0011\nאָבֵל שֶׁיֵּשׁ לוֹ בָּנִים קְטַנִּים, \u0010y4\u0011 אֵין לוֹ לְבַטְּלָם מִלִמּוּדָם.",{"g":["ברייתא מ\"ק דף כ\"א ע\"א ומייתי לה שם דף ט\"ו ע\"א מדקאמר ליה רחמנא ליחזקאל האנק דום:","\u0003הרמב\"ן בסת\"ה ולא דמי לתפילין דד\"ת שאני דכתיב בהו משמחי לב:\u0004 ","\u0003שם בברייתא דף כ\"א ע\"א:\u0004 ","טור בשם הרי\"ץ גיאת:\n(°) כצ\"ל מקום הגה זו וכן מפורש בברייתא שם במעשה דרבי יוסי וכו' וכן משמע בהדיא באשי\"רי:","\u0003ג\"ז שם בשם הרי\"ץ גיאת הואיל וסגי לישראל שיקרא במקומו וכ\"ש במקום ת\"ח דרב קרא בכהני:\u0004 ","שם בשם תשובת אביו הרא\"ש עיין בא\"ח סימן קל\"א שאין נפילת אפים בבית האבל ולקמן סימן שצ\"ג כתב הב\"י בשם הכל בו דא\"א תחנה ולמנצח ושיר מזמור ושגם בתפלת ערבית של שבת אצל האבל אין אומרים ברכה אחת מעין ז' ולא במה מדליקין:","בסת\"ה בשם י\"א וכ\"כ הסמ\"ג בשם ר\"ת שחזר בעת זקנותו ממה שהיה אוסר בימי אבלו באיוב וקינות וכו' וכ\"כ הטור בשם אביו הרא\"ש:","\u0003שם בברייתא דאבל רבתי:\u0004 ","\u0003ג\"ז שם בשם אביו הרא\"ש:\u0004 ","\u0003הגהות מיימוני בפ\"ה (ומרדכי) מטעם כי אין אבילות לקטן:\u0004 "],"t":["\u0003להתלמד. \u0004 כתב הט\"ז נ\"ל דמלמד יכול ללמוד ההלכה עם תלמידיו אחר ג' ימים דזה הוה בכלל רבים צריכים לו דתינוקות של בית רבן הבל פיהם חביב מלימוד הגדולים גם נראה פשוט שאבל מותר להשתמש בתשמישי התורה כשקורין כגון גלילה וכיוצא בזה דקריאה לחוד אסור לו משום דכתיב משמחי לב וכן ראיתי בהג\"ה וז\"ל הרב ר\"ח היה אבל בזמן שני וחמישי והתפללו סליחות אצלו וקראו בתורה והוא היה הגולל ס\"ת כו' עכ\"ל:","\u0003כהן. \u0004 כ' הב\"ח ותימא דבסי' ת' בדין שבת כתב הרב דבאין שם כהן אחר אלא הוא מותר לקרותו וכאן לא כתב כלום וכ' הש\"ך דלק\"מ דהכא טעמא דאיסורא דאבל אסור בד\"ת אתא לאשמועינן ומדין אבלות בשבת לא מיירי אבל התם דמיירי בכל הסי' מדין איסור אבלות בשבת קאמר דמותר לעלות משום דאל\"כ ה\"ל אבלות דפרהסיא ואין אבלות דפרהסיא נוהג בשבת והכי משמע התם להדיא עיין שם עכ\"ל:"],"r":["\u0003(ליקוט) אבל כל שבעה כו'. \u0004עבה\"ג. ודלא כי\"ח ועתוס' כ\"א א' ד\"ה אלו כו' (ע\"כ):","\u0003אם האבל כו'. \u0004כנ\"ל בס\"א דוקא שרבים צריכין לו משא\"כ כה\"ג שאינו אלא מפני דרכי שלום. שם:","\u0003אם אין כו'. \u0004נלמד מס\"א:","\u0003ומצוה כו'. \u0004כמש\"ל סי' שע\"ו ס\"ג:","\u0003אבל מותר כו'. \u0004עתוס' כ\"א א' ד\"ה ואסור כו':","\u0003(ליקוט) וה\"מ כו'. \u0004א\"ר פ\"י חכם כו' וערא\"ש סי' פ\"ד (ע\"כ):","\u0003וה\"מ כו'. \u0004כנ\"ל ס\"א:","\u0003אבל כו'. \u0004עבה\"ג וכמש\"ל ס\"ס שצ\"ו:"]}],["אָבֵל אָסוּר בִּשְׁאֵלַת שָׁלוֹם. כֵּיצַד, שְׁלֹשָׁה יָמִים הָרִאשׁוֹנִים אֵינוֹ שׁוֹאֵל בִּשְׁלוֹם כָּל אָדָם, וְאִם אֲחֵרִים לֹא יָדְעוּ שֶׁהוּא אָבֵל וְשָׁאֲלוּ בִּשְׁלוֹמוֹ, לֹא יָשִׁיב לָהֶם שָׁלוֹם אֶלָא יוֹדִיעֵם שֶׁהוּא אָבֵל. מִג' עַד שִׁבְעָה, אֵינוֹ שׁוֹאֵל, וְאִם אֲחֵרִים לֹא יָדְעוּ שֶׁהוּא אָבֵל וְשָׁאֲלוּ בִּשְׁלוֹמוֹ, מֵשִׁיב לָהֶם. מִשִּׁבְעָה עַד ל', שׁוֹאֵל בִּשְׁלוֹם אֲחֵרִים שֶׁהֵם שְׁרוּיִים בְּשָׁלוֹם, וְאֵין אֲחֵרִים שׁוֹאֲלִים בִּשְׁלוֹמוֹ, וְכָל שֶׁכֵּן שֶׁמֵּשִׁיב לְמִי שֶׁשּׁוֹאֵל בִּשְׁלוֹמוֹ. לְאַחַר ל' יוֹם, הֲרֵי הוּא כִּשְׁאָר כָּל אָדָם. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר קְרוֹבִים, אֲבָל עַל אָבִיו וְאִמּוֹ שׁוֹאֵל בִּשְׁלוֹם אֲחֵרִים אַחַר שִׁבְעָה, וְאֵין אֲחֵרִים שׁוֹאֲלִים בִּשְׁלוֹמוֹ עַד אַחַר י\"ב חֹדֶשׁ. \u0005הַגָּה: וּמֵאַחַר שֶׁאָסוּר בִּשְׁאֵלַת שָׁלוֹם, כָּל שֶׁכֵּן שֶׁאָסוּר לְהַרְבּוֹת בִּדְבָרִים (רַמְבַּ\"ם פ\"ה וְכָל בּוֹ)\u0006. וְאִם עוֹשֶׂה לִכְבוֹד רַבִּים, כְּגוֹן שֶׁרַבִּים בָּאִים לְנַחֲמוֹ, מֻתָּר לוֹמַר לָהֶם: לְכוּ לְבָתֵּיכֶם לְשָׁלוֹם, דְּלִכְבוֹד רַבִּים שָׁרֵי \u0005(נ\"י פֶּרֶק אֵין מְגַלְּחִין וּבְהַגָּהוֹת מיי' וּבְמָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006. \u0010y0\u0011 וְיֵשׁ מְקִלִּין הָאִדָּנָא בִּשְׁאֵלַת שְׁלוֹם הָאָבֵל לְאַחַר ל', וְאֵין טַעַם לָהֶם, \u0010y1\u0011 אִם לֹא שֶׁיַּחְלְקוּ לוֹמַר שֶׁזֶּה מַה שֶּׁאָנוּ נוֹהֲגִים לֹא מִקְרֵי שְׁאֵלַת שָׁלוֹם שֶׁבִּימֵיהֶם \u0005(סְבָרַת הָרַב)\u0006. וְעַיֵּן בא\"ח סִימָן פ\"ט.\nהַמּוֹצֵא אֶת חֲבֵרוֹ אָבֵל בְּתוֹךְ ל' יוֹם, מְדַבֵּר עִמּוֹ תַּנְחוּמִין וְאֵינוֹ שׁוֹאֵל בִּשְׁלוֹמוֹ. לְאַחַר ל' יוֹם, שׁוֹאֵל בִּשְׁלוֹמוֹ וְאֵינוֹ מְדַבֵּר עִמּוֹ תַּנְחוּמִים כְּדַרְכּוֹ, אֶלָא מִן הַצַּד, שֶׁאֵינוֹ מַזְכִּיר לוֹ שֵׁם הַמֵּת, אֶלָא אוֹמֵר לוֹ: תִּתְנַחֵם. מֵתָה אִשְׁתּוֹ וְנָשָׂא אַחֶרֶת, אֵינוֹ נִכְנָס לְבֵיתוֹ לְדַבֵּר עִמּוֹ תַּנְחוּמִין. מְצָאוֹ בַּשּׁוּק, אוֹמֵר לוֹ: תִּתְנַחֵם, בְּשָׂפָה רָפָה וּבְכֹבֶד רֹאשׁ. אֲבָל אִם לֹא נָשָׂא אַחֶרֶת, מְדַבֵּר עִמּוֹ תַּנְחוּמִין \u0010y2\u0011 עַד שֶׁיַּעַבְרוּ ג' רְגָלִים. וְעַל אָבִיו וְעַל אִמּוֹ מְדַבֵּר עִמּוֹ תַּנְחוּמִין כָּל י\"ב חֹדֶשׁ; לְאַחַר י\"ב חֹדֶשׁ מְדַבֵּר עִמּוֹ מִן הַצַּד. \u0010y3\u0011\nמָקוֹם שֶׁנָּהֲגוּ לִהְיוֹת שׁוֹאֲלִים בִּשְׁלוֹם אֲבֵלִים בְּשַׁבָּת, שׁוֹאֲלִים. וְכָתַב הַרַמְבַּ\"ם שֶׁהָאָבֵל נוֹתֵן שָׁלוֹם לְכָל אָדָם בְּשַׁבָּת, שֶׁהוּא מִכְּלַל דְּבָרִים שֶׁבְּפַרְהֶסְיָא. \u0005הַגָּה: \u0010c0\u0011 וְאָסוּר לִשְׁלֹחַ מָנוֹת לְאָבֵל עַל אָבִיו וְאִמּוֹ כָּל י\"ב חֹדֶשׁ, וַאֲפִלּוּ בְּשַׁבָּת, בְּמָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לִשְׁאֹל בִּשְׁלוֹמוֹ בְּשַׁבָּת (תְּשׁוּבַת מהרי\"ל סי' ל\"א)\u0006 ; אֲבָל בְּמָקוֹם שֶׁנָּהֲגוּ לִשְׁאֹל בִּשְׁלוֹמוֹ בְּשַׁבָּת, גַּם זֶה שָׁרֵי.",["\u0003ויש מקילין האידנא בשאילת שלום האבל. \u0004על אביו ואמו אחר ל':","\u0003אם לא שיחלקו כו'. \u0004ובאמת אין זה טעם נכון דא\"כ תוך ל' נמי ולא מצינו לשום פוסק שחילק בכך:","\u0003עד שיעברו ג' רגלים. \u0004כדלקמן סימן שצ\"ב ס\"ב:","\u0003מקום כו'. \u0004ואיתא בירושלמי הובא בפוסקים ר' אושעיא רבא אזל לחד אתר וחמא תמן אבלים בשבתא ושאל בהון ואמר להון איני יודע מנהג מקומכם אבל שלום עליכם כמנהג מקומי ועיין בא\"ח סימן רפ\"ז:"],["\u0003ואסור לשלוח מנות. \u0004כתב מו\"ח ז\"ל בשם הג\"ה בשם רבינו יהודה אבל תוך ל' אינו יכול להזמין לאחרים או להזמן עם אחרים ע\"כ ונראה דה\"ה כל י\"ב חדש על אביו ואמו:"],"\u0010g0\u0011 אָבֵל אָסוּר בִּשְׁאֵלַת שָׁלוֹם. כֵּיצַד, \u0010g1\u0011 שְׁלֹשָׁה יָמִים הָרִאשׁוֹנִים אֵינוֹ שׁוֹאֵל בִּשְׁלוֹם כָּל אָדָם, וְאִם אֲחֵרִים לֹא יָדְעוּ שֶׁהוּא אָבֵל וְשָׁאֲלוּ בִּשְׁלוֹמוֹ, לֹא יָשִׁיב לָהֶם שָׁלוֹם אֶלָא יוֹדִיעֵם שֶׁהוּא אָבֵל. מִג' עַד שִׁבְעָה, אֵינוֹ שׁוֹאֵל, וְאִם אֲחֵרִים לֹא יָדְעוּ שֶׁהוּא אָבֵל וְשָׁאֲלוּ בִּשְׁלוֹמוֹ, מֵשִׁיב לָהֶם. מִשִּׁבְעָה עַד ל', שׁוֹאֵל בִּשְׁלוֹם אֲחֵרִים שֶׁהֵם שְׁרוּיִים בְּשָׁלוֹם, וְאֵין אֲחֵרִים שׁוֹאֲלִים בִּשְׁלוֹמוֹ, וְכָל שֶׁכֵּן שֶׁמֵּשִׁיב לְמִי שֶׁשּׁוֹאֵל בִּשְׁלוֹמוֹ. לְאַחַר ל' יוֹם, הֲרֵי הוּא כִּשְׁאָר כָּל אָדָם. \u0010g2\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר קְרוֹבִים, אֲבָל עַל אָבִיו וְאִמּוֹ שׁוֹאֵל בִּשְׁלוֹם אֲחֵרִים אַחַר שִׁבְעָה, וְאֵין אֲחֵרִים שׁוֹאֲלִים בִּשְׁלוֹמוֹ עַד אַחַר י\"ב חֹדֶשׁ. \u0005הַגָּה: \u0010r0\u0011 וּמֵאַחַר שֶׁאָסוּר בִּשְׁאֵלַת שָׁלוֹם, כָּל שֶׁכֵּן שֶׁאָסוּר לְהַרְבּוֹת בִּדְבָרִים (רַמְבַּ\"ם פ\"ה וְכָל בּוֹ)\u0006. \u0010r1\u0011 וְאִם עוֹשֶׂה לִכְבוֹד רַבִּים, כְּגוֹן שֶׁרַבִּים בָּאִים לְנַחֲמוֹ, מֻתָּר לוֹמַר לָהֶם: לְכוּ לְבָתֵּיכֶם לְשָׁלוֹם, דְּלִכְבוֹד רַבִּים שָׁרֵי \u0005(נ\"י פֶּרֶק אֵין מְגַלְּחִין וּבְהַגָּהוֹת מיי' וּבְמָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006. \u0010y0\u0011 וְיֵשׁ מְקִלִּין הָאִדָּנָא בִּשְׁאֵלַת שְׁלוֹם הָאָבֵל לְאַחַר \u0010t0\u0011 ל', וְאֵין טַעַם לָהֶם, \u0010y1\u0011 אִם לֹא שֶׁיַּחְלְקוּ לוֹמַר שֶׁזֶּה מַה שֶּׁאָנוּ נוֹהֲגִים לֹא מִקְרֵי שְׁאֵלַת שָׁלוֹם \u0010t1\u0011 שֶׁבִּימֵיהֶם \u0005(סְבָרַת הָרַב)\u0006. וְעַיֵּן בא\"ח סִימָן \u0010g3\u0011 פ\"ט.\nהַמּוֹצֵא אֶת חֲבֵרוֹ אָבֵל בְּתוֹךְ ל' יוֹם, מְדַבֵּר עִמּוֹ תַּנְחוּמִין וְאֵינוֹ שׁוֹאֵל בִּשְׁלוֹמוֹ. לְאַחַר ל' יוֹם, שׁוֹאֵל בִּשְׁלוֹמוֹ וְאֵינוֹ מְדַבֵּר עִמּוֹ תַּנְחוּמִים כְּדַרְכּוֹ, אֶלָא מִן הַצַּד, שֶׁאֵינוֹ מַזְכִּיר לוֹ שֵׁם הַמֵּת, אֶלָא אוֹמֵר לוֹ: תִּתְנַחֵם. \u0010g4\u0011 מֵתָה אִשְׁתּוֹ וְנָשָׂא אַחֶרֶת, אֵינוֹ נִכְנָס לְבֵיתוֹ לְדַבֵּר עִמּוֹ תַּנְחוּמִין. מְצָאוֹ בַּשּׁוּק, אוֹמֵר לוֹ: תִּתְנַחֵם, בְּשָׂפָה רָפָה וּבְכֹבֶד רֹאשׁ. אֲבָל אִם \u0010g5\u0011 לֹא נָשָׂא אַחֶרֶת, מְדַבֵּר עִמּוֹ תַּנְחוּמִין \u0010y2\u0011 עַד שֶׁיַּעַבְרוּ ג' רְגָלִים. \u0010g6\u0011 וְעַל אָבִיו וְעַל אִמּוֹ מְדַבֵּר עִמּוֹ תַּנְחוּמִין כָּל י\"ב חֹדֶשׁ; לְאַחַר י\"ב חֹדֶשׁ מְדַבֵּר עִמּוֹ מִן הַצַּד. \u0010y3\u0011 \u0010g7\u0011 \u0010r2\u0011\nמָקוֹם שֶׁנָּהֲגוּ לִהְיוֹת שׁוֹאֲלִים בִּשְׁלוֹם אֲבֵלִים בְּשַׁבָּת, שׁוֹאֲלִים. \u0010g8\u0011 וְכָתַב הַרַמְבַּ\"ם שֶׁהָאָבֵל נוֹתֵן שָׁלוֹם לְכָל אָדָם בְּשַׁבָּת, \u0010g9\u0011 שֶׁהוּא מִכְּלַל דְּבָרִים שֶׁבְּפַרְהֶסְיָא. \u0005הַגָּה: \u0010c0\u0011 וְאָסוּר \u0010t2\u0011 לִשְׁלֹחַ מָנוֹת לְאָבֵל עַל אָבִיו וְאִמּוֹ כָּל י\"ב חֹדֶשׁ, וַאֲפִלּוּ בְּשַׁבָּת, בְּמָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לִשְׁאֹל בִּשְׁלוֹמוֹ בְּשַׁבָּת (תְּשׁוּבַת מהרי\"ל סי' ל\"א)\u0006 ; אֲבָל בְּמָקוֹם שֶׁנָּהֲגוּ לִשְׁאֹל בִּשְׁלוֹמוֹ בְּשַׁבָּת, גַּם זֶה שָׁרֵי.",{"g":["מ\"ק דף ט\"ו ע\"א ומייתי לה מדקאמר ליה רחמנא ליחזקאל האנק דום ופי' רש\"י כלומר בדבר זה תנהוג אבילות ולא תשאל לשלום וכמ\"ש התוס' שם שיהיה צריך להראות בקצת דברים שהיה אבל ולא היה נוהג דיני אבל אלא למשל:","\u0003ברייתא ומסקנא דגמרא שם דף כ\"א ע\"ב:\u0004 ","\u0003ברייתא ומסקנא בגמ' שם:\u0004 ","\u0003ברייתא ומסקנא דגמרא שם:\u0004 ","\u0003שם בברייתא:\u0004 ","\u0003טור בשם הרמב\"ן בסת\"ה:\u0004 ","\u0003ברייתא שם דף כ\"א ע\"ב:\u0004 ","\u0003ירושלמי פ\"ג דברכות וכתבו הרא\"ש שם במ\"ק:\u0004 ","\u0003וכ\"כ הטור בשמו:\u0004 ","\u0003לשון הטור וכתב הכ\"מ ולא הוזכר בגמרא משום דמילתא דפשיטותא היא:\u0004 "],"t":["\u0003ל'. \u0004 על אביו ואמו. ש\"ך:","\u0003שבימיהם. \u0004 ובאמת אין זה טעם נכון דא\"כ תוך ל' נמי ולא מצינו לשום פוסק שחילק בכך עכ\"ל הש\"ך \u0005(ומיהו אפשר לומר כיון שרוב שאילת שלום שלנו אינו אלא שאומר צפרא טבא וזה מותר שאינו שאילת שלום ממש כדאיתא בב\"י בא\"ח סימן פ\"ה והביאו בש\"ע שם. ועוד מביא בב\"י שם בשם ר\"י פרישת שלום כמו כריעה אבל שלום בפה מותר כמו צפרא דמרי טב וכיוצא בו ע\"ש וכתב שם בד\"מ דבזוהר פקודי דף ק\"ג ע\"א משמע דאינו אסור רק כשמזכיר השם וזה שם לענין שלא יתן שלום לחבירו קודם שיתפלל וש\"מ שכל זה שאנו נוהגין אינו בכלל שאילת שלום כנ\"ל)\u0006:","\u0003מנות. \u0004 כ' הב\"ח בשם רבינו יהודה דאבל תוך ל' אינו יכול להזמין לאחרים או להזמן עם אחרים ע\"כ. ונראה דה\"ה כל י\"ב חדש על אביו ואמו עכ\"ל הט\"ז \u0005(וכן למזוג שקורין שענקי\"ן לאורח אבל. מהרי\"ל)\u0006 ואף בשבת במקום דנוהגין דאין שואלין בשלום בשבת. ד\"מ. וכתב מ\"א בא\"ח סי' תרנ\"ו ממשמעות דברי הרמ\"א דבמקום שאין נוהגים אבילות בפורים דינו כשבת ומותר לשלוח במקום שנהגו לשאול בשלומו \u0005(וט\"ז כתב שם אין נראה לסמוך על זה. עיין שם)\u0006:"],"r":["\u0003ומאחר כו'. \u0004ע\"ל סי' שצ\"ג ס\"ב שניה כו':","\u0003ואם עושה כו'. \u0004גמ' שם:","\u0003(ליקוט) מקום כו'. \u0004עי' רא\"ש דמ\"ק סע\"ה וספ\"ה (ע\"כ):"]}],["אָבֵל חַיָּב בַּעֲטִיפַת הָרֹאשׁ, דְּהַיְנוּ שֶׁיְּכַסֶה רֹאשׁוֹ בְּטַלִית אוֹ בְּסוּדָר וְיַחֲזִיר קְצָתוֹ עַל פִּיו וְעַל רֹאשׁ הַחֹטֶם; וְהָנֵי מִלֵי שֶׁצָּרִיךְ עֲטִיפָה, בְּכָל הַיּוֹם. אֲבָל כְּשֶׁבָּאִין מְנַחֲמִים אֶצְלוֹ, מְגַלֶה רֹאשׁוֹ לִכְבוֹדָם. \u0005הַגָּה: \u0010y0\u0011 \u0010c0\u0011 וְיֵשׁ אוֹמְרִים שֶׁאֵין נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ בַּעֲטִיפָה (הַגָּהוֹת מַיְמוֹנִי פ\"ה)\u0006 ; וְכֵן הַמִּנְהָג פָּשׁוּט, וְאֵין לְהַחְמִיר לְשַׁנּוֹת בַּמֶּה שֶׁלֹּא נָהֲגוּ אֲבוֹתֵינוּ.",["\u0003וי\"א שאין נוהגין כו'. \u0004מפני שמביא לידי שחוק גדול מן העובדי כוכבים ועבדים ושפחות שבינינו מיהו יש לנהוג בעטיפה קצת דהיינו למשוך הכובע למטה לפני העינים וכן משמע בבית חדש ועיין לקמן סימן ת':"],["\u0003וי\"א שאין נוהגין במדינות אלו כו'. \u0004כתב הרוקח אבל חייב בעטיפה כמו עתה שמושכין הכובע לפני העינים כל ז' ימים ובשבת בצינעא ולא בפרהסיא עכ\"ל. וכתב מו\"ח ז\"ל לפי זה מיד כשמתחיל השליח צבור ברכו אז יגביה האבל את הכובע דלא להוי מילתא דבפרהסיא עכ\"ל:"],"\u0010g0\u0011 אָבֵל חַיָּב בַּעֲטִיפַת הָרֹאשׁ, \u0010g1\u0011 \u0010r0\u0011 דְּהַיְנוּ שֶׁיְּכַסֶה רֹאשׁוֹ \u0010r1\u0011 בְּטַלִית אוֹ בְּסוּדָר וְיַחֲזִיר קְצָתוֹ עַל פִּיו וְעַל רֹאשׁ \u0010g2\u0011 \u0010r2\u0011 הַחֹטֶם; וְהָנֵי מִלֵי שֶׁצָּרִיךְ עֲטִיפָה, בְּכָל הַיּוֹם. אֲבָל כְּשֶׁבָּאִין מְנַחֲמִים אֶצְלוֹ, מְגַלֶה רֹאשׁוֹ לִכְבוֹדָם. \u0005הַגָּה: \u0010y0\u0011 \u0010c0\u0011 \u0010r3\u0011 וְיֵשׁ אוֹמְרִים שֶׁאֵין נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ בַּעֲטִיפָה (הַגָּהוֹת מַיְמוֹנִי פ\"ה)\u0006 ; וְכֵן \u0010t0\u0011 הַמִּנְהָג פָּשׁוּט, וְאֵין לְהַחְמִיר לְשַׁנּוֹת בַּמֶּה שֶׁלֹּא נָהֲגוּ אֲבוֹתֵינוּ.",{"g":["\u0003מ\"ק דף ט\"ו ע\"א מדקאמר ליה רחמנא ליחזקאל ולא תעט' על שפם מכלל דלכ\"ע אסירי:\u0004 ","\u0003טור בשם פירוש רב האי אמימרא דשמואל כל עטיפה וכו'\u0004 ואמימרא דרב נחמן ע\"ג דיקנא שם דף כ\"ד ע\"א:","שם בשם הרמב\"ן בסת\"ה:\n(°) ומפרש שם משום שחוק העובדי כוכבים:"],"t":["\u0003המנהג. \u0004 מפני שמביא לידי שחוק גדול מן העובדי כוכבים ועבדים ושפחות שבינינו. מיהו יש לנהוג העטיפה קצת כמו עתה שמושכין הכובע לפני העינים כל ז' ימים ובשבת בצינעא ולא בפרהסיא. וכתב הב\"ח לפ\"ז מיד כשמתחיל החזן ברכו אז יגביה האבל את הכובע דלא להוי מלתא דפרהסיא. עכ\"ל:"],"r":["\u0003(ליקוט) דהיינו שמכסה כו' ויחזיר כו'. \u0004בירושלמי \u0005(פ\"ג) \u0006לא תעטה על שפם מכאן שצריך לכסות פניו וליכסיניה מלרע דלא ליהוין אמרין פומיה הוא חשש:","\u0003בטלית או בסודר. \u0004תה\"א בשם רב מתתיה גאון וכמש\"ש כ\"ד א' אביי אשכחיה לר\"י כו' (ע\"כ):","\u0003וה\"מ כו'. \u0004מ\"ש והביאו תה\"א והטור:\n\u0003(ליקוט) וה\"מ כו'. \u0004א\"ר פ\"י נסתם הגולל כו' בא לעמוד כו' באו כו' (ע\"כ):","\u0003וי\"א כו'. \u0004עתוס' כ\"א א' ד\"ה אלו כו':"]}],["אָבֵל חַיָּב בִּכְפִיַּת הַמִּטָּה. \u0010c0\u0011 וּבִשְׁעַת שֵׁנָה וַאֲכִילָה, יוֹשֵׁב עַל מִטָּה כְּפוּיָה, אֲבָל כָּל הַיּוֹם אֵינוֹ יוֹשֵׁב, אֲפִלוּ עַל מִטָּה כְּפוּיָה, אֶלָא עַל גַבֵּי קַרְקַע. וְכֵן הַמְנַחֲמִים אֵינָם רַשָּׁאִים לֵישֵׁב אֶלָא עַל גַבֵּי קַרְקַע. \u0010y0\u0011\nעַכְשָׁו לֹא נָהֲגוּ בִּכְפִיַּת הַמִּטָּה, מִפְּנֵי שֶׁיֹאמְרוּ הָעוֹבְדֵי כּוֹכָבִים שֶׁהוּא מְכַשְּׁפוּת, וְעוֹד שֶׁאֵין הַמִּטּוֹת שֶׁלָנוּ עֲשׂוּיוֹת כַּמִּטּוֹת שֶׁלָהֶן כְּדֵי שֶׁיְּהֵא נִכָּר בָּהֶם כְּפִיָּה.",["\u0003עכשיו לא נהגו כו'. \u0004מ\"מ אסור לו לישב על גבי ספסל או כרים וכסתות כי אם על גבי קרקע אם לא חולה וזקן שיש להם צער בישיבה על גבי קרקע מותרים להשים כר קטן מתחתיו. מיהו יכול לילך ולעמוד וא\"צ לישב כלל רק כשהמנחמים אצלו צריך לישב ע\"ג קרקע וה\"ה דכשרוצה לישן דצריך לישן על גבי קרקע מיהו המנחמים יושבים ע\"ג ספסל דמסתמא מחיל להו. כל זה מבואר בדרישה:"],["\u0003ובשעת שינה כו'. \u0004כתב רש\"ל אבל אין לו לישן כל ז' אלא ע\"ג הקרקע כ\"כ הר\"מ והאבל א\"צ לישב ע\"ג קרקע אלא כשהמנחמים אצלו ואז גם המנחמים צריכין לישב ע\"ג קרקע אא\"כ אמר להו האבל שבו ע\"ג ספסלים דמצי מחיל ליקריה (ואפשר משום הכי אין המנחמי' יושבין בזמן הזה ע\"ג קרקע דמחיל האבל מסתמא) ולישב האבל ע\"ג כרים וכסתות בעוד שהמנחמים אצלו לא יתכן אמנם חולה וזקן שיש להם צער בישיבת קרקע מותר להשים כר קטן תחתיו עכ\"ל. מה שכ' שאין צריך האבל לישב ע\"ג קרקע אלא כשהמנחמים אצלו פירוש אבל בלאו הכי יכול לעמוד או לילך בחדרו אבל על כל פנים אסור לישב ע\"ג ספסל:"],"\u0010g0\u0011 אָבֵל \u0010r0\u0011 חַיָּב בִּכְפִיַּת הַמִּטָּה. \u0010c0\u0011 \u0010g1\u0011 וּבִשְׁעַת שֵׁנָה וַאֲכִילָה, יוֹשֵׁב עַל מִטָּה כְּפוּיָה, \u0010r1\u0011 אֲבָל כָּל הַיּוֹם אֵינוֹ יוֹשֵׁב, אֲפִלוּ עַל מִטָּה כְּפוּיָה, אֶלָא עַל גַבֵּי קַרְקַע. וְכֵן הַמְנַחֲמִים אֵינָם רַשָּׁאִים לֵישֵׁב אֶלָא עַל גַבֵּי קַרְקַע. \u0010y0\u0011 \u0010g2\u0011 \u0010t0\u0011 \u0010r2\u0011\nעַכְשָׁו לֹא נָהֲגוּ בִּכְפִיַּת הַמִּטָּה, מִפְּנֵי שֶׁיֹאמְרוּ הָעוֹבְדֵי כּוֹכָבִים שֶׁהוּא מְכַשְּׁפוּת, וְעוֹד שֶׁאֵין הַמִּטּוֹת שֶׁלָנוּ עֲשׂוּיוֹת כַּמִּטּוֹת שֶׁלָהֶן כְּדֵי שֶׁיְּהֵא נִכָּר בָּהֶם כְּפִיָּה.",{"g":["\u0003מ\"ק דף ט\"ו ע\"א מדקתני בר קפרא וכו':\u0004 ","\u0003הרמב\"ן בסת\"ה ממימרא דרב יהודה אמר רב וכו'\u0004 שם דף כ\"ח ע\"ב:","\u0003טור בשם אביו הרא\"ש:\u0004 "],"t":["\u0003עכשיו. \u0004 כ' הש\"ך ומ\"מ אסור לו לישב ע\"ג ספסל או על כרים וכסתות כי אם ע\"ג קרקע אם לא חולה וזקן שיש להם צער בישיבה על גב קרקע מותרים להשים כר קטן מתחתיו. מיהו יכול לילך ולעמוד וא\"צ לישב כלל רק כשהמנחמים אצלו צריך לישב ע\"ג קרקע וה\"ה דכשרוצה לישן צריך לישן ע\"ג קרקע \u0005(ועכשיו רבים נהגו שלא לישן כל ז' ע\"ג קרקע אפשר מפני שטבעם חלוש והוי כחולים לענין זה)\u0006 מיהו המנחמים יושבים ע\"ג ספסל דמסתמא מחיל להו. עכ\"ל:"],"r":["\u0003(ליקוט) בכפיית כו'. \u0004ערא\"ש סי' קכ\"ה אבל אם כפה כו' שאין החובה כו' כ\"ש כו' וכמש\"ש כ\"א א' ודלמא מילתא כו' והתניא כו' ובא\"ר פי\"א היה ישן ע\"ג מטה ע\"ג ספסל ע\"ג אודיינא חייב בכפיית המטה האומר איני כופה הריני ישן ע\"ג ספסל אין שומעין לו ובירושלמי \u0005(פ\"ג) \u0006אמר איני כופה את המטה הריני ישן ע\"ג ספסל אין שומעין לו מפני שאמר איני כופה את המטה אבל אם אמר הריני כופה את המטה שומעין לו מתני' לא אמרה כן וכשמברין אותו כל העם מסובין על הארץ והוא מיסב על הספסל בכהן גדול אבל הדיוט לא ומשני ברבים הא ביחיד לא ולא עבדין כן ר\"ל שאפי' ברבים יושבין על הספסל ואין נזהרין בזה ומ\"מ למדנו מזה שביחיד כל שכפה מותר לישן ע\"ג ספסל וכ\"ש ע\"ג קרקע עכ\"ל בתה\"א ודברי טוש\"ע צ\"ע (ע\"כ):","\u0003(ליקוט) אבל כל כו'. \u0004עתוס' כ\"ז א' ד\"ה מן כו' (ע\"כ):\n\u0003(ליקוט) אבל כל היום כו' וכן כו'. \u0004גמ' כ\"ה ב' והביאו הרי\"ף ורא\"ש שם אר\"י א\"ר אין המנחמין כו' סקמ\"ה וגירסת הרמב\"ן \u0005(בתה\"א) \u0006מנין לאבל שאין רשאי לישב ע\"ג מטה אלא ע\"ג הארץ שנאמר וישבו אתו לארץ ואר\"י א\"ר מנין למנחמין כו' וכ\"כ בטור והכל ליתא בגמרא שלנו שהשמיטוהו המדפיסים (ע\"כ):","\u0003עכשיו כו'. \u0004תוס' כ\"א א' כנ\"ל \u0005(ס\"ס שפ\"ו):\u0006"]}],["אָבֵל \u0010c0\u0011 אָסוּר לְהַנִּיחַ תְּפִלִין בְּיוֹם רִאשׁוֹן; \u0010y0\u0011 וְאַחַר שֶׁהֵנֵץ הַחַמָּה בְּיוֹם שֵׁנִי, מֻתָּר לַהֲנִיחָם.\nמִבָּעֵי לֵהּ לְאָבֵל לְיַתּוֹבֵי דַּעְתֵּהּ לְכַוּוֹנֵי לִבֵּהּ לַתְּפִלִין שֶׁלֹּא יַסִיחַ דַּעְתּוֹ מֵהֶם, אֲבָל בִּשְׁעַת הֶסְפֵּד וּבְכִי לֹא מַנַּח לְהוּ.",["\u0003ואחר שהנץ כו'. \u0004ויש פוסקים דאינו אסור אלא ביום ראשון וביום ב' מותר מיד אפי' קודם הנץ החמה וכ\"פ הב\"ח. ואם שמע שמועה קרובה דינה כיום קבורה דאסור להניח תפילין. כן משמע מדברי הרמב\"ן והמחבר לקמן סי' ת\"ב ס\"ב וכ\"פ בתשו' משאת בנימין סימן פ\"ב ופשוט הוא:"],["\u0003אסור להניח תפילין. \u0004גם ביום שמועה קרובה אסור להניח תפילין כ\"כ הרמב\"ן וב\"י מביאו לקמן סימן ת\"ב:"],"\u0010g0\u0011 \u0010r0\u0011 אָבֵל \u0010c0\u0011 אָסוּר לְהַנִּיחַ \u0010g1\u0011 תְּפִלִין בְּיוֹם \u0010t0\u0011 רִאשׁוֹן; \u0010y0\u0011 \u0010g2\u0011 וְאַחַר שֶׁהֵנֵץ \u0010t1\u0011 הַחַמָּה בְּיוֹם שֵׁנִי, מֻתָּר לַהֲנִיחָם. \u0010g3\u0011 \u0010r1\u0011\nמִבָּעֵי לֵהּ לְאָבֵל לְיַתּוֹבֵי דַּעְתֵּהּ לְכַוּוֹנֵי לִבֵּהּ לַתְּפִלִין שֶׁלֹּא יַסִיחַ דַּעְתּוֹ מֵהֶם, \u0010r2\u0011 אֲבָל בִּשְׁעַת הֶסְפֵּד וּבְכִי לֹא מַנַּח לְהוּ.",{"g":["\u0003מ\"ק דף ט\"ו ע\"א מדקאמר ליה רחמנא ליחזקאל פארך חבוש עליך מכלל דלכ\"ע אסור:\u0004 ","\u0003כרבי יהושע בברייתא שם דף כ\"א ע\"א:\u0004 ","\u0003טור בשם אביו הרא\"ש וכך הם דברי הרמב\"ן בסת\"ה:\u0004 ","\u0003שם בשם הרמב\"ן שם:\u0004 "],"t":["\u0003ראשון. \u0004 כתב הט\"ז דגם ביום שמועה קרובה אסור להניח תפילין כן כתב הרמב\"ן ומביאו ב\"י לקמן סימן ת\"ב עכ\"ל:","\u0003החמה. \u0004 כתב הש\"ך ויש פוסקים דאינו אסור אלא ביום ראשון וביום ב' מותר מיד אפי' קודם הנץ החמה \u0005(כשיאיר היום)\u0006 וכ\"פ הב\"ח עכ\"ל \u0005(ועיין בה\"י)\u0006:"],"r":["\u0003אבל כו' ואחר כו'. \u0004וכן משמע בפ\"ב דסוכה \u0005(כ\"ה ב') \u0006ועמ\"ש בא\"ח סי' ל\"ח:","\u0003מיבעיא כו'. \u0004כמש\"ש \u0005(בסוכה שם) \u0006לענין סוכה:\n\u0003(ליקוט) מיבעי כו'. \u0004כמ\"ש \u0005(שבת י\"ב א' וש\"מ) \u0006חייב אדם למשמש כו'. תה\"א (ע\"כ):","\u0003אבל בשעת כו'. \u0004כמש\"ש שנאמר פאר וערש\"י שם:"]}],["אָבֵל אָסוּר לְכַבֵּס כְּסוּתוֹ כָּל שִׁבְעָה יָמִים, אֲפִלוּ בְּמַיִם לְבַד; וּלְאַחַר שִׁבְעָה, מֻתָּר. וּכְשֵׁם שֶׁאָסוּר לְכַבֵּס, כָּךְ אָסוּר לִלְבֹּשׁ הַמְכֻבָּסִים קֹדֶם לָכֵן. \u0010y0\u0011 \u0005וְאַחַר ז' שָׁרֵי, \u0010y1\u0011 וְהָעוֹלָם נָהֲגוּ בּוֹ אִסּוּר (כְּדַעַת ריב\"א וְסִיעָתוֹ)\u0006. וְנוֹהֲגִין שֶׁאָדָם אַחֵר \u0010y2\u0011 לוֹבְשָׁם תְּחִלָּה, וְאַחַר כָּךְ לוֹבְשָׁם הָאָבֵל, וְהַמִּנְהָג עִקָּר \u0005(טוּר בְּשֵׁם סמ\"ק וכ\"כ הַמָּרְדְּכַי ה\"א וְכָל בּוֹ)\u0006. וְכֵן נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ לְאַחַר שִׁבְעָה; וְאִם לְבָשׁוֹ אָדָם אַחֵר \u0010y3\u0011 רַק שָׁעָה אַחַת דַּי בְּכָךְ \u0005(כָּל בּוֹ וסמ\"ק)\u0006. וְאֵין צָרִיךְ לוֹמַר שֶׁאָסוּר לִלְבֹּשׁ חֲדָשִׁים. וְגַם הַסְדִינִים וְהַמַּצָּעוֹת שֶׁל מִטָּה אָסוּר לְכַבְּסָן וּלְהַצִּיעַ \u0010c0\u0011 הַמְכֻבָּסִין. וְכֵן מִטְפְּחוֹת הַיָּדַיִם, אַף עַל פִּי שֶׁמֻּתָּר לְכַבְּסָן בַּמּוֹעֵד; וְכֵן כָּל אוֹתָן שֶׁשָּׁנִינוּ שֶׁמֻּתָּר לְכַבְּסָן בַּמּוֹעֵד, כְּגוֹן הַיּוֹצֵא מִבֵּית הַשִּׁבְיָה וּמִבֵּית הָאֲסוּרִים, וְהַמְּנֻדֶּה שֶׁהִתִּירוּ לוֹ חֲכָמִים, וְהַנִּשְׁאָל לְחָכָם וְהֻתַּר, וְהַבָּא מִמְּדִינַת הַיָּם \u0010y4\u0011 שֶׁהָלַךְ לְהַרְוִיחַ \u0010y5\u0011 וְלֹא הָיָה לוֹ פְּנַאי לְגַלֵחַ, אֲסוּרִים בִּימֵי אֶבְלוֹ, שֶׁאִם אֵרְעוֹ אֶחָד מֵהֶם, קֹדֶם הָאֲבֵלוּת וְנִכְנַס מִיָּד לְתוֹךְ הָאֲבֵלוּת, אָסוּר לְכַבֵּס אֶלָא אִם כֵּן אֵרְעוֹ אֶחָד מֵהֶם וּתְכָפוּהוּ מִיָּד שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, אָז מֻתָּר לְכַבֵּס אַף בְּנֶתֶר וְחוֹל וַאֲפִלוּ תּוֹךְ שִׁבְעָה, וּבִלְבַד שֶׁיַּעֲשֶׂנּוּ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ. וְאַחַר שֶׁתְּכָפוּהוּ אֲבֵלָיו זֶה אַחַר זֶה, מְכַבֵּס בְּמַיִם אֲבָל לֹא בְּנֶתֶר וְאָהָל.\nמֻתָּר לְכַבֵּס בִּגְדֵי קְטַנִּים שֶׁמֵּת אֲבִיהֶם.\nאָסוּר לִלְבֹּשׁ תּוֹךְ שִׁבְעָה כֵּלִים חֲדָשִׁים צְבוּעִים וִישָׁנִים יוֹצְאִים מִתַּחַת הַמַּכְבֵּשׁ. \u0005(פי' כְּלִי לַעֲצֹר בּוֹ הַבְּגָדִים)\u0006. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּאָסוּר לִלְבֹּשׁ בִּגְדֵי שַׁבָּת תּוֹךְ ד' שָׁבוּעוֹת הָרִאשׁוֹנִים, אֲבָל אַחַר כָּךְ מֻתָּר אֲפִלּוּ עַל אָבִיו וְאִמּוֹ, וְכֵן לַעֲשׂוֹת בְּגָדִים חֲדָשִׁים\u0006 \u0005(כָּל בּוֹ בְּשֵׁם מוֹהֲרַ\"ם)\u0006, \u0005אָבֵל נָהֲגוּ אִסּוּר כָּל י\"ב \u0010y6\u0011 חֹדֶשׁ.\u0006\nאָסוּר תּוֹךְ שִׁבְעָה לְכַבֵּס וּלְהַנִּיחַ, בֵּין עַל יְדֵי עַצְמוֹ בֵּין עַל יְדֵי אֲחֵרִים. וְאִם הָיְתָה כְּסוּתוֹ \u0010y7\u0011 בְּקִבֹּלֶת בְּיַד אֲחֵרִים, מְכַבֵּס אוֹתוֹ כִּדַרְכּוֹ כְּמוֹ שְׁאָר מְלַאכְתּוֹ בְּתָלוּשׁ שֶׁבְּיַד אֲחֵרִים, בְּקִבֹּלֶת.\nכָּל שְׁלֹשִׁים יוֹם אָסוּר לִלְבֹּשׁ \u0005אוֹ לְהַצִּיעַ תַּחְתָּיו (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006 בֶּגֶד מְגֹהָץ, וְהוּא שֶׁיְּהֵא לָבָן וְחָדָשׁ, וַאֲפִלוּ הוּא שֶׁל פִּשְׁתָּן. וְעַל אָבִיו וְעַל אִמּוֹ, אָסוּר עַד שֶׁיַּגִיעַ הָרֶגֶל אַחַר שְׁלֹשִׁים וְיִגְעֲרוּ בּוֹ חֲבֵרָיו.\nגִהוּץ יֵשׁ אוֹמְרִים צק\"ל בִּלְשׁוֹן עֲרָב, וְיֵשׁ אוֹמְרִים דְּהַיְנוּ כִּבּוּס בְּמַיִם וְאֵפֶר אוֹ בְּנֶתֶר וּבֹרִית.\nאַחַר שִׁבְעָה מֻתָּר לְגַהֵץ, בֵּין לְעַצְמוֹ בֵּין לַאֲחֵרִים; וְלֹא אָמְרוּ שְׁלֹשִׁים יוֹם לְגִהוּץ, אֶלָא \u0010y8\u0011 לִלְבֹּשׁ.\nיֵשׁ מִי שֶׁאוֹמֵר דְּהָאִידָּנָא לֵיכָּא אִסוּר גִהוּץ, שֶׁהֲרֵי אָמְרוּ גִהוּץ שֶׁלָנוּ כְּכִבּוּס שֶׁלָהֶם.",["\u0003ואחר ז' שרי. \u0004היינו כשאין מגוהץ או לדידן דגיהוץ שלנו ככיבוס שלהם כדלקמן בסוף הסימן:","\u0003והעולם נהגו בו אסור. \u0004היינו שחוששים לסברת ריב\"א וסייעתו דאסרו כיבוס כל ל' ומשמע בתוספות דמ\"ק דף כ\"ג ע\"א דאינו אוסר אלא במכובס בנתר וחול אבל לא במים לבד וכתב הב\"ח ולפ\"ז במכובס במים לבד אין צריך להלבישו אחר תחלה ופשיטא דשרי לאחר ז' מיד:","\u0003לובשם תחלה. \u0004ואפילו במגוהצין ג\"כ באבן חלקה מותר בכה\"ג וכ\"כ הב\"ח:","\u0003רק שעה אחת. \u0004כלומר זמן מה וא\"צ שעה זמניות וכן משמע בפוסקים וכן נוהגין ולא כמ\"ש בעט\"ז שעה או שתים ואולי גם הוא ל\"ד קאמר:","\u0003שהלך להרויח. \u0004לאפוקי לטיול ועיין כא\"ח סימן תקל\"א:","\u0003ולא היה לו פנאי לגלח. \u0004והוא הדין כאן לכבס:","\u0003אסור כו'. \u0004הטעם משום דאסור בעשיית מלאכה:","\u0003ביד אחרים. \u0004ובבית אחרים. וכדלעיל סימן ש\"פ סעיף י\"ח ע\"ש:","\u0003יש מי כו'. \u0004עיין בא\"ח סימן תקנ\"א סעיף ג':"],["\u0003וכן מטפחות הידים והשלחן כו'. \u0004כתב רש\"ל עיין בא\"ח סימן תקנ\"א שהיתר פשוט לכבוד שבת לפרוס המטפחת המכובסת ע\"כ:"],"\u0010g0\u0011 \u0010r0\u0011 אָבֵל אָסוּר לְכַבֵּס כְּסוּתוֹ \u0010g1\u0011 \u0010r1\u0011 כָּל שִׁבְעָה יָמִים, \u0010r2\u0011 אֲפִלוּ בְּמַיִם לְבַד; וּלְאַחַר שִׁבְעָה, \u0010g2\u0011 \u0010r3\u0011 מֻתָּר. וּכְשֵׁם שֶׁאָסוּר לְכַבֵּס, כָּךְ אָסוּר לִלְבֹּשׁ הַמְכֻבָּסִים קֹדֶם לָכֵן. \u0010y0\u0011 \u0005וְאַחַר ז' שָׁרֵי, \u0010y1\u0011 וְהָעוֹלָם נָהֲגוּ בּוֹ אִסּוּר (כְּדַעַת ריב\"א \u0010g3\u0011 \u0010r4\u0011 וְסִיעָתוֹ)\u0006. וְנוֹהֲגִין שֶׁאָדָם אַחֵר \u0010y2\u0011 לוֹבְשָׁם תְּחִלָּה, וְאַחַר כָּךְ לוֹבְשָׁם הָאָבֵל, וְהַמִּנְהָג עִקָּר \u0005(טוּר בְּשֵׁם סמ\"ק וכ\"כ הַמָּרְדְּכַי ה\"א וְכָל בּוֹ)\u0006. וְכֵן נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ לְאַחַר שִׁבְעָה; וְאִם לְבָשׁוֹ אָדָם אַחֵר \u0010y3\u0011 רַק \u0010t0\u0011 שָׁעָה אַחַת דַּי בְּכָךְ \u0005(כָּל בּוֹ וסמ\"ק)\u0006. \u0010g4\u0011 \u0010r5\u0011 וְאֵין צָרִיךְ לוֹמַר שֶׁאָסוּר לִלְבֹּשׁ חֲדָשִׁים. וְגַם הַסְדִינִים וְהַמַּצָּעוֹת שֶׁל מִטָּה אָסוּר לְכַבְּסָן וּלְהַצִּיעַ \u0010c0\u0011 \u0010r6\u0011 הַמְכֻבָּסִין. וְכֵן מִטְפְּחוֹת הַיָּדַיִם, אַף עַל פִּי שֶׁמֻּתָּר לְכַבְּסָן בַּמּוֹעֵד; \u0010g5\u0011 וְכֵן כָּל אוֹתָן שֶׁשָּׁנִינוּ שֶׁמֻּתָּר לְכַבְּסָן בַּמּוֹעֵד, כְּגוֹן הַיּוֹצֵא מִבֵּית הַשִּׁבְיָה וּמִבֵּית הָאֲסוּרִים, וְהַמְּנֻדֶּה שֶׁהִתִּירוּ לוֹ חֲכָמִים, וְהַנִּשְׁאָל לְחָכָם וְהֻתַּר, וְהַבָּא מִמְּדִינַת הַיָּם \u0010y4\u0011 שֶׁהָלַךְ \u0010t1\u0011 לְהַרְוִיחַ \u0010y5\u0011 וְלֹא הָיָה לוֹ פְּנַאי \u0010t2\u0011 לְגַלֵחַ, אֲסוּרִים בִּימֵי אֶבְלוֹ, \u0010g6\u0011 שֶׁאִם אֵרְעוֹ אֶחָד מֵהֶם, קֹדֶם הָאֲבֵלוּת וְנִכְנַס מִיָּד לְתוֹךְ הָאֲבֵלוּת, אָסוּר לְכַבֵּס \u0010g7\u0011 אֶלָא אִם כֵּן אֵרְעוֹ אֶחָד מֵהֶם וּתְכָפוּהוּ מִיָּד שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, אָז \u0010g8\u0011 מֻתָּר לְכַבֵּס אַף בְּנֶתֶר וְחוֹל וַאֲפִלוּ תּוֹךְ שִׁבְעָה, וּבִלְבַד שֶׁיַּעֲשֶׂנּוּ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ. וְאַחַר שֶׁתְּכָפוּהוּ אֲבֵלָיו זֶה אַחַר זֶה, מְכַבֵּס בְּמַיִם אֲבָל לֹא בְּנֶתֶר וְאָהָל. \u0010g9\u0011 \u0010r7\u0011\nמֻתָּר לְכַבֵּס בִּגְדֵי קְטַנִּים שֶׁמֵּת אֲבִיהֶם. \u0010g10\u0011 \u0010r8\u0011\nאָסוּר לִלְבֹּשׁ תּוֹךְ שִׁבְעָה כֵּלִים חֲדָשִׁים צְבוּעִים וִישָׁנִים יוֹצְאִים מִתַּחַת הַמַּכְבֵּשׁ. \u0005(פי' כְּלִי לַעֲצֹר בּוֹ הַבְּגָדִים)\u0006. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּאָסוּר לִלְבֹּשׁ בִּגְדֵי שַׁבָּת תּוֹךְ ד' שָׁבוּעוֹת הָרִאשׁוֹנִים, אֲבָל אַחַר כָּךְ מֻתָּר אֲפִלּוּ עַל אָבִיו וְאִמּוֹ, וְכֵן לַעֲשׂוֹת בְּגָדִים חֲדָשִׁים\u0006 \u0005(כָּל בּוֹ בְּשֵׁם מוֹהֲרַ\"ם)\u0006, \u0005אָבֵל נָהֲגוּ אִסּוּר כָּל י\"ב \u0010y6\u0011 \u0010g11\u0011 \u0010r9\u0011 חֹדֶשׁ.\u0006\nאָסוּר תּוֹךְ שִׁבְעָה \u0010t3\u0011 לְכַבֵּס וּלְהַנִּיחַ, בֵּין עַל יְדֵי עַצְמוֹ בֵּין עַל יְדֵי אֲחֵרִים. \u0010r10\u0011 וְאִם הָיְתָה כְּסוּתוֹ \u0010y7\u0011 בְּקִבֹּלֶת בְּיַד אֲחֵרִים, מְכַבֵּס אוֹתוֹ כִּדַרְכּוֹ כְּמוֹ שְׁאָר מְלַאכְתּוֹ בְּתָלוּשׁ שֶׁבְּיַד אֲחֵרִים, \u0010g12\u0011 \u0010r11\u0011 בְּקִבֹּלֶת.\nכָּל שְׁלֹשִׁים יוֹם אָסוּר לִלְבֹּשׁ \u0005אוֹ לְהַצִּיעַ תַּחְתָּיו (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006 בֶּגֶד \u0010r12\u0011 מְגֹהָץ, וְהוּא שֶׁיְּהֵא לָבָן וְחָדָשׁ, \u0010r13\u0011 וַאֲפִלוּ הוּא שֶׁל פִּשְׁתָּן. \u0010g13\u0011 \u0010r14\u0011 וְעַל אָבִיו וְעַל אִמּוֹ, אָסוּר עַד שֶׁיַּגִיעַ הָרֶגֶל אַחַר שְׁלֹשִׁים וְיִגְעֲרוּ בּוֹ \u0010g14\u0011 חֲבֵרָיו.\nגִהוּץ יֵשׁ אוֹמְרִים צק\"ל בִּלְשׁוֹן עֲרָב, וְיֵשׁ אוֹמְרִים דְּהַיְנוּ כִּבּוּס בְּמַיִם וְאֵפֶר אוֹ בְּנֶתֶר \u0010g15\u0011 \u0010r15\u0011 וּבֹרִית.\nאַחַר שִׁבְעָה מֻתָּר לְגַהֵץ, בֵּין לְעַצְמוֹ בֵּין לַאֲחֵרִים; וְלֹא אָמְרוּ שְׁלֹשִׁים יוֹם לְגִהוּץ, אֶלָא \u0010y8\u0011 \u0010g16\u0011 לִלְבֹּשׁ.\nיֵשׁ מִי שֶׁאוֹמֵר דְּהָאִידָּנָא לֵיכָּא אִסוּר גִהוּץ, שֶׁהֲרֵי אָמְרוּ גִהוּץ שֶׁלָנוּ כְּכִבּוּס שֶׁלָהֶם.",{"g":["\u0003מימרא דרב חסדא מדיוקא דברייתא תכפוהו אבליו וכו'\u0004 שם דף י\"ז ע\"ב:","\u0003הרמב\"ן בסת\"ה וכ\"נ מדברי הרמב\"ם בפ\"ה וקי\"ל הלכה כדברי המקיל באבל:\u0004 ","\u0003רמב\"ן בסת\"ה שלא מפני איסור מלאכה נגעו אלא שאסור ללבוש:\u0004 ","כדעת ריב\"א הביאו הטור וכן כתבו התוספות בשמו והביא ראיה ממסכת שמחות והתוס' כתבו די\"ל דכיבוס דקתני בהנך ברייתות הוא גיהוץ:","\u0003שם בסת\"ה:\u0004 ","הרא\"ש שם בפסקיו בשם הראב\"ד בסת\"ה בשם חכמי צרפת שם מהא דתניא כל אלו שאומרים מותרים לגלח במועד אסורין לגלח בימי אבלו שם דף י\"ז ע\"ב וה\"ה לכיבוס:","\u0003מהך ברייתא דלעיל דה\"ה לכיבוס וכ\"כ התוספות שם:\u0004 ","\u0003כאוקימתא דרב חסדא וכו'\u0004 שם:","\u0003כדמשני רב חסדא הא דמקשי מברייתא דתכפוהו אבליו:\u0004 ","\u0003בהלכות שמחות:\u0004 ","טור בשם הרמב\"ן בסת\"ה דס\"ל כר\"א בר שמעון בברייתא שם דף כ\"ג ע\"א דמקיל וקי\"ל דהלכה כדברי המקיל באבל ולא הקיל אלא בגזירת ל' אבל בגזירת שבעה נחמיר דומיא דכיבוס:","שם:","\u0003שם בסת\"ה והרא\"ש שם בפסקיו בשם הראב\"ד:\u0004 ","\u0003ברייתא באבל רבתי וכ\"כ הרמב\"ן בספר ת\"ה והרא\"ש שם בפסקיו:\u0004 ","\u0003עיין במ\"ש בא\"ת סימן תקנ\"א:\u0004 ","\u0003לשון הטור מדברי הרמב\"ן בסת\"ה:\u0004 ","שם וכ\"כ הנ\"י:\n(°) וכתב הכל בו בשם ר\"מ במקום שאסור ללבוש חדשים אם מניח לאחר ללבשן ב' או ג' ימים הכל מותר ונלע\"ד דוקא בצריך להם:"],"t":["\u0003שעה. \u0004 כלומר זמן מה וא\"צ שעה זמניות וכן משמע בפוסקים וכן נוהגין ולא כמ\"ש בלבוש שעה או שתים ואולי גם הוא לאו דוקא קאמר עכ\"ל הש\"ך וכתב הב\"ח דהמכובס במים לבד ולא בנתר וחול אין צריך להלבישו אחר תחלה ופשיטא דשרי לאחר ז' מיד:","\u0003להרויח. \u0004 לאפוקי לטיול. ועיין בא\"ח סי' תקל\"א:","\u0003לגלח. \u0004 וה\"ה כאן לכבס. ש\"ך:","\u0003לכבס. \u0004 הטעם משום דאסור בעשיית מלאכה. ש\"ך. וכ' מהרש\"ל עיין באו\"ח סי' תקנ\"א שהיתר פשוט לכבוד שבת לפרוש על השלחן המטפחת המכובסת:"],"r":["\u0003אבל כו'. \u0004פ\"א דתענית ומ\"ק י\"ז ב' ט\"ו א':","\u0003כל כו' ואחר כו' והעולם כו'. \u0004עתוס' כ\"ג א' ד\"ה כל כו' וביבמות מ\"ג א' ד\"ה שמותר כו':","\u0003אפילו במים כו'. \u0004עתוס' י\"ז ב' ד\"ה זאת. א\"נ כו' וכ\"ה בגמרא שם במים ולא כו':","\u0003וכשם כו'. \u0004עבא\"ח סי' תקנ\"א:\n\u0003(ליקוט) וכשם שאסור לכבס כו'. \u0004תוס' כ\"ד ב' ד\"ה ברכת ועיי\"ל ס\"ז אחר ז' מותר כו' וזהו ראיה לדברי ר\"י שם בתוס':","\u0003ונוהגין שאדם כו'. \u0004תוס' סד\"ה הנ\"ל (ע\"כ):","\u0003ואצ\"ל כו' וגם כו'. \u0004עבא\"ח שם:","\u0003וכן מטפחת כו' וכן כל כו' אא\"כ כו'. \u0004בתוספתא \u0005(פ\"ב) \u0006דמ\"ק כל אלו שאמרו מותר לגלח במועד מותרים לגלח בימי אבלן כל אלו שאמרו מותר לכבס כו' וכשם דההיא לגלח דוקא בשתכפוהו כמ\"ש י\"ז ב' ה\"ה בלכבס דכחדא מיתניא ועמ\"ש בא\"ח סי' תקל\"א בליקוטים.\n\u0003(ליקוט) וכן מטפחות כו' וכן כל כו' אא\"כ כו'. \u0004עתוס' כ\"ג א' סד\"ה כל (ע\"כ):","\u0003מותר כו'. \u0004כנ\"ל ס\"ס שפ\"ד:","\u0003אסור כו'. \u0004מדפליגי בגיהוץ שם כ\"ג א' מכלל דבכיבוס לכ\"ע אסור:","\u0003אסור כו'. \u0004עבא\"ח סי' תקנ\"א:","\u0003ואם היתה כו'. \u0004ע\"ל סי' ש\"פ:","\u0003כל ל' כו'. \u0004כרבא כ\"ג א':\n\u0003(ליקוט) סעיף ה' וסעיף ז' כל כו' אחר ז' כו'. \u0004א\"ר פ\"ז ל' יום לגיהוץ כיצד כו' מותר להוליך כו' (ע\"כ):\n\u0003(ליקוט) כל כו'. \u0004הנה הראב\"ד פי' דגם חדשים דוקא ביוצאין מן המכבש דאשניהם קאי וערא\"ש שם ס\"ק אבל הרמב\"ן חלק עליו דא\"כ הל\"ל והוא שיוצאין כו' ומדקאמר ישנים יוצאין כו' משמע דקאי ישנים וזה שלא הזכירו בדברי רבי וראב\"ש יוצאין מתחת המכבש דלדידהו דוקא בחדשין (ע\"כ):","\u0003(ליקוט) והוא כו' \u0004עתוס' כ\"ג א' ד\"ה רבא כו' ופ' כו' (ע\"כ):","\u0003ואפילו הוא כו' גיהווץ י\"א כו' יש מי שאומר כו'. \u0004עיין כל זה בא\"ח סי' תקנ\"א מש\"ש:\n\u0003(ליקוט) ואפילו הוא כו'. \u0004דמ\"ש \u0005(תענית כ\"ט ב') \u0006כלי פשתן אין בהם משום גיהוץ בישנים אמרו שאין הזיעה והטינוף יוצא מהם לגמרי משא\"כ כאן בחדשים ובירושלמי \u0005(פ\"ג דמ\"ק) \u0006איזהו גיהוץ כלי צמר חדשים וכלי פשתן מגוהצים לבנים למדנו שאף כלי פשתן יש בהם משום גיהוץ וכן אמרינן בפרק ע\"פ \u0005(ק\"ט א') \u0006בכלי פשתן המגוהצין ומיהו אנן קי\"ל כגמרא דידן דאף כלי צמר דוקא לבנים:","\u0003ועל אביו כו'. \u0004שאע\"ג דבירושלמי \u0005(סוף מ\"ק) \u0006אמרינן יב\"ח סמכינן אמ\"ש בא\"ר \u0005(פ\"ט) \u0006עד שיגיע הרגל ויגערו כו' וכמ\"ש בגמ' \u0005(כ\"ב ב') \u0006בתספורת וחד דינא להו אלא דבגיהוץ בלא רגל אין חבריו מכירים שיגערו בו משא\"כ בתספורת. תה\"א דלא כהרמב\"ם שפסק כסתמא דגמ' דבגיהוץ לא חלקו כלום ופסק דאפילו על אביו ואמו עד שלשים ע\"ש (ע\"כ):","\u0003אחר ז' כו'. \u0004מ\"ש והביאו הרא\"ש סי' ק':"]}],["אָבֵל אָסוּר לְגַלֵחַ שְׂעָרוֹ, אֶחָד שְׂעַר רֹאשׁוֹ וְאֶחָד שְׂעַר זְקָנוֹ וְאֶחָד כָּל שֵׂעָר שֶׁבּוֹ, וַאֲפִלוּ שֶׁל בֵּית הַסְתָרִים, כָּל ל' יוֹם. וּשְׂעַר שֶׁל הַשָּׂפָה וּמֵהַצְּדָדִים, \u0010y0\u0011 כָּל שֶׁמְּעַכֵּב אֶת הָאֲכִילָה, תּוֹךְ ז' אָסוּר; אַחַר שִׁבְעָה, מֻתָּר.\nיָשַׁב לְגַלֵחַ, וְאָמְרוּ לוֹ: מֵת אָבִיו, הֲרֵי זֶה מַשְׁלִים רֹאשׁוֹ, \u0010c0\u0011 אֶחָד הַמְגַלֵחַ וְאֶחָד הַמִּתְגַלֵחַ; וּמַה שֶּׁהַסַפָּר גוֹמֵר, הַיְנוּ בִּדְלֵיכָּא סַפָּר אַחֵר בְּמָתָא.\nכָּל אוֹתָם שֶׁאָמְרוּ מֻתָּר לְגַלֵחַ בְּחֹל הַמּוֹעֵד, אִם אֵרְעוֹ אֶחָד מֵאֵלוּ קֹדֶם הָאֲבֵלוּת, וְנִכְנַס מִיָּד תּוֹךְ הָאֵבֶל, אָסוּר לְגַלֵחַ. אֲבָל אִם אֵרְעוֹ אֶחָד מֵאֵלוּ, וּתְכָפוּהוּ מִיָּד שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, מְגַלֵחַ כְּדַרְכּוֹ, בֵּין בְּתַעַר בֵּין בְּמִסְפָּרַיִם, וַאֲפִלוּ תּוֹךְ שִׁבְעָה. וְאָדָם אֶחָד שֶׁתְּכָפוּהוּ אֲבֵלָיו זֶה אַחַר זֶה, מֵקֵל שְׂעָרוֹ בְּתַעַר אֲבָל לֹא בְּמִסְפָּרַיִם. \u0005וּבִלְבַד שֶׁיַּעֲשֶׂנּוּ בְּצִנְעָא (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ן)\u0006.\nעַל כָּל הַמֵּתִים מְגַלֵחַ לְאַחַר שְׁלֹשִׁים; עַל אָבִיו וְעַל אִמּוֹ, עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו. \u0005הַגָּה: וְאֵין הָרֶגֶל מְהָנֵי אִם פָּגַע קֹדֶם שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו (טוּר)\u0006. וְעַיֵּן בא\"ח סִימָן תקמ\"ח. וְשִׁעוּר גְּעָרָה יֵשׁ בּוֹ פְּלֻגְתָּא, וְנוֹהֲגִים בְּג' חֳדָשִׁים \u0005(כְּדַעַת מהרא\"י בִּפְסָקָיו וַאֲגֻדָּה ומהרי\"ל והר\"ן)\u0006. וּבִמְקוֹמוֹת אֵלּוּ נוֹהֲגִין שֶׁאֵין מִסְתַּפְּרִין עַל אָב וָאֵם כָּל י\"ב חֹדֶשׁ \u0005(מהרי\"ל מִנְהַג קְצָת מְקוֹמוֹת)\u0006, אִם לֹא לְצֹרֶךְ, כְּגוֹן שֶׁהִכְבִּיד עָלָיו שְׂעָרוֹ, אוֹ שֶׁהוֹלֵךְ בֵּין הָעוֹבְדֵי כּוֹכָבִים וּמִתְנַוֵּל בֵּינֵיהֶם בְּשַׂעֲרוֹתָיו, דְּמֻתָּר לְסַפֵּר \u0005(כֵּן הֵשִׁיב הָאוֹר זָרוּעַ)\u0006.\nאִשָּׁה מֻתֶּרֶת בִּנְטִילַת שֵׂעָר אַחַר ז'. \u0005הַגָּה: וְיֵשׁ אוֹסְרִים אַף לְאִשָּׁה, וְכֵן \u0010y1\u0011 \u0010y2\u0011 \u0010c1\u0011 עִקָּר.\u0006\nלִסְרֹק רֹאשׁוֹ בְּמַסְרֵק, מֻתָּר, אֲפִלוּ תּוֹךְ שִׁבְעָה.\nכְּשֵׁם שֶׁאָסוּר לְגַלֵחַ כָּל שְׁלֹשִׁים יוֹם, כָּךְ אָסוּר לִטֹּל צִפֹּרְנַיִם בִּכְלִי; אֲבָל בְּיָדָיו אוֹ בְּשִׁנָּיו, מֻתָּר, אֲפִלוּ תּוֹךְ שִׁבְעָה. וְאִשָּׁה שֶׁאֵרַע טְבִילָתָהּ אַחַר שִׁבְעָה, תּוֹךְ שְׁלֹשִׁים, אִם תִּטֹּל צִפָּרְנֶיהָ בְּיָדֶיהָ אוֹ בְּשִׁנֶּיהָ אֵינָהּ נוֹטֶלֶת יָפֶה, אֶלָא תֹּאמַר לְעוֹבֶדֶת כּוֹכָבִים לִטְּלָם בְּתַעַר אוֹ בְּמִסְפָּרַיִם. \u0005הַגָּה: \u0010y3\u0011 \u0010c2\u0011 וְלָאו דַּוְקָא עוֹבֶדֶת כּוֹכָבִים, אֶלָּא הוּא הַדִּין יִשְׂרְאֵלִית, וְסִרְכָא דְּלִשְׁנָא דְּחֹל הַמּוֹעֵד נָקַט (דַּעַת עַצְמוֹ)\u0006.",["\u0003כל שמעכב כו'. \u0004תימה דכאן פסק כדעת הרי\"ץ גיאות שבטור ובב\"י כתב דנקטינן כהראב\"ד ורמב\"ם דאסור כלל ואין חילוק בין שערות המעכבים האכילה או לא ע\"ש:","\u0003לסרוק כו'. \u0004כאן חסר סעיף א' שהרי נרשם סעיף ד' סעיף ו' ולא נרשם סעיף ה' ולא כעט\"ז שחלק סעיף ה' לב' סעיפים ע\"ש אלא צ\"ל סעיף חדש כמו שהוא במקצת ספרי הש\"ע וכך צ\"ל אשה מותרת בנטילת שער אחר ז'. הג\"ה ויש אוסרים אף לאשה וכן עיקר ע\"כ. וכן הוא בהקדמת סמ\"ק ע\"ש ועיין בב\"י ב' הדעות והב\"ח פסק דבמקום שדרכה של אשה לגלח שערות אלו כגון רבוי שערות דצידעא ובת צידעא מותרת ליטלם אחר ז' ע\"ש:","\u0003האשה כו'. \u0004ובב\"י משמע דאפי' לאיש מותר שאין כאן לא תענוג ולא שמחה ונ\"ל דל\"ד נקט אשה ובב\"ח כתב שמצא שט\"ס הוא וצריך להגיה לסרוק ראשו כו' וכן הוא בעט\"ז אך בהגה' סמ\"ק בשם א\"ז מתיר דוקא לאשה ולא לאיש ומביאו הב\"ח:","\u0003ולאו דוקא עובדת כוכבים כו'. \u0004ולפעד\"נ דדוקא נקט עובדת כוכבים דאלת\"ה א\"כ אפילו לאיש לשתרי לגלח או ליטול צפרניו על ידי ישראל אחר אלא ודאי כיון דשלוחו הוא אסור וא\"כ אמאי שרי באשה טפי בשלוחה מבהיא עצמה וגם דוחק לומר דסרכא דלישנא דח\"ה נקט דהא המחבר ס\"ל בא\"ח סי' תקל\"ב דמותר ליטול צפרניו בח\"ה אלא דהגמי\"י ס\"ל דאסור ליטול צפרניו בח\"ה וקאמר דעל ידי עובד כוכבים מותר דאמירה לעובד כוכבי' שבות ובמקום מצוה לא גזור ואם כן ה\"ה באבל דהא קי\"ל אמירה לעובדי כוכבים שבות אפילו בדבר שאינו של שבת וכדלעיל הלכות כלאי בהמה סי' רצ\"ז ס\"ד וא\"כ הכא דוקא לעובד כוכבים שרי דאמירה לעובד כוכבים לא אסור אלא משום שבות ובמקום מצוה לא גזרו אבל לישראל אסור ודו\"ק:"],["\u0003אחד המגלח. \u0004פי' שבשעת הגילוח נאמר למגלח שמת לו מת יכול לגמור מלאכתו משום כבוד הבריות:\n\u0003בסימן \u0004זה נחסר סעיף אחד והיינו סעיף ה' וכצ\"ל אשה מותרת בנטילת שער אחר שבעה ימים. הג\"ה ויש אוסרין אף לאשה וכן עיקר. קבלתי שנמצא כן בש\"ע של רמ\"א כתיבת ידו ז\"ל:","\u0003לסרוק ראשו במסרק כו'. \u0004כצ\"ל:","\u0003ולאו דוקא כו'. \u0004תמוה לי דאם יש איסור ליטול בעצמה ודאי גם ע\"י ישראלית אסור דיש משום לפני עור וגו') אבל נראה לי שהוצרכו ליטול ע\"י ישראלית כדי שיהיה ע\"י שינוי כמ\"ש בסמוך דאילו בידיה או בשיניה אי אפשר לה להסירם היטב כפי הצורך לטבילה אבל תימה לי על בעל הש\"ע שהרי פסק בסעיף ה' אשה מותרת בנטילת שער אחר ז' והיינו כרי\"ף ורמב\"ם וכמו שכ' ב\"י ולמה לא תהיה מותרת כאן ליטול צפרניה ע\"י עצמה בלא שינוי והלא צפרנים אינם חמורים משער. ועוד קשיא אפי' לדעת רמ\"א והלא בסי' שצ\"ג סעיף ג' התירו ליטול צפרנים בשביל למול ולמה לא נתיר בשביל טבילת מצוה לכולי עלמא ולא ראינו נשים נוהגות כן ליטול צפרנים על ידי אחר תוך שלשים:"],"\u0010g0\u0011 אָבֵל אָסוּר לְגַלֵחַ שְׂעָרוֹ, \u0010g1\u0011 \u0010r0\u0011 אֶחָד שְׂעַר רֹאשׁוֹ וְאֶחָד שְׂעַר זְקָנוֹ וְאֶחָד כָּל שֵׂעָר שֶׁבּוֹ, וַאֲפִלוּ שֶׁל בֵּית הַסְתָרִים, כָּל ל' יוֹם. \u0010g2\u0011 \u0010r1\u0011 וּשְׂעַר שֶׁל הַשָּׂפָה וּמֵהַצְּדָדִים, \u0010y0\u0011 \u0010g3\u0011 כָּל שֶׁמְּעַכֵּב אֶת הָאֲכִילָה, \u0010g4\u0011 תּוֹךְ ז' אָסוּר; אַחַר שִׁבְעָה, \u0010g5\u0011 \u0010r2\u0011 מֻתָּר.\nיָשַׁב לְגַלֵחַ, וְאָמְרוּ לוֹ: מֵת אָבִיו, הֲרֵי זֶה מַשְׁלִים רֹאשׁוֹ, \u0010c0\u0011 אֶחָד הַמְגַלֵחַ וְאֶחָד הַמִּתְגַלֵחַ; וּמַה שֶּׁהַסַפָּר גוֹמֵר, \u0010g6\u0011 הַיְנוּ בִּדְלֵיכָּא סַפָּר אַחֵר בְּמָתָא. \u0010g7\u0011\nכָּל אוֹתָם שֶׁאָמְרוּ מֻתָּר לְגַלֵחַ בְּחֹל הַמּוֹעֵד, אִם אֵרְעוֹ אֶחָד מֵאֵלוּ קֹדֶם הָאֲבֵלוּת, וְנִכְנַס מִיָּד תּוֹךְ הָאֵבֶל, אָסוּר לְגַלֵחַ. אֲבָל אִם אֵרְעוֹ אֶחָד מֵאֵלוּ, וּתְכָפוּהוּ מִיָּד שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, \u0010g8\u0011 מְגַלֵחַ כְּדַרְכּוֹ, בֵּין בְּתַעַר בֵּין בְּמִסְפָּרַיִם, \u0010r3\u0011 וַאֲפִלוּ תּוֹךְ שִׁבְעָה. וְאָדָם אֶחָד שֶׁתְּכָפוּהוּ אֲבֵלָיו זֶה אַחַר זֶה, מֵקֵל שְׂעָרוֹ בְּתַעַר אֲבָל לֹא בְּמִסְפָּרַיִם. \u0010r4\u0011 \u0005וּבִלְבַד שֶׁיַּעֲשֶׂנּוּ בְּצִנְעָא (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ן)\u0006. \u0010g9\u0011\nעַל כָּל הַמֵּתִים מְגַלֵחַ לְאַחַר שְׁלֹשִׁים; עַל אָבִיו וְעַל אִמּוֹ, עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו. \u0005הַגָּה: \u0010r5\u0011 וְאֵין הָרֶגֶל מְהָנֵי אִם פָּגַע קֹדֶם שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו (טוּר)\u0006. וְעַיֵּן בא\"ח סִימָן תקמ\"ח. וְשִׁעוּר גְּעָרָה יֵשׁ בּוֹ פְּלֻגְתָּא, וְנוֹהֲגִים בְּג' חֳדָשִׁים \u0005(כְּדַעַת מהרא\"י בִּפְסָקָיו וַאֲגֻדָּה ומהרי\"ל והר\"ן)\u0006. וּבִמְקוֹמוֹת אֵלּוּ נוֹהֲגִין שֶׁאֵין מִסְתַּפְּרִין עַל אָב וָאֵם כָּל י\"ב חֹדֶשׁ \u0005(מהרי\"ל מִנְהַג קְצָת מְקוֹמוֹת)\u0006, אִם לֹא לְצֹרֶךְ, כְּגוֹן שֶׁהִכְבִּיד עָלָיו שְׂעָרוֹ, אוֹ שֶׁהוֹלֵךְ בֵּין הָעוֹבְדֵי כּוֹכָבִים וּמִתְנַוֵּל בֵּינֵיהֶם בְּשַׂעֲרוֹתָיו, דְּמֻתָּר לְסַפֵּר \u0005(כֵּן הֵשִׁיב \u0010g10\u0011 \u0010r6\u0011 הָאוֹר זָרוּעַ)\u0006.\nאִשָּׁה מֻתֶּרֶת בִּנְטִילַת שֵׂעָר אַחַר ז'. \u0005הַגָּה: \u0010g11\u0011 \u0010r7\u0011 וְיֵשׁ אוֹסְרִים אַף לְאִשָּׁה, וְכֵן \u0010y1\u0011 \u0010y2\u0011 \u0010c1\u0011 \u0010g12\u0011 \u0010r8\u0011 עִקָּר.\u0006\nלִסְרֹק רֹאשׁוֹ \u0010t0\u0011 בְּמַסְרֵק, מֻתָּר, אֲפִלוּ תּוֹךְ שִׁבְעָה. \u0010g13\u0011\nכְּשֵׁם שֶׁאָסוּר לְגַלֵחַ כָּל שְׁלֹשִׁים יוֹם, כָּךְ אָסוּר \u0010g14\u0011 לִטֹּל צִפֹּרְנַיִם \u0010g15\u0011 \u0010r9\u0011 בִּכְלִי; אֲבָל בְּיָדָיו אוֹ \u0010g16\u0011 \u0010r10\u0011 בְּשִׁנָּיו, מֻתָּר, אֲפִלוּ תּוֹךְ שִׁבְעָה. \u0010g17\u0011 \u0010r11\u0011 וְאִשָּׁה שֶׁאֵרַע טְבִילָתָהּ אַחַר שִׁבְעָה, תּוֹךְ שְׁלֹשִׁים, אִם תִּטֹּל צִפָּרְנֶיהָ בְּיָדֶיהָ אוֹ בְּשִׁנֶּיהָ אֵינָהּ נוֹטֶלֶת יָפֶה, אֶלָא תֹּאמַר לְעוֹבֶדֶת כּוֹכָבִים לִטְּלָם בְּתַעַר אוֹ בְּמִסְפָּרַיִם. \u0005הַגָּה: \u0010y3\u0011 \u0010c2\u0011 וְלָאו דַּוְקָא עוֹבֶדֶת כּוֹכָבִים, אֶלָּא הוּא הַדִּין \u0010t1\u0011 יִשְׂרְאֵלִית, וְסִרְכָא דְּלִשְׁנָא דְּחֹל הַמּוֹעֵד נָקַט (דַּעַת עַצְמוֹ)\u0006.",{"g":["מ\"ק דף י\"ד ע\"א וע\"ב ומייתי לה שם מדקאמר ליה רחמנא לבני אהרן ראשיכם אל תפרעו מכלל דכ\"ע מיחייבי:","\u0003שם דף י\"ח:\u0004 ","\u0003כשמואל שם:\u0004 ","\u0003כרבי אמי שם:\u0004 ","כדעת הרי\"ץ גיאת ובה\"ג הביאם הטור וכ\"כ התוס' שם וצריך לי עיון שבב\"י כתב שלענין הלכה נקטינן כדברי הרמב\"ם בפ\"ה והראב\"ד דסברי שלא התירו כן אלא בח\"ה אבל באבילות לא וכדתניא באבל רבתי:","באבל רבתי בירושל' בפ\"ק דשבת וכתבוהו הרי\"ף והרא\"ש שם בפ\"ג דמ\"ק וכתב המרדכי משום דגדול כבוד הבריות:","\u0003שם במרדכי:\u0004 ","\u0003ברייתות שם דף י\"ז ע\"ב וכדמשני רב חסדא וכו'\u0004 שם:","רמב\"ן בסת\"ה ויליף לה דמתני בההיא ברייתא נמי ומכבס כסותו וההיא ע\"כ תוך ז' היא דאחר ז' אין אסור בכיבוס:","\u0003ברייתא שם דף כ\"ב ע\"ב:\u0004 ","\u0003ברייתא באבל רבתי וכ\"כ הרי\"ף שם בפ\"ג וכ\"כ הרמב\"ם:\u0004 ","\u0003כ\"כ הרב רבי מענדל אב\"ד דקק\"ק בהקדמתו לספר עמודי גולה שכצ\"ל:\u0004 ","\u0003רבינו ירוחם בשם רש\"י והמפרשים וכ\"כ הגהות מיימוני בשם י\"מ וקי\"ל הלכה כדברי המיקל באבל:\u0004 ","\u0003ברייתא שם דף י\"ז ע\"ב:\u0004 ","\u0003פירוש בין דיד בון דרגל כמימרא דרב ענן שם דף י\"ח ע\"א:\u0004 ","\u0003מימרא דרב חייא בר אשי וכו'\u0004 שם וכדעת הרי\"ף והרמב\"ם וכן הסכים הרמב\"ן בסת\"ה שבכלי אסור כל ל' יום:","\u0003כדעת הרי\"ף והרמב\"ן בספר ת\"ה והביאם הטור:\u0004 ","הגהות מיימוני פרק ה' בשם הר\"מ מאינגלטירא ולענ\"ד שאע\"ג דפסק המחבר לעיל סעיף ה' דאשה מותרת בנטילת שער י\"ל דלא התירו אלא בנטילת שער שהיא נמאסת בה ביותר:"],"t":["\u0003במסרק. \u0004 ובהגה' סמ\"ק בשם א\"ז מתיר דוקא לאשה ולא לאיש ומביאו הב\"ח. ש\"ך:","\u0003ישראלית. \u0004 והש\"ך כ' דדוקא נקט עובדת כוכבים דאלת\"ה אפילו לאיש לישתרי לגלח וליטול צפרניו ע\"י ישראל אחר אלא ודאי כיון דשלוחו הוא אסור אלא דוקא ע\"י עובדת כוכבים שרי דאמירה לעובד כוכבים לא אסור אלא משום שבות ובמקום מצוה לא גזרו ובט\"ז הקשה שהרי בס\"ה פסק דאשה מותרת בנטילת שער אחר ז' ולמה לא תהיה מותרת כאן ליטול צפרניה ע\"י עצמה בלא שינוי והלא אינם חמורים משער. גם קשה אפילו לדעת רמ\"א והלא בסי' שצ\"ג ס\"ג התיר ליטול צפרנים בשביל למול ולמה לא נתיר בשביל טבילת מצוה לכ\"ע עכ\"ל \u0005(ובנה\"כ כתב דלק\"מ דהכא כיון דאפשר ע\"י שינוי שאני דכל מה דאפשר לתקן עדיף. ומ\"ש מנטילת צפרני המוהל התם אין כונתו משום נוי רק שמתקן ב' צפרני אגודל שיש בהן צורך מילה כשהן משופעין ומחודדין לצורך הפריעה. עכ\"ל)\u0006:"],"r":["\u0003אחד שער כו'. \u0004מ\"ש והביאו הרא\"ש בסי' ק' ותוס' ביבמות מג\"א ד\"ה במקום כו':","\u0003ושער כו' ומהצדדים כו'. \u0004עברא\"ש סי' ס\"ז וכדברי הראב\"ד שפסק כרבי אמי דשפה וצדדים כל שמעכבת ושלא כהרא\"ש וכתב בת\"ה שהראב\"ד כתב דוקא בח\"ה אבל באבל אסור \u0005(וכ\"ד הרמב\"ם) \u0006מברייתא הנ\"ל וא' שער זקנו כו' והרי\"ץ גיאות כתב דתוך ז' אסור ולאחר ז' מותר והרמב\"ן הביא ראיה מירושלמי דאף תוך ז' מותר ועבב\"י שהביא הירושלמי ופסק בש\"ע כהרי\"ץ גיאות ועשה הכרעה אבל דברי הרמב\"ן עיקר כמו שהוכיח מירושלמי וכ\"ה דעת הטור:\n\u0003(ליקוט) ושער שעל כו'. \u0004דלא כהראב\"ד שכתב דדוקא בחה\"מ אבל באבלות אסור כמ\"ש בא\"ר לתספורת כיצד כו' וליתא דבירושלמי \u0005(פ\"ג) \u0006אמרינן שפה ונטילת צפרנים אית תניי תני ברגל מותר ובאבל אסור ואית תניי תני ברגל אסור ובאבל מותר כו' חייא בר אשי בשם רב הלכה כדברי שהוא מיקל כאן וכאן ר\"י בר אחא ר\"ש בר רב משמיה דרב \u0005(כ\"ה בתה\"א) \u0006הלכה כדברי שהוא מיקל בהלכות אבל רב אמר שפה כנטילת צפרנים לכ\"ד א\"ר ירמיה ובלבד הנוטות ר\"ל שנוטות על הפה ומעכב האכילה (ע\"כ):","\u0003(ליקוט) ישב כו'. \u0004א\"ר פ\"ה ה\"ח וערא\"ש פקט\"ו (ע\"כ):","\u0003ואפילו תוך כו'. \u0004ממש\"ש ומכבס כו' ועבה\"ג:","\u0003ובלבד כו'. \u0004עבא\"ח סי' תקל\"א:","\u0003ואין הרגל כו'. \u0004עתוס' כ\"ב ב' ד\"ה עד כו':","\u0003אשה כו'. \u0004מ\"ש והביאו הרא\"ש סי' ק' ותוס' דיבמות שם:\n\u0003(ליקוט) אשה כו'. \u0004בא\"ר \u0005(כ\"ה בתה\"א) \u0006כל מה שיש באיש יש באשה חוץ מתספורת אבל תוס' מפרשים כל זה במעברת סרק ע\"פ שלמטה וכן הסכים הרמב\"ן וז\"ש ויש אוסרין כו' (ע\"כ):","\u0003ויש אוסרין כו'. \u0004עבתוס' שם ובתה\"א כתב בשם תוס' דהאי תספורת דשרי היינו ע\"פ שלמטה כו' וכ\"כ בתוס' דמ\"ק י\"ח א' ד\"ה ובגנוסתרי כו':","\u0003(ליקוט) לסרוק כו'. \u0004עתוס' י\"ט ב' ד\"ה אתיא כו' (ע\"כ):","\u0003בכלי כו' אבל כו' אפילו כו'. \u0004עברא\"ש שם סי' ס\"ו ומשמע דברי הרי\"ף שכל ל' יום אסור בכלי. תה\"א ועתוס' שם י\"ח א' ד\"ה ובגנוסתרי. ולא ידענא מנ\"ל כו':","\u0003(ליקוט) אפילו תוך ז'. \u0004מעובדא דשמואל שם. תה\"א (ע\"כ):","\u0003ואשה כו'. \u0004עבא\"ח סי' תקל\"ב:"]}],["אָבֵל אָסוּר בְּשִׂמְחָה; לְפִיכָךְ לֹא יִקַח תִּינוֹק בְּחֵיקוֹ כָּל שִׁבְעָה, שֶׁמָּא יָבֹא לִידֵי שְׂחוֹק.\nעַל כָּל מֵתִים נִכְנָס לְבֵית הַמִּשְׁתֶּה לְאַחַר שְׁלֹשִׁים יוֹם; עַל אָבִיו וְעַל אִמּוֹ, \u0010c0\u0011 לְאַחַר י\"ב חֹדֶשׁ. וְאַף אִם הַשָּׁנָה מְעֻבֶּרֶת, מֻתָּר לְאַחַר י\"ב חֹדֶשׁ. וּמִיהוּ \u0010y0\u0011 שִׂמְחַת מְרֵעוּת שֶׁהָיָה חַיָּב לִפְרֹעַ אוֹתָהּ מִיָּד, מֻתָּר לַעֲשׂוֹתָהּ מִיָּד אַחַר שִׁבְעָה. אֲבָל אִם אֵינוֹ חַיָּב לְפָרְעָהּ, אָסוּר לִכָּנֵס לָהּ עַד ל'. וְעַל אָבִיו וְעַל אִמּוֹ, אַף עַל פִּי שֶׁחַיָּב לְפָרְעָהּ, אָסוּר \u0005עַד\u0006 לְאַחַר \u0010y1\u0011 י\"ב חֹדֶשׁ. \u0005הַגָּה: וּבַחֲבוּרַת מִצְוָה, כְּגוֹן שֶׁמַּשִּׂיא יָתוֹם וִיתוֹמָה לְשֵׁם שָׁמַיִם, וְאִם לֹא יֹאכַל שָׁם יִתְבַּטֵּל הַמַּעֲשֶׂה, מֻתָּר לְאַחַר ל', \u0010y2\u0011 אֲבָל תּוֹךְ ל' אָסוּר לְכָל סְעֻדַּת מִצְוָה שֶׁבָּעוֹלָם (טוּר בְּשֵׁם הָרַאֲבַ\"ד)\u0006. אֲבָל סְעֻדַּת מִצְוָה דְּלֵית בֵּיהּ שִׂמְחָה, מֻתָּר לִכָּנֵס בָּהּ, כְּגוֹן פִּדְיוֹן הַבֵּן אוֹ סְעֻדַּת בְּרִית מִילָה, מֻתָּר לֶאֱכֹל שָׁם אֲפִלּוּ תּוֹךְ שִׁבְעָה, וּבִלְבַד שֶׁלֹּא יֵצֵא מִפֶּתַח בֵּיתוֹ \u0005(ת\"ה סִי' רנ\"א)\u0006. וְיֵשׁ אוֹסְרִין בִּסְעֻדַּת בְּרִית מִילָה \u0005(מָרְדְּכַי)\u0006. וְהַמִּנְהָג שֶׁלֹּא \u0010c1\u0011 לֶאֱכֹל בְּשׁוּם סְעֻדָּה בָּעוֹלָם כָּל י\"ב חֹדֶשׁ, אִם הוּא חוּץ לְבֵיתוֹ, וּבְתוֹךְ הַבַּיִת מְקִלִּין שֶׁאוֹכֵל בְּבֵיתוֹ בִּסְעֻדַּת בְּרִית מִילָה, וְכָל שֶׁכֵּן בִּשְׁאָר סְעֻדּוֹת שֶׁאֵין בָּהֶם שִׂמְחָה. אֲבָל בִּסְעֻדַּת נִשּׂוּאִין יֵשׁ לְהַחְמִיר, כֵּן נִרְאֶה לִי. אָבֵל שֶׁהוּא בַּעַל בְּרִית אוֹ מוֹהֵל, יִלְבַּשׁ בִּגְדֵי שַׁבָּת עַד לְאַחַר הַמִּילָה. \u0010c2\u0011 וּמֻתָּר לִכָּנֵס לַמִּילָה לֶאֱכֹל שָׁם, אִם הוּא לְאַחַר ל', אַף עַל פִּי שֶׁאֵין הַמִּילָה בְּבֵיתוֹ \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת מהרי\"ל)\u0006.\nלִכָּנֵס לַחֻפָּה שֶׁלֹּא בִּשְׁעַת אֲכִילָה, לִשְׁמֹעַ הַבְּרָכוֹת, יֵשׁ מַתִּירִין וְיֵשׁ אוֹסְרִין; אֶלָא עוֹמֵד חוּץ לַבַּיִת לִשְׁמֹעַ הַבְּרָכוֹת. \u0005הַגָּה: אָבֵל לֹא יִכָּנֵס לַבַּיִת כְּלָל בְּשָׁעָה שֶׁעוֹמְדִים שָׁם בְּמַזְמוּטֵי חָתָן וְכַלָּה, וְכֵן נוֹהֲגִים בְּאַשְׁכְּנַז (טוּר)\u0006 וּבִמְדִינוֹת אֵלּוּ. וְכָל זֶה בְּבַיִת שֶׁעוֹשִׂין הַחֲתֻנָּה וְאוֹכְלִין וְשׁוֹתִין וּשְׂמֵחִין שָׁם, אֲבָל בְּחֻפָּה שֶׁעוֹשִׂין בְּבֵית הַכְּנֶסֶת, שֶׁמְּבָרְכִין שָׁם בִּרְכַּת אֵרוּסִין וְנִשּׂוּאִין וְאֵין שִׂמְחָה כְּלָל, מֻתָּר מִיָּד אַחַר שִׁבְעָה \u0005(הַגָּהוֹת מַיְמוֹנִי)\u0006. וְיֵשׁ אוֹסְרִין עַד שְׁלֹשִׁים \u0005(שָׁם בְּשֵׁם ראבי\"ה)\u0006, וְכֵן נִרְאֶה לִי. וְיֵשׁ מְקוֹמוֹת שֶׁמַּחְמִירִין לִהְיוֹת הָאָבֵל עוֹמֵד כָּל י\"ב חֹדֶשׁ חוּץ לְבֵית הַכְּנֶסֶת לִשְׁמֹעַ הַבְּרָכוֹת \u0005(הַגָּהוֹת במהרי\"ל)\u0006. וּמִכָּל מָקוֹם נִרְאֶה דְּאָבֵל יָכוֹל לְבָרֵךְ בִּרְכַּת אֵרוּסִין וְנִשּׂוּאִין תַּחַת הַחֻפָּה שֶׁבְּבֵית הַכְּנֶסֶת. \u0010c3\u0011 וְכֵן יוּכַל לְהַכְנִיס חָתָן כְּדֶרֶךְ אַרְצֵנוּ שֶׁשְּׁנֵי אֲנָשִׁים מַכְנִיסִין הֶחָתָן תַּחַת \u0010y3\u0011 הַחֻפָּה. וְיוּכַל לִלְבֹּשׁ קְצָת בִּגְדֵי שַׁבָּת בְּשָׁעָה שֶׁמַּכְנִיסִין, \u0010y4\u0011 וּבִלְבַד שֶׁיְּהֵא אַחַר ל' \u0005(ד\"ע)\u0006, וְכֵן נוֹהֲגִין. יֵשׁ מַתִּירִין לְאָבֵל לֶאֱכֹל בִּסְעֻדַּת נִשּׂוּאִין אוֹ בְּרִית מִילָה עִם הַמְּשַׁמְּשִׁין, \u0010y5\u0011 וּבִלְבַד שֶׁלֹּא יְהֵא בִּמְקוֹם שִׂמְחָה כְּגוֹן בְּבַיִת אַחֵר \u0005(כָּל בּוֹ וּבֵית יוֹסֵף בְּשֵׁם סמ\"ק)\u0006, וְיֵשׁ אוֹסְרִין \u0005(הַגָּהוֹת אֲשֵׁרִי)\u0006, וְכֵן נוֹהֲגִין, רַק שֶׁהָאָבֵל מְשַׁמֵּשׁ שָׁם, אִם יִרְצֶה, וְאוֹכֵל בְּבֵיתוֹ מִמַּה שֶּׁשּׁוֹלְחִין לוֹ מִן הַסְּעֻדָּה. יֵשׁ מַתִּירִין לְאָבֵל \u0010y6\u0011 \u0010c4\u0011 לֶאֱכֹל בְּאוֹתָהּ סְעֻדָּה שֶׁל דָּגִים שֶׁעוֹשִׂים לְאַחַר הַנִּשּׂוּאִין, כִּי מֵאַחַר שֶׁכְּבָר פָּסְקוּ לוֹמַר שֶׁהַשִּׂמְחָה בִּמְעוֹנוֹ אִית לֵיהּ הֶכֵּר שֶׁאֵין שִׂמְחָה בְּאוֹתָהּ סְעֻדָּה, וְשָׁרֵי \u0005(בֵּית יוֹסֵף בְּשֵׁם רוֹקֵחַ)\u0006. \u0010y7\u0011 יֵשׁ אוֹמְרִים דְּאָסוּר לֶאֱכֹל בִּסְעֻדָּה בַּלַּיְלָה שֶׁבְּיוֹם הַמָּחֳרָת מֵת אָבִיו אוֹ אִמּוֹ \u0005(בְּהַגָּהוֹת מִנְהָגִים בְּשֵׁם מהרי\"ו)\u0006.",["\u0003שמחת מריעות כו'. \u0004שעושים ריעים זה עם זה שאוכלים ושותים זה עם זה היום וחוזרים ואוכלים עם זה למחר:","\u0003י\"ב חודש. \u0004ואף אם השנה מעוברת סגי בי\"ב חדש. כן כתבו הפוסקים:","\u0003אבל תוך שלשים אסור.) \u0004משמע אפי' בשאר קרובים וכן משמע בעט\"ז וכן הוא להדיא בהראב\"ד שהביא בספר תורת האדם שממנו מקור דין זה ע\"ש וכן בל' הראב\"ד שברא\"ש וכן לענין שאלת שלום לעיל סימן שפ\"ה ולענין נשואין לקמן סימן שנ\"ב אין חילוק בשלשים בין אביו ואמו לשאר קרובים והב\"ח לא פירש כן ולפעד\"נ כמ\"ש:","\u0003ויכול ללבוש קצת בגדי שבת כו'. \u0004בעט\"ז השמיט תיבת קצת ואולי גם הרב ל\"ד נקט דה\"ה דיכול ללבוש כל בגדי שבת וכן נוהגין:","\u0003ובלבד שיהא אחר ל' כו'. \u0004גם כאן פירש הב\"ח דיש להתיר לאבל על שאר קרוביו תוך ל' כמו בכניסת יתום ויתומה דלעיל ולשון הרב לא משמע כן אלא נראה כמ\"ש בס\"ק ג':","\u0003ובלבד שלא יהא במקום שמחה. \u0004כגון בבית אחר כצ\"ל וכן הוא בעט\"ז:","\u0003לאכול באותה סעודה של דגים כו'. \u0004כתב הב\"ח מיהו בליל ב' אע\"פ דנוהגים בק\"ק קראקא שלא לברך שהשמחה במעונו אין לאבל לאכול באותה סעודה דל\"ד ליום ב' שכבר בעל בעילת מצוה בליל ב' כפי מנהגם ולכך עושים סעודה של דגים ביום ב' משום ברכת דגים כדאיתא פ\"ק דכתובות הלכך אינה נקראת סעודת שמחה ואין אומרים לא אשר ברא ולא שהשמחה במעונו אבל בליל ב' מקמי בעילת מצוה דמברכים אשר ברא לא נגמרו הנשואים ומה שלא נהגו לומר שהשמח' במעונו הוא מפני דמתאספי' שם אנשים ונשים כו' עיין שם:","\u0003יש אומרים דאסור לאכול כו'. \u0004וכ' העטרת זהב ולא ראיתי נוהגים כן ואני אומר דבר שאינו מצוי לא שייך בו מנהג כמו שכתב לעיל ר\"ס ק\"צ ולא ראינו אינו ראיה ואני ראיתי נוהגים לאיסור גם לקמן ס\"ס ת\"ב כתב הרב בסתם לאיסור:"],["\u0003לאחר י\"ב חדש. \u0004כתוב בטור ואף אם השנה מעוברת משמע דאחר י\"ב חדש הפסיק לגמרי האבילות מדשרי לילך לבית המשתה ותמהתי על שיש אנשים נוהגים קצת אבילות גם בחודש הי\"ג מאין להם דבר זה והוא באמת דבר בטל וכ\"כ מו\"ח ז\"ל:","\u0003בשום סעודה בעולם תוך י\"ב חדש. \u0004וה\"ה תוך ל' על שאר קרובים:","\u0003למילה לאכול שם אם הוא לאחר ל'. \u0004תמוה לי שהרי בתשובת מהרי\"ל סי' קט\"ז משמע דאחר ז' מותר וב\"י מביאו:\n\u0003שוב \u0004ראיתי בדרכי משה שהכריע כן מסברא דנפשיה לאסור עד לאחר ל' והנה דבר פשוט שעל אביו ואמו קאי זה דאלו בשאר קרובים פשיטא שמותר לאחר שלשים דאין לומר דקמ\"ל איסורא תוך ל' דא\"כ היה לו לומר ואסור כל ל' אלא דעל אביו ואמו קאי ובשאר קרובים אפי' תוך ל' שרי אחר ז' ימים והוא תמוה דבהדיא כתב הרא\"ש פרק אלו מגלחין דתוך ל' שוה בשאר קרובים לאביו ואמו ומ\"מ אין להקל בתוך ל' של אביו ואמו נגד הכרעת רמ\"א:","\u0003וכן יוכל להכניס חתן כו'. \u0004כתב מו\"ח ז\"ל ונראה דכ\"ש שיש להתיר לאבל על שאר קרוביו תוך ל' להכניס החתן דטפי יש להתיר תוך ל' על שאר קרוביו מתוך י\"ב חדש על אביו ואמו ונ\"ל דלא התירו אלא להכניס החתן תחת החופה אבל לא ליכנס לאכול על סעודת החתונה דהא אפילו במשיא יתום ויתומה לא התירו לאכול בסעודה אם לא בדרך שאם לא יהיה שם יתבטל המעשה והא ודאי דמשיא יתומה הוה כמו אביה וטפי הוה מסתבר להתיר מאותו שמכניס החתן תחת החופה כנ\"ל שלא כקצת שנוהגים להקל בזה:","\u0003באותה סעודה של דגים כו'. \u0004לפי המנהג שכתב רמ\"א שלא לאכול בשום סעודה כו' גם זה אסור:"],"\u0010g0\u0011 אָבֵל \u0010r0\u0011 אָסוּר בְּשִׂמְחָה; \u0010r1\u0011 לְפִיכָךְ לֹא יִקַח תִּינוֹק בְּחֵיקוֹ כָּל שִׁבְעָה, שֶׁמָּא יָבֹא לִידֵי שְׂחוֹק. \u0010g1\u0011\nעַל כָּל מֵתִים נִכְנָס לְבֵית הַמִּשְׁתֶּה לְאַחַר שְׁלֹשִׁים יוֹם; עַל אָבִיו וְעַל אִמּוֹ, \u0010c0\u0011 לְאַחַר י\"ב חֹדֶשׁ. \u0010g2\u0011 וְאַף אִם הַשָּׁנָה מְעֻבֶּרֶת, מֻתָּר לְאַחַר י\"ב חֹדֶשׁ. \u0010g3\u0011 וּמִיהוּ \u0010y0\u0011 שִׂמְחַת \u0010t0\u0011 מְרֵעוּת שֶׁהָיָה חַיָּב לִפְרֹעַ אוֹתָהּ מִיָּד, מֻתָּר לַעֲשׂוֹתָהּ מִיָּד אַחַר שִׁבְעָה. אֲבָל אִם אֵינוֹ חַיָּב לְפָרְעָהּ, \u0010g4\u0011 אָסוּר לִכָּנֵס לָהּ עַד ל'. \u0010g5\u0011 וְעַל אָבִיו וְעַל אִמּוֹ, \u0010r2\u0011 אַף עַל פִּי שֶׁחַיָּב לְפָרְעָהּ, אָסוּר \u0005עַד\u0006 לְאַחַר \u0010y1\u0011 י\"ב חֹדֶשׁ. \u0005הַגָּה: \u0010r3\u0011 וּבַחֲבוּרַת מִצְוָה, כְּגוֹן שֶׁמַּשִּׂיא יָתוֹם וִיתוֹמָה לְשֵׁם שָׁמַיִם, וְאִם לֹא יֹאכַל שָׁם יִתְבַּטֵּל הַמַּעֲשֶׂה, מֻתָּר לְאַחַר ל', \u0010y2\u0011 אֲבָל תּוֹךְ ל' אָסוּר לְכָל סְעֻדַּת מִצְוָה \u0010t1\u0011 שֶׁבָּעוֹלָם (טוּר בְּשֵׁם הָרַאֲבַ\"ד)\u0006. אֲבָל סְעֻדַּת מִצְוָה דְּלֵית בֵּיהּ שִׂמְחָה, מֻתָּר לִכָּנֵס בָּהּ, כְּגוֹן פִּדְיוֹן הַבֵּן אוֹ סְעֻדַּת בְּרִית מִילָה, מֻתָּר לֶאֱכֹל שָׁם אֲפִלּוּ תּוֹךְ שִׁבְעָה, וּבִלְבַד שֶׁלֹּא יֵצֵא מִפֶּתַח בֵּיתוֹ \u0005(ת\"ה סִי' רנ\"א)\u0006. \u0010r4\u0011 וְיֵשׁ אוֹסְרִין בִּסְעֻדַּת בְּרִית מִילָה \u0005(מָרְדְּכַי)\u0006. וְהַמִּנְהָג שֶׁלֹּא \u0010c1\u0011 לֶאֱכֹל בְּשׁוּם סְעֻדָּה בָּעוֹלָם כָּל י\"ב חֹדֶשׁ, אִם הוּא חוּץ לְבֵיתוֹ, וּבְתוֹךְ הַבַּיִת מְקִלִּין שֶׁאוֹכֵל בְּבֵיתוֹ בִּסְעֻדַּת בְּרִית מִילָה, וְכָל שֶׁכֵּן בִּשְׁאָר סְעֻדּוֹת שֶׁאֵין בָּהֶם שִׂמְחָה. אֲבָל בִּסְעֻדַּת נִשּׂוּאִין יֵשׁ לְהַחְמִיר, כֵּן \u0010r5\u0011 נִרְאֶה לִי. אָבֵל שֶׁהוּא בַּעַל בְּרִית אוֹ מוֹהֵל, יִלְבַּשׁ בִּגְדֵי שַׁבָּת עַד לְאַחַר הַמִּילָה. \u0010c2\u0011 וּמֻתָּר לִכָּנֵס לַמִּילָה לֶאֱכֹל שָׁם, אִם הוּא לְאַחַר \u0010t2\u0011 ל', אַף עַל פִּי שֶׁאֵין הַמִּילָה בְּבֵיתוֹ \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת מהרי\"ל)\u0006. \u0010g6\u0011 \u0010r6\u0011\nלִכָּנֵס לַחֻפָּה שֶׁלֹּא בִּשְׁעַת אֲכִילָה, לִשְׁמֹעַ הַבְּרָכוֹת, יֵשׁ מַתִּירִין וְיֵשׁ אוֹסְרִין; אֶלָא עוֹמֵד חוּץ לַבַּיִת לִשְׁמֹעַ הַבְּרָכוֹת. \u0005הַגָּה: אָבֵל לֹא יִכָּנֵס לַבַּיִת כְּלָל בְּשָׁעָה שֶׁעוֹמְדִים שָׁם בְּמַזְמוּטֵי חָתָן וְכַלָּה, וְכֵן נוֹהֲגִים בְּאַשְׁכְּנַז (טוּר)\u0006 וּבִמְדִינוֹת אֵלּוּ. \u0010r7\u0011 וְכָל זֶה בְּבַיִת שֶׁעוֹשִׂין הַחֲתֻנָּה וְאוֹכְלִין וְשׁוֹתִין וּשְׂמֵחִין שָׁם, אֲבָל בְּחֻפָּה שֶׁעוֹשִׂין בְּבֵית הַכְּנֶסֶת, שֶׁמְּבָרְכִין שָׁם בִּרְכַּת אֵרוּסִין וְנִשּׂוּאִין וְאֵין שִׂמְחָה כְּלָל, מֻתָּר מִיָּד אַחַר שִׁבְעָה \u0005(הַגָּהוֹת מַיְמוֹנִי)\u0006. וְיֵשׁ אוֹסְרִין עַד שְׁלֹשִׁים \u0005(שָׁם בְּשֵׁם ראבי\"ה)\u0006, וְכֵן נִרְאֶה לִי. וְיֵשׁ מְקוֹמוֹת שֶׁמַּחְמִירִין לִהְיוֹת הָאָבֵל עוֹמֵד כָּל י\"ב חֹדֶשׁ חוּץ לְבֵית הַכְּנֶסֶת לִשְׁמֹעַ הַבְּרָכוֹת \u0005(הַגָּהוֹת במהרי\"ל)\u0006. וּמִכָּל מָקוֹם נִרְאֶה דְּאָבֵל יָכוֹל לְבָרֵךְ בִּרְכַּת אֵרוּסִין וְנִשּׂוּאִין תַּחַת הַחֻפָּה שֶׁבְּבֵית הַכְּנֶסֶת. \u0010c3\u0011 וְכֵן יוּכַל לְהַכְנִיס חָתָן כְּדֶרֶךְ אַרְצֵנוּ שֶׁשְּׁנֵי אֲנָשִׁים מַכְנִיסִין הֶחָתָן תַּחַת \u0010y3\u0011 \u0010t3\u0011 הַחֻפָּה. וְיוּכַל לִלְבֹּשׁ קְצָת בִּגְדֵי שַׁבָּת בְּשָׁעָה שֶׁמַּכְנִיסִין, \u0010y4\u0011 \u0010t4\u0011 וּבִלְבַד שֶׁיְּהֵא אַחַר ל' \u0005(ד\"ע)\u0006, וְכֵן נוֹהֲגִין. יֵשׁ מַתִּירִין לְאָבֵל לֶאֱכֹל בִּסְעֻדַּת נִשּׂוּאִין אוֹ בְּרִית מִילָה עִם הַמְּשַׁמְּשִׁין, \u0010y5\u0011 וּבִלְבַד שֶׁלֹּא יְהֵא בִּמְקוֹם שִׂמְחָה כְּגוֹן בְּבַיִת אַחֵר \u0005(כָּל בּוֹ וּבֵית יוֹסֵף בְּשֵׁם סמ\"ק)\u0006, וְיֵשׁ אוֹסְרִין \u0005(הַגָּהוֹת אֲשֵׁרִי)\u0006, וְכֵן נוֹהֲגִין, רַק שֶׁהָאָבֵל מְשַׁמֵּשׁ שָׁם, אִם יִרְצֶה, וְאוֹכֵל בְּבֵיתוֹ מִמַּה שֶּׁשּׁוֹלְחִין לוֹ מִן הַסְּעֻדָּה. יֵשׁ מַתִּירִין לְאָבֵל \u0010y6\u0011 \u0010c4\u0011 לֶאֱכֹל בְּאוֹתָהּ סְעֻדָּה שֶׁל דָּגִים שֶׁעוֹשִׂים לְאַחַר הַנִּשּׂוּאִין, כִּי מֵאַחַר שֶׁכְּבָר פָּסְקוּ לוֹמַר שֶׁהַשִּׂמְחָה \u0010t5\u0011 בִּמְעוֹנוֹ אִית לֵיהּ הֶכֵּר שֶׁאֵין שִׂמְחָה בְּאוֹתָהּ סְעֻדָּה, וְשָׁרֵי \u0005(בֵּית יוֹסֵף בְּשֵׁם רוֹקֵחַ)\u0006. \u0010y7\u0011 יֵשׁ אוֹמְרִים דְּאָסוּר לֶאֱכֹל בִּסְעֻדָּה בַּלַּיְלָה שֶׁבְּיוֹם \u0010t6\u0011 הַמָּחֳרָת מֵת אָבִיו אוֹ אִמּוֹ \u0005(בְּהַגָּהוֹת מִנְהָגִים בְּשֵׁם מהרי\"ו)\u0006.",{"g":["\u0003מימרא דרב פפא בשם אבל רבתי מ\"ק דף כ\"ו ע\"ב:\u0004 ","\u0003ברייתא שם דף כ\"ב ע\"ב:\u0004 ","\u0003הרא\"ש שם בשם ראבי\"ה וש\"פ משמו ודייק לה מדקתני י\"ב חודש ולא קתני שנה:\u0004 ","\u0003כדמתני אמימר שם ולאלתר לאו דוקא אלא אחר ז':\u0004 ","\u0003ברייתא שם וכדמשני שם בגמרא:\u0004 ","\u0003כ\"כ הרי\"ף והרא\"ש והרמב\"ם בפ\"ו והרמב\"ן בסת\"ה:\u0004 ","\u0003טור בשם הר\"ר יהודה מברצלונא בשם י\"א וכ\"כ התוספות שם והגהות מיימוני בפ\"ו וסמ\"ג בשם י\"א:\u0004 "],"t":["\u0003מריעות. \u0004 שעושים ריעים זה עם זה שאוכלים ושותים עם זה היום וחוזרים ואוכלים עם זה למחר. ש\"ך:","\u0003שבעולם. \u0004 כתב הש\"ך משמע אפילו בשאר קרובים הדין כן. וכן לענין שאלת שלום ולענין נשואין אין חילוק כלל בין אביו ואמו לשאר קרובים. והב\"ח לא פירש כן ולא נהירא עכ\"ל:","\u0003ל'. \u0004 כתב הט\"ז דיש לתמוה על הרמ\"א שהרי בתשו' מהרי\"ל משמע דאחר ז' מותר. שוב ראיתי בד\"מ שהכריע כן מסברא דנפשיה לאסור עד אחר ל'. ודבר פשוט שעל אביו ואמו קאי דאלו בשאר קרובים פשיטא שמותר לאחר ל' דא\"ל דקמ\"ל איסורא תוך ל' דא\"כ ה\"ל לומר ואסור כל ל' אלא ע\"כ דבשאר קרובים אפי' תוך ל' שרי אחר ז' ימים והוא תמוה דבהדיא כתב הרא\"ש פ' אלו מגלחין דתוך ל' שוה בשאר קרובים לאביו ואמו. מ\"מ אין להקל בתוך ל' לאביו ואמו נגד הכרעת רמ\"א. עכ\"ל \u0005(ובנה\"כ כ' שהמעיין בתשו' מהרי\"ל סימן קכ\"ג יראה לעינים דאינו מתיר תוך ל' באביו ואמו ע\"ש)\u0006:","\u0003קצת. \u0004 בלבוש השמיט תיבת קצת ואולי גם הרב לאו דוקא נקט דה\"ה דיכול ללבוש כל בגדי שבת וכן נוהגין. ש\"ך:","\u0003ובלבד. \u0004 גם כאן פירש הב\"ח דיש להתיר לאבל על שאר קרוביו תוך ל' כמו בכניסת יתום ויתומה ואין כן דעת הש\"ך וכמ\"ש בס\"ק ב' ע\"ש. והט\"ז כ' ונ\"ל דלא התירו אלא להכניס החתן תחת החופה אבל לא ליכנס לאכול על סעודת החתונה דהא אפי' במשיא יתום ויתומה לא התירו לאכול בסעודה אם לא בדרך שאם לא יהיה שם יתבטל המעשה והא ודאי דמשיא יתומה הוה כמו אביה וטפי הוה מסתבר להתיר מאותו שמכניס החתן תחת החופה כנ\"ל שלא כקצת שנוהגים להקל בזה עכ\"ל \u0005(ויש נוהגין להיות מן המשמשים על הסעודה ולאכול אח\"כ עם המשמשים אחר גמר הסעודה וזה אין למחות בידם. אבל להסב על השלחן כשאר בעלי הסעודה ראוי למחות)\u0006:","\u0003במעונו. \u0004 כ' הב\"ח מיהו בליל ב' אע\"פ דנוהגין בק\"ק קראקא שלא לברך שהשמחה במעונו אין לאבל לאכול באותה סעודה דל\"ד ליום ב' שכבר בעל בעילת מצוה בליל ב' כפי מנהגם ולכך עושים סעודה של דגים ביום ב' משום ברכת דגים כדאיתא פ\"ק דכתובות הלכך אינה נקראת סעודת שמחה ואין אומרים לא אשר ברא ולא שהשמחה במעונו אבל בליל ב' מקמי בעילת מצוה דמברכים אשר ברא לא נגמרו הנשואים. ומה שלא נהגו לומר שהשמחה במעונו הוא מפני שמתאספים שם אנשים ונשים וכו' ע\"ש. וכתב הט\"ז ולפי המנהג שכ' רמ\"א שלא לאכול בשום סעודה גם באותה סעודה של דגים אסור. עכ\"ל:","\u0003המחרת. \u0004 וכ' הלבוש ולא ראיתי נוהגין כן ואני אומר בדבר שאינו מצוי לא שייך בו מנהג כמ\"ש לעיל ר\"ס ק\"ץ ע\"ש. ולא ראינו אינו ראיה. ואני ראיתי נוהגין לאיסור. גם לקמן ס\"ס ת\"ב כתב הרב בסתם לאיסור. עכ\"ל הש\"ך:"],"r":["\u0003אסור כו'. \u0004כ\"ב ב' וכמ\"ש בס\"ב:","\u0003לפיכך כו'. \u0004עבה\"ג:","\u0003אע\"פ שחייב כו'. \u0004מדמחלק לל' יום:","\u0003ובחבורת כו'. \u0004מ\"ש וירושלמי והביאו תוס' שם ד\"ה ולשמחת כו' ובכתובות ד' א סד\"ה אבל וביבמות מ\"ד א' סד\"ה שאני ופי' הראב\"ד דוקא כה\"ג דשאר סעודת מצוה הא חמיר מסעודת רשות ממש\"ש ולשמחת מריעות כו' ודוקא לאחר ל' יום וכן כההיא דירושלמי דמתיר בחבורת מצוה וקידוש החודש שא\"א בלעדו כגון אכילת פסח וז\"ש ואם לא כו' ועברא\"ש סימן פ\"ט. ונ\"י פי' כגון בסעודה דלית שמחה כגון ברית כו' וכמ\"ש בפרק קמא דכתובות \u0005(ח' א') \u0006ת\"ש אבל סעודת כו':\n\u0003(ליקוט) ובחבורת כו'. \u0004אבל הרמב\"ן חולק וכ' דוקא כמ\"ש בירושלמי קידוש ר\"ח ואכילת קדשים ופסח כו' (ע\"כ):","\u0003ויש אוסרין כו'. \u0004כמ\"ש בר\"פ י\"ט דשבת שנאמר שש אנכי כו' ועתוס' דמ\"ק ד\"ה הנ\"ל:","\u0003אבל שהוא כו'. \u0004עבא\"ח סי' תקנ\"ט:","\u0003ליכנס כו' יש מתירין לאבל כו' וי\"א כו'. \u0004עבתוס' ד\"ה הנ\"ל ף","\u0003(ליקוט) וכ\"ז בבית כו'. \u0004כמ\"ש בסוכה כ\"ה ב' אין שמחה כו' אין שמחה כו' (ע\"כ):"]}],["אָסוּר לִשָּׂא אִשָּׁה כָּל ל' יוֹם, אֲפִלוּ בְּלֹא סְעֻדָּה; וּלְאַחַר שְׁלֹשִׁים, מֻתָּר, אֲפִלוּ עַל אָבִיו וְאִמּוֹ, וַאֲפִלוּ לַעֲשׂוֹת \u0010c0\u0011 סְעֻדָּה. וּמֻתָּר לְקַדֵּשׁ אִשָּׁה אֲפִלוּ בְּיוֹם הַמִּיתָה, וְהוּא שֶׁלֹּא יַעֲשֶׂה סְעֻדָּה, אֶלָא אִם כֵּן עָבְרוּ שְׁלֹשִׁים יוֹם. \u0010y0\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּגַם לְאָרֵס אָסוּר כָּל ל' יוֹם (טוּר וְהָרֹא\"שׁ וְהָרַמְבַּ\"ן)\u0006 וְכֵן \u0010y1\u0011 עִקָּר.\nמֵתָה אִשְׁתּוֹ, אָסוּר לִשָּׂא אַחֶרֶת עַד שֶׁיַּעַבְרוּ עָלֶיהָ \u0010c1\u0011 שָׁלֹשׁ רְגָלִים, \u0005אֲבָל לִכָּנֵס לְבֵית הַמִּשְׁתֶּה, \u0010y2\u0011 דִּינוֹ כְּמוֹ בִּשְׁאָר קְרוֹבִים, (טוּר)\u0006 \u0010c2\u0011 וְרֹאשׁ הַשָּׁנָה וְיוֹם כִּפּוּרִים אֵינָם חֲשׁוּבִים כִּרְגָלִים לְעִנְיָן זֶה. וְאִם לֹא \u0010y3\u0011 קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה, אוֹ שֶׁיֵּשׁ לוֹ בָּנִים קְטַנִּים, אוֹ שֶׁאֵין לוֹ מִי שֶׁיְּשַׁמְּשֶׁנּוּ, \u0010y4\u0011 \u0010c3\u0011 מֻתָּר לְקַדֵּשׁ מִיָּד וְלִכְנֹס אַחַר שִׁבְעָה; וְלֹא יָבֹא עָלֶיהָ עַד לְאַחַר שְׁלֹשִׁים יוֹם, אֶלָא אִם כֵּן לֹא קִיֵּם מִצְוֹת פְּרִיָּה וּרְבִיָּה, שֶׁאָז מֻתָּר לָבוֹא עָלֶיהָ אַחַר שִׁבְעָה. \u0005הַגָּה: וְהוּא הַדִּין בִּשְׁאָר אֲבֵלוּת, אֲפִלּוּ בַּאֲבֵלוּת דְּאָבִיו וְאִמּוֹ, מֻתָּר לִשָּׂא וְלָבוֹא עָלֶיהָ אַחַר שִׁבְעָה, אִם לֹא קִיֵּם פִּרְיָה וּרְבִיָּה. יֵשׁ אוֹמְרִים דְּאַף מִי שֶׁהוּא עָשִׁיר וִיכֹלֶת בְּיָדוֹ לִשְׂכֹּר לוֹ מְשָׁרְתִים וּמְשָׁרְתוֹת, מִכָּל מָקוֹם אִם אֵין בִּתּוֹ אוֹ כַּלָּתוֹ אֶצְלוֹ בְּבֵיתוֹ שֶׁתּוּכַל לְשַׁמְּשׁוֹ בַּחֲפִיפַת הָרֹאשׁ אוֹ שְׁאָר דְּבָרִים שֶׁמִּתְבַּיֵּשׁ מֵאֲחֵרִים, מִקְרֵי אֵין לוֹ מִי שֶׁיְּשַׁמְּשֶׁנּוּ, וְכָל כַּיּוֹצֵא בָּזֶה (פִּסְקֵי מהרא\"י סי\"ג)\u0006 ; וְלָכֵן נִשְׁתַּרְבֵּב הַמִּנְהָג שֶׁרַבִּים מְקִלִּין בָּעִנְיָן וְנוֹשְׂאִין נָשִׁים תּוֹךְ שָׁלֹשׁ רְגָלִים, וּבַעַל נֶפֶשׁ יָחוּשׁ לְעַצְמוֹ. מִי שֶׁתְּפָשׂוֹ הַשַּׂר וְאֵינוֹ רוֹצֶה לְהַנִּיחוֹ מִתְּפִיסָתוֹ, עַד שֶׁיִּשָּׂא אִשָּׁה תּוֹךְ שָׁלֹשׁ רְגָלִים אַחַר מִיתַת אִשְׁתּוֹ, יֵשׁ מַתִּירִין מִשּׁוּם צַעַר דִּידֵיהּ \u0005(בֵּית יוֹסֵף)\u0006, וְכֵן נִרְאֶה לִי \u0010c4\u0011 עִקָּר.\nמִי שֶׁלֹּא קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה, וְשִׁדֵּךְ אִשָּׁה וְאַחַר שֶׁהֵכִין צָרְכֵי חֻפָּה, מֵת אֲחִי \u0010y5\u0011 \u0010c5\u0011 הַמְשֻׁדֶּכֶת, מֻתָּר לְכָּנְּסָהּ וְלָבוֹא עָלֶיהָ אַחַר שִׁבְעָה. \u0005הַגָּה: וְכֵן אִם יֵשׁ לוֹ בָּנִים קְטַנִּים וְנִתְרַצָּה לְאָחוֹת אִשְׁתּוֹ, \u0010y6\u0011 מֻתָּר לְכַנְּסָהּ, \u0010y7\u0011 כִּי הִיא מְרַחֶמֶת עַל בְּנֵי אֲחוֹתָהּ יוֹתֵר מֵאַחֶרֶת (כ\"כ בְּפי' הָרֹא\"שׁ וְהַגָּהוֹת מַיְמוֹנִי וּמָרְדְּכַי)\u0006.",["\u0003וי\"א כו'. \u0004מיהו לקשר עצמו בשידוכין בלא אירוסין ודאי שרי אפי' ביום המיתה. ב\"ח:","\u0003מתה אשתו כו'. \u0004והיא שמת בעלה אינה מתאבלת אלא ל' יום אלא שאסורה ליארס ולינשא עד ג' חדשי' משום הבחנה כדאיתא ביבמות (ונתבאר בא\"ע סימן י\"ג) עכ\"ל טור וכ\"כ הפוסקים וכתב המרדכי הטעם שאין האשה צריכה להמתין ג' רגלים משום דאשה בכל דהו ניחא לה ושוכחת אהבת הראשון לאחר ל' יום. ואם אירע שנשא' תוך ל' יום לאבילותן של שאר קרובים לא תבעל כן דעת הרמב\"ם לפי מה שפירש הב\"ח דבריו ע\"ש:","\u0003דינו כמו בשאר קרובים. \u0004לעיל סי' שצ\"א וכן כל שאר אבילות אינו נוהג רק ל' יום כמו בשאר קרובים:","\u0003מצות פריה ורביה. \u0004באופן שנתבאר בא\"ע סי' א':","\u0003מותר לקדש מיד. \u0004כתב הב\"ח דהיינו לדעת המחבר דמתיר בסעיף א' לקדש ביום המיתה ולא קיימא לן הכי אלא רשאי לקדשה ולכנסה מיד אחר ז':","\u0003מותר לכנסה כו'. \u0004כיון דאיכא הפסד בדבר אם לא יכנוס וגם לא קיים פריה ורביה וע\"ל סי' שמ\"ב:","\u0003מותר לכנסה. \u0004מיד ויבא עליה אחר שבעה כן כ' העט\"ז והב\"ח כתב דלא יבא עליה עד אחר שלשים ונראה דלא פליגי דהעט\"ז מיירי בשלא קיים מצות פריה ורביה והב\"ח איירי כשקיים:","\u0003כי היא מרחמת כו'. \u0004ולכן מותר אפי' בלא הפסד:"],["\u0003ומותר לקדש כו'. \u0004שמא יקדמנו אחר ברחמים:","\u0003ג' רגלים. \u0004לאו משום תוספת אבילות אלא כדי שתשתכח הראשונה מדעתו בשעה שיהיה עם השניה וע\"י שמחת הרגלים הוא שוכח הראשונה:","\u0003וראש השנה ויוה\"כ אינם כרגלים. \u0004באגודה פסק דחשיבי כרגלים אף לענין זה:\n\u0003כתוב \u0004בטור והיא שמת בעלה אינה מתאבלת אלא ל' יום עכ\"ל ולענין שתינשא לאחר מבואר בא\"ע סי' י\"ג והנשים נוהגות שמתאבלות שנה תמימה על בעליהן ואיני יודע להם סמך וראיה ואולי עושות בשביל בניהם שמתאבלין י\"ב חדש והטעם שאשה אינה צריכה להמתין ג' רגלים להנשא לאחר כמו האיש דאשה בכל דהו ניחא לה. כן כ' המרדכי:","\u0003מותר לקדש מיד ולכנוס אחר ז'. \u0004לטעמיה אזיל דפסק בסעיף א' כרמב\"ם דבכל גווני מותר לקדש מיד אבל למאי דפסק רמ\"א שם דאפי' לקדש אסור ה\"נ אסור לקדש עד אחר ז' ותימה על רמ\"א שלא כ' כאן כלום:","\u0003מי שלא קיים כו'. \u0004בטור איתא בלשון זה מעשה באחד ששידך ומת אחי המשודכת קרוב לחופה אחר שהזמין הקרואין והתיר ר\"ת שתכנס לחופה תוך ל' משום פריה ורביה שלו כיון ששידך זאת ואם לא ישאנה לא ישא אחרת אבל אם לא שידך אע\"פ שחפץ בזאת יותר מבאחרת אסור וכן הורה אדוני אבי הרא\"ש הלכ' למעשה לאחד ששידך והכין כל צרכי החופה ומתה אחות המשודכת והוא לא קיים פריה ורביה והתיר לו לכנוס ולבעול אחר ז' ימים שיהיה לו הפסד בדבר אם לא יכנוס אבל בלא הפסד אמר שלא היה מתיר עכ\"ל היתר זה הוא חידוש דאע\"פ שהיא אבילה ואינה חייבת בפריה ורביה מ\"מ התיר לה בשבילו שהוא יקיים פריה ורביה וזה לא מצינו בגמרא להיתר בהדיא אלא דמעשה שהיה כך היה סמוך לחופה והרא\"ש לא סמך על ר\"ת להתיר בזה אלא משום הפסד הסעודה שצירף לזה ומשים הכי במעשה דר\"ת לא זכר כלום מהכנת צרכי החופה כמו שזכר בהוראת הרא\"ש ובזה מתורץ מה שהקשה מו\"ח ז\"ל למה הצריך הטור לזכור שנית תורף המעשה בהוראת הרא\"ש ולא כ' בקיצור וכן הורה אדוני אבי ז\"ל למעשה משום הפסד דיש שינוי לשון בהוראת הרא\"ש ובאבן עזר סי' י\"ד כתב הטור סתם מי ששידך אשה ואירעה אבל כו' ולא זכר שם משום הפסד הסעודה והיינו לדינא הוא כן אבל למעשה אין היתר אלא משום הפסד סעודה וכהרא\"ש וכ\"פ בש\"ע כאן והא דכ' כאן מותר לכנסה ולבוא עליה אחר ז' הך לכנסה הוא נמי אחר ז' דוקא דאין לומר משום הפסד מותר לכנסה אפי' תוך ז' דהא כ' הרא\"ש פרק אלו מגלחין בשם ר\"ת אפי' במקום פסידא לא התירו לכנוס תוך ז' אף באין לו בנים דלא התירו אלא באביו של חתן ואמה של הכלה דוקא וכל שכן שהיא אבילה ואינה מחויבת בפריה ורביה אלא ודאי כמו שכתבתי ובפרישה האריך בזה ולא עיין בדברי ר\"ת שכ' הרא\"ש בשמו כמו שזכרתי:","\u0003מותר לכנסה כי היא מרחמת. \u0004פי' כניסה לחופה דוקא התירו אבל לא לבעול עד אחר ל' יום בדין זה דהרי אין כאן מצות פריה ורביה:"],"אָסוּר \u0010g0\u0011 לִשָּׂא אִשָּׁה כָּל ל' יוֹם, \u0010r0\u0011 אֲפִלוּ בְּלֹא סְעֻדָּה; וּלְאַחַר שְׁלֹשִׁים, \u0010g1\u0011 \u0010r1\u0011 מֻתָּר, אֲפִלוּ עַל אָבִיו וְאִמּוֹ, וַאֲפִלוּ לַעֲשׂוֹת \u0010c0\u0011 \u0010g2\u0011 \u0010r2\u0011 סְעֻדָּה. וּמֻתָּר לְקַדֵּשׁ אִשָּׁה \u0010r3\u0011 אֲפִלוּ בְּיוֹם הַמִּיתָה, \u0010g3\u0011 וְהוּא שֶׁלֹּא יַעֲשֶׂה סְעֻדָּה, אֶלָא אִם כֵּן עָבְרוּ שְׁלֹשִׁים יוֹם. \u0010y0\u0011 \u0010r4\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּגַם \u0010t0\u0011 לְאָרֵס אָסוּר כָּל ל' יוֹם (טוּר וְהָרֹא\"שׁ \u0010g4\u0011 וְהָרַמְבַּ\"ן)\u0006 וְכֵן \u0010y1\u0011 \u0010g5\u0011 עִקָּר.\nמֵתָה \u0010t1\u0011 אִשְׁתּוֹ, אָסוּר לִשָּׂא אַחֶרֶת עַד שֶׁיַּעַבְרוּ עָלֶיהָ \u0010c1\u0011 \u0010r5\u0011 שָׁלֹשׁ רְגָלִים, \u0010r6\u0011 \u0005אֲבָל לִכָּנֵס לְבֵית הַמִּשְׁתֶּה, \u0010y2\u0011 דִּינוֹ כְּמוֹ \u0010t2\u0011 בִּשְׁאָר קְרוֹבִים, (טוּר)\u0006 \u0010c2\u0011 \u0010g6\u0011 \u0010r7\u0011 וְרֹאשׁ הַשָּׁנָה וְיוֹם כִּפּוּרִים אֵינָם \u0010t3\u0011 חֲשׁוּבִים כִּרְגָלִים לְעִנְיָן זֶה. \u0010g7\u0011 וְאִם לֹא \u0010y3\u0011 קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה, אוֹ שֶׁיֵּשׁ לוֹ בָּנִים קְטַנִּים, \u0010g8\u0011 אוֹ שֶׁאֵין לוֹ מִי שֶׁיְּשַׁמְּשֶׁנּוּ, \u0010y4\u0011 \u0010c3\u0011 \u0010t4\u0011 \u0010r8\u0011 מֻתָּר לְקַדֵּשׁ מִיָּד וְלִכְנֹס אַחַר שִׁבְעָה; \u0010g9\u0011 וְלֹא יָבֹא עָלֶיהָ עַד לְאַחַר שְׁלֹשִׁים יוֹם, \u0010g10\u0011 אֶלָא אִם כֵּן לֹא קִיֵּם מִצְוֹת פְּרִיָּה וּרְבִיָּה, שֶׁאָז מֻתָּר לָבוֹא עָלֶיהָ אַחַר שִׁבְעָה. \u0005הַגָּה: \u0010r9\u0011 וְהוּא הַדִּין בִּשְׁאָר אֲבֵלוּת, אֲפִלּוּ בַּאֲבֵלוּת דְּאָבִיו וְאִמּוֹ, מֻתָּר לִשָּׂא וְלָבוֹא עָלֶיהָ אַחַר שִׁבְעָה, אִם לֹא קִיֵּם פִּרְיָה וּרְבִיָּה. יֵשׁ אוֹמְרִים דְּאַף מִי שֶׁהוּא עָשִׁיר וִיכֹלֶת בְּיָדוֹ לִשְׂכֹּר לוֹ מְשָׁרְתִים וּמְשָׁרְתוֹת, מִכָּל מָקוֹם אִם אֵין בִּתּוֹ אוֹ כַּלָּתוֹ אֶצְלוֹ בְּבֵיתוֹ שֶׁתּוּכַל לְשַׁמְּשׁוֹ בַּחֲפִיפַת הָרֹאשׁ אוֹ שְׁאָר דְּבָרִים שֶׁמִּתְבַּיֵּשׁ מֵאֲחֵרִים, מִקְרֵי אֵין לוֹ מִי שֶׁיְּשַׁמְּשֶׁנּוּ, וְכָל כַּיּוֹצֵא בָּזֶה (פִּסְקֵי מהרא\"י סי\"ג)\u0006 ; וְלָכֵן נִשְׁתַּרְבֵּב הַמִּנְהָג שֶׁרַבִּים מְקִלִּין בָּעִנְיָן וְנוֹשְׂאִין נָשִׁים תּוֹךְ שָׁלֹשׁ רְגָלִים, וּבַעַל נֶפֶשׁ יָחוּשׁ לְעַצְמוֹ. מִי שֶׁתְּפָשׂוֹ הַשַּׂר וְאֵינוֹ רוֹצֶה לְהַנִּיחוֹ מִתְּפִיסָתוֹ, עַד שֶׁיִּשָּׂא אִשָּׁה תּוֹךְ שָׁלֹשׁ רְגָלִים אַחַר מִיתַת אִשְׁתּוֹ, יֵשׁ מַתִּירִין מִשּׁוּם צַעַר דִּידֵיהּ \u0005(בֵּית יוֹסֵף)\u0006, וְכֵן נִרְאֶה לִי \u0010c4\u0011 \u0010g11\u0011 \u0010r10\u0011 עִקָּר.\nמִי שֶׁלֹּא קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה, וְשִׁדֵּךְ אִשָּׁה וְאַחַר שֶׁהֵכִין צָרְכֵי חֻפָּה, מֵת אֲחִי \u0010y5\u0011 \u0010c5\u0011 \u0010t5\u0011 הַמְשֻׁדֶּכֶת, מֻתָּר לְכָּנְּסָהּ וְלָבוֹא עָלֶיהָ אַחַר שִׁבְעָה. \u0005הַגָּה: וְכֵן אִם יֵשׁ לוֹ בָּנִים קְטַנִּים וְנִתְרַצָּה לְאָחוֹת אִשְׁתּוֹ, \u0010y6\u0011 \u0010t6\u0011 מֻתָּר לְכַנְּסָהּ, \u0010y7\u0011 כִּי הִיא מְרַחֶמֶת עַל בְּנֵי אֲחוֹתָהּ יוֹתֵר מֵאַחֶרֶת (כ\"כ בְּפי' הָרֹא\"שׁ וְהַגָּהוֹת מַיְמוֹנִי וּמָרְדְּכַי)\u0006.",{"g":["\u0003לשון הטור מברייתא מ\"ק דף כ\"ג ע\"א:\u0004 ","מדברי אביו הרא\"ש שם בשם ר\"ת דלא אסרו אלא בית השמחה דליכא מצוה וה\"ר יוסף הביא ראיה לדבריו ממסכת שמחות:","\u0003רמב\"ם בפ\"ו מהלכות אבל ולמדו מדין האירוסין בט\"ב וציינתיו בא\"ח בסי' תקנ\"א:\u0004 ","כן פי' בכ\"מ ובב\"י בתירוץ ב' דס\"ל לרבינו דהא דאסר רבי יוסי כל ל' יום מפני האיבול יבמות דף מ\"א ע\"א איירי בסעודה:","\u0003כרבי יוסי ושאני ט' באב דאבלות ישנה היא:\u0004 ","שם במ\"ק בברייתא וכת\"ק כדעת הרמב\"ם והביאו הטור וכתבו התוס' בשם רבי יונה ולא שייך כאן לומר דקי\"ל הלכה כדברי המיקל באבל דימי אבלו כלו להן וטעמא דשלש רגלים כדי שישא אחרת ולא יהיה זוכר מן הראשונה ויהיו ב' דעות במטה:","\u0003הרא\"ש שם וש\"פ:\u0004 ","\u0003שם בברייתא:\u0004 ","\u0003ירושלמי פ\"ד דיבמות:\u0004 ","\u0003שם בברייתא וכדמפרש רב פפא:\u0004 ","\u0003טור בשם ר\"ת וכ\"כ הרא\"ש גם בשם הראב\"ד ושכן נראה מדברי הרי\"ף:\u0004 ","\u0003שם בשם מעשה לפני ר\"ת וכ\"כ הרא\"ש בפסקיו שם וש\"פ:\u0004 "],"t":["\u0003לארס. \u0004 מיהו לקשר עצמו בשידוכין בלא אירוסין ודאי שרי אפי' ביום המיתה. ב\"ח:","\u0003אשתו. \u0004 והיא שמת בעלה אינה מתאבלת אלא ל' יום רק שאסורה ליארס ולינשא עד אחר ג' חדשים משום הבחנה כמ\"ש בא\"ע סי' י\"ג עכ\"ל הטור. וכתב המרדכי הטעם שאין האשה צריכה להמתין ג' רגלים משום דאשה בכל דהו ניחא לה ושוכחת אהבת הראשון אחר ל' יום. ואם אירע שנשאת תוך ל' יום לאבלותה של שאר קרובים לא תבעל כן דעת הרמב\"ם לפי מה שפי' הב\"ח דבריו ע\"ש עכ\"ל הש\"ך:","\u0003בשאר. \u0004 וכן כל שאר אבילות אינו נוהג רק שלשים יום כמו בשאר קרובים. ש\"ך:","\u0003חשובים. \u0004 ובאגודה פסק דחשיבי כרגלים אף לענין זה \u0005(ובנה\"כ כ' דכל הפוסקים חולקים עליו וכן דעת כל האחרונים וטעמייהו מסתבר עכ\"ל)\u0006 ומיהו נראה לפי המנהג שכתב רמ\"א שרבים מקילין ובעל נפש יחוש לעצמו אבל אם עברו ג' רגלים עם ר\"ה ויוה\"כ יוכל לסמוך על בעל אגודה. והטעם לזה אינו משום תוספת אבילות אלא כדי שתשתכח הראשונה מדעתו בשעה שיהיה עם השניה וע\"י שמחת הרגלים הוא שוכח הראשונה ע\"כ יש מי שרוצה לחלק בזה אם היה לו אשה חולנית זמן רב או שהיה להם איבה ורצה לגרשה ומתה שאז ודאי נשכח אהבת הראשונה מלבו מיד. משא\"כ אם היתה עמו באהבה תמיד וחלתה כדרך העולם ומתה דאז אהבת הראשונה תקועה בלבו ואינה נשכחת עד אחר ג' רגלים. אבל לא נראה לחלק כן מדעתנו מה שאינו נזכר בגדולי פוסקים וגם האחרונים אין מזכירין מזה רק בת' מיימונית מפלפל ומאריך בזה ע\"ש בהלכות שמחות. ואין לזוז מדברי הרמ\"א. ועי' בתשובת חב\"י שאלה ד' מעשה שאירע שם והחמיר בזה ועי' תשובת ראנ\"ח ח\"ב שאלה ד':","\u0003לקדש. \u0004 והב\"ח כתב דהיינו לדעת המחבר דמתיר בס\"א לקדש ביום המיתה ולא קיימא לן הכי אלא דאחר שבעה מיד רשאי לקדשה ולכנסה:","\u0003לכנסה. \u0004 כתב הש\"ך הטעם כיון דאיכא הפסד בדבר אם לא יכניס וגם לא קיים פריה ורביה וע\"ל סי' שמ\"ב. והט\"ז כתב דהך לכנסה קאי אלאחר שבעה דבתוך ז' אפי' במקום הפסד אסור ע\"ש:","\u0003מותר לכנסה. \u0004 מיד ולבא עליה אחר שבעה כ\"כ הלבוש והב\"ח כתב דלא יבא עליה עד אחר ל' ונראה דלא פליגי דהלבוש מיירי בשלא קיים פו\"ר והב\"ח איירי בדקיים עכ\"ל הש\"ך:"],"r":["\u0003אפילו בלא כו'. \u0004אפי' קודם שבוע של ת\"ב אסור כה\"ג וכ\"ש כאן וכמ\"ש ביבמות מ\"ג ע\"ש:","\u0003אפי' על כו'. \u0004תוס' שם בד\"ה שאני כו' ובכתובות ד' א' ד\"ה אבל כו':","\u0003ומותר כו' והוא כו'. \u0004כמו קודם ת\"ב כנ\"ל:","\u0003אפילו ביום כו'. \u0004עתוס' דיבמות שם במגילת סתרים כו':","\u0003וי\"א דגם כו'. \u0004בגמרא שם ונראה דהרמב\"ם מפרש מש\"ש מתקיף כו' וה\"נ במתני' חוץ מן האלמנה היינו ג\"כ בסעודה ומפרש שאני אבילות כו' דאבילות דת\"ב חמירא לכן אסור במשא ומתן דלפרש\"י קשה מ\"ט אסור במו\"מ ועתוס' הנ\"ל שדחקו בזה וכתבו ומפרש ר\"ת כו' וצ\"ל דבאבילות דרבים כו' ועוד דייק הרמב\"ם ממ\"ש כאן כל שלשים לנשואין וכמו שהקשה תוס' שם וע\"ש:\n(ליקוט) א\"ר פ\"ז ל' יום לאירוסין ל' יום לנשואין אלא דשם אמרו בשניהן דוקא בסעודה \u0005(ועיין בחידושי הרמב\"ן יבמות שם ובתה\"א) \u0006כיצד לאירוסין כו' כיצד לנשואין כו' (ע\"כ):","\u0003(ליקוט) שלש רגלים. \u0004עתוס' שם ד\"ה עד שיעברו כו' (ע\"כ):","\u0003אבל ליכנס כו'. \u0004פשוט הוא ולמד מדברי התוס' הנ\"ל שכתבו וא\"ת דהכא כו' א\"נ נשואין נקט כו' וכל דברי תוס' כתב ג\"כ הרא\"ש במ\"ק שם ועתוס' דמ\"ק כ\"ג א' ד\"ה עד כו' דימי אבלו כו':","\u0003ור\"ה וי\"כ כו'. \u0004דטעמא ששמחת הרגלים ישכח את אשתו כמ\"ש תוס' הנ\"ל ועבא\"ח סי' תקפ\"ב ס\"ח ובספ\"ג דעירובין \u0005(מ' ב') \u0006א\"ד כיון דלא איקרי רגלים כו':","\u0003לקדש מיד כו' וליכנס כו' אא\"כ כו'. \u0004עבתוס' שם ושם ורא\"ש שם:\n\u0003(ליקוט) אא\"כ כו'. \u0004כדעת ר\"ת ואף שהתוס' ביבמות שם וכתובות שם הקשו על ר\"ת תירץ הרא\"ש במ\"ק שם דמ\"ש בא\"ר אחר ל' מילתא פסיקתא נקט כו' ע\"ש: שאז מותר לבא כו'. שבדידיה אין הכניסה אלא משום ביאה אבל דעת ר\"י שבזה אפי' הכניסה אסור עד שלשים ושכן משמע בא\"ר: אחר שבעה. דוקא מהא דכתובות ד' א' דע\"כ שם בבחור וכמ\"ש תוס' שם (ע\"כ):","\u0003וה\"ה כו'. \u0004שם ושם:","\u0003מי שלא כו' ובן כו'. \u0004שם ושם מהא דמ\"ק ואמר לאחותה כו' ע\"ש:"]}],["אָבֵל, ג' יָמִים הָרִאשׁוֹנִים אֵינוֹ יוֹצֵא לְבֵית הָאָבֵל \u0010y0\u0011 וְלֹא לְבֵית הַקְבָרוֹת; מִכָּאן וָאֵילָךְ, אִם מֵת לַאֲחֵרִים מֵת בִּשְׁכוּנָתוֹ, יוֹצֵא אַחַר הַמִּטָּה לְבֵית הַקְבָרוֹת, וְאֵינוֹ יוֹשֵׁב בִּמְקוֹם הַמְנַחֲמִים אֶלָא בִּמְקוֹם הַמִּתְנַחֲמִים; וְאִם אֵין שָׁם כְּדֵי מִטָּה וְקוֹבְרֶיהָ, \u0010y1\u0011 יוֹצֵא אֲפִלוּ בְּיוֹם רִאשׁוֹן וַאֲפִלוּ בִּשְׁכוּנָה אַחֶרֶת. \u0005הַגָּה: וּמִקְצָת יוֹם ג' הֲרֵי הוּא כְּכֻלּוֹ (הַגָּהוֹת מַיְמוֹנִי פ\"ז)\u0006. וְלֹא רָאִיתִי נוֹהֲגִין כֵּן עַכְשָׁו, כִּי אֵין אָבֵל הוֹלֵךְ לְבֵית הַקְּבָרוֹת וְלֹא לְבֵית הָאָבֵל כָּל שִׁבְעָה; וְאֶפְשָׁר שֶׁלָּאו חִיּוּב הוּא, אֶלָּא רְשׁוּת, וּמֵאַחַר שֶׁעַכְשָׁו אֵין מִתְנַחֲמִין כְּמוֹ בִּימֵיהֶם, שֵׁב וְאַל תַּעֲשֶׂה עָדִיף.\nאָבֵל, שָׁבוּעַ הָרִאשׁוֹן אֵינוֹ יוֹצֵא מִפֶּתַח בֵּיתוֹ, \u0010y2\u0011 וַאֲפִלוּ לִשְׁמֹעַ בִּרְכוֹת חֻפָּה אוֹ בִּרְכוֹת הַמִּילָה. \u0005הַגָּה: מִיהוּ הַמֵּקֵל לָצֵאת בַּלַּיְלָה, מִפְּנֵי הַצֹּרֶךְ, לֹא הִפְסִיד (ת\"ה סִימָן ר\"צ)\u0006. וְהָא דְּאָסוּר לָצֵאת חוּץ לְבֵיתוֹ, הַיְנוּ דַּוְקָא לְטַיֵּל, אוֹ לְמַשָּׂא וּמַתָּן וְכַדּוֹמֶה, אֲבָל אִם שָׁלַח מוֹשֵׁל אַחֲרָיו \u0005(מָרְדְּכַי ה\"א)\u0006 אוֹ שֶׁצָּרִיךְ לֵילֵךְ בַּדֶּרֶךְ אוֹ לִשְׁאָר דְּבָרִים הַצְּרִיכִים לוֹ הַרְבֵּה, כְּגוֹן דָּבָר הָאָבֵד, מֻתָּר לוֹ לָצֵאת \u0005(תּוֹסָפוֹת סוֹף מ\"ק)\u0006, וְכֵן נוֹהֲגִין. וְדִין נְעִילַת סַנְדָּלָיו, עַיֵּן לְעֵיל סִימָן שפ\"ב. שְׁנִיָּה, יוֹצֵא וְאֵינוֹ יוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר; שְׁלִישִׁית, יוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר. \u0005הַגָּה: וְאִם רוֹצֶה שֶׁלֹּא לֵישֵׁב בִּמְקוֹמוֹ בְּשָׁבוּעַ שְׁלִישִׁית וּלְדַבֵּר, הָרְשׁוּת בְּיָדוֹ (הגמי\"י)\u0006. וְעַכְשָׁו נוֹהֲגִין שֶׁאֵין יוֹשְׁבִין בִּמְקוֹמָם כָּל שְׁלֹשִׁים; וְעַל אָבִיו וְאִמּוֹ כָּל י\"ב חֹדֶשׁ, וְאֵין לְמִנְהָג זֶה עִקָּר, מִכָּל מָקוֹם אֵין לְשַׁנּוֹת מִן הַמִּנְהָג, כִּי כָּל מָקוֹם לְפִי מִנְהָגוֹ; רְבִיעִית, הֲרֵי הוּא כִּשְׁאָר כָּל אָדָם. אֲפִלוּ לֹא שָׁלְמוּ שְׁלֹשָׁה שְׁבוּעוֹת, כְּגוֹן שֶׁמֵּת בְּאֶמְצַע שָׁבוּעַ, מִיָּד כְּשֶׁכָּלָה אוֹתוֹ שָׁבוּעַ וּשְׁנַיִם שֶׁאַחֲרָיו, חָשׁוּב שָׁבוּעַ הַבָּא רְבִיעִית.\nהָאָבֵל אֵינוֹ יוֹצֵא בַּחֹל לְבֵית הַכְּנֶסֶת, אֲבָל בְּשַׁבָּת יוֹצֵא. \u0005וְכֵן לְבֵית הַמִּדְרָשׁ (בֵּיתיוֹסֵף)\u0006. וְאָנוּ נוֹהֲגִים שֶׁבְּכָל יוֹם קְרִיאַת הַתּוֹרָה יוֹצֵא לב\"ה. \u0005הַגָּה: וּבִמְדִינוֹת אֵלּוּ נוֹהֲגִין שֶׁאֵין יוֹצֵא אֶלָּא בְּשַׁבָּת. וְאִם הָאָבֵל מוֹהֵל \u0010y3\u0011 אוֹ בַּעַל בְּרִית, לְאַחַר שְׁלֹשָׁה, מִתְפַּלֵּל בְּבֵיתוֹ, וּכְשֶׁמְּבִיאִין הַתִּינוֹק לָמוּל, הוֹלֵךְ הָאָבֵל לְבֵית הַכְּנֶסֶת (הַגָּהוֹת אֲשֵׁרִי)\u0006. אֲבָל, תּוֹךְ שְׁלֹשָׁה, לֹא יֵצֵא \u0010y4\u0011 אֶלָּא אִם כֵּן אֵין מוֹהֵל אַחֵר בָּעִיר \u0010y5\u0011 \u0005(אוֹר זָרוּעַ)\u0006 ; וְיֵשׁ מְקִלִּין אֲפִלּוּ תּוֹךְ שְׁלֹשָׁה, אֲפִלּוּ אִם יֵשׁ מוֹהֵל אַחֵר בָּעִיר \u0005(בֵּית יוֹסֵף)\u0006 ; וּמֻתָּר לוֹ לְתַקֵּן הַצִּפָּרְנַיִם וּלְגַלֵּחַ לְצֹרֶךְ הַמִּילָה, אֲבָל אִם יֵשׁ מוֹהֵל אַחֵר אָסוּר \u0005(סְבָרַת הָרַב דְּלֹא כְּאוֹר זָרוּעַ דְּמַתִּיר סְתָם)\u0006. וְכֵן כָּל דְּבַר מִצְוָה שֶׁאִי אֶפְשָׁר לַעֲשׂוֹת בְּלֹא הָאָבֵל, מֻתָּר לוֹ לָצֵאת לְקַיֵּם הַמִּצְוָה \u0005(סְבָרַת הָרַב וּבֵית יוֹסֵף)\u0006.\nהַנּוֹהֲגִים כְּשֶׁהֵם אֲבֵלִים שֶׁלֹּא לְשַׁנּוֹת מְקוֹמָם בְּבֵית הַכְּנֶסֶת בְּשַׁבָּת, יָפֶה הֵם עוֹשִׂים. \u0005הַגָּה: \u0010y6\u0011 וְיֵשׁ אוֹמְרִים שֶׁגַּם בְּשַׁבָּת יְשַׁנֶּה מְקוֹמוֹ (נִמּוּקֵי יוֹסֵף סוֹף פֶּרֶק הַמּוֹכֵר פֵּרוֹת)\u0006, וְכֵן הַמִּנְהָג פָּשׁוּט, וְאֵין לְשַׁנּוֹת הַמִּנְהָג.",["\u0003ולא לבה\"ק. \u0004אם מת לאחרים מת:","\u0003יוצא אפי' ביום ראשון. \u0004כצ\"ל:","\u0003אפילו לשמוע כו'. \u0004אף על גב דאבל חייב בכל המצות היינו במצות עשה שבגופו כגון ציצית ותפילין או למול את בנו אבל לילך לחופה או למילה לשמוע הברכות בשביל גמילות חסד אין לו לצאת מפתח ביתו. תשובת הרא\"ש:","\u0003או בעל ברית. \u0004פי' סנדק ולכן תוך שלשה לא יצא אבל אבי הבן פשיטא דאפילו תוך שלשה ימים יצא לכולי עלמא:","\u0003אא\"כ אין מוהל אחר בעיר. \u0004ואז מותר אפילו ביום ראשון:","\u0003ויש מקילין כו'. \u0004הוא הב\"י וק\"ק דהרי הבית יוסף כ' דלפי מנהגו שהאבל יוצא לב\"ה להתפלל בכל יום קריאת התורה כ\"ש שיצא כדי למול אפילו תוך שלשה ימים ראשונים ואפילו יש מוהל אחר בעיר עכ\"ל וא\"כ מאחר שכ' הרב דאנו נוהגין שאינו יוצא אלא בשבת למה כ' סברת היש מקילין כאן:","\u0003וי\"א שגם בשבת כו'. \u0004דס\"ל שאין זה דבר של פרהסיא שאין אבילות ניכר בזה כל כך שהרבה פעמים אדם מחליף מקומו אפילו אינו אבל עכ\"ל עט\"ז מהנ\"י ולמ\"ש לקמן ר\"ס ת' דאבלות הנוהג כל שלשים נוהג אפילו בשבת בלאו הכי ניחא:"],[],"\u0010g0\u0011 אָבֵל, ג' יָמִים הָרִאשׁוֹנִים אֵינוֹ יוֹצֵא לְבֵית הָאָבֵל \u0010y0\u0011 וְלֹא לְבֵית \u0010t0\u0011 הַקְבָרוֹת; מִכָּאן וָאֵילָךְ, אִם מֵת לַאֲחֵרִים מֵת \u0010g1\u0011 בִּשְׁכוּנָתוֹ, יוֹצֵא אַחַר הַמִּטָּה לְבֵית הַקְבָרוֹת, \u0010g2\u0011 וְאֵינוֹ יוֹשֵׁב בִּמְקוֹם הַמְנַחֲמִים אֶלָא בִּמְקוֹם הַמִּתְנַחֲמִים; \u0010g3\u0011 \u0010r0\u0011 וְאִם אֵין שָׁם כְּדֵי מִטָּה וְקוֹבְרֶיהָ, \u0010y1\u0011 יוֹצֵא אֲפִלוּ בְּיוֹם רִאשׁוֹן וַאֲפִלוּ בִּשְׁכוּנָה אַחֶרֶת. \u0005הַגָּה: \u0010r1\u0011 וּמִקְצָת יוֹם ג' הֲרֵי הוּא כְּכֻלּוֹ (הַגָּהוֹת מַיְמוֹנִי פ\"ז)\u0006. וְלֹא רָאִיתִי נוֹהֲגִין כֵּן עַכְשָׁו, כִּי אֵין אָבֵל הוֹלֵךְ לְבֵית הַקְּבָרוֹת וְלֹא לְבֵית הָאָבֵל כָּל שִׁבְעָה; וְאֶפְשָׁר שֶׁלָּאו חִיּוּב הוּא, אֶלָּא רְשׁוּת, וּמֵאַחַר שֶׁעַכְשָׁו אֵין מִתְנַחֲמִין כְּמוֹ בִּימֵיהֶם, שֵׁב וְאַל תַּעֲשֶׂה עָדִיף. \u0010g4\u0011\nאָבֵל, שָׁבוּעַ הָרִאשׁוֹן אֵינוֹ יוֹצֵא מִפֶּתַח בֵּיתוֹ, \u0010y2\u0011 \u0010g5\u0011 וַאֲפִלוּ לִשְׁמֹעַ בִּרְכוֹת חֻפָּה אוֹ בִּרְכוֹת הַמִּילָה. \u0005הַגָּה: מִיהוּ הַמֵּקֵל לָצֵאת בַּלַּיְלָה, מִפְּנֵי הַצֹּרֶךְ, לֹא הִפְסִיד (ת\"ה סִימָן ר\"צ)\u0006. \u0010r2\u0011 וְהָא דְּאָסוּר לָצֵאת חוּץ לְבֵיתוֹ, הַיְנוּ דַּוְקָא לְטַיֵּל, אוֹ לְמַשָּׂא וּמַתָּן וְכַדּוֹמֶה, אֲבָל אִם שָׁלַח מוֹשֵׁל אַחֲרָיו \u0005(מָרְדְּכַי ה\"א)\u0006 אוֹ שֶׁצָּרִיךְ לֵילֵךְ בַּדֶּרֶךְ אוֹ לִשְׁאָר דְּבָרִים הַצְּרִיכִים לוֹ הַרְבֵּה, כְּגוֹן דָּבָר הָאָבֵד, מֻתָּר לוֹ לָצֵאת \u0005(תּוֹסָפוֹת סוֹף מ\"ק)\u0006, וְכֵן נוֹהֲגִין. וְדִין נְעִילַת סַנְדָּלָיו, עַיֵּן לְעֵיל סִימָן שפ\"ב. \u0010g6\u0011 \u0010r3\u0011 שְׁנִיָּה, יוֹצֵא וְאֵינוֹ יוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר; שְׁלִישִׁית, יוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר. \u0005הַגָּה: \u0010r4\u0011 וְאִם רוֹצֶה שֶׁלֹּא לֵישֵׁב בִּמְקוֹמוֹ בְּשָׁבוּעַ שְׁלִישִׁית וּלְדַבֵּר, הָרְשׁוּת בְּיָדוֹ (הגמי\"י)\u0006. וְעַכְשָׁו נוֹהֲגִין שֶׁאֵין יוֹשְׁבִין בִּמְקוֹמָם כָּל שְׁלֹשִׁים; וְעַל אָבִיו וְאִמּוֹ כָּל י\"ב חֹדֶשׁ, וְאֵין לְמִנְהָג זֶה עִקָּר, מִכָּל מָקוֹם אֵין לְשַׁנּוֹת מִן הַמִּנְהָג, כִּי כָּל מָקוֹם לְפִי מִנְהָגוֹ; \u0010g7\u0011 רְבִיעִית, הֲרֵי הוּא כִּשְׁאָר כָּל אָדָם. \u0010g8\u0011 אֲפִלוּ לֹא שָׁלְמוּ שְׁלֹשָׁה שְׁבוּעוֹת, כְּגוֹן שֶׁמֵּת בְּאֶמְצַע שָׁבוּעַ, מִיָּד כְּשֶׁכָּלָה אוֹתוֹ שָׁבוּעַ וּשְׁנַיִם שֶׁאַחֲרָיו, חָשׁוּב שָׁבוּעַ הַבָּא \u0010g9\u0011 \u0010r5\u0011 רְבִיעִית.\nהָאָבֵל אֵינוֹ יוֹצֵא בַּחֹל לְבֵית הַכְּנֶסֶת, אֲבָל בְּשַׁבָּת יוֹצֵא. \u0005וְכֵן לְבֵית הַמִּדְרָשׁ (בֵּיתיוֹסֵף)\u0006. וְאָנוּ נוֹהֲגִים שֶׁבְּכָל יוֹם קְרִיאַת הַתּוֹרָה יוֹצֵא לב\"ה. \u0005הַגָּה: וּבִמְדִינוֹת אֵלּוּ נוֹהֲגִין שֶׁאֵין יוֹצֵא אֶלָּא בְּשַׁבָּת. \u0010r6\u0011 וְאִם הָאָבֵל מוֹהֵל \u0010y3\u0011 אוֹ בַּעַל \u0010t1\u0011 בְּרִית, לְאַחַר שְׁלֹשָׁה, מִתְפַּלֵּל בְּבֵיתוֹ, וּכְשֶׁמְּבִיאִין הַתִּינוֹק לָמוּל, הוֹלֵךְ הָאָבֵל לְבֵית הַכְּנֶסֶת (הַגָּהוֹת אֲשֵׁרִי)\u0006. אֲבָל, תּוֹךְ שְׁלֹשָׁה, לֹא יֵצֵא \u0010y4\u0011 \u0010r7\u0011 אֶלָּא אִם כֵּן אֵין מוֹהֵל אַחֵר \u0010t2\u0011 בָּעִיר \u0010y5\u0011 \u0010r8\u0011 \u0005(אוֹר זָרוּעַ)\u0006 ; וְיֵשׁ \u0010t3\u0011 מְקִלִּין אֲפִלּוּ תּוֹךְ שְׁלֹשָׁה, אֲפִלּוּ אִם יֵשׁ מוֹהֵל אַחֵר בָּעִיר \u0005(בֵּית יוֹסֵף)\u0006 ; וּמֻתָּר לוֹ לְתַקֵּן הַצִּפָּרְנַיִם וּלְגַלֵּחַ לְצֹרֶךְ הַמִּילָה, אֲבָל אִם יֵשׁ מוֹהֵל אַחֵר אָסוּר \u0005(סְבָרַת הָרַב דְּלֹא כְּאוֹר זָרוּעַ דְּמַתִּיר סְתָם)\u0006. וְכֵן כָּל דְּבַר מִצְוָה שֶׁאִי אֶפְשָׁר לַעֲשׂוֹת בְּלֹא הָאָבֵל, מֻתָּר לוֹ לָצֵאת לְקַיֵּם הַמִּצְוָה \u0005(סְבָרַת הָרַב \u0010g10\u0011 \u0010r9\u0011 וּבֵית יוֹסֵף)\u0006.\nהַנּוֹהֲגִים כְּשֶׁהֵם אֲבֵלִים שֶׁלֹּא לְשַׁנּוֹת מְקוֹמָם בְּבֵית הַכְּנֶסֶת בְּשַׁבָּת, יָפֶה הֵם עוֹשִׂים. \u0005הַגָּה: \u0010y6\u0011 \u0010r10\u0011 וְיֵשׁ אוֹמְרִים שֶׁגַּם בְּשַׁבָּת יְשַׁנֶּה מְקוֹמוֹ (נִמּוּקֵי יוֹסֵף סוֹף פֶּרֶק הַמּוֹכֵר פֵּרוֹת)\u0006, וְכֵן הַמִּנְהָג פָּשׁוּט, וְאֵין לְשַׁנּוֹת הַמִּנְהָג.",{"g":["\u0003ברייתא מ\"ק דף כ\"א ע\"ב:\u0004 ","\u0003רמב\"ן בסת\"ה בשם ברייתא באבל רבתי:\u0004 ","\u0003שם בברייתא במ\"ק:\u0004 ","\u0003ברייתא באבל רבתי פ\"ו וכתב הב\"י ופשוט הוא שהרי הוא חייב בכל המצות:\u0004 ","\u0003ברייתא מ\"ק דף כ\"ג ע\"א:\u0004 ","תשובת הרא\"ש כלל כ\"ז וכתב הא דאבל חייב בכל המצות היינו במצות עשה שבגופו כגון ציצית ותפילין או למול את בנו אבל לילך לחופה ולמילה לשמוע ברכה בשביל גמילות חסד אין לו לצאת מפתח ביתו וכ\"כ הטור ורבינו ירוחם בשם המפרשים:\n(°) וכתב מהרש\"ל בסוף מ\"ק שנוהגים ליקח עפר במנעלים כשהולך:","\u0003שם בברייתא:\u0004 ","\u0003שם בברייתא:\u0004 ","\u0003טור ובסי' שצ\"ט כתבו בשם ה\"ר שמעון:\u0004 ","שם ובשם אביו הרא\"ש:\n(°) והמנהג שנכנס האבל לבית הכנסת קודם תפלת ערבית והזקנים עומדים עליו בפתח ב\"ה והאולם בשתי שורות לנחמו ע\"פ אגדה דפרקי ר\"א בפרק ט\"ז והביאו הטור וראיתי פה לק\"ק ספרדיים מנהגים אחרים בענין התפלה וההשכבה ומנהג המנחמים ואומרים שם בערב (לפני תפלת ערבית) ובבוקר אחר התפלה מזמור מ\"ט בתהלים וצדוק הדין (אחר כל תפלה ותפלה) גם המה מנהגים עתיקין וותיקין):\n(°) בד\"מ השמיט תיבת ולגלח והוא הנכון לפענ\"ד דמה צורך מילה שייך לגלוח ומ\"מ לא רציתי למחקו דאולי אצפרני' קאי אלא שהלשון אינו מדויק ועוד דא\"כ צ\"ל ולגלחם ודוק:","\u0003בית יוסף וכדעתו:\u0004 "],"t":["\u0003הקברות. \u0004 אם מת לאחרים מת. כ\"כ הש\"ך \u0005(אבל אם מת לו מת יוצא אפילו ביום כנ\"ל:\n\n\u0006","\u0003ברית. \u0004 פי' סנדק ולכן תוך שלשה ימים לא יוצא אבל אבי הבן פשיטא דאפי' תוך ג' ימים יוצא לכ\"ע. ש\"ך:","\u0003בעיר. \u0004 ואז מותר אפילו ביום ראשון. ש\"ך:","\u0003מקילין. \u0004 כתב הש\"ך וקשה דהב\"י כ\"כ לפי מנהגו שהאבל יוצא לבהכ\"נ להתפלל בכל יום קריאת התורה כ\"ש שיוצא כדי למול אפילו תוך ג' ימים ראשונים ואפילו יש מוהל אחר בעיר וא\"כ מאחר שכתב הרב דאנו נוהגים שאינו יוצא אלא בשבת למה כתב סברת היש מקילין כאן עכ\"ל:"],"r":["\u0003(ליקוט) ואם אין שם כו'. \u0004א\"ר פ\"ו בד\"א כו' (ע\"כ):","\u0003ומקצת כו'. \u0004עתוס' שם ד\"ה מכאן כו' וה\"נ תניא כו' מיום ג' ואילך כו' ושם א' ד\"ה בשלישי כו':\n\u0003(ליקוט) ומקצת כו'. \u0004שם \u0005(בא\"ר פ\"ו) \u0006מת באותה כו' בשלישי יוצא כו' וכן אמרו שם לענין שאילת שלום שאלו בשלומו כו' בשלישי כו' \u0005(ועיין לעיל סי' ש\"פ ס\"ק ו' בשם הרמב\"ן) \u0006(ע\"כ).","\u0003והא דאסור כו'. \u0004עתוס' ך\"ז א' סד\"ה אם כו':","\u0003שניה כו' ואינו מדבר. \u0004טור דכ\"ש הוא:","\u0003ואם רוצה כו' ועכשיו כו' כל שלשים. \u0004עתוס' שם ד\"ה ר' יהודה כו' \u0005(והמנהג הוא ע\"פ הירושלמי דהלכה כר\"י שבשבוע ד' יושב במקומו ואינו מדבר. לכן נהגו שלא לישב במקומו כדי שיוכל לדבר ועיין דרכי משה):\u0006","\u0003האבל כו' וכן לבה\"מ כו'. \u0004במ\"ש והביאו הרא\"ש שם אלא דאוסר בבה\"כ אף בשבת רק בבה\"מ ור\"ה גאון כתב דהכל לפי המנהג ע\"ש ברא\"ש:","\u0003ואם האבל כו'. \u0004כמו לבה\"ק דס\"א וכ\"כ נ\"י מכאן ואילך הולך כו' וכן בכל דבר מצוה כו':","\u0003אא\"כ אין כו' וכן כ\"ד כו'. \u0004כנ\"ל ס\"א ואם אין שם כדי כו':","\u0003ויש מקילין כו'. \u0004כ\"כ ב\"י לפי מנהגם שיוצא בכל קריאת התורה לבה\"כ כנ\"ל:","\u0003הנוהגים כו'. \u0004משום שהוא דבר שבפרהסיא:","\u0003וי\"א כו'. \u0004והביא ראיה ממ\"ש בב\"ב ק' א' א\"ל א\"כ אף בשבת כו' וב\"י דחה דבריו ואין דבריו מוכרחין ועוד נ\"ל ראיה מפרקי ר\"א והביא הרא\"ש בסי' צ\"ג והיו ישראל הולכין בשבת כו' הנכנס כו' וע\"ל ר\"ס ת' ומש\"ש \u0005(בס\"ק ג'):\u0006"]}],["אֵין מִתְקַשִּׁין עַל הַמֵּת יוֹתֵר מִדַּאי; וְכָל הַמִּתְקַשֶּׁה עָלָיו יוֹתֵר מִדַּאי, עַל מֵת אַחֵר הוּא בּוֹכֶה; אֶלָא שְׁלֹשָׁה יָמִים לִבְכִי, שִׁבְעָה לְהֶסְפֵּד, שְׁלֹשִׁים לְתִסְפֹּרֶת וּלְגִהוּץ.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר הָעָם. אֲבָל תַּלְמִידֵי חֲכָמִים, הַכֹּל לְפִי חָכְמָתָם; וְאֵין בּוֹכִים עֲלֵיהֶם יוֹתֵר מִל' יוֹם; וְאֵין מַסְפִּידִין עֲלֵיהֶם יוֹתֵר מִי\"ב חֹדֶשׁ; וְכֵן חָכָם שֶׁבָּא שְׁמוּעָתוֹ לְאַחַר י\"ב חֹדֶשׁ, \u0010y0\u0011 אֵין מַסְפִּידִין אוֹתוֹ.\nיוֹצְאִין לְבֵית הַקְבָרוֹת \u0010y1\u0011 וּפוֹקְדִים עַל הַמֵּתִים שְׁלֹשָׁה יָמִים, שֶׁמָּא עֲדַיִן הוּא חַי.\nכָּל שְׁלֹשָׁה יָמִים יִרְאֶה הָאָבֵל כְּאִלוּ חֶרֶב מֻנַּחַת לוֹ בֵּין כְּתֵפָיו; מִשִּׁלֹשָׁה וְעַד שִׁבְעָה, כְּאִלוּ זָקוּף כְּנֶגְדּוֹ בְּקֶרֶן זָוִית; מִשִּׁבְעָה וְעַד שְׁלֹשִׁים, כְּאִלוּ עוֹבֵר לְפָנָיו בַּשּׁוּק; וְכָל אוֹתָהּ הַשָּׁנָה הַדִּין מְתוּחָה כְּנֶגֶד אוֹתָהּ מִשְׁפָּחָה; וְאִם נוֹלָד בֵּן זָכָר בְּאוֹתָהּ מִשְׁפָּחָה, נִתְרַפֵּאת כָּל הַמִּשְׁפָּחָה.\nאֶחָד מֵהַחֲבוּרָה שֶׁמֵּת, תִּדְאַג כָּל הַחֲבוּרָה.\nכָּל מִי שֶׁאֵינוֹ מִתְאַבֵּל כְּמוֹ שֶׁצִּוּוּ חֲכָמִים, הֲרֵי זֶה אַכְזָרִי; אֶלָא יִפְחַד וְיִדְאַג וִיפַשְׁפֵּשׁ בְּמַעֲשָׂיו וְיַחֲזֹר בִּתְשׁוּבָה.",["\u0003אין מספידין אותו. \u0004אפילו ביום שמועה:","\u0003ופוקדים על המתים כו'. \u0004כתב הפרישה זה היה דוקא בימיהם שהיו מניחין את המת בכוכין () [אולי שייך זה בסי' זה סעיף ד' עמ\"ש ואם נולד בן זכר כו'. מראה כהן:] והיה אפשר לגלות את המת ולראותו וכתב עוד הדרישה בשם מהרש\"ל אדם שמת לו מת ובתוך שלשים נולד לו בן אין עושין שמחה ומשתה ביום המילה רוקח עכ\"ל וכמדומה שאין נוהגין כן:"],[],"\u0010g0\u0011 אֵין מִתְקַשִּׁין עַל הַמֵּת יוֹתֵר מִדַּאי; וְכָל הַמִּתְקַשֶּׁה עָלָיו יוֹתֵר מִדַּאי, עַל מֵת אַחֵר הוּא בּוֹכֶה; \u0010g1\u0011 אֶלָא שְׁלֹשָׁה יָמִים לִבְכִי, שִׁבְעָה לְהֶסְפֵּד, שְׁלֹשִׁים \u0010g2\u0011 \u0010r0\u0011 לְתִסְפֹּרֶת וּלְגִהוּץ.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר הָעָם. אֲבָל תַּלְמִידֵי חֲכָמִים, הַכֹּל לְפִי חָכְמָתָם; \u0010g3\u0011 וְאֵין בּוֹכִים עֲלֵיהֶם יוֹתֵר מִל' יוֹם; \u0010g4\u0011 וְאֵין מַסְפִּידִין עֲלֵיהֶם יוֹתֵר מִי\"ב חֹדֶשׁ; \u0010g5\u0011 וְכֵן חָכָם שֶׁבָּא שְׁמוּעָתוֹ לְאַחַר י\"ב חֹדֶשׁ, \u0010y0\u0011 אֵין מַסְפִּידִין אוֹתוֹ. \u0010g6\u0011\nיוֹצְאִין לְבֵית הַקְבָרוֹת \u0010y1\u0011 \u0010t0\u0011 וּפוֹקְדִים עַל הַמֵּתִים שְׁלֹשָׁה יָמִים, שֶׁמָּא עֲדַיִן הוּא חַי. \u0010g7\u0011 \u0010r1\u0011\nכָּל שְׁלֹשָׁה יָמִים יִרְאֶה הָאָבֵל כְּאִלוּ חֶרֶב מֻנַּחַת לוֹ בֵּין כְּתֵפָיו; מִשִּׁלֹשָׁה וְעַד שִׁבְעָה, כְּאִלוּ זָקוּף כְּנֶגְדּוֹ בְּקֶרֶן זָוִית; מִשִּׁבְעָה וְעַד שְׁלֹשִׁים, כְּאִלוּ עוֹבֵר לְפָנָיו בַּשּׁוּק; \u0010r2\u0011 וְכָל אוֹתָהּ הַשָּׁנָה הַדִּין מְתוּחָה כְּנֶגֶד אוֹתָהּ מִשְׁפָּחָה; \u0010g8\u0011 וְאִם נוֹלָד בֵּן זָכָר בְּאוֹתָהּ מִשְׁפָּחָה, נִתְרַפֵּאת כָּל הַמִּשְׁפָּחָה. \u0010g9\u0011\nאֶחָד מֵהַחֲבוּרָה שֶׁמֵּת, תִּדְאַג כָּל הַחֲבוּרָה. \u0010g10\u0011\nכָּל מִי שֶׁאֵינוֹ מִתְאַבֵּל כְּמוֹ שֶׁצִּוּוּ חֲכָמִים, הֲרֵי זֶה אַכְזָרִי; \u0010r3\u0011 אֶלָא יִפְחַד וְיִדְאַג וִיפַשְׁפֵּשׁ בְּמַעֲשָׂיו וְיַחֲזֹר בִּתְשׁוּבָה.",{"g":["\u0003מימרא דרב יהודה אמר רב מ\"ק דף כ\"ז ע\"ב:\u0004 ","\u0003שם בגמ':\u0004 ","\u0003טור בשם הרשב\"א:\u0004 ","\u0003שם מצוואת רבי הושיבו ישיבה לאחר ל' יום דלא עדיפנא ממרע\"ה וכו'\u0004 כתובות דף ק\"ג ע\"ב:","\u0003ג\"ז משם דספדי תריסר ירחי שתא:\u0004 ","מדאמר דוד שאול נפקו להו י\"ב ירחא שתא ולא דרכי' למספדיה יבמו' דף ע\"ט ע\"א וכ\"כ הרמב\"ן בסת\"ה בשם גאון:","\u0003ברייתא דאבל רבתי פ\"ח:\u0004 ","ירושלמי סוף מ\"ק ואיתא שם למה הדבר דומה לכיפה של אבנים כיון שנתרועעה אבן אחת נתרועעה כולה:","\u0003ג\"ז שם משמיה דר' יוחנן:\u0004 ","\u0003מימרא דר' חייא בר אבא וכו'\u0004 שבת דף ק\"ה ע\"ב:","\u0003רמב\"ם פרק י\"ג מהלכות אבל וכתב הכ\"מ שדברי רבינו ראוים אליו:\u0004 "],"t":["\u0003ופוקדים. \u0004 כתב הפרישה זה היה דוקא בימיהם שהיו מניחין את המת בכוכין והיה אפשר לגלות את המת ולראותו. וכתב עוד בשם מהרש\"ל אדם שמת לו מת ובתוך ל' נולד לו בן אין עושין שמחה ומשתה ביום המילה רוקח עכ\"ל. וכמדומה שאין נוהגין כן. ש\"ך:"],"r":["\u0003בד\"א כו'. \u0004וראיה מרבי וכמש\"ו וכן במשה ואהרן:","\u0003כל שלשה כו'. \u0004גמ' כ\"ז ב':","\u0003וכל אותה כו' ואם נולד כו'. \u0004ירושלמי שם:","\u0003אלא יפחד כו'. \u0004כמ\"ש מה יתאונן כו':"]}],["\u0010c0\u0011 כֵּיוָן שֶׁעָמְדוּ מְנַחֲמִים מֵאֵצֶל הָאָבֵל בְּיוֹם שְׁבִיעִי, מֻתָּר בְּכָל דְּבָרִים שֶׁאָסוּר בָּהֶם תּוֹךְ שִׁבְעָה, דְּמִקְצָת הַיּוֹם כְּכֻלוֹ, לֹא שְׁנָא מִקִצָת יוֹם שְׁבִיעִי לֹא שְׁנָא מִקְצָת יוֹם שְׁלֹשִׁים, \u0010y0\u0011 כֵּיוָן שֶׁהֵנֵץ הַחַמָּה בְּיוֹם שְׁלֹשִׁים, בָּטְלוּ מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים \u0005(רֹא\"שׁ וְרַבֵּנוּ יְרוּחָם)\u0006. \u0005הַגָּה: וּבִמְדִינוֹת אֵלּוּ שֶׁאֵין הַמְּנַחֲמִין רְגִילִין לָבוֹא בְּיוֹם ז', צָרִיךְ לְהַמְתִּין עַד שָׁעָה שֶׁרְגִילִין הַמְּנַחֲמִים לָבוֹא בִּשְׁאָר יָמִים, דְּהַיְנוּ לְאַחַר יְצִיאָה מִבֵּית הַכְּנֶסֶת שֶׁרְגִילִין לָבוֹא מְנַחֲמִין, כֵּן נִרְאֶה לִי, וּדְלֹא כְּמוֹ שֶׁרְגִילִין לְהַמְתִּין שָׁעָה עַל הַיּוֹם, דְּאֵין הַדָּבָר תָּלוּי רַק בַּעֲמִידַת הַמְּנַחֲמִין.\u0006 \u0005(וְכֵן מַשְׁמָע בַּאֲשֵׁרִי)\u0006.\nשָׁמַע שְׁמוּעָה רְחוֹקָה בַּלַיְלָה, כֵּיוָן דְּסָגֵי בְּשָׁעָה אַחַת, סַלְקָא, אֲפִלוּ בַּלַיְלָה.\nמִי שֶׁמֵּת אָבִיו אוֹ אִמּוֹ בְּרֹאשׁ חֹדֶשׁ נִיסָן, \u0010y1\u0011 \u0010c1\u0011 לֹא אַמְרִינָן בכ\"ט בַּאֲדָר שֶׁאַחֲרָיו מִקְצָת הַיּוֹם כְּכֻלוֹ, אֶלָא צָרִיךְ לִנְהֹג דְּבָרִים הָאֲסוּרִים בי\"ב חֹדֶשׁ עַד שֶׁיִּכָּנֵס רֹאשׁ חֹדֶשׁ נִיסָן. \u0005הַגָּה: \u0010y2\u0011 וְנָהֲגוּ \u0010c2\u0011 לְהוֹסִיף עוֹד הַיּוֹם שֶׁמֵּת בּוֹ הָאָב אוֹ הָאֵם לִנְהֹג בּוֹ דִּין י\"ב חֹדֶשׁ, וְנָכוֹן הוּא.\u0006",["\u0003כיון שהנץ כו'. \u0004דביום ל' שאין מנחמים מותר מיד כשהנץ החמה:","\u0003לא אמרינן כו'. \u0004כיון דתליא בחדשים:","\u0003ונהגו להוסיף. \u0004ואפי' חל אותו היום בשבת נוהג בו דין י\"ב חדש כן הוא בתרומת הדשן סי' רצ\"ב מיהו כשהשנה מעוברת דמותר ליכנס לבית המשתה לאחר י\"ב חדש כדלעיל סי' שצ\"א ס\"ק ב' אין נוהג דין י\"ב חודש ביום שמת בו אב או אם אע\"פ שאומר קדיש וברכו ומתענה בו ביום דמאחר דכבר הפסיק מאבלותו שוב אינו חוזר לאבלותו כ\"כ הב\"ח. ונראה דהיינו דוקא בשאר מיני אבילות אבל לאכול בסעודה של שמחה ומשתה אסור בכל שנה ביום שמת בו אב ואם וכדכ' הרב לקמן ס\"ס ת\"ב כ\"ש הכא:"],["\u0003כיון שעמדו כו'. \u0004עיין מה שכתבתי בטעם דין זה בסי' ת\"ב ויש בו נפקא מינה לדינא:","\u0003לא אמרינן בכ\"ט באדר כו'. \u0004הטעם בת\"ה שם סי' רצ\"ב דכל שתלוי במנין ימים אמרינן מקצת יום האחרון ככולו משא\"כ באבילות דתלוי בי\"ב חודש בכל דוכתי וא\"כ אם תאמר מקצת ככולו לא יצטרך להתאבל רק קצת מחודש האחרון וזה ודאי אינו:","\u0003להוסיף עוד יום שמת כו'. \u0004בת\"ה סי' רצ\"ב כתב הטעם משום דאמרינן קדיש וברכו ומתענין בו דיום מיתה הוא כו' ולכך נוהגין ענין אבילות באותו יום עכ\"ל. ולפי זה אפילו עד עולם כל יארציי\"ט שלו הוה הדין כן. ומו\"ח ז\"ל כ' דאם השנה מעוברת מותר ליכנס לבית המשתה לאחר י\"ב חודש כדלעיל סי' שצ\"א ואז אין נוהג דין י\"ב חודש ביום שמת בו אביו ואף על פי שמתענה בו כיון דכבר נכנס למשתה והפסיק אבילותו שוב אינו חוזר לאבילותו כו' עכ\"ל. ותמוהים דבריו דהא עד עולם צריך לנהוג כן ביום יארציי\"ט שלו וכ\"כ רמ\"א סי' ת\"ב סעיף י\"ב שלעולם אין לאכול בסעודה בלילה של יום היארציי\"ט וכתוב בלבוש אולי במקומו של רמ\"א נהגו כן כי ברוב המקומות שעברתי לא ראיתי נוהגים כן:"],"\u0010c0\u0011 \u0010g0\u0011 \u0010r0\u0011 כֵּיוָן שֶׁעָמְדוּ מְנַחֲמִים מֵאֵצֶל הָאָבֵל בְּיוֹם שְׁבִיעִי, מֻתָּר בְּכָל דְּבָרִים שֶׁאָסוּר בָּהֶם תּוֹךְ שִׁבְעָה, דְּמִקְצָת הַיּוֹם \u0010r1\u0011 כְּכֻלוֹ, לֹא שְׁנָא מִקִצָת יוֹם שְׁבִיעִי לֹא שְׁנָא מִקְצָת יוֹם שְׁלֹשִׁים, \u0010y0\u0011 \u0010r2\u0011 כֵּיוָן שֶׁהֵנֵץ \u0010t0\u0011 הַחַמָּה בְּיוֹם שְׁלֹשִׁים, בָּטְלוּ מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים \u0005(רֹא\"שׁ וְרַבֵּנוּ יְרוּחָם)\u0006. \u0005הַגָּה: וּבִמְדִינוֹת אֵלּוּ שֶׁאֵין הַמְּנַחֲמִין רְגִילִין לָבוֹא בְּיוֹם ז', צָרִיךְ לְהַמְתִּין עַד שָׁעָה שֶׁרְגִילִין הַמְּנַחֲמִים לָבוֹא בִּשְׁאָר יָמִים, דְּהַיְנוּ לְאַחַר יְצִיאָה מִבֵּית הַכְּנֶסֶת שֶׁרְגִילִין לָבוֹא מְנַחֲמִין, כֵּן נִרְאֶה לִי, וּדְלֹא כְּמוֹ שֶׁרְגִילִין לְהַמְתִּין שָׁעָה עַל הַיּוֹם, דְּאֵין הַדָּבָר תָּלוּי רַק בַּעֲמִידַת הַמְּנַחֲמִין.\u0006 \u0005(וְכֵן מַשְׁמָע \u0010g1\u0011 בַּאֲשֵׁרִי)\u0006.\nשָׁמַע \u0010r3\u0011 שְׁמוּעָה רְחוֹקָה בַּלַיְלָה, כֵּיוָן דְּסָגֵי בְּשָׁעָה אַחַת, סַלְקָא, אֲפִלוּ בַּלַיְלָה. \u0010g2\u0011\nמִי שֶׁמֵּת אָבִיו אוֹ אִמּוֹ בְּרֹאשׁ חֹדֶשׁ נִיסָן, \u0010y1\u0011 \u0010c1\u0011 לֹא אַמְרִינָן בכ\"ט בַּאֲדָר שֶׁאַחֲרָיו מִקְצָת הַיּוֹם כְּכֻלוֹ, אֶלָא צָרִיךְ לִנְהֹג דְּבָרִים הָאֲסוּרִים בי\"ב חֹדֶשׁ \u0010g3\u0011 עַד \u0010t1\u0011 שֶׁיִּכָּנֵס רֹאשׁ חֹדֶשׁ נִיסָן. \u0005הַגָּה: \u0010y2\u0011 וְנָהֲגוּ \u0010c2\u0011 \u0010t2\u0011 לְהוֹסִיף עוֹד הַיּוֹם שֶׁמֵּת בּוֹ הָאָב אוֹ הָאֵם לִנְהֹג בּוֹ דִּין י\"ב חֹדֶשׁ, וְנָכוֹן הוּא.\u0006",{"g":["\u0003מימרא (דר' חייא בר גמדא) [דרב עמרם] וכו'\u0004 מ\"ק (כ\"ב ע\"א) [י\"ט ע\"ב] וכאבא שאול שם (י\"ט ע\"ב):","\u0003טור בשם הר\"מ מרוטנבורג:\u0004 ","\u0003תה\"ד סי' רצ\"ב:\u0004 ","ומפרש שם הטעם דלגבי אבילות די\"ב חדש לא הזכירו בשום מקום אלא י\"ב חדש ולא שנ\"ד ימים:"],"t":["\u0003החמה. \u0004 דביום ל' שאין מנחמים מותר מיד בהנץ החמה. ש\"ך:","\u0003שיכנס. \u0004 הטעם בת\"ה שם דכל שתלוי במנין הימים אמרי' מקצת יום האחרון ככולו משא\"כ באבלות התלוי בי\"ב חדש בכל דוכתי אם תאמר מקצתו ככולו לא יצטרך להתאבל רק קצת חדש האחרון וזה אינו. עכ\"ל הט\"ז:","\u0003להוסיף. \u0004 ואפילו חל אותו היום בשבת נוהג בו דין י\"ב חדש כן הוא בת\"ה סי' רצ\"ב. מיהו כשהשנה מעוברת דמותר ליכנס לבית המשתה לאחר י\"ב חדש כמ\"ש בסי' שצ\"א ס\"ב אין נוהג דין י\"ב חדש ביום שמת בו אב או אם אע\"פ שאומר קדיש וברכו ומתענה בו ביום דמאחר שכבר הפסיק מאבלותו שוב אינו חוזר לאבלותו כ\"כ הב\"ח. ונראה דהיינו דוקא בשאר מיני אבילות אבל לאכול בסעודת שמחה ומשתה אסור בכל שנה ביום שמת בו אב או אם וכמ\"ש הרב לקמן ס\"ס ת\"ב כ\"ש הכא עכ\"ל הש\"ך \u0005(ועי' מ\"ש לעיל סי' שצ\"א. ומיהו אפילו לדעת המקילין בזה כמ\"ש הלבוש וכמ\"ש לעיל מ\"מ בשנה ראשונה אפילו בשנת העיבור לא יאכל בסעודה של שמחה. ומכל מקום נוהגין שאם חל יארציי\"ט שלו בשבת או ביום טוב שלובשים טלית של חול כדי לשנות קצת. וכן נוהגין כל השנים אפילו לאחר שנה ראשונה ובענין תענית יארציי\"ט אם ישלים עיין סי' ת\"ב)\u0006:"],"r":["\u0003כיון כו'. \u0004י\"ט ב' כמאן אזלא כו':\n\u0003(ליקוט) כיון כו'. \u0004עתוס' כ\"א ב' ד\"ה אפילו כו' (ע\"כ):\n\u0003(ליקוט) כיון כו' כיון כו'. \u0004תוס' והרא\"ש אבל הרמב\"ן חלק עליהם וכתב דאפילו מקצת הלילה עולה ומ\"ש \u0005(י\"ט ב') \u0006כיון שעמדו המנחמין לפי שאם רצה לישב כל היום הרשות בידו ודרך היה לבא מנחמין ולכך אסור לפי שעדיין ינחמו אותו ומ\"ש ראיה ממ\"ש כ\"ז א' ולמוצאי שבת אע\"פ כו' משם ראיה להיפך דאי ס\"ד דכל הלילה בעי צריכא למימר \u0005(וע\"ש בריטב\"א) \u0006אלא דמשום דמקצת הלילה עולה ס\"ד דסגי בדבר אחד בחליצת מנעל קמ\"ל דבעי כל דיני שבעה אף בכפיית המטה אף לשעה אחת ומה שהביאו ראיה משומרת יום \u0005(דספ\"ב דמגילה) \u0006ג\"כ אינה ראיה דשם גמרינן מזבה דטבילתן ביום ואדרבה משם ראיה להיפך וערש\"י בפסחים פ\"א א' ד\"ה א\"נ ברואה כו' ואע\"ג דלרבנן דוקא ביממא היינו משום דס\"ל דלא אמרינן מקצת היום ככולו וסותרת אפילו ראתה בסוף היום והוא מימי הזבה עדיין משא\"כ לר\"י אבל תוס' שם ד\"ה א\"נ פי' כשיטתן ע\"ש וכתב הרמב\"ן שכן הורה ר\"ת בשעת הדחק וע\"ש \u0005(בתה\"א) \u0006(ע\"כ):","\u0003ל\"ש כו'. \u0004שם ונהרדעי כו':","\u0003(ליקוט) כיון שתנץ כו'. \u0004כמ\"ש בספ\"ב דמגילה ועברא\"ש סי' ע\"ז:","\u0003שמועה כו'. \u0004ברא\"ש שם וכן נראה מדקאמר במגילה שם כיון דבעיא ספירה דוקא כה\"ג וכן מדלא תני בסוף יומא \u0005(וש\"מ) \u0006רק הזב כו' \u0005(משמע דשאר טמאים טובלין בין ביום בין בלילה ועברמב\"ם פ\"א דמקואות וראב\"ד שם):\u0006"]}],["אָבֵל שֶׁלֹּא נָהַג אֲבֵלוּתוֹ תּוֹךְ שִׁבְעָה, בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד, מַשְׁלִים אוֹתוֹ כָּל שְׁלֹשִׁים, \u0010c0\u0011 חוּץ מֵהַקְרִיעָה, שֶׁאִם לֹא קָרַע בִּשְׁעַת \u0010y0\u0011 חִמּוּם, אֵינוֹ קוֹרֵעַ, אֶלָא תּוֹךְ שִׁבְעָה, חוּץ מֵאָבִיו וְאִמּוֹ שֶׁקוֹרֵעַ \u0010y1\u0011 אֲפִלוּ לְאַחַר שִׁבְעָה.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בְּשֶׁלֹּא נָהַג אֲבֵלוּת כְּלָל כָּל שִׁבְעָה; אֲבָל אִם זִלְזֵל בְּמִקְצָת הַיָּמִים, וְלֹא נָהַג בָּהֶם אֲבֵלוּת, כְּגוֹן מִי שֶׁאָמְרוּ לוֹ שֶׁמֵּת לוֹ מֵת בַּיּוֹם הָא', וְהָיָה בְּעִיר אַחֶרֶת וְלֹא נָהַג אֲבֵלוּת, וּבַיּוֹם הַשֵּׁנִי בָּא לְעִירוֹ וְנָהַג אֲבֵלוּת, אֵין צָרִיךְ לְהַשְׁלִים, וּמוֹנֶה שִׁבְעָה מִיּוֹם הָרִאשׁוֹן. \u0010c1\u0011\nקָטָן שֶׁמֵּת אָבִיו וְאִמּוֹ, \u0010y2\u0011 אֲפִלוּ הִגְדִּיל תּוֹךְ שִׁבְעָה, בָּטֵל מִמֶּנּוּ כָּל דִּין אֲבֵלוּת וְאֵינוֹ חַיָּב בּוֹ.",["\u0003אינו קורע כו'. \u0004כתב הב\"ח דהיכא שהיה אנוס כגון שהיה חולה ומסוכן שאי אפשר לקרוע או כגון שאין דעתו צלולה ומיושבת עליו וחזר לבוריו ולדעתו אחר שבעה שחשוב עכשיו כשעת חימום דל\"ד לשוגג או מזיד דעבר שעת חימום כיון שהיה בריא בשעה ששמע שמת לו מת וחייב באותה שעה אבל זה לא נתחמם אלא בשעה שחזר לבוריו ודעתו צלולה ומיושבת ובאות' שעה חל עליו חובת קריעה ע\"כ:","\u0003אפילו לאחר שבעה. \u0004כדלעיל סי' ש\"מ ס\"ח:","\u0003ואפילו הגדיל. \u0004והב\"ח פסק כדעת מהר\"ם דבהגדיל תוך ל' מונה ז' ול' משעה שהגדיל אבל אם הגדיל אחר ל' בטל ממנו גזירת ז' ול' ע\"ש מיהו מה שהקשה מלעיל סי' שמ\"א ס\"ב דמבדיל אחר שיקבר המת בקל יש לחלק ביניהם עיין שם:"],["\u0003חוץ מהקריעה כו'. \u0004לע\"ד נראה אם היה חולה ודעתו אינה מיושבת מחמת חולי לא אזלינן בזה בתר שעת חימום דהא אין יודע להתחמם אלא כשתבוא לו דעה צלולה כשאר כל אדם אז הוה חימום שלו אבל לא אכפת לן במה שהוא אינו יכול לקרוע מחמת שהוא מסוכן בחליו דסוף סוף ידע בחימום בעת ההיא ועל כן פטור אח\"כ מלקרוע כנ\"ל:","\u0003קטן שמת כו' ואפי' הגדיל כו'. \u0004דין זה הוא במחלוקת בין מהר\"ם להרא\"ש תלמידו בסוף מועד קטן דמהר\"ם סבירא ליה חייב להתאבל אחר שיגדיל שבעה ושלשים מיום שנעשה גדול והוה כשמע שמועה קרובה ברגל שמתאבל אחר הרגל ז' ול' ואע\"ג דהתם ימי הרגל עולין למנין שלשים היינו לפי שנהג בהם איסור גיהוץ ותספורת אבל כאן בקטנותו לא נהג כלום ואע\"פ שיש לחלק קצת בין שמע ברגל לנדון זה דהתם גברא בר חיובא הוא אלא דיומא הוא דקגרים אבל הכא גברא לאו בר חיובא הוא כלל וא\"כ נימא כיון דבשעת מיתה לא היה ראוי להתאבל יפטור עולמית הא ליתא דאין דיחוי אצל מצות כדאיתא פרק כיסוי הדם כו' והרא\"ש חולק ואומר תופס אני אותה סברא שיש לחלק בין היכא דגברא בר חיובא הוא ויומא גרים לקטן דבשעה שהיה לו להתאבל פטור מחמת קטנות פקע מיניה חיוב אבילות לעולם ודמי להא דאמר בפרק מי שהיה טמא קטן שהגדיל בין ב' פסחים דסבר רבי נתן שני תשלומין לראשון וכל שאינו זקוק לראשון אינו זקוק לשני וכן נמי הא דיושבים על שמועה קרובה ז' ול' אינה מצוה בפני עצמה אלא תשלום לאבלות שהיה לו לעשות מיד אחר הקבורה כשידע וכשלא ידע תקנו שיש לו תשלומין כל שלשים יום והיכא דידע ולא נתחייב לא שייך ביה תשלומין מידי דהוה אחיגר ביום ראשון ונתפשט ביום שני של חג דלא שייך ביה תשלומין כו' ע\"כ. וכ' רבינו ירוחם שיש לפסוק כמהר\"ם שהוא רבו של הרא\"ש והב\"י הכריע כהרא\"ש דהלכה כדברי המיקל באבל וכן פסק כאן בשו\"ע דפטור ובימי חרפי בא מעשה זה לידי בקטן שהגדיל תוך ז' ועיינתי בו והוקשה לי בדברי הרא\"ש שכתב דאבלות הוה בו משום תשלומין דבזה אין שייך תשלומין אלא כל יום מן הז' הוא מצוה בפ\"ע דהא פסקינן כאן סעיף ב' אם זלזל במקצת ז' הימים דא\"צ להשלים ולמה כתבו הטור והשו\"ע אפי' הגדיל בתוך שבעה. והרציתי הדברים הללו לפני מו\"ח ז\"ל והשיב לי שבלא\"ה סותרים דברי השלחן ערוך זה את זה דבפרק מי שמתו יש ג\"כ פלוגתא בין הרא\"ש ורבינו יהודה ובין מהר\"ם לענין הבדלה דרבינו יהודה היה אונן במ\"ש ולא הבדיל ולמחר ביום א' אחר הקבורה לא רצה ג\"כ להבדיל מאחר שהיה פטור בשעת חיוב הבדלה ודומה לחיגר שנתפשט ביום שני שזכרתי לעיל והואיל ונדחה ידחה ומהר\"ם חולק שם וס\"ל ביום המחרת חייב להבדיל דהא קי\"ל מי שלא הבדיל במ\"ש מבדיל והולך כל השבת כולה והרא\"ש כ' שם שהוא הסכים לרבינו יהודה דהא דאמרינן מי שלא הבדיל במ\"ש כו' היינו כשלא היה לו יין במ\"ש או אונס אחר שלא היה יכול להבדיל אבל אונן דבשעה שחל עליו חיוב הבדלה היה פטור לגמרי תו לא מתחייב ודמיא לחיגר דלעיל ע\"כ והנה לעיל סי' שמ\"א פסק השו\"ע שחייב להבדיל והיינו כמהר\"ם וכאן פסק דפטור כשהגדיל והיינו כהרא\"ש דטעם אחד לשתי הפלוגתות ואין ישוב לזה וע\"כ פסק הוא בכל מקום כמהר\"ם שהוא רבו של הרא\"ש וגם כאן חייב בז' ושלשים דלא כפסק הש\"ע וכן קבע הוא בחיבורו על היורה דעה כאן ואני בעניי תמהתי ונפלאתי על פסק זה שנחלקו בו אבות העולם מהר\"ם והרא\"ש ומתירא אני להכניס ראשי החלש בין הרים גדולים מאורי ישראל ומ\"מ עצור במלין לא אוכל כי תלמוד ערוך הוא פסק זה לפע\"ד שלא כדברי מהר\"ם ולא כדברי הרא\"ש במחילה מכבודם וע\"פ זה יתבאר שפסקי הש\"ע הם דברי אלהים חיים:\n\u0003אמרינן \u0004בפרק נגמר הדין (סנהדרין דף מ\"ז) בהא דאמרינן לא היו קוברין אותן הרוגי בית דין בקברות אבותם ואי ס\"ד כיון דאיקטל הוי ליה כפרה ליקברו ומשני מיתה וקבורה בעינן מתיב רב אדא לא היו מתאבלין על הרוגי ב\"ד אלא אוננין ואי ס\"ד כיון דאיקבר הוה ליה כפרה ליתאבלו ומשני בעינן נמי עיכול בשר. רב אשי אמר לעולם לא בעינן עיכול בשר אלא צערא דחיבוט הקבר פורתא וטעמא דלא היו מתאבלין משום דאבילות מסתימת הגולל חיילא כפרה מאימת הויא מכי חזי צערא דקברא פורתא הלכך הואיל ואידחו ידחו פירש\"י הואיל ונדחו שלא נראו להתאבל בשעת התחלת האבלות ידחו אף לאחר מכאן ואע\"ג דגבי קובר את מתו ברגל תנן מונה ז' ימים אחר הרגל ולא אמרינן הואיל ונדחו ידחו התם לא אידחו לגמרי שהרי אמרי' כל שהוא משום עיסקי רבים אין הרגל מפסיקן ורבים באים לנחמו עכ\"ל:\n\u0003והנה \u0004אתה רואה ק\"ו כאן דמה כאן בפרק נגמר הדין דאחר סתימת הגולל לא היה שום אבילות בעולם כיון דהמת לא חזי לכך דלא הוי ליה כפרה עדיין והיה מן הראוי לומר דאחר שיהיה קצת בקבר ויכופר אז יתחיל אבילות שלו כדרך שמתחיל בשאר מתים אחר סתימת הגולל אפ\"ה לא אמרינן כן אלא אמרינן הואיל ואידחי בשעה שמתחיל לשאר העולם לא יתאבלו עליו כלל אח\"כ ק\"ו כאן שהיה אבילות בעולם והמתאבל לא חל עליו החיוב פשיטא הואיל ואידחי בשעת החיוב ידחה לעולם ופשוט דהלכה כרב אשי דבתרא הוא ותו אני אומר דגם תירוץ הראשון בגמ' אינו חולק על האי סברא דאידחי אידחי דאל\"כ לדידיה נמי קשה יתאבלו על הרוגי ב\"ד דלאחר העיכול דאז יש להם בודאי כפרה אלא פשיטא דבזה אמרינן אידחי אידחי אלא דפליגי על רב אשי במה שאמר שיש להם כפרה בזמן קצר מכי חזו פורתא צערא דקברא בזה פליגי וס\"ל דאין הכפרה ממהרת כ\"כ אבל אי היתה ממהרת ודאי גם הם סבירא להו אידחי אידחי וכן מבואר שם בסוגיא לעיל מיניה דכ\"ע אית להו כיון שאידחו אידחו לפי המסקנא גם הב\"י בסי' שמ\"ה כ' ואסיקנא לענין הרוגי ב\"ד בפרק נגמר הדין דהוי ליה כפרה בקטלא וקבורה אלא היינו טעמא דאין מתאבלין עליהם דאבילות מתחיל מסתימת הגולל כו' והיינו כתירוץ רב אשי אלא דבנוסח דברי בית יוסף יש ט\"ס שכתב הרוגי מלכות וצ\"ל הרוגי ב\"ד א\"כ מבואר דלא כמהר\"ם שחייב לקטן והגדיל וגם דלא כהרא\"ש דאילו להרא\"ש הפטור משום דהוה תשלומין וכל שפטור בשעת החיוב אין עליו תשלומין משמע דאילו במקום שאין תשלומין הוה חיוב ומודה למהר\"ם והרי כאן בפרק נגמר הדין שאין שם תשלומין דהא לא היה ראוי לאבילות מתחלה ואפ\"ה אמרינן דפטור אח\"כ אלא דבר ברור הוא דהפטור לאו משום דלא שייך ביה תשלומין נגעו בו אלא משום שחכמים הטילו עליו אבילות מן שעה ראשונה שהמרירות עליו ביותר דהיינו משיסתום הגולל ומן אותה שעה הוא מתאבל והולך כפי דינו אבל כל שנפטר בשעת עיקר המרירות דהיינו אחר סתימת הגולל אין עליו שום חיוב אחר כך ומשום הכי הרוגי ב\"ד וכן קטן והגדיל פטורים לגמרי כיון שהיו פטורים בשעת עיקר המרירות ויפה מכוון לזה פי' רש\"י שהעתקתי שלא דמי לקובר מת ברגל שחייב בז' ול' אחר הרגל ששם בשעת עיקר המרירות לא נפטר שהרי יש עליו קצת אבילות גם ברגל ואין כאן דמיון להבדלה שחייב לעשות ביום המחרת אע\"פ שבליל מ\"ש היה פטור כמ\"ש השלחן ערוך בסי' שמ\"א דשם הוא עיקר זמן ההבדלה מתחלה כך שימשוך זמנה כל השבת או עד ליל ד' ולא אמרינן דאם לא הבדיל במ\"ש הוה ההבדלה שאח\"כ תשלומין על מ\"ש אלא עדיין זמנה ממש וזה דומה לתפלת ערבית וק\"ש שאחז\"ל במסכת ברכות שזמנה קודם אכילה וכל העובר חייב מיתה ואעפ\"כ זמנה כל הלילה כמ\"ש בפי' שזמנה כל הלילה והכי נמי ממש כן הוא בהבדלה וזהו נכלל במה שאמרו מי שלא הבדיל במ\"ש מבדיל והולך כל השבת כולה. וכן לא קשה ממה שמצינו בסוכה פרק הישן (סוכה דף כ\"ז) בקטן שנתגדל בימי הסוכות דחייב לעשות סוכה התם נמי זמנה כן הוא כל ז' הימים ואין בזה משום תשלומין על מה שלא ישב בסוכה בשעת קטנותו כדאמרינן במתני' שם שאין תשלומין למי שלא אכל בסוכה משא\"כ באבילות שהעיקר תלוי בהתחלת האבילות בשעת עיקר המרירות וכל שלא התחיל לא יגמור ע\"כ נראה להלכה ולמעשה כפסק הרא\"ש לענין אבילות דפטור כאן ולא מטעמיה אלא מטעם שאמרנו. ולענין הבדלה כדעת מהר\"ם וכפסק הש\"ע בב' המקומות והם צודקים וברורים ומקום הניחו לנו רבותינו אבות העולם לזכות בו בסייעתא דשמיא:"],"\u0010g0\u0011 אָבֵל שֶׁלֹּא נָהַג אֲבֵלוּתוֹ תּוֹךְ שִׁבְעָה, בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד, מַשְׁלִים אוֹתוֹ כָּל שְׁלֹשִׁים, \u0010c0\u0011 \u0010r0\u0011 חוּץ מֵהַקְרִיעָה, שֶׁאִם לֹא קָרַע בִּשְׁעַת \u0010y0\u0011 חִמּוּם, אֵינוֹ \u0010t0\u0011 קוֹרֵעַ, אֶלָא תּוֹךְ שִׁבְעָה, חוּץ מֵאָבִיו וְאִמּוֹ שֶׁקוֹרֵעַ \u0010y1\u0011 אֲפִלוּ לְאַחַר שִׁבְעָה. \u0010g1\u0011\nבַּמֶּה דְּבָרִים אֲמוּרִים, בְּשֶׁלֹּא נָהַג אֲבֵלוּת כְּלָל כָּל שִׁבְעָה; אֲבָל אִם זִלְזֵל בְּמִקְצָת הַיָּמִים, וְלֹא נָהַג בָּהֶם אֲבֵלוּת, כְּגוֹן מִי שֶׁאָמְרוּ לוֹ שֶׁמֵּת לוֹ מֵת בַּיּוֹם הָא', וְהָיָה בְּעִיר אַחֶרֶת וְלֹא נָהַג אֲבֵלוּת, וּבַיּוֹם הַשֵּׁנִי בָּא לְעִירוֹ וְנָהַג אֲבֵלוּת, אֵין צָרִיךְ לְהַשְׁלִים, וּמוֹנֶה שִׁבְעָה מִיּוֹם הָרִאשׁוֹן. \u0010c1\u0011 \u0010g2\u0011 \u0010r1\u0011\nקָטָן שֶׁמֵּת אָבִיו וְאִמּוֹ, \u0010y2\u0011 \u0010t1\u0011 \u0010r2\u0011 אֲפִלוּ הִגְדִּיל תּוֹךְ שִׁבְעָה, בָּטֵל מִמֶּנּוּ כָּל דִּין אֲבֵלוּת וְאֵינוֹ חַיָּב בּוֹ.",{"g":["טור בשם הראב\"ד וכן כתב הרמב\"ן בסת\"ה והרא\"ש בפ\"ג דמ\"ק בשמו ולמד כן מדקתני בברייתא במ\"ק דף כ' ע\"א קיים כפיית המטה וכו' ולא קתני הקובר מתו:","\u0003שם בשם אביו הרא\"ש בתשובות כלל כ\"ז:\u0004 ","ג\"ז שם בשם אביו הרא\"ש בפסקיו בסוף מ\"ק ומטעם שכתב שם שיש לחלק בין היכא דגברא בר חיובא הוא ויומא לא גרים לקטן שבעת שהיה לו להתאבל נפטר מחמת קטנות פקע מיניה חיוב אבילות לעולם וכו' ועוד כתב לחלק בין היכא דיש בידו לבטל הדיחוי שלו מה שאין כן קטן דאין בידו לבטל הדיחוי שלו וכו' ע\"כ ומטעמים אלו לענ\"ד אין סתירה למה שפסק ב\"י לעיל סי' שמ\"א דמבדיל אחר שיקבר המת וק\"ל:\n(°) ודין הקריעה לקטן עיין בסימן ש\"מ סעיף כ\"ז:"],"t":["\u0003קורע. \u0004 כ' הב\"ח דהיכא שהיה אנוס שהיה חולה ומסוכן שא\"א לקרוע או שאין דעתו צלולה ומיושבת עליו וחזר לבוריו ולדעתו אחר ז' שחשוב עכשיו כשעת חימום דל\"ד לשוגג או מזיד דעבר שעת חימום כיון שהיה בריא בשעה ששמע שמת לו מת וחייב באותה שעה אבל זה לא נתחמם אלא בשעה שחזר לבוריו ודעתו צלולה ומיושבת ובאותה שעה חל עליו חובת קריעה עכ\"ל \u0005(וט\"ז פסק דפטור מלקרוע אח\"כ ע\"ש ודבריו נראין תמוהין חדא שאין מזכיר דברי חמיו כדרכו ועוד תחלת דבריו משכימים עם הב\"ח ואח\"כ מסיים וע\"כ פטור אח\"כ מלקרוע. ע\"כ נ\"ל שטעות נפל בדבריו או איזה חסרון יש כאן וע\"ש)\u0006:","\u0003הגדיל. \u0004 והב\"ח פסק כדעת מהר\"ם דבהגדיל תוך שבעה מונה ז' ול' משעה שהגדיל אבל אם הגדיל אחר ל' בטל ממנו גזרת ז' ול' ע\"ש והט\"ז מאריך בדין זה וסוף דבריו סיים לענין הלכה למעשה נראה כפסק הש\"ע דקטן פטור מהאבלות כי דבריו הם צודקים וברורים. ומקום הניחו לנו רבותינו אבות העולם לזכות בו בס\"ד:"],"r":["\u0003חוץ כו'. \u0004כנ\"ל סי' ש\"מ סי\"ח:","\u0003קטן כו'. \u0004דאין חייב כמ\"ש י\"ד ב' נמצא אבילות כו':","\u0003ואפילו הגדיל כו'. \u0004כמ\"ש ברפ\"ט דפסחים וכן קטן שהגדיל כו' ובסנהדרין מ\"ז ב' הלכך הואיל כו' ועט\"ז:"]}],["\u0010y0\u0011 מִתְאַבְּלִין עַל פִּי עֵד אֶחָד, וְעֵד מִפִּי עֵד \u0010c0\u0011 וְעוֹבֵד כּוֹכָבִים מֵסִיחַ לְפִי תֻּמּוֹ.\nשְׁנַיִם אוֹמְרִים: מֵת, וּשְׁנַיִם אוֹמְרִים: לֹא מֵת, \u0010y1\u0011 \u0010c1\u0011 אֵינוֹ מִתְאַבֵּל.",["\u0003מתאבלים כו'. \u0004כתב הרמב\"ן זה הכלל כל עדות שמשיאים האשה על פיה הקרובים מתאבלים וכ\"פ הב\"ח ועיין בא\"ע סי' י\"ז נתבאר עדות שמשיאין האשה על פיה וכ' עוד הב\"ח היכא שכתבו לאחד שמת קרובו ואיכא ספק אם הוא תוך ל' חייב להתאבל דכל כמה דמצינן ליה לאוקמיה אחזקתיה מוקמינן ואמרינן השתא מקרוב מת וכן הוא בתשובת ן' לב מיהו היכא שהוא כתב יד של חכם אמרי' מסתמא לאחר ל' הוא דאם איתא דאפשר היה שיגיע הכתב לידו תוך ל' לא היה כותב בסתם אלא היה מבאר כ\"כ הב\"ח וכן כ' בתשו' ר\"מ מינץ סי' צ\"ה דצריך להתאבל מטעם דמוקמינן אחזקתיה וכ' דאם אירע שהורו דאין להתאבל מספק ואח\"כ נודע לו למפרע שמת תוך ל' צ\"ע אם יחזור ויתאבל או לא ע\"ש ולפעד\"נ דצריך להתאבל בכה\"ג וע\"ל ר\"ס שצ\"ו ודו\"ק:","\u0003אינו מתאבל. \u0004דמוקמינן ליה אחזקתיה דחי וע\"ל סי' של\"ט ס\"ב דבאמרו לו ראינו קרובך גוסס היום ג' ימים צריך להתאבל עליו:"],["\u0003ועובד כוכבים מסיח לפי תומו. \u0004כ' רש\"ל וז\"ל עובדת כוכבים שספרה לפי תומה לראובן שמתה אחותו פסק ראבי\"ה שמתאבל על פיה דנאמנת להחמיר וא\"מ פסק דהילכתא כדברי המיקל באבל ועובד כוכבים אינו נאמן להחמיר במילי דאבילות וה\"ר ישעיה אומר דאין עובד כוכבים נאמן במסיח לפי תומו אלא לעדות אשה או על פירות של עצמו מעיד דשל ערלה הן אבל בכל עדיות דעלמא אין עובד כוכבים נאמן במסיח לפי תומו בין להקל בין להחמיר. ע\"כ תשובת אור זרוע עכ\"ל:","\u0003אינו מתאבל. \u0004הטעם דכיון דספיקא היא אזלינן בה להקל כ' מהר\"ם מינץ סי' צ\"ה מי ששמע שמת לו מת ואינו יודע אם תוך ל' או לאחר ל' יום אם חייב להתאבל והאריך בזה וזה כלל דבריו דיש סברא לומר כיון דהקילו בענין אבילות כיון דספיקא דרבנן הוא והביא בשם הלכות שמחות דמהר\"ם דאין להחמיר באבילות בספק דחומרא דאתי לידי קולא היא שנוהג אבילות בשבת בדברים של צינעא ומבטל תלמוד תורה כל שבעה ימים אך מטעם חזקה נ\"ל להחמיר דתנן בפ' כל הגט המביא גט והניחו זקן או חולה נותנו לה בחזקת שהוא קיים כו' והביא הרבה דינים שהולכי' בתר חזקה ע\"כ י\"ל העמד המת על חזקתו והשתא הוא דמת ולא החליט הפסק ומסיק לבסוף דאין לו ראיה ברורה לא לחיוב ולא לפטור) ובתשו' מהר\"י ן' לב פסק לחיוב מכח ההיא דפ' כל הגט שזכרתי וכן פסק מו\"ח ז\"ל כאן ולפענ\"ד לא נראה כן מכח ראיות ברורות כאשר אבאר בסייעתא דשמיא:\n\u0003ראשונה \u0004דאמרינן במשנה בפסחים פרק האשה (ד' צ\"א) האונן והמפקח את הגל (מעל האדם ואין יודע אם ימצאנו חי או מת כו') שוחטין עליו את הפסח (מפני שעודנו בחזקת טהרה כו' לפיכך אם אירע בהם פסול פטורים מלעשות פסח שני כיון שבשעת זריקה ראוין הם) חוץ מן המפקח בגל ונמצא המת תחתיו שחייב לעשות פסח שני שהוא טמא מתחילתו פי' קודם שחיטה שהרי האהיל על הטומאה משעה שהתחיל לפקח וכתבו התוס' תימא לר\"י מפקח הגל נמי נימא חי היה כשהתחיל לפקח. וי\"ל כיון שנמצא מת אית לן למימר שמתחילתו היה מת שכל הטומאות כשעת מציאתן עכ\"ל הרי לפניך דלא אמרינן אוקים אותו בחזקת חי והשתא הוא דמת וא\"ל דלא ילפינן איסור מטומאה וכן שום חיוב או פטור דהא במתניתין ההיא ילפינן שחייב לעשות פסח שני ולא חשבינן ליה לספק דילמא מייתי חולין בעזרה אלא דבר ודאי חשבינן ליה דמת מעיקרא ויליף מטומאה הכי נמי נליף שפטור מאבילות דנימא כיון דהשתא מת מעיקרא מת חשבינן ליה וא\"ל דשאני במפקח הגל דתכף שנפל עליו הגל הזה סבר דודאי מת זה אינו דהא כתבו התוספות שכל הטומאות כשעת מציאתן משמע בכל גווני אמרינן כן ותו דודאי אינו הכרח שמת תיכף דשפיר מצינו לומר שהיה עדיין חי דהא תנא סתמא אמר המפקח את הגל דהיינו אפי' תיכף שנפל עליו:\n\u0003שנית \u0004מפרק המדיר (כתובות דף ע\"ז) אמר רב יהודא אמר שמואל המחליף פרה בחמור ומשך בעל החמור את הפרה ולא הספיק בעל הפרה למשוך את החמור עד שמת החמור על בעל החמור להביא ראיה שהיה חמורו קיים בשעת משיכת הפרה וקשה למה יביא ראיה לזה אמאי לא נוקים אותו בחזקת שהיה חי תחלה והשתא הוא דמת וכן במסקנא שם דאמר רמי בר יחזקאל על בעל הפרה להביא ראיה שמת תחלה כיון שהספק נולד ברשותו פי' שבעל החמור עשה כבר משיכה בפרה אמאי הוצרך לומר בשביל שהספק נולד ברשותו תיפוק ליה דמוקמינן לה בחזקת חי כההיא דפרק כל הגט דלעיל מ\"ש חזקת אדם חי או בהמה חיה:\n\u0003שלישית \u0004ממה שכתב הטור והשו\"ע באבן עזר סימן י\"ז מצאו הרוג ומכירין אותו בטביעת עין ואין יודעין מתי נהרג י\"א שתולין שנהרג תוך ג' ימים ומעידין עליו ויש אוסרין ומבואר בבית יוסף בשם הרשב\"א דאזלינן לחומרא דשמא כבר נהרג וקשה אמאי לא נימא דהשתא הוא דנהרג דנוקמיניה בחזקת חי כמעיקרא עד השתא כההיא דפרק כל הגט. וע\"כ לתרץ הנהו תלתא קושיות אלימתות דע\"כ לא אמרינן פרק כל הגט דמוקמינן ליה בחזקת חי אלא כל שלא ידענו עדיין שמת משא\"כ בהנך תלת מילי דהשתא ודאי מת שפיר אמרינן דכבר היה מת וכמשמעות לשון התוספות בפסחים שזכרנו שכתבו כיון שמצאוהו מת אית לן לומר שמתחלתו היה מת. ואין להקשות מ\"ש משאר חזקות שאמרינן חזקה אפי' בכה\"ג כגון במקוה דפרכינן בריש נדה דנימא השתא הוא דחסר וכן בסימן פ\"א לעיל בגבינות שנעשו מחלב בהמה ונמצאת טרפה דאמרינן השתא הוא דנטרפה וכן בהרבה דוכתי נלע\"ד לומר דשאני במיתה דכל חי עומד למות והוא מועד לכך בלי ספק ע\"כ שפיר אמרינן דודאי כל זמן שאינו מבורר שמת אמרינן עדיין חי הוא אבל כשמבורר שמת אזלא החזקה לענין שנאמר דהשתא הוא שמת דאדרבה אמרינן שמעיקרא היה מת כיון שעמד לכך וסברא זאת שאמרנו שעומד לכך מצינו אותו בטור ח\"מ סי' ס\"ה וז\"ל וא\"ל העמד השטר אחזקתו שלא נפרע לפי שהשטר עומד ליפרע עכ\"ל ש\"מ שסברא זאת מגרע כח החזקה הכי נמי נימא כן לענין חזקה זאת דהשתא הוא דמת שאין לך לומר כן וכיון שזכינו לזה נימא גם כאן דאין חייב להתאבל מכח ספק מחמת החזקה דאין לך לומר השתא הוא דמת דוקא ועל דברים אלו סמכתי עצמי ופסקתי הלכה למעשה כן שאין חיוב אבילות על זה הספק בפרט אחר היסוד הגדול שהולכין באבל להקל טפי מבשאר מילי דרבנן ואין מן הראוי להחמיר דאתי לידי קולא לחלל שבת כמו שזכרנו בתשובה דלעיל: עוד כתב מהר\"ם מינץ בתשוב' דלעיל וז\"ל ויען שאין לי ראיה ברורה לא לכאן ולא לכאן הגם אם יש מורה דפסק דאין להתאבל בכה\"ג דספק אם תוך ל' הוא אבאר איך דינה אם לא יוודע לו בבירור עד לאחר ל' ואח\"כ יוודע לו למפרע דהוה תוך שלשים כשבאה לו השמועה אם חשבינן אותה כשמועה רחוקה או אמרינן כיון דהיה לו ידיעה תוך שלשים אע\"ג דעבר שלשים צריך להתאבל ע\"כ ורצה שם ללמוד דין זה ממ\"ש בשמחות דמהר\"ם בתאומים שמת אחד מהם תוך שלשים והשני חי עד לאחר שלשים דמסתפק שם להר\"ם אם יתאבל על המת דאי נימא דהוה ג\"כ בר קיימא דאין אשה מתעברת וחוזרת ומתעברת נפלים לפי' ר\"ח או דילמא דהוה כשמועה רחוקה כיון דהשתא כבר עברו שלשים יום או דילמא לא דמי לשמועה רחוקה דהתם לא ידע כלל שמת אבל הכא דידע מיתלא תלא עד שיודע ספיקא כו' וצידד מהר\"ם דפטור דהוה כמו שמועה רחוקה ועדיין נסתפק מהר\"ם מינץ שם דשמא בזה לא הוה כשמועה רחוקה דבכל עת ראוי לחול האבילות אם ישמע עדיין אם הוא תוך ל' משא\"כ בההיא דתאומים שזכרנו שא\"א לו להוודע תוך ל' אם הראשון נפל או בר קיימא ומסיק דצ\"ע אם חייב להתאבל בזה ע\"כ ולעד\"נ דאין כאן אבילות כיון שעכ\"פ השתא עברו ל' יום מיום המיתה דלא גרע ממי ששגג או הזיד ולא נהג כלל אבילות עד לאחר ל' יום דודאי אח\"כ אין עליו אבילות כמ\"ש כאן בסעיף א' דמי ששגג או הזיד משלים כל ל' משמע אחר ל' אין שום שייכות תשלומין כנלע\"ד. ושוב ראיתי בתשובת מוהר\"ם מלובלין שהביא דברי הש\"ע האלו כהוייתן ופסק כן והוא אגב חורפיה לא עיין כל הצורך בזה:"],"\u0010y0\u0011 \u0010g0\u0011 \u0010r0\u0011 מִתְאַבְּלִין עַל פִּי עֵד אֶחָד, וְעֵד מִפִּי עֵד \u0010c0\u0011 \u0010t0\u0011 וְעוֹבֵד כּוֹכָבִים מֵסִיחַ לְפִי \u0010g1\u0011 \u0010t1\u0011 \u0010r1\u0011 תֻּמּוֹ.\nשְׁנַיִם אוֹמְרִים: מֵת, וּשְׁנַיִם אוֹמְרִים: לֹא מֵת, \u0010y1\u0011 \u0010c1\u0011 אֵינוֹ מִתְאַבֵּל.",{"g":["טור בשם הרמב\"ן בסת\"ה וטענותיו הם בפרקי הרא\"ש והמרדכי בפ\"ג דמ\"ק וסיים הרמב\"ן זה הכלל עדות שמשיאין אשה על פיו קרובים מתאבלין:","\u0003מרדכי סמ\"ק (והגהמי\"י) מהא דאמרי' דר\"ע מודה לענין אבילות בכורות דף מ\"ט ע\"א:\u0004 "],"t":["\u0003ועובד כוכבים. \u0004 כתב רש\"ל עובדת כוכבים שספרה לפי תומה לראובן שמתה אחותו פסק ראבי\"ה שמתאבל על פיה דנאמנת להחמיר. וא\"מ פסק דהלכתא כדברי המיקל באבל ועובד כוכבים אינו נאמן להחמיר במילי דאבלות. וה\"ר ישעיה אומר דאין עובד כוכבים מסל\"ת נאמן אלא לעדות אשה או על פירותיו דשל ערלה הן אבל בכל עדיות דעלמא אין עובד כוכבים מסל\"ת נאמן בין להקל בין להחמיר ע\"כ תשובת אור זרוע. עכ\"ל:","\u0003שנים. \u0004 כ' הרמב\"ן זה הכלל כל עדות שמשיאים האשה על פיהם הקרובים מתאבלים. ועי' בא\"ע סי' י\"ז נתבאר עדות שמשיאים האשה על פיהם. וכ' הב\"ח היכא שכתבו לאחד שמת קרובו ואיכא ספק אם הוא תוך ל' חייב להתאבל דכל כמה דמצינן לאוקמיה אחזקתיה מוקמינן ואמרינן השתא מקרוב מת. מיהו היכא שהוא כתב יד של חכם אמרינן דמסתמא לאחר ל' הוא. דאם איתא שהיה אפשר שיגיע הכתב לידו תוך ל' לא היה כותב בסתם אלא היה מבאר. וכ\"כ בתשו' ר\"מ מינץ דצריך להתאבל מטעם חזקה כנ\"ל. וכ' דאם אירע שהורו דאין להתאבל מספק ואח\"כ נודע לו למפרע שמת תוך ל' צ\"ע אם יחזור ויתאבל או לא ע\"ש. ונ\"ל דצריך להתאבל בכה\"ג וע\"ל ר\"ס שצ\"ו ודוק עכ\"ל הש\"ך \u0005(ועי' בתשו' שזכרתי)\u0006 \u0005(ובנה\"כ הגיה דבריו שצ\"ל ול\"נ דאין צריך להתאבל וכו')\u0006 ובט\"ז פסק דהיכא דאיכא ספק אם הוא תוך ל' או לאו א\"צ להתאבל ע\"ש שמאריך בכמה ראיות להעמיד דבריו:"],"r":["\u0003מתאבלין כו'. \u0004ממעשה דר\"ח ורב בריש פסחים ובפ\"ג דמ\"ק ואמרי' בפט\"ו דיבמות \u0005(קט\"ז ב' במתני') \u0006התרתם ערוה חמורה כו' ה\"נ לענין אבילות וערא\"ש סי' ע\"ט ועמ\"ש בא\"ע סי' י\"ז סל\"ז:","\u0003שנים כו'. \u0004דנשאר בספק כמ\"ש בפ\"ו \u0005(ל\"א ב') \u0006ופ\"ט \u0005(מ\"ז) \u0006דסוטה וכאן ספקו להקל כמ\"ש בבכורות מ\"ט א' \u0005(הכל מודים וכו'):\u0006"]}],["אֲבֵלוּת יוֹם רִאשׁוֹן, אִם הוּא \u0010c0\u0011 יוֹם מִיתָה וּקְבוּרָה, הָוֵי דְּאוֹרַיְתָא; וּשְׁאָר הַיָּמִים, מִדְּרַבָּנָן. בַּמֶּה דְּבָרִים אֲמוּרִים, \u0010y0\u0011 בְּשִׁבְעָה מֵתִים הַמְּפֹרָשִׁים בַּתּוֹרָה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, אֲבָל אוֹתָם שֶׁהוֹסִיפוּ עֲלֵיהֶם כִּדְאִיתָא בְּסִימָן שע\"ד, אֲפִלוּ בְּיוֹם רִאשׁוֹן הֵם מִדְּרַבָּנָן. \u0010y1\u0011 \u0010c1\u0011 וְיֵשׁ אוֹמְרִים שֶׁאַף אֲבֵלוּת יוֹם רִאשׁוֹן דְּמִיתָה וּקְבוּרָה הָוֵי דְּרַבָּנָן בְּכָל הַמֵּתִים.",["\u0003בז' מתים. \u0004שהם אביו ואמו בנו ובתו אחיו ואחותו בתולה ואשתו נשואה:","\u0003וי\"א כו'. \u0004והכי קי\"ל כדלקמן סימן שצ\"ט סי\"ג:"],["\u0003יום מיתה וקבורה. \u0004לאפוקי מת ביום א' ונקבר למחר או שמועה קרובה:","\u0003וי\"א שאף אבילות כו'. \u0004בטור סיים אלא אנינות לחוד ביום ראשון דהוה דאורייתא ואנינות לחוד ואבילות לחוד האסור בזה מותר בזה ואונן אינו אסור ביום ראשון מן התורה אלא באכילת קדשים ומעשר שני ועוד החמירו בו חכמים בדברים המפורשים בפרק מי שמתו עכ\"ל פי' אונן הוה ביום המיתה אפילו אחר שנקבר לענין אכילת קדשים ומעשר שני כדאיתא בפרק טבול יום (זבחים דף ק') וחכמים החמירו בו קודם שנקבר לענין אכילת בשר ויין ותשמיש ופטור מכל המצות והיינו מטעם שמתו מוטל לפניו לקברו ואז מותר בנעילת סנדל ורחיצה וגילוח וכל מה שאסור משום אבילות דלעיל עד שיסתום הגולל ואז מותר בבשר ויין וחייב בכל המצות זולת תפילין ביום ראשון ומ\"ש הטור האסור בזה מותר בזה לאו כללא הוא דהא תשמיש אסור בשניהם אלא על שאר החילוקים שזכרנו אמר כן:"],"\u0010g0\u0011 \u0010r0\u0011 אֲבֵלוּת יוֹם רִאשׁוֹן, \u0010r1\u0011 אִם הוּא \u0010c0\u0011 יוֹם מִיתָה וּקְבוּרָה, הָוֵי דְּאוֹרַיְתָא; וּשְׁאָר הַיָּמִים, מִדְּרַבָּנָן. \u0010g1\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, \u0010y0\u0011 \u0010t0\u0011 בְּשִׁבְעָה מֵתִים הַמְּפֹרָשִׁים בַּתּוֹרָה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, אֲבָל אוֹתָם שֶׁהוֹסִיפוּ עֲלֵיהֶם כִּדְאִיתָא בְּסִימָן שע\"ד, אֲפִלוּ בְּיוֹם רִאשׁוֹן הֵם מִדְּרַבָּנָן. \u0010y1\u0011 \u0010c1\u0011 \u0010g2\u0011 וְיֵשׁ אוֹמְרִים שֶׁאַף אֲבֵלוּת יוֹם רִאשׁוֹן דְּמִיתָה וּקְבוּרָה הָוֵי \u0010t1\u0011 דְּרַבָּנָן בְּכָל הַמֵּתִים.",{"g":["טור בשם הרמב\"ן בסת\"ה ובשם הרמב\"ם ריש פ\"ב מהלכות אבל אך באבילות האיש על אשתו כתב שהוא מדבריהם ומפרש בב\"י ובכ\"מ כיון דאתיא מדרשא ואינו מפורש קרי לה מדבריהם:","שם:","\u0003שם בשם ר\"ת ור\"י וכ\"כ ה\"ר יונה בפרק ב' דברכות בשם חכמי הצרפתים וכן הסכים הרא\"ש:\u0004 "],"t":["\u0003בשבעה. \u0004 שהם אביו ואמו בנו ובתו אחיו ואחותו בתולה ואשתו נשואה:","\u0003דרבנן. \u0004 והכי קי\"ל כמ\"ש בסי' שצ\"ט סי\"ג:"],"r":["\u0003אבילות כו' וי\"א כו'. \u0004עברא\"ש ספ\"ב דברכות ורפ\"ג דמ\"ק סנ\"א:","\u0003אם הוא כו'. \u0004כמ\"ש בזבחים ק' א' רב מרי אמר ל\"ק כו' ועברא\"ש במ\"ק שם ור\"י דחה ראיה זו דשאני התם כו' ועבא\"ח סי' תקמ\"ח ס\"ג:"]}],["הַקוֹבֵר מֵתוֹ קֹדֶם הָרֶגֶל, בְּעִנְיָן שֶׁחָל עָלָיו אֲבֵלוּת, וְנָהַג בּוֹ \u0010y0\u0011 \u0010c0\u0011 אֲפִלוּ שָׁעָה אַחַת קֹדֶם הָרֶגֶל, מַפְסִיק הָאֲבֵלוּת וּמְבַטֵּל מִמֶּנּוּ גְזֵרַת שִׁבְעָה \u0010y1\u0011 וִימֵי הָרֶגֶל עוֹלִים לוֹ לִמִנְיַן שְׁלֹשִׁים, הֲרֵי שִׁבְעָה לִפְנֵי הָרֶגֶל, וִימֵי הָרֶגֶל, וּמַשְׁלִים עֲלֵיהֶם הַשְּׁלֹשִׁים. וְדַוְקָא שֶׁנָּהַג אֲבֵלוּת בְּאוֹתָהּ שָׁעָה, אֲפִלוּ לֹא נָהַג אֶלָא דְּבָרִים שֶׁבְּצִנְעָא, כְּגוֹן שֶׁשָּׁמַע שְׁמוּעָה קְרוֹבָה בְּיוֹם שַׁבָּת שֶׁחָל לִהְיוֹת בְּעֶרֶב הָרֶגֶל, שֶׁאַף עַל פִּי שֶׁאֵינוֹ נוֹהֵג אֶלָא דְּבָרִים שֶׁבְּצִנְעָא, הָרֶגֶל מַפְסִיק. אָבֵל אִם שָׁגַג אוֹ הֵזִיד וְלֹא נָהַג אֲבֵלוּת, \u0005אוֹ\u0006 שֶׁהָיָה קָרוֹב לַחֲשֵׁכָה וְלֹא הָיָה יָכוֹל לִנְהֹג, אֵין הָרֶגֶל מְבַטֵּל הָאֲבֵלוּת; וְכָל שֶׁכֵּן אִם לֹא יָדַע בְּמִיתַת הַמֵּת קֹדֶם הָרֶגֶל, שֶׁאֵין הָרֶגֶל מְבַטְּלוֹ, \u0010y2\u0011 אֶלָא נוֹהֵג בָּרֶגֶל דְּבָרִים שֶׁבְּצִנְעָא, וּמוֹנֶה שִׁבְעָה אַחַר הָרֶגֶל, וּבְאוֹתָהּ הַשִּׁבְעָה מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים, וַעֲבָדָיו וְשִׁפְחוֹתָיו עוֹשִׂים בְּצִנְעָה בְּתוֹךְ בֵּיתוֹ, דְּכֵיוָן דִּכְבָר נִתְבַּטֵּל בְּשִׁבְעַת יְמֵי הָרֶגֶל מִמְּלָאכָה, אַף עַל פִּי שֶׁלֹּא נִתְבַּטֵּל מֵחֲמַת הָאֵבֶל אֶלָא מֵחֲמַת הָרֶגֶל, סוֹף סוֹף נָהַג בְּדִין אֲבֵלוּת בְּעִנְיַן מְלָאכָה, הִלְכָּךְ אֵין לְהַחְמִיר בּוֹ כְּמוֹ בִּשְׁאָר אֲבֵלוּת וּמְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים. וְכָל יְמֵי הָרֶגֶל רַבִּים מִתְעַסְקִים בּוֹ לְנַחֲמוֹ, \u0010y3\u0011 הִלְכָּךְ אֵין מִתְעַסְקִין בּוֹ לְנַחֲמוֹ אַחַר הָרֶגֶל. וְרֶגֶל עוֹלֶה לְמִנְיַן שְׁלֹשִׁים, שֶׁהֲרֵי דִּין שְׁלֹשִׁים דְּהַיְנוּ גִהוּץ וְתִסְפֹּרֶת נוֹהֲגִים בָּרֶגֶל, \u0010c1\u0011 וְלֹא מִתּוֹרַת רֶגֶל בִּלְבַד אָסוּר בָּהֶם, אֶלָא אַף מִתּוֹרַת אֵבֶל, שֶׁהֲרֵי מִתּוֹרַת הָרֶגֶל מֻתָּר לִלְבֹּשׁ כֵּלִים מְגֹהֲצִים חֲדָשִׁים וּלְבָנִים, \u0010y4\u0011 וְנוֹטֵל צִפָּרְנָיו בְּמִסְפָּרַיִם וְשָׂמֵחַ שִׂמְחַת מְרֵעוּת, וְהַבָּא מִמְּדִינַת הַיָּם וּמִבֵּית הַשִּׁבְיָה וְהַשְּׁאָר שֶׁמָּנוּ חֲכָמִים, מֻתָּרִין לְסַפֵּר וּלְכַבֵּס, וּמִדִּין אֲבֵלוּת אָסוּר בְּכֻלָם כְּמוֹ בַּחֹל.\nהַקוֹבֵר מֵתוֹ \u0010c2\u0011 בָּרֶגֶל \u0010y5\u0011 בְּחֹל הַמּוֹעֵד, נֹהַג דִּין אֲנִינוּת כָּל זְמַן שֶׁלֹּא נִקְבַּר; וּלְאַחַר שֶׁנִּקְבַּר, נוֹהֵג דְּבָרִים שֶׁבְּצִנְעָא \u0005וּמִכָּל מָקוֹם מֻתָּר לְיַחֵד עִם אִשְׁתּוֹ (בֵּית יוֹסֵף בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ)\u0006 וְעַיֵּן לִעֵיל סִימָן שפ\"ג וּבְא\"ח סִימָן תקמ\"ח, וְהָרֶגֶל עוֹלֶה לְמִנְיַן שְׁלֹשִׁים, שֶׁמַּשְׁלִים עָלָיו שְׁלֹשִׁים; אֲפִלוּ קְבָרוֹ בְּחַג הַסֻכּוֹת, \u0010y6\u0011 \u0010c3\u0011 לֹא אַמְרִינָן דִּשְׁמִינִי עֲצֶרֶת מְבַטֵּל, וּמִתְעַסְקִים בָּרֶגֶל לְנַחֲמוֹ. \u0005הַגָּה: וְכָל מְלָאכָה הַמֻּתֶּרֶת לַעֲשׂוֹת לוֹ בַּמּוֹעֵד בְּדָבָר הָאָבֵד, מֻתָּר לַעֲשׂוֹת בְּעַצְמוֹ; וְאִם אֵין דָּבָר הָאָבֵד, נַעֲשֵׂית עַל יְדֵי אֲחֵרִים בְּבָתֵּיהֶם, וַעֲבָדָיו וְשִׁפְחוֹתָיו עוֹשִׂין בְּצִנְעָא תּוֹךְ בֵּיתוֹ (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006, וּלְאַחַר הָרֶגֶל מַתְחִיל לִמְנוֹת שִׁבְעָה, וְלִכְשֶׁיִּכְלוּ שִׁבְעָה לְמִיתַת הַמֵּת אַף עַל פִּי שֶׁעֲדַיִן לֹא כָּלוּ שִׁבְעַת יְמֵי הָאֲבֵלוּת, מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים בְּבָתֵּיהֶם, וַעֲבָדָיו עוֹשִׂין לוֹ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ; וְאֵין רַבִּים מִתְעַסְקִים בּוֹ לְנַחֲמוֹ אַחַר הָרֶגֶל מִנְיַן הַיָּמִים שֶׁנִּחֲמוּהוּ בָּרֶגֶל, אֲבָל מַרְאִים לוֹ פָּנִים, כְּגוֹן אִם קְבָרוֹ בִּשְׁלֹשָׁה יָמִים הָאַחֲרוֹנִים שֶׁל רֶגֶל, מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים בִּשְׁלֹשָׁה יָמִים אַחֲרוֹנִים שֶׁל אֵבֶל, \u0010y7\u0011 וּבִמְקוֹמוֹת שֶׁעוֹשִׂים שְׁנֵי יָמִים, מוֹנֶה הַשִּׁבְעָה מִיּוֹם טוֹב שֵׁנִי הָאַחֲרוֹן, הוֹאִיל וּמִדִּבְרֵיהֶם הוּא עוֹלֶה מֵהַמִּנְיָן, וּמוֹנֶה מֵאַחֲרָיו שִׁשָּׁה יָמִים בִּלְבַד.\nאִם קָבַר אֶת מֵתוֹ שִׁבְעָה יָמִים קֹדֶם הָרֶגֶל, וְנָהַג בָּהֶם גְזֵרַת שִׁבְעָה, הָרֶגֶל מְבַטֵּל מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים, אֲפִלוּ חָל יוֹם שְׁבִיעִי בְּעֶרֶב הָרֶגֶל, דְּמִקְצָת הַיּוֹם כְּכֻלוֹ וְעוֹלֶה לְכָאן וּלְכָאן, וּמֻתָּר לְכַבֵּס \u0010y8\u0011 וְלִרְחֹץ וּלְסַפֵּר בְּעֶרֶב הָרֶגֶל. \u0005הַגָּה: \u0010y9\u0011 סָמוּךְ לַחֲשֵׁכָה (טוּר)\u0006. \u0010y10\u0011 וּבְעֶרֶב פֶּסַח מֻתָּר בַּכֹּל אַחַר חֲצוֹת, דְּהַיְנוּ מִזְּמַן שְׁחִיטַת הַפֶּסַח וָאֵילָךְ; וְעָדִיף שֶׁיְּגַלֵּחַ קֹדֶם חֲצוֹת, \u0010y11\u0011 הוֹאִיל וַאֲחֵרִים אֲסוּרִים לְגַלֵּחַ אַחַר חֲצוֹת \u0005(תְּשׁוּבַת ר\"י מִינְ\u0006 ץ \u0005ס\"ד)\u0006. וְכֵן אִם חָל שְׁמִינִי בְּשַׁבָּת שֶׁבְּעֶרֶב הָרֶגֶל, מֻתָּר לְכַבֵּס וְלִרְחֹץ וּלְסַפֵּר בְּעֶרֶב שַׁבָּת, וְאִם לֹא גִלַח בְּעֶרֶב יוֹם טוֹב אוֹ בְּעֶרֶב שַׁבָּת, מֻתָּר לְגַלֵחַ אַחַר הָרֶגֶל, שֶׁכְּבָר נִתְבַּטֵּל מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים. אֲבָל בְּחֹל הַמּוֹעֵד לֹא יְגַלַח, כֵּיוָן שֶׁהָיָה אֶפְשָׁר לוֹ לְגַלֵחַ קֹדֶם הָרֶגֶל. וְאִם חָל שְׁבִיעִי שֶׁלוֹ בְּשַׁבַּת עֶרֶב הָרֶגֶל, אָסוּר לְגַלֵחַ בְּעֶרֶב שַׁבָּת, וּמֻתָּר לְגַלֵחַ אַחַר הָרֶגֶל, וְכֵן בְּחֹל הַמּוֹעֵד, כֵּיוָן שֶׁלֹּא הָיָה יָכוֹל לְגַלֵחַ קֹדֶם הָרֶגֶל.\nהָא דְּרֶגֶל מְבַטֵּל גְזֵרַת שְׁלֹשִׁים, בִּשְׁאָר מֵתִים. אֲבָל בְּאָבִיו וְאִמּוֹ, שֶׁאָסוּר \u0005לְסַפֵּר\u0006 \u0010y12\u0011 עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו, אֲפִלוּ פָּגַע בּוֹ הָרֶגֶל לְאַחַר ל' יוֹם, אֵינוֹ מְבַטֵּל.\nאִם חָל אֶחָד מִיְּמֵי הָאֲבֵלוּת, חוּץ מֵהַשְּׁבִיעִי, בְּעֶרֶב הָרֶגֶל, \u0010y13\u0011 מֻתָּר לְכַבֵּס, וְלֹא יִלְבְּשֶׁנּוּ עַד הַלַיְלָה. וְטוֹב לִזָּהֵר מִלְכַבֵּס עַד אַחַר חֲצוֹת, כְּדֵי שֶׁיְּהֵא נִכָּר שֶׁמִּפְּנֵי הָרֶגֶל הוּא מְכַבֵּס. אֲבָל \u0010y14\u0011 לִרְחֹץ, אָסוּר עַד הַלַיְלָה. וְיֵשׁ מַתִּירִין לִרְחֹץ אַחַר תְּפִלַת הַמִּנְחָה, סָמוּךְ \u0010y15\u0011 \u0010c4\u0011 לַחֲשֵׁכָה, \u0005וְכֵן נוֹהֲגִין.\u0006\nרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים חֲשׁוּבִים כִּרְגָלִים לְבַטֵּל הָאֲבֵלוּת.\nנָהַג שָׁעָה אַחַת לִפְנֵי הַפֶּסַח, אוֹתָהּ שָׁעָה חֲשׁוּבָה כְּז', וְח' יְמֵי הַפֶּסַח הֲרֵי ט\"ו, וּמַשְׁלִים עֲלֵיהֶם ט\"ו אֲחֵרִים.\nשָׁעָה אַחַת לִפְנֵי עֲצֶרֶת חֲשׁוּבָה כְּשִׁבְעָה. וַעֲצֶרֶת, כֵּיוָן שֶׁאִם לֹא הִקְרִיב קָרְבָּנוֹת עֲצֶרֶת בַּעֲצֶרֶת יֵשׁ לוֹ תַּשְׁלוּמִין כָּל שִׁבְעָה, חָשׁוּב כְּשִׁבְעָה, הֲרֵי י\"ד, וּמַשְׁלִים עֲלֵיהֶם ט\"ז אֲחֵרִים; \u0010y16\u0011 וְיוֹם שֵׁנִי שֶׁל עֲצֶרֶת עוֹלֶה לְמִנְיַן הַט\"ז.\nשָׁעָה אַחַת לִפְנֵי רֹאשׁ הַשָּׁנָה בָּטְלָה מִמֶּנּוּ גְזֵרַת שִׁבְעָה, מִפְּנֵי רֹאשׁ הַשָּׁנָה; וּגְזֵרַת ל' מְבַטֵּל מִמֶּנּוּ יוֹם כִּפּוּרִים; וּמְגַלֵחַ עֶרֶב יוֹם כִּפּוּרִים. וְהוּא הַדִּין לְקוֹבֵר מֵתוֹ בִּשְׁלֹשָׁה בְּתִשְׁרֵי, שֶׁמְגַלֵחַ בְּעֶרֶב יוֹם הַכִּפּוּרִים.\nשָׁעָה אַחַת לִפְנֵי יוֹם הַכִּפּוּרִים בְּטֵלָה מִמֶּנּוּ גְזֵרַת ז' מִפְּנֵי יוֹם כִּפּוּרִים, וּגְזֵרַת ל' מְבַטֵּל מִמֶּנּוּ הֶחָג, וּמְגַלֵחַ בְּעֶרֶב הֶחָג.\nשָׁעָה אַחַת לִפְנָי הֶחָג וְהֶחָג, הֲרֵי י\"ד; וּשְׁמִינִי עֲצֶרֶת שִׁבְעָה, הֲרֵי כ\"א; וְיוֹם שֵׁנִי שֶׁל שְׁמִינִי עֲצֶרֶת, \u0010c5\u0011 הֲרֵי כ\"ב; וּמַשְׁלִים עֲלֵיהֶם ח' אֲחֵרִים.\nהַקוֹבֵר אֶת מֵתוֹ שָׁעָה אַחַת לִפְנֵי הָרֶגֶל, אוֹתָהּ שָׁעָה וְהָרֶגֶל חֲשׁוּבִים כְּי\"ד, וּמִיָּד אַחַר הָרֶגֶל יֵשׁ לוֹ דִּין שָׁבוּעַ שְׁלִישִׁי \u0010y17\u0011 לְעִנְיָן שֶׁיּוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר.\nבִּמְקוֹמוֹת שֶׁעוֹשִׂין שְׁנֵי יוֹם טוֹב, מִי שֶׁמֵּת לוֹ מֵת בְּיוֹם טוֹב שֵׁנִי שֶׁהוּא יוֹם טוֹב הָאַחֲרוֹן שֶׁל פֶּסַח אוֹ שֶׁל חַג, אוֹ בְּיוֹם טוֹב שֵׁנִי שֶׁל עֲצֶרֶת, \u0010c6\u0011 וּקְבָרוֹ בּוֹ בַּיּוֹם, נוֹהֵג בּוֹ אֲבֵלוּת, הוֹאִיל וְיוֹם טוֹב שֵׁנִי מִדִּבְרֵיהֶם, וַאֲבֵלוּת יוֹם רִאשׁוֹן שֶׁהוּא יוֹם מִיתָה וּקְבוּרָה שֶׁל תּוֹרָה, יִדָּחֶה עֲשֵׂה שֶׁל דִּבְרֵיהֶם מִפְּנֵי עֲשֵׂה שֶׁל תּוֹרָה. אֲבָל אִם מֵת בְּיוֹם טוֹב שֵׁנִי שֶׁל רֹאשׁ הַשָּׁנָה, וְקָבְרוּ בּוֹ בַּיּוֹם, אֵינוֹ נוֹהֵג בּוֹ אֲבֵלוּת, שֶׁשְּׁנֵי הַיָּמִים כְּיוֹם אָרֹךְ הֵם. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּשִׁבְעָה מֵתִים הַמְּפֹרָשִׁים בַּתּוֹרָה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, אֲבָל אוֹתָם שֶׁהוֹסִיפוּ עֲלֵיהֶם כִּדְאִיתָא בְּסִימָן שע\"ד, אֵין אֲבֵלוּתָם אֶלָא מִדְּרַבָּנָן, לְפִיכָךְ אֵינוֹ נוֹהֵג עֲלֵיהֶם אֲבֵלוּת בְּשׁוּם יוֹם טוֹב. וַאֲפִלוּ בְּאוֹתָם שֶׁאָמַרְנוּ שֶׁנּוֹהֵג אֲבֵלוּת בְּיוֹם טוֹב שֵׁנִי, אֵינוֹ קוֹרֵעַ. וְהָעוֹלָם נוֹהֲגִין שֶׁלֹּא לְהִתְאַבֵּל בְּיוֹם טוֹב שֵׁנִי שֶׁל גָלֻיּוֹת עַל שׁוּם מֵת, אֲפִלוּ הוּא יוֹם מִיתָה וּקְבוּרָה. \u0005הַגָּה: דְּסוֹבְרִין כְּדַעַת הָאוֹמְרִים שֶׁאֵין שׁוּם אֲבֵלוּת דְּאוֹרַיְתָא, וְכֵן הַמִּנְהָג פָּשׁוּט, וְאֵין לְשַׁנּוֹת (ר\"ת וְר\"י וְרֹא\"שׁ)\u0006.\nמֵת לוֹ מֵת בְּעֶרֶב יוֹם טוֹב, וְנִתְיָרֵא שֶׁמָּא לֹא יַסְפִּיק לְקָבְרוֹ מִבְּעוֹד יוֹם, וּמְסָרוֹ לְעוֹבְדֵי כּוֹכָבִים שֶׁיּוֹלִיכוּהוּ לְקָבְרוֹ, כֵּיוָן שֶׁהוֹצִיאוּהוּ מֵהָעִיר וְנִתְכַּסָה מֵעֵינֵי הַקְרוֹבִים \u0010y18\u0011 חָלָה עָלָיו אֲבֵלוּת; וְאִם הוּא שָׁעָה אַחַת קֹדֶם הָרֶגֶל, וְנָהַג בּוֹ אֲבֵלוּת, בָּטְלָה לָהּ גְזֵרַת שִׁבְעָה אַף עַל פִּי שֶׁנִּקְבַּר בְּיוֹם טוֹב.",["\u0003אפילו שעה אחת. \u0004פירוש כל שהוא ולא בעינן שעה זמניות וכ\"כ בתשובת משאת בנימין סי' ע\"ד:","\u0003וימי הרגל עולים כו' ומשלים כו'. \u0004היינו ע\"פ שנתבאר לקמן מסעיף ז' ואילך:","\u0003אלא נוהג ברגל דברים שבצינעא. \u0004ולענין מלאכה במועד דינו כמ\"ש הרב בסעיף ב':","\u0003הלכך אין מתעסקין בו לנחמו ורגל עולה למנין (ז') [שלשים]. \u0004היינו בנודע לו מיתת המת ברגל אע\"פ שלא נודע לו קודם הרגל והיינו שכתב ר' ירוחם דרגל עולה למנין (ז') [שלשים] מדלא גרע מקובר מתו ברגל עכ\"ל ולא כמ\"ש בב\"י דבנודע לו מיתת המת קודם הרגל מיירי ואולי ל\"ד קאמר או ט\"ס הוא וצ\"ל ברגל:","\u0003ונוטל צפרניו במספרים. \u0004היינו לדעת המחבר בא\"ח סי' תקל\"ב אבל אנן קי\"ל להחמיר כמ\"ש הרב שם וסתם כאן הדברים לפי שאין כאן מקום דיני מועד:","\u0003בח\"ה. \u0004ה\"ה ביו\"ט שני או ביום טוב ראשון כשרוצה לקברו ע\"י עממים חל עליו אנינות כדלעיל סימן שמ\"א סעיף א' ולאחר שיקבר כל אלו הדינים נוהגים בו:","\u0003לא אמרינן דשמיני עצרת מבטל. \u0004ואין ש\"ע עולה רק ליום אחד כשקברו ברגל כ\"כ הגהמי\"י ומביאה ב\"י ודוקא כשקברו קודם חג הסוכות הוא דעולה ש\"ע ג\"כ לז' לקמן סעיף י\"א משא\"כ הכא וכ\"כ הב\"ח בשם התוספות ומרדכי ופסק כן ודלא כמהרש\"ל בתשובה סימן ה' שכתב דמבטל הוא דאינו מבטל הא למנין ז' לענין הל' עולה ש\"ע אפי' קברו ברגל מיהו בתשובת משאת בנימין סימן ע\"א פסק כמהרש\"ל עיין שם וכן נראה דעת הדרישה:","\u0003ובמקומות שעושים ב' ימים כו'. \u0004כתב הב\"ח ס\"ס זה דה\"ה בשני י\"ט של ר\"ה כגון שמת לו מת ביו\"ט ראשון של ר\"ה מונה הז' מיו\"ט הב' דהוי ג\"כ מדבריהם וע\"ש:","\u0003ולספר. \u0004כלומר דאע\"ג דתספורת נוהג כל ל' וכדלעיל ר\"ס ש\"ץ הכא בטל ממנו גזרת ל':","\u0003סמוך לחשיכה. \u0004מה שנרשם כאן טור הוא טעות דבטור לא כתב ע\"ש ריב\"א אלא דבחל יום א' דאבילות או יום (ז') [ו] בערב הרגל דמותר דוקא סמוך לחשכה אבל נ\"ל שהוא מהגהת אשר\"י שהביא הב\"י בא\"ח סי' תקמ\"ח וז\"ל אפי' חל יום ח' או יום ט' בערב הרגל צריך להמתין עד סמוך ללילה שאז ניכר שבשביל הרגל הותר כ\"כ ראבי\"ה ע\"כ:","\u0003ובערב פסח כו'. \u0004זה הוציא הרב מתשובת מהר\"י מינץ סי' ד' וצ\"ע דאדרבה משמע שם דע\"פ שוה לכל ערב יו\"ט לענין כיבוס ורחיצה דלא הותר אלא סמוך לחשיכה דמסיים שם וא\"כ יכול לספר קודם חצות ול\"ד לרחיצה דאפשר מחשיכה כו' עיין שם רק דאיתא שם דבערב פסח יש לגלח קודם חצות הואיל ואחרים אסורים לגלח אחר חצות דאין עושין מלאכה בערב פסח אחר חצות מפני שהיה זמן שחיטת הפסח וכמו שנתבאר באורח חיים סי' תקמ\"ח עיין שם וראיתי בב\"ה שהעתיק דברי הרב והשמיט הא דבערב פסח מותר בכל וצריך עיון:","\u0003הואיל ואחרים אסורים לגלח לו. \u0004דאין עושין מלאכה בערב פסח אחר חצות ואם כן יצטרך לגלח על ידי עצמו להכי עדיף טפי קודם חצות וכן הוא בתשובת מהר\"ם מינץ שם ודלא כהעט\"ז שכתב הואיל ואחרים הרבה נהגו איסור לגלח אחר חצות גם הוא ינהוג איסור כו':","\u0003עד שיגערו בו חביריו. \u0004כדלעיל סימן ש\"ץ ס\"ד:","\u0003מותר לכבס. \u0004דכבר בטל ממנו גזרת ז' אבל לספר אסור דלא נתבטל ממנו גזרת ל' כיון דאין כאן ז' ימים קודם הרגל:","\u0003אסור עד הלילה. \u0004כיון דאפשר משחשכה:","\u0003וכן נוהגין. \u0004וכתוב בת\"ה סימן רפ\"ז דאפילו מת לו מת בע\"ש ואותו שבת הוא ערב הרגל מותר לרחוץ בע\"ש לפי מנהגינו ואין להקשות דהיאך כ' הרב וכן נוהגין דהא לעיל ר\"ס שפ\"א כתב הרב דאנן נהגינן איסור רחיצה כל ל' וכן לעיל ר\"ס שפ\"ט כתב דנהגינן איסור כביסה כל ל' י\"ל דאינו אלא חומרא ומדינא שרי וכדמשמע מדברי הרב שם והכא משום כבוד הרגל לא נהגו להחמיר וכ\"כ העט\"ז ותדע דהא בת\"ה שם כתוב בשם מהר\"מ אפילו לא נהג אבילות אלא שעה א' לפני הרגל מותר ברחיצה בחמין סמוך לערב והרי מהר\"מ ס\"ל דאסרי' רחיצה כל שלשים וכמ\"ש הגהמ\"י על שמו ומביא ב\"י סוף סי' ת' אלא ודאי כדאמרן ואע\"ג דבא\"ח סימן תקמ\"ח ס\"ח וס\"י כתב הרב דלדידן דנוהגים איסור רחיצה כל ל' אסור לרחוץ דהא הרגל לא בטל ממנו רק גזרת ז' וה\"ה לענין כיבוס במקום דנוהגין איסור כיבוס כל ל' עכ\"ל היינו משום דכך הוא ראוי להורות אי הוי איסור רחיצה וכיבוס כל ל' מן הדין אבל כאן כתב דמ\"מ המנהג אינו כן וכ\"כ הב\"ח אלא דצריך ליישב לאיזה צורך כ' הרב שם כן כיון דס\"ס המנהג אינו כן ונ\"ל דס\"ל דהא דהמנהג אינו כן היינו משום כבוד הרגל והלכך היכא דליכא משום כבוד הרגל אסור ונ\"מ דלאחר הרגל אסור רחיצה וכביסה עד ל' דהרגל לא בטל ממנו רק גזרת ז' כנ\"ל ודוק:","\u0003ויום שני של עצרת עולה למנין. \u0004כיון דיום טוב שני אינו אלא מדבריהם:","\u0003לענין שיושב כו'. \u0004כדלעיל סימן שצ\"ג סעיף ב' ואנן לא נהגינן הכי כמו שנתבאר שם:","\u0003חלה עליו אבילות. \u0004וכמו שנתבאר לעיל ר\"ס שס\"ה:"],["\u0003אפי' שעה אחת. \u0004פירוש אפי' חליצת מנעל לחוד שנהג מעט די בכך. כ\"פ מהר\"ר בנימין בתשובה:","\u0003ולא מתורת רגל לבד כו'. \u0004זהו סברת הרמב\"ן והוכיחה מדמיבעיא לן אי רגל עולה למנין ל' או לאו ולענין ז' לא מבעיא ליה דודאי אינו עולה כיון דלא נהגא מצות ז' ברגל דהא אין איסור בנעילת סנדל וכפיית מטה כי קא מבעיא ליה לענין ל' דקא נהגא מצות ל' ברגל פירש\"י דהא ברגל נמי אסור בגיהוץ ותספורת והקשה הרמב\"ן הא מקצת דין ז' נמי נוהג ברגל דהא אינו מכבס כסותו אפילו במים לחוד ורבים מתעסקים לנחמו כדין אבל אלא ודאי במנין ל' צריך להיות דכל דין ל' אף מה שאין אסור מחמת הרגל נוהג בו משא\"כ בדין ז' שאין נוהג בו אלא מעט והלכך כתב כאן שאף דין גיהוץ ותספורת נוהג באבל בלא דין הרגל וכמ\"ש כאן. והטור כ' שמדברי הרא\"ש נראה שאין איסורן מדין אבל יותר מאיסור דרגל והיינו דסבר אע\"פ שאין נוהג איסור מחמת אבילות טפי מרגל אלא מה שאסור ברגל מ\"מ עולה הרגל למנין ל' כיון דעכ\"פ נוהג בו איסור ופסק ב\"י כרמב\"ן דמסתבר טעמיה וכן פסק בש\"ע ובתשובת מהר\"ר בנימין חולק על הש\"ע דלא מסתבר לפסוק כרמב\"ן דדבריו דחוים דאין קושיתו קושיא ממנין ז' דעיקר דין ז' הוא פח\"ז נת\"ר סי' של ז' דהיינו פריעת ראש חליצת סנדל) כו' ואע\"ג שנוהג דין כיבוס במי' אין זה עיקר דין אבילות משא\"כ דין ל' שעיקר הדין הוא גיהוץ ותספורת והוא נוהג גם ברגל ע\"כ עולה ועוד מאן לימא לן שהקובר מתו ברגל אינו מכבס כסותו במים לבד דילמא אין ה\"נ דמותר עכ\"ד ואינם נראים כלל דמה שכ' דעיקר דין אבילות הוא פח\"ז נת\"ר מי הגיד לו שזה עיקר דלא הזכירו אלו בגמ' אלא לענין שבת דפח\"ז חוב ונת\"ר רשות אבל כיבוס במים אין שייך לענין שבת כלל ע\"כ לא חשביה בכלל פח\"ז נת\"ר ובאמת אין חילוק בין אלו לכיבוס כלל וכיבוס הוא נזכר בירושל' ואי ס\"ד דבמקצת דין ל' סגי ה\"נ היה לנו לומר בדין ז' במקצת ומ\"ש דילמא כיבוס במים ברגל אין אסור מחמת אבל לא דק כלל בזה דודאי איסור גמור הוא לכ\"ע דהא דבר שבצינעא נוהג בו איסור וזה ודאי צינעא הוא דמי ירגיש בזה שאין מכבס כסותו במים. והרא\"ש אין חולק אלא על תוספת דגיהוץ ותספורת דהויין מילי דפרהסיא ע\"כ אין בהם איסור נוסף על הרגל והרמב\"ן חשב גם זה לצינעא דהיינו מה שאין לובש בגד מגוהץ באותן ימים דמי יאמר שיש לו בגד מגוהץ ואינו לובשו גם מה שחשב עוד הרמב\"ן לאיסור נוסף במה שאינו מגלח אף שבא ממדינת הים אין זה מפורסם כ\"כ וכן שאר הדברים שחשבן כאן ובאמת דברים נכונים הם לומר כן ויפה דן הב\"י כרמב\"ן:\n\u0003וראיתי \u0004עוד בתשו' הנ\"ל שמעשה היה בחתן שנשא אשה בערב הרגל ובתוך הרגל מת לו מת פסק שם דאע\"ג דחתן דעלמא שאירע לו אבילות בתוך ז' ימי משתה אין מונה ל' אלא אחר ימי המשתה מטעם דהוא עדיף מימי הרגל דאיהו מותר בגיהוץ ותספורת כמ\"ש סי' שמ\"ב משא\"כ חתן זה דימי משתה שלו הם ברגל ממילא אסור בגיהוץ וכו' משום הכי להרמב\"ן דלעיל דס\"ל דהרגל עולה למנין ל' מטעם איסור נוסף ממילא זה החתן שמותר באותו תוספת ע\"כ [אין] עולין לו ימי המשתה שלו ולהרא\"ש (נמי) דעולה לו [נמי] אפי' אם ימי האבילות אין להם איסור יותר מן הרגל א\"כ הכי נמי דנוהג איסור גיהוץ מחמת הרגל עולה לו ג\"כ למנין שלשים וכ\"פ שם למעשה ובעיני יפלא מאד דברים אלו דודאי גם להרא\"ש אין עולה אלא כשיש איסור לאבל מחמת אבלותו אלא שאותו איסור הוא ג\"כ מחמת הרגל בזה אמר דשפיר עולה כיון דמ\"מ הוא נוהג באותו איסור דהוא יכול לומר אני עושה מחמת האבילות ואם יש איסור נוסף מה לי בכך משא\"כ בחתן זה שאין בו חיוב אבילות כלל וזה שנוהג איסור הוא מחמת הרגל לחוד היאך מצאנו ידינו ורגלינו לומר שיהיה זה נחשב לימי השלשים הלא אנו רואין שזה נהג איסור דוקא מחמת הרגל לא מחמת אבילות הא למה זה דומה לחתן שהוא תוך שבעת ימי משתה שלו במקום שאי אפשר לו לגהץ או שהיתה שבועה עליו שלא לגהץ וכי נימא שיהיה זה נחשב לו למנין ל' הא ודאי ליתא. על כן נראה דהאי מילתא שכתב דעולה לחתן ימי משתה שלו למנין ל' חידושא הוא ולא ילפינן מיניה ואינו עולה לכולי עלמא כמו בשאר חתן ואין זה דומה למ\"ש בסימן שמ\"א דיכול החתן לדחות שבעת ימי משתה ולהקדים שבעת ימי אבילות לטובתו דהתם בימי אבילות תליא מילתא בקום עשה שצריך לעשות מעשה להראות האבילות דהיינו חליצת סנדל וכפיית מטה וכיוצא בו שפיר אמרינן דעל ידי מעשה ההוא מבטל שבעת ימי המשתה שלו מה שאין כן בדין ל' שאין תלוי במעשה אלא במה שאנו אוסרין לו גיהוץ ותספורת בזה ודאי אנו אומרים שאין בידו לבטל ואם הוא אומר שרוצה לבטל מחמת שבלא\"ה יהיה אסור לו מחמת הרגל הרי אנו רואים בפירוש שהוא אינו רוצה לעשות שום אבילות רק מה שצריך לעשות מחמת הרגל ובזה ודאי אין עולה לו כן נראה לע\"ד בדבר זה:","\u0003ברגל בחול המועד. \u0004דאילו ביו\"ט עצמו יש חילוק ביו\"ט הראשון אינו נוהג אנינות אא\"כ רוצה לקברו ע\"י עממים ובשני נוהג אנינות בכל גווני אבל בחול המועד נוהג לעולם אנינות:","\u0003לא אמרינן דשמיני עצרת מבטל. \u0004פי' דהוה אמינא דשמיני עצרת שהוא רגל בפני עצמו אתי ומבטל האבילות כדלעיל ריש סי' זה היכא דנהג שעה אחת אבילות לפני הרגל והכי נמי נהג ברגל עצמו קודם שמיני עצרת קצת אבילות דהיינו גיהוץ ותספורת כמ\"ש בסוף סעיף א' קמ\"ל דלא אמרינן כן דליכא חשיבות לשמיני עצרת אלא אם כבר נסתלק משבעת ימי אבלות קודם הרגל מה שאין כן בזה. וכ' ב\"י בשם הגהת מיימונית דהוא הדין דאין חשיבות לשמיני עצרת להיות נחשב לשבעה ימים שנזכר בסעיף י\"א אלא אם נקבר קודם הרגל משא\"כ אם מת ברגל לא נחשב שמיני עצרת במנין ל' אלא ליום אחד וכן כתבו התוס' בפ' אלו מגלחין (מועד קטן דף כ\"ד) וכן כ' המרדכי בשם ריב\"ש דלא כדברי ה\"ר יוסף שסבירא ליה דשמיני עצרת וכן עצרת ויו\"כ הכל נחשב לשבעה ימים אם מת בו ביום ביום לענין ל' ורש\"ל בתשובה סי' ה' חולק ואומר דגם במת ברגל נחשב שמ\"ע למנין שבעה ימים לענין ל' ואין לו ראיה ברורה רק שמביא ראיה מדכתב הטור כאן שאין שמיני עצרת מבטל משמע דדוקא אינו מבטל לגמרי שבעת ימי אבילות אבל מ\"מ נחשב לשבעה לענין מנין שלשים אם כן סבירא ליה כה\"ר יוסף שזכרנו ואין מזה ראיה דהטור נקט ל' ביטול לאפוקי ממ\"ש תחילה שהרגל מבטל כמו שכתבתי. וכן משמע לי מדברי הרמב\"ם דלא כרש\"ל בזה מדכתב הקובר מתו בתוך הרגל כו' והעתיק לשונו בשלחן ערוך באורח חיים סימן תקמ\"ח וסיים שם ומונה שלשים מיום הקבורה משמע אפילו מת בסוף ימי הרגל מונה מיום הקבורה שלשים יום ולא אמרינן דאותן ימי הרגל יהיו נחשבים לשבעה ימים דמאי שנא ממת בעצרת או יום כפור לפי דעת ה\"ר יוסף שזכרנו אלא ודאי דאין שום עילוי לרגל כלל להיות נחשב לשבעה אלא אם כן נקבר קודם הרגל שעה אחת. וכן יראה לי מסוגית הגמרא דבעי מיניה אביי מרבה קברו ברגל עולה לו למנין שלשים או לא למנין שבעה לא מבעיא כו' אמר ליה אינו עולה ואחר כך מותבינן עליה ומסקינן ליה בתיובתא אלא אמרינן עולה מדאמר אביי מי עולה למנין שלשים שמע מיניה שמספקא ליה אי יהיו נחשבים ימי הרגל למנין הימים של שלשים דהיינו דימי הרגל יהיו תחת שאר ימים של שלשים ולא עלה על דעתו שיהיה להם מעלה יתירה שיהיו נחשבים לשבעה ימים ועל זה אמר לו רבה דאינן עולים והיינו אפילו בעד ימים אחרים לא יעלו וכל שכן שלא יהיו נחשבים לשבעה ומסקינן זה בתיובתא דלמנין שלשים עולים ולענין שיהיו נחשבים לשבעה לא מסקינן בהדיא שיהיה להם מעלה זאת ומנא לן בזה לומר לאפוקי מדרבה. ועוד ראיה מדברי ה\"ר זרחיה הלוי שכתבו בשמו בתשובת מיימון לספר שופטים סימן י\"ז לענין אם לא ידע שמת לו מת קודם החג עד אחר החג שלא נאמר דימי החג ושמיני עצרת יהיו נחשבים כל אחד לשבעה וממילא נעשית שמועה רחוקה אלא לזה אין לימי הרגל מעלה אלא נחשבים כשאר ימים וכתב שם לשון זה וכל שכן זה שלא ידע ולא שמע במות המת קודם הרגל היאך יעלה לו רגל לעשות יום א' לפני החג והחג ושמיני עצרת לכ\"א יום אם אמרו במי שהפסיק לו החג אבילותו יאמרו במי שלא ידע ושמע כו' עכ\"ל הרי שלא נתן מעלה לרגל להיות נחשב כז' אלא במפסיק אבילות ולא סגי בשמע ולא הפסיק כגון שמע ברגל דאל\"כ היה לו לומר אם אמרו במי ששמע יאמרו במי שלא שמע אלא כדפרישית ודרך כל שכן אמר כן דאם אמרו כן במי שהפסיק אבילות שבעה שלו פשיטא שלא יאמרו במלתא רחיקתא שלא ידע ולא שמע וה\"ה ששמע ברגל דלא מהני ליה להחשב לשבעה אלא שדין שלו התם קאי אלא ידע ולא שמע ורש\"ל בתשו' דלעיל כתב ועוד מאחר שהרב זרחיה הלוי כתב דכל אותן הרגלים לעולם נחשבים למנין שבעה ימים אפילו לענין שמועה רחוקה אף שלא נהג אבילות בעולם ויש מן החכמים שנסתפקו בזה כו' ואף דלא קי\"ל כהר\"ר זרחיה הלוי בזה היינו משום שלא מסתברא שיעלה למנין שבעה מי שלא שמע שמת משום הכי מסתבר להחמיר אבל במי שידע פשיטא שיעלה למנין שבעה עכ\"ל ותמוה הוא שכתב בשם הר\"ר זרחיה הלוי להקל ולא עיין בדברי ה\"ר זרחיה הלוי גופיה שהוא פוסק להחמיר כמו שהעתקתי ויותר מזה תמהתי על תשובה למהר\"ר בנימין שכתב שיש לפסוק כרש\"ל בדין זה שיש לו ראיה מדברי ה\"ר זרחיה הלוי ולא עיין אחר גוף דברי ה\"ר זרחי' הלוי וכן לא יעשה וכבר זכרנו אמתת דברי ה\"ר זרחיה הלוי שיש להוכיח איפכא וכמ\"ש וגם מו\"ח ז\"ל כתב דלא כרש\"ל בדין זה:","\u0003וכן נוהגין. \u0004יש לתמוה שבא\"ח סי' תקמ\"ח כתב רמ\"א בסעיף י' דלדידן אסור רחיצה אפילו סמוך לחשיכה ואפשר דהתם קאמר שראוי לפסוק כן אבל באמת אין נוהגין כן אלא מתירין סמוך לחשיכה. כן נראה לע\"ד ליישב דבריו:","\u0003הרי כ\"ב. \u0004קשה ליחשב שמיני עצרת כרגל בפ\"ע גם לענין ביטול ל' כיון דנתבטל ז' קודם החג והחג נחשב לשבעה הרי י\"ד כמו דאמרינן בי\"כ בסעיף י' תירץ הרא\"ש דשאני הכא שלא נהג דין ל' כלל ואע\"ג שנהג גיהוץ ותספורת מ\"מ הרי בלאו אבילות נמי אסור באלו מחמת הרגל וצ\"ע לתרץ זה אליבא דרמב\"ן דסבירא ליה דיש באבילות איסור נוסף על איסור הרגל כמוזכר לעיל סימן זה סעיף א' א\"כ קשה למה לא יבטל שמיני עצרת את שלשים כיון שכבר נהג בדין שלשים בתוספת האיסור ונראה דמ\"מ יש כאן שינוי משאר שלשים בחול דהתם יש היכר בעיקר הדין גיהוץ ותספורת משא\"כ כאן שאין היכר אלא בתוספת וזה אין הוכחה כל כך ודי בזה שנאמר שהרגל עולה למנין השלשים אבל לא לענין דליהוי כנהג מקצת שלשים ממש לענין שיבא שמיני עצרת ויבטל לגמרי שאר הל'. כנ\"ל:","\u0003וקברו בו ביום נוהג בו כו'. \u0004ברמב\"ם כאן לפני זה בבא אחרת דהיינו הקובר את מתו ברגל כו' המקומות שעושין ב' י\"ט מונה השבעה מיו\"ט שני האחרון אע\"ג שאין נוהג בו אבילות לפי שהוא מדבריהם ע\"כ עולה למנין ז' ומונה אחריו ששה בלבד והשלחן ערוך לא הזכירו כאן לפי שבאורח חיים סימן תקמ\"ח הזכירו:\n\u0003וכתוב \u0004במהרי\"ל וז\"ל יום שני של ראש השנה איני מורה שיעלה למנין שבעה ואמר שכן הוא במיימוני אבל בשאר יו\"ט מודה שעולה אע\"פ שלא מצא בהדיא היכא שקברו תוך המועד דלא הוה יו\"ט האחרון יום הקבורה שיעלה למנין ז' עכ\"ל וכ' רש\"ל ע\"ז ותימה לי הלא בהגה' מיי' חולק בזה החילוק ע\"ש עכ\"ל דהיינו מבואר שם בהגה' מיימוני בשם רב יהוד' הלכה למעשה באמו שנפטרה ביו\"ט א' של סוכות ונקברה ביו\"ט שני ולאחר סוכות נהג אבילות ו' ימים לבד ורא\"ה פסק גם הוא היכא שקברו ביו\"ט אחרון אבל קברו ברגל קודם לכן לא וזה לשונו הקובר מתו ביו\"ט אחרון או ביו\"ט שני דעצרת מונה ששה אחר הרגל דיום מיתה עולה לו מן המנין אע\"ג דלא נהיג ביה אבילות דדאורייתא היא כו' עכ\"ל ומ\"מ אין לנו אלא כפסק הש\"ע בא\"ח די\"ט ב' של גליות עולה אפילו מת ונקבר בראשון על ידי עממים וטעם שהחמיר מהרי\"ל בר\"ה לפי שהוא כיומא אריכתא עם היום הראשון וע\"כ אין סברא למנות מיום שני כל שמת ונקבר ביום הראשון דכשם שהראשון אינו עולה למנין ז' כך השני כחד יומא הם אבל אם נקבר ביום שני של ר\"ה נראה פשוט דמונה ממנו דהא עכ\"פ מדבריהם הוא כמ\"ש הטור לדעת הרמב\"ן והגאונים אין בזה עיכוב לומר דהא שייך ליום הראשון דזה ודאי דהא בכל דצריך מנין ימים ודאי מנינן ר\"ה לשני ימים רק באם הוה הקבורה ביו\"ט ראשון של ר\"ה ואז לא מנינן אותו הראשון אז גריר אבתריה גם יום השני מחמת דיומא אריכתא חשבינן ליה משא\"כ בנקבר ביום שני. כן נראה לי ברור:\n\u0003ראיתי \u0004להזכיר פה מה שראיתי במקצת מקומות כשקוברין מת ביום טוב ראשון ע\"י עממים באין ישראלים ומחזירים העפר לתוך הקבר על המת עד זיבולא בתרייתא והוא איסור גמור בעיני דהרי מלאכה גמורה היא ויש בזה משום בונה ופשיטא דאסור על ידי ישראל ע\"כ יש ליזהר בזה לעשות ע\"י עממים על כל צרה שלא תבוא:"],"\u0010g0\u0011 \u0010r0\u0011 הַקוֹבֵר מֵתוֹ קֹדֶם הָרֶגֶל, בְּעִנְיָן שֶׁחָל עָלָיו אֲבֵלוּת, וְנָהַג בּוֹ \u0010y0\u0011 \u0010c0\u0011 \u0010t0\u0011 אֲפִלוּ שָׁעָה אַחַת קֹדֶם הָרֶגֶל, מַפְסִיק הָאֲבֵלוּת וּמְבַטֵּל מִמֶּנּוּ גְזֵרַת שִׁבְעָה \u0010y1\u0011 \u0010g1\u0011 וִימֵי הָרֶגֶל עוֹלִים לוֹ לִמִנְיַן שְׁלֹשִׁים, הֲרֵי שִׁבְעָה לִפְנֵי הָרֶגֶל, וִימֵי הָרֶגֶל, וּמַשְׁלִים עֲלֵיהֶם הַשְּׁלֹשִׁים. \u0010g2\u0011 וְדַוְקָא שֶׁנָּהַג אֲבֵלוּת בְּאוֹתָהּ שָׁעָה, \u0010r1\u0011 אֲפִלוּ לֹא נָהַג אֶלָא דְּבָרִים שֶׁבְּצִנְעָא, כְּגוֹן שֶׁשָּׁמַע שְׁמוּעָה קְרוֹבָה בְּיוֹם שַׁבָּת שֶׁחָל לִהְיוֹת בְּעֶרֶב הָרֶגֶל, שֶׁאַף עַל פִּי שֶׁאֵינוֹ נוֹהֵג אֶלָא דְּבָרִים שֶׁבְּצִנְעָא, הָרֶגֶל מַפְסִיק. אָבֵל אִם שָׁגַג אוֹ הֵזִיד וְלֹא נָהַג אֲבֵלוּת, \u0005אוֹ\u0006 שֶׁהָיָה קָרוֹב לַחֲשֵׁכָה וְלֹא הָיָה יָכוֹל לִנְהֹג, אֵין הָרֶגֶל מְבַטֵּל הָאֲבֵלוּת; וְכָל שֶׁכֵּן אִם לֹא יָדַע בְּמִיתַת הַמֵּת קֹדֶם הָרֶגֶל, שֶׁאֵין הָרֶגֶל מְבַטְּלוֹ, \u0010y2\u0011 \u0010g3\u0011 \u0010r2\u0011 אֶלָא נוֹהֵג בָּרֶגֶל דְּבָרִים \u0010g4\u0011 שֶׁבְּצִנְעָא, וּמוֹנֶה שִׁבְעָה אַחַר הָרֶגֶל, וּבְאוֹתָהּ הַשִּׁבְעָה מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים, וַעֲבָדָיו וְשִׁפְחוֹתָיו עוֹשִׂים בְּצִנְעָה בְּתוֹךְ בֵּיתוֹ, דְּכֵיוָן דִּכְבָר נִתְבַּטֵּל בְּשִׁבְעַת יְמֵי הָרֶגֶל מִמְּלָאכָה, אַף עַל פִּי שֶׁלֹּא נִתְבַּטֵּל מֵחֲמַת הָאֵבֶל אֶלָא מֵחֲמַת הָרֶגֶל, סוֹף סוֹף נָהַג בְּדִין אֲבֵלוּת בְּעִנְיַן מְלָאכָה, הִלְכָּךְ אֵין לְהַחְמִיר בּוֹ כְּמוֹ בִּשְׁאָר אֲבֵלוּת וּמְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים. וְכָל יְמֵי הָרֶגֶל רַבִּים מִתְעַסְקִים בּוֹ לְנַחֲמוֹ, \u0010y3\u0011 הִלְכָּךְ אֵין מִתְעַסְקִין בּוֹ לְנַחֲמוֹ אַחַר הָרֶגֶל. וְרֶגֶל עוֹלֶה לְמִנְיַן שְׁלֹשִׁים, שֶׁהֲרֵי דִּין שְׁלֹשִׁים דְּהַיְנוּ גִהוּץ וְתִסְפֹּרֶת נוֹהֲגִים בָּרֶגֶל, \u0010c1\u0011 \u0010g5\u0011 \u0010r3\u0011 וְלֹא מִתּוֹרַת רֶגֶל בִּלְבַד אָסוּר בָּהֶם, אֶלָא אַף מִתּוֹרַת אֵבֶל, שֶׁהֲרֵי מִתּוֹרַת הָרֶגֶל \u0010t1\u0011 מֻתָּר לִלְבֹּשׁ כֵּלִים מְגֹהֲצִים חֲדָשִׁים וּלְבָנִים, \u0010y4\u0011 וְנוֹטֵל \u0010t2\u0011 צִפָּרְנָיו בְּמִסְפָּרַיִם וְשָׂמֵחַ שִׂמְחַת מְרֵעוּת, וְהַבָּא מִמְּדִינַת הַיָּם וּמִבֵּית הַשִּׁבְיָה וְהַשְּׁאָר שֶׁמָּנוּ חֲכָמִים, מֻתָּרִין לְסַפֵּר וּלְכַבֵּס, וּמִדִּין אֲבֵלוּת אָסוּר בְּכֻלָם כְּמוֹ \u0010g6\u0011 בַּחֹל.\nהַקוֹבֵר מֵתוֹ \u0010c2\u0011 בָּרֶגֶל \u0010y5\u0011 \u0010t3\u0011 בְּחֹל הַמּוֹעֵד, \u0010g7\u0011 נֹהַג דִּין אֲנִינוּת כָּל זְמַן שֶׁלֹּא נִקְבַּר; וּלְאַחַר שֶׁנִּקְבַּר, \u0010g8\u0011 נוֹהֵג דְּבָרִים שֶׁבְּצִנְעָא \u0005וּמִכָּל מָקוֹם מֻתָּר לְיַחֵד עִם אִשְׁתּוֹ (בֵּית יוֹסֵף בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ)\u0006 וְעַיֵּן לִעֵיל סִימָן שפ\"ג וּבְא\"ח סִימָן תקמ\"ח, \u0010g9\u0011 וְהָרֶגֶל עוֹלֶה לְמִנְיַן שְׁלֹשִׁים, שֶׁמַּשְׁלִים עָלָיו שְׁלֹשִׁים; \u0010r4\u0011 אֲפִלוּ קְבָרוֹ בְּחַג הַסֻכּוֹת, \u0010y6\u0011 \u0010c3\u0011 \u0010g10\u0011 לֹא אַמְרִינָן דִּשְׁמִינִי \u0010t4\u0011 עֲצֶרֶת מְבַטֵּל, \u0010g11\u0011 וּמִתְעַסְקִים בָּרֶגֶל לְנַחֲמוֹ. \u0005הַגָּה: וְכָל מְלָאכָה הַמֻּתֶּרֶת לַעֲשׂוֹת לוֹ בַּמּוֹעֵד בְּדָבָר הָאָבֵד, מֻתָּר לַעֲשׂוֹת בְּעַצְמוֹ; וְאִם אֵין דָּבָר הָאָבֵד, נַעֲשֵׂית עַל יְדֵי אֲחֵרִים בְּבָתֵּיהֶם, וַעֲבָדָיו וְשִׁפְחוֹתָיו עוֹשִׂין בְּצִנְעָא תּוֹךְ בֵּיתוֹ (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006, וּלְאַחַר הָרֶגֶל מַתְחִיל לִמְנוֹת שִׁבְעָה, וְלִכְשֶׁיִּכְלוּ שִׁבְעָה לְמִיתַת הַמֵּת אַף עַל פִּי שֶׁעֲדַיִן לֹא כָּלוּ שִׁבְעַת יְמֵי הָאֲבֵלוּת, \u0010r5\u0011 מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים \u0010r6\u0011 בְּבָתֵּיהֶם, וַעֲבָדָיו עוֹשִׂין לוֹ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ; וְאֵין רַבִּים מִתְעַסְקִים בּוֹ לְנַחֲמוֹ אַחַר הָרֶגֶל מִנְיַן הַיָּמִים שֶׁנִּחֲמוּהוּ בָּרֶגֶל, \u0010r7\u0011 אֲבָל מַרְאִים לוֹ פָּנִים, כְּגוֹן אִם קְבָרוֹ בִּשְׁלֹשָׁה יָמִים הָאַחֲרוֹנִים שֶׁל רֶגֶל, מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים בִּשְׁלֹשָׁה יָמִים אַחֲרוֹנִים שֶׁל אֵבֶל, \u0010y7\u0011 \u0010g12\u0011 וּבִמְקוֹמוֹת שֶׁעוֹשִׂים שְׁנֵי יָמִים, מוֹנֶה הַשִּׁבְעָה מִיּוֹם טוֹב \u0010t5\u0011 שֵׁנִי הָאַחֲרוֹן, הוֹאִיל וּמִדִּבְרֵיהֶם הוּא עוֹלֶה מֵהַמִּנְיָן, וּמוֹנֶה מֵאַחֲרָיו שִׁשָּׁה יָמִים בִּלְבַד. \u0010g13\u0011\nאִם קָבַר אֶת מֵתוֹ שִׁבְעָה יָמִים קֹדֶם הָרֶגֶל, וְנָהַג בָּהֶם גְזֵרַת שִׁבְעָה, הָרֶגֶל מְבַטֵּל מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים, \u0010g14\u0011 אֲפִלוּ חָל יוֹם שְׁבִיעִי בְּעֶרֶב הָרֶגֶל, דְּמִקְצָת הַיּוֹם כְּכֻלוֹ וְעוֹלֶה לְכָאן וּלְכָאן, וּמֻתָּר לְכַבֵּס \u0010y8\u0011 וְלִרְחֹץ וּלְסַפֵּר בְּעֶרֶב הָרֶגֶל. \u0005הַגָּה: \u0010y9\u0011 סָמוּךְ לַחֲשֵׁכָה (טוּר)\u0006. \u0010y10\u0011 \u0010r8\u0011 וּבְעֶרֶב \u0010t6\u0011 פֶּסַח מֻתָּר בַּכֹּל אַחַר חֲצוֹת, דְּהַיְנוּ מִזְּמַן שְׁחִיטַת הַפֶּסַח וָאֵילָךְ; וְעָדִיף שֶׁיְּגַלֵּחַ קֹדֶם חֲצוֹת, \u0010y11\u0011 הוֹאִיל וַאֲחֵרִים אֲסוּרִים לְגַלֵּחַ אַחַר חֲצוֹת \u0005(תְּשׁוּבַת ר\"י מִינְ\u0006 ץ \u0005ס\"ד)\u0006. \u0010g15\u0011 וְכֵן אִם חָל שְׁמִינִי בְּשַׁבָּת שֶׁבְּעֶרֶב הָרֶגֶל, מֻתָּר לְכַבֵּס וְלִרְחֹץ וּלְסַפֵּר בְּעֶרֶב שַׁבָּת, וְאִם לֹא גִלַח בְּעֶרֶב יוֹם טוֹב אוֹ בְּעֶרֶב שַׁבָּת, מֻתָּר לְגַלֵחַ אַחַר הָרֶגֶל, שֶׁכְּבָר נִתְבַּטֵּל מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים. אֲבָל בְּחֹל הַמּוֹעֵד לֹא יְגַלַח, כֵּיוָן שֶׁהָיָה אֶפְשָׁר לוֹ לְגַלֵחַ קֹדֶם הָרֶגֶל. וְאִם חָל שְׁבִיעִי שֶׁלוֹ בְּשַׁבַּת עֶרֶב הָרֶגֶל, אָסוּר לְגַלֵחַ בְּעֶרֶב שַׁבָּת, וּמֻתָּר לְגַלֵחַ אַחַר הָרֶגֶל, \u0010g16\u0011 וְכֵן בְּחֹל הַמּוֹעֵד, כֵּיוָן שֶׁלֹּא הָיָה יָכוֹל לְגַלֵחַ קֹדֶם הָרֶגֶל. \u0010g17\u0011 \u0010r9\u0011\nהָא דְּרֶגֶל מְבַטֵּל גְזֵרַת שְׁלֹשִׁים, בִּשְׁאָר מֵתִים. אֲבָל בְּאָבִיו וְאִמּוֹ, שֶׁאָסוּר \u0005לְסַפֵּר\u0006 \u0010y12\u0011 עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו, אֲפִלוּ פָּגַע בּוֹ הָרֶגֶל לְאַחַר ל' יוֹם, אֵינוֹ מְבַטֵּל. \u0010g18\u0011\nאִם חָל אֶחָד מִיְּמֵי הָאֲבֵלוּת, חוּץ מֵהַשְּׁבִיעִי, בְּעֶרֶב הָרֶגֶל, \u0010y13\u0011 \u0010t7\u0011 מֻתָּר לְכַבֵּס, וְלֹא יִלְבְּשֶׁנּוּ עַד הַלַיְלָה. וְטוֹב לִזָּהֵר מִלְכַבֵּס עַד אַחַר חֲצוֹת, כְּדֵי שֶׁיְּהֵא נִכָּר שֶׁמִּפְּנֵי הָרֶגֶל הוּא מְכַבֵּס. אֲבָל \u0010y14\u0011 לִרְחֹץ, אָסוּר עַד הַלַיְלָה. \u0010r10\u0011 וְיֵשׁ מַתִּירִין לִרְחֹץ אַחַר תְּפִלַת הַמִּנְחָה, סָמוּךְ \u0010y15\u0011 \u0010c4\u0011 לַחֲשֵׁכָה, \u0005וְכֵן \u0010t8\u0011 נוֹהֲגִין.\u0006 \u0010g19\u0011\nרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים חֲשׁוּבִים כִּרְגָלִים לְבַטֵּל הָאֲבֵלוּת. \u0010g20\u0011\nנָהַג שָׁעָה אַחַת לִפְנֵי הַפֶּסַח, אוֹתָהּ שָׁעָה חֲשׁוּבָה כְּז', וְח' יְמֵי הַפֶּסַח הֲרֵי ט\"ו, וּמַשְׁלִים עֲלֵיהֶם ט\"ו אֲחֵרִים. \u0010g21\u0011\nשָׁעָה אַחַת לִפְנֵי עֲצֶרֶת חֲשׁוּבָה כְּשִׁבְעָה. וַעֲצֶרֶת, כֵּיוָן שֶׁאִם לֹא הִקְרִיב קָרְבָּנוֹת עֲצֶרֶת בַּעֲצֶרֶת יֵשׁ לוֹ תַּשְׁלוּמִין כָּל שִׁבְעָה, חָשׁוּב כְּשִׁבְעָה, הֲרֵי י\"ד, וּמַשְׁלִים עֲלֵיהֶם ט\"ז אֲחֵרִים; \u0010y16\u0011 \u0010g22\u0011 וְיוֹם שֵׁנִי שֶׁל עֲצֶרֶת עוֹלֶה לְמִנְיַן הַט\"ז. \u0010g23\u0011\nשָׁעָה אַחַת לִפְנֵי רֹאשׁ הַשָּׁנָה בָּטְלָה מִמֶּנּוּ גְזֵרַת שִׁבְעָה, מִפְּנֵי \u0010g24\u0011 רֹאשׁ הַשָּׁנָה; וּגְזֵרַת ל' מְבַטֵּל מִמֶּנּוּ יוֹם כִּפּוּרִים; וּמְגַלֵחַ עֶרֶב יוֹם כִּפּוּרִים. וְהוּא הַדִּין לְקוֹבֵר מֵתוֹ בִּשְׁלֹשָׁה בְּתִשְׁרֵי, שֶׁמְגַלֵחַ בְּעֶרֶב \u0010g25\u0011 יוֹם הַכִּפּוּרִים.\nשָׁעָה אַחַת לִפְנֵי יוֹם הַכִּפּוּרִים בְּטֵלָה מִמֶּנּוּ גְזֵרַת ז' מִפְּנֵי יוֹם כִּפּוּרִים, וּגְזֵרַת ל' מְבַטֵּל מִמֶּנּוּ הֶחָג, וּמְגַלֵחַ בְּעֶרֶב הֶחָג. \u0010g26\u0011\nשָׁעָה אַחַת לִפְנָי הֶחָג וְהֶחָג, הֲרֵי י\"ד; וּשְׁמִינִי עֲצֶרֶת שִׁבְעָה, הֲרֵי כ\"א; \u0010g27\u0011 וְיוֹם שֵׁנִי שֶׁל שְׁמִינִי עֲצֶרֶת, \u0010c5\u0011 הֲרֵי \u0010t9\u0011 כ\"ב; וּמַשְׁלִים עֲלֵיהֶם ח' אֲחֵרִים. \u0010g28\u0011 \u0010r11\u0011\nהַקוֹבֵר אֶת מֵתוֹ שָׁעָה אַחַת לִפְנֵי הָרֶגֶל, אוֹתָהּ שָׁעָה וְהָרֶגֶל חֲשׁוּבִים כְּי\"ד, וּמִיָּד אַחַר הָרֶגֶל יֵשׁ לוֹ דִּין שָׁבוּעַ שְׁלִישִׁי \u0010y17\u0011 לְעִנְיָן שֶׁיּוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר. \u0010g29\u0011 \u0010r12\u0011\nבִּמְקוֹמוֹת שֶׁעוֹשִׂין שְׁנֵי יוֹם טוֹב, מִי שֶׁמֵּת לוֹ מֵת בְּיוֹם טוֹב שֵׁנִי שֶׁהוּא יוֹם טוֹב הָאַחֲרוֹן שֶׁל פֶּסַח אוֹ שֶׁל חַג, אוֹ בְּיוֹם טוֹב שֵׁנִי שֶׁל עֲצֶרֶת, \u0010c6\u0011 וּקְבָרוֹ בּוֹ בַּיּוֹם, נוֹהֵג בּוֹ אֲבֵלוּת, הוֹאִיל וְיוֹם טוֹב שֵׁנִי מִדִּבְרֵיהֶם, וַאֲבֵלוּת יוֹם רִאשׁוֹן שֶׁהוּא יוֹם מִיתָה וּקְבוּרָה שֶׁל תּוֹרָה, יִדָּחֶה עֲשֵׂה שֶׁל דִּבְרֵיהֶם מִפְּנֵי עֲשֵׂה שֶׁל תּוֹרָה. \u0010g30\u0011 \u0010r13\u0011 אֲבָל אִם מֵת בְּיוֹם טוֹב שֵׁנִי שֶׁל רֹאשׁ הַשָּׁנָה, וְקָבְרוּ בּוֹ בַּיּוֹם, אֵינוֹ נוֹהֵג בּוֹ אֲבֵלוּת, שֶׁשְּׁנֵי הַיָּמִים כְּיוֹם אָרֹךְ הֵם. \u0010g31\u0011 \u0010r14\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, בְּשִׁבְעָה מֵתִים הַמְּפֹרָשִׁים בַּתּוֹרָה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, אֲבָל אוֹתָם שֶׁהוֹסִיפוּ עֲלֵיהֶם כִּדְאִיתָא בְּסִימָן שע\"ד, אֵין אֲבֵלוּתָם אֶלָא מִדְּרַבָּנָן, לְפִיכָךְ אֵינוֹ נוֹהֵג עֲלֵיהֶם אֲבֵלוּת בְּשׁוּם יוֹם טוֹב. \u0010r15\u0011 וַאֲפִלוּ בְּאוֹתָם שֶׁאָמַרְנוּ שֶׁנּוֹהֵג אֲבֵלוּת בְּיוֹם טוֹב שֵׁנִי, אֵינוֹ קוֹרֵעַ. \u0010g32\u0011 וְהָעוֹלָם נוֹהֲגִין שֶׁלֹּא לְהִתְאַבֵּל בְּיוֹם טוֹב שֵׁנִי שֶׁל גָלֻיּוֹת עַל שׁוּם מֵת, אֲפִלוּ הוּא יוֹם מִיתָה וּקְבוּרָה. \u0005הַגָּה: דְּסוֹבְרִין כְּדַעַת הָאוֹמְרִים שֶׁאֵין שׁוּם אֲבֵלוּת דְּאוֹרַיְתָא, וְכֵן הַמִּנְהָג פָּשׁוּט, וְאֵין לְשַׁנּוֹת (ר\"ת וְר\"י וְרֹא\"שׁ)\u0006. \u0010g33\u0011\nמֵת לוֹ מֵת בְּעֶרֶב יוֹם טוֹב, וְנִתְיָרֵא שֶׁמָּא לֹא יַסְפִּיק לְקָבְרוֹ מִבְּעוֹד יוֹם, \u0010t10\u0011 וּמְסָרוֹ לְעוֹבְדֵי כּוֹכָבִים שֶׁיּוֹלִיכוּהוּ לְקָבְרוֹ, כֵּיוָן שֶׁהוֹצִיאוּהוּ מֵהָעִיר וְנִתְכַּסָה מֵעֵינֵי הַקְרוֹבִים \u0010y18\u0011 חָלָה עָלָיו אֲבֵלוּת; וְאִם הוּא שָׁעָה אַחַת קֹדֶם הָרֶגֶל, וְנָהַג בּוֹ אֲבֵלוּת, בָּטְלָה לָהּ גְזֵרַת שִׁבְעָה אַף עַל פִּי שֶׁנִּקְבַּר בְּיוֹם טוֹב.",{"g":["\u0003לשון הטור ממשנה מ\"ק דף י\"ט ע\"א וברייתא שם דף כ' ע\"א וכחכמים:\u0004 ","\u0003בעיא שם דף י\"ט ע\"ב ונפשטא דעולין בדף כ' ע\"א ומימרא דאמוראי שם:\u0004 ","\u0003כן דקדק הראב\"ד מדקתני קיים כפיית המטה וכו'\u0004 וציינתיו ג\"כ לעיל סימן שצ\"ו:","מהא דאמר רבי יוחנן דברים שבצנעא נוהג כתובות דף ד' ע\"א וכדעת הרמב\"ן וכ\"פ התוס' והרא\"ש שם בכתובות וכתבו שכן פסק בה\"ג:","\u0003שם בברייתא במ\"ק דף כ' ע\"א:\u0004 ","\u0003שם בשם הרמב\"ן בסת\"ה מדקאמר בגמ' כי קא מבעיא ליה למנין ל' דקא נהגא וכו'\u0004 שם די\"ט ע\"ב:\n(°) עיין בא\"ח סימן תקל\"ב בהג\"ה שיש נוהגין להחמיר וכן נוהגין:","שם:","עיין בסי' שמ\"א בסוף סעיף א' דאם רוצה לקברו בי\"ט נוהג בו ג\"כ דין אנינות וכ\"ש ביום טוב ב':","\u0003כמימרא דרבי יוחנן וציינתיו בסעיף דלעיל:\u0004 ","\u0003ציינתיו לעיל סעיף קטן ב':\u0004 ","\u0003כמימרא דרבינא מ\"ק דף כ\"ד ע\"ב:\u0004 ","ברייתא שם דף כ' ע\"א:\n(°) פי' שמבקרין אותו כל ימי אבלו והוא מירושלמי:","\u0003שם מדברי אביו הרא\"ש שם בפסקיו וכ\"כ רבינו ירוחם:\u0004 ","\u0003ברייתא שם דף י\"ט ע\"ב:\u0004 ","\u0003שם וכאבא שאול דאיפסקא הלכתא שם בגמ' כוותיה:\u0004 ","\u0003שם גם אליבא דחכמים:\u0004 ","\u0003ברייתא וכדמפרש לה בגמרא שם דף י\"ז ע\"ב:\u0004 ","\u0003לשון הטור מדברי אביו הרא\"ש מהא דתניא דעל אביו ואמו אינו נכנס וכו'\u0004 שם דף כ\"ב ע\"א וכ\"כ בירושלמי וכ\"כ הרמב\"ם בפרק י\"א:","ציינתיו בא\"ח סימן תקמ\"ח סעיף י':\n(°) עיין שם בהג\"ה ששם פסק שהוא אסור לדידן דנוהגים איסור רחיצה כל ל':","\u0003משנה מ\"ק דף י\"ט ע\"ב וכרשב\"ג דאיפסקא הלכתא כוותיה דף כ\"ד ע\"א:\u0004 ","\u0003ממימרא דאמוראי שם ע\"ב:\u0004 ","שם:","\u0003ציינתיו לעיל סוף סעיף ב':\u0004 ","\u0003שם בגמ' אדבריה רב פפא לרב אויא סבא וכו':\u0004 ","\u0003רא\"ש בשם הרז\"ה והרמב\"ן ז\"ל וכ\"כ הגהמי\"י שלזה הסכים הר\"מ וכ\"כ הגה\"א בשם א\"ז:\u0004 ","\u0003שם ושם:\u0004 ","\u0003מימרא דרבינא שם דף כ\"ד ע\"ב:\u0004 ","\u0003מדברי הרא\"ש ורבינו ירוחם וכמ\"ש לעיל:\u0004 ","\u0003טור בשם ה\"ר שמשון וכ\"כ אביו הרא\"ש והגמ\"יי בפרק י' בשמו:\u0004 ","\u0003שם בשם בה\"ג הלכה למעשה:\u0004 ","\u0003שם בשם הרמב\"ן בשם י\"א ושזו היא דעת הרמב\"ם בס\"פ עשירי מהלכות אבל ודעת הגאונים:\u0004 ","\u0003שם בשם הרמב\"ן לדעת הגאונים:\u0004 ","\u0003כדעת הרא\"ש בפסקיו בשם חכמים אחרונים וכ' שראיותיהן ברורות וחזקות ולא תזוז מינה:\u0004 ","נתבאר במ\"ש בסימן שע\"ה סעיף ב' (בשם רמב\"ן בשם ב\"ה):"],"t":["\u0003שעה. \u0004 פי' כל שהוא ולא בעינן שעה זמנית ואפילו חליצת מנעל לחוד שנהג מעט די בכך. וכ\"כ בתשו' מ\"ב. ט\"ז וש\"ך:","\u0003ללבוש. \u0004 כ' בתשו' מ\"ב שמעשה היה בחתן שנשא ערב הרגל ובתוך הרגל מת לו מת ופסק דאע\"ג דחתן דעלמא שאירע לו אבילות בתוך ז' ימי המשתה אינו מונה שלשים אלא אחר ימי המשתה מטעם דהוא עדיף מרגל דאיהו מותר בגיהוץ ותספורת משא\"כ חתן זה דימי משתה שלו הם ברגל ממילא אסור בגיהוץ וכו' מחמת הרגל הלכך עולה לו למנין שלשים וכתב הט\"ז דבעיניו יפלא מאד דברים הללו דע\"כ לא אמרו דעולה אלא כשיש איסור מחמת אבילותו אלא שאותו האיסור הוא גם כן מחמת הרגל בזה שייך שפיר דעולה כיון דעכ\"פ הוא נוהג איסור ויכול לומר אני נוהג האיסור מחמת האבילות. משא\"כ בחתן זה שאין בו חיוב אבילות כלל וזה שנוהג איסור הוא מחמת הרגל לחוד היאך יעלה על הדעת לומר שיהיה זה נחשב לימי השלשים. ע\"כ נראה דליתא להאי דינא אלא דימי הרגל אינם עולים לו כלל כמו בשאר חתן וכו' ע\"ש. והאי דימי הרגל עולים למנין שלשים שכתב המחבר כתב הש\"ך דהיינו אף בנודע לו מיתת המת ברגל אע\"פ שלא נודע לו קודם הרגל ודלא כמ\"ש בב\"י דבנודע לו קודם הרגל דוקא הוא דעולה ואולי גם הב\"י לאו דוקא קאמר או ט\"ס הוא וצ\"ל ברגל עכ\"ל:","\u0003צפרניו. \u0004 היינו לדעת המחבר בא\"ח סי' תקל\"ב אבל אנן קי\"ל להחמיר כמ\"ש הר\"ב שם וסתם כאן הדברים לפי שאין כאן מקום דיני מועד. ש\"ך:","\u0003המועד. \u0004 ה\"ה ביו\"ט שני או בי\"ט ראשון כשרוצה לקברו ע\"י עממים חל עליו אנינות כדלעיל סי' שמ\"א ס\"א ולאחר שיקבר כל אלו הדינים נוהגים בו עכ\"ל הש\"ך:","\u0003עצרת. \u0004 כתב הש\"ך ואין ש\"ע עולה רק ליום א' כשקברו ברגל ודוקא כשקברו קודם חג הסכות הוא דעולה ש\"ע ג\"כ לז' ימים \u0005(ועי' לקמן סעיף י\"א)\u0006 משא\"כ הכא. ודלא כמהרש\"ל בתשו' שכ' דמבטל הוא דאינו מבטל אבל למנין ז' לענין הל' עולה ש\"ע אפילו קברו ברגל. מיהו בתשובת משאת בנימין פסק כמהרש\"ל וכן נראה דעת הדרישה עכ\"ל. גם הט\"ז מאריך בראיות לסתור דברי מהרש\"ל ותשובת מ\"ב הנ\"ל ע\"ש:","\u0003שני. \u0004 כ' הב\"ח וה\"ה אם מת ביו\"ט ראשון של ר\"ה מונה השבעה מיו\"ט הב' דהוי ג\"כ מדבריהם. ע\"ש בס\"ס זה \u0005(וכ\"כ בתשו' גינת ורדים כלל ה' וכ\"כ בתשו' תורת חיים סי' י\"א)\u0006:","\u0003פסח. \u0004 כתב הש\"ך דדין זה הוציא הרב מתשו' מהר\"י מינץ וצ\"ע דאדרבה משם משמע דלענין כבוס ורחיצה ע\"פ שוה לשאר עיו\"ט דלא הותר רק סמוך לחשכה אך שכתב שם דבע\"פ יש לגלח קודם חצות הואיל ואחרים ג\"כ אסורים לגלח אחר חצות מפני שהוא זמן שחיטת הפסח וכמ\"ש בא\"ח סי' תקמ\"ח ע\"ש וצ\"ע. עכ\"ל:","\u0003לכבס. \u0004 דכבר בטל ממנו גזירת ז' אבל לספר אסור דלא נתבטל ממנו גזירת ל' כיון דאין כאן ז' ימים קודם הרגל. ש\"ך:","\u0003נוהגין. \u0004 וכתב בת\"ה דאפילו מת לו מת בע\"ש ואותו שבת הוא ערב הרגל מותר לרחוץ בע\"ש לפי מנהגינו. וא\"ל היאך כתב הרב וכן נוהגין הא לעיל ר\"ס שפ\"א כ' דאנן נהגינן איסור רחיצה כל ל' וכן בר\"ס שפ\"ט כתב דנהגינן איסור כביסה כל ל' י\"ל דאינו אלא חומרא ומדינא שרי והכא משום כבוד הרגל לא נהגו להחמיר וכ\"כ הלבוש ואע\"ג דבא\"ח סי' תקמ\"ח ס\"ח וס\"י כתב הרב דלדידן דנוהגים איסור רחיצה כל ל' אסור לרחוץ דהא הרגל לא בטל ממנו רק גזירת ז' וה\"ה לענין כבוס במקום דנוהגין איסור כבוס כל ל' ע\"כ היינו משום דכך ראוי להורות אי הוי איסור רחיצה וכבוס כל ל' מן הדין אבל כאן כתב דמ\"מ המנהג אינו כן וכ\"כ הב\"ח אלא דצריך ליישב לאיזה צורך כתב הרב שם כן כיון דס\"ס המנהג אינו כך. ונ\"ל דס\"ל דהא דמנהג אינו כן היינו משום כבוד הרגל והלכך היכא דליכא משום כבוד הרגל אסור ונ\"מ דלאחר הרגל אסור רחיצה וכביסה עד ל' דהרגל לא ביטל ממנו רק גזרת ז' ודוק עכ\"ל הש\"ך:","\u0003כ\"ב. \u0004 כתב הט\"ז קשה ליחשב ש\"ע כרגל בפני עצמו גם לענין ביטול שלשים כיון דנתבטל השבעה קודם החג והחג נחשב לשבעה הרי י\"ד כמו דאמרי' בי\"כ בס\"י. תירץ הרא\"ש דשאני הכא שלא נהג דין ל' כלל ואע\"ג שנהג גיהוץ ותספורת מ\"מ הרי בלאו אבילות נמי אסור באלו מחמת הרגל וצ\"ע לתרץ זה אליבא דהרמב\"ן דס\"ל דיש באבלות איסור נוסף על איסור הרגל א\"כ קשה למה לא יבטל ש\"ע גזרת ל' כיון שכבר נהג בדין ל' בתוספת האיסור. ונראה דמ\"מ יש שינוי משאר ל' בחול דהתם יש היכר בעיקר דין גיהוץ ותספורת משא\"כ כאן שאין היכר אלא בתוספת וזה אין הוכחה כ\"כ לכך די בזה שנאמר הרגל עולה למנין הל' אבל לא להיות כנהג מקצת שלשים ממש לענין שש\"ע יבטל לגמרי שאר הל' עכ\"ל:","\u0003ומסרו. \u0004 כתב הט\"ז ראיתי להזכיר פה מה שראיתי בקצת מקומות כשקוברין מת ביו\"ט ראשון ע\"י עממים באים ישראלים ומחזירים העפר לתוך הקבר על המת עד זיבולא בתרייתא והוא איסור גמור בעיני דהרי מלאכה גמורה היא ויש בזה משום בונה ופשיטא דאסור ע\"י ישראל. ע\"כ יש ליזהר בזה לעשות ע\"י עובדי כוכבים על כל צרה שלא תבוא עכ\"ל:"],"r":["\u0003הקובר כו'. \u0004עבא\"ח סי' תקמ\"ח ומש\"ש:","\u0003אפי' לא נהג כו'. \u0004טור. דהא עולה לו למנין ז' כמש\"ל סי' ת\"ב ס\"ז ובא\"ח שם:","\u0003אלא נוהג ברגל כו'. \u0004דהוי כמו קברו ברגל וכמ\"ש בא\"ח שם וכמש\"ש בגמרא הקובר את מתו ב' ימים קודם הרגל כו' לת\"ק:\n\u0003(ליקוט) אלא נוהג ברגל כו'. \u0004כמ\"ש בכתובות ד' א' ודלא כהרמב\"ם פ\"י שכתב דאינו נוהג כלל ברגל ונראה שגרס שם שבת במקום מועד וכמ\"ש במ\"ק כ\"ד א' הכי אר\"י כו' אבל ממקומו הוא מוכרע דהא חופה מדמינן לרגל ועתוס' שם ד\"ה מסייע כו' וכ\"ה בתוספתא \u0005(פ\"ב) \u0006אין אבל רשאי להתאבל בתוך המועד אבל נוהג בצנעה בתוך ביתו וכן בא\"ר \u0005(פ\"ז) \u0006אבל במועד כאלו שאינו אבל ונוהג בצנעה ובירושלמי על מתני' שבת עולה כו' רגלים מפסיקים כו' ואמר שם הטעם א\"ר סימון בשם ר\"י שהוא מותר בתשמיש המטה ר\"ל ברגל משא\"כ בשבת כו' ופריך והלא אמרו אין אבל ברגל אלא שהוא נוהג בצנעא מהו בצנעא שהוא אסור בתשמיש המטה כו' אלא אר\"א אפשר לשבעה בלא רגל ואי אפשר לשבעה בלא שבת ועבתה\"א \u0005(ובמלחמות סוף מ\"ק. ועבריטב\"א דמ\"ק כ\"ג ב') \u0006(ע\"כ):","\u0003ולא מתורת כו'. \u0004עבה\"ג ודלא כרש\"י שם ד\"ה דהא נהגא כו' דאם כדברי רש\"י מצות ז' נמי תעלה שהרי נוהג דברים שבצנעה ורבים מתעסקים בו אלא ע\"כ צ\"ל דנהגא כו' כל מצות ל' קאמר דאינו אסור דברים שבפרהסיא אלא דוקא דברים שבתוך ז' וכ\"כ מהרי\"ו וע\"ל ר\"ס ת' בהג\"ה מש\"ש ובש\"ך שם ס\"ק ב' \u0005(ובתה\"א ובמלחמות כתב וטעמא דמילתא מפני שהן מצות לא תעשה ומדין הרגל נמי נוהג בהן במקצתן הלכך כשנוהג בכולן באבלותו אין אבלותו מתפרסמת עליו. משמע דוקא דבר שהוא בשב ואל תעשה דלא כמהרי\"ו): \u0006\n\u0003(ליקוט) ולא מתורת כו'. \u0004ותדע שהרי אף מקצת שבעה נוהגת בו שאינו מכבס כסותו והרבים מתעסקים עמו אלא כיון דלא נהיג כדינו אינו עולה. ע\"ש \u0005(בתה\"א וכ\"כ במלחמות סוף מ\"ק) \u0006(ע\"כ):","\u0003אפילו קברו בחג הסוכות כו'. \u0004דאפילו קודם לרגל אינו מבטל ש\"ע כמש\"ל סי\"א וכ\"ש זה שלא נהג כלל קודם וכנ\"ל ס\"א וע\"ל סי' ת\"ב ס\"ח ועברא\"ש סי' ע\"ה והר\"ז הלוי כו' והרמב\"ן כו' וא\"ת א\"כ בחג נמי כו' ובתוס' כ\"ד ב' ד\"ה דר\"א כו' ובסמוך פי' בענין זה כו':","\u0003(ליקוט) מלאכתו נעשית כו'. \u0004תוס' שם ד\"ה שלשה כו':","\u0003בבתיהם. \u0004דלא כתוס' שם \u0005(י\"ט ב') \u0006ד\"ה ומלאכתו כו' (ע\"כ):","\u0003(ליקוט) אבל מדאין לו פנים כו'. \u0004ירושלמי פ\"ג הקובר את מתו ג' ימים בתוך הרגל מונה ז' לאחר הרגל ג' ימים הראשונים הרבים מתעסקין עמו ד' ימים האחרונים אין הרבים מתעסקים עמו מהו להראות לו פנים ר' יעקב ב\"ר אידי בשם ר' חנינא והלא אמרו אין אבל בשבת מפני מה אמרו להראות לו פנים לא מפני הכבוד וה\"נ מפני הכבוד. ב\"י \u0005(ע\"כ):\u0006","\u0003ובע\"ש כו'. \u0004נראה דחשיב כמו מועד דקרא חשבו בתוך המועדים וכן מדמי בגמרא פ\"ד דפסחים \u0005(נ\"ה ב') \u0006ובפ\"ב דמ\"ק:","\u0003(ליקוט) הא דרגל כו'. \u0004תוס' כ\"ב ב' ד\"ה עד כו' (ע\"כ):","\u0003(ליקוט) ויש מתירין כו'. \u0004עתוס' י\"ט ב' ד\"ה שאסור. והרי\"ט כו' וע\"ש כ\"ג א' ד\"ה ואמר. וריב\"א כו' ומיהו כו' (ע\"כ):","\u0003הקובר כו'. \u0004כן תי' ר\"ש מש\"ש כ\"ד ב' יום א' לפני ר\"ה כו' ועתוס' שם ד\"ה דר\"א כו' ויותר היה י\"ל לענין כו' ורא\"ש סי' ע\"ה ע\"ש:","\u0003(ליקוט) במקומות כו'. \u0004עתוס' דמ\"ק כ\"ד ב' סד\"ה דר\"א כו' (ע\"כ):","\u0003אבל אם מת בי\"ט שני של ר\"ה כו'. \u0004כמ\"ש בפ\"א די\"ט \u0005(ה' ו'):\u0006","\u0003(ליקוט) בד\"א בז' כו'. \u0004דלא כהרמב\"ם שכתב דאשתו אינה אלא מד\"ס והא שמטמא לה דעשאוה כמת מצוה דביבמות פ\"ט ב' לא אמרו כן אלא באשתו קטנה. תה\"א והמחלוקת של גאונים ותוס' ע\"ש באריכות שיישב כל הקושיות של תוס' ע\"ש (ע\"כ):","\u0003ואפילו כו'. \u0004וכנ\"ל סימן ש\"מ סל\"א וכמש\"ש דלא אמרינן י\"ט שני כחול אלא לענין צרכיו של מת דוקא:"]}],["שַׁבָּת אֵינוֹ מַפְסִיק אֲבֵלוּת וְעוֹלֶה לְמִנְיַן שִׁבְעָה, שֶׁהֲרֵי קְצָת דִּינֵי אֲבֵלוּת נוֹהֲגִים בּוֹ, דְּהַיְנוּ דְּבָרִים שֶׁבְּצִנְעָא שֶׁהֵם: תַּשְׁמִישׁ הַמִּטָּה וּרְחִיצָה. \u0010y0\u0011 אֲבָל דְּבָרִים שֶׁבְּפַרְהֶסְיָא \u0005לֹא,\u0006 דְּהַיְנוּ לְהָסִיר עֲטִיפָתוֹ, \u0010y1\u0011 \u0005וְדַוְקָא כְּשֶׁהוּא מְעֻטָּף עֲטִיפוֹת יִשְׁמְעֵאלִים כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שפ\"ו, אֲבָל קְצָת עֲטִיפָה שֶׁנּוֹהֲגִים בִּקְצָת מְקוֹמוֹת כָּל ל', אֵין צָרִיךְ לְהָסִיר בְּשַׁבָּת, הוֹאִיל וְיֵשׁ לוֹ מִנְעָלִים בְּרַגְלָיו (מהרי\"ו סִימָן ה')\u0006, וְלִלְבֹּשׁ מִנְעָלָיו, וְלִזְקֹף הַמִּטָּה מִכְּפִיָּתָהּ, וְשֶׁלֹּא לִלְבֹּשׁ בֶּגֶד קָרוּעַ, אֶלָא מַחֲלִיפוֹ, וְאִם אֵין לוֹ לְהַחֲלִיף \u0010y2\u0011 מַחֲזִיר קִרְעוֹ לְאַחֲרָיו; וְתַלְמוּד תּוֹרָה הָוֵי דָּבָר \u0010y3\u0011 \u0010c0\u0011 שֶׁבְּצִנְעָא, אֲבָל לַחֲזֹר הַפָּרָשָׁה, כֵּיוָן שֶׁחַיָּב אָדָם לְהַשְׁלִים פָּרָשִׁיּוֹתָיו עִם הַצִּבּוּר, הָוֵי כְּקוֹרֵא אֶת שְׁמַע וּמֻתָּר. וְאִם קָרְאוּ אֶת הָאָבֵל לַעֲלוֹת לַתּוֹרָה, צָרִיךְ לַעֲלוֹת, שֶׁאִם הָיָה נִמְנָע הָיָה דָּבָר שֶׁל פַּרְהֶסְיָא; וְרַבֵּנוּ תָּם הָיוּ קוֹרִים אוֹתוֹ בְּכָל פַּעַם שְׁלִישִׁי, וְאֵרַע בּוֹ אֲבֵלוּת וְלֹא קְרָאוֹ הַחַזָּן, וְעָלָה הוּא מֵעַצְמוֹ וְאָמַר כֵּיוָן שֶׁהֻרְגַל לִקְרוֹתוֹ שְׁלִישִׁי בְּכָל שַׁבָּת, הָרוֹאָה שֶׁאֵינוֹ עוֹלֶה אוֹמֵר שֶׁבִּשְׁבִיל אֲבֵלוּת הוּא נִמְנָע, וְהָוֵי דְּבָרִים שֶׁל פַּרְהֶסְיָא. \u0005וְכֵן אִם הַכֹּהֵן אָבֵל וְאֵין כֹּהֵן אַחֵר בְּבֵית הַכְּנֶסֶת, מֻתָּר לִקְרוֹתוֹ; אֲבָל בְּעִנְיָן אַחֵר, אָסוּר (הַגָּהוֹת מַיְמוֹנִי פ\"ג מה\"א)\u0006.\nגְרָרַתּוּ חַיָּה אוֹ הֲרָגוּהוּ לִסְטִים, \u0010y4\u0011 \u0010y5\u0011 וּבְשַׁבָּת נִתְיָאֵשׁ מִלְבַקֵשׁ, כֵּיוָן דִּדְבָרִים שֶׁבְּצִנְעָא נוֹהֵג בְּשַׁבָּת עוֹלֶה לוֹ לְיוֹם אֶחָד. \u0005הַגָּה: אִם פָּגַע יוֹם ל' שֶׁל אֲבֵלוּת בְּשַׁבָּת וְיוֹם כ\"ט בְּעֶרֶב שַׁבָּת, מֻתָּר לוֹ לִרְחֹץ בְּעֶרֶב שַׁבָּת, אַף בִּמְקוֹמוֹת שֶׁנּוֹהֲגִין שֶׁלֹּא לִרְחֹץ כָּל שְׁלֹשִׁים, דְּהוֹאִיל וּמִדִּינָא שָׁרֵי לְאַחַר שִׁבְעָה, אֶלָּא שֶׁנָּהֲגוּ לְהַחְמִיר כָּל ל', בִּכְהַאי גַּוְנָא שָׁרֵי מִשּׁוּם כְּבוֹד שַׁבָּת (הַגָּהוֹת מַיְמוֹנִי בְּשֵׁם מַהֲרַ\"ם פ\"י ופ\"ו דְּיוֹם טוֹב)\u0006. וְהוּא הַדִּין כָּל כַּיּוֹצֵא בָּזֶה, כְּגוֹן לַחֲזֹר עַל מְקוֹמוֹ בְּלֵיל שַׁבָּת וְלִלְבֹּשׁ בִּגְדֵי שַׁבָּת, דְּהָא נָמִי אֵינוֹ אֶלָּא מִנְהָג בְּעָלְמָא \u0005(כֵּן נִרְאֶה מִדִּבְרֵי מַהַרַ\"שׁ)\u0006, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִי' שפ\"ט וש\"צ; וְאַף עַל פִּי שֶׁיֵּשׁ לְחַלֵּק בֵּין רְחִיצָה שֶׁאֲסוּרָה בְּשַׁבָּת וּבֵין דְּבָרִים אֵלּוּ שֶׁאֶפְשָׁר לוֹ לַעֲשׂוֹת בְּשַׁבָּת, מִכָּל מָקוֹם אֵין נ\"ל לְחַלֵּק בְּכָךְ.",["\u0003אבל דברים שבפרהסיא. \u0004דהיינו להסיר עטיפתו אינו נוהג וצריך ללבוש מנעליו ולזקוף המטה. כו' כן ראוי להיות:","\u0003ודוקא כו' הואיל ויש לו מנעלים ברגליו. \u0004לא ידעתי מה ענין מנעלים ברגליו לכאן דמאן דמתיר משום מנעלים ברגליו מתיר אפי' בעטיפת ישמעאלי' כדמשמע בש\"ס ורמב\"ן ובאמת במהרי\"ו כ' דהכא מותר מטעם כיון שנוהגים בעטיפה זו גם אחר ז' ימי אבילות דלא אסרינן דבר שבפרהסיא אלא מה שאינו רק תוך ז' ואח\"כ כתב דמותר ג\"כ מטעם דמנעלים ברגליו עיין שם ובעט\"ז השמיט האי סיומא דהואיל ויש לו מנעלים ברגליו:","הב\"ח בס\"ס שפ\"ו דמהרי\"ו מיירי באותה עטיפה שהוא לבוש שקורין קאפ\"א לפי מה ששמעתי שנוהגים להתעסק בה כל ל' אבל לשום הכובע לפני העינים שנוהגים במלכותינו כל ז' בלחוד דזהו נקרא עטיפה לדידן הוי פרהסיא בשבת אם לא יגביה הכובע כדרך כל אדם הילכך מיד שמתחיל הש\"ץ ברכו חייב להגביה הכובע ע\"כ:","\u0003מחזיר קרעו לאחריו. \u0004והאידנא לא נהגו לדקדק בזה ואפשר דמנעלים מוכיחים עליהן וכמ\"ש הגהמ\"י ומביאה בית יוסף דהיכא דמנעלים ברגליו אין צריך לחזרת קרע עיין שם:","\u0003אבל לחזור הפרשה כו'. \u0004כתוב בדרישה בשם מהרש\"ל דה\"ה לחזור שנים מקרא ואחד תרגום מותר ע\"ש:","\u0003ובשבת נתייאש לבקשו כו'. \u0004דכיון דנתייאשו לבקשו הוי ליה כנקבר כדלעיל סימן שע\"ה סעיף ז' ושבת עולה אפילו בתחלת המנין כדלקמן סימן ת\"ב ס\"ז:"],["\u0003אבל לחזור הפרשה. \u0004ובאגודה כתב ונראה לאיסור וכ' רש\"ל להכריע דבחול אסור ובשבת שרי שהוא זמנו והוא מחובת היום עד כאן לשונו. וכתב רש\"ל בתשובה סימן ע\"א דאבל שיום מילת בנו בשבת אין לו לעלות לתורה אע\"פ שנהגו בקצת מקומות שאבי הבן הוי חיוב לעלות ביום מילת בנו מכ\"מ לא מקרי פרהסיא:"],"\u0010g0\u0011 שַׁבָּת אֵינוֹ מַפְסִיק אֲבֵלוּת וְעוֹלֶה לְמִנְיַן שִׁבְעָה, \u0010r0\u0011 שֶׁהֲרֵי קְצָת דִּינֵי אֲבֵלוּת נוֹהֲגִים בּוֹ, דְּהַיְנוּ דְּבָרִים שֶׁבְּצִנְעָא שֶׁהֵם: תַּשְׁמִישׁ הַמִּטָּה וּרְחִיצָה. \u0010y0\u0011 אֲבָל דְּבָרִים שֶׁבְּפַרְהֶסְיָא \u0005לֹא,\u0006 \u0010g1\u0011 \u0010r1\u0011 דְּהַיְנוּ לְהָסִיר עֲטִיפָתוֹ, \u0010y1\u0011 \u0010r2\u0011 \u0005וְדַוְקָא כְּשֶׁהוּא מְעֻטָּף עֲטִיפוֹת יִשְׁמְעֵאלִים כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שפ\"ו, אֲבָל קְצָת עֲטִיפָה שֶׁנּוֹהֲגִים בִּקְצָת מְקוֹמוֹת כָּל ל', אֵין צָרִיךְ לְהָסִיר בְּשַׁבָּת, הוֹאִיל וְיֵשׁ לוֹ \u0010t0\u0011 מִנְעָלִים בְּרַגְלָיו (מהרי\"ו סִימָן ה')\u0006, \u0010g2\u0011 \u0010r3\u0011 וְלִלְבֹּשׁ מִנְעָלָיו, \u0010g3\u0011 וְלִזְקֹף הַמִּטָּה מִכְּפִיָּתָהּ, וְשֶׁלֹּא לִלְבֹּשׁ בֶּגֶד קָרוּעַ, אֶלָא מַחֲלִיפוֹ, וְאִם אֵין לוֹ לְהַחֲלִיף \u0010y2\u0011 \u0010t1\u0011 מַחֲזִיר קִרְעוֹ לְאַחֲרָיו; \u0010g4\u0011 וְתַלְמוּד תּוֹרָה הָוֵי דָּבָר \u0010y3\u0011 \u0010c0\u0011 שֶׁבְּצִנְעָא, אֲבָל \u0010t2\u0011 לַחֲזֹר הַפָּרָשָׁה, כֵּיוָן שֶׁחַיָּב אָדָם לְהַשְׁלִים פָּרָשִׁיּוֹתָיו עִם הַצִּבּוּר, הָוֵי כְּקוֹרֵא אֶת שְׁמַע וּמֻתָּר. וְאִם קָרְאוּ אֶת הָאָבֵל לַעֲלוֹת לַתּוֹרָה, צָרִיךְ לַעֲלוֹת, שֶׁאִם הָיָה נִמְנָע הָיָה דָּבָר שֶׁל פַּרְהֶסְיָא; וְרַבֵּנוּ תָּם הָיוּ קוֹרִים אוֹתוֹ בְּכָל פַּעַם שְׁלִישִׁי, וְאֵרַע בּוֹ אֲבֵלוּת וְלֹא קְרָאוֹ הַחַזָּן, וְעָלָה הוּא מֵעַצְמוֹ וְאָמַר כֵּיוָן שֶׁהֻרְגַל לִקְרוֹתוֹ שְׁלִישִׁי בְּכָל שַׁבָּת, הָרוֹאָה שֶׁאֵינוֹ עוֹלֶה אוֹמֵר שֶׁבִּשְׁבִיל אֲבֵלוּת הוּא נִמְנָע, וְהָוֵי דְּבָרִים שֶׁל פַּרְהֶסְיָא. \u0005וְכֵן אִם הַכֹּהֵן אָבֵל וְאֵין כֹּהֵן אַחֵר בְּבֵית הַכְּנֶסֶת, מֻתָּר לִקְרוֹתוֹ; אֲבָל בְּעִנְיָן אַחֵר, אָסוּר (הַגָּהוֹת מַיְמוֹנִי פ\"ג מה\"א)\u0006. \u0010g5\u0011 \u0010r4\u0011\nגְרָרַתּוּ חַיָּה אוֹ הֲרָגוּהוּ לִסְטִים, \u0010y4\u0011 \u0010y5\u0011 וּבְשַׁבָּת נִתְיָאֵשׁ מִלְבַקֵשׁ, כֵּיוָן דִּדְבָרִים שֶׁבְּצִנְעָא נוֹהֵג בְּשַׁבָּת עוֹלֶה לוֹ לְיוֹם אֶחָד. \u0005הַגָּה: \u0010r5\u0011 אִם פָּגַע יוֹם ל' שֶׁל אֲבֵלוּת בְּשַׁבָּת וְיוֹם כ\"ט בְּעֶרֶב שַׁבָּת, מֻתָּר לוֹ לִרְחֹץ בְּעֶרֶב שַׁבָּת, אַף בִּמְקוֹמוֹת שֶׁנּוֹהֲגִין שֶׁלֹּא לִרְחֹץ כָּל שְׁלֹשִׁים, דְּהוֹאִיל וּמִדִּינָא שָׁרֵי לְאַחַר שִׁבְעָה, אֶלָּא שֶׁנָּהֲגוּ לְהַחְמִיר כָּל ל', בִּכְהַאי גַּוְנָא שָׁרֵי מִשּׁוּם כְּבוֹד שַׁבָּת (הַגָּהוֹת מַיְמוֹנִי בְּשֵׁם מַהֲרַ\"ם פ\"י ופ\"ו דְּיוֹם טוֹב)\u0006. וְהוּא הַדִּין כָּל כַּיּוֹצֵא בָּזֶה, כְּגוֹן לַחֲזֹר עַל מְקוֹמוֹ בְּלֵיל שַׁבָּת וְלִלְבֹּשׁ בִּגְדֵי שַׁבָּת, דְּהָא נָמִי אֵינוֹ אֶלָּא מִנְהָג בְּעָלְמָא \u0005(כֵּן נִרְאֶה מִדִּבְרֵי מַהַרַ\"שׁ)\u0006, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִי' שפ\"ט וש\"צ; וְאַף עַל פִּי שֶׁיֵּשׁ לְחַלֵּק בֵּין רְחִיצָה שֶׁאֲסוּרָה בְּשַׁבָּת וּבֵין דְּבָרִים אֵלּוּ שֶׁאֶפְשָׁר לוֹ לַעֲשׂוֹת בְּשַׁבָּת, מִכָּל מָקוֹם אֵין נ\"ל לְחַלֵּק בְּכָךְ.",{"g":["\u0003משנה מ\"ק דף י\"ט ע\"א:\u0004 ","\u0003כמימרא דשמואל שם דף כ\"ד ע\"א:\u0004 ","טור בשם אביו הרא\"ש שם בפסקיו כיון דהאידנא אין רגילין לילך יחף מדאמרינן לאו כ\"ע עבידי דסיימי וכו' שם:","\u0003שם במימרא דשמואל:\u0004 ","טור מדברי אביו הרא\"ש בפסקיו וכ\"כ הגהמ\"יי בפ\"ד בשם הר\"מ:\n(°) וכ' רש\"ל בתשובה סימן ע\"א דאבל שיום מילת בנו בשבת אין לו לעלות בתורה אף ע\"פ שנהגו בקצת מקומות שאבי הבן הוי חיוב לעלות ביום מילת בנו מ\"מ לא מקרי פרהסיא:","ירושלמי ומרדכי בשם הר\"מ מאנגלטירא הביאו הב\"י בסימן ת\"ג:\n(°) איתא בגמרא דף כ\"ז ע\"א והביאו הטור בסוף סי' זה זוקפין המטות בע\"ש מן המנחה ולמענה ואמר רבה וכו' אע\"פ כן אינו יושב עליה עד שתחשך וכתבו התוספות שם דמכאן סמכו שלא לישב ע\"ג כסא וספסל וכו':"],"t":["\u0003מנעלים. \u0004 כתב הש\"ך לא ידעתי מה ענין מנעלים ברגליו לכאן דמאן דמתיר משום מנעלים ברגליו מתיר אפילו בעטיפת ישמעאלים וכ\"מ בש\"ס וברמב\"ן. ובאמת במהרי\"ו כתב דהכא מותר מטעם כיון שנוהגים בעטיפה זו גם אחר ז' ימי אבלות דלא אסרינן דבר שבפרהסיא אלא מה שאינו רק תוך ז' ואח\"כ כתב דמותר ג\"כ מטעמא דמנעלים ברגליו ע\"ש. ובלבוש השמיט האי סיומא דהואיל ויש מנעלים ברגליו עכ\"ל:","\u0003מחזיר. \u0004 כתב הש\"ך והאידנא לא נהגו לדקדק בזה. ואפשר דהמנעלים מוכיחים עליהם כמ\"ש הב\"י דהיכא דהמנעלים ברגליו א\"צ לחזרת קרע ע\"ש עכ\"ל:","\u0003הפרשה. \u0004 כתב בדרישה בשם מהרש\"ל דה\"ה לחזור שנים מקרא ואחד תרגום מותר ע\"ש:"],"r":["\u0003שהרי קצת כו'. \u0004טור ולכאורה תמוה שאפילו בי\"ט נמי תעלה אבל כבר תי' תוס' כ\"ג ב' ד\"ה מ\"ד. ובתוס' הרב מקשה כו' ודברי הטור הוא כפי' ה\"ר ר' שמעון שם בתוס' ע\"ש:","\u0003דהיינו כו'. \u0004הרי\"ף וש\"פ דפסקו כשמואל משום דר\"נ ס\"ל כוותיה שם וכן ר' יוחנן שם דאמר ל\"ש כו' ולא כתוס' שם ד\"ה שמואל כו':","\u0003ודוקא כו' הואיל כו'. \u0004זה כתב מהרי\"ו בטעם ב' אבל בטעם הראשון כתב משום דכל שבתוך ל' מותר אף בשבת וכמש\"ל סי' שצ\"ט ס\"א \u0005(בס\"ק ד') \u0006ובלא\"ה כיון שאינו כעטיפת הישמעאלים מותר דשמואל ל\"פ ארב אלא משום דשמואל לטעמיה כו' וכ\"כ המרדכי וז\"ל עטיפת הראש דבר של צנעה הוא ולא כעטיפת הישמעאלים אלא כיסוי הראש לבד כדאביי דאשכחא לרב יוסף ולטעמא דמנעלים ברגליו אפילו כעטיפת הישמעאלים מותר כמש\"ש ושמואל לטעמיה כו' אר\"י ל\"ש כו' וכן בפרקי ר\"א והביאו הרא\"ש סי' צ\"ג הולכין בשבת כו' הנכנס לשער אבלים והיה שפמו כו' ובש\"ע השמיט דין זה דמנעלים ברגליו והא דרב יוסף ועבב\"י בזה כמה שיטות:","\u0003וללבוש מנעליו. \u0004מדינא דגמרא רשות וחייב בחליצת אלא ממ\"ש \u0005(שם) \u0006מאי שנא נעילת הסנדל דרשות דלאו כ\"ע כו' והשתא כ\"ע הולכין בסנדל. הרא\"ש:","\u0003גררתו כו'. \u0004עתוס' י\"ז ב' ד\"ה בשחל כו':","\u0003אם פגע כו'. \u0004כמש\"ש ומודים חכמים כו' אע\"ג דאין מקצת יום ככולו לדידהו ה\"נ:"]}],["אֵין מַנִּיחִין אֶת הַמִּטָּה בָּרְחוֹב בְּחֹל הַמּוֹעֵד, שֶׁלֹּא לְהַרְגִיל אֶת הַהֶסְפֵּד, שֶׁאָסוּר לְהַרְגִיל אֶת הַהֶסְפֵּד בְּחֹל הַמּוֹעֵד, אֶלָא לִכְבוֹד תַּלְמִיד חָכָם; לְפִיכָךְ אֵין מוֹלִיכִין הַמֵּת לְבֵית הַקְבָרוֹת בְּחֹל הַמּוֹעֵד, עַד שֶׁיִּהְיֶה כָּל הַקֶבֶר מְתֻקָן וּמְזֻמָּן.\nאֵין קוֹרְעִין בְּחֹל הַמּוֹעֵד אֶלָא מִי שֶׁהוּא \u0010y0\u0011 חַיָּב לִקְרֹעַ כִּדְאִיתָא בְּסִימָן ש\"מ, אֲבָל מִי שֶׁאֵינוֹ חַיָּב, וְרוֹצֶה לִקְרֹעַ מִפְּנֵי הַכָּבוֹד, אָסוּר. \u0010y1\u0011\nשָׁמַע בְּחֹל הַמּוֹעֵד שְׁמוּעָה קְרוֹבָה, חַיָּב לִקְרֹעַ.\nאֵין חוֹלְצִין כָּתֵף בַּמּוֹעֵד, וְאֵין מַבְרִין בּוֹ אֶלָא קְרוֹבָיו שֶׁל מֵת; אֲבָל הַקְרוֹבִים, מַבְרִין. וְהוּא הַדִּין לַחֲנֻכָּה וּפוּרִים וְרֹאשׁ חֹדֶשׁ. וּכְשֶׁמַּבְרִין, אֵין מַבְרִין אֶלָא עַל מִטּוֹת זְקוּפוֹת, אֲבָל בְּיוֹם טוֹב, אֲפִלוּ בְּיוֹם טוֹב שֵׁנִי, אֵין קוֹרְעִין וְלֹא חוֹלְצִין וְלֹא מַבְרִין; וּבְחֹל הַמּוֹעֵד מַבְרִין הַכֹּל עַל הֶחָכָם לְתוֹךְ הָרְחוֹב, כְּדֶרֶךְ שֶׁמַּבְרִין אֶת הַקְרוֹבִים, שֶׁהַכֹּל כִּקְרוֹבָיו.\nנָשִׁים בְּחֹל הַמּוֹעֵד מְעַנּוֹת, דְּהַיְנוּ שֶׁכֻּלָן עוֹנוֹת כְּאַחַת; אֲבָל לֹא מְטַפְּחוֹת, דְּהַיְנוּ לְהַכּוֹת כַּף עַל כַּף. בְּרֹאשׁ חֹדֶשׁ, חֲנֻכָּה וּפוּרִים, מְעַנּוֹת וּמְטַפְּחוֹת, אֲבָל לֹא מְקוֹנְנוֹת, דְּהַיְנוּ שֶׁאַחַת מְדַבֶּרֶת וְכֻלָן עוֹנוֹת אַחֲרֶיהָ. נִקְבַּר הַמֵּת, לֹא מְעַנּוֹת וְלֹא מְטַפְּחוֹת; וְהָנֵי מִלֵי לְאִינַשׁ דְּעַלְמָא, אֲבָל לְתַלְמִיד חָכָם, בֵּין בְּחֹל הַמּוֹעֵד בֵּין בְּרֹאשׁ חֹדֶשׁ, חֲנֻכָּה וּפוּרִים, מְעַנּוֹת וּמְקוֹנְנוֹת כְּדַרְכָּן בַּחֹל; וְהָנֵי מִלֵי בְּפָנָיו, אֲבָל שֶׁלֹּא בְּפָנָיו, לֹא. וְיוֹם שְׁמוּעָה, אֲפִלוּ רְחוֹקָה, כִּבְפָנָיו דְּמֵי.\nאוֹמְרִים עַל הַמֵּת צִדּוּק הַדִּין וְקַדִּישׁ, כְּדַרְכָּן. וְכֵן בְּיוֹם טוֹב שֵׁנִי; אֲבָל בְּיוֹם טוֹב רִאשׁוֹן, כֵּיוָן שֶׁאֵין מִתְעַסְקִים בַּמֵּת אֵין אוֹמְרִים אוֹתוֹ. \u0005הַגָּה: וְיֵשׁ חוֹלְקִין שֶׁלֹּא לוֹמַר צִדּוּק הַדִּין בַּמּוֹעֵד (הַטּוּר הֵבִיא כַּמָּה רַבְּוָתָא)\u0006, וְכֵן הַמִּנְהָג פָּשׁוּט בִּמְדִינוֹת אֵלּוּ שֶׁלֹּא לוֹמַר צִדּוּק הדִּין בְּכָל הַיָּמִים שֶׁאֵין אוֹמְרִים בָּהֶם תַּחֲנוּן \u0005(בְּמִנְהָגִים)\u0006 ; וְלָכֵן אֵין אוֹמְרִים גַּם כֵּן כְּשֶׁקּוֹבְרִין \u0010y2\u0011 אַחַר חֲצוֹת בְּעֶרֶב שַׁבָּת. יֵשׁ אוֹמְרִים שֶׁאִם קוֹבְרִים הַמֵּת בַּלַּיְלָה, שֶׁאֵין אוֹמְרִים קַדִּישׁ וְלֹא צִדּוּק הדִּין \u0005(כָּל בּוֹ)\u0006.\nמֵת לוֹ מֵת קֹדֶם פּוּרִים, וּפָגַע בּוֹ פּוּרִים, אֵינוֹ מַפְסִיק \u0010y3\u0011 הָאֲבֵלוּת; וּמִכָּל מָקוֹם אֵין אֲבֵלוּת נוֹהֵג בּוֹ, לֹא בְּי\"ד וְלֹא בְּט\"ו, אֶלָא דְּבָרִים שֶׁבְּצִנְעָא נוֹהֵג, וְחַיָּב לִשְׁלֹחַ מָנוֹת. וְאַף עַל פִּי שֶׁאֵינוֹ מִתְאַבֵּל בָּהֶם, עוֹלִים לוֹ מִמִּנְיַן הַשִּׁבְעָה, כְּמוֹ שַׁבָּת.",["\u0003כדאיתא בסימן ש\"מ. \u0004כצ\"ל:","\u0003שמע כו'. \u0004ע\"ל סימן ש\"מ סל\"ב ובא\"ח סי' תקמ\"ז:","\u0003אחר חצות בע\"ש. \u0004(אע\"פ שבערב) [אבל בערב] ר\"ח ובערב חנוכ' אומרי' אפי' אחר חצות (לא) [דלא] עדיפי מע\"ש כ\"כ העט\"ז ומשמע דה\"ה בעי\"ט אחר חצות א\"א:","\u0003ומ\"מ אין אבילות נוהג בו כו'. \u0004ומהרש\"ל פסק דצריך לנהוג כל דיני אבילות ושכן המנהג והביאו הדרישה ע\"ש וכ\"כ המחבר בא\"ח סי' תרצ\"ו סעיף ד' ודרישה כתב ליישב דברי המחבר דלא סתרי אהדדי דבא\"ח מיירי שמת לו מת בו ביום וכאן מיירי שמת קודם לכן ודוחק והרב בהג\"ה שם פסק כהמחבר כאן) וכ' שכן נוהגין והב\"ח לא הביא אלא דברי מהרש\"ל ע\"ש:"],[],"\u0010g0\u0011 אֵין מַנִּיחִין אֶת הַמִּטָּה בָּרְחוֹב בְּחֹל הַמּוֹעֵד, שֶׁלֹּא לְהַרְגִיל אֶת הַהֶסְפֵּד, שֶׁאָסוּר לְהַרְגִיל אֶת הַהֶסְפֵּד בְּחֹל הַמּוֹעֵד, \u0010g1\u0011 \u0010r0\u0011 אֶלָא לִכְבוֹד תַּלְמִיד חָכָם; לְפִיכָךְ אֵין מוֹלִיכִין הַמֵּת לְבֵית הַקְבָרוֹת בְּחֹל הַמּוֹעֵד, עַד שֶׁיִּהְיֶה כָּל הַקֶבֶר \u0010g2\u0011 מְתֻקָן וּמְזֻמָּן.\nאֵין קוֹרְעִין בְּחֹל הַמּוֹעֵד אֶלָא מִי שֶׁהוּא \u0010y0\u0011 חַיָּב לִקְרֹעַ כִּדְאִיתָא בְּסִימָן ש\"מ, \u0010g3\u0011 אֲבָל מִי שֶׁאֵינוֹ חַיָּב, וְרוֹצֶה לִקְרֹעַ מִפְּנֵי הַכָּבוֹד, אָסוּר. \u0010y1\u0011 \u0010g4\u0011 \u0010r1\u0011\nשָׁמַע בְּחֹל הַמּוֹעֵד שְׁמוּעָה קְרוֹבָה, \u0010g5\u0011 חַיָּב לִקְרֹעַ.\nאֵין חוֹלְצִין כָּתֵף בַּמּוֹעֵד, וְאֵין מַבְרִין בּוֹ אֶלָא קְרוֹבָיו שֶׁל מֵת; \u0010g6\u0011 \u0010r2\u0011 אֲבָל הַקְרוֹבִים, מַבְרִין. \u0010g7\u0011 \u0010r3\u0011 וְהוּא הַדִּין לַחֲנֻכָּה וּפוּרִים וְרֹאשׁ חֹדֶשׁ. \u0010g8\u0011 וּכְשֶׁמַּבְרִין, אֵין מַבְרִין אֶלָא עַל מִטּוֹת זְקוּפוֹת, \u0010g9\u0011 אֲבָל בְּיוֹם טוֹב, \u0010r4\u0011 אֲפִלוּ בְּיוֹם טוֹב שֵׁנִי, אֵין קוֹרְעִין וְלֹא חוֹלְצִין וְלֹא מַבְרִין; \u0010g10\u0011 וּבְחֹל הַמּוֹעֵד מַבְרִין הַכֹּל עַל הֶחָכָם לְתוֹךְ הָרְחוֹב, כְּדֶרֶךְ שֶׁמַּבְרִין אֶת הַקְרוֹבִים, שֶׁהַכֹּל כִּקְרוֹבָיו. \u0010g11\u0011\nנָשִׁים בְּחֹל הַמּוֹעֵד מְעַנּוֹת, דְּהַיְנוּ שֶׁכֻּלָן עוֹנוֹת כְּאַחַת; אֲבָל לֹא מְטַפְּחוֹת, דְּהַיְנוּ לְהַכּוֹת כַּף עַל כַּף. \u0010g12\u0011 בְּרֹאשׁ חֹדֶשׁ, חֲנֻכָּה וּפוּרִים, מְעַנּוֹת וּמְטַפְּחוֹת, אֲבָל לֹא מְקוֹנְנוֹת, דְּהַיְנוּ שֶׁאַחַת מְדַבֶּרֶת וְכֻלָן עוֹנוֹת אַחֲרֶיהָ. נִקְבַּר הַמֵּת, לֹא מְעַנּוֹת וְלֹא מְטַפְּחוֹת; וְהָנֵי מִלֵי לְאִינַשׁ דְּעַלְמָא, \u0010g13\u0011 אֲבָל לְתַלְמִיד חָכָם, בֵּין בְּחֹל הַמּוֹעֵד בֵּין בְּרֹאשׁ חֹדֶשׁ, חֲנֻכָּה וּפוּרִים, מְעַנּוֹת וּמְקוֹנְנוֹת כְּדַרְכָּן בַּחֹל; וְהָנֵי מִלֵי בְּפָנָיו, אֲבָל שֶׁלֹּא בְּפָנָיו, לֹא. וְיוֹם \u0010g14\u0011 שְׁמוּעָה, אֲפִלוּ רְחוֹקָה, כִּבְפָנָיו דְּמֵי. \u0010g15\u0011 \u0010r5\u0011\nאוֹמְרִים עַל הַמֵּת צִדּוּק הַדִּין וְקַדִּישׁ, כְּדַרְכָּן. וְכֵן בְּיוֹם טוֹב שֵׁנִי; אֲבָל בְּיוֹם טוֹב רִאשׁוֹן, כֵּיוָן שֶׁאֵין מִתְעַסְקִים בַּמֵּת אֵין אוֹמְרִים אוֹתוֹ. \u0005הַגָּה: וְיֵשׁ חוֹלְקִין שֶׁלֹּא לוֹמַר צִדּוּק הַדִּין בַּמּוֹעֵד (הַטּוּר הֵבִיא כַּמָּה רַבְּוָתָא)\u0006, וְכֵן הַמִּנְהָג פָּשׁוּט בִּמְדִינוֹת אֵלּוּ שֶׁלֹּא לוֹמַר צִדּוּק הדִּין בְּכָל הַיָּמִים שֶׁאֵין אוֹמְרִים בָּהֶם תַּחֲנוּן \u0005(בְּמִנְהָגִים)\u0006 ; וְלָכֵן אֵין אוֹמְרִים גַּם כֵּן כְּשֶׁקּוֹבְרִין \u0010y2\u0011 אַחַר חֲצוֹת \u0010t0\u0011 בְּעֶרֶב שַׁבָּת. יֵשׁ אוֹמְרִים שֶׁאִם קוֹבְרִים הַמֵּת בַּלַּיְלָה, שֶׁאֵין אוֹמְרִים קַדִּישׁ וְלֹא צִדּוּק הדִּין \u0005(כָּל בּוֹ)\u0006. \u0010g16\u0011 \u0010r6\u0011\nמֵת לוֹ מֵת קֹדֶם פּוּרִים, וּפָגַע בּוֹ פּוּרִים, אֵינוֹ מַפְסִיק \u0010y3\u0011 \u0010r7\u0011 הָאֲבֵלוּת; וּמִכָּל מָקוֹם אֵין אֲבֵלוּת \u0010t1\u0011 נוֹהֵג בּוֹ, לֹא בְּי\"ד וְלֹא בְּט\"ו, אֶלָא דְּבָרִים שֶׁבְּצִנְעָא נוֹהֵג, וְחַיָּב לִשְׁלֹחַ מָנוֹת. וְאַף עַל פִּי שֶׁאֵינוֹ מִתְאַבֵּל בָּהֶם, עוֹלִים לוֹ מִמִּנְיַן הַשִּׁבְעָה, כְּמוֹ שַׁבָּת.",{"g":["\u0003משנה מ\"ק דף כ\"ז ע\"א:\u0004 ","\u0003נימוקי יוסף שם:\u0004 ","\u0003משנה שם דף כ\"ד ע\"ב:\u0004 ","\u0003שם בגמ' דף כ\"ה ע\"א:\u0004 ","\u0003רבינו ירוחם ובשם הראב\"ד ושכ\"כ ר\"מ וכ\"כ המרדכי ושכן משמע בירושלמי וכ\"כ הגהמ\"יי פי\"א:\u0004 ","\u0003שם במשנה:\u0004 ","טור וכדעת אביו הרא\"ש בפסקיו וכ\"כ הרמב\"ן והרמב\"ם בפי\"א וש\"פ:\n(°) לאפוקי מהר\"ם מארץ האי וסמ\"ג וסמ\"ק שכתבו שאין עושין הבראה בת\"ה ועיין בב\"י:","\u0003סמ\"ג בהלכות ח\"ה:\u0004 ","\u0003שם במשנה:\u0004 ","\u0003רמב\"ם בפי\"א מהלכות אבל וכ\"כ הרמב\"ן בסת\"ה וכ\"פ הר\"ן בפ\"ק די\"ט:\u0004 ","ברייתא וגמ' שם דף כ\"ה ע\"א ומימרא דרב פפא שם דף כ\"ז ע\"ב:\n(°) ברמב\"ם שם איתא אבלים שהכל אבלים עליו וכ\"כ המחבר בא\"ח סימן תקמ\"ז וע\"ש:","\u0003משנה שם דף כ\"ה ע\"ב:\u0004 ","\u0003שם במשנה:\u0004 ","\u0003מימרא דרב פפא דלעיל:\u0004 ","\u0003מעובדא דרב כהנא דספדיה לרב זביד וכו'\u0004 שם:","טור בשם הרי\"ץ גיאת בשם תלמידי רש\"י בשם רש\"י וכ\"כ הרמב\"ן:\n(°) וכתבו הגהמי\"י והגה\"א בשם א\"ז שרבינו יואל הלוי לא אמר כל ז' ימים אחר עצרת כי אם דרך הליכה כי עצרת יש לו תשלומין כל ז':","טור בשם הר\"מ מרוטנבורג מדברי אביו הרא\"ש בפסקיו שם מטעם דימי משתה ושמחה קבילו עלייהו ובדברים של צנעא נוהג דלא עדיף משבת:\n(°) בא\"ח סימן תר\"צ ס\"ד פסק המחבר שכל דיני אבלות נוהגים בחנוכה ופורים ובדרישה כתב ליישב דברי המחבר דבא\"ח איירי באבלות יום א' וכאן בשאר ימים והש\"ך כ\" שהוא דוחק ע\"ש:"],"t":["\u0003בע\"ש. \u0004 \u0005(אע\"פ שבערב)\u0006 [אבל בערב] ר\"ח וערב חנוכה אומרים אפי' לאחר חצות \u0005(לא)\u0006 [דלא] עדיפי מע\"ש כ\"כ הלבוש ומשמע דה\"ה שאין אומרים ג\"כ בערב יו\"ט אחר חצות. ש\"ך:","\u0003נוהג. \u0004 ומהרש\"ל פסק דצריך לנהוג כל דיני אבילות ושכן המנהג וכ\"כ המחבר בא\"ח סי' תרצ\"ו ס\"ד. ובדרישה כתב ליישב דברי המחבר דלא סתרי אהדדי דבא\"ח מיירי שמת לו מת בו ביום וכאן מיירי שמת קודם לכן ודוחק \u0005(ויש רוצים להגיה בא\"ח דהאי בחנוכה צ\"ל בצינעא. וה\"ק כל דברי אבלות בצינעא נוהגים בפורים. ובזה מיושב מה שמזכיר שם חנוכה בהלכות פורים וה\"ל להביאו בהלכות חנוכה סי' ת\"ע ששם מזכיר דיני חנוכה בהספד אלא ודאי שט\"ס הוא וצ\"ל בצינעא)\u0006 והרב בהג\"ה שם פסק כהמחבר כאן וכתב שכן נוהגין והב\"ח לא הביא אלא דברי מהרש\"ל ע\"ש. עכ\"ל הש\"ך:"],"r":["\u0003אלא לכבוד ת\"ח. \u0004כ\"ז ב' ובמגילה ג' ב' וכמ\"ש בס\"ה:","\u0003שמע בח\"ה כו'. \u0004מדפריך שם אמתני' ואפילו חכם והתניא חכם כו' משמע דברייתא איירי אף בחה\"מ והיא איירי בשמועה קרובה דאי בין מיתה לקבורה אפילו לאו חכם רק אדם כשר חייבין לקרעו כמש\"ש וכמש\"ל סי' ש\"מ ס\"ו וס\"ז ועבא\"ח סי' תקמ\"ז כ\"ז הסי':","\u0003(ליקוט) אבל הקרובים כו'. \u0004ממתני' הנ\"ל וירושלמי שם ועתוס' ך' א' ד\"ה שכבר כו' ושם כ\"ד ב' ד\"ה אלא כו' (ע\"ב):","\u0003וה\"ה לחנוכה כו'. \u0004מדחילק בסיפא נשים במועד כו' בר\"ח כו' ולא חילק ברישא ואינו מוכרח:","\u0003אפי' בי\"ט שני כו'. \u0004שלא אמרו \u0005(י\"ט ו' א') \u0006כחול שוויוה רבנן אלא למה שלצרכו בלבד מדקאמר אפילו למיגיז ליה אסא כו' משמע דוקא הכל לצרכו:","\u0003אומרים כו' וי\"ח. \u0004עבא\"ח סימן ת\"כ ס\"ב:\n\u0003(ליקוט) אומרים כו'. \u0004ערא\"ש סי' קל\"ד: סעיף ז' ע\"ש סי' קל\"ב (ע\"כ):","\u0003מת כו'. \u0004כמש\"ו ואע\"פ כו':","\u0003ומ\"מ. \u0004עבא\"ח סי' תרצ\"ו:"]}],["מִי שֶׁבָּאָה לוֹ שְׁמוּעָה שֶׁמֵּת לוֹ קָרוֹב, אִם בְּתוֹךְ ל' יוֹם הִגִיעָה הַשְּׁמוּעָה, אֲפִלוּ יוֹם ל' עַצְמוֹ, הֲרֵי זוֹ שְׁמוּעָה קְרוֹבָה וְחַיָּב לִנְהֹג שִׁבְעָה יְמֵי אֲבֵלוּת מִיּוֹם שֶׁהִגִיעַ הַשְּׁמוּעָה; וְקוֹרֵעַ וּמוֹנֶה ל' יוֹם \u0005מִיּוֹם הַשְּׁמוּעָה (כָּךְ מַשְׁמָע מֵהַרַמְבַּ\"ם וּמִנִּמּוּקֵי יוֹסֵף פא\"מ וּבְמָרְדְּכַי)\u0006 לְתִסְפֹּרֶת עִם שְׁאָר דְּבָרִים. \u0010c0\u0011 כְּלָלוֹ שֶׁל דָּבָר, יוֹם שְׁמוּעָתוֹ הַקְרוֹבָה כְּיוֹם הַקְבוּרָה. וְאִם שָׁמַע מִיּוֹם ל' וָאֵילָךְ, אֵין צָרִיךְ לִנְהֹג אֶלָא שָׁעָה אַחַת, לֹא שְׁנָא שָׁמַע בַּיּוֹם לֹא שְׁנָא שָׁמַע בַּלַיְלָה, שֶׁאִם שָׁמַע בַּלַיְלָה וְנָהַג מִקְצָת אֲבֵלוּת בַּלַיְלָה שָׁעָה אַחַת, עוֹלֶה לוֹ; וַאֲפִלוּ שָׁמַע עַל אָבִיו וְאִמּוֹ. וְהָנֵי מִלֵי לְעִנְיַן גְזֵרַת שִׁבְעָה, \u0010c1\u0011 אֲבָל לְעִנְיַן גְזֵרַת שְׁלֹשִׁים, נוֹהֵג עַל אָבִיו וְאִמּוֹ בְּתִסְפֹּרֶת עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו, וּבְגִהוּץ עַד שֶׁיַּגִיעַ הָרֶגֶל וְיִגְעֲרוּ בּוֹ, וְכֵן בִּשְׁאֵלַת שָׁלוֹם וְלִכָּנֵס לְבֵית הַמִּשְׁתֶּה; וּמוֹנֶה מִיּוֹם מִיתָה וְלֹא מִיּוֹם שְׁמוּעָה. \u0010y0\u0011 לְפִיכָךְ אִם בָּאָה לוֹ שְׁמוּעָה עַל אָבִיו וְאִמּוֹ לְאַחַר י\"ב חֹדֶשׁ, \u0010c2\u0011 אֵינוֹ נוֹהֵג אֶלָא יוֹם אֶחָד אַף בִּגְזֵרַת ל'.\nהַשּׁוֹמֵעַ שְׁמוּעָה רְחוֹקָה, אֵין צָרִיךְ לִנְהֹג כָּל דִּין אֲבֵלוּת, אֶלָא דַּיּוֹ בַּחֲלִיצַת מִנְעָל, וְאֵין צָרִיךְ לֹא עֲטִיפָה וְלֹא כְּפִיַּת הַמִּטָּה, וּמֻתָּר בִּמְלָאכָה, רְחִיצָה וְסִיכָה וְתַשְׁמִישׁ הַמִּטָּה וּבְתַלְמוּד תּוֹרָה, וְאִם אֵין לוֹ מִנְעָלִים בְּרַגְלָיו צָרִיךְ שֶׁיִּכְפֶה מִטָּתוֹ אוֹ יַעֲטֹף רֹאשׁוֹ, שֶׁצָּרִיךְ שֶׁיַּעֲשֶׂה מַעֲשֶׂה שֶׁנִּכָּר בּוֹ שֶׁעוֹשֶׂה מִשּׁוּם אֲבֵלוּת; וְאִם הָיָה עוֹסֵק בַּתּוֹרָה אוֹ בִּמְלָאכָה, אוֹ שֶׁהָיָה רוֹחֵץ וְסָךְ, וּבָאָה לוֹ שְׁמוּעָה, מַפְסִיק שָׁעָה אַחַת מִשּׁוּם אֲבֵלוּת, וְחוֹזֵר לְמַה שֶּׁבְּיָדוֹ, \u0010y1\u0011 אֲבָל אִם הָיָה לָבוּשׁ תְּפִלִין, אֵינוֹ צָרִיךְ לְחָלְצָן, וּמִכָּל מָקוֹם אֵינוֹ יוֹצֵא יְדֵי אֲבֵלוּת בְּהֶפְסֵק זֶה, וְצָרִיךְ שֶׁיַּעֲשֶׂה מַעֲשֶׂה שֶׁנִּכָּר שֶׁעוֹשֶׂה מִשּׁוּם אֲבֵלוּת, כְּגוֹן חֲלִיצַת מִנְעָל אוֹ כְּפִיַּת הַמִּטָּה וַעֲטִיפָה; וּמִיהוּ בְּחָדָא סָגֵי.\nאֵין מַבְרִין עַל שְׁמוּעָה רְחוֹקָה.\nאֵין קוֹרְעִין עַל שְׁמוּעָה רְחוֹקָה; וְעַל אָבִיו וְאִמּוֹ, קוֹרֵעַ לְעוֹלָם. \u0005וּבְמָקוֹם שֶׁאֵין לוֹ \u0010y2\u0011 לִקְרֹעַ, אָסוּר לְהַחְמִיר עַל עַצְמוֹ \u0010y3\u0011 וְלִקְרֹעַ (אוֹר זָרוּעַ)\u0006.\nהַשּׁוֹמֵעַ שְׁמוּעָה בְּשַׁבָּת אוֹ בָּרֶגֶל, וּלְמוֹצָאֵי שַׁבָּת וְרֶגֶל נַעֲשֵׂית רְחוֹקָה, אֵינוֹ נוֹהֵג \u0010c3\u0011 אֶלָא יוֹם אֶחָד, וּבְשַׁבָּת וְרֶגֶל אָסוּר בִּדְבָרִים שֶׁל צִנְעָא.\nהַשּׁוֹמֵעַ שְׁמוּעָה רְחוֹקָה בְּשַׁבָּת אוֹ בָּרֶגֶל, אֵינוֹ נוֹהֵג אֲפִלוּ דְּבָרִים שֶׁבְּצִנְעָא, וּלְמוֹצָאֵי שַׁבָּת וְרֶגֶל נוֹהֵג שָׁעָה אַחַת, וְדַיּוֹ.\nהַשּׁוֹמֵעַ שְׁמוּעָה קְרוֹבָה בְּשַׁבָּת הַשַּׁבָּת עוֹלָה לוֹ לְיוֹם אֶחָד, וּלְמָחָר קוֹרֵעַ, \u0010c4\u0011 וַהֲוָה לֵיהּ יוֹם שִׁשִּׁי שְׁבִיעִי לַאֲבֵלוּת.\nעֲשָׂרָה יָמִים אַחַר חַג הַסֻכּוֹת שָׁמַע שֶׁמֵּת לוֹ מֵת בְּעֶרֶב הֶחָג, אַף עַל פִּי שֶׁאִם נִמְנֶה שָׁעָה אַחַת לִפְנֵי הֶחָג ז' וְשִׁבְעַת יְמֵי הֶחָג וְיוֹם שְׁמִינִי עֲצֶרֶת כ\"א, וַעֲשָׂרָה יָמִים אֲחֵרִים הֲרֵי ל\"א, \u0010c5\u0011 אֵין לָזֶה דִּין שְׁמוּעָה רְחוֹקָה, \u0010y4\u0011 אֶלָא דִּין שְׁמוּעָה קְרוֹבָה, שֶׁאֵין הָרֶגֶל עוֹלֶה לְמִי שֶׁלֹּא נָהַג אֲבֵלוּת קֹדֶם לוֹ כְּלָל; וְכָל שֶׁכֵּן לְמִי שֶׁלֹּא הָיָה יוֹדֵעַ שֶׁמֵּת לוֹ מֵת \u0005(ר' יְרוּחָם בְּשֵׁם בַּעַל הַמָּאוֹר וְכ\"ד הָרַמְבַּ\"ן)\u0006.\nשָׁמַע שְׁתֵּי שְׁמוּעוֹת רְחוֹקוֹת בְּיוֹם אֶחָד, אֵינוֹ נוֹהֵג עֲלֵיהֶן \u0010y5\u0011 אֶלָא יוֹם אֶחָד. הָיוּ קְרוֹבוֹת, אוֹ שֶׁמֵּתוּ לוֹ שְׁנֵי מֵתִים כְּאֶחָד, מוֹנֶה לִשְׁתֵּיהֶם כְּאֶחָד שִׁבְעָה וּשְׁלֹשִׁים. \u0010y6\u0011 שָׁמַע לְזֶה הַיּוֹם וְלָזֶה לְמָחָר, מוֹנֶה לַשֵּׁנִי מִיּוֹם שְׁמוּעָה, שִׁבְעָה וּשְׁלֹשִׁים.\nשָׁמַע שְׁמוּעָה קְרוֹבָה בְּשַׁבָּת עֶרֶב הָרֶגֶל, כֵּיוָן דִּדְבָרִים שֶׁבְּצִנְעָא נוֹהֵג, \u0010y7\u0011 עוֹלֶה לוֹ אוֹתוֹ שַׁבָּת לִמִנְיַן שִׁבְעָה. \u0010y8\u0011\nמִי שֶׁהִתְפַּלֵל כְּבַר עַרְבִית וַעֲדַיִן יוֹם הוּא, וְשָׁמַע שְׁמוּעָה קְרוֹבָה, \u0010c6\u0011 מוֹנֶה מִיּוֹם מָחָר, וְאוֹתוֹ יוֹם אֵינוֹ עוֹלֶה לוֹ.\nמִי שֶׁמֵּת לוֹ מֵת וְלא נוֹדַע לוֹ, אֵינוֹ חוֹבָה שֶׁיֹאמְרוּ לוֹ; וַאֲפִלוּ בְּאָבִיו וְאִמּוֹ; וְעַל זֶה נֶאֱמַר: מוֹצִיא דִּבָּה הוּא כְּסִיל \u0005(מִשְׁלֵי י, יח)\u0006 וּמֻתָּר לְהַזְמִינוֹ לִסְעֻדַּת אֵרוּסִין וְנִשּׂוּאִין וְכָל שִׂמְחָה, כֵּיוָן שֶׁאֵינוֹ יוֹדֵעַ. מִיהוּ אִם שׁוֹאֵל עָלָיו, \u0010c7\u0011 אֵין לוֹ לְשַׁקֵר וְלוֹמַר: חַי הוּא, שֶׁנֶּאֱמַר: מִדְּבַר שֶׁקֶר תִּרְחָק \u0005(שְׁמוֹת כג, ז)\u0006. \u0005הַגָּה: וּמִכָּל מָקוֹם בְּבָנִים זְכָרִים, נָהֲגוּ לְהוֹדִיעַ, כְּדֵי שֶׁיֹּאמְרוּ קַדִּישׁ; אֲבָל בְּבָנוֹת, אֵין מִנְהָג כְּלָל לְהוֹדִיעָם\u0006 \u0005(מהרי\"ו סי' י\"ג)\u0006. \u0005מִצְוָה לְהִתְעַנּוֹת יוֹם שֶׁמֵּת בּוֹ אָבִיו אוֹ אִמּוֹ\u0006 \u0005(כָּל בּוֹ בְּשֵׁם הר\"מ וְעוֹד פּוֹסְקִים)\u0006, \u0005וּמִתְעַנִּין \u0010c8\u0011 יוֹם הַמִּיתָה וְלֹא יוֹם הַקְּבוּרָה\u0006 \u0005(מהרי\"ו סִימָן קכ\"א ומהרא\"י סִימָן רצ\"ו וְהָאַחֲרוֹנִים)\u0006, \u0010y9\u0011 \u0005אִם לֹא מִי שֶׁהָיָה אֵצֶל הַקְּבוּרָה וְלֹא אֵצֶל הַמִּיתָה.\u0006 \u0005(בְּקַבָּלָה מִפִּי זָקֵן מֻפְלָג מַהֲרַ\"ם לַנְדֹּא)\u0006 ; \u0005וְאִם אֵרַע יוֹם זֶה בְּיוֹם שֶׁאֵין אוֹמְרִים בּוֹ תַּחֲנוּן, אֵין מִתְעַנִּין כְּלָל. וְאִם מֵתוּ בַּאֲדָר וְנִתְעַבְּרָה הַשָּׁנָה, \u0010y10\u0011 הָעִקָּר לְהִתְעַנּוֹת בָּאֲדָר הָרִאשׁוֹן\u0006 \u0005(ת\"ה סִימָן רצ\"ד ומהר\"י מִינְ ץ)\u0006, אַף עַל פִּי שֶׁיֵּשׁ חוֹלְקִין, כָּךְ הוּא \u0010y11\u0011 עִקָּר. וְאִם מֵתוּ בִּשְׁנַת הָעִבּוּר בָּאֲדָר הַשֵּׁנִי, מִתְעַנֶּה גַּם כֵּן בְּעִבּוּר בָּאֲדָר הַשֵּׁנִי \u0005(ג\"ז שָׁם)\u0006. \u0005וְעַיֵּן בְּאֹרַח חַיִּים סִימָן תקס\"ח סָעִיף ז'. וְעַיֵּן לְעֵיל סִימָן שצ\"א שֶׁאֵין לֶאֱכֹל בִּסְעֻדָּה בְּלֵיל יוֹם שֶׁמֵּת בּוֹ אָב וָאֵם. וְאִם חָל תַּעֲנִית זֶה בְּעֶרֶב שַׁבָּת, דִּינוֹ כִּשְׁאָר תַּעֲנִית. וְעַיֵּן בא\"ח סִימָן רמ\"ט. מִיהוּ אִם בְּפַעַם רִאשׁוֹן הִשְׁלִים, יִנְהֹג כֵּן כָּל יָמָיו.\u0006",["\u0003לפיכך אם כו' אלא יום אחד. \u0004כלומר שעה אחת:","\u0003אבל אם היה לבוש תפילין א\"צ לחלצן. \u0004לפי שאף בשעת אבילות מניח תפילין ואינו חולץ אלא ביום ראשון לבד ולא תהא שמועה רחוקה חמורה מיום ב' של אבילות קרובה עכ\"ל רמב\"ן:","\u0003אסור להחמיר כו'. \u0004אם לא על אביו ואמו או אדם גדול שהיה רגיל להקשות לו בדבר הלכה דהוי מסתפי מיניה אם בא לעשות מילתא יתירה לכבודו מותר כ\"כ הב\"ח בסימן ש\"מ סעיף כ\"ה בשם א\"ז:","\u0003השומע כו' אלא יום אחד. \u0004כלומר שעה אחת ומכאן פסק הב\"ח לישב במוצאי שבת שעה א' על הארץ ולנהוג אבילות ואפי' אם חל יום הז' בשבת צריך לנהוג אבילות שעה אחת במוצ\"ש דהא הכא אף על גב דדברים שבצנעא נוהג בשבת לא נפטר בזה וצריך לעשות במו\"ש מעשה שניכר בו משום אבילות עכ\"ד ולפע\"ד ל\"ד כלל דהכא כיון שחכמים חייבו לנהוג אבילות כראוי עכ\"פ שעה אחת וביום השבת אין נוהגין אבילות רק במקצת א\"כ מעולם לא נהג זה דין אבילות כראוי אפי' שעה אחת לכן חייב למוצאי שבת או למוצאי הרגל לנהוג אבילות שעה א' אבל מי שנהג אבילות ז' ימים ובתוך הז' חל יום השבת למה יתחייב באבילות במו\"ש ואפילו זלזל במקצת הימים ולא נהג אבילות קי\"ל לעיל סי' שצ\"ז דאין צריך להשלים וכ\"ש יום השבת דנהג אבילות כדינו. עוד האריך הב\"ח להוציא דברי הר' יחיאל מפשטן ופסק דאם חל יום ז' של אבילות בשבת צריך לנהוג דברים שבצינעא כל היום כיון שאינו נוהג בשבת אלא דברים שבצינעא והביא ראיה ממאי דקי\"ל בסעיף ב' דצריך שיעשה מעשה הניכר משום אבילות וכל מעיין ישפוט בצדק דדעת הר\"ר יחיאל דגם בשבת אמרינן מקצת יום ככולו ונוהג מקצת יום השבת ותו לא ואין חולק עליו בזה והכי משמע פשט לישנא דש\"ס ופוסקים דלא לישתמיט חד לפלוגי בהכי ול\"ד לדלעיל סעיף ב' מטעם שכתבתי בסמוך:","\u0003אלא דין שמועה קרובה. \u0004ומתחיל למנות ז' ול' משעה ששמע וכתבו הב\"ח והדרישה בסי' שצ\"ט בשם מהרש\"ל דלפי זה היכא דמת ביום א' ונקבר ביום ב' אע\"פ שהקרובים שהיו אצל הקבורה מונים מיום הקבורה כי אז היתה סתימת הגולל מ\"מ אותן שלא היו אצל הקבורה ולא נודע להן שמת עד שהגיע יום ל' מיום הקבורה א\"צ לנהוג אבילות כיון דיום שמועה דידהו הוא יום ל\"א מיום המית' וה\"ל שמועה רחוקה דלגבי דין שמועה יום המיתה הוא עיקר ע\"כ:","\u0003אלא יום א'. \u0004כלומר שעה א':","\u0003שמע לזה היום כו'. \u0004וכן במתו לו שנים זה אחר זה כדלעיל סימן שע\"ה ס\"י:","\u0003עולה לו אותו שבת למנין שבעה. \u0004ושוב הרגל מבטל ממנו גזרת ז' כדלעיל ר\"ס שצ\"ט:","\u0003מי שהתפלל כו'. \u0004ע\"ל ס\"ס שע\"ה מ\"ש בזה:","\u0003אם לא מי שהיה אצל הקבורה ולא אצל המיתה. \u0004והעט\"ז השיג על זה דהא טעמא הוא דמתענין מפני הסכנה דריע מזליה ביום זה שמת אביו או אמו וא\"כ אין חילוק ולעולם יש להתענות יום המיתה עכ\"ד וכן משמע בתשובות מהר\"י ברין שהביא בב\"ח גם בתשובת משאת בנימין סימן פ\"ד הקשה על דברי הרב דאטו שני אחים שדרים בעיר אחת א' מהן היה אצל מיתת אביו והב' לא היה בעיר כשמת אביו וקודם הקבורה בא גם הב' שאז הא' יעשה יאר ציי\"ט ביום המיתה והב' למחרתו ואיכא משום לא תתגודדו וגם דמי לחוכא ואיטלולא ואנן בעי' דרכיה דרכי נועם עכ\"ל גם מדברי שאר אחרונים משמע דלעולם מתענין יום המיתה ולא יום הקבורה ובתשו' מ\"ב שם כתב דדוקא משנה ראשונה ואילך אבל בשנה א' לעולם עושין יא\"צ מיום הקבורה דאל\"כ לפעמים לא ישלים אבילות י\"ב חודש כגון אם מת בע\"ש בר\"ח שבט סמוך לשבת שאין פנאי לקברו קודם שבת ויקבר ביום א' שאחריו שהוא ג' שבט ואם אתה עושה היארציי\"ט ביום המיתה בר\"ח שבט גם האבלות יפסוק באותו יום כי כבר נהוג עלמא שלא להתאבל רק עד היאר ציי\"ט וזה ודאי לאו שפיר הוי דהאבילות מתחיל מיום הקבורה ולא מיום המיתה וצריך להשלים האבילות עד ג' שבט עכ\"ל ומעולם לא שמענו ולא ראינו לחלק שנות היאר ציי\"ט ולומר דבשנה ראשונה יש לעשות מיום הקבורה ואחר כך מיום המיתה גם מדברי כל האחרונים שכתבו סתמא דיש לעשות ביום המיתה משמע גם שנה ראשונה וכן משמע בת\"ה דלקמן דגם בשנה ראשונה עושים היאר ציי\"ט ביום המיתה ולענין קושייתו נראה לי דבלאו הכי נמי קשה דהא לפעמים משכחת לה דיום המיתה יהא מרוחק הרבה מיום הקבורה כגון שהוליכו למקום אחרת וכה\"ג כגון שמת בר\"ח ניסן ונקבר בי\"ד בניסן דאין האבילות מתחיל אלא מיום הקבורה וכדלעיל סימן שע\"ה והיאר ציי\"ט מתחיל מיום המיתה ודוחק לומר דלענין אבילות די\"ב חודש אזלינן בתר יום המיתה וגם דוחק לומר דאם אירע בכהאי גוונא יש לעשות היארציי\"ט קודם י\"ב חודש וכן משמע בת\"ה דלעולם עושים היאר ציי\"ט בסוף תשלום האבלות ולעולם מונים האבלות די\"ב חודש משעת הקבורה שכתב על מי שמת אביו בר\"ח ניסן דמן הדין מיד שיכנס אח\"כ ר\"ח ניסן שלים האבילות דהא כבר כלו י\"ב חודש אלא שהעולם נוהגין דאפי' בר\"ח ניסן כל אותו היום אין מבטלין דין אבילות די\"ב חודש ואפשר משום דאמרינן קדיש וברכו ומתענים כיום שמת בו אביו הוא לכן נוהגין ענין אבילות באותו היום אבל מן הדין אין צריך וגם נ\"מ למי שמתענה ואומר קדיש וברכו ביום המיתה והוא מת ביום ונקבר למחר דאבילות לעולם מיום קבורה מנינן עכ\"ל ע\"כ נראה דלעולם יש להתענות יום המיתה אלא דאם אירע דיום המיתה מרוחק מיום הקבורה ג' או ד' ימים או יותר יש להתענות בשנה ראשונה ביום הקבורה כדי שיעשה היאר ציי\"ט בתשלום האבלות כיון דלא אפשר בענין אחר וגם כיון דמילתא דלא שכיחא היא יש לסמוך בכה\"ג אמ\"ד לעשות ביום הקבורה ומשנה ראשונה ואילך יתענה ביום המיתה אבל מי שמת אביו ונקבר בו ביום או ביום שלאחריו יש להתענות ביום המיתה אף בשנה ראשונה כנ\"ל ודו\"ק:","\u0003העיקר להתענות באדר ראשון. \u0004ובא\"ח סימן תקס\"ח מסיים הרב מיהו יש מחמירין להתענות בשניהם וכ\"כ מהרש\"ל שכן נוהגין והביאו הבית חדש:","\u0003ואם מתו בשנת העיבור כו'. \u0004וה\"ה אם מתו בשנת העיבור באדר הראשון מתענים בשנת העיבור באדר הראשון וכן כתב מהרש\"ל שם דפשוט שאם מת בראשון או בשני שכך מתענין בשנים המעוברות:"],["\u0003כללו של דבר יום שמועתו כו'. \u0004מבואר בבית יוסף סימן זה בשם הרמב\"ן דביום השמועה קרובה לא יניח תפילין כמו ביום הקבורה:","\u0003אבל לענין גזירת שלשים. \u0004פירוש מה שתלוי בשאר קרובים במנין שלשים דהיינו גיהוץ ותספורת זה נוהג באביו עד שיגערו כו' ומה שכתב ומונה מיום המיתה רצונו לומר דברים האסורים בי\"ב חדש:","\u0003אינו נוהג אלא יום אחד. \u0004ואף אותו יום אמרינן מקצתו ככולו וכן ברמב\"ן וכ\"כ בא\"ח סימן תקמ\"ח:","\u0003אלא יום אחד. \u0004ר\"ל שעה אחת אבל אם שמע שמועה בשבת שהוא כ\"ט אז נוהג לאחר השבת שבעה ושלשים. רש\"ל. וטעם לזה שאינו נוהג אבילות אחר השבת אע\"ג דביום השבת התחיל והוא ביום השלשים דכיון שאינו מתאבל אבילות גמור באותו שבת רק בדברים שבצינעא על כן אין גזירת אבילות אחריו כך כתב ב\"י בשם רשב\"א וכ' הרמב\"ן דבאותו שבת ורגל אסור בדבר שבצינעא כל אותו יום ולא אמרינן בזה מקצתו ככולו כיון שיש עליו חוב ליום שאחריו שעה אחת היאך נאמר שיפסיק מאבילות ויחזור לו:","\u0003והוי ליה יום ששי שביעי. \u0004בטור כתב אחר זה וה\"ר יחיאל כתב שאין שבת עולה לו בתחילת המנין אלא יתחיל למנות ביום א' והוי ליה יום שביעי שביעי לאבילות ונוהג בו דברים שבצינעא במקצת היום עכ\"ל ופסק ב\"י כדעה הראשונה ומ\"מ הבאתי כאן דברי ה\"ר יחיאל ללמוד ממנו שאם מת באחד בשבת דהוי ליה יום ז' בשבת דאין לנהוג בו איסור בדברים שבצינעא אלא במקצת היום דהיינו בשחרית בהנץ החמה כמ\"ש ה\"ר יחיאל כאן לענין מת בשבת דבזה לא מצינו חולק עליו ואין להקשות הא אמרינן בסימן שצ\"ה בענין מקצת היום ככולו של יום השביעי דתלוי דוקא בעמדו המנחמים מאצלו והכי איתא להדיא בפ' אלו מגלחין ולא סגי בהנץ החמה כמו ביום שלשים הא לאו קושיא היא כלל דבכל ענין שאמרו מקצתו ככולו היינו שאותו מקצת צ\"ל בו מאותו ענין שחייב בשאר ימים בכולו דהיינו במקום שתלוי האבילות בקום עשה כגון במנין שבעה שצריך לעשות מעשה בחליצת סנדל וזקיפת המטה וכיוצא בהם בזה אמרינן דצריך באותו מקצת של יום השביעי לעשות מעשה החיוב עליו ולא סגי בשב ואל תעשה ונתנו גבול לזה המקצת עד קימת המנחמים מאצלו שעד אותה שעה ראוי להיות בקום עשה מה שמוטל עליו בעת ההיא מה שאין כן לדין ל' שאין עליו חיוב בקום עשה רק בשב ואל תעשה דהיינו דאסור גיהוץ ותספורת בזה סגי בהנץ החמה כיון דכבר נהג איסור בשב ואל תעשה די בכך ומשום הכי בשמע שמועה דחוקה שנוהגת שעה אחת היינו נמי בקום עשה שצריך לעשות מעשה דוקא כעין שצריך לעשות בשמועה קרובה שבעה ימים כן יעשה ברחוקה אותה שעה וכמ\"ש בסעיף ב' בסי' זה ומשום הכי כשחל יום שביעי של שבעה ימים בשבת סגי במקצת אע\"ג דאין עושה מעשה באותו מקצת דהא גם ביום השבת כולו לא יעשה מעשה הניכר אלא דעולה למנין משום דנוהג בו דבר שבצינעא ובזה סגי במקצת ממנו והוי כיום השלשים ממש שזכרנו כנ\"ל ברור אלא שראיתי למו\"ח ז\"ל שרוצה לחלוק על ה\"ר יחיאל ולומר דלא אמרי' ביום השבת יום שביעי מקצתו ככולו ורוצה לאסור לאותו אבל לקרות בתורה אפי' במנחה כיון שאין עושה מעשה הניכר בו משום אבילות ועפ\"ז כ' ליישב מה שנהגו איזה אנשים כשחל יום ז' בשבת לישב במוצאי שבת שעה אחת על הארץ כדי לעשות היכר לאבילות שביום השבת לא עשה היכר ודרך זה הוא רחוק מאד דהיאך ישלים ביום השמיני מה שהיה חייב בז' אין זה אלא תימה ותו דא\"כ אם יש שבת באמצע שבוע של אבילות היאך ישלים במ\"ש מה שחייב לעשות בשבת הלא אותו אבלות מה שעושה במוצאי שבת הוא משום חיוב יומא גופיה והיאך תצרפו לעבר ולעתיד. ואין ראיה מאותן אנשים דלאו דסמכי נינהו אלא יום השבת של ז' הוא ממש בדין ז' כמו דין ל' לענין שלשים דהיינו בשב ואל תעשה בדברים שבצינעא כמו בשלשים לגיהוץ ותספורת כן הוא ברור ונכון ודברי ה\"ר יחיאל שהביא הטור הם נכונים להלכה לענין זה שאם חל יום השביעי בשבת שאין צריך אלא מקצת בשחרית ואפי' בשחרית יש היתר לקרותו בתורה אלא כיון שבחול ממתין עד אחר התפלה של שחרית גם בשבת יעשה כן אבל במנחה יש היתר גמור לקרותו לתורה ואין עליו דין שביעי לגמרי כדעת ה\"ר יחיאל ואין חולק עליו בזה. ועוד כתב מו\"ח ז\"ל דאפשר דה\"ר יחיאל לא התיר אלא בתשמיש המטה וכיוצא בדברים דהויין בצינעא ואין שם פרסום כלל אבל לקרותו לתורה מודה ה\"ר יחיאל דאסור כיון שלא עשה מעשה הניכר לאבילות ומאד תמוהין דברים אלו דאנן איפכא תפסינן בכל מקום שאסור להתאבל בפרהסיא מ\"מ יעשה אבילות בצינעא וכאן היאך נימא דבצינעא יהא מותר ובפרהסיא אסור אין זה נכון כלל אלא גם בשבת מותר אחר תפלת שחרית בכל ואין עליו שום איסור מחמת אבילות לגמרי ואותן האנשים שיושבים על הארץ במוצאי שבת אחר יום השבת שהוא שביעי לאבילות הם עושים מדעתם ומוסיפים אבילות שלא מדברי חכמים כלל ואפשר שבא הטעות ההוא ממה שראו בסעיף ו' שבמוצאי שבת ורגל נוהג אבילות שעה אחת נמשך להם הטעות שבכל שבת של אבילות הם סוברים לעשות כן והוא טעות גמור דשם הוה החיוב הגמור במוצאי שבת משום שמועה רחוקה משא\"כ בזה ואדרבה משם ראיה למה שכתבתי שהרי כתב שם הרמב\"ן דבכל אותו שבת אסורים בדבר שבצינעא כמו שזכרתי בסעיף ה' והיינו משום שיש עליו עדיין חיוב אבילות במוצאי שבת משמע הא בלאו הכי לא אסור כל השבת אלא מקצתו ככולו וכן הוא עיקר בלי ספק:","\u0003אין לזה דין שמועה רחוקה. \u0004ה\"ה למי שמת ביום אחד ונקבר ביום שלאחריו חשבינן לענין שמועה קרובה מיום המיתה דבתר יום המיתה אזלינן בכל מילי זולת לענין אבילות דמתחיל מסתימת הגולל:","\u0003מונה מיום מחר. \u0004הטעם דהוי תרי קולי דסתרי אהדדי כיון דעשה אותו לילה לתפלת ערבית אל תעשהו יום ונראה לי דאם שמע שמועה קרובה בסוף יום ל' אחר תפלת ערבית ועדיין יום הוא ודאי לא אמרינן דהוה לילה מכח התפלה דלהחמיר אמרינן כן לענין שלא יעלה יום שעבר למנין ז' אבל לא להקל לומר שהוא שמועה רחוקה אלא צריך להתאבל) ודומה למ\"ש בסימן רס\"ב לענין מילה דלא איכפת לן בתפלה ובזה ודאי מונה מיום שעבר ולא ממחרת דאל\"כ הוה עושה תרי מילי דסתרי דכיון דחשבת ליה יום דלהוי שמועה קרובה היאך יתחיל למנות מיום המחרת דא\"כ הוי לילה ואין כאן אבילות לגמרי:","\u0003אין לו לשקר כו'. \u0004נראה דיש לומר בלשון דמשתמע לתרי אפי דהיינו שאין מבואר בפירוש בדבריו שהוא מת אלא הלשון סובל לחיים ולמיתה וראיה מדאיתא ברבי חייא ששאל לרב אבא קיים א\"ל אימא קיימת ופירשו התוס' דבלשון בתמיה אמר עד שאתה שואלני על אבי שאלני על אמי ומתוך זה הבין ר' חייא שמת אביו שמע מיניה שלא אמר בפירוש שמת:","\u0003יום המיתה ולא יום הקבורה. \u0004) כתוב בתשובת מהר\"ר בנימין נראה דהיינו דוקא משנה ראשונה ואילך אבל בשנה ראשונה לעולם עושין היאר ציי\"ט ביום הקבורה ולא ביום המיתה דאל\"כ לפעמים לא ישלים אבילות של י\"ב חדש כגון אם מת בע\"ש בר\"ח שבט ואין פנאי לקברו עד יום א' שהוא ג' שבט ואם יהיה לו יאר ציי\"ט ביום המיתה בר\"ח שבט גם האבילות יפסוק באותו היום כי כבר נהוג עלמא שלא להתאבל רק עד היאר ציי\"ט וזה ודאי לאו שפיר דהאבילות התחיל מיוה הקבורה ולא מיום המיתה וצריך להשלים האבילות עד יום הקבורה שהוא ג' שבט עכ\"ל. ולא אאמין שיצאו דברים אלו מפי אותו צדיק דודאי לא מונה שום אדם י\"ב חודש רק מיום המיתה דאטו מי שלא שמע שמת אביו עד חצי שנה ודאי לא ימנה רק חצי שנה באבילות דמ\"ש בסימן שצ\"ד דכל אותה שנה הדין מתוח כו' היינו מן מיתת המת לא מיום התחלת האבילות והכי נמי ודאי יסיים האבילות ביום ו' בר\"ח שבט ואז יהיה לו יאר ציי\"ט ומה לנו במה שלא יתאבל י\"ב חודש במילואם אם אי אפשר בכך ואדרבה לדידיה יש לתמוה דהא עכ\"פ לא יתאבל יותר מיום ו' שהוא היום דאז כלו י\"ב חודש ימי הדין שלו וירחיק היא\"ר ציי\"ט מן סיום אבילות שלו אלא לית מאן דחש לזה. הרחמן יגדור פרצת עמו ישראל וינחם אותם בבנין ירושלים במהרה בימינו אמן כן יהי רצון:"],"\u0010g0\u0011 מִי שֶׁבָּאָה לוֹ שְׁמוּעָה שֶׁמֵּת לוֹ קָרוֹב, אִם בְּתוֹךְ ל' יוֹם הִגִיעָה הַשְּׁמוּעָה, \u0010g1\u0011 \u0010r0\u0011 אֲפִלוּ יוֹם ל' עַצְמוֹ, הֲרֵי זוֹ שְׁמוּעָה קְרוֹבָה וְחַיָּב לִנְהֹג שִׁבְעָה יְמֵי אֲבֵלוּת מִיּוֹם שֶׁהִגִיעַ הַשְּׁמוּעָה; \u0010g2\u0011 \u0010r1\u0011 וְקוֹרֵעַ \u0010r2\u0011 וּמוֹנֶה ל' יוֹם \u0005מִיּוֹם הַשְּׁמוּעָה (כָּךְ מַשְׁמָע מֵהַרַמְבַּ\"ם וּמִנִּמּוּקֵי יוֹסֵף פא\"מ וּבְמָרְדְּכַי)\u0006 לְתִסְפֹּרֶת עִם שְׁאָר דְּבָרִים. \u0010c0\u0011 \u0010t0\u0011 כְּלָלוֹ שֶׁל דָּבָר, יוֹם שְׁמוּעָתוֹ הַקְרוֹבָה כְּיוֹם הַקְבוּרָה. \u0010g3\u0011 וְאִם שָׁמַע מִיּוֹם ל' וָאֵילָךְ, אֵין צָרִיךְ לִנְהֹג אֶלָא שָׁעָה אַחַת, לֹא שְׁנָא שָׁמַע בַּיּוֹם \u0010r3\u0011 לֹא שְׁנָא שָׁמַע בַּלַיְלָה, שֶׁאִם שָׁמַע בַּלַיְלָה \u0010g4\u0011 וְנָהַג מִקְצָת אֲבֵלוּת בַּלַיְלָה שָׁעָה אַחַת, עוֹלֶה לוֹ; \u0010g5\u0011 \u0010r4\u0011 וַאֲפִלוּ שָׁמַע עַל אָבִיו וְאִמּוֹ. \u0010g6\u0011 וְהָנֵי מִלֵי לְעִנְיַן גְזֵרַת שִׁבְעָה, \u0010c1\u0011 אֲבָל לְעִנְיַן גְזֵרַת שְׁלֹשִׁים, נוֹהֵג עַל אָבִיו וְאִמּוֹ בְּתִסְפֹּרֶת עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו, וּבְגִהוּץ עַד שֶׁיַּגִיעַ הָרֶגֶל וְיִגְעֲרוּ בּוֹ, וְכֵן בִּשְׁאֵלַת שָׁלוֹם וְלִכָּנֵס לְבֵית הַמִּשְׁתֶּה; וּמוֹנֶה מִיּוֹם מִיתָה וְלֹא מִיּוֹם שְׁמוּעָה. \u0010y0\u0011 לְפִיכָךְ אִם בָּאָה לוֹ שְׁמוּעָה עַל אָבִיו וְאִמּוֹ לְאַחַר י\"ב חֹדֶשׁ, \u0010c2\u0011 אֵינוֹ נוֹהֵג אֶלָא יוֹם אֶחָד אַף בִּגְזֵרַת ל'. \u0010g7\u0011 \u0010r5\u0011\nהַשּׁוֹמֵעַ שְׁמוּעָה רְחוֹקָה, אֵין צָרִיךְ לִנְהֹג כָּל דִּין אֲבֵלוּת, אֶלָא דַּיּוֹ בַּחֲלִיצַת מִנְעָל, וְאֵין צָרִיךְ לֹא עֲטִיפָה וְלֹא כְּפִיַּת הַמִּטָּה, וּמֻתָּר בִּמְלָאכָה, רְחִיצָה וְסִיכָה וְתַשְׁמִישׁ הַמִּטָּה וּבְתַלְמוּד תּוֹרָה, וְאִם אֵין לוֹ מִנְעָלִים בְּרַגְלָיו צָרִיךְ שֶׁיִּכְפֶה מִטָּתוֹ אוֹ יַעֲטֹף רֹאשׁוֹ, שֶׁצָּרִיךְ שֶׁיַּעֲשֶׂה מַעֲשֶׂה שֶׁנִּכָּר בּוֹ שֶׁעוֹשֶׂה מִשּׁוּם אֲבֵלוּת; וְאִם הָיָה עוֹסֵק בַּתּוֹרָה אוֹ בִּמְלָאכָה, אוֹ שֶׁהָיָה רוֹחֵץ וְסָךְ, וּבָאָה לוֹ שְׁמוּעָה, מַפְסִיק שָׁעָה אַחַת מִשּׁוּם אֲבֵלוּת, וְחוֹזֵר לְמַה שֶּׁבְּיָדוֹ, \u0010y1\u0011 \u0010g8\u0011 אֲבָל אִם הָיָה לָבוּשׁ תְּפִלִין, אֵינוֹ צָרִיךְ \u0010t1\u0011 לְחָלְצָן, וּמִכָּל מָקוֹם אֵינוֹ יוֹצֵא יְדֵי אֲבֵלוּת בְּהֶפְסֵק זֶה, וְצָרִיךְ שֶׁיַּעֲשֶׂה מַעֲשֶׂה שֶׁנִּכָּר שֶׁעוֹשֶׂה מִשּׁוּם אֲבֵלוּת, כְּגוֹן חֲלִיצַת מִנְעָל אוֹ כְּפִיַּת הַמִּטָּה וַעֲטִיפָה; וּמִיהוּ בְּחָדָא סָגֵי. \u0010g9\u0011 \u0010r6\u0011\nאֵין מַבְרִין עַל שְׁמוּעָה רְחוֹקָה. \u0010g10\u0011 \u0010r7\u0011\nאֵין קוֹרְעִין עַל שְׁמוּעָה רְחוֹקָה; \u0010g11\u0011 וְעַל אָבִיו וְאִמּוֹ, קוֹרֵעַ לְעוֹלָם. \u0005וּבְמָקוֹם שֶׁאֵין לוֹ \u0010y2\u0011 לִקְרֹעַ, אָסוּר \u0010t2\u0011 לְהַחְמִיר עַל עַצְמוֹ \u0010y3\u0011 וְלִקְרֹעַ (אוֹר זָרוּעַ)\u0006.\nהַשּׁוֹמֵעַ שְׁמוּעָה \u0010g12\u0011 בְּשַׁבָּת אוֹ בָּרֶגֶל, וּלְמוֹצָאֵי שַׁבָּת וְרֶגֶל נַעֲשֵׂית רְחוֹקָה, אֵינוֹ נוֹהֵג \u0010c3\u0011 אֶלָא יוֹם \u0010t3\u0011 אֶחָד, \u0010g13\u0011 וּבְשַׁבָּת וְרֶגֶל אָסוּר בִּדְבָרִים שֶׁל \u0010g14\u0011 צִנְעָא.\nהַשּׁוֹמֵעַ שְׁמוּעָה רְחוֹקָה בְּשַׁבָּת אוֹ בָּרֶגֶל, אֵינוֹ נוֹהֵג אֲפִלוּ דְּבָרִים שֶׁבְּצִנְעָא, וּלְמוֹצָאֵי שַׁבָּת וְרֶגֶל נוֹהֵג שָׁעָה אַחַת, וְדַיּוֹ. \u0010g15\u0011\nהַשּׁוֹמֵעַ שְׁמוּעָה קְרוֹבָה בְּשַׁבָּת הַשַּׁבָּת \u0010t4\u0011 עוֹלָה לוֹ לְיוֹם אֶחָד, וּלְמָחָר קוֹרֵעַ, \u0010c4\u0011 וַהֲוָה לֵיהּ יוֹם שִׁשִּׁי שְׁבִיעִי \u0010g16\u0011 לַאֲבֵלוּת.\nעֲשָׂרָה יָמִים אַחַר חַג הַסֻכּוֹת שָׁמַע שֶׁמֵּת לוֹ מֵת בְּעֶרֶב הֶחָג, אַף עַל פִּי שֶׁאִם נִמְנֶה שָׁעָה אַחַת לִפְנֵי הֶחָג ז' וְשִׁבְעַת יְמֵי הֶחָג וְיוֹם שְׁמִינִי עֲצֶרֶת כ\"א, וַעֲשָׂרָה יָמִים אֲחֵרִים הֲרֵי ל\"א, \u0010c5\u0011 אֵין לָזֶה דִּין שְׁמוּעָה רְחוֹקָה, \u0010y4\u0011 אֶלָא דִּין שְׁמוּעָה \u0010t5\u0011 קְרוֹבָה, שֶׁאֵין הָרֶגֶל עוֹלֶה לְמִי שֶׁלֹּא נָהַג אֲבֵלוּת קֹדֶם לוֹ כְּלָל; וְכָל שֶׁכֵּן לְמִי שֶׁלֹּא הָיָה יוֹדֵעַ שֶׁמֵּת לוֹ מֵת \u0005(ר' יְרוּחָם בְּשֵׁם בַּעַל הַמָּאוֹר וְכ\"ד הָרַמְבַּ\"ן)\u0006. \u0010g17\u0011\nשָׁמַע שְׁתֵּי שְׁמוּעוֹת רְחוֹקוֹת בְּיוֹם אֶחָד, אֵינוֹ נוֹהֵג עֲלֵיהֶן \u0010y5\u0011 אֶלָא יוֹם אֶחָד. הָיוּ קְרוֹבוֹת, אוֹ שֶׁמֵּתוּ לוֹ שְׁנֵי מֵתִים כְּאֶחָד, מוֹנֶה לִשְׁתֵּיהֶם כְּאֶחָד שִׁבְעָה וּשְׁלֹשִׁים. \u0010y6\u0011 שָׁמַע לְזֶה הַיּוֹם וְלָזֶה \u0010t6\u0011 לְמָחָר, מוֹנֶה לַשֵּׁנִי מִיּוֹם שְׁמוּעָה, שִׁבְעָה וּשְׁלֹשִׁים. \u0010g18\u0011\nשָׁמַע שְׁמוּעָה קְרוֹבָה בְּשַׁבָּת עֶרֶב הָרֶגֶל, כֵּיוָן דִּדְבָרִים שֶׁבְּצִנְעָא נוֹהֵג, \u0010y7\u0011 עוֹלֶה לוֹ אוֹתוֹ שַׁבָּת \u0010t7\u0011 לִמִנְיַן שִׁבְעָה. \u0010y8\u0011 \u0010g19\u0011\nמִי שֶׁהִתְפַּלֵל כְּבַר עַרְבִית וַעֲדַיִן יוֹם הוּא, וְשָׁמַע שְׁמוּעָה קְרוֹבָה, \u0010c6\u0011 מוֹנֶה מִיּוֹם \u0010t8\u0011 מָחָר, וְאוֹתוֹ יוֹם אֵינוֹ עוֹלֶה לוֹ. \u0010g20\u0011\nמִי שֶׁמֵּת לוֹ מֵת וְלא נוֹדַע לוֹ, אֵינוֹ חוֹבָה שֶׁיֹאמְרוּ לוֹ; וַאֲפִלוּ בְּאָבִיו וְאִמּוֹ; וְעַל זֶה נֶאֱמַר: מוֹצִיא דִּבָּה הוּא כְּסִיל \u0010g21\u0011 \u0010r8\u0011 \u0005(מִשְׁלֵי י, יח)\u0006 וּמֻתָּר לְהַזְמִינוֹ לִסְעֻדַּת אֵרוּסִין וְנִשּׂוּאִין וְכָל שִׂמְחָה, כֵּיוָן שֶׁאֵינוֹ יוֹדֵעַ. \u0010g22\u0011 מִיהוּ אִם שׁוֹאֵל עָלָיו, \u0010c7\u0011 אֵין לוֹ \u0010t9\u0011 לְשַׁקֵר וְלוֹמַר: חַי הוּא, שֶׁנֶּאֱמַר: מִדְּבַר שֶׁקֶר תִּרְחָק \u0005(שְׁמוֹת כג, ז)\u0006. \u0005הַגָּה: וּמִכָּל מָקוֹם בְּבָנִים זְכָרִים, נָהֲגוּ לְהוֹדִיעַ, כְּדֵי שֶׁיֹּאמְרוּ קַדִּישׁ; אֲבָל בְּבָנוֹת, אֵין מִנְהָג כְּלָל לְהוֹדִיעָם\u0006 \u0005(מהרי\"ו סי' י\"ג)\u0006. \u0005מִצְוָה לְהִתְעַנּוֹת יוֹם שֶׁמֵּת בּוֹ אָבִיו אוֹ אִמּוֹ\u0006 \u0005(כָּל בּוֹ בְּשֵׁם הר\"מ וְעוֹד פּוֹסְקִים)\u0006, \u0005וּמִתְעַנִּין \u0010c8\u0011 יוֹם הַמִּיתָה וְלֹא יוֹם הַקְּבוּרָה\u0006 \u0005(מהרי\"ו סִימָן קכ\"א ומהרא\"י סִימָן רצ\"ו וְהָאַחֲרוֹנִים)\u0006, \u0010y9\u0011 \u0005אִם לֹא מִי שֶׁהָיָה \u0010t10\u0011 אֵצֶל הַקְּבוּרָה וְלֹא אֵצֶל הַמִּיתָה.\u0006 \u0005(בְּקַבָּלָה מִפִּי זָקֵן מֻפְלָג מַהֲרַ\"ם לַנְדֹּא)\u0006 ; \u0005וְאִם אֵרַע יוֹם זֶה בְּיוֹם שֶׁאֵין אוֹמְרִים בּוֹ תַּחֲנוּן, אֵין מִתְעַנִּין כְּלָל. וְאִם מֵתוּ בַּאֲדָר וְנִתְעַבְּרָה הַשָּׁנָה, \u0010y10\u0011 הָעִקָּר לְהִתְעַנּוֹת בָּאֲדָר \u0010t11\u0011 הָרִאשׁוֹן\u0006 \u0005(ת\"ה סִימָן רצ\"ד ומהר\"י מִינְ ץ)\u0006, אַף עַל פִּי שֶׁיֵּשׁ חוֹלְקִין, כָּךְ הוּא \u0010y11\u0011 עִקָּר. וְאִם מֵתוּ בִּשְׁנַת הָעִבּוּר בָּאֲדָר הַשֵּׁנִי, מִתְעַנֶּה גַּם כֵּן בְּעִבּוּר בָּאֲדָר \u0010t12\u0011 הַשֵּׁנִי \u0005(ג\"ז שָׁם)\u0006. \u0005וְעַיֵּן בְּאֹרַח חַיִּים סִימָן תקס\"ח סָעִיף ז'. וְעַיֵּן לְעֵיל סִימָן שצ\"א שֶׁאֵין לֶאֱכֹל בִּסְעֻדָּה בְּלֵיל יוֹם שֶׁמֵּת בּוֹ אָב וָאֵם. וְאִם חָל תַּעֲנִית זֶה בְּעֶרֶב שַׁבָּת, דִּינוֹ כִּשְׁאָר תַּעֲנִית. וְעַיֵּן בא\"ח סִימָן רמ\"ט. מִיהוּ אִם בְּפַעַם רִאשׁוֹן הִשְׁלִים, יִנְהֹג כֵּן כָּל יָמָיו.\u0006",{"g":["\u0003לשון הרמב\"ם ריש פ\"ז מהלכות אבל מברייתא מ\"ק דף כ' ע\"א:\u0004 ","\u0003וכן העלה הרי\"ף וכן הכריע הרמב\"ן:\u0004 ","וכתב הרא\"ש ונוהג בה דין הבראה וכל דיני אבלות כיום קבורה וכמ\"ש רבינו כללו של דבר וכו':","\u0003פלוגתא דתנאי שם דף כ' ע\"א ואיפסקא הלכתא כר\"ע:\u0004 ","\u0003ציינתיו לעיל סימן שצ\"ה סעיף ב':\u0004 ","\u0003הרמב\"ן והרא\"ש מעובדא דרב ורבי חייא שם דף כ' ע\"א וכגירסת ר\"ח ופירושו שם בתוספות:\u0004 ","\u0003טור בשם הרמב\"ן בסת\"ה מסברא:\u0004 ","\u0003שם בשם הרמב\"ן בספר ת\"ה מעובדא דרבי חייא דאתיא ליה שמועה רחוקה וכו'\u0004 ש\"מ תלת וכו' שם דף כ' ע\"ב:","שם מעובדא דרבי חייא שהיה לבוש תפילין ולא חלצן ואפילו בשעת אבילות הוא לובשן דלא תהא שמועה רחוקה חמורה מיום שני של אבילות קרובה:","\u0003נימוקי יוסף והמרדכי:\u0004 ","\u0003כרבי מני שם בגמרא:\u0004 ","\u0003שם משמיה דר' זירא וכ\"כ הרמב\"ן בשם הירושלמי מדברי הרי\"ף וכ\"כ הרא\"ש:\u0004 ","\u0003ברייתא שם:\u0004 ","שם בשם הרמב\"ן בסת\"ה ועיין במ\"ש הב\"י במה שנשאל הרשב\"א כיון דשמע בשבת שהוא יום ל' הרי היא קרובה וכו':","שם:","\u0003שם בשם סמ\"ג ושכ\"כ בה\"ג וש\"פ בשמו:\u0004 ","\u0003הרב ר\"ז הלוי בפ\"ג דמ\"ק והביאו ג\"כ הר\"ם שם:\u0004 ","\u0003הרמב\"ן בסת\"ה בשם הרי\"ץ גיאו' מעובדא דרב חייא וכו'\u0004 וציינתיו לעיל סעיף ב' דא\"ל דאביו ואמו אינן קיימי:\n(°) כלומר שעה אחת דמקצת היום ככולו:","מרדכי דמ\"ק בשם מהר\"מ (והגהמי\"י ולעיל ר\"ס שצ\"ט):","\u0003הגהמי\"י פ\"ג והמרדכי בסוף מ\"ק ונתבאר טעמו במ\"ש בס\"ס שע\"ה וע\"ש:\u0004 ","\u0003ג\"ז שם מעובדא דרבי חייא שציינתי לעיל בסעיף ב':\u0004 ","\u0003שם בהגהמי\"י פ\"ו בשם רש\"י:\u0004 ","שם במרדכי והגהמי\"י וכ\"כ התוס' בעובדא דרבי חייא שם ונלע\"ד שיש ללמוד מעובדא זו כפי גירסת ר\"ח וכמ\"ש התוס' שם שלא ישיב להדיא מת אלא ישיב לו שקרובו אחר קיים כדי שיבין מעצמו וכדי להשמיעו חדשות טובות גם כן:\n(°) בשם מהרש\"ל דוקא שחל פעם ראשון פי' בשנה ראשונה בע\"ש ולא השלים באותו פעם משא\"כ אם חל פעם ראשון בחול שכבר נקבע התענית עד צה\"כ חייב להשלים ג\"כ כשחל אחר כן בע\"ש:"],"t":["\u0003כללו. \u0004 כתב הט\"ז דמבואר בב\"י בשם הרמב\"ן דביום שמועה קרובה לא יניח תפילין כמו ביום הקבורה עכ\"ל:","\u0003לחלצן. \u0004 לפי שאף בשעת אבילות מניח תפילין ואינו חולצן אלא ביום ראשון בלבד. ולא תהא שמועה רחוקה חמורה מיום ב' של אבילות קרובה עכ\"ל הרמב\"ן. ש\"ך:","\u0003להחמיר. \u0004 משום \u0005(בל תשחית)\u0006 אם לא על אביו ואמו או אדם גדול שהיה רגיל להקשות לו בדבר הלכה דהוי מיסתפי מיניה אם בא לעשות מילתא יתירה לכבודו מותר. כ\"כ הב\"ח בסי' ש\"מ סכ\"ה בשם א\"ז. עכ\"ל הש\"ך:","\u0003אחד. \u0004 ר\"ל שעה א' אבל אם שמע שמועה בשבת שהוא כ\"ט אז נוהג לאחר השבת שבעה ושלשים. מהרש\"ל. וטעם בזה שאינו נוהג אבילות אחר השבת אע\"ג דהתחיל ביום השבת והוא ביום השלשים דכיון שאינו מתאבל אבילות גמור באותו שבת רק בדברים שבצנעא ע\"כ אין גזרת אבילות אחריו כ\"כ הב\"י בשם הרשב\"א. וכתב הרמב\"ן דבאותו שבת ורגל אסור בדבר שבצנעא כל אותו יום ולא אמרינן בזה מקצתו ככולו כיון שיש עליו חוב ליום שאחריו שעה א' היאך נאמר שיפסיק האבילות ויחזור לו עכ\"ל הט\"ז. ובש\"ך כתב דמכאן פסק הב\"ח דאם חל יום הז' של אבילות בשבת דצריך לישב על הארץ במוצאי שבת ולנהוג אבילות שעה אחת דהא הכא אע\"ג דדברים שבצנעא נוהג בשבת לא נפטר בזה וצריך לעשות במו\"ש מעשה שניכר בו משום אבילות עכ\"ד. ולפע\"ד ל\"ד כלל דהכא כיון שחכמים חייבו לנהוג אבילות כראוי עכ\"פ שעה א' וביום השבת אין נוהגין אבילות רק במקצת א\"כ מעולם לא נהג זה דין אבילות כראוי אפילו שעה א' לכן חייב למוצאי שבת או למוצאי הרגל לנהוג אבילות שעה א' אבל מי שנהג אבילות ז' ימים ובתוך הז' חל יום השבת למה יתחייב באבילות במו\"ש ואפילו זלזל במקצת הימים ולא נהג אבילות קי\"ל לעיל סי' שצ\"ו דא\"צ להשלים וכ\"ש יום השבת דנהג אבילות כדינו עכ\"ל. וגם הט\"ז השיג עליו וכתב שאין זה אלא דברי תימה ואותן האנשים שעושין כן לאו דסמכי נינהו. ואפשר שבא להם הטעות ממה שראו בס\"ו בשמועה רחוקה שבמו\"ש ורגל נוהג אבלות שעה אחת וסברי שבכל שבת של אבילות עושים כן. והוא טעות גמור דשם הוי עיקר החיוב במו\"ש משום שמועה רחוקה משא\"כ בזה עכ\"ל:","\u0003עולה. \u0004 כ' הט\"ז שבטור כתוב אחר זה והר\"ר יחיאל כ' שאין שבת עולה לו בתחלת המנין אלא יתחיל למנות ביום א' וכו' ופסק הב\"י כדעה הראשונה. ומ\"מ הבאתי דברי הר\"ר יחיאל ללמוד ממנו שאם מת באחד בשבת דה\"ל יום השבת ז' של אבלות דאין לנהוג בו איסור בדברים שבצנעא אלא במקצת היום דהיינו בשחרית בהנץ החמה. וא\"ל הא אמרינן בסי' שצ\"ה בענין מקצת היום ככולו של יום השביעי דתלוי דוקא בעמדו המנחמים מאצלו ולא סגי בהנץ החמה כמו ביום ל'. הא לאו קושיא היא כלל דבכ\"מ שאמרו מקצתו ככולו היינו שאותו מקצת צריך להיות מאותו ענין שחייב בשאר הימים כגון במנין שבעה שצריך לעשות מעשה בחליצת סנדל וכיוצא בזה ושם אמרי' דצריך באותו מקצת של יום הז' לעשות מעשה החיוב עליו ונתנו גבול שעד שעת קימת המנחמים מאצלו ראוי להיות בקום ועשה מה שמוטל עליו לנהוג אבילות בעת ההיא משא\"כ בדין ל' שאין עליו חיוב רק בשב וא\"ת דהיינו איסור גיהוץ ותספורת בזה סגי בהנץ החמה כיון דכבר נהג איסור בשב וא\"ת די בכך. ומש\"ה בשמע שמועה רחוקה שנוהנ שעה א' צריך לעשות מעשה דוקא בשעה הזאת כמו בשמועה קרובה ז' ימים. הלכך כשחל יום השביעי בשבת סגי במקצת דהא גם ביום השבת כולו לא יעשה מעשה הניכר משום אבילות רק דבר שבצנעה נוהג והוא בשב וא\"ת וסגי במקצת ממנו דהוי ממש כיום השלשים כנ\"ל ברור. ודלא כהב\"ח שרוצה לחלוק על הר\"ר יחיאל ולומר דלא אמרי' ביום השבת מקצתו ככולו ורוצה לאסור לאותו אבל שחל יום השביעי שלו בשבת שלא יקרא בתורה אפילו במנחה דליתא ואפילו בשחרית יש היתר לקרותו בתורה אלא כיון שבחול ממתין עד אחר תפלת שחרית גם בשבת יעשה כן אבל במנחה יש היתר גמור לקרותו לתורה כדעת הר\"ר יחיאל שאין עליו דין שביעי לגמרי ואין חולק עליו בזה. ויש ג\"כ להביא ראיה ממ\"ש בס\"ה בשם הרמב\"ן דבכל אותו שבת אסור בדבר שבצנעא והיינו משום שיש עליו עדיין חיוב אבילות במו\"ש. משמע הא לא\"ה אינו אסור כל השבת אלא מקצתו ככולו וכן הוא עיקר בלי ספק עכ\"ל. וגם הש\"ך חולק על הב\"ח בזה וכתב דהכי משמע לישנא דש\"ס ופוסקים דלא לישתמיט חד לפלוגי בהכי:","\u0003קרובה. \u0004 כתב הש\"ך ומתחיל למנות ז' ול' משעה ששמע וכתבו הב\"ח והדרישה בשם מהרש\"ל דלפ\"ז היכא דמת ביום א' ונקבר ביום ב' אע\"פ שהקרובים שהיו אצל הקבורה מונים מיום הקבורה כי אז היתה סתימת הגולל מ\"מ אותן שלא היו אצל הקבורה ולא נודע להן שמת עד שהגיע יום ל' מיום הקבורה א\"צ לנהוג אבילות כיון דיום שמועה דידהו הוא יום ל\"א מיום המיתה וה\"ל שמועה רחוקה דלגבי דין שמועה יום המיתה הוא עיקר עכ\"ל וכ\"כ הט\"ז:","\u0003למחר. \u0004 וכן במתו לו ב' זה אחר זה כדלעיל סי' שע\"ה ס\"י. ש\"ך:","\u0003למנין. \u0004 ושוב הרגל מבטל ממנו גזרת ז' כדלעיל ר\"ס שצ\"ט. ש\"ך:","\u0003מחר. \u0004 כתב הט\"ז ונראה דאם שמע שמועה קרובה בסוף יום שלשים אחר תפלת ערבית ועדיין יום הוא ודאי לא אמרינן דהוי לילה מכח התפלה דלהחמיר אמרינן כן לענין שלא יעלה יום שעבר למנין שבעה אבל לא להקל לומר שהוא שמועה רחוקה אלא צריך להתאבל ודומה למ\"ש בסי' רס\"ב לענין מילה דלא איכפת לן בתפלה ובזה עכ\"פ מונה מיום השמועה ולא ממחרת דלא ליהוי כתרי מילי דסתרי אהדדי עכ\"ל \u0005(ועיין לעיל סי' שע\"ה)\u0006:","\u0003לשקר. \u0004 ונראה דיש לומר בלשון דמשמע לתרי אפי דהיינו שאין מבואר בפירוש בדבריו שהוא מת אלא שהלשון סובל לחיים ולמות וראיה מר' חייא ששאל לרב אבא קיים א\"ל אמא קיימת ופי' התוספות דחיבילא' בשתממתיהאעבידו ששא\"תמה ששולאאלניאמערל באפביירוששאלשנימתעלעאכ\"מיל והמטת\"וזך: ז \u0005(ה\n\u0006","הבי\u0003א\u0004ן\u0003צ\u0004ר\u0003ל\u0004'\u0003. \u0004 והלבוש השיג ע\"ז דהא טעמא דמתענין הוא מפני הסכנה דריע מזלי' ביום זה שמת אביו או אמו וא\"כ אין חילוק ולעולם יש להתענות יום המיתה עכ\"ד. וכן משמע בתשובת מהר\"י ברין שהביא בב\"ח גם בתשובת משאת בנימין הקשה על דברי הר\"ב דאטו ב' אחים הדרים בעיר אחת והאחד היה אצל מיתת אביו והשני לא היה בעיר כשמת אביו וקודם הקבורה בא גם השני שאז האחד יעשה יא\"צ ביום המיתה והב' למחרתו ואיכא משום דלא תתגודדו וגם דמי לחוכא ואיטלולא ואנן בעינן דרכיה דרכי נועם ע\"כ. גם מדברי שאר אחרונים משמע דלעולם מתענין יום המיתה ולא יום הקבורה. ובתשובת מ\"ב שם כתב דדוקא משנה ראשונה ואילך אבל בשנה ראשונה לעולם עושין יא\"צ מיום הקבורה דאל\"כ לפעמים לא ישלים אבלות י\"ב חדש כגון אם מת בע\"ש סמוך לשבת שאין פנאי לקברו עד יום א' ואם יעשה היא\"צ ביום המיתה גם האבלות יפסוק בו ביום כי כבר נהוג עלמא שלא להתאבל רק עד היא\"צ וזה ודאי לאו שפיר דמי דהאבלות מתחלת מיום הקבורה וצריך להשלים עד אותו היום עכ\"ד ומעולם לא שמענו ולא ראינו לחלק שנות היא\"צ ולומר דבשנה ראשונה יש לעשות מיום הקבורה ואח\"כ מיום המיתה גם מדברי כל האחרונים שכתבו סתמא דיש לעשות ביום המיתה משמע גם בשנה ראשונה ולענין קושייתו נ\"ל דהא בלא\"ה נמי קשה דלפעמים משכחת לה שיהא יום הקבורה מרוחק הרבה מיום המיתה כגון שהוליכוהו למקום אחר לקברו שם דאין האבלות מתחיל אלא מיום הקבורה וכמ\"ש לעיל סי' שע\"ה והיא\"צ תתחיל מיום המיתה. ודוחק לומר דלענין אבלות די\"ב חדש אזלינן בתר יום המיתה וגם דוחק לומר דאם אירע בכה\"ג יש לעשות היא\"צ קודם י\"ב חודש. וכן משמע בת\"ה דלעולם עושים היא\"צ בתשלום האבלות. ומן הדין אפילו באותו יום היא\"צ שוב א\"צ לנהוג אבלות כי כבר נשלם זמן י\"ב חדש רק שהעולם נוהגין דכל אותו היום אין מבטלין דין אבלות די\"ב חדש. ואפשר משום דאומרים קדיש וברכו ומתענים לכן נוהגים ענין אבלות באותו יום אבל מן הדין א\"צ וגם נ\"מ למי שמתענה ואומר קדיש וברכו ביום המיתה והוא מת היום ונקבר למחר דאבלות לעולם מיום קבורה מנינן ע\"כ דברי הת\"ה. ע\"כ נראה דלעולם יש להתענות יום המיתה אלא דאם אירע דיום המיתה מרוחק מיום הקבורה ג' או ד' ימים או יותר יש להתענות בשנה ראשונה ביום הקבורה כדי שיעשה היא\"צ בתשלום האבלות כיון דא\"א בענין אחר וגם מילתא דלא שכיחא היא יש לסמוך בכה\"ג אמ\"ד לעשות ביום הקבורה ומשנה ראשונה ואילך יתענה ביום המיתה אבל מי שמת אביו ונקבר ביום שלאחריו יש להתענות ביום המיתה אף בשנה ראשונה כנ\"ל ודוק עכ\"ל הש\"ך. אבל הט\"ז פסק דלעולם לא יעשה היא\"צ רק ביום המיתה אף שהוא מרוחק הרבה מיום הקבורה ומה לנו במה שלא התאבל י\"ב חדש אם א\"א בכך ולית מאן דחש לזה עכ\"ל:","\u0003הראשון. \u0004 וכתב הש\"ך דבא\"ח ס' תקס\"ח מסיים הרב מיהו יש מחמירין להתענות בשניהם וכ\"כ מהרש\"ל שכן נוהגין והביאו הב\"ח עכ\"ל:","\u0003השני. \u0004 וה\"ה אם מתו בשנת העיבור באדר הראשון מתענים בשנת העיבור באדר הראשון וכ\"כ מהרש\"ל שם דפשוט שאם מת בראשון או בשני שכך מתענין בשנים המעוברות. עד כאן לשון הש\"ך:"],"r":["\u0003אפילו יום ל' עצמו. \u0004ממש\"ש ב' שמע שמועה קרובה בשבת ולמ\"ש כו' וע\"כ ביום למ\"ד הוא דאי ביום כ\"ט אכתי חייב לנהוג בליל מ\"ש כמש\"ל ר\"ס שצ\"ה \u0005(ודוחק לומר דמיירי בששמע בליל שבת דהלשון שמע שמועה בשבת בכל יום שבת משמע. ריטב\"א):\u0006","\u0003וקורע כו'. \u0004מדאיבעיא להו שם בנעשית למ\"ש רחוקה אם קורע ואף למ\"ד שאינו קורע דליכא אבילות כמש\"ש בשלמא לדידי כו' וכן שם כ\"ה א' הכל קורעין כו' ומיירי ביום שמועה וכמש\"ל סי' ת\"א ס\"ג:","\u0003ומונה כו' \u0004מיום השמועהו ערא\"ש שם וכן משמע לשון מונה שבעה ושלשים:","\u0003ל\"ש כו'. \u0004כמש\"ל סימן שצ\"ה ס\"ב:","\u0003ואפילו שמע על כו'. \u0004ככל הני דשם וכמש\"ש א\"ל יחידאה הוא כו' ועבה\"ג:","\u0003השומע כו'. \u0004כמ\"ש וש\"מ אבל אסור בנעילת הסנדל דמאי קמ\"ל אלא דאינו אסור אלא בנעילת הסנדל כו'. רמב\"ן והביאו הרא\"ש שם סי' ע\"ו:","\u0003אין מברין כו'. \u0004מהא דר' חייא הנ\"ל ועתוס' ך\"ד כ' ד\"ה אלא:","\u0003אין קורעין כו'. \u0004מדאיבעיא להו ך' ב' בשמע בשבת:\n\u0003(ליקוט) אין כו' וע\"ל כו'. \u0004עתוס' כ' ב' ד\"ה קורע כו' \u0005(וע\"ל סי' ש\"מ ס\"ק מ') \u0006(ע\"כ):","\u0003(ליקוט) ומותר כו'. \u0004עהג\"א סי' קכ\"א (ע\"כ):"]}],["הַמְלַקֵט עַצְמוֹת אָבִיו, אוֹ שֶׁל שְׁאָר קְרוֹבִים שֶׁמִּתְאַבְּלִים עֲלֵיהֶם, מִתְאַבֵּל עֲלֵיהֶם כָּל הַיּוֹם כֻּלוֹ, בְּכָל הַדְּבָרִים הַנּוֹהֲגִים בְּאָבֵל, בִּכְפִיַּת הַמִּטָּה וַעֲטִיפַת הָרֹאשׁ וּנְעִילַת הַסַנְדָּל וְתַשְׁמִישׁ הַמִּטָּה וּרְחִיצָה וְסִיכָה; וְלָעֶרֶב אֵין מִתְאַבֵּל עֲלֵיהֶם, אֲפִלוּ צְרוּרִים לוֹ בִּסְדִינוֹ. הָיָה עוֹמֵד וּמְלַקֵט, וְחָשְׁכָה לוֹ, מֻתָּר בַּיּוֹם שֶׁלְאַחֲרָיו. לְפִיכָךְ אֵין מְלַקְטִין אוֹתָם סָמוּךְ לַחֲשֵׁכָה, כְּדֵי שֶׁלֹּא יִהְיֶה נִמְצָא שֶׁלֹּא הִתְאַבֵּל עַל לִקוּט עַצְמוֹת אָבִיו. \u0010y0\u0011 \u0005וְאֵין אֲנִינוּת בְּלִקּוּט עֲצָמוֹת, רַק חָל עָלָיו אֲבֵלוּת מִיָּד (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nכָּל שֶׁקוֹרֵעַ עָלָיו בִּשְׁעַת מִיתָתוֹ, קוֹרֵעַ עָלָיו בִּשְׁעַת לִקוּט עֲצָמוֹת. וְכָל שֶׁאֵינוֹ מִתְאַחֶה בִּשְׁעַת מִיתָתוֹ, אֵינוֹ מִתְאַחֶה בִּשְׁעַת לִקוּט עֲצָמוֹת.\nעֲצָמוֹת, אֵין עוֹמְדִין עֲלֵיהֶם בְּשׁוּרָה, אֲבָל אוֹמְרִים עֲלֵיהֶם תַּנְחוּמִין לְעַצְמָם. וְאֵין מַבְרִין עֲלֵיהֶם בְּחֶבֶר עִיר, אֲבָל מַבְרִין עֲלֵיהֶם בְּבֵיתוֹ. וְאֵין אוֹמְרִים עֲלֵיהֶם קִינָה וּנְהִי, אֲבָל אוֹמְרִים עֲלֵיהֶם קִלוּסִין. \u0005דְּהַיְנוּ שִׁבְחוֹ שֶׁל מֵת, וּמְשַׁבְּחִין לְהקב\"ה שֶׁמֵּמִית וּמְחַיֶּה (בַּטּוּר תִּמְצָא מְבֹאָר)\u0006.\nאֵין מְלַקְטִין עַצְמוֹת אָבִיו בַּמּוֹעֵד, וְאֵין צָרִיךְ לוֹמַר עַצְמוֹת שְׁאָר קְרוֹבִים.\nשָׁמַע שֶׁהַיּוֹם לִקְטוּ עַצְמוֹת אֶחָד מִקְרוֹבָיו שֶׁהוּא מִתְאַבֵּל עֲלֵיהֶם, אַף עַל פִּי שֶׁלֹּא הָיָה שָׁם, מִתְאַבֵּל עֲלֵיהֶם. \u0005אֲבָל שָׁמַע שֶׁנִּלְקְטוּ אֶתְמוֹל, אֵין מִתְאַבֵּל עֲלֵיהֶם (טוּר בְּשֵׁם הַיְּרוּשַׁלְמִי)\u0006.\nאֵין מְפָרְקִין אֶת הָעֲצָמוֹת וְלֹא מַפְסִיקִין אֶת הַגִידִים.\nלִקוּט עֲצָמוֹת \u0010y1\u0011 אֵינוֹ אֶלָא מִשֶּׁיִּכְלֶה הַבָּשָׂר; כָּלָה הַבָּשָׂר, אֵין הַצּוּרָה נִכֶּרֶת בָּעֲצָמוֹת, לְפִיכָךְ יָכוֹל לְלַקֵט בְּיָדוֹ עַצְמוֹת אָבִיו וְאִמּוֹ; וְאַף עַל פִּי כֵן נָכוֹן הַדָּבָר שֶׁלֹּא יִלְקְטֵם הוּא עַצְמוֹ, מֵהַהִיא דְּרַבִּי אֱלִיעֶזֶר בַּר צָדוֹק דִּבְסָמוּךְ.\nמְלַקֵט אָדָם עַצְמוֹת שְׁנֵי מֵתִים כְּאֶחָד בְּרֹאשׁ אֲפַרְסְקָל מִכָּאן, וּבְרֹאשׁ אֲפַרְסְקָל מִכָּאן, דִּבְרֵי רַבִּי יוֹחָנָן בֶּן נוּרִי. ר\"א אוֹמֵר: סוֹף אֲפַרְסְקָל לְהִתְעַכֵּל, וְסוֹף עֲצָמוֹת לְהִתְעַכֵּל, וְנִמְצְאוּ עַצְמוֹת שְׁנֵי מֵתִים מִתְעָרְבִים, אֶלָא מְלַקְטִין וְנוֹתְנִין כָּל אֶחָד לְעַצְמוֹ בְּאָרוֹן שֶׁל אֲרָזִים. אָמַר רַבִּי אֱלִיעֶזֶר בַּר צָדוֹק: כָּךְ אָמַר לִי אַבָּא בִּשְׁעַת מִיתָתוֹ: מִתְּחִלָה קִבְרוּנִי בְּבִקְעָה, וּלְבַסוֹף לְקֹט עַצְמוֹתַי וּתְנֵם בָּאֲרָזִים, וְאַל תִּלְקְטֵם אַתָּה בְּיָדְךָ, שֶׁלֹּא יִהְיוּ בְּזוּיוֹת עָלֶיךָ.\nהַמְלַקֵט עֲצָמוֹת, וְהַמְשַׁמֵּר אֶת הַמֵּת, וְהַמּוֹלִיךְ אוֹתָם מִמָּקוֹם לְמָקוֹם, פָּטוּר מִקְרִיאַת שְׁמַע וּמִתְּפִלָה וּמֵהַתְּפִלִין, וּמִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה, בֵּין בְּחֹל בֵּין בְּשַׁבָּת, לֹא שְׁנָא עַצְמוֹת קְרוֹבִים לֹא שְׁנָא עַצְמוֹת רְחוֹקִים, בֵּין אִם הוּא בִּסְפִינָה אוֹ בַּדֶּרֶךְ, \u0010y2\u0011 וַאֲפִלוּ אִם הֵם מְלַקְטִים רַבִּים. וְאִם רָצָה לְהַחְמִיר עַל עַצְמוֹ, לֹא יַחְמִיר, מִפְּנֵי כְּבוֹד עֲצָמוֹת.\nהַמּוֹלִיךְ עֲצָמוֹת מִמָּקוֹם לְמָקוֹם, הֲרֵי זֶה לֹא יִתְּנֵם בְּשַׂק אוֹ בְּדִסְקִיָּא וְיַנִּיחֵם עַל הַחֲמוֹר וְיִרְכַּב עֲלֵיהֶם, \u0010y3\u0011 מִפְּנֵי שֶׁנּוֹהֵג בָּהֶם מִנְהַג בִּזָּיוֹן; אֲבָל אִם מַפְשִׁילוֹ לַאֲחוֹרָיו עַל הַחֲמוֹר, שַׁפִּיר דָּמֵי. וְאִם הָיָה מִתְיָרֵא מִפְּנֵי הַגַנָּבִים וְהַלִסְטִים, מֻתָּר. \u0005הַגָּה: וְהַחַי יִתֵּן אֶל לִבּוֹ דְּבָרִים שֶׁל מִיתָה; דְּיִסְפַּד, יִסְפְּדוּנֵהּ; דְּיִקְבַּר, יִקְבְּרוּנֵהּ; דְּיִטְעֹן, יַטְעִינֵהּ; דְּיִדַּל, יַדְלוּנֵהּ; וְגָדוֹל הַשָּׁלוֹם שֶׁנִּתַּן לַצַּדִּיקִים, שֶׁבְּשָׁעָה שֶׁהַצַּדִּיק נִפְטָר ג' כִּתּוֹת שֶׁל מַלְאָכִים נוֹתְנִים לוֹ שָׁלוֹם. (הַכֹּל בַּטּוּר וְהָרֹא\"שׁ וְכָל בּוֹ)\u0006 \u0005(וְאוֹמְרִים יָבֹא שָׁלוֹם כָּל הַכָּתוּב לַחַיִּים קָדוֹשׁ יֵאָמֶר לוֹ)\u0006. בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים. \u0005(יְשַׁעְיָה כה, ח')\u0006.",["\u0003ואין אנינות כו'. \u0004כלומר שיאסר קודם שיקברו העצמות באכילת בשר ושתיית יין כדין אונן לעיל סימן שמ\"א אלא מיד חל עליו האבלות אף קודם שקברם וע\"ל סימן שע\"ה ס\"ז. כהן אינו רשאי ללקוט עצמות אביו דשמא נחסר אביו סא\"ז מ\"ו פירוש אם נחסר כל שהוא מאביו אסור ליטמא לו כדלעיל סוף סי' שע\"ג עכ\"ל דרישה:","\u0003אינו אלא משיכלה הבשר. \u0004כלומר לענין זה שילקטם הוא בעצמו וכדמפרש ואזיל אבל אה\"נ דאף כשלא כלה הבשר חייב להתאבל כל היום כדלעיל סימן שע\"ה סעיף ז' ודוק:","\u0003ואפי' הם מלקטים רבים. \u0004דוקא מלקטים רבים אבל משמרים רבים זה משמר וזה קורא וכמ\"ש בא\"ח סימן ע\"א ס\"ד:","\u0003מפני שנוהג בהם כו'. \u0004עיין לעיל סימן רפ\"ב סעיף ג':"],[],"\u0010g0\u0011 \u0010r0\u0011 הַמְלַקֵט עַצְמוֹת אָבִיו, \u0010g1\u0011 אוֹ שֶׁל שְׁאָר קְרוֹבִים שֶׁמִּתְאַבְּלִים עֲלֵיהֶם, מִתְאַבֵּל עֲלֵיהֶם כָּל הַיּוֹם \u0010g2\u0011 כֻּלוֹ, בְּכָל הַדְּבָרִים הַנּוֹהֲגִים בְּאָבֵל, בִּכְפִיַּת הַמִּטָּה וַעֲטִיפַת הָרֹאשׁ וּנְעִילַת הַסַנְדָּל וְתַשְׁמִישׁ הַמִּטָּה וּרְחִיצָה וְסִיכָה; וְלָעֶרֶב אֵין מִתְאַבֵּל עֲלֵיהֶם, \u0010g3\u0011 אֲפִלוּ צְרוּרִים לוֹ בִּסְדִינוֹ. \u0010g4\u0011 הָיָה עוֹמֵד וּמְלַקֵט, וְחָשְׁכָה לוֹ, מֻתָּר בַּיּוֹם שֶׁלְאַחֲרָיו. לְפִיכָךְ אֵין מְלַקְטִין אוֹתָם סָמוּךְ לַחֲשֵׁכָה, כְּדֵי שֶׁלֹּא יִהְיֶה נִמְצָא שֶׁלֹּא הִתְאַבֵּל עַל לִקוּט עַצְמוֹת אָבִיו. \u0010y0\u0011 \u0005וְאֵין \u0010t0\u0011 אֲנִינוּת בְּלִקּוּט עֲצָמוֹת, רַק חָל עָלָיו אֲבֵלוּת מִיָּד (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. \u0010g5\u0011 \u0010r1\u0011\nכָּל שֶׁקוֹרֵעַ עָלָיו בִּשְׁעַת מִיתָתוֹ, קוֹרֵעַ עָלָיו בִּשְׁעַת לִקוּט עֲצָמוֹת. וְכָל שֶׁאֵינוֹ מִתְאַחֶה בִּשְׁעַת מִיתָתוֹ, אֵינוֹ מִתְאַחֶה בִּשְׁעַת לִקוּט עֲצָמוֹת. \u0010g6\u0011\nעֲצָמוֹת, אֵין עוֹמְדִין עֲלֵיהֶם בְּשׁוּרָה, אֲבָל אוֹמְרִים עֲלֵיהֶם תַּנְחוּמִין לְעַצְמָם. וְאֵין מַבְרִין עֲלֵיהֶם בְּחֶבֶר עִיר, אֲבָל מַבְרִין עֲלֵיהֶם בְּבֵיתוֹ. \u0010g7\u0011 וְאֵין אוֹמְרִים עֲלֵיהֶם קִינָה וּנְהִי, אֲבָל אוֹמְרִים עֲלֵיהֶם קִלוּסִין. \u0005דְּהַיְנוּ שִׁבְחוֹ שֶׁל מֵת, וּמְשַׁבְּחִין לְהקב\"ה שֶׁמֵּמִית וּמְחַיֶּה (בַּטּוּר תִּמְצָא \u0010g8\u0011 מְבֹאָר)\u0006.\nאֵין מְלַקְטִין עַצְמוֹת אָבִיו בַּמּוֹעֵד, וְאֵין צָרִיךְ לוֹמַר עַצְמוֹת שְׁאָר קְרוֹבִים. \u0010g9\u0011\nשָׁמַע שֶׁהַיּוֹם לִקְטוּ עַצְמוֹת אֶחָד מִקְרוֹבָיו שֶׁהוּא מִתְאַבֵּל עֲלֵיהֶם, אַף עַל פִּי שֶׁלֹּא הָיָה שָׁם, מִתְאַבֵּל עֲלֵיהֶם. \u0005אֲבָל שָׁמַע שֶׁנִּלְקְטוּ אֶתְמוֹל, אֵין מִתְאַבֵּל עֲלֵיהֶם (טוּר בְּשֵׁם הַיְּרוּשַׁלְמִי)\u0006. \u0010g10\u0011\nאֵין מְפָרְקִין אֶת הָעֲצָמוֹת וְלֹא מַפְסִיקִין אֶת הַגִידִים. \u0010g11\u0011\nלִקוּט עֲצָמוֹת \u0010y1\u0011 אֵינוֹ אֶלָא \u0010t1\u0011 מִשֶּׁיִּכְלֶה הַבָּשָׂר; כָּלָה הַבָּשָׂר, אֵין הַצּוּרָה נִכֶּרֶת בָּעֲצָמוֹת, לְפִיכָךְ יָכוֹל לְלַקֵט בְּיָדוֹ עַצְמוֹת אָבִיו וְאִמּוֹ; וְאַף עַל פִּי כֵן נָכוֹן הַדָּבָר שֶׁלֹּא יִלְקְטֵם הוּא עַצְמוֹ, מֵהַהִיא דְּרַבִּי אֱלִיעֶזֶר בַּר צָדוֹק דִּבְסָמוּךְ. \u0010g12\u0011\nמְלַקֵט אָדָם עַצְמוֹת שְׁנֵי מֵתִים כְּאֶחָד בְּרֹאשׁ אֲפַרְסְקָל מִכָּאן, וּבְרֹאשׁ אֲפַרְסְקָל מִכָּאן, דִּבְרֵי רַבִּי יוֹחָנָן בֶּן נוּרִי. ר\"א אוֹמֵר: סוֹף אֲפַרְסְקָל לְהִתְעַכֵּל, וְסוֹף עֲצָמוֹת לְהִתְעַכֵּל, וְנִמְצְאוּ עַצְמוֹת שְׁנֵי מֵתִים מִתְעָרְבִים, אֶלָא מְלַקְטִין וְנוֹתְנִין כָּל אֶחָד לְעַצְמוֹ בְּאָרוֹן שֶׁל אֲרָזִים. אָמַר רַבִּי אֱלִיעֶזֶר בַּר צָדוֹק: כָּךְ אָמַר לִי אַבָּא בִּשְׁעַת מִיתָתוֹ: מִתְּחִלָה קִבְרוּנִי בְּבִקְעָה, וּלְבַסוֹף לְקֹט עַצְמוֹתַי וּתְנֵם בָּאֲרָזִים, וְאַל תִּלְקְטֵם אַתָּה בְּיָדְךָ, שֶׁלֹּא יִהְיוּ בְּזוּיוֹת עָלֶיךָ. \u0010g13\u0011 \u0010r2\u0011\nהַמְלַקֵט עֲצָמוֹת, וְהַמְשַׁמֵּר אֶת הַמֵּת, וְהַמּוֹלִיךְ אוֹתָם מִמָּקוֹם לְמָקוֹם, פָּטוּר מִקְרִיאַת שְׁמַע וּמִתְּפִלָה וּמֵהַתְּפִלִין, וּמִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה, \u0010r3\u0011 בֵּין בְּחֹל בֵּין בְּשַׁבָּת, לֹא שְׁנָא עַצְמוֹת קְרוֹבִים לֹא שְׁנָא עַצְמוֹת רְחוֹקִים, בֵּין אִם הוּא בִּסְפִינָה אוֹ בַּדֶּרֶךְ, \u0010y2\u0011 וַאֲפִלוּ אִם הֵם מְלַקְטִים \u0010t2\u0011 רַבִּים. וְאִם רָצָה לְהַחְמִיר עַל עַצְמוֹ, לֹא יַחְמִיר, מִפְּנֵי כְּבוֹד עֲצָמוֹת. \u0010g14\u0011\nהַמּוֹלִיךְ עֲצָמוֹת מִמָּקוֹם לְמָקוֹם, הֲרֵי זֶה לֹא יִתְּנֵם בְּשַׂק אוֹ בְּדִסְקִיָּא וְיַנִּיחֵם עַל הַחֲמוֹר וְיִרְכַּב עֲלֵיהֶם, \u0010y3\u0011 מִפְּנֵי \u0010t3\u0011 שֶׁנּוֹהֵג בָּהֶם מִנְהַג בִּזָּיוֹן; \u0010g15\u0011 אֲבָל אִם מַפְשִׁילוֹ לַאֲחוֹרָיו עַל הַחֲמוֹר, שַׁפִּיר דָּמֵי. וְאִם הָיָה מִתְיָרֵא מִפְּנֵי הַגַנָּבִים וְהַלִסְטִים, מֻתָּר. \u0005הַגָּה: \u0010g16\u0011 וְהַחַי יִתֵּן אֶל לִבּוֹ דְּבָרִים שֶׁל מִיתָה; דְּיִסְפַּד, יִסְפְּדוּנֵהּ; דְּיִקְבַּר, יִקְבְּרוּנֵהּ; דְּיִטְעֹן, יַטְעִינֵהּ; דְּיִדַּל, יַדְלוּנֵהּ; וְגָדוֹל הַשָּׁלוֹם שֶׁנִּתַּן לַצַּדִּיקִים, \u0010g17\u0011 שֶׁבְּשָׁעָה שֶׁהַצַּדִּיק נִפְטָר ג' כִּתּוֹת שֶׁל מַלְאָכִים נוֹתְנִים לוֹ שָׁלוֹם. (הַכֹּל בַּטּוּר וְהָרֹא\"שׁ וְכָל בּוֹ)\u0006 \u0005(וְאוֹמְרִים יָבֹא שָׁלוֹם כָּל הַכָּתוּב לַחַיִּים קָדוֹשׁ יֵאָמֶר לוֹ)\u0006. בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים. \u0005(יְשַׁעְיָה כה, ח')\u0006.",{"g":["\u0003ברייתא מ\"ק דף ח' ע\"א:\u0004 ","\u0003הרמב\"ן בסת\"ה וכ\"כ הרא\"ש בפ\"ק דמ\"ק מברייתא דאבל רבתי:\u0004 ","\u0003שם וכ\"כ ר' ירוחם:\u0004 ","\u0003כפי' התוס' שם:\u0004 ","\u0003ברייתא באבל רבתי פי\"ב וכתבוהו הרמב\"ן שם והרא\"ש שם:\u0004 ","\u0003ברייתא באבל רבתי וכתבוהו הרמב\"ן שם והרא\"ש שם:\u0004 ","\u0003ברייתא שם וכתבוהו שם:\u0004 ","\u0003ברייתא ירושלמי וכתבוהו הרי\"ף בסוף פ\"ק והרמב\"ן בסת\"ה והרא\"ש בפרק דמ\"ק והרמב\"ם פי\"ב:\u0004 ","לשון הרמב\"ם בפי\"א ממשנה מ\"ק דף ח' ע\"א וכרבי יוסי כפי הכלל שבידינו ר\"מ ורבי יוסי הלכה כרבי יוסי:","\u0003ירושלמי וכרבי חגי:\u0004 ","\u0003ברייתא באבל רבתי וכתבוהו הרמב\"ן בסת\"ה והרא\"ש בפ\"ק דמ\"ק:\u0004 ","שם:","\u0003שם בברייתא וכרבי יוחנן בן נורי דמסתבר טעמיה:\u0004 ","\u0003ברייתא שם:\u0004 ","\u0003ברייתא ברכות דף י\"ח ע\"א:\u0004 ","\u0003הרא\"ש שם:\u0004 ","\u0003ברייתא משמיה דרבי מאיר מ\"ק דף כ\"ח ע\"ב ובכמה דוכתי:\u0004 ","כתובות דף ק\"ד ע\"א ונלע\"ד דהטעם בג' כתות מלאכים אלו משום דהתורה ומעשה הצדיקים בג' דברים במחשבתם הטובה ודיבור ומעשה וכמ\"ש הרמב\"ן בפירוש החומש בפרשת וירא ופרי מעשיהם כגמול ידיהם ישלם להם. יהי רצון שנזכה ג\"כ שזה יהיה חלקנו וכבוד ה' יאספנו ברוך ה' לעולם אמן ואמן:"],"t":["\u0003אנינות. \u0004 כלומר שיאסר קודם שיקברו העצמות באכילת בשר ושתיית יין כדין אונן לעיל סי' שמ\"א אלא מיד חל עליו האבלות אף קודם שיקברם ע\"ל סי' שע\"ה ס\"ז. כהן אינו רשאי ללקט עצמות אביו דשמא נחסר אביו סא\"ז פי' אם נחסר כל שהוא מאביו אסור ליטמא לו כדלעיל ס\"ס שע\"ג דרישה עכ\"ל הש\"ך:","\u0003משיכלה. \u0004 כלומר לענין זה שילקטם הוא בעצמו כדמפרש ואזיל אבל אה\"נ דאף כשלא כלה הבשר חייב להתאבל כל היום כדלעיל סי' שע\"ה ס\"ז. ש\"ך:","\u0003רבים. \u0004 כתב הש\"ך ודוקא מלקטים רבים אבל משמרים רבים זה משמר וזה קורא וכמ\"ש בא\"ח סי' ע\"א ס\"ד \u0005(ודין מקום הקבר שנלקטו ממנו העצמות אם מותר לקבור בו מתים אחרים ע\"ל סי' שס\"ג ושס\"ד. וע' בתשו' ש\"י שאלה פ\"ז)\u0006:","\u0003שנוהג. \u0004 ע\"ל סי' רפ\"ב ס\"ג. והרחמן יגדור פרצת עמו ישראל וינחם אותם בבנין ירושלים במהרה בימינו אמן כן יהי רצון:"],"r":["\u0003(ליקוט) המלקט כו' \u0004עד סוף הסימן ערא\"ש פ\"א סי' יו\"ד י\"א י\"ב ופ\"ג סי' ק\"ג (ע\"כ):","\u0003(ליקוט) כל שקורע כו'. \u0004עד ס\"ט הכל בא\"ר פי\"ב:","\u0003המלקט כו' \u0004שם רפי\"ג וכת\"ק (ע\"כ):","\u0003בין כו'. \u0004הכל דלא כתנאים דשם דכולהו יחידאי נינהו והלכה כת\"ק לבד. הרמב\"ן והרא\"ש ומ\"ש ואפילו הם כו' היינו דלא כר' נתן וצ\"ל דגריס להיפך אם יש חבילה עמהם חייב אבל גירסת הרא\"ש פטור וכ\"ה בתה\"א אבל גורס קבלה עמהם ועיין תפארת שמואל וצ\"ע (ע\"כ):"]}]]};
